CREATE OR REPLACE FUNCTION "public"."ack_my_onboarding_seen"("p_surface" "text", "p_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_employee_id uuid;
  v_version integer;
BEGIN
  IF p_surface IS NULL OR p_surface NOT IN ('tech') THEN
    RAISE EXCEPTION 'unknown onboarding surface'
      USING errcode = '22023';
  END IF;
  IF p_version IS NULL OR p_version < 1 OR p_version > 10000 THEN
    RAISE EXCEPTION 'onboarding version out of range'
      USING errcode = '22023';
  END IF;

  SELECT employee.id
  INTO v_employee_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IN (
      'admin',
      'office',
      'project_manager',
      'field_tech',
      'estimator',
      'supervisor'
    )
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  INSERT INTO public.employee_onboarding_state (
    employee_id,
    surface,
    version_seen
  )
  VALUES (v_employee_id, p_surface, p_version)
  ON CONFLICT (employee_id, surface)
  DO UPDATE SET
    version_seen = GREATEST(
      public.employee_onboarding_state.version_seen,
      EXCLUDED.version_seen
    ),
    updated_at = now()
  RETURNING version_seen INTO v_version;

  RETURN v_version;
END;
$$;


ALTER FUNCTION "public"."ack_my_onboarding_seen"("p_surface" "text", "p_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_adhoc_job_task"("p_job_id" "uuid", "p_title" "text", "p_phase_name" "text", "p_phase_color" "text" DEFAULT '#6b7280'::"text", "p_appointment_id" "uuid" DEFAULT NULL::"uuid", "p_target_date" "date" DEFAULT NULL::"date", "p_job_schedule_phase_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_id UUID;
  v_jsp_id UUID;
BEGIN
  -- Auto-lookup job_schedule_phase_id if not provided
  v_jsp_id := p_job_schedule_phase_id;
  IF v_jsp_id IS NULL THEN
    SELECT jsp.id INTO v_jsp_id
    FROM job_schedule_phases jsp
    JOIN job_schedules js ON js.id = jsp.job_schedule_id
    WHERE js.job_id = p_job_id AND jsp.phase_name = p_phase_name
    LIMIT 1;
  END IF;

  INSERT INTO job_tasks (job_id, title, phase_name, phase_color, appointment_id, target_date, job_schedule_phase_id)
  VALUES (p_job_id, p_title, p_phase_name, p_phase_color, p_appointment_id, p_target_date, v_jsp_id)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."add_adhoc_job_task"("p_job_id" "uuid", "p_title" "text", "p_phase_name" "text", "p_phase_color" "text", "p_appointment_id" "uuid", "p_target_date" "date", "p_job_schedule_phase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_custom_schedule_phase"("p_job_id" "uuid", "p_phase_name" "text", "p_phase_color" "text" DEFAULT '#6b7280'::"text", "p_target_start" "date" DEFAULT NULL::"date", "p_target_end" "date" DEFAULT NULL::"date", "p_duration_days" integer DEFAULT 1, "p_sort_order" integer DEFAULT 999) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_schedule_id UUID;
  v_phase_id UUID;
BEGIN
  SELECT id INTO v_schedule_id FROM job_schedules WHERE job_id = p_job_id LIMIT 1;
  IF v_schedule_id IS NULL THEN
    RAISE EXCEPTION 'Job has no schedule';
  END IF;

  INSERT INTO job_schedule_phases (
    job_schedule_id, phase_name, phase_color, target_start, target_end, duration_days, sort_order
  ) VALUES (
    v_schedule_id, p_phase_name, p_phase_color,
    COALESCE(p_target_start, public.mt_today()),
    COALESCE(p_target_end, public.mt_today() + p_duration_days - 1),
    p_duration_days, p_sort_order
  ) RETURNING id INTO v_phase_id;

  RETURN v_phase_id;
END;
$$;


ALTER FUNCTION "public"."add_custom_schedule_phase"("p_job_id" "uuid", "p_phase_name" "text", "p_phase_color" "text", "p_target_start" "date", "p_target_end" "date", "p_duration_days" integer, "p_sort_order" integer) OWNER TO "postgres";

