CREATE OR REPLACE FUNCTION "public"."add_homebuilding_chat_message"("p_chat_id" "uuid", "p_role" "text", "p_content" "text") RETURNS "public"."homebuilding_chat_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r public.homebuilding_chat_messages;
begin
  insert into public.homebuilding_chat_messages(chat_id, role, content)
  values (p_chat_id, p_role, left(p_content, 20000)) returning * into r;
  update public.homebuilding_chats set updated_at = now() where id = p_chat_id;
  return r;
end; $$;


ALTER FUNCTION "public"."add_homebuilding_chat_message"("p_chat_id" "uuid", "p_role" "text", "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_lead_note"("p_lead_id" "uuid", "p_body" "text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id     uuid;
  v_contact_id uuid;
  v_actor      uuid;
  v_row        crm_lead_notes;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.crm_lead_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  IF p_body IS NULL OR btrim(p_body) = '' THEN
    RAISE EXCEPTION 'note body is required';
  END IF;

  v_actor := COALESCE(
    p_created_by,
    (SELECT e.id FROM employees e WHERE e.auth_user_id = (SELECT auth.uid()) LIMIT 1)
  );

  SELECT org_id, contact_id INTO v_org_id, v_contact_id
  FROM inbound_leads WHERE id = p_lead_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO crm_lead_notes (lead_id, org_id, contact_id, body, created_by)
  VALUES (p_lead_id, v_org_id, v_contact_id, btrim(p_body), v_actor)
  RETURNING * INTO v_row;

  RETURN json_build_object(
    'id', v_row.id,
    'lead_id', v_row.lead_id,
    'body', v_row.body,
    'created_at', v_row.created_at,
    'created_by', v_row.created_by,
    'author_name', (SELECT COALESCE(e.display_name, e.full_name) FROM employees e WHERE e.id = v_row.created_by)
  );
END;
$$;


ALTER FUNCTION "public"."add_lead_note"("p_lead_id" "uuid", "p_body" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_related_job"("p_source_job_id" "uuid", "p_division" "text" DEFAULT 'reconstruction'::"text", "p_priority" integer DEFAULT 3, "p_type_of_loss" "text" DEFAULT NULL::"text", "p_internal_notes" "text" DEFAULT NULL::"text", "p_project_manager_id" "uuid" DEFAULT NULL::"uuid", "p_lead_tech_id" "uuid" DEFAULT NULL::"uuid", "p_invoiced_value" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_source jobs;
  v_claim  claims;
  v_job_id uuid;
  v_job    jsonb;
BEGIN
  SELECT * INTO v_source FROM jobs WHERE id = p_source_job_id;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'Source job not found';
  END IF;
  IF v_source.claim_id IS NULL THEN
    RAISE EXCEPTION 'Source job has no claim — cannot add related job';
  END IF;
  SELECT * INTO v_claim FROM claims WHERE id = v_source.claim_id;

  INSERT INTO jobs (
    division, source, phase, priority, status,
    insured_name, client_phone, client_email,
    address, city, state, zip,
    type_of_loss, date_of_loss,
    insurance_company, claim_number, policy_number,
    adjuster_name, adjuster_phone, adjuster_email, cat_code,
    project_manager_id, lead_tech_id, internal_notes,
    primary_contact_id, claim_id,
    invoiced_value, ar_status,
    created_at, updated_at
  ) VALUES (
    p_division::job_division,
    v_source.source,
    'job_received',
    p_priority,
    'active',
    v_source.insured_name,
    v_source.client_phone,
    v_source.client_email,
    COALESCE(v_claim.loss_address, v_source.address),
    COALESCE(v_claim.loss_city,    v_source.city),
    COALESCE(v_claim.loss_state,   v_source.state),
    COALESCE(v_claim.loss_zip,     v_source.zip),
    COALESCE(NULLIF(p_type_of_loss, ''), v_source.type_of_loss),
    v_source.date_of_loss,
    COALESCE(v_claim.insurance_carrier, v_source.insurance_company),
    COALESCE(v_claim.insurance_claim_number, v_source.claim_number),
    v_claim.policy_number,
    v_source.adjuster_name,
    v_source.adjuster_phone,
    v_source.adjuster_email,
    v_source.cat_code,
    COALESCE(p_project_manager_id, v_source.project_manager_id),
    p_lead_tech_id,
    NULLIF(p_internal_notes, ''),
    v_source.primary_contact_id,
    v_source.claim_id,
    COALESCE(p_invoiced_value, 0),
    CASE WHEN p_invoiced_value > 0 THEN 'invoiced' ELSE 'open' END,
    now(), now()
  )
  RETURNING id INTO v_job_id;

  IF v_source.primary_contact_id IS NOT NULL THEN
    INSERT INTO contact_jobs (contact_id, job_id, role, is_primary)
    VALUES (v_source.primary_contact_id, v_job_id, 'primary_client', true)
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT to_jsonb(j) INTO v_job FROM (SELECT * FROM jobs WHERE id = v_job_id) j;

  RETURN jsonb_build_object(
    'job',          v_job,
    'claim_id',     v_source.claim_id,
    'claim_number', v_claim.claim_number
  );
END;
$$;


ALTER FUNCTION "public"."add_related_job"("p_source_job_id" "uuid", "p_division" "text", "p_priority" integer, "p_type_of_loss" "text", "p_internal_notes" "text", "p_project_manager_id" "uuid", "p_lead_tech_id" "uuid", "p_invoiced_value" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."job_time_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "work_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "hours" numeric NOT NULL,
    "hourly_rate" numeric,
    "total_cost" numeric GENERATED ALWAYS AS ("round"((((COALESCE("travel_minutes", (0)::numeric) / 60.0) + COALESCE("hours", (0)::numeric)) * COALESCE("hourly_rate", (0)::numeric)), 2)) STORED,
    "work_type" "text" DEFAULT 'field'::"text",
    "description" "text",
    "clock_in" timestamp with time zone,
    "clock_out" timestamp with time zone,
    "entered_by" "uuid",
    "approved" boolean DEFAULT false,
    "approved_by" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "travel_start" timestamp with time zone,
    "on_site_end" timestamp with time zone,
    "paused_at" timestamp with time zone,
    "total_paused_minutes" numeric DEFAULT 0,
    "appointment_id" "uuid",
    "travel_minutes" numeric,
    "travel_start_lat" numeric(9,6),
    "travel_start_lng" numeric(9,6),
    "clock_in_lat" numeric(9,6),
    "clock_in_lng" numeric(9,6),
    "auto_continued" boolean DEFAULT false NOT NULL,
    "continued_from" "uuid",
    "auto_split_seq" integer DEFAULT 0 NOT NULL,
    "source" "text",
    CONSTRAINT "job_time_entries_hours_check" CHECK ((("hours" >= (0)::numeric) AND ("hours" <= (24)::numeric))),
    CONSTRAINT "job_time_entries_hours_nonneg" CHECK ((("hours" IS NULL) OR ("hours" >= (0)::numeric))),
    CONSTRAINT "job_time_entries_paused_nonneg" CHECK ((("total_paused_minutes" IS NULL) OR ("total_paused_minutes" >= (0)::numeric))),
    CONSTRAINT "job_time_entries_travel_nonneg" CHECK ((("travel_minutes" IS NULL) OR ("travel_minutes" >= (0)::numeric))),
    CONSTRAINT "job_time_entries_work_type_check" CHECK (("work_type" = ANY (ARRAY['field'::"text", 'office'::"text", 'travel'::"text", 'estimate'::"text", 'inspection'::"text", 'overtime'::"text", 'ad_hoc'::"text"])))
);


ALTER TABLE "public"."job_time_entries" OWNER TO "postgres";


COMMENT ON COLUMN "public"."job_time_entries"."clock_in" IS 'When tech arrived on site — travel ends, on-site begins';



COMMENT ON COLUMN "public"."job_time_entries"."clock_out" IS 'When entry truly closes — next OMW or end of day';



COMMENT ON COLUMN "public"."job_time_entries"."travel_start" IS 'When tech tapped OMW — clock starts here';



COMMENT ON COLUMN "public"."job_time_entries"."on_site_end" IS 'When tech tapped Finish — triggers client text, but clock keeps running';



COMMENT ON COLUMN "public"."job_time_entries"."paused_at" IS 'Timestamp when currently paused (null = not paused)';



COMMENT ON COLUMN "public"."job_time_entries"."total_paused_minutes" IS 'Accumulated pause time in minutes — subtracted from on-site duration';



CREATE OR REPLACE FUNCTION "public"."admin_clock_out_entry"("p_id" "uuid", "p_actor_id" "uuid", "p_clock_out" timestamp with time zone DEFAULT "now"()) RETURNS "public"."job_time_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_e job_time_entries%ROWTYPE; v_paused numeric; v_hours numeric;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  select * into v_e from job_time_entries where id=p_id;
  if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
  if v_e.clock_out is not null then raise exception 'ALREADY_CLOSED' using errcode='P0001'; end if;
  if v_e.clock_in is not null then
    v_paused := coalesce(v_e.total_paused_minutes,0);
    if v_e.paused_at is not null then v_paused := v_paused + greatest(0, extract(epoch from (p_clock_out - v_e.paused_at))/60); end if;
    v_hours := least(24, greatest(0, extract(epoch from (p_clock_out - v_e.clock_in))/3600 - v_paused/60));
    update job_time_entries set clock_out=p_clock_out, on_site_end=coalesce(on_site_end,p_clock_out), hours=v_hours, paused_at=null, total_paused_minutes=round(v_paused::numeric,2), updated_at=now() where id=p_id returning * into v_e;
  else
    update job_time_entries set clock_out=p_clock_out, hours=0, travel_minutes=coalesce(travel_minutes, least(1440, greatest(0, round(extract(epoch from (p_clock_out - v_e.travel_start))/60.0,1)))), updated_at=now() where id=p_id returning * into v_e;
  end if;
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload) values ('time_entry.admin_clocked_out','job_time_entry', v_e.id, p_actor_id, v_e.job_id, jsonb_build_object('clock_out', p_clock_out));
  return v_e;
end; $$;


ALTER FUNCTION "public"."admin_clock_out_entry"("p_id" "uuid", "p_actor_id" "uuid", "p_clock_out" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_time_entry"("p_actor_id" "uuid", "p_id" "uuid" DEFAULT NULL::"uuid", "p_employee_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_work_date" "date" DEFAULT NULL::"date", "p_hours" numeric DEFAULT NULL::numeric, "p_clock_in" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_clock_out" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_travel_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_on_site_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_travel_minutes" numeric DEFAULT NULL::numeric, "p_total_paused_minutes" numeric DEFAULT NULL::numeric, "p_work_type" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_override_approved" boolean DEFAULT false) RETURNS "public"."job_time_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_old job_time_entries%ROWTYPE; v_new job_time_entries%ROWTYPE; v_emp uuid; v_ts timestamptz; v_ci timestamptz; v_ose timestamptz; v_co timestamptz;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  if p_id is not null then
    select * into v_old from job_time_entries where id=p_id;
    if v_old.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
    if v_old.approved and not p_override_approved then raise exception 'ENTRY_APPROVED_LOCKED' using errcode='P0001'; end if;
  end if;
  v_emp := coalesce(p_employee_id, v_old.employee_id);
  v_ts := coalesce(p_travel_start, v_old.travel_start); v_ci := coalesce(p_clock_in, v_old.clock_in);
  v_ose := coalesce(p_on_site_end, v_old.on_site_end); v_co := coalesce(p_clock_out, v_old.clock_out);
  if v_ts is not null and v_ci is not null and v_ci < v_ts then raise exception 'BAD_ORDER_clock_in_before_travel' using errcode='P0001'; end if;
  if v_ci is not null and v_ose is not null and v_ose < v_ci then raise exception 'BAD_ORDER_on_site_end_before_clock_in' using errcode='P0001'; end if;
  if v_ose is not null and v_co is not null and v_co < v_ose then raise exception 'BAD_ORDER_clock_out_before_on_site_end' using errcode='P0001'; end if;
  if v_ci is not null and v_co is not null and v_co < v_ci then raise exception 'BAD_ORDER_clock_out_before_clock_in' using errcode='P0001'; end if;
  if v_co is null and v_ts is not null then
    if exists (select 1 from job_time_entries where employee_id=v_emp and clock_out is null and travel_start is not null and id <> coalesce(p_id,'00000000-0000-0000-0000-000000000000')) then
      raise exception 'OPEN_ENTRY_EXISTS' using errcode='P0001'; end if;
  end if;
  if p_id is null then
    if v_emp is null or p_job_id is null then raise exception 'MISSING_REQUIRED_FIELDS' using errcode='P0001'; end if;
    insert into job_time_entries (employee_id, job_id, work_date, hours, work_type, description, notes, travel_start, clock_in, on_site_end, clock_out, travel_minutes, total_paused_minutes, entered_by, auto_continued, source)
    values (v_emp, p_job_id, coalesce(p_work_date,(now() at time zone 'America/Denver')::date), coalesce(p_hours,0), coalesce(p_work_type,'field'), p_description, p_notes, v_ts, v_ci, v_ose, v_co, p_travel_minutes, coalesce(p_total_paused_minutes,0), p_actor_id, false, 'admin')
    returning * into v_new;
  else
    update job_time_entries set employee_id=v_emp, job_id=coalesce(p_job_id,v_old.job_id), work_date=coalesce(p_work_date,v_old.work_date),
      hours=coalesce(p_hours,v_old.hours), work_type=coalesce(p_work_type,v_old.work_type), description=coalesce(p_description,v_old.description),
      notes=coalesce(p_notes,v_old.notes), travel_start=v_ts, clock_in=v_ci, on_site_end=v_ose, clock_out=v_co,
      travel_minutes=coalesce(p_travel_minutes,v_old.travel_minutes), total_paused_minutes=coalesce(p_total_paused_minutes,v_old.total_paused_minutes),
      auto_continued=false, updated_at=now() where id=p_id returning * into v_new;
  end if;
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload)
  values (case when p_id is null then 'time_entry.admin_created' else 'time_entry.admin_updated' end, 'job_time_entry', v_new.id, p_actor_id, v_new.job_id, jsonb_build_object('override_approved', p_override_approved));
  return v_new;
end; $$;


ALTER FUNCTION "public"."admin_upsert_time_entry"("p_actor_id" "uuid", "p_id" "uuid", "p_employee_id" "uuid", "p_job_id" "uuid", "p_work_date" "date", "p_hours" numeric, "p_clock_in" timestamp with time zone, "p_clock_out" timestamp with time zone, "p_travel_start" timestamp with time zone, "p_on_site_end" timestamp with time zone, "p_travel_minutes" numeric, "p_total_paused_minutes" numeric, "p_work_type" "text", "p_description" "text", "p_notes" "text", "p_override_approved" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_qbo_invoice_command_attempt"("p_command_id" "uuid", "p_expected_provider_stage" "text", "p_provider_stage" "text", "p_provider_action" "text", "p_provider_target_id" "text", "p_provider_request_id" "text", "p_provider_payload" "jsonb", "p_provider_payload_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_command public.qbo_invoice_commands; v_reservation public.qbo_invoice_command_reservations;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE='42501'; END IF;
 IF p_expected_provider_stage IS NULL OR p_provider_stage IS NULL OR p_provider_action IS NULL OR p_provider_request_id IS NULL OR (p_provider_target_id IS NULL AND p_provider_action <> 'create') OR jsonb_typeof(p_provider_payload) <> 'object' OR p_provider_payload_hash !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-attempt'); END IF;
 SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id=p_command_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations WHERE invoice_id=v_command.invoice_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.command_id IS DISTINCT FROM p_command_id OR v_reservation.action IS DISTINCT FROM v_command.action OR v_reservation.actor_auth_user_id IS DISTINCT FROM v_command.actor_auth_user_id OR v_reservation.actor_employee_id IS DISTINCT FROM v_command.actor_employee_id OR v_reservation.initiator IS DISTINCT FROM v_command.initiator OR v_reservation.realm_id IS DISTINCT FROM v_command.realm_id THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
 IF v_command.status <> 'provider_started' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-state','status',v_command.status); END IF;
 IF v_command.provider_stage = p_provider_stage AND v_command.provider_action IS NOT DISTINCT FROM p_provider_action AND v_command.provider_target_id IS NOT DISTINCT FROM p_provider_target_id AND v_command.provider_request_id IS NOT DISTINCT FROM p_provider_request_id AND v_command.provider_payload IS NOT DISTINCT FROM p_provider_payload AND v_command.provider_payload_hash IS NOT DISTINCT FROM p_provider_payload_hash THEN RETURN jsonb_build_object('ok',true,'replay',true,'status',v_command.status,'provider_stage',v_command.provider_stage,'provider_action',v_command.provider_action,'provider_target_id',v_command.provider_target_id,'provider_request_id',v_command.provider_request_id,'provider_payload',v_command.provider_payload,'provider_payload_hash',v_command.provider_payload_hash); END IF;
 IF v_command.provider_stage IS DISTINCT FROM p_expected_provider_stage THEN RETURN jsonb_build_object('ok',false,'reason','attempt-mismatch','provider_stage',v_command.provider_stage); END IF;
 UPDATE public.qbo_invoice_commands SET provider_stage=p_provider_stage,provider_action=p_provider_action,provider_target_id=p_provider_target_id,provider_request_id=p_provider_request_id,provider_payload=p_provider_payload,provider_payload_hash=p_provider_payload_hash,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
 RETURN jsonb_build_object('ok',true,'advanced',true,'status',v_command.status,'provider_stage',v_command.provider_stage,'provider_action',v_command.provider_action,'provider_target_id',v_command.provider_target_id,'provider_request_id',v_command.provider_request_id,'provider_payload',v_command.provider_payload,'provider_payload_hash',v_command.provider_payload_hash);
END;
$_$;


ALTER FUNCTION "public"."advance_qbo_invoice_command_attempt"("p_command_id" "uuid", "p_expected_provider_stage" "text", "p_provider_stage" "text", "p_provider_action" "text", "p_provider_target_id" "text", "p_provider_request_id" "text", "p_provider_payload" "jsonb", "p_provider_payload_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_midnight_clock_split"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_started timestamptz := now();
  v_count   int := 0;
  v_e       record;
  v_cap     timestamptz;
  v_paused  numeric;
  v_hours   numeric;
  v_emp     text;
begin
  for v_e in
    select * from job_time_entries
    where clock_out is null
      and travel_start is not null
      and work_date < (now() at time zone 'America/Denver')::date
    order by work_date asc, created_at asc
  loop
    v_cap := ((v_e.work_date::text || ' 23:59:59')::timestamp at time zone 'America/Denver');

    if v_e.clock_in is not null then
      v_paused := coalesce(v_e.total_paused_minutes, 0);
      if v_e.paused_at is not null then
        v_paused := v_paused + greatest(0, extract(epoch from (v_cap - v_e.paused_at)) / 60);
      end if;
      v_hours := least(24, greatest(0, extract(epoch from (v_cap - v_e.clock_in)) / 3600 - v_paused / 60));
      update job_time_entries
        set clock_out = v_cap, on_site_end = coalesce(on_site_end, v_cap), hours = v_hours,
            paused_at = null, total_paused_minutes = round(v_paused::numeric, 2), updated_at = now()
      where id = v_e.id;
    else
      update job_time_entries
        set clock_out = v_cap, hours = 0,
            travel_minutes = coalesce(travel_minutes,
              least(1440, greatest(0, round(extract(epoch from (v_cap - v_e.travel_start)) / 60.0, 1)))),
            updated_at = now()
      where id = v_e.id;
    end if;

    if v_e.auto_continued = true and coalesce(v_e.auto_split_seq, 0) >= 1 then
      update job_time_entries
        set notes = coalesce(notes, '') || ' [abandoned: needs review]', updated_at = now()
      where id = v_e.id;
      select full_name into v_emp from employees where id = v_e.employee_id;
      perform create_notification(
        'time_entry.abandoned_clock', 'Abandoned clock needs review',
        coalesce(v_emp, 'A tech') || ' had an auto-continued clock that was never touched for a second day; it has been stopped. Please review their hours.',
        '/time-tracking', 'job_time_entry', v_e.id, v_e.job_id,
        jsonb_build_object('employee_id', v_e.employee_id, 'work_date', v_e.work_date, 'auto_split_seq', v_e.auto_split_seq)
      );
    else
      insert into job_time_entries (
        job_id, employee_id, appointment_id, work_date, hours, work_type,
        travel_start, clock_in, entered_by, description,
        auto_continued, continued_from, auto_split_seq, source
      ) values (
        v_e.job_id, v_e.employee_id, v_e.appointment_id, (v_e.work_date + 1), 0, coalesce(v_e.work_type, 'field'),
        (((v_e.work_date + 1)::text || ' 00:00:00')::timestamp at time zone 'America/Denver'),
        (((v_e.work_date + 1)::text || ' 00:00:00')::timestamp at time zone 'America/Denver'),
        v_e.employee_id, coalesce(v_e.description, 'Continued overnight'),
        true, v_e.id, coalesce(v_e.auto_split_seq, 0) + 1, 'auto_split'
      );
    end if;

    v_count := v_count + 1;
  end loop;

  insert into worker_runs (worker_name, status, records_processed, started_at, completed_at)
  values ('apply_midnight_clock_split', 'completed', v_count, v_started, now());
end;
$$;


ALTER FUNCTION "public"."apply_midnight_clock_split"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_qbo_estimate_decision"("p_estimate_id" "uuid", "p_action" "text", "p_approved_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_approved_amount" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_est public.estimates;
  v_action text := lower(trim(COALESCE(p_action, '')));
  v_conversion jsonb;
  v_invoice_id uuid;
  v_reason text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;

  IF v_action NOT IN ('accept', 'reject', 'convert', 'approve_only') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-action');
  END IF;

  SELECT * INTO v_est
  FROM public.estimates
  WHERE id = p_estimate_id
  FOR UPDATE;
  IF v_est.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'estimate-not-found');
  END IF;

  IF v_est.converted_invoice_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'already-converted',
      'status', v_est.status, 'invoice_id', v_est.converted_invoice_id);
  END IF;

  IF v_action = 'reject' THEN
    IF v_est.status = 'denied' THEN
      RETURN jsonb_build_object('ok', true, 'skipped', 'already-denied',
        'status', v_est.status);
    END IF;
    IF v_est.status NOT IN ('draft', 'submitted', 'under_review', 'revised') THEN
      RETURN jsonb_build_object('ok', true, 'skipped', 'already-decided',
        'status', v_est.status);
    END IF;
    UPDATE public.estimates
    SET status = 'denied',
        denied_reason = 'Declined by customer in QuickBooks',
        updated_at = now()
    WHERE id = v_est.id;
    RETURN jsonb_build_object('ok', true, 'action', 'denied');
  END IF;

  IF v_action = 'accept' AND v_est.status NOT IN ('draft', 'submitted', 'under_review', 'revised') THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'already-decided',
      'status', v_est.status);
  END IF;
  IF v_action = 'approve_only' AND v_est.status NOT IN ('draft', 'submitted', 'under_review', 'revised') THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'already-decided',
      'status', v_est.status);
  END IF;
  IF v_action = 'convert' AND v_est.status NOT IN ('draft', 'submitted', 'under_review', 'revised', 'approved') THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'already-decided',
      'status', v_est.status);
  END IF;

  -- Existing staff/QBO metadata always wins; supplied metadata is used only to
  -- fill a blank value, then the local estimate amount/clock is the fallback.
  UPDATE public.estimates
  SET approved_at = COALESCE(approved_at, p_approved_at, now()),
      approved_amount = COALESCE(approved_amount, p_approved_amount, amount),
      status = CASE WHEN v_action = 'approve_only' THEN 'approved' ELSE status END,
      updated_at = now()
  WHERE id = v_est.id;

  IF v_action = 'approve_only' THEN
    RETURN jsonb_build_object('ok', true, 'action', 'approved-needs-manual-convert');
  END IF;

  -- convert_estimate_to_invoice takes the same row lock re-entrantly and never
  -- forces line appends. A populated invoice is an explicit manual boundary.
  v_conversion := public.convert_estimate_to_invoice(v_est.id, false, NULL);
  v_invoice_id := NULLIF(v_conversion->>'invoice_id', '')::uuid;
  IF COALESCE((v_conversion->>'needs_confirm')::boolean, false) THEN
    UPDATE public.estimates
    SET status = 'approved', updated_at = now()
    WHERE id = v_est.id;
    RETURN jsonb_build_object('ok', true, 'action', 'approved-needs-manual-convert',
      'invoice_id', v_invoice_id, 'lines_copied', 0, 'appended', false);
  END IF;

  RETURN jsonb_build_object('ok', true, 'action', 'approved-and-converted',
    'invoice_id', v_invoice_id, 'lines_copied', COALESCE((v_conversion->>'lines_copied')::integer, 0),
    'appended', COALESCE((v_conversion->>'appended')::boolean, false));
END;
$$;


ALTER FUNCTION "public"."apply_qbo_estimate_decision"("p_estimate_id" "uuid", "p_action" "text", "p_approved_at" timestamp with time zone, "p_approved_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_schedule_plan"("p_job_id" "uuid", "p_template_id" "uuid", "p_start_date" "date", "p_skip_weekends" boolean DEFAULT true, "p_phase_overrides" "jsonb" DEFAULT '[]'::"jsonb", "p_duration_overrides" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_schedule_id UUID;
  v_template_name TEXT;
  v_phases RECORD;
  v_task RECORD;
  v_dep RECORD;
  v_current_date DATE;
  v_end_date DATE;
  v_phase_dates JSONB := '{}'::JSONB;
  v_skipped UUID[] := '{}';
  v_tasks_created INT := 0;
  v_phases_created INT := 0;
  v_sort INT := 0;
  v_jsp_id UUID;
  v_duration INT;
  v_override_duration INT;
  v_current_phase TEXT;
BEGIN
  SELECT name INTO v_template_name FROM schedule_templates WHERE id = p_template_id;
  IF v_template_name IS NULL THEN
    RAISE EXCEPTION 'Template not found';
  END IF;

  -- Get current job phase
  SELECT phase INTO v_current_phase FROM jobs WHERE id = p_job_id;

  IF EXISTS (SELECT 1 FROM job_schedules WHERE job_id = p_job_id) THEN
    DELETE FROM job_tasks WHERE job_id = p_job_id AND template_task_id IS NOT NULL;
    DELETE FROM job_schedule_phases WHERE job_schedule_id IN (SELECT id FROM job_schedules WHERE job_id = p_job_id);
    DELETE FROM job_schedules WHERE job_id = p_job_id;
  END IF;

  FOR v_phases IN SELECT * FROM jsonb_array_elements(p_phase_overrides) LOOP
    IF (v_phases.value->>'skip')::BOOLEAN IS TRUE THEN
      v_skipped := v_skipped || (v_phases.value->>'phase_id')::UUID;
    END IF;
  END LOOP;

  INSERT INTO job_schedules (job_id, template_id, start_date, name, created_by)
  VALUES (p_job_id, p_template_id, p_start_date, v_template_name, p_created_by)
  RETURNING id INTO v_schedule_id;

  FOR v_phases IN
    SELECT tp.id, tp.name, tp.color, tp.duration_days, tp.is_milestone, tp.display_order
    FROM template_phases tp
    WHERE tp.template_id = p_template_id
      AND tp.id != ALL(v_skipped)
    ORDER BY tp.display_order
  LOOP
    v_duration := v_phases.duration_days;
    IF p_duration_overrides ? v_phases.id::TEXT THEN
      v_override_duration := (p_duration_overrides->>v_phases.id::TEXT)::INT;
      IF v_override_duration > 0 THEN
        v_duration := v_override_duration;
      END IF;
    END IF;

    v_current_date := p_start_date;

    FOR v_dep IN
      SELECT td.source_phase_id, td.dependency_type
      FROM template_dependencies td
      WHERE td.target_phase_id = v_phases.id
        AND td.source_phase_id != ALL(v_skipped)
    LOOP
      IF v_phase_dates ? v_dep.source_phase_id::TEXT THEN
        DECLARE
          dep_end DATE;
        BEGIN
          dep_end := (v_phase_dates->v_dep.source_phase_id::TEXT->>'end_date')::DATE;
          IF v_dep.dependency_type = 'starts_after' THEN
            dep_end := dep_end + 1;
            IF p_skip_weekends THEN
              WHILE EXTRACT(DOW FROM dep_end) IN (0, 6) LOOP
                dep_end := dep_end + 1;
              END LOOP;
            END IF;
          END IF;
          IF dep_end > v_current_date THEN
            v_current_date := dep_end;
          END IF;
        END;
      END IF;
    END LOOP;

    IF p_skip_weekends THEN
      WHILE EXTRACT(DOW FROM v_current_date) IN (0, 6) LOOP
        v_current_date := v_current_date + 1;
      END LOOP;
    END IF;

    v_end_date := v_current_date;
    IF NOT v_phases.is_milestone AND v_duration > 1 THEN
      DECLARE
        days_remaining INT := v_duration - 1;
      BEGIN
        WHILE days_remaining > 0 LOOP
          v_end_date := v_end_date + 1;
          IF p_skip_weekends AND EXTRACT(DOW FROM v_end_date) IN (0, 6) THEN
            CONTINUE;
          END IF;
          days_remaining := days_remaining - 1;
        END LOOP;
      END;
    END IF;

    v_phase_dates := v_phase_dates || jsonb_build_object(
      v_phases.id::TEXT,
      jsonb_build_object('start_date', v_current_date::TEXT, 'end_date', v_end_date::TEXT)
    );

    v_sort := v_sort + 1;
    INSERT INTO job_schedule_phases (
      job_schedule_id, phase_name, phase_color, target_start, target_end,
      duration_days, sort_order, template_phase_id
    ) VALUES (
      v_schedule_id, v_phases.name, v_phases.color, v_current_date, v_end_date,
      v_duration, v_sort, v_phases.id
    ) RETURNING id INTO v_jsp_id;
    v_phases_created := v_phases_created + 1;

    FOR v_task IN
      SELECT tt.id, tt.title, tt.is_required, tt.display_order
      FROM template_tasks tt
      WHERE tt.template_phase_id = v_phases.id
      ORDER BY tt.display_order
    LOOP
      INSERT INTO job_tasks (
        job_id, job_schedule_id, phase_name, phase_color, template_task_id, template_phase_id,
        title, is_required, target_date, job_schedule_phase_id
      ) VALUES (
        p_job_id, v_schedule_id, v_phases.name, v_phases.color, v_task.id, v_phases.id,
        v_task.title, v_task.is_required, v_current_date, v_jsp_id
      );
      v_tasks_created := v_tasks_created + 1;
    END LOOP;
  END LOOP;

  -- Auto-advance job phase to reconstruction_in_progress if currently pre-production
  IF v_current_phase IN ('lead', 'job_received', 'estimate_submitted', 'estimate_approved', 'work_authorized') THEN
    UPDATE jobs SET 
      phase = 'reconstruction_in_progress',
      phase_entered_at = now(),
      updated_at = now()
    WHERE id = p_job_id;

    -- Log the phase change
    INSERT INTO job_phase_history (job_id, from_phase, to_phase, changed_by, changed_at)
    VALUES (p_job_id, v_current_phase, 'reconstruction_in_progress', p_created_by, now());
  END IF;

  RETURN jsonb_build_object(
    'schedule_id', v_schedule_id,
    'phases_created', v_phases_created,
    'tasks_created', v_tasks_created,
    'start_date', p_start_date,
    'end_date', (SELECT MAX(target_end) FROM job_schedule_phases WHERE job_schedule_id = v_schedule_id),
    'phase_advanced', v_current_phase IN ('lead', 'job_received', 'estimate_submitted', 'estimate_approved', 'work_authorized')
  );
END;
$$;


ALTER FUNCTION "public"."apply_schedule_plan"("p_job_id" "uuid", "p_template_id" "uuid", "p_start_date" "date", "p_skip_weekends" boolean, "p_phase_overrides" "jsonb", "p_duration_overrides" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_time_entries"("p_entry_ids" "uuid"[], "p_approved_by" "uuid", "p_approved" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE job_time_entries
  SET approved = p_approved,
      approved_by = CASE WHEN p_approved THEN p_approved_by ELSE NULL END,
      updated_at = now()
  WHERE id = ANY(p_entry_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."approve_time_entries"("p_entry_ids" "uuid"[], "p_approved_by" "uuid", "p_approved" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_tasks_to_appointment"("p_appointment_id" "uuid", "p_task_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_is_trusted boolean :=
    public.is_trusted_appointment_command_caller();
  v_job_id uuid;
  v_count integer := 0;
BEGIN
  IF p_appointment_id IS NULL THEN
    RAISE EXCEPTION
      'assign_tasks_to_appointment: p_appointment_id is required'
      USING ERRCODE = '22023';
  END IF;

  SELECT appointment.job_id
  INTO v_job_id
  FROM public.appointments appointment
  WHERE appointment.id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'assign_tasks_to_appointment: appointment not found'
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT v_is_trusted
     AND (
       public.current_active_internal_appointment_employee() IS NULL
       OR NOT public.can_current_employee_edit_appointment_command(
         p_appointment_id
       )
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment task access required'
      USING ERRCODE = '42501';
  END IF;

  IF p_task_ids IS NULL THEN
    RETURN jsonb_build_object(
      'appointment_id',
      p_appointment_id,
      'tasks_assigned',
      0
    );
  END IF;

  PERFORM 1
  FROM public.job_tasks task
  WHERE task.id = ANY(p_task_ids)
  ORDER BY task.id
  FOR UPDATE;

  IF cardinality(p_task_ids) IS DISTINCT FROM (
    SELECT count(*)::integer
    FROM public.job_tasks task
    WHERE task.id = ANY(p_task_ids)
      AND task.job_id = v_job_id
      AND (
        task.appointment_id IS NULL
        OR task.appointment_id = p_appointment_id
      )
  ) THEN
    RAISE EXCEPTION
      'assign_tasks_to_appointment: task IDs must be unique, unassigned/current, and belong to the appointment job'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.job_tasks task
  SET appointment_id = NULL
  WHERE task.appointment_id = p_appointment_id
    AND NOT (task.id = ANY(p_task_ids))
    AND task.is_completed IS FALSE;

  UPDATE public.job_tasks task
  SET appointment_id = p_appointment_id
  WHERE task.id = ANY(p_task_ids);

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'appointment_id',
    p_appointment_id,
    'tasks_assigned',
    v_count
  );
END;
$$;


ALTER FUNCTION "public"."assign_tasks_to_appointment"("p_appointment_id" "uuid", "p_task_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_tasks_to_appointment"("p_appointment_id" "uuid", "p_task_ids" "uuid"[]) IS 'UPR appointment crew atomic save/audit repair v1: legacy-compatible actor, object, and same-job task replacement';



CREATE OR REPLACE FUNCTION "public"."attest_prior_sms_consent"("p_contact_id" "uuid", "p_actor_id" "uuid", "p_consent_method" "text", "p_consent_obtained_on" "date", "p_evidence_note" "text", "p_request_ip" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor public.employees%ROWTYPE;
  v_contact public.contacts%ROWTYPE;
  v_existing public.service_sms_consents%ROWTYPE;
  v_method text := lower(btrim(COALESCE(p_consent_method, '')));
  v_note text := btrim(COALESCE(p_evidence_note, ''));
  v_request_ip text := NULLIF(btrim(COALESCE(p_request_ip, '')), '');
  v_phone_digits text;
  v_phone_key text;
  v_locked_phone_digits text;
  v_locked_phone_key text;
  v_recorded_at timestamptz := now();
  v_already_recorded boolean := false;
  v_attestation_id uuid;
BEGIN
  IF current_user <> 'service_role' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'CONSENT_ATTESTATION_NOT_AUTHORIZED'
    );
  END IF;

  IF p_contact_id IS NULL OR p_actor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ATTESTATION');
  END IF;

  IF v_method <> ALL (ARRAY[
    'verbal_permission',
    'signed_work_authorization',
    'other_written_permission',
    'customer_requested_texts',
    'other_verified_permission'
  ]) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CONSENT_METHOD');
  END IF;

  IF char_length(v_note) < 10 OR char_length(v_note) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_EVIDENCE_NOTE');
  END IF;

  IF p_consent_obtained_on IS NULL
     OR p_consent_obtained_on > (v_recorded_at AT TIME ZONE 'America/Denver')::date THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_CONSENT_DATE');
  END IF;

  IF v_request_ip IS NOT NULL
     AND (
       char_length(v_request_ip) < 3
       OR char_length(v_request_ip) > 64
       OR v_request_ip !~ '^[0-9A-Fa-f:.]+$'
     ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST_IP');
  END IF;

  SELECT *
  INTO v_actor
  FROM public.employees
  WHERE id = p_actor_id
  LIMIT 1
  FOR SHARE;

  IF v_actor.id IS NULL
     OR v_actor.is_active IS DISTINCT FROM true
     OR v_actor.is_external IS DISTINCT FROM false
     OR v_actor.role::text NOT IN ('admin', 'office') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'CONSENT_ATTESTATION_NOT_AUTHORIZED'
    );
  END IF;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id;

  IF v_contact.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_NOT_FOUND');
  END IF;

  v_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_phone_digits) = 10 THEN
    v_phone_key := v_phone_digits;
  ELSIF length(v_phone_digits) = 11 AND left(v_phone_digits, 1) = '1' THEN
    v_phone_key := right(v_phone_digits, 10);
  ELSE
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_HAS_NO_PHONE');
  END IF;

  -- Serialize with the CallRail inbound projector, then lock every duplicate
  -- contact using this normalized number before checking suppression.
  PERFORM pg_advisory_xact_lock(hashtextextended('messaging-phone:' || v_phone_key, 0));

  PERFORM c.id
  FROM public.contacts c
  WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
  ORDER BY c.id
  FOR UPDATE;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id
  FOR UPDATE;

  v_locked_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_locked_phone_digits) = 10 THEN
    v_locked_phone_key := v_locked_phone_digits;
  ELSIF length(v_locked_phone_digits) = 11 AND left(v_locked_phone_digits, 1) = '1' THEN
    v_locked_phone_key := right(v_locked_phone_digits, 10);
  END IF;

  IF v_contact.id IS NULL
     OR v_locked_phone_key IS NULL
     OR v_locked_phone_key <> v_phone_key THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_PHONE_CHANGED');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.dnd IS TRUE
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_DND_ACTIVE');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.opt_out_at IS NOT NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_OPTED_OUT');
  END IF;

  -- The provider-event insert commits before the CallRail projection RPC. If a
  -- STOP is durable but not yet projected onto contacts, refuse attestation.
  IF EXISTS (
    SELECT 1
    FROM public.message_provider_events e
    WHERE e.direction = 'inbound'
      AND e.message_type IN ('sms', 'mms')
      AND e.processing_state IN ('received', 'claimed', 'retryable', 'failed')
      AND right(regexp_replace(COALESCE(e.sender_address, ''), '[^0-9]', '', 'g'), 10)
        = v_phone_key
      AND regexp_replace(lower(trim(COALESCE(e.content, ''))), '[^a-z0-9]', '', 'g')
        = ANY (ARRAY['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'])
      AND NOT EXISTS (
        SELECT 1
        FROM public.message_provider_events later_event
        WHERE later_event.direction = 'inbound'
          AND later_event.message_type IN ('sms', 'mms')
          AND later_event.processing_state = 'processed'
          AND right(
            regexp_replace(COALESCE(later_event.sender_address, ''), '[^0-9]', '', 'g'),
            10
          ) = v_phone_key
          AND later_event.occurred_at > e.occurred_at
          AND regexp_replace(
            lower(trim(COALESCE(later_event.content, ''))),
            '[^a-z0-9]',
            '',
            'g'
          ) = ANY (ARRAY['start', 'unstop', 'subscribe', 'yes'])
      )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'CONTACT_PENDING_STOP');
  END IF;

  SELECT *
  INTO v_existing
  FROM public.service_sms_consents
  WHERE contact_id = v_contact.id
  FOR UPDATE;
  v_already_recorded := v_existing.contact_id IS NOT NULL;

  -- Raw evidence is append-only and browser-inaccessible. The legacy
  -- sms_consent_log receives only a redacted reference to this row.
  INSERT INTO public.service_sms_consent_attestations (
    contact_id,
    phone,
    consent_scope,
    consent_method,
    consent_obtained_on,
    evidence_note,
    attestation_version,
    sender_identity,
    recorded_by,
    request_ip,
    recorded_at
  )
  VALUES (
    v_contact.id,
    v_contact.phone,
    'service_related_customer_project_messages',
    v_method,
    p_consent_obtained_on,
    v_note,
    'prior_sms_consent_v1',
    'Utah Pros Restoration',
    v_actor.id,
    v_request_ip,
    v_recorded_at
  )
  RETURNING id INTO v_attestation_id;

  INSERT INTO public.service_sms_consents (
    contact_id,
    phone,
    consent_scope,
    consent_method,
    consent_obtained_on,
    evidence_note,
    attestation_version,
    sender_identity,
    recorded_by,
    request_ip,
    attested_at,
    updated_at
  )
  VALUES (
    v_contact.id,
    v_contact.phone,
    'service_related_customer_project_messages',
    v_method,
    p_consent_obtained_on,
    v_note,
    'prior_sms_consent_v1',
    'Utah Pros Restoration',
    v_actor.id,
    v_request_ip,
    v_recorded_at,
    v_recorded_at
  )
  ON CONFLICT (contact_id) DO UPDATE
  SET
    phone = EXCLUDED.phone,
    consent_scope = EXCLUDED.consent_scope,
    consent_method = EXCLUDED.consent_method,
    consent_obtained_on = EXCLUDED.consent_obtained_on,
    evidence_note = EXCLUDED.evidence_note,
    attestation_version = EXCLUDED.attestation_version,
    sender_identity = EXCLUDED.sender_identity,
    recorded_by = EXCLUDED.recorded_by,
    request_ip = EXCLUDED.request_ip,
    attested_at = EXCLUDED.attested_at,
    updated_at = EXCLUDED.updated_at;

  -- Every successful submission appends evidence, including a re-attestation.
  INSERT INTO public.sms_consent_log (
    contact_id,
    phone,
    event_type,
    source,
    details,
    ip_address,
    performed_by,
    created_at
  )
  VALUES (
    v_contact.id,
    v_contact.phone,
    'prior_consent_attested',
    v_method,
    jsonb_build_object(
      'attestation', 'verified_prior_sms_consent',
      'attestation_id', v_attestation_id,
      'attestation_version', 'prior_sms_consent_v1',
      'consent_scope', 'service_related_customer_project_messages',
      'sender_identity', 'Utah Pros Restoration',
      'recorded_at', v_recorded_at
    )::text,
    NULL,
    v_actor.id,
    v_recorded_at
  );

  RETURN jsonb_build_object(
    'ok', true,
    'already_recorded', v_already_recorded,
    'contact_id', v_contact.id,
    'service_sms_consent', true,
    'consent_scope', 'service_related_customer_project_messages',
    'consent_method', v_method,
    'consent_obtained_on', p_consent_obtained_on,
    'recorded_by', v_actor.id,
    'attested_at', v_recorded_at
  );
END;
$_$;


ALTER FUNCTION "public"."attest_prior_sms_consent"("p_contact_id" "uuid", "p_actor_id" "uuid", "p_consent_method" "text", "p_consent_obtained_on" "date", "p_evidence_note" "text", "p_request_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_appointment_crew_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_kind text;
  v_is_trusted boolean :=
    public.is_trusted_appointment_command_caller();
  v_appointment_id uuid;
  v_job_id uuid;
  v_old_assignment jsonb;
  v_new_assignment jsonb;
BEGIN
  v_actor_id :=
    public.current_attributed_appointment_crew_actor();
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: attributed active internal appointment actor required'
      USING ERRCODE = '42501';
  END IF;

  IF v_is_trusted THEN
    v_actor_kind := CASE
      WHEN auth.jwt() ->> 'role' = 'service_role' THEN 'service_role'
      ELSE 'database_owner'
    END;
  ELSE
    v_actor_kind := 'employee';
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE')
     AND NOT EXISTS (
       SELECT 1
       FROM public.employees employee
       WHERE employee.id = NEW.employee_id
         AND employee.is_active IS TRUE
         AND employee.is_external IS FALSE
         AND employee.role::text IS DISTINCT FROM 'crm_partner'
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal appointment crew required'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE'
     AND (
       NEW.id IS DISTINCT FROM OLD.id
       OR NEW.appointment_id IS DISTINCT FROM OLD.appointment_id
       OR NEW.employee_id IS DISTINCT FROM OLD.employee_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment crew identity is immutable'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.role IS NOT DISTINCT FROM OLD.role THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_appointment_id := OLD.appointment_id;
    v_old_assignment := jsonb_build_object(
      'employee_id', OLD.employee_id,
      'role', OLD.role::text
    );
  ELSIF TG_OP = 'INSERT' THEN
    v_appointment_id := NEW.appointment_id;
    v_new_assignment := jsonb_build_object(
      'employee_id', NEW.employee_id,
      'role', NEW.role::text
    );
  ELSE
    v_appointment_id := NEW.appointment_id;
    v_old_assignment := jsonb_build_object(
      'employee_id', OLD.employee_id,
      'role', OLD.role::text
    );
    v_new_assignment := jsonb_build_object(
      'employee_id', NEW.employee_id,
      'role', NEW.role::text
    );
  END IF;

  SELECT appointment.job_id
  INTO v_job_id
  FROM public.appointments appointment
  WHERE appointment.id = v_appointment_id;

  INSERT INTO public.system_events (
    event_type,
    entity_type,
    entity_id,
    actor_id,
    job_id,
    payload
  )
  VALUES (
    'appointment.crew_changed',
    'appointment',
    v_appointment_id,
    v_actor_id,
    v_job_id,
    jsonb_build_object(
      'operation', lower(TG_OP),
      'actor_kind', v_actor_kind,
      'old_assignment', v_old_assignment,
      'new_assignment', v_new_assignment,
      'changed_at', statement_timestamp()
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."audit_appointment_crew_change"() OWNER TO "postgres";


