CREATE OR REPLACE FUNCTION "public"."cas_qbo_invoice_link"("p_invoice_id" "uuid", "p_expected_qbo_invoice_id" "text", "p_new_qbo_invoice_id" "text", "p_qbo_doc_number" "text" DEFAULT NULL::"text", "p_qbo_emailed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_qbo_email_status" "text" DEFAULT NULL::"text", "p_sent_to_email" "text" DEFAULT NULL::"text", "p_write_email_metadata" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_invoice public.invoices;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_invoice FROM public.invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','invoice-not-found'); END IF;
 IF v_invoice.locked IS TRUE THEN RETURN jsonb_build_object('ok',false,'reason','invoice-locked','current_qbo_invoice_id',v_invoice.qbo_invoice_id); END IF;
 IF v_invoice.qbo_invoice_id IS DISTINCT FROM p_expected_qbo_invoice_id THEN
   IF v_invoice.qbo_invoice_id IS NOT DISTINCT FROM p_new_qbo_invoice_id THEN RETURN jsonb_build_object('ok',true,'id',v_invoice.id,'job_id',v_invoice.job_id,'contact_id',v_invoice.contact_id,'invoice_number',v_invoice.invoice_number,'qbo_doc_number',v_invoice.qbo_doc_number,'qbo_invoice_id',v_invoice.qbo_invoice_id,'idempotent',true); END IF;
   RETURN jsonb_build_object('ok',false,'reason','qbo-invoice-mismatch','current_qbo_invoice_id',v_invoice.qbo_invoice_id);
 END IF;
 UPDATE public.invoices SET qbo_invoice_id=p_new_qbo_invoice_id,qbo_synced_at=CASE WHEN p_new_qbo_invoice_id IS NULL THEN NULL ELSE now() END,qbo_doc_number=CASE WHEN p_new_qbo_invoice_id IS NULL THEN NULL ELSE COALESCE(p_qbo_doc_number,qbo_doc_number) END,qbo_emailed_at=CASE WHEN p_new_qbo_invoice_id IS DISTINCT FROM v_invoice.qbo_invoice_id THEN NULL WHEN p_write_email_metadata THEN p_qbo_emailed_at ELSE qbo_emailed_at END,qbo_email_status=CASE WHEN p_new_qbo_invoice_id IS DISTINCT FROM v_invoice.qbo_invoice_id THEN NULL WHEN p_write_email_metadata THEN p_qbo_email_status ELSE qbo_email_status END,sent_to_email=CASE WHEN p_new_qbo_invoice_id IS DISTINCT FROM v_invoice.qbo_invoice_id THEN NULL WHEN p_write_email_metadata THEN p_sent_to_email ELSE sent_to_email END,qbo_sync_error=NULL,updated_at=now() WHERE id=v_invoice.id RETURNING * INTO v_invoice;
 RETURN jsonb_build_object('ok',true,'id',v_invoice.id,'job_id',v_invoice.job_id,'contact_id',v_invoice.contact_id,'invoice_number',v_invoice.invoice_number,'qbo_doc_number',v_invoice.qbo_doc_number,'qbo_invoice_id',v_invoice.qbo_invoice_id);
END;
$$;


ALTER FUNCTION "public"."cas_qbo_invoice_link"("p_invoice_id" "uuid", "p_expected_qbo_invoice_id" "text", "p_new_qbo_invoice_id" "text", "p_qbo_doc_number" "text", "p_qbo_emailed_at" timestamp with time zone, "p_qbo_email_status" "text", "p_sent_to_email" "text", "p_write_email_metadata" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."message_provider_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "provider_event_id" "text",
    "provider_message_id" "text",
    "provider_conversation_id" "text",
    "direction" "text",
    "message_type" "text",
    "provider_status" "text",
    "sender_address" "text",
    "recipient_address" "text",
    "content" "text",
    "company_resource_id" "text",
    "person_resource_id" "text",
    "agent_name" "text",
    "media_count" integer DEFAULT 0 NOT NULL,
    "owned_media" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "raw_body_hash" "text" NOT NULL,
    "dedupe_key" "text" NOT NULL,
    "occurred_at" timestamp with time zone,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "processing_state" "text" DEFAULT 'received'::"text" NOT NULL,
    "processing_attempts" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone,
    "claimed_at" timestamp with time zone,
    "processed_at" timestamp with time zone,
    "message_id" "uuid",
    "contact_id" "uuid",
    "conversation_id" "uuid",
    "send_attempt_id" "uuid",
    "outcome" "text",
    "error_code" "text",
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    CONSTRAINT "message_provider_events_direction_check" CHECK ((("direction" IS NULL) OR ("direction" = ANY (ARRAY['inbound'::"text", 'outbound'::"text"])))),
    CONSTRAINT "message_provider_events_media_count_check" CHECK (("media_count" >= 0)),
    CONSTRAINT "message_provider_events_message_type_check" CHECK ((("message_type" IS NULL) OR ("message_type" = ANY (ARRAY['sms'::"text", 'mms'::"text", 'rcs'::"text"])))),
    CONSTRAINT "message_provider_events_owned_media_check" CHECK (("jsonb_typeof"("owned_media") = 'array'::"text")),
    CONSTRAINT "message_provider_events_processing_attempts_check" CHECK (("processing_attempts" >= 0)),
    CONSTRAINT "message_provider_events_provider_check" CHECK (("provider" = ANY (ARRAY['twilio'::"text", 'callrail'::"text"]))),
    CONSTRAINT "message_provider_events_state_check" CHECK (("processing_state" = ANY (ARRAY['received'::"text", 'claimed'::"text", 'processed'::"text", 'retryable'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."message_provider_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."message_provider_events" IS 'Service-only deduplicated provider-event inbox. Stores normalized text facts needed for recovery, not raw provider payloads or short-lived media URLs.';



COMMENT ON COLUMN "public"."message_provider_events"."provider_status" IS 'Provider-native status observed on this event. Domain state is derived only after provider-specific validation.';



COMMENT ON COLUMN "public"."message_provider_events"."resolved_at" IS 'Set when a human or Worker has acknowledged a terminal failure. The ops-health check ignores resolved rows, which is what stops a permanent failure alerting every Denver day forever. NULL means still outstanding.';



CREATE OR REPLACE FUNCTION "public"."claim_callrail_provider_event"("p_event_id" "uuid", "p_now" timestamp with time zone, "p_stale_before" timestamp with time zone) RETURNS SETOF "public"."message_provider_events"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'claim_callrail_provider_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  UPDATE public.message_provider_events AS event
  SET
    processing_state = 'claimed',
    processing_attempts = event.processing_attempts + 1,
    claimed_at = p_now,
    updated_at = p_now
  WHERE event.id = p_event_id
    AND event.provider = 'callrail'
    AND event.message_type IN ('sms', 'mms')
    AND (
      event.processing_state = 'received'
      OR (
        event.processing_state = 'retryable'
        AND event.next_attempt_at <= p_now
      )
      OR (
        event.processing_state = 'claimed'
        AND event.claimed_at < p_stale_before
      )
    )
  RETURNING event.*;
END;
$$;


ALTER FUNCTION "public"."claim_callrail_provider_event"("p_event_id" "uuid", "p_now" timestamp with time zone, "p_stale_before" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_callrail_provider_event"("p_event_id" "uuid", "p_now" timestamp with time zone, "p_stale_before" timestamp with time zone) IS 'Service-only atomic claim fence for one due CallRail provider event.';



CREATE OR REPLACE FUNCTION "public"."claim_fixed_automation"("p_automation_key" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_claimed boolean := false;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'claim_fixed_automation is service-role only'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.fixed_automation_claims AS c (
    automation_key, entity_type, entity_id, claimed_at
  )
  VALUES (p_automation_key, p_entity_type, p_entity_id, p_now)
  ON CONFLICT ON CONSTRAINT fixed_automation_claims_unique_entity DO NOTHING;

  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  RETURN v_claimed;
END;
$$;


ALTER FUNCTION "public"."claim_fixed_automation"("p_automation_key" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_fixed_automation"("p_automation_key" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_now" timestamp with time zone) IS 'Service-only atomic claim taken BEFORE a fixed automation sends. True means this caller may send.';



