CREATE OR REPLACE FUNCTION "public"."claim_message_notification_outbox"("p_limit" integer, "p_now" timestamp with time zone, "p_stale_before" timestamp with time zone, "p_claim_token" "uuid") RETURNS TABLE("id" "uuid", "type_key" "text", "payload" "jsonb", "delivery_attempts" integer, "claim_token" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'claim_message_notification_outbox is service-role only'
      USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100
     OR p_now IS NULL OR p_stale_before IS NULL OR p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Notification outbox claim arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH due AS (
    SELECT o.id
    FROM public.message_notification_outbox o
    WHERE (
        o.delivery_state = 'pending'
        OR (
          o.delivery_state = 'retryable'
          AND o.next_attempt_at <= p_now
        )
        OR (
          o.delivery_state = 'processing'
          AND o.claimed_at < p_stale_before
        )
      )
    ORDER BY COALESCE(o.next_attempt_at, o.created_at), o.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  )
  UPDATE public.message_notification_outbox o
  SET
    delivery_state = 'processing',
    delivery_attempts = o.delivery_attempts + 1,
    claimed_at = p_now,
    claim_token = p_claim_token,
    updated_at = p_now
  FROM due
  WHERE o.id = due.id
  RETURNING o.id, o.type_key, o.payload, o.delivery_attempts, o.claim_token;
END;
$$;


ALTER FUNCTION "public"."claim_message_notification_outbox"("p_limit" integer, "p_now" timestamp with time zone, "p_stale_before" timestamp with time zone, "p_claim_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_message_notification_outbox"("p_limit" integer, "p_now" timestamp with time zone, "p_stale_before" timestamp with time zone, "p_claim_token" "uuid") IS 'Service-role-only fenced lease claim for due or stale inbound-message notification jobs.';



CREATE OR REPLACE FUNCTION "public"."claim_message_recipient_attempt"("p_attempt_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'claim_message_recipient_attempt is service-role only'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.message_send_attempts
  SET
    state = 'submitting',
    started_at = now(),
    updated_at = now()
  WHERE id = p_attempt_id
    AND parent_attempt_id IS NOT NULL
    AND state = 'prepared'
    AND message_id IS NULL
    AND provider_message_id IS NULL;

  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."claim_message_recipient_attempt"("p_attempt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_message_recipient_attempt"("p_attempt_id" "uuid") IS 'Service-role-only atomic prepared-to-submitting claim; only the winning worker may perform the recipient provider side effect.';



CREATE OR REPLACE FUNCTION "public"."claim_native_push_delivery"("p_delivery_key" "uuid", "p_employee_id" "uuid", "p_device_token_id" "uuid", "p_device_fingerprint" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_claimed boolean;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required'
      USING errcode = '42501';
  END IF;

  -- The claim prevents duplicate retries, but it is not permanent business
  -- history. Retain a 90-day replay window and remove at most 1,000 expired
  -- rows per delivery so an active device cannot grow this table forever.
  WITH expired_claims AS (
    SELECT existing_claim.delivery_key
    FROM public.native_push_delivery_claims existing_claim
    WHERE existing_claim.claimed_at < now() - interval '90 days'
    ORDER BY existing_claim.claimed_at
    LIMIT 1000
  )
  DELETE FROM public.native_push_delivery_claims existing_claim
  USING expired_claims
  WHERE existing_claim.delivery_key = expired_claims.delivery_key;

  INSERT INTO public.native_push_delivery_claims (
    delivery_key,
    employee_id,
    device_fingerprint
  )
  SELECT
    p_delivery_key,
    p_employee_id,
    p_device_fingerprint
  WHERE EXISTS (
    SELECT 1
    FROM public.device_tokens token_row
    WHERE token_row.id = p_device_token_id
      AND token_row.employee_id = p_employee_id
  )
  ON CONFLICT (delivery_key) DO NOTHING
  RETURNING true INTO v_claimed;

  RETURN COALESCE(v_claimed, false);
END;
$$;


ALTER FUNCTION "public"."claim_native_push_delivery"("p_delivery_key" "uuid", "p_employee_id" "uuid", "p_device_token_id" "uuid", "p_device_fingerprint" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_notification_delivery_diagnostic"("p_employee_id" "uuid", "p_channel" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_claimed boolean;
  v_state text;
  v_result jsonb;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required'
      USING ERRCODE = '42501';
  END IF;

  IF p_employee_id IS NULL
     OR p_request_id IS NULL
     OR p_channel NOT IN ('bell', 'web_push', 'native_push', 'email') THEN
    RAISE EXCEPTION 'invalid notification diagnostic claim'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee_row
    WHERE employee_row.id = p_employee_id
      AND employee_row.role::text = 'admin'
      AND employee_row.is_active IS TRUE
      AND employee_row.is_external IS FALSE
  ) THEN
    RAISE EXCEPTION 'notification diagnostic owner required'
      USING ERRCODE = '42501';
  END IF;

  WITH expired_claims AS (
    SELECT
      existing_claim.employee_id,
      existing_claim.channel,
      existing_claim.request_id
    FROM public.notification_delivery_diagnostic_claims existing_claim
    WHERE existing_claim.claimed_at < now() - interval '90 days'
    ORDER BY existing_claim.claimed_at
    LIMIT 1000
  )
  DELETE FROM public.notification_delivery_diagnostic_claims existing_claim
  USING expired_claims
  WHERE existing_claim.employee_id = expired_claims.employee_id
    AND existing_claim.channel = expired_claims.channel
    AND existing_claim.request_id = expired_claims.request_id;

  INSERT INTO public.notification_delivery_diagnostic_claims (
    employee_id,
    channel,
    request_id
  )
  VALUES (
    p_employee_id,
    p_channel,
    p_request_id
  )
  ON CONFLICT (employee_id, channel, request_id) DO NOTHING
  RETURNING true INTO v_claimed;

  IF COALESCE(v_claimed, false) THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'state', 'pending'
    );
  END IF;

  SELECT existing_claim.state, existing_claim.result
  INTO v_state, v_result
  FROM public.notification_delivery_diagnostic_claims existing_claim
  WHERE existing_claim.employee_id = p_employee_id
    AND existing_claim.channel = p_channel
    AND existing_claim.request_id = p_request_id;

  RETURN jsonb_build_object(
    'claimed', false,
    'state', COALESCE(v_state, 'pending'),
    'result', v_result
  );
END;
$$;


ALTER FUNCTION "public"."claim_notification_delivery_diagnostic"("p_employee_id" "uuid", "p_channel" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_qbo_event"("p_id" "text", "p_entity" "text", "p_operation" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_claimed boolean;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.qbo_events AS existing (id, entity, operation, status)
  VALUES (p_id, p_entity, p_operation, 'processing')
  ON CONFLICT (id) DO UPDATE
  SET entity = EXCLUDED.entity,
      operation = EXCLUDED.operation,
      status = 'processing',
      error = NULL,
      processed_at = NULL
  WHERE existing.status = 'retry'
  RETURNING true INTO v_claimed;

  RETURN COALESCE(v_claimed, false);
END;
$$;


ALTER FUNCTION "public"."claim_qbo_event"("p_id" "text", "p_entity" "text", "p_operation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_qbo_receipt_event"("p_id" "text", "p_entity" "text", "p_operation" "text", "p_realm_id" "text", "p_entity_id" "text", "p_provider_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_inserted integer;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_id), '') IS NULL
     OR p_entity <> 'Payment'
     OR NULLIF(btrim(p_operation), '') IS NULL
     OR NULLIF(btrim(p_realm_id), '') IS NULL
     OR NULLIF(btrim(p_entity_id), '') IS NULL THEN
    RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.qbo_events (
    id, entity, operation, status, qbo_realm_id, qbo_entity_id, provider_updated_at
  ) VALUES (
    btrim(p_id), 'Payment', btrim(p_operation), 'processing',
    btrim(p_realm_id), btrim(p_entity_id), p_provider_updated_at
  )
  ON CONFLICT (id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted = 1;
END;
$$;


ALTER FUNCTION "public"."claim_qbo_receipt_event"("p_id" "text", "p_entity" "text", "p_operation" "text", "p_realm_id" "text", "p_entity_id" "text", "p_provider_updated_at" timestamp with time zone) OWNER TO "postgres";


