CREATE OR REPLACE FUNCTION "public"."clock_appointment_action"("p_appointment_id" "uuid", "p_employee_id" "uuid", "p_action" "text", "p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_accuracy" numeric DEFAULT NULL::numeric) RETURNS SETOF "public"."job_time_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_entry        job_time_entries%ROWTYPE;
  v_now          TIMESTAMPTZ := NOW();
  v_job_id       UUID;
  v_paused_min   NUMERIC;
  v_total_ms     NUMERIC;
  v_hours        NUMERIC;
  v_stale        RECORD;
  v_stale_hours  NUMERIC;
BEGIN
  SELECT job_id INTO v_job_id FROM appointments WHERE id = p_appointment_id;

  SELECT * INTO v_entry
  FROM job_time_entries
  WHERE appointment_id = p_appointment_id AND employee_id = p_employee_id
  ORDER BY (clock_out IS NULL) DESC, created_at DESC
  LIMIT 1;

  IF p_action = 'omw' THEN
    IF EXISTS (
      SELECT 1 FROM feature_flags
      WHERE key = 'clock_enforce_explicit_clockout' AND enabled = true
    ) AND EXISTS (
      SELECT 1 FROM job_time_entries
      WHERE employee_id = p_employee_id
        AND clock_out IS NULL AND travel_start IS NOT NULL
        AND appointment_id IS DISTINCT FROM p_appointment_id
    ) THEN
      RAISE EXCEPTION 'OPEN_ENTRY_EXISTS' USING ERRCODE = 'P0001';
    END IF;

    FOR v_stale IN
      SELECT id, job_id, clock_in, travel_start, total_paused_minutes, appointment_id
      FROM job_time_entries
      WHERE employee_id = p_employee_id
        AND clock_out IS NULL AND travel_start IS NOT NULL
        AND id != COALESCE(v_entry.id, '00000000-0000-0000-0000-000000000000')
    LOOP
      IF v_stale.clock_in IS NOT NULL THEN
        v_stale_hours := EXTRACT(EPOCH FROM (v_now - v_stale.clock_in)) / 3600
                         - COALESCE(v_stale.total_paused_minutes, 0) / 60;
        UPDATE job_time_entries
        SET clock_out = v_now, on_site_end = COALESCE(on_site_end, v_now),
            hours = LEAST(24, GREATEST(0, v_stale_hours))
        WHERE id = v_stale.id;
      ELSE
        v_stale_hours := 0;
        UPDATE job_time_entries
        SET clock_out = v_now, hours = 0,
            travel_minutes = COALESCE(travel_minutes,
              LEAST(1440, GREATEST(0, ROUND(EXTRACT(EPOCH FROM (v_now - v_stale.travel_start)) / 60.0, 1))))
        WHERE id = v_stale.id;
      END IF;

      IF v_stale_hours > 24 THEN
        INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, job_id, payload)
        VALUES ('time_entry.auto_closed_stale','job_time_entry',v_stale.id,p_employee_id,v_stale.job_id,
          jsonb_build_object('previous_appointment_id', v_stale.appointment_id,'new_appointment_id', p_appointment_id,
            'clock_in', v_stale.clock_in,'auto_closed_at', v_now,'raw_hours', ROUND(v_stale_hours::numeric, 2),
            'capped_hours', 24,'reason','Tech tapped On My Way on a new appointment >24h after previous clock-in without hitting Finish'));
      END IF;
    END LOOP;

    IF v_entry.id IS NULL OR v_entry.clock_out IS NOT NULL THEN
      INSERT INTO job_time_entries (
        job_id, employee_id, appointment_id, work_date, hours, work_type, travel_start, entered_by, description, travel_start_lat, travel_start_lng
      ) VALUES (
        v_job_id, p_employee_id, p_appointment_id, (v_now AT TIME ZONE 'America/Denver')::DATE, 0, 'field', v_now, p_employee_id,
        (SELECT COALESCE(title, 'Appointment') FROM appointments WHERE id = p_appointment_id) || ' — en route', p_lat, p_lng
      ) RETURNING * INTO v_entry;
    ELSE
      UPDATE job_time_entries
      SET travel_start = v_now, travel_start_lat = COALESCE(p_lat, travel_start_lat), travel_start_lng = COALESCE(p_lng, travel_start_lng)
      WHERE id = v_entry.id RETURNING * INTO v_entry;
    END IF;

    UPDATE appointments SET status = 'en_route' WHERE id = p_appointment_id;

  ELSIF p_action = 'start' THEN
    UPDATE job_time_entries
    SET clock_in = v_now, clock_in_lat = COALESCE(p_lat, clock_in_lat), clock_in_lng = COALESCE(p_lng, clock_in_lng),
        travel_minutes = CASE WHEN v_entry.travel_start IS NOT NULL
          THEN ROUND(EXTRACT(EPOCH FROM (v_now - v_entry.travel_start)) / 60.0, 1) ELSE NULL END
    WHERE id = v_entry.id RETURNING * INTO v_entry;
    UPDATE appointments SET status = 'in_progress' WHERE id = p_appointment_id;

  ELSIF p_action = 'pause' THEN
    UPDATE job_time_entries SET paused_at = v_now WHERE id = v_entry.id RETURNING * INTO v_entry;
    UPDATE appointments SET status = 'paused' WHERE id = p_appointment_id;

  ELSIF p_action = 'resume' THEN
    v_paused_min := COALESCE(v_entry.total_paused_minutes, 0) + EXTRACT(EPOCH FROM (v_now - v_entry.paused_at)) / 60;
    UPDATE job_time_entries SET paused_at = NULL, total_paused_minutes = ROUND(v_paused_min::NUMERIC, 2)
    WHERE id = v_entry.id RETURNING * INTO v_entry;
    UPDATE appointments SET status = 'in_progress' WHERE id = p_appointment_id;

  ELSIF p_action = 'finish' THEN
    v_paused_min := COALESCE(v_entry.total_paused_minutes, 0);
    IF v_entry.paused_at IS NOT NULL THEN
      v_paused_min := v_paused_min + EXTRACT(EPOCH FROM (v_now - v_entry.paused_at)) / 60;
    END IF;
    v_total_ms := EXTRACT(EPOCH FROM (v_now - v_entry.clock_in)) * 1000 - v_paused_min * 60000;
    v_hours := LEAST(24, GREATEST(0, ROUND((v_total_ms / 3600000)::NUMERIC, 2)));
    UPDATE job_time_entries
    SET clock_out = v_now, on_site_end = v_now, hours = v_hours, paused_at = NULL, total_paused_minutes = ROUND(v_paused_min::NUMERIC, 2)
    WHERE id = v_entry.id RETURNING * INTO v_entry;
    UPDATE appointments SET status = 'completed' WHERE id = p_appointment_id;
  END IF;

  RETURN NEXT v_entry;
END;
$$;


ALTER FUNCTION "public"."clock_appointment_action"("p_appointment_id" "uuid", "p_employee_id" "uuid", "p_action" "text", "p_lat" numeric, "p_lng" numeric, "p_accuracy" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clock_finish_entry"("p_entry_id" "uuid", "p_employee_id" "uuid") RETURNS "public"."job_time_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_e job_time_entries%ROWTYPE; v_now timestamptz := now(); v_paused numeric; v_hours numeric;
begin
  select * into v_e from job_time_entries where id=p_entry_id and employee_id=p_employee_id and clock_out is null;
  if v_e.id is null then raise exception 'ENTRY_NOT_FOUND_OR_CLOSED' using errcode='P0001'; end if;
  if v_e.clock_in is not null then
    v_paused := coalesce(v_e.total_paused_minutes,0);
    if v_e.paused_at is not null then v_paused := v_paused + greatest(0, extract(epoch from (v_now - v_e.paused_at))/60); end if;
    v_hours := least(24, greatest(0, extract(epoch from (v_now - v_e.clock_in))/3600 - v_paused/60));
    update job_time_entries set clock_out=v_now, on_site_end=coalesce(on_site_end,v_now), hours=v_hours,
      paused_at=null, total_paused_minutes=round(v_paused::numeric,2), updated_at=now() where id=v_e.id returning * into v_e;
  else
    update job_time_entries set clock_out=v_now, hours=0,
      travel_minutes=coalesce(travel_minutes, least(1440, greatest(0, round(extract(epoch from (v_now - v_e.travel_start))/60.0,1)))),
      updated_at=now() where id=v_e.id returning * into v_e;
  end if;
  if v_e.appointment_id is not null then update appointments set status='completed' where id=v_e.appointment_id; end if;
  return v_e;
end; $$;


ALTER FUNCTION "public"."clock_finish_entry"("p_entry_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clock_omw_precheck"("p_appointment_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_open      job_time_entries%ROWTYPE;
  v_enforce   boolean := false;
  v_title     text;
  v_job_number text;
  v_insured   text;
  v_status    text;
  v_open_json jsonb;
begin
  select coalesce(enabled, false) into v_enforce
  from feature_flags where key = 'clock_enforce_explicit_clockout';
  v_enforce := coalesce(v_enforce, false);

  select * into v_open
  from job_time_entries
  where employee_id = p_employee_id
    and clock_out is null
    and travel_start is not null
    and appointment_id is distinct from p_appointment_id
  order by created_at desc
  limit 1;

  if v_open.id is null then
    return jsonb_build_object('requires_confirmation', false, 'enforce_explicit', false, 'open_entry', null);
  end if;

  select a.title, j.job_number, j.insured_name
    into v_title, v_job_number, v_insured
  from appointments a
  left join jobs j on j.id = a.job_id
  where a.id = v_open.appointment_id;

  v_status := case
    when v_open.paused_at is not null then 'paused'
    when v_open.clock_in  is not null then 'on_site'
    else 'omw'
  end;

  v_open_json := jsonb_build_object(
    'entry_id', v_open.id, 'appointment_id', v_open.appointment_id, 'title', v_title,
    'job_id', v_open.job_id, 'job_number', v_job_number, 'insured_name', v_insured,
    'travel_start', v_open.travel_start, 'clock_in', v_open.clock_in, 'status', v_status,
    'elapsed_minutes', round(extract(epoch from (now() - v_open.travel_start)) / 60.0)
  );

  return jsonb_build_object('requires_confirmation', not v_enforce, 'enforce_explicit', v_enforce, 'open_entry', v_open_json);
end;
$$;


ALTER FUNCTION "public"."clock_omw_precheck"("p_appointment_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_open_clocks_on_appt_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  update job_time_entries
    set clock_out = now(),
        on_site_end = case when clock_in is not null then coalesce(on_site_end, now()) else on_site_end end,
        hours = case when clock_in is not null then least(24, greatest(0, extract(epoch from (now()-clock_in))/3600 - coalesce(total_paused_minutes,0)/60)) else 0 end,
        travel_minutes = case when clock_in is null then coalesce(travel_minutes, least(1440, greatest(0, round(extract(epoch from (now()-travel_start))/60.0,1)))) else travel_minutes end,
        paused_at = null,
        notes = coalesce(notes,'') || ' [auto-closed: appointment deleted]',
        updated_at = now()
  where appointment_id = OLD.id and clock_out is null and travel_start is not null;
  return OLD;
end; $$;


ALTER FUNCTION "public"."close_open_clocks_on_appt_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_notification_delivery_diagnostic"("p_employee_id" "uuid", "p_channel" "text", "p_request_id" "uuid", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required'
      USING ERRCODE = '42501';
  END IF;

  IF p_employee_id IS NULL
     OR p_request_id IS NULL
     OR p_channel NOT IN ('bell', 'web_push', 'native_push', 'email')
     OR p_result IS NULL
     OR jsonb_typeof(p_result) <> 'object'
     OR NOT (p_result ?& ARRAY[
       'channel',
       'ok',
       'sent',
       'attempted',
       'pruned'
     ]::text[])
     OR (p_result - ARRAY[
       'channel',
       'ok',
       'sent',
       'attempted',
       'pruned',
       'reason'
     ]::text[]) <> '{}'::jsonb
     OR p_result->>'channel' IS DISTINCT FROM p_channel
     OR jsonb_typeof(p_result->'ok') <> 'boolean'
     OR jsonb_typeof(p_result->'sent') <> 'number'
     OR jsonb_typeof(p_result->'attempted') <> 'number'
     OR jsonb_typeof(p_result->'pruned') <> 'number'
     OR COALESCE((p_result->>'sent')::numeric, -1) < 0
     OR COALESCE((p_result->>'attempted')::numeric, -1) < 0
     OR COALESCE((p_result->>'pruned')::numeric, -1) < 0
     OR (
       p_result ? 'reason'
       AND (
         jsonb_typeof(p_result->'reason') <> 'string'
         OR length(p_result->>'reason') NOT BETWEEN 1 AND 80
       )
     ) THEN
    RAISE EXCEPTION 'invalid notification diagnostic result'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.notification_delivery_diagnostic_claims existing_claim
  SET
    state = 'complete',
    result = p_result,
    completed_at = now()
  WHERE existing_claim.employee_id = p_employee_id
    AND existing_claim.channel = p_channel
    AND existing_claim.request_id = p_request_id
    AND existing_claim.state = 'pending'
  RETURNING existing_claim.result INTO v_result;

  IF v_result IS NULL THEN
    SELECT existing_claim.result
    INTO v_result
    FROM public.notification_delivery_diagnostic_claims existing_claim
    WHERE existing_claim.employee_id = p_employee_id
      AND existing_claim.channel = p_channel
      AND existing_claim.request_id = p_request_id
      AND existing_claim.state = 'complete';
  END IF;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'notification diagnostic claim missing'
      USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'completed', true,
    'result', v_result
  );
END;
$$;


ALTER FUNCTION "public"."complete_notification_delivery_diagnostic"("p_employee_id" "uuid", "p_channel" "text", "p_request_id" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sign_request"("p_token" "uuid", "p_signer_name" "text", "p_signer_ip" "text", "p_signed_file_path" "text", "p_consent_terms" boolean DEFAULT NULL::boolean, "p_consent_commitment" boolean DEFAULT NULL::boolean, "p_consent_esign" boolean DEFAULT NULL::boolean, "p_consent_authority" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_req          sign_requests;
  v_doc_id       uuid;
  v_doc_label    text;
  v_has_consents boolean;
  v_payload      jsonb;
BEGIN
  v_has_consents := p_consent_terms IS NOT NULL
                 OR p_consent_commitment IS NOT NULL
                 OR p_consent_esign IS NOT NULL
                 OR p_consent_authority IS NOT NULL;

  UPDATE sign_requests SET
    status              = 'signed',
    signer_name         = p_signer_name,
    signer_ip           = p_signer_ip,
    signed_file_path    = p_signed_file_path,
    signed_at           = now(),
    consent_terms       = COALESCE(p_consent_terms, consent_terms),
    consent_commitment  = COALESCE(p_consent_commitment, consent_commitment),
    consent_esign       = COALESCE(p_consent_esign, consent_esign),
    consent_authority   = COALESCE(p_consent_authority, consent_authority),
    consents_signed_at  = CASE WHEN v_has_consents THEN now() ELSE consents_signed_at END,
    updated_at          = now()
  WHERE token = p_token AND status = 'pending'
  RETURNING * INTO v_req;

  IF v_req.id IS NULL THEN
    RETURN jsonb_build_object('error', 'Not found or already signed');
  END IF;

  v_doc_label := CASE v_req.doc_type
    WHEN 'coc'              THEN 'Certificate of Completion'
    WHEN 'work_auth'        THEN 'Work Authorization'
    WHEN 'direction_pay'    THEN 'Direction of Pay'
    WHEN 'change_order'     THEN 'Change Order'
    WHEN 'recon_agreement'  THEN 'Reconstruction Agreement'
    ELSE 'Signed Document'
  END;

  INSERT INTO job_documents (
    job_id, name, file_path, mime_type,
    category, sign_request_id, esign_status,
    created_at, updated_at
  ) VALUES (
    v_req.job_id,
    v_doc_label || ' – Signed.pdf',
    p_signed_file_path,
    'application/pdf',
    'contract',
    v_req.id,
    'signed',
    now(), now()
  )
  RETURNING id INTO v_doc_id;

  -- Audit event — high-value legal act, captured for investigation/defense
  v_payload := jsonb_build_object(
    'doc_type',         v_req.doc_type,
    'doc_label',        v_doc_label,
    'signer_name',      v_req.signer_name,
    'signer_email',     v_req.signer_email,
    'signer_ip',        v_req.signer_ip,
    'signed_at',        v_req.signed_at,
    'signed_file_path', v_req.signed_file_path,
    'job_document_id',  v_doc_id,
    'divisions',        to_jsonb(COALESCE(v_req.divisions, '{}'::text[])),
    'contact_id',       v_req.contact_id
  );
  IF v_req.doc_type = 'recon_agreement' THEN
    v_payload := v_payload || jsonb_build_object(
      'consents', jsonb_build_object(
        'terms',      v_req.consent_terms,
        'commitment', v_req.consent_commitment,
        'esign',      v_req.consent_esign,
        'authority',  v_req.consent_authority
      ),
      'consents_signed_at', v_req.consents_signed_at
    );
  END IF;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, job_id, payload)
  VALUES ('esign.signed', 'sign_request', v_req.id, NULL, v_req.job_id, v_payload);

  RETURN jsonb_build_object(
    'success',          true,
    'sign_request_id',  v_req.id,
    'job_document_id',  v_doc_id,
    'job_id',           v_req.job_id,
    'doc_type',         v_req.doc_type
  );
END;
$$;


ALTER FUNCTION "public"."complete_sign_request"("p_token" "uuid", "p_signer_name" "text", "p_signer_ip" "text", "p_signed_file_path" "text", "p_consent_terms" boolean, "p_consent_commitment" boolean, "p_consent_esign" boolean, "p_consent_authority" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sign_request_with_private_storage"("p_token" "uuid", "p_signer_name" "text", "p_signer_ip" "text", "p_signed_file_path" "text", "p_consent_terms" boolean DEFAULT NULL::boolean, "p_consent_commitment" boolean DEFAULT NULL::boolean, "p_consent_esign" boolean DEFAULT NULL::boolean, "p_consent_authority" boolean DEFAULT NULL::boolean, "p_sms_disclosure_version" "text" DEFAULT NULL::"text", "p_sms_disclosure_sha256" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result jsonb;
  v_updated integer;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'NOT_AUTHORIZED';
  END IF;

  v_result := public.complete_sign_request_with_work_authorization_sms_consent(
    p_token,
    p_signer_name,
    p_signer_ip,
    p_signed_file_path,
    p_consent_terms,
    p_consent_commitment,
    p_consent_esign,
    p_consent_authority,
    p_sms_disclosure_version,
    p_sms_disclosure_sha256
  );

  IF v_result IS NULL OR v_result ? 'error' THEN
    RETURN v_result;
  END IF;

  UPDATE public.job_documents
  SET storage_bucket = 'job-documents-private'
  WHERE id = (v_result ->> 'job_document_id')::uuid;
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated <> 1 THEN
    RAISE EXCEPTION 'SIGNED_DOCUMENT_BUCKET_ASSIGNMENT_FAILED';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."complete_sign_request_with_private_storage"("p_token" "uuid", "p_signer_name" "text", "p_signer_ip" "text", "p_signed_file_path" "text", "p_consent_terms" boolean, "p_consent_commitment" boolean, "p_consent_esign" boolean, "p_consent_authority" boolean, "p_sms_disclosure_version" "text", "p_sms_disclosure_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sign_request_with_work_authorization_sms_consent"("p_token" "uuid", "p_signer_name" "text", "p_signer_ip" "text", "p_signed_file_path" "text", "p_consent_terms" boolean DEFAULT NULL::boolean, "p_consent_commitment" boolean DEFAULT NULL::boolean, "p_consent_esign" boolean DEFAULT NULL::boolean, "p_consent_authority" boolean DEFAULT NULL::boolean, "p_sms_disclosure_version" "text" DEFAULT NULL::"text", "p_sms_disclosure_sha256" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_result jsonb;
  v_req public.sign_requests%ROWTYPE;
  v_contact public.contacts%ROWTYPE;
  v_phone_digits text;
  v_phone_key text;
BEGIN
  IF current_user <> 'service_role' THEN
    RETURN jsonb_build_object(
      'error', 'WORK_AUTH_SMS_CONSENT_NOT_AUTHORIZED'
    );
  END IF;

  -- The existing function owns the legal signature, job document and audit
  -- event. Calling it inside this wrapper keeps that deployed contract intact
  -- and makes the following evidence insert part of the same transaction.
  v_result := public.complete_sign_request(
    p_token,
    p_signer_name,
    p_signer_ip,
    p_signed_file_path,
    p_consent_terms,
    p_consent_commitment,
    p_consent_esign,
    p_consent_authority
  );

  IF v_result IS NULL OR v_result ? 'error' THEN
    RETURN v_result;
  END IF;

  SELECT *
  INTO v_req
  FROM public.sign_requests
  WHERE id = (v_result ->> 'sign_request_id')::uuid
  FOR SHARE;

  IF v_req.id IS NULL OR v_req.doc_type <> 'work_auth' THEN
    RETURN v_result;
  END IF;

  IF p_sms_disclosure_version IS DISTINCT FROM 'upr_work_auth_sms_v1'
     OR p_sms_disclosure_sha256 IS DISTINCT FROM
       '22b2a37dc4094f683da6c0fe1d4955da989733a3a799307129b9fa83cae1265e' THEN
    RETURN v_result || jsonb_build_object(
      'sms_consent_recorded', false,
      'sms_consent_reason', 'disclosure_not_approved'
    );
  END IF;

  IF v_req.status <> 'signed'
     OR v_req.contact_id IS NULL
     OR v_req.job_id IS NULL
     OR v_req.signed_at IS NULL
     OR NULLIF(btrim(COALESCE(v_req.signer_ip, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(v_req.signed_file_path, '')), '') IS NULL THEN
    RETURN v_result || jsonb_build_object(
      'sms_consent_recorded', false,
      'sms_consent_reason', 'sign_request_not_eligible'
    );
  END IF;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = v_req.contact_id
  FOR SHARE;

  v_phone_digits := regexp_replace(
    COALESCE(v_contact.phone, ''),
    '[^0-9]',
    '',
    'g'
  );
  IF length(v_phone_digits) = 10 THEN
    v_phone_key := v_phone_digits;
  ELSIF length(v_phone_digits) = 11 AND left(v_phone_digits, 1) = '1' THEN
    v_phone_key := right(v_phone_digits, 10);
  END IF;

  IF v_contact.id IS NULL OR v_phone_key IS NULL THEN
    RETURN v_result || jsonb_build_object(
      'sms_consent_recorded', false,
      'sms_consent_reason', 'contact_has_no_phone'
    );
  END IF;

  INSERT INTO public.work_authorization_sms_consents (
    sign_request_id,
    contact_id,
    job_id,
    phone,
    signer_ip,
    disclosure_version,
    disclosure_sha256,
    signed_file_path,
    signed_at
  ) VALUES (
    v_req.id,
    v_req.contact_id,
    v_req.job_id,
    v_contact.phone,
    v_req.signer_ip,
    p_sms_disclosure_version,
    p_sms_disclosure_sha256,
    v_req.signed_file_path,
    v_req.signed_at
  )
  ON CONFLICT (sign_request_id) DO NOTHING;

  INSERT INTO public.sms_consent_log (
    contact_id,
    phone,
    event_type,
    source,
    performed_by,
    details
  ) VALUES (
    v_req.contact_id,
    v_contact.phone,
    'service_consent_recorded',
    'upr_signed_work_authorization',
    NULL,
    jsonb_build_object(
      'consent_scope', 'service_related_customer_project_messages',
      'disclosure_version', p_sms_disclosure_version,
      'sign_request_id', v_req.id
    )::text
  );

  RETURN v_result || jsonb_build_object(
    'sms_consent_recorded', true,
    'sms_consent_reason', 'upr_signed_work_authorization'
  );
END;
$$;


ALTER FUNCTION "public"."complete_sign_request_with_work_authorization_sms_consent"("p_token" "uuid", "p_signer_name" "text", "p_signer_ip" "text", "p_signed_file_path" "text", "p_consent_terms" boolean, "p_consent_commitment" boolean, "p_consent_esign" boolean, "p_consent_authority" boolean, "p_sms_disclosure_version" "text", "p_sms_disclosure_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_advance_w9_year"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_year integer := EXTRACT(YEAR FROM (now() AT TIME ZONE 'America/Denver'))::integer; v_count integer;
BEGIN
  UPDATE public.contractor_compliance_profiles SET required_w9_year=v_year,updated_at=now() WHERE is_active IS TRUE AND required_w9_year<v_year;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END; $$;


ALTER FUNCTION "public"."contractor_compliance_advance_w9_year"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_append_activity"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_activity_type" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_profile uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  SELECT id INTO v_profile FROM public.contractor_compliance_profiles WHERE contact_id=p_contractor_id;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: contractor profile not found' USING errcode='P0002'; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,actor_employee_id,event_type,note) VALUES(v_profile,p_actor_employee_id,p_activity_type,NULLIF(btrim(p_note),''));
END; $$;


ALTER FUNCTION "public"."contractor_compliance_append_activity"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_activity_type" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_authorize_document_file"("p_actor_employee_id" "uuid", "p_document_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: W-9 file access requires manager role' USING errcode='42501'; END IF;
  RETURN (SELECT jsonb_build_object('storage_bucket',d.storage_bucket,'storage_object_path',d.storage_object_path,'original_filename',d.original_filename) FROM public.contractor_compliance_documents d WHERE d.id=p_document_id);
END; $$;


ALTER FUNCTION "public"."contractor_compliance_authorize_document_file"("p_actor_employee_id" "uuid", "p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_claim_delivery"("p_request_id" "uuid", "p_stage" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_delivery public.contractor_compliance_request_deliveries; v_contact uuid; v_types text[];
BEGIN
  IF NULLIF(btrim(p_stage),'') IS NULL OR length(p_stage)>80 THEN RETURN NULL; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.contractor_compliance_requests r JOIN public.contractor_compliance_profiles p ON p.id=r.profile_id
    WHERE r.id=p_request_id AND p.is_active AND p.requests_paused_at IS NULL AND r.expires_at>now() AND r.revoked_at IS NULL AND r.paused_at IS NULL AND r.completed_at IS NULL
      AND EXISTS (
        SELECT 1 FROM unnest(r.requested_document_types) typ
        WHERE
          (typ='w9' AND NOT EXISTS (
            SELECT 1 FROM public.contractor_compliance_documents d
            WHERE d.profile_id=p.id AND d.document_type='w9'
              AND d.review_state IN ('accepted','superseded') AND d.tax_year=p.required_w9_year
          ))
          OR (typ='general_liability' AND COALESCE(public.contractor_compliance_continuous_coverage_end(
                p.id,ARRAY['general_liability'],(now() AT TIME ZONE 'America/Denver')::date
              ),'0001-01-01'::date)
              <= COALESCE(NULLIF(substring(r.request_identity FROM '([0-9]{4}-[0-9]{2}-[0-9]{2})$'), '')::date,(now() AT TIME ZONE 'America/Denver')::date))
          OR (typ IN ('workers_comp','workers_comp_waiver') AND COALESCE(public.contractor_compliance_continuous_coverage_end(
                p.id,ARRAY['workers_comp','workers_comp_waiver'],(now() AT TIME ZONE 'America/Denver')::date
              ),'0001-01-01'::date)
              <= COALESCE(NULLIF(substring(r.request_identity FROM '([0-9]{4}-[0-9]{2}-[0-9]{2})$'), '')::date,(now() AT TIME ZONE 'America/Denver')::date))
      )
  ) THEN RETURN NULL; END IF;
  INSERT INTO public.contractor_compliance_request_deliveries(request_id,stage_key,idempotency_key,status) VALUES(p_request_id,p_stage,'contractor-compliance:' || p_request_id::text || ':' || p_stage,'claimed') ON CONFLICT(request_id,stage_key) DO NOTHING RETURNING * INTO v_delivery;
  IF v_delivery.id IS NULL THEN RETURN NULL; END IF;
  SELECT p.contact_id,r.requested_document_types INTO v_contact,v_types
  FROM public.contractor_compliance_requests r
  JOIN public.contractor_compliance_profiles p ON p.id=r.profile_id
  WHERE r.id=p_request_id;
  RETURN jsonb_build_object(
    'delivery_id',v_delivery.id,'contractor_id',v_contact,'contact_id',v_contact,
    'document_types',v_types,'provider_idempotency_key',v_delivery.idempotency_key
  );
END; $_$;


ALTER FUNCTION "public"."contractor_compliance_claim_delivery"("p_request_id" "uuid", "p_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_continuous_coverage_end"("p_profile_id" "uuid", "p_types" "text"[], "p_start" "date") RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH coverage AS (
    SELECT range_agg(daterange(d.coverage_start_date,d.coverage_end_date,'[]')) AS intervals
    FROM public.contractor_compliance_documents d
    WHERE d.profile_id=p_profile_id
      AND d.document_type=ANY(p_types)
      AND d.review_state IN ('accepted','superseded')
      AND d.coverage_start_date IS NOT NULL
      AND d.coverage_end_date IS NOT NULL
  )
  SELECT upper(interval_value)-1
  FROM coverage
  CROSS JOIN LATERAL unnest(coverage.intervals) AS ranges(interval_value)
  WHERE interval_value @> p_start
  ORDER BY upper(interval_value) DESC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."contractor_compliance_continuous_coverage_end"("p_profile_id" "uuid", "p_types" "text"[], "p_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_create_audit_period"("p_name" "text", "p_start_date" "date", "p_end_date" "date", "p_inclusion_basis" "text" DEFAULT 'current_active_profiles'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_id uuid;
BEGIN
  SELECT e.id INTO v_actor
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid()
    AND e.is_active
    AND NOT e.is_external
    AND e.role::text IN ('admin', 'office');
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor audit manager required' USING errcode = '42501';
  END IF;
  IF length(btrim(p_name)) NOT BETWEEN 3 AND 120
     OR p_end_date < p_start_date
     OR p_end_date - p_start_date > 731
     OR p_inclusion_basis NOT IN ('current_active_profiles', 'manual_external') THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: audit name, dates, or basis' USING errcode = '22023';
  END IF;
  INSERT INTO public.contractor_compliance_audit_periods (
    name, start_date, end_date, status, inclusion_basis, created_by
  ) VALUES (
    btrim(p_name), p_start_date, p_end_date, 'draft', p_inclusion_basis, v_actor
  )
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'status', 'draft');
END;
$$;


ALTER FUNCTION "public"."contractor_compliance_create_audit_period"("p_name" "text", "p_start_date" "date", "p_end_date" "date", "p_inclusion_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_create_request"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_document_types" "text"[], "p_recipient_email" "text" DEFAULT NULL::"text", "p_expires_in_days" integer DEFAULT 30, "p_source" "text" DEFAULT 'manual'::"text", "p_token_digest" "text" DEFAULT NULL::"text", "p_request_identity" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_profile uuid; v_id uuid; v_identity text; v_contact_email text;
BEGIN
  IF NOT ((p_actor_employee_id IS NULL AND p_source='automated_reminder' AND current_setting('request.jwt.claim.role',true)='service_role') OR EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office'))) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  IF p_expires_in_days NOT BETWEEN 1 AND 90 OR p_token_digest !~ '^[0-9a-f]{64}$'
     OR NULLIF(btrim(p_request_identity),'') IS NULL
     OR cardinality(p_document_types)<1
     OR NOT p_document_types <@ ARRAY['w9','workers_comp','workers_comp_waiver','general_liability']::text[] THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: request identity, document types, expiry, or digest' USING errcode='22023';
  END IF;
  SELECT p.id,c.email INTO v_profile,v_contact_email
  FROM public.contractor_compliance_profiles p
  JOIN public.contacts c ON c.id=p.contact_id AND c.role='subcontractor'
  WHERE p.contact_id=p_contractor_id AND p.is_active IS TRUE;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: active contractor profile not found' USING errcode='P0002'; END IF;
  v_identity := btrim(p_request_identity);
  INSERT INTO public.contractor_compliance_requests(profile_id,request_identity,requested_document_types,recipient_email,token_digest,expires_at,created_by,source)
  VALUES(v_profile,v_identity,ARRAY(SELECT DISTINCT typ FROM unnest(p_document_types) typ ORDER BY typ),lower(COALESCE(NULLIF(btrim(p_recipient_email),''),NULLIF(btrim(v_contact_email),''))),lower(p_token_digest),now()+make_interval(days=>p_expires_in_days),p_actor_employee_id,p_source)
  ON CONFLICT(request_identity) DO UPDATE SET updated_at=public.contractor_compliance_requests.updated_at
  WHERE public.contractor_compliance_requests.token_digest=EXCLUDED.token_digest AND public.contractor_compliance_requests.profile_id=EXCLUDED.profile_id AND public.contractor_compliance_requests.requested_document_types=EXCLUDED.requested_document_types
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: request identity mismatch' USING errcode='23505'; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,request_id,actor_employee_id,event_type)
  SELECT v_profile,v_id,p_actor_employee_id,'request_created'
  WHERE NOT EXISTS (SELECT 1 FROM public.contractor_compliance_activity a WHERE a.request_id=v_id AND a.event_type='request_created');
  IF p_source='automated_reminder' AND v_identity LIKE '%:overdue_week_%' THEN
    INSERT INTO public.contractor_compliance_activity(profile_id,request_id,event_type,note)
    SELECT v_profile,v_id,'overdue_escalated','Overdue compliance follow-up is assigned to the internal owner.'
    WHERE NOT EXISTS (SELECT 1 FROM public.contractor_compliance_activity a WHERE a.request_id=v_id AND a.event_type='overdue_escalated');
  END IF;
  RETURN jsonb_build_object('request_id',v_id,'expires_at',now()+make_interval(days=>p_expires_in_days));
END; $_$;


ALTER FUNCTION "public"."contractor_compliance_create_request"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_document_types" "text"[], "p_recipient_email" "text", "p_expires_in_days" integer, "p_source" "text", "p_token_digest" "text", "p_request_identity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_finish_delivery"("p_delivery_id" "uuid", "p_outcome" "text", "p_provider_message_id" "text" DEFAULT NULL::"text", "p_skip_reason" "text" DEFAULT NULL::"text", "p_ambiguous" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_request uuid;
BEGIN
  UPDATE public.contractor_compliance_request_deliveries
  SET status=CASE WHEN p_ambiguous THEN 'ambiguous' WHEN p_outcome IN ('sent','suppressed','failed','cancelled') THEN p_outcome ELSE 'failed' END,
      provider_message_id=NULLIF(btrim(p_provider_message_id),''),
      outcome_reason=NULLIF(btrim(p_skip_reason),''),
      sent_at=CASE WHEN p_outcome='sent' AND p_ambiguous IS FALSE THEN now() ELSE sent_at END,
      completed_at=now()
  WHERE id=p_delivery_id AND status='claimed'
  RETURNING request_id INTO v_request;
  IF v_request IS NULL THEN RETURN; END IF;
  IF p_outcome = 'sent' AND p_ambiguous IS FALSE THEN
    UPDATE public.contractor_compliance_requests SET sent_at=now(),updated_at=now() WHERE id=v_request;
    INSERT INTO public.contractor_compliance_activity(profile_id,request_id,event_type)
    SELECT r.profile_id,r.id,'request_email_sent' FROM public.contractor_compliance_requests r WHERE r.id=v_request;
  END IF;
END; $$;


ALTER FUNCTION "public"."contractor_compliance_finish_delivery"("p_delivery_id" "uuid", "p_outcome" "text", "p_provider_message_id" "text", "p_skip_reason" "text", "p_ambiguous" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_has_continuous_coverage"("p_profile_id" "uuid", "p_types" "text"[], "p_start" "date", "p_end" "date") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT COALESCE(range_agg(daterange(d.coverage_start_date,d.coverage_end_date,'[]')) @> daterange(p_start,p_end,'[]'),false)
  FROM public.contractor_compliance_documents d
  WHERE d.profile_id=p_profile_id AND d.document_type=ANY(p_types) AND d.review_state IN ('accepted','superseded')
    AND d.coverage_start_date IS NOT NULL AND d.coverage_end_date IS NOT NULL;
$$;


ALTER FUNCTION "public"."contractor_compliance_has_continuous_coverage"("p_profile_id" "uuid", "p_types" "text"[], "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_ingest_document"("p_actor_employee_id" "uuid" DEFAULT NULL::"uuid", "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_contractor_id" "uuid" DEFAULT NULL::"uuid", "p_document_type" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'internal_upload'::"text", "p_storage_bucket" "text" DEFAULT 'contractor-compliance-private'::"text", "p_storage_path" "text" DEFAULT NULL::"text", "p_original_filename" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_byte_size" bigint DEFAULT NULL::bigint, "p_content_sha256" "text" DEFAULT NULL::"text", "p_effective_date" "date" DEFAULT NULL::"date", "p_expiration_date" "date" DEFAULT NULL::"date", "p_tax_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_profile uuid; v_id uuid; v_version integer;
BEGIN
  SELECT p.id INTO v_profile FROM public.contractor_compliance_profiles p JOIN public.contacts c ON c.id=p.contact_id AND c.role='subcontractor' WHERE p.contact_id=p_contractor_id FOR UPDATE;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: contractor profile not found' USING errcode='P0002'; END IF;
  IF p_request_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.contractor_compliance_requests r
    JOIN public.contractor_compliance_profiles p ON p.id=r.profile_id
    WHERE r.id=p_request_id AND r.profile_id=v_profile
      AND p.is_active IS TRUE AND p.requests_paused_at IS NULL
      AND p_document_type=ANY(r.requested_document_types)
      AND r.expires_at>now() AND r.revoked_at IS NULL AND r.paused_at IS NULL
      AND r.completed_at IS NULL AND r.upload_count<r.max_uploads
  ) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: invalid upload request' USING errcode='42501'; END IF;
  IF p_request_id IS NULL AND NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  SELECT COALESCE(max(d.version_number),0)+1 INTO v_version FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type=p_document_type;
  INSERT INTO public.contractor_compliance_documents(profile_id,document_type,version_number,review_state,coverage_start_date,coverage_end_date,tax_year,received_source,storage_bucket,storage_object_path,original_filename,mime_type,byte_size,sha256_hex)
  VALUES(v_profile,p_document_type,v_version,'pending_review',p_effective_date,p_expiration_date,p_tax_year,p_source,p_storage_bucket,p_storage_path,p_original_filename,p_mime_type,p_byte_size,lower(p_content_sha256)) RETURNING id INTO v_id;
  IF p_request_id IS NOT NULL THEN UPDATE public.contractor_compliance_requests SET upload_count=upload_count+1,updated_at=now() WHERE id=p_request_id; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,document_id,request_id,actor_employee_id,event_type) VALUES(v_profile,v_id,p_request_id,p_actor_employee_id,'document_received');
  RETURN jsonb_build_object('id',v_id,'review_state','pending_review','version_number',v_version);
END; $$;


ALTER FUNCTION "public"."contractor_compliance_ingest_document"("p_actor_employee_id" "uuid", "p_request_id" "uuid", "p_contractor_id" "uuid", "p_document_type" "text", "p_source" "text", "p_storage_bucket" "text", "p_storage_path" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_sha256" "text", "p_effective_date" "date", "p_expiration_date" "date", "p_tax_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_lock_audit_period"("p_audit_period_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  SELECT e.id INTO v_actor
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid()
    AND e.is_active
    AND NOT e.is_external
    AND e.role::text IN ('admin', 'office');
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor audit manager required' USING errcode = '42501';
  END IF;
  UPDATE public.contractor_compliance_audit_periods
  SET status = 'locked', locked_by = v_actor, locked_at = now(), updated_at = now()
  WHERE id = p_audit_period_id AND status = 'open' AND materialized_at IS NOT NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVALID_STATE: materialized open audit required' USING errcode = '55000';
  END IF;
END;
$$;


ALTER FUNCTION "public"."contractor_compliance_lock_audit_period"("p_audit_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_materialize_audit_period"("p_audit_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_period public.contractor_compliance_audit_periods;
  v_count integer;
BEGIN
  SELECT e.id INTO v_actor
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid()
    AND e.is_active
    AND NOT e.is_external
    AND e.role::text IN ('admin', 'office');
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor audit manager required' USING errcode = '42501';
  END IF;
  SELECT * INTO v_period
  FROM public.contractor_compliance_audit_periods
  WHERE id = p_audit_period_id
  FOR UPDATE;
  IF v_period.id IS NULL THEN
    RAISE EXCEPTION 'NOT_FOUND: audit period missing' USING errcode = 'P0002';
  END IF;
  IF v_period.status IN ('locked', 'closed') THEN
    RAISE EXCEPTION 'AUDIT_LOCKED: manifest is immutable' USING errcode = '55000';
  END IF;

  IF v_period.inclusion_basis = 'current_active_profiles' THEN
    DELETE FROM public.contractor_compliance_audit_roster
    WHERE audit_period_id = v_period.id AND inclusion_source = 'current_active_profile';
    INSERT INTO public.contractor_compliance_audit_roster (
      audit_period_id, profile_id, included, inclusion_source,
      active_in_period, paid_in_period, reconciliation_state,
      reconciliation_metadata, captured_at
    )
    SELECT
      v_period.id,
      p.id,
      true,
      'current_active_profile',
      NULL,
      NULL,
      'unknown',
      jsonb_build_object(
        'basis',
        'current active profile at materialization; not proof of activity or payment in the audit period'
      ),
      now()
    FROM public.contractor_compliance_profiles p
    JOIN public.contacts c ON c.id = p.contact_id AND c.role = 'subcontractor'
    WHERE p.is_active;
  END IF;

  DELETE FROM public.contractor_compliance_audit_request_deliveries
  WHERE audit_period_id = v_period.id;
  DELETE FROM public.contractor_compliance_audit_requests
  WHERE audit_period_id = v_period.id;
  DELETE FROM public.contractor_compliance_audit_evidence
  WHERE audit_period_id = v_period.id;

  INSERT INTO public.contractor_compliance_audit_evidence (
    audit_period_id, profile_id, requirement_group, interval_kind,
    interval_start, interval_end, document_id, document_version,
    captured_review_state
  )
  SELECT
    v_period.id,
    r.profile_id,
    CASE
      WHEN d.document_type IN ('workers_comp', 'workers_comp_waiver') THEN 'workers_comp'
      ELSE 'general_liability'
    END,
    'coverage',
    GREATEST(d.coverage_start_date, v_period.start_date),
    LEAST(d.coverage_end_date, v_period.end_date),
    d.id,
    d.version_number,
    d.review_state
  FROM public.contractor_compliance_audit_roster r
  JOIN public.contractor_compliance_documents d ON d.profile_id = r.profile_id
  WHERE r.audit_period_id = v_period.id
    AND r.included
    AND d.document_type IN ('workers_comp', 'workers_comp_waiver', 'general_liability')
    AND d.review_state IN ('accepted', 'superseded')
    AND d.coverage_start_date <= v_period.end_date
    AND d.coverage_end_date >= v_period.start_date;

  WITH requirement_groups(requirement_group, document_types) AS (
    VALUES
      ('workers_comp'::text, ARRAY['workers_comp', 'workers_comp_waiver']::text[]),
      ('general_liability'::text, ARRAY['general_liability']::text[])
  ),
  covered AS (
    SELECT
      r.profile_id,
      g.requirement_group,
      range_agg(daterange(
        GREATEST(d.coverage_start_date, v_period.start_date),
        LEAST(d.coverage_end_date, v_period.end_date),
        '[]'
      )) FILTER (WHERE d.id IS NOT NULL) AS intervals
    FROM public.contractor_compliance_audit_roster r
    CROSS JOIN requirement_groups g
    LEFT JOIN public.contractor_compliance_documents d
      ON d.profile_id = r.profile_id
      AND d.document_type = ANY(g.document_types)
      AND d.review_state IN ('accepted', 'superseded')
      AND d.coverage_start_date <= v_period.end_date
      AND d.coverage_end_date >= v_period.start_date
    WHERE r.audit_period_id = v_period.id AND r.included
    GROUP BY r.profile_id, g.requirement_group
  ),
  gaps AS (
    SELECT c.profile_id, c.requirement_group, gap_interval
    FROM covered c
    CROSS JOIN LATERAL unnest(
      datemultirange(daterange(v_period.start_date, v_period.end_date, '[]'))
      - COALESCE(c.intervals, '{}'::datemultirange)
    ) AS gap_ranges(gap_interval)
  )
  INSERT INTO public.contractor_compliance_audit_evidence (
    audit_period_id, profile_id, requirement_group,
    interval_kind, interval_start, interval_end
  )
  SELECT
    v_period.id,
    g.profile_id,
    g.requirement_group,
    'gap',
    lower(g.gap_interval),
    upper(g.gap_interval) - 1
  FROM gaps g;

  INSERT INTO public.contractor_compliance_audit_requests (
    audit_period_id, request_id, profile_id, requested_document_types,
    source, created_at_snapshot, sent_at_snapshot, completed_at_snapshot,
    revoked_at_snapshot, expires_at_snapshot
  )
  SELECT
    v_period.id,
    q.id,
    q.profile_id,
    q.requested_document_types,
    q.source,
    q.created_at,
    q.sent_at,
    q.completed_at,
    q.revoked_at,
    q.expires_at
  FROM public.contractor_compliance_requests q
  JOIN public.contractor_compliance_audit_roster r
    ON r.profile_id = q.profile_id
    AND r.audit_period_id = v_period.id
    AND r.included
  WHERE q.created_at < ((v_period.end_date + 1)::timestamp AT TIME ZONE 'America/Denver')
    AND q.requested_document_types
        && ARRAY['workers_comp', 'workers_comp_waiver', 'general_liability']::text[]
    AND (
      (q.expires_at AT TIME ZONE 'America/Denver')::date >= v_period.start_date
      OR (q.sent_at AT TIME ZONE 'America/Denver')::date
         BETWEEN v_period.start_date AND v_period.end_date
    );

  INSERT INTO public.contractor_compliance_audit_request_deliveries (
    audit_period_id, delivery_id, request_id, stage_key, status,
    sent_at_snapshot, completed_at_snapshot, outcome_reason
  )
  SELECT
    v_period.id,
    d.id,
    d.request_id,
    d.stage_key,
    d.status,
    d.sent_at,
    d.completed_at,
    d.outcome_reason
  FROM public.contractor_compliance_request_deliveries d
  JOIN public.contractor_compliance_audit_requests q
    ON q.request_id = d.request_id AND q.audit_period_id = v_period.id;

  UPDATE public.contractor_compliance_audit_periods
  SET status = 'open', materialized_by = v_actor, materialized_at = now(), updated_at = now()
  WHERE id = v_period.id;

  SELECT count(*) INTO v_count
  FROM public.contractor_compliance_audit_roster
  WHERE audit_period_id = v_period.id AND included;
  RETURN jsonb_build_object('id', v_period.id, 'status', 'open', 'roster_count', v_count);
END;
$$;


ALTER FUNCTION "public"."contractor_compliance_materialize_audit_period"("p_audit_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_mutate_profile_requests"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_profile uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  UPDATE public.contractor_compliance_profiles SET requests_paused_at=CASE WHEN p_action='pause_reminders' THEN now() WHEN p_action='resume_reminders' THEN NULL ELSE requests_paused_at END,requests_paused_by=CASE WHEN p_action='pause_reminders' THEN p_actor_employee_id WHEN p_action='resume_reminders' THEN NULL ELSE requests_paused_by END,requests_pause_reason=CASE WHEN p_action='pause_reminders' THEN NULLIF(btrim(p_reason),'') WHEN p_action='resume_reminders' THEN NULL ELSE requests_pause_reason END,updated_at=now() WHERE contact_id=p_contractor_id AND p_action IN ('pause_reminders','resume_reminders') RETURNING id INTO v_profile;
  IF v_profile IS NULL OR (p_action='pause_reminders' AND NULLIF(btrim(p_reason),'') IS NULL) THEN RAISE EXCEPTION 'INVALID_ARGUMENT: profile or pause reason' USING errcode='22023'; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,actor_employee_id,event_type,note) VALUES(v_profile,p_actor_employee_id,'profile_'||p_action,NULLIF(btrim(p_reason),''));
END; $$;


ALTER FUNCTION "public"."contractor_compliance_mutate_profile_requests"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_mutate_request"("p_actor_employee_id" "uuid", "p_request_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_profile uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  UPDATE public.contractor_compliance_requests SET paused_at=CASE WHEN p_action='pause' THEN now() WHEN p_action='resume' THEN NULL ELSE paused_at END,paused_by=CASE WHEN p_action='pause' THEN p_actor_employee_id WHEN p_action='resume' THEN NULL ELSE paused_by END,pause_reason=CASE WHEN p_action='pause' THEN COALESCE(NULLIF(btrim(p_reason),''),'paused by manager') WHEN p_action='resume' THEN NULL ELSE pause_reason END,revoked_at=CASE WHEN p_action='revoke' THEN now() ELSE revoked_at END,revoked_by=CASE WHEN p_action='revoke' THEN p_actor_employee_id ELSE revoked_by END,revoke_reason=CASE WHEN p_action='revoke' THEN COALESCE(NULLIF(btrim(p_reason),''),'revoked by manager') ELSE revoke_reason END,updated_at=now() WHERE id=p_request_id AND p_action IN ('pause','resume','revoke') RETURNING profile_id INTO v_profile;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: request not found' USING errcode='P0002'; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,request_id,actor_employee_id,event_type) VALUES(v_profile,p_request_id,p_actor_employee_id,'request_' || p_action);
END; $$;


ALTER FUNCTION "public"."contractor_compliance_mutate_request"("p_actor_employee_id" "uuid", "p_request_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_public_request"("p_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  SELECT jsonb_build_object('request_id',r.id,'contractor_id',p.contact_id,'requested_document_types',r.requested_document_types,'expires_at',r.expires_at)
  FROM public.contractor_compliance_requests r JOIN public.contractor_compliance_profiles p ON p.id=r.profile_id
  WHERE r.token_digest=lower($1) AND r.expires_at>now() AND r.revoked_at IS NULL AND r.paused_at IS NULL AND r.completed_at IS NULL AND r.upload_count<r.max_uploads;
$_$;


ALTER FUNCTION "public"."contractor_compliance_public_request"("p_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_record_public_attempt"("p_request_id" "uuid", "p_token_digest" "text", "p_ip_digest" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.contractor_compliance_requests r WHERE r.id=p_request_id AND r.token_digest=lower(p_token_digest) AND r.expires_at>now() AND r.revoked_at IS NULL AND r.paused_at IS NULL) THEN RETURN false; END IF;
  INSERT INTO public.contractor_compliance_public_attempts(request_id,ip_hash,window_started_at,attempt_count) VALUES(p_request_id,COALESCE(lower(p_ip_digest),repeat('0',64)),date_trunc('hour',now()),1) ON CONFLICT(request_id,ip_hash,window_started_at) DO UPDATE SET attempt_count=public.contractor_compliance_public_attempts.attempt_count+1,last_attempt_at=now() RETURNING attempt_count INTO v_count;
  RETURN v_count <= 10;
END; $$;


ALTER FUNCTION "public"."contractor_compliance_record_public_attempt"("p_request_id" "uuid", "p_token_digest" "text", "p_ip_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_reminder_candidates"("p_limit" integer DEFAULT 100) RETURNS TABLE("request_identity" "text", "contractor_id" "uuid", "document_types" "text"[], "recipient_email" "text", "stage" "text", "requirement_label" "text", "due_label" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
WITH t AS (SELECT (now() AT TIME ZONE 'America/Denver')::date today), base AS (
  SELECT p.id,p.contact_id,c.email,p.required_w9_year,t.today,(p.created_at AT TIME ZONE 'America/Denver')::date profile_start,
    EXISTS(SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='w9' AND d.review_state IN ('accepted','superseded') AND d.tax_year=p.required_w9_year) w9_ok,
    public.contractor_compliance_continuous_coverage_end(p.id,ARRAY['workers_comp','workers_comp_waiver'],t.today) wc_end,
    public.contractor_compliance_continuous_coverage_end(p.id,ARRAY['general_liability'],t.today) gl_end
  FROM public.contractor_compliance_profiles p
  JOIN public.contacts c ON c.id=p.contact_id AND c.role='subcontractor'
  CROSS JOIN t
  WHERE p.is_active AND p.requests_paused_at IS NULL
), req AS (
  SELECT contact_id,email,today,'w9' kind,ARRAY['w9']::text[] types,make_date(required_w9_year,1,1) anchor,false missing,'current-year W-9' label FROM base WHERE NOT w9_ok
  UNION ALL SELECT contact_id,email,today,'workers_comp',ARRAY['workers_comp','workers_comp_waiver'],COALESCE(wc_end,profile_start),wc_end IS NULL,'workers compensation coverage or Utah waiver' FROM base WHERE wc_end IS NULL OR wc_end<=today+60
  UNION ALL SELECT contact_id,email,today,'general_liability',ARRAY['general_liability'],COALESCE(gl_end,profile_start),gl_end IS NULL,'general liability certificate' FROM base WHERE gl_end IS NULL OR gl_end<=today+60
), stages AS (
  SELECT r.*, s.stage,s.due
  FROM req r
  CROSS JOIN LATERAL (
    SELECT due_stage.stage,due_stage.due
    FROM (
      SELECT 'missing_initial'::text stage,r.anchor due WHERE r.missing
      UNION ALL
      SELECT scheduled.stage,scheduled.due
      FROM (VALUES ('60d',r.anchor-60),('30d',r.anchor-30),('14d',r.anchor-14),('7d',r.anchor-7),('expiration',r.anchor)) scheduled(stage,due)
      WHERE NOT r.missing
      UNION ALL
      SELECT 'overdue_week_'||g::text,r.anchor+(g*7) FROM generate_series(1,8) g
    ) due_stage
    WHERE due_stage.due<=r.today
    ORDER BY due_stage.due DESC
    LIMIT 1
  ) s
)
SELECT 'contractor:'||contact_id::text||':'||kind||':'||stage||':'||anchor::text,contact_id,types,email,stage,label,
  CASE WHEN stage LIKE 'overdue%' THEN 'overdue' WHEN stage='expiration' THEN 'expires today' WHEN stage='missing_initial' THEN 'missing now' ELSE 'renewal due' END
FROM stages WHERE email IS NOT NULL ORDER BY due,contact_id LIMIT LEAST(GREATEST(p_limit,1),500);
$$;


ALTER FUNCTION "public"."contractor_compliance_reminder_candidates"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_reminder_poll"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_url text; v_secret text;
BEGIN
  SELECT value INTO v_url FROM public.integration_config WHERE key='contractor_compliance_reminder_worker_url';
  SELECT value INTO v_secret FROM public.integration_config WHERE key='cron_worker_secret';
  IF v_url NOT IN (
    'https://dev.utahpros.app/api/contractor-compliance-reminders',
    'https://utahpros.app/api/contractor-compliance-reminders'
  ) OR NULLIF(btrim(v_secret),'') IS NULL THEN
    RETURN;
  END IF;
  PERFORM net.http_post(
    url:=v_url,
    headers:=jsonb_build_object('Content-Type','application/json','x-webhook-secret',v_secret),
    body:='{}'::jsonb,
    timeout_milliseconds:=30000
  );
END;
$$;


ALTER FUNCTION "public"."contractor_compliance_reminder_poll"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_review_document"("p_actor_employee_id" "uuid", "p_document_id" "uuid", "p_review_state" "text", "p_rejection_reason" "text" DEFAULT NULL::"text", "p_coverage_start_date" "date" DEFAULT NULL::"date", "p_coverage_end_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_profile uuid; v_type text; v_start date; v_end date;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  IF p_review_state NOT IN ('accepted','rejected') OR (p_review_state='rejected' AND NULLIF(btrim(p_rejection_reason),'') IS NULL) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: accepted or reasoned rejection required' USING errcode='22023';
  END IF;

  -- Resolve the dates this acceptance would end up with: the supplied values
  -- win, otherwise whatever the contractor already provided.
  SELECT COALESCE(p_coverage_start_date, d.coverage_start_date),
         COALESCE(p_coverage_end_date,   d.coverage_end_date)
    INTO v_start, v_end
    FROM public.contractor_compliance_documents d
   WHERE d.id = p_document_id AND d.review_state = 'pending_review';

  IF p_review_state = 'accepted'
     AND EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.id=p_document_id AND d.document_type <> 'w9')
     AND (v_start IS NULL OR v_end IS NULL OR v_end < v_start) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: coverage start and end dates are required to accept this document'
      USING errcode='22023';
  END IF;

  UPDATE public.contractor_compliance_documents
  SET review_state=p_review_state,verified_by=p_actor_employee_id,verified_at=now(),
      coverage_start_date=CASE WHEN document_type='w9' THEN coverage_start_date ELSE COALESCE(p_coverage_start_date, coverage_start_date) END,
      coverage_end_date=CASE WHEN document_type='w9' THEN coverage_end_date ELSE COALESCE(p_coverage_end_date, coverage_end_date) END,
      rejection_reason=CASE WHEN p_review_state='rejected' THEN NULLIF(btrim(p_rejection_reason),'') ELSE NULL END
  WHERE id=p_document_id AND review_state='pending_review'
  RETURNING profile_id,document_type INTO v_profile,v_type;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: reviewable document not found' USING errcode='P0002'; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,document_id,actor_employee_id,event_type) VALUES(v_profile,p_document_id,p_actor_employee_id,'document_' || p_review_state);
  IF p_review_state='accepted' THEN
    UPDATE public.contractor_compliance_documents
    SET review_state='superseded',superseded_at=now(),superseded_by_document_id=p_document_id
    WHERE profile_id=v_profile AND document_type=v_type AND id<>p_document_id AND review_state='accepted';
    UPDATE public.contractor_compliance_requests r SET completed_at=now(),updated_at=now()
    WHERE r.profile_id=v_profile AND r.completed_at IS NULL AND r.revoked_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM unnest(r.requested_document_types) typ WHERE
        (typ='w9' AND NOT EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type='w9' AND d.review_state IN ('accepted','superseded') AND d.tax_year=(SELECT required_w9_year FROM public.contractor_compliance_profiles WHERE id=v_profile)))
        OR (typ='general_liability' AND COALESCE(public.contractor_compliance_continuous_coverage_end(v_profile,ARRAY['general_liability'],(now() AT TIME ZONE 'America/Denver')::date),'0001-01-01'::date)
              <= COALESCE(NULLIF(substring(r.request_identity FROM '([0-9]{4}-[0-9]{2}-[0-9]{2})$'), '')::date,(now() AT TIME ZONE 'America/Denver')::date))
        OR (typ IN ('workers_comp','workers_comp_waiver') AND COALESCE(public.contractor_compliance_continuous_coverage_end(v_profile,ARRAY['workers_comp','workers_comp_waiver'],(now() AT TIME ZONE 'America/Denver')::date),'0001-01-01'::date)
              <= COALESCE(NULLIF(substring(r.request_identity FROM '([0-9]{4}-[0-9]{2}-[0-9]{2})$'), '')::date,(now() AT TIME ZONE 'America/Denver')::date))
      );
  END IF;
  RETURN jsonb_build_object('id',p_document_id,'review_state',p_review_state);
END; $_$;


ALTER FUNCTION "public"."contractor_compliance_review_document"("p_actor_employee_id" "uuid", "p_document_id" "uuid", "p_review_state" "text", "p_rejection_reason" "text", "p_coverage_start_date" "date", "p_coverage_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_rotate_request"("p_actor_employee_id" "uuid", "p_old_request_id" "uuid", "p_token_digest" "text", "p_request_identity" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_old public.contractor_compliance_requests; v_id uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active AND NOT e.is_external AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  SELECT id INTO v_id FROM public.contractor_compliance_requests WHERE request_identity=p_request_identity;
  IF v_id IS NOT NULL THEN RETURN jsonb_build_object('request_id',v_id); END IF;
  SELECT * INTO v_old FROM public.contractor_compliance_requests WHERE id=p_old_request_id FOR UPDATE;
  IF v_old.id IS NULL OR p_token_digest !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'INVALID_ARGUMENT: request rotation' USING errcode='22023'; END IF;
  UPDATE public.contractor_compliance_requests SET revoked_at=now(),revoked_by=p_actor_employee_id,revoke_reason='rotated request',updated_at=now() WHERE id=v_old.id;
  INSERT INTO public.contractor_compliance_requests(profile_id,request_identity,requested_document_types,recipient_email,token_digest,expires_at,created_by,source,supersedes_request_id) VALUES(v_old.profile_id,p_request_identity,v_old.requested_document_types,v_old.recipient_email,lower(p_token_digest),now()+interval '30 days',p_actor_employee_id,'manual_resend',v_old.id) RETURNING id INTO v_id;
  RETURN jsonb_build_object('request_id',v_id);
END; $_$;


ALTER FUNCTION "public"."contractor_compliance_rotate_request"("p_actor_employee_id" "uuid", "p_old_request_id" "uuid", "p_token_digest" "text", "p_request_identity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_set_profile_active"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_is_active" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_profile uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id=p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE AND e.role::text IN ('admin','office')) THEN RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance manager required' USING errcode='42501'; END IF;
  IF p_is_active IS FALSE AND NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'INVALID_ARGUMENT: deactivation reason required' USING errcode='22023'; END IF;
  UPDATE public.contractor_compliance_profiles SET is_active=p_is_active,updated_at=now() WHERE contact_id=p_contractor_id RETURNING id INTO v_profile;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: contractor profile not found' USING errcode='P0002'; END IF;
  INSERT INTO public.contractor_compliance_activity(profile_id,actor_employee_id,event_type,note) VALUES(v_profile,p_actor_employee_id,CASE WHEN p_is_active THEN 'profile_activated' ELSE 'profile_deactivated' END,NULLIF(btrim(p_reason),''));
END; $$;


ALTER FUNCTION "public"."contractor_compliance_set_profile_active"("p_actor_employee_id" "uuid", "p_contractor_id" "uuid", "p_is_active" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_compliance_upsert_audit_roster"("p_audit_period_id" "uuid", "p_contact_id" "uuid", "p_included" boolean DEFAULT true, "p_active_in_period" boolean DEFAULT NULL::boolean, "p_paid_in_period" boolean DEFAULT NULL::boolean, "p_inclusion_source" "text" DEFAULT 'manual'::"text", "p_external_source" "text" DEFAULT NULL::"text", "p_source_external_id" "text" DEFAULT NULL::"text", "p_reconciliation_state" "text" DEFAULT 'unknown'::"text", "p_reconciliation_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_profile uuid;
BEGIN
  SELECT e.id INTO v_actor
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid()
    AND e.is_active
    AND NOT e.is_external
    AND e.role::text IN ('admin', 'office');
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor audit manager required' USING errcode = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.contractor_compliance_audit_periods p
    WHERE p.id = p_audit_period_id AND p.status IN ('locked', 'closed')
  ) THEN
    RAISE EXCEPTION 'AUDIT_LOCKED: roster is immutable' USING errcode = '55000';
  END IF;
  IF p_inclusion_source NOT IN ('manual', 'external_import')
     OR p_reconciliation_state NOT IN ('unknown', 'unreconciled', 'reconciled', 'variance')
     OR (
       p_inclusion_source = 'external_import'
       AND (
         NULLIF(btrim(p_external_source), '') IS NULL
         OR NULLIF(btrim(p_source_external_id), '') IS NULL
       )
     )
     OR COALESCE(p_reconciliation_metadata, '{}'::jsonb)
        ?| ARRAY['token', 'token_digest', 'storage_path', 'tax_identifier', 'ssn', 'ein'] THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: sourced audit roster facts required' USING errcode = '22023';
  END IF;
  SELECT p.id INTO v_profile
  FROM public.contractor_compliance_profiles p
  JOIN public.contacts c ON c.id = p.contact_id AND c.role = 'subcontractor'
  WHERE p.contact_id = p_contact_id;
  IF v_profile IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.contractor_compliance_audit_periods p WHERE p.id = p_audit_period_id
  ) THEN
    RAISE EXCEPTION 'NOT_FOUND: audit period or contractor missing' USING errcode = 'P0002';
  END IF;
  INSERT INTO public.contractor_compliance_audit_roster (
    audit_period_id, profile_id, included, inclusion_source,
    active_in_period, paid_in_period, external_source, source_external_id,
    source_as_of, reconciliation_state, reconciliation_metadata, captured_at
  ) VALUES (
    p_audit_period_id, v_profile, p_included, p_inclusion_source,
    p_active_in_period, p_paid_in_period, NULLIF(btrim(p_external_source), ''),
    NULLIF(btrim(p_source_external_id), ''), now(), p_reconciliation_state,
    COALESCE(p_reconciliation_metadata, '{}'::jsonb), now()
  )
  ON CONFLICT (audit_period_id, profile_id) DO UPDATE SET
    included = EXCLUDED.included,
    inclusion_source = EXCLUDED.inclusion_source,
    active_in_period = EXCLUDED.active_in_period,
    paid_in_period = EXCLUDED.paid_in_period,
    external_source = EXCLUDED.external_source,
    source_external_id = EXCLUDED.source_external_id,
    source_as_of = EXCLUDED.source_as_of,
    reconciliation_state = EXCLUDED.reconciliation_state,
    reconciliation_metadata = EXCLUDED.reconciliation_metadata,
    captured_at = now();
END;
$$;


ALTER FUNCTION "public"."contractor_compliance_upsert_audit_roster"("p_audit_period_id" "uuid", "p_contact_id" "uuid", "p_included" boolean, "p_active_in_period" boolean, "p_paid_in_period" boolean, "p_inclusion_source" "text", "p_external_source" "text", "p_source_external_id" "text", "p_reconciliation_state" "text", "p_reconciliation_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contractor_w9_upsert_provider_handoff"("p_contact_id" "uuid", "p_tax_year" integer, "p_provider_target" "text", "p_quickbooks_contractor_external_id" "text" DEFAULT NULL::"text", "p_gusto_contractor_external_id" "text" DEFAULT NULL::"text", "p_handoff_status" "text" DEFAULT 'not_ready'::"text", "p_handoff_date" "date" DEFAULT NULL::"date", "p_provider_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_profile uuid;
  v_id uuid;
  v_has_current_w9 boolean;
BEGIN
  SELECT e.id INTO v_actor
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid()
    AND e.is_active
    AND NOT e.is_external
    AND e.role::text IN ('admin', 'office');
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: W-9 handoff manager required' USING errcode = '42501';
  END IF;
  IF p_tax_year NOT BETWEEN 2000 AND 2200
     OR p_provider_target NOT IN ('unassigned', 'quickbooks', 'gusto', 'quickbooks_and_gusto', 'other')
     OR p_handoff_status NOT IN ('not_ready', 'ready', 'handed_off', 'reconciled')
     OR (
       p_handoff_status <> 'not_ready'
       AND p_provider_target = 'unassigned'
     )
     OR (
       p_handoff_status IN ('handed_off', 'reconciled')
       AND (
         p_handoff_date IS NULL
         OR NULLIF(btrim(p_provider_reference), '') IS NULL
       )
     ) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: W-9 handoff values' USING errcode = '22023';
  END IF;

  SELECT p.id INTO v_profile
  FROM public.contractor_compliance_profiles p
  JOIN public.contacts c ON c.id = p.contact_id AND c.role = 'subcontractor'
  WHERE p.contact_id = p_contact_id;
  IF v_profile IS NULL THEN
    RAISE EXCEPTION 'NOT_FOUND: contractor missing' USING errcode = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.contractor_compliance_documents d
    WHERE d.profile_id = v_profile
      AND d.document_type = 'w9'
      AND d.tax_year = p_tax_year
      AND d.review_state IN ('accepted', 'superseded')
  ) INTO v_has_current_w9;
  IF p_handoff_status <> 'not_ready' AND NOT v_has_current_w9 THEN
    RAISE EXCEPTION 'W9_NOT_READY: accepted W-9 required for tax year' USING errcode = '55000';
  END IF;

  INSERT INTO public.contractor_w9_provider_handoffs (
    profile_id,
    tax_year,
    provider_target,
    quickbooks_contractor_external_id,
    gusto_contractor_external_id,
    handoff_status,
    handoff_date,
    provider_reference,
    updated_by
  ) VALUES (
    v_profile,
    p_tax_year,
    p_provider_target,
    NULLIF(btrim(p_quickbooks_contractor_external_id), ''),
    NULLIF(btrim(p_gusto_contractor_external_id), ''),
    p_handoff_status,
    p_handoff_date,
    NULLIF(btrim(p_provider_reference), ''),
    v_actor
  )
  ON CONFLICT (profile_id, tax_year) DO UPDATE SET
    provider_target = EXCLUDED.provider_target,
    quickbooks_contractor_external_id = EXCLUDED.quickbooks_contractor_external_id,
    gusto_contractor_external_id = EXCLUDED.gusto_contractor_external_id,
    handoff_status = EXCLUDED.handoff_status,
    handoff_date = EXCLUDED.handoff_date,
    provider_reference = EXCLUDED.provider_reference,
    updated_by = EXCLUDED.updated_by,
    updated_at = now()
  RETURNING id INTO v_id;

  INSERT INTO public.contractor_compliance_activity (
    profile_id, actor_employee_id, event_type, note, safe_metadata
  ) VALUES (
    v_profile,
    v_actor,
    'w9_provider_handoff_updated',
    NULL,
    jsonb_build_object(
      'tax_year', p_tax_year,
      'provider_target', p_provider_target,
      'handoff_status', p_handoff_status
    )
  );

  RETURN jsonb_build_object(
    'id', v_id,
    'tax_year', p_tax_year,
    'handoff_status', p_handoff_status
  );
END;
$$;


ALTER FUNCTION "public"."contractor_w9_upsert_provider_handoff"("p_contact_id" "uuid", "p_tax_year" integer, "p_provider_target" "text", "p_quickbooks_contractor_external_id" "text", "p_gusto_contractor_external_id" "text", "p_handoff_status" "text", "p_handoff_date" "date", "p_provider_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_estimate_to_invoice"("p_estimate_id" "uuid", "p_force" boolean DEFAULT false, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_est      public.estimates;
  v_contact  public.contacts;
  v_jobres   jsonb;
  v_job_id   uuid;
  v_invoice  public.invoices;
  v_existing integer;
  v_copied   integer;
  v_max_sort integer;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.billing_edit_access() THEN
    RAISE EXCEPTION 'not_authorized: active internal billing editor required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_est
  FROM public.estimates
  WHERE id = p_estimate_id
  FOR UPDATE;
  IF v_est.id IS NULL THEN RAISE EXCEPTION 'Estimate % not found', p_estimate_id; END IF;

  IF v_est.converted_invoice_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'invoice_id', v_est.converted_invoice_id,
      'lines_copied', 0,
      'appended', false
    );
  END IF;

  v_job_id := v_est.job_id;
  IF v_job_id IS NULL THEN
    IF v_est.contact_id IS NULL THEN
      RAISE EXCEPTION 'Estimate % has no contact to create a job from', p_estimate_id;
    END IF;
    SELECT * INTO v_contact FROM public.contacts WHERE id = v_est.contact_id;
    v_jobres := public.create_job_with_contact(
      p_contact_id     := v_contact.id,
      p_contact_name   := v_contact.name,
      p_contact_phone  := v_contact.phone,
      p_contact_email  := v_contact.email,
      p_contact_role   := COALESCE(v_contact.role, 'homeowner'),
      p_division       := COALESCE(v_est.intended_division, 'water'),
      p_source         := 'insurance',
      p_priority       := 3,
      p_address        := v_est.property_address,
      p_city           := v_est.property_city,
      p_state          := v_est.property_state,
      p_zip            := v_est.property_zip,
      p_internal_notes := 'Auto-created from estimate ' || COALESCE(v_est.estimate_number, v_est.id::text)
    );
    v_job_id := (v_jobres->'job'->>'id')::uuid;
    IF v_job_id IS NULL THEN RAISE EXCEPTION 'Failed to auto-create a job for estimate %', p_estimate_id; END IF;
    UPDATE public.estimates SET job_id = v_job_id WHERE id = p_estimate_id;
  END IF;

  v_invoice := public.create_invoice_for_job(v_job_id, p_created_by);

  SELECT count(*) INTO v_existing
  FROM public.invoice_line_items
  WHERE invoice_id = v_invoice.id;
  IF v_existing > 0 AND NOT p_force THEN
    RETURN jsonb_build_object('needs_confirm', true, 'invoice_id', v_invoice.id, 'existing_line_count', v_existing);
  END IF;

  SELECT COALESCE(MAX(sort_order), -1) INTO v_max_sort
  FROM public.invoice_line_items
  WHERE invoice_id = v_invoice.id;

  INSERT INTO public.invoice_line_items (
    invoice_id, description, xactimate_code, quantity, unit, unit_price,
    qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name, sort_order
  )
  SELECT
    v_invoice.id, eli.description, eli.xactimate_code, eli.quantity, eli.unit, eli.unit_price,
    eli.qbo_item_id, eli.qbo_item_name, eli.qbo_class_id, eli.qbo_class_name,
    v_max_sort + (row_number() OVER (ORDER BY eli.sort_order, eli.created_at))::integer
  FROM public.estimate_line_items eli
  WHERE eli.estimate_id = p_estimate_id;
  GET DIAGNOSTICS v_copied = ROW_COUNT;

  UPDATE public.invoices
  SET estimate_id = p_estimate_id, updated_at = now()
  WHERE id = v_invoice.id;
  UPDATE public.estimates
  SET converted_invoice_id = v_invoice.id,
      status = 'approved',
      approved_at = COALESCE(approved_at, now()),
      approved_amount = COALESCE(approved_amount, amount),
      updated_at = now()
  WHERE id = p_estimate_id;

  RETURN jsonb_build_object('ok', true, 'invoice_id', v_invoice.id, 'lines_copied', v_copied, 'appended', v_existing > 0);
END;
$$;


ALTER FUNCTION "public"."convert_estimate_to_invoice"("p_estimate_id" "uuid", "p_force" boolean, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_oop_quote_to_estimate"("p_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid;
  v_quote public.oop_quotes;
  v_job public.jobs;
  v_snapshot public.oop_quote_pricing_snapshots;
  v_estimate public.estimates;
  v_line jsonb;
  v_item jsonb;
  v_section text;
  v_amount numeric;
  v_service_total numeric := 0;
  v_equipment_total numeric := 0;
  v_equipment_labels text[] := ARRAY[]::text[];
  v_label text;
  v_service_description text;
  v_equipment_description text;
  v_qbo_item_id text;
  v_qbo_item_name text;
  v_inserted integer := 0;
  v_total numeric;
BEGIN
  v_actor := public.oop_pricing_active_employee(false);

  IF NOT public.billing_edit_access() THEN
    RAISE EXCEPTION 'not_authorized: active internal billing editor required'
      USING ERRCODE = '42501';
  END IF;

  SELECT q.*
    INTO v_quote
    FROM public.oop_quotes q
   WHERE q.id = p_quote_id
   FOR UPDATE;
  IF v_quote.id IS NULL THEN RAISE EXCEPTION 'oop_quote_not_found'; END IF;

  IF v_quote.converted_estimate_id IS NOT NULL THEN
    SELECT e.* INTO v_estimate
      FROM public.estimates e
     WHERE e.id = v_quote.converted_estimate_id;
    IF v_estimate.id IS NULL THEN RAISE EXCEPTION 'oop_quote_estimate_link_broken'; END IF;
    RETURN jsonb_build_object('ok',true,'estimate_id',v_estimate.id,'created',false);
  END IF;

  IF v_quote.job_id IS NULL THEN RAISE EXCEPTION 'oop_quote_job_required'; END IF;
  IF COALESCE(v_quote.quote_total, 0) <= 0 THEN RAISE EXCEPTION 'oop_quote_positive_total_required'; END IF;

  SELECT j.*
    INTO v_job
    FROM public.jobs j
   WHERE j.id = v_quote.job_id
   FOR SHARE;
  IF v_job.id IS NULL THEN RAISE EXCEPTION 'oop_quote_job_not_found'; END IF;
  IF v_job.primary_contact_id IS NULL THEN RAISE EXCEPTION 'oop_quote_job_contact_required'; END IF;

  SELECT s.*
    INTO v_snapshot
    FROM public.oop_quote_pricing_snapshots s
   WHERE s.quote_id = v_quote.id
     AND s.cleared_at IS NULL;
  IF v_snapshot.quote_id IS NULL
    OR jsonb_typeof(v_snapshot.pricing_evaluated_lines) <> 'array'
    OR jsonb_typeof(v_snapshot.pricing_config_snapshot->'items') <> 'array' THEN
    RAISE EXCEPTION 'oop_quote_snapshot_required';
  END IF;

  INSERT INTO public.estimates (
    job_id, contact_id, estimate_number, estimate_type, notes, created_by,
    intended_division, property_address, property_city, property_state, property_zip
  ) VALUES (
    v_job.id, v_job.primary_contact_id, public.generate_estimate_number(), 'initial',
    NULLIF(btrim(v_quote.notes), ''), v_actor, v_quote.job_type,
    v_job.address, v_job.city, v_job.state, v_job.zip
  ) RETURNING * INTO v_estimate;

  -- Roll the priced items into two customer-facing buckets instead of copying the
  -- internal breakdown onto the document. The bucket is the price list's own
  -- `section`, so a new equipment item added in the pricing builder lands in the
  -- equipment bucket without touching this function.
  FOR v_line IN
    SELECT value
      FROM jsonb_array_elements(v_snapshot.pricing_evaluated_lines)
     ORDER BY COALESCE((value->>'sortOrder')::integer, 2147483647), value->>'key'
  LOOP
    v_amount := round(COALESCE((v_line->>'amount')::numeric, 0), 2);
    IF NOT COALESCE((v_line->>'customerVisible')::boolean,false) OR v_amount <= 0 THEN
      CONTINUE;
    END IF;

    IF v_line->>'key' = 'project_minimum_adjustment' THEN
      -- Not a priced item; it tops the job up to the project minimum, so it
      -- belongs with the service rather than with equipment.
      v_service_total := v_service_total + v_amount;
      CONTINUE;
    END IF;

    SELECT item.value
      INTO v_item
      FROM jsonb_array_elements(v_snapshot.pricing_config_snapshot->'items') item(value)
     WHERE item.value->>'key' = v_line->>'key'
     LIMIT 1;
    IF v_item IS NULL THEN RAISE EXCEPTION 'oop_quote_snapshot_item_missing'; END IF;

    v_section := lower(btrim(COALESCE(v_item->>'section', '')));
    IF v_section = 'equipment' THEN
      v_equipment_total := v_equipment_total + v_amount;
      v_label := btrim(COALESCE(v_item->>'label', ''));
      IF v_label <> '' AND NOT (v_label = ANY (v_equipment_labels)) THEN
        v_equipment_labels := v_equipment_labels || v_label;
      END IF;
    ELSE
      v_service_total := v_service_total + v_amount;
    END IF;
  END LOOP;

  -- Standard scope of work. Staff can edit either description afterwards in the
  -- estimate editor; this is the starting text, not a frozen contract.
  IF v_quote.job_type = 'mold' THEN
    v_service_description :=
      'Mold remediation. Containment of the affected area under negative air pressure, '
      || 'removal and disposal of mold-affected materials, HEPA vacuuming and detail cleaning '
      || 'of the remaining structure, antimicrobial application, and post-remediation drying '
      || 'to industry standard. Includes technician labor, personal protective equipment, and '
      || 'haul-off and disposal of debris.';
    v_qbo_item_id := '1010000131';
    v_qbo_item_name := 'Mold Remediation Services';
  ELSE
    v_service_description :=
      'Water damage mitigation and structural drying. Emergency response and stabilization of '
      || 'the affected area: containment of the work zone, demolition and removal of '
      || 'unsalvageable materials, cleaning and detail cleaning of affected surfaces, '
      || 'antimicrobial application to the remaining structure, and structural drying to '
      || 'industry standard. Includes technician labor, personal protective equipment, and '
      || 'haul-off and disposal of debris.';
    v_qbo_item_id := '1010000071';
    v_qbo_item_name := 'Water Damage Mitigation And Drying';
  END IF;

  -- QuickBooks Item/Class defaults. These mirror divisionToQbo() in
  -- functions/lib/quickbooks.js, which is the fallback the estimate Worker still
  -- applies to any line that arrives without them; the two lists are pinned
  -- together by tests/qa/unit/oop-estimate-grouped-lines.test.js. Class 1000000005
  -- is "Mitigation" — the only non-Reconstruction class in the realm, and the one
  -- both water and mold work belongs to.
  IF v_service_total > 0 THEN
    INSERT INTO public.estimate_line_items (
      estimate_id, description, quantity, unit, unit_price, sort_order,
      qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name
    ) VALUES (
      v_estimate.id, v_service_description, 1, NULL, v_service_total, 0,
      v_qbo_item_id, v_qbo_item_name, '1000000005', 'Mitigation'
    );
    v_inserted := v_inserted + 1;
  END IF;

  IF v_equipment_total > 0 THEN
    v_equipment_description :=
      'Equipment. Drying and air-quality equipment placed, monitored and removed over the '
      || 'course of the project'
      || CASE
           WHEN array_length(v_equipment_labels, 1) > 0
             THEN ': ' || array_to_string(v_equipment_labels, ', ')
           ELSE ''
         END
      || '.';
    INSERT INTO public.estimate_line_items (
      estimate_id, description, quantity, unit, unit_price, sort_order,
      qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name
    ) VALUES (
      v_estimate.id, v_equipment_description, 1, NULL, v_equipment_total, 1,
      v_qbo_item_id, v_qbo_item_name, '1000000005', 'Mitigation'
    );
    v_inserted := v_inserted + 1;
  END IF;

  IF v_inserted = 0 THEN RAISE EXCEPTION 'oop_quote_customer_lines_required'; END IF;

  SELECT round(COALESCE(sum(li.line_total), 0), 2)
    INTO v_total
    FROM public.estimate_line_items li
   WHERE li.estimate_id = v_estimate.id;
  IF v_total <> round(v_quote.quote_total, 2) THEN
    RAISE EXCEPTION 'oop_quote_estimate_total_mismatch';
  END IF;

  -- This metadata-only transition must not run the legacy canonical recompute or
  -- clear the private v2 snapshot. A distinct marker also prevents a direct
  -- browser UPDATE from manufacturing the provenance link.
  PERFORM set_config('oop_pricing.estimate_conversion', 'on', true);
  PERFORM set_config('oop_pricing.v2_write', 'on', true);
  UPDATE public.oop_quotes
     SET converted_estimate_id = v_estimate.id
   WHERE id = v_quote.id;
  PERFORM set_config('oop_pricing.v2_write', 'off', true);
  PERFORM set_config('oop_pricing.estimate_conversion', 'off', true);

  RETURN jsonb_build_object('ok',true,'estimate_id',v_estimate.id,'created',true);
END;
$$;


ALTER FUNCTION "public"."convert_oop_quote_to_estimate"("p_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_oop_quote_to_estimate"("p_quote_id" "uuid") IS 'Creates or returns the one draft UPR estimate for a saved, job-linked OOP quote. Writes at most two grouped customer lines (service + equipment) with QuickBooks Item/Class defaults. Does not call QuickBooks.';



CREATE OR REPLACE FUNCTION "public"."correct_oop_estimate"("p_estimate_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_address" "jsonb", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor uuid;
  v_role text;
  v_estimate public.estimates;
  v_line_count integer;
  v_existing_count integer;
  v_address text;
  v_city text;
  v_state text;
  v_zip text;
  v_total numeric;
  v_lines jsonb;
  v_matches boolean;
  v_updated_at timestamptz;
BEGIN
  v_actor := public.oop_pricing_active_employee(false);
  SELECT e.role::text
    INTO v_role
    FROM public.employees e
   WHERE e.id = v_actor;
  IF v_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'not_authorized: active internal admin required'
      USING ERRCODE = '42501';
  END IF;

  IF p_estimate_id IS NULL OR p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION 'oop_estimate_correction_version_required'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_address) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_lines) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'oop_estimate_correction_payload_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_address := NULLIF(btrim(p_address->>'property_address'), '');
  v_city := NULLIF(btrim(p_address->>'property_city'), '');
  v_state := NULLIF(btrim(p_address->>'property_state'), '');
  v_zip := NULLIF(btrim(p_address->>'property_zip'), '');
  IF length(COALESCE(v_address, '')) > 500
    OR length(COALESCE(v_city, '')) > 160
    OR length(COALESCE(v_state, '')) > 64
    OR length(COALESCE(v_zip, '')) > 32 THEN
    RAISE EXCEPTION 'oop_estimate_correction_address_invalid'
      USING ERRCODE = '22023';
  END IF;

  v_line_count := jsonb_array_length(p_lines);
  IF v_line_count < 1 OR v_line_count > 100 THEN
    RAISE EXCEPTION 'oop_estimate_correction_line_count_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_lines) elem
     WHERE jsonb_typeof(elem) IS DISTINCT FROM 'object'
        OR COALESCE(elem->>'id', '') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        OR length(btrim(COALESCE(elem->>'description', ''))) NOT BETWEEN 1 AND 2000
        OR COALESCE(elem->>'quantity', '') !~ '^[0-9]+([.][0-9]+)?$'
        OR COALESCE(elem->>'unit_price', '') !~ '^[0-9]+([.][0-9]+)?$'
        OR COALESCE(elem->>'sort_order', '') !~ '^[0-9]+$'
  ) THEN
    RAISE EXCEPTION 'oop_estimate_correction_line_invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (
    SELECT count(DISTINCT x.id)
      FROM jsonb_to_recordset(p_lines)
        AS x(id uuid, description text, quantity numeric, unit_price numeric, sort_order integer)
  ) <> v_line_count THEN
    RAISE EXCEPTION 'oop_estimate_correction_duplicate_line'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_to_recordset(p_lines)
        AS x(id uuid, description text, quantity numeric, unit_price numeric, sort_order integer)
     WHERE x.quantity <= 0
        OR x.quantity > 100000
        OR x.unit_price < 0
        OR x.unit_price > 10000000
  ) THEN
    RAISE EXCEPTION 'oop_estimate_correction_line_bounds'
      USING ERRCODE = '22023';
  END IF;

  SELECT e.*
    INTO v_estimate
    FROM public.estimates e
   WHERE e.id = p_estimate_id
   FOR UPDATE;
  IF v_estimate.id IS NULL THEN
    RAISE EXCEPTION 'oop_estimate_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_estimate.converted_invoice_id IS NOT NULL THEN
    RAISE EXCEPTION 'oop_estimate_already_converted' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.oop_quotes q
     WHERE q.converted_estimate_id = v_estimate.id
  ) THEN
    RAISE EXCEPTION 'oop_estimate_source_quote_required' USING ERRCODE = '23514';
  END IF;

  SELECT count(*)
    INTO v_existing_count
    FROM public.estimate_line_items li
   WHERE li.estimate_id = v_estimate.id;
  IF v_existing_count <> v_line_count OR EXISTS (
    SELECT 1
      FROM jsonb_to_recordset(p_lines)
        AS x(id uuid, description text, quantity numeric, unit_price numeric, sort_order integer)
      LEFT JOIN public.estimate_line_items li
        ON li.id = x.id
       AND li.estimate_id = v_estimate.id
     WHERE li.id IS NULL
  ) THEN
    RAISE EXCEPTION 'oop_estimate_correction_line_set_mismatch'
      USING ERRCODE = '23514';
  END IF;

  SELECT round(sum(x.quantity * x.unit_price), 2)
    INTO v_total
    FROM jsonb_to_recordset(p_lines)
      AS x(id uuid, description text, quantity numeric, unit_price numeric, sort_order integer);
  IF v_total <= 0 OR v_total > 100000000 THEN
    RAISE EXCEPTION 'oop_estimate_correction_total_invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_estimate.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    SELECT
      v_estimate.property_address IS NOT DISTINCT FROM v_address
      AND v_estimate.property_city IS NOT DISTINCT FROM v_city
      AND v_estimate.property_state IS NOT DISTINCT FROM v_state
      AND v_estimate.property_zip IS NOT DISTINCT FROM v_zip
      AND NOT EXISTS (
        SELECT 1
          FROM public.estimate_line_items li
          FULL OUTER JOIN jsonb_to_recordset(p_lines)
            AS x(id uuid, description text, quantity numeric, unit_price numeric, sort_order integer)
            ON x.id = li.id
         WHERE (li.estimate_id = v_estimate.id OR li.id IS NULL)
           AND (
             li.id IS NULL
             OR x.id IS NULL
             OR li.description IS DISTINCT FROM btrim(x.description)
             OR li.quantity IS DISTINCT FROM x.quantity
             OR li.unit_price IS DISTINCT FROM x.unit_price
             OR li.sort_order IS DISTINCT FROM x.sort_order
           )
      )
      INTO v_matches;
    IF NOT COALESCE(v_matches, false) THEN
      RAISE EXCEPTION 'oop_estimate_correction_conflict'
        USING ERRCODE = '40001';
    END IF;
  ELSE
    UPDATE public.estimate_line_items li
       SET description = btrim(x.description),
           quantity = x.quantity,
           unit_price = x.unit_price,
           sort_order = x.sort_order
      FROM jsonb_to_recordset(p_lines)
        AS x(id uuid, description text, quantity numeric, unit_price numeric, sort_order integer)
     WHERE li.id = x.id
       AND li.estimate_id = v_estimate.id;

    v_updated_at := clock_timestamp();
    UPDATE public.estimates e
       SET property_address = v_address,
           property_city = v_city,
           property_state = v_state,
           property_zip = v_zip,
           updated_at = v_updated_at
     WHERE e.id = v_estimate.id;
  END IF;

  SELECT e.updated_at
    INTO v_updated_at
    FROM public.estimates e
   WHERE e.id = v_estimate.id;
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', li.id,
        'description', li.description,
        'quantity', li.quantity,
        'unit_price', li.unit_price,
        'line_total', li.line_total,
        'sort_order', li.sort_order
      )
      ORDER BY li.sort_order, li.created_at
    ),
    '[]'::jsonb
  )
    INTO v_lines
    FROM public.estimate_line_items li
   WHERE li.estimate_id = v_estimate.id;

  RETURN jsonb_build_object(
    'ok', true,
    'replayed', v_estimate.updated_at IS DISTINCT FROM p_expected_updated_at,
    'updated_at', v_updated_at,
    'total', v_total,
    'lines', v_lines
  );
END;
$_$;


ALTER FUNCTION "public"."correct_oop_estimate"("p_estimate_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_address" "jsonb", "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."correct_oop_estimate"("p_estimate_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_address" "jsonb", "p_lines" "jsonb") IS 'Atomically corrects the service address and exact existing line set of an unconverted OOP estimate for an active internal admin.';



CREATE OR REPLACE FUNCTION "public"."create_appointment_with_crew"("p_title" "text", "p_date" "date", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_kind" "text" DEFAULT 'job'::"text", "p_time_start" time without time zone DEFAULT NULL::time without time zone, "p_time_end" time without time zone DEFAULT NULL::time without time zone, "p_type" "text" DEFAULT 'mitigation'::"text", "p_status" "text" DEFAULT 'scheduled'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_is_private" boolean DEFAULT false, "p_notify_client" boolean DEFAULT true, "p_crew" "jsonb" DEFAULT '[]'::"jsonb", "p_task_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_task_templates" "jsonb" DEFAULT '[]'::"jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_role text;
  v_is_trusted boolean :=
    public.is_trusted_appointment_command_caller();
  v_appointment public.appointments%ROWTYPE;
BEGIN
  IF v_is_trusted THEN
    IF p_actor_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.employees employee
         WHERE employee.id = p_actor_id
           AND employee.is_active IS TRUE
           AND employee.is_external IS FALSE
           AND employee.role::text IS DISTINCT FROM 'crm_partner'
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: active internal appointment creator required'
        USING ERRCODE = '42501';
    END IF;
    PERFORM pg_catalog.set_config(
      'upr.appointment_crew_actor_id',
      p_actor_id::text,
      true
    );
  ELSE
    v_actor_id :=
      public.current_active_internal_appointment_employee();
    IF p_actor_id IS NOT NULL
       AND p_actor_id IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment creator does not match caller'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_actor_id :=
    public.current_attributed_appointment_crew_actor();
  IF v_actor_id IS NULL
     OR (
       NOT v_is_trusted
       AND NOT public.can_current_employee_create_appointment_command()
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: attributed active internal appointment creator required'
      USING ERRCODE = '42501';
  END IF;
  SELECT employee.role::text
  INTO v_actor_role
  FROM public.employees employee
  WHERE employee.id = v_actor_id;
  PERFORM pg_catalog.set_config(
    'upr.appointment_crew_actor_id',
    v_actor_id::text,
    true
  );

  IF NULLIF(btrim(COALESCE(p_title, '')), '') IS NULL
     OR p_date IS NULL THEN
    RAISE EXCEPTION
      'create_appointment_with_crew: title and date are required'
      USING ERRCODE = '22023';
  END IF;

  IF p_kind NOT IN ('job', 'event')
     OR (p_kind = 'job' AND p_job_id IS NULL)
     OR (p_kind = 'event' AND p_job_id IS NOT NULL) THEN
    RAISE EXCEPTION
      'create_appointment_with_crew: invalid appointment kind/job shape'
      USING ERRCODE = '22023';
  END IF;

  IF p_job_id IS NOT NULL THEN
    PERFORM 1
    FROM public.jobs job
    WHERE job.id = p_job_id
    FOR SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        'create_appointment_with_crew: job not found'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_time_start IS NOT NULL
     AND p_time_end IS NOT NULL
     AND p_time_end <= p_time_start THEN
    RAISE EXCEPTION
      'create_appointment_with_crew: end time must follow start time'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(NULLIF(btrim(p_type), ''), 'mitigation')
       NOT IN (
         'monitoring',
         'mitigation',
         'inspection',
         'reconstruction',
         'estimate',
         'delivery',
         'mold_remediation',
         'content_cleaning',
         'other'
       )
     OR COALESCE(NULLIF(btrim(p_status), ''), 'scheduled')
       NOT IN (
         'scheduled',
         'en_route',
         'in_progress',
         'paused',
         'completed',
         'cancelled'
       ) THEN
    RAISE EXCEPTION
      'create_appointment_with_crew: invalid type or status'
      USING ERRCODE = '22023';
  END IF;

  IF p_is_private
     AND NOT v_is_trusted
     AND v_actor_role NOT IN ('admin', 'project_manager') THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment privacy manager required'
      USING ERRCODE = '42501';
  END IF;

  IF jsonb_typeof(COALESCE(p_task_templates, '[]'::jsonb))
       <> 'array'
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(
         COALESCE(p_task_templates, '[]'::jsonb)
       ) template
       WHERE jsonb_typeof(template) IS DISTINCT FROM 'object'
          OR NULLIF(
            btrim(COALESCE(template ->> 'title', '')),
            ''
          ) IS NULL
     ) THEN
    RAISE EXCEPTION
      'create_appointment_with_crew: invalid task templates'
      USING ERRCODE = '22023';
  END IF;

  IF p_job_id IS NULL
     AND jsonb_array_length(
       COALESCE(p_task_templates, '[]'::jsonb)
     ) > 0 THEN
    RAISE EXCEPTION
      'create_appointment_with_crew: events cannot clone job tasks'
      USING ERRCODE = '22023';
  END IF;

  IF p_task_ids IS NOT NULL THEN
    PERFORM 1
    FROM public.job_tasks task
    WHERE task.id = ANY(p_task_ids)
    ORDER BY task.id
    FOR UPDATE;

    IF cardinality(p_task_ids) IS DISTINCT FROM (
      SELECT count(*)::integer
      FROM public.job_tasks task
      WHERE task.id = ANY(p_task_ids)
        AND task.job_id = p_job_id
        AND task.appointment_id IS NULL
    ) THEN
      RAISE EXCEPTION
        'create_appointment_with_crew: task IDs must be unique, unassigned, and belong to the appointment job'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.appointments (
    job_id,
    title,
    date,
    time_start,
    time_end,
    type,
    status,
    notes,
    created_by,
    kind,
    is_private,
    notify_client
  )
  VALUES (
    p_job_id,
    btrim(p_title),
    p_date,
    p_time_start,
    p_time_end,
    COALESCE(
      NULLIF(btrim(p_type), ''),
      'mitigation'
    )::public.appointment_type,
    COALESCE(
      NULLIF(btrim(p_status), ''),
      'scheduled'
    )::public.appointment_status,
    NULLIF(btrim(COALESCE(p_notes, '')), ''),
    v_actor_id,
    p_kind,
    p_is_private,
    p_notify_client
  )
  RETURNING *
  INTO v_appointment;

  PERFORM *
  FROM public.sync_appointment_crew(
    v_appointment.id,
    COALESCE(p_crew, '[]'::jsonb)
  );

  IF p_task_ids IS NOT NULL THEN
    PERFORM public.assign_tasks_to_appointment(
      v_appointment.id,
      p_task_ids
    );
  END IF;

  INSERT INTO public.job_tasks (
    job_id,
    appointment_id,
    title,
    phase_name,
    phase_color,
    is_completed
  )
  SELECT
    v_appointment.job_id,
    v_appointment.id,
    btrim(template ->> 'title'),
    NULLIF(btrim(COALESCE(template ->> 'phase_name', '')), ''),
    NULLIF(btrim(COALESCE(template ->> 'phase_color', '')), ''),
    false
  FROM jsonb_array_elements(
    COALESCE(p_task_templates, '[]'::jsonb)
  ) template;

  RETURN jsonb_build_object(
    'id', v_appointment.id,
    'job_id', v_appointment.job_id,
    'kind', v_appointment.kind,
    'date', v_appointment.date,
    'time_start', v_appointment.time_start,
    'time_end', v_appointment.time_end,
    'title', v_appointment.title,
    'status', v_appointment.status
  );
END;
$$;


ALTER FUNCTION "public"."create_appointment_with_crew"("p_title" "text", "p_date" "date", "p_job_id" "uuid", "p_kind" "text", "p_time_start" time without time zone, "p_time_end" time without time zone, "p_type" "text", "p_status" "text", "p_notes" "text", "p_is_private" boolean, "p_notify_client" boolean, "p_crew" "jsonb", "p_task_ids" "uuid"[], "p_task_templates" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_appointment_with_crew"("p_title" "text", "p_date" "date", "p_job_id" "uuid", "p_kind" "text", "p_time_start" time without time zone, "p_time_end" time without time zone, "p_type" "text", "p_status" "text", "p_notes" "text", "p_is_private" boolean, "p_notify_client" boolean, "p_crew" "jsonb", "p_task_ids" "uuid"[], "p_task_templates" "jsonb", "p_actor_id" "uuid") IS 'UPR appointment crew atomic save/audit repair v1: atomic appointment, crew, assigned-task, and cloned-task creation';



CREATE OR REPLACE FUNCTION "public"."create_draft_invoice_for_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_enabled TEXT;
BEGIN
  SELECT value INTO v_enabled FROM integration_config WHERE key = 'auto_draft_invoices';
  IF v_enabled IS DISTINCT FROM 'true' THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM invoices WHERE job_id = NEW.id) THEN RETURN NEW; END IF;
  INSERT INTO invoices (job_id, contact_id, invoice_number, status, invoice_type)
  VALUES (NEW.id, NEW.primary_contact_id, generate_invoice_number(), 'draft', 'standard');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_draft_invoice_for_job"() OWNER TO "postgres";


