COMMENT ON TABLE "public"."estimates" IS 'No browser-role grant for `anon`. The public e-sign flow reads through token-constrained SECURITY DEFINER RPCs (get_sign_request_by_token), never through a browser table grant, so this revoke does not touch signing.';



CREATE OR REPLACE FUNCTION "public"."create_estimate_for_contact"("p_contact_id" "uuid", "p_intended_division" "text" DEFAULT 'water'::"text", "p_estimate_type" "text" DEFAULT 'initial'::"text", "p_property_address" "text" DEFAULT NULL::"text", "p_property_city" "text" DEFAULT NULL::"text", "p_property_state" "text" DEFAULT NULL::"text", "p_property_zip" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."estimates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row public.estimates;
  v_created_by uuid;
BEGIN
  IF auth.role() IS NOT DISTINCT FROM 'service_role' THEN
    v_created_by:=p_created_by;
  ELSE
    IF auth.role() IS DISTINCT FROM 'authenticated' OR NOT public.billing_edit_access() THEN
      RAISE EXCEPTION 'not_authorized: active internal billing editor required' USING ERRCODE='42501';
    END IF;
    SELECT e.id INTO v_created_by
      FROM public.employees e
     WHERE e.auth_user_id=auth.uid()
       AND e.is_active IS TRUE
       AND e.is_external IS FALSE
       AND e.role::text IN ('admin','office','project_manager');
    IF v_created_by IS NULL THEN
      RAISE EXCEPTION 'not_authorized: active internal billing editor required' USING ERRCODE='42501';
    END IF;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.contacts WHERE id=p_contact_id) THEN
    RAISE EXCEPTION 'Contact % not found',p_contact_id;
  END IF;
  INSERT INTO public.estimates(contact_id,estimate_number,estimate_type,status,amount,subtotal,
    intended_division,property_address,property_city,property_state,property_zip,created_by)
  VALUES(p_contact_id,public.generate_estimate_number(),COALESCE(p_estimate_type,'initial'),'draft',0,0,
    COALESCE(p_intended_division,'water'),p_property_address,p_property_city,p_property_state,p_property_zip,v_created_by)
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."create_estimate_for_contact"("p_contact_id" "uuid", "p_intended_division" "text", "p_estimate_type" "text", "p_property_address" "text", "p_property_city" "text", "p_property_state" "text", "p_property_zip" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_estimate_for_job"("p_job_id" "uuid", "p_estimate_type" "text" DEFAULT 'initial'::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."estimates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row estimates;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.billing_edit_access() THEN
    RAISE EXCEPTION 'not_authorized: active internal billing editor required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO estimates (job_id, contact_id, estimate_number, estimate_type, status, amount, subtotal, created_by)
  SELECT j.id, j.primary_contact_id, generate_estimate_number(),
         COALESCE(p_estimate_type, 'initial'), 'draft', 0, 0, p_created_by
  FROM jobs j WHERE j.id = p_job_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Job % not found', p_job_id; END IF;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."create_estimate_for_job"("p_job_id" "uuid", "p_estimate_type" "text", "p_created_by" "uuid") OWNER TO "postgres";


