CREATE TABLE IF NOT EXISTS "public"."invoices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "contact_id" "uuid",
    "invoice_number" "text" NOT NULL,
    "invoice_type" "text" DEFAULT 'standard'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "subtotal" numeric DEFAULT 0 NOT NULL,
    "tax" numeric DEFAULT 0,
    "total" numeric DEFAULT 0 NOT NULL,
    "amount_paid" numeric DEFAULT 0 NOT NULL,
    "balance_due" numeric GENERATED ALWAYS AS (("total" - "amount_paid")) STORED,
    "invoice_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "due_date" "date" DEFAULT (("now"() AT TIME ZONE 'America/Denver'::"text"))::"date",
    "sent_at" timestamp with time zone,
    "paid_at" timestamp with time zone,
    "sent_to_email" "text",
    "sent_to_phone" "text",
    "pdf_url" "text",
    "estimate_id" "uuid",
    "notes" "text",
    "internal_notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "original_total" numeric,
    "adjusted_total" numeric,
    "adjustment_reason" "text",
    "adjusted_at" timestamp with time zone,
    "adjusted_by" "uuid",
    "insurance_responsibility" numeric DEFAULT 0,
    "deductible_amount" numeric DEFAULT 0,
    "depreciation_withheld" numeric DEFAULT 0,
    "depreciation_released" numeric DEFAULT 0,
    "homeowner_responsibility" numeric DEFAULT 0,
    "insurance_paid" numeric DEFAULT 0,
    "homeowner_paid" numeric DEFAULT 0,
    "billed_to" "text" DEFAULT 'insurance'::"text",
    "carrier_name" "text",
    "claim_number" "text",
    "policy_number" "text",
    "qbo_invoice_id" "text",
    "qbo_synced_at" timestamp with time zone,
    "qbo_sync_error" "text",
    "stripe_payment_link_url" "text",
    "stripe_checkout_session_id" "text",
    "stripe_payment_link_created_at" timestamp with time zone,
    "qbo_doc_number" "text",
    "qbo_emailed_at" timestamp with time zone,
    "qbo_email_status" "text",
    "xactimate_meta" "jsonb",
    "locked" boolean DEFAULT false NOT NULL,
    "customer_message" "text",
    "send_cc_email" "text",
    "qbo_bill_email" "text",
    "qbo_email_checked_at" timestamp with time zone,
    CONSTRAINT "invoices_billed_to_check" CHECK (("billed_to" = ANY (ARRAY['insurance'::"text", 'homeowner'::"text", 'property_manager'::"text", 'both'::"text", 'other'::"text"]))),
    CONSTRAINT "invoices_invoice_type_check" CHECK (("invoice_type" = ANY (ARRAY['standard'::"text", 'progress'::"text", 'final'::"text", 'supplement'::"text", 'deductible'::"text", 'depreciation_release'::"text"]))),
    CONSTRAINT "invoices_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'saved'::"text", 'sent'::"text", 'viewed'::"text", 'partially_paid'::"text", 'paid'::"text", 'overdue'::"text", 'voided'::"text", 'disputed'::"text"])))
);


ALTER TABLE "public"."invoices" OWNER TO "postgres";


COMMENT ON TABLE "public"."invoices" IS 'No browser-role grant for `anon`. The anon key ships inside the public browser bundle; RLS already refused these rows for want of an anon policy, and the grant was the dangerous half of that pair. Logged-in access is `authenticated` via RLS; Workers use the privileged server-side role.';



COMMENT ON COLUMN "public"."invoices"."qbo_emailed_at" IS 'When QuickBooks emailed this invoice to the customer (via /api/qbo-invoice action:send).';



COMMENT ON COLUMN "public"."invoices"."qbo_email_status" IS 'QuickBooks EmailStatus (NotSet | NeedToSend | EmailSent) as UPR last observed it -- from a UPR-triggered send OR from any QBO invoice read. Paired with qbo_email_checked_at.';



COMMENT ON COLUMN "public"."invoices"."xactimate_meta" IS 'AI Xactimate import recap (billable, totals incl. paid_when_incurred, reconcile checks, work_type, imported_at) written by the analyze-xactimate worker; rendered as the persistent recap banner in InvoiceEditor.';



COMMENT ON COLUMN "public"."invoices"."locked" IS 'Manual, opt-in read-only flag. When true the billing UI disables all edits for this invoice. Never set automatically — only by explicit manual update.';



COMMENT ON COLUMN "public"."invoices"."customer_message" IS 'Staff-authored message shown to the customer on the QuickBooks invoice. NULL keeps the derived job/claim memo.';



COMMENT ON COLUMN "public"."invoices"."send_cc_email" IS 'Optional single CC address applied as BillEmailCc before the QuickBooks send. NULL means no CC.';



COMMENT ON COLUMN "public"."invoices"."qbo_bill_email" IS 'BillEmail.Address on the QuickBooks invoice as UPR last observed it -- the address QuickBooks actually emails. May differ from the UPR contact email; the invoice surfaces flag that.';



COMMENT ON COLUMN "public"."invoices"."qbo_email_checked_at" IS 'When UPR last read EmailStatus/BillEmail off the QuickBooks invoice. NULL means never observed, which is a different answer from "observed as not emailed".';



CREATE OR REPLACE FUNCTION "public"."create_invoice_for_job"("p_job_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."invoices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row public.invoices; v_created_by uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.billing_edit_access() THEN RAISE EXCEPTION 'not_authorized: active internal billing editor required' USING ERRCODE='42501'; END IF;
  IF auth.role() = 'service_role' THEN
    v_created_by := p_created_by;
  ELSE
    SELECT e.id INTO v_created_by FROM public.employees e
    WHERE e.auth_user_id=auth.uid() AND e.is_active AND NOT COALESCE(e.is_external,false)
    LIMIT 1;
    IF v_created_by IS NULL THEN RAISE EXCEPTION 'not_authorized: active internal employee required' USING ERRCODE='42501'; END IF;
  END IF;
  PERFORM 1 FROM public.jobs WHERE id=p_job_id FOR UPDATE;
  SELECT * INTO v_row FROM public.invoices WHERE job_id=p_job_id ORDER BY created_at LIMIT 1;
  IF FOUND THEN RETURN v_row; END IF;
  INSERT INTO public.invoices (job_id,contact_id,invoice_number,status,invoice_type,created_by)
  SELECT j.id,j.primary_contact_id,public.generate_invoice_number(),'draft','standard',v_created_by FROM public.jobs j WHERE j.id=p_job_id RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."create_invoice_for_job"("p_job_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_job_with_contact"("p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_contact_name" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_role" "text" DEFAULT 'homeowner'::"text", "p_billing_address" "text" DEFAULT NULL::"text", "p_billing_city" "text" DEFAULT NULL::"text", "p_billing_state" "text" DEFAULT NULL::"text", "p_billing_zip" "text" DEFAULT NULL::"text", "p_insurance_carrier" "text" DEFAULT NULL::"text", "p_policy_number" "text" DEFAULT NULL::"text", "p_division" "text" DEFAULT 'water'::"text", "p_source" "text" DEFAULT 'insurance'::"text", "p_priority" integer DEFAULT 3, "p_type_of_loss" "text" DEFAULT NULL::"text", "p_date_of_loss" "date" DEFAULT NULL::"date", "p_target_completion" "date" DEFAULT NULL::"date", "p_address" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_zip" "text" DEFAULT NULL::"text", "p_insurance_company" "text" DEFAULT NULL::"text", "p_claim_number" "text" DEFAULT NULL::"text", "p_job_policy_number" "text" DEFAULT NULL::"text", "p_adjuster_name" "text" DEFAULT NULL::"text", "p_adjuster_phone" "text" DEFAULT NULL::"text", "p_adjuster_email" "text" DEFAULT NULL::"text", "p_cat_code" "text" DEFAULT NULL::"text", "p_project_manager_id" "uuid" DEFAULT NULL::"uuid", "p_lead_tech_id" "uuid" DEFAULT NULL::"uuid", "p_internal_notes" "text" DEFAULT NULL::"text", "p_existing_claim_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_contact_id uuid; v_claim_id uuid; v_job_id uuid;
  v_job jsonb; v_contact jsonb; v_claim_number text; v_loss_type text; v_has_any_address boolean;
BEGIN
  IF p_contact_id IS NOT NULL THEN
    v_contact_id := p_contact_id;
    UPDATE contacts SET billing_address=COALESCE(billing_address,p_billing_address),billing_city=COALESCE(billing_city,p_billing_city),
      billing_state=COALESCE(billing_state,p_billing_state),billing_zip=COALESCE(billing_zip,p_billing_zip),updated_at=now()
    WHERE id=v_contact_id AND billing_address IS NULL AND p_billing_address IS NOT NULL;
  ELSE
    INSERT INTO contacts(name,phone,email,role,billing_address,billing_city,billing_state,billing_zip,insurance_carrier,policy_number,preferred_contact_method,preferred_language,opt_in_status,dnd,created_at,updated_at)
    VALUES(p_contact_name,p_contact_phone,NULLIF(p_contact_email,''),COALESCE(p_contact_role,'homeowner'),NULLIF(p_billing_address,''),NULLIF(p_billing_city,''),NULLIF(p_billing_state,''),NULLIF(p_billing_zip,''),NULLIF(p_insurance_carrier,''),NULLIF(p_policy_number,''),'sms','en',false,false,now(),now())
    RETURNING id INTO v_contact_id;
  END IF;

  v_loss_type := CASE
    WHEN p_type_of_loss ILIKE '%water%' OR p_division='water' THEN 'water'
    WHEN p_type_of_loss ILIKE '%fire%' OR p_division='fire' THEN 'fire'
    WHEN p_type_of_loss ILIKE '%mold%' OR p_division='mold' THEN 'mold'
    WHEN p_type_of_loss ILIKE '%storm%' OR p_type_of_loss ILIKE '%wind%' THEN 'storm'
    WHEN p_type_of_loss ILIKE '%sewer%' THEN 'sewer'
    WHEN p_division='contents' THEN 'contents' ELSE 'water' END;

  IF p_existing_claim_id IS NOT NULL THEN
    v_claim_id := p_existing_claim_id;
    SELECT claim_number INTO v_claim_number FROM claims WHERE id = v_claim_id;
  ELSE
    v_claim_number := 'CLM-'||to_char(now(),'YYMM')||'-'||lpad(nextval('claim_number_seq')::text,3,'0');
    INSERT INTO claims(claim_number,insurance_claim_number,contact_id,insurance_carrier,policy_number,date_of_loss,loss_address,loss_city,loss_state,loss_zip,loss_type,status,created_by,created_at,updated_at)
    VALUES(v_claim_number,NULLIF(p_claim_number,''),v_contact_id,NULLIF(p_insurance_company,''),NULLIF(p_job_policy_number,''),p_date_of_loss,NULLIF(p_address,''),NULLIF(p_city,''),NULLIF(p_state,''),NULLIF(p_zip,''),v_loss_type,'open',p_created_by,now(),now())
    RETURNING id INTO v_claim_id;
  END IF;

  INSERT INTO jobs(division,source,phase,priority,status,insured_name,client_phone,client_email,address,city,state,zip,type_of_loss,date_of_loss,target_completion,insurance_company,claim_number,policy_number,adjuster_name,adjuster_phone,adjuster_email,cat_code,project_manager_id,lead_tech_id,internal_notes,primary_contact_id,claim_id,created_at,updated_at)
  VALUES(p_division::job_division, p_source::job_source, 'job_received',p_priority,'active',
    COALESCE(p_contact_name,(SELECT name FROM contacts WHERE id=v_contact_id)),
    COALESCE(p_contact_phone,(SELECT phone FROM contacts WHERE id=v_contact_id)),
    COALESCE(p_contact_email,(SELECT email FROM contacts WHERE id=v_contact_id)),
    NULLIF(p_address,''),NULLIF(p_city,''),NULLIF(p_state,''),NULLIF(p_zip,''),
    NULLIF(p_type_of_loss,''),p_date_of_loss,p_target_completion,
    NULLIF(p_insurance_company,''),NULLIF(p_claim_number,''),NULLIF(p_job_policy_number,''),
    NULLIF(p_adjuster_name,''),NULLIF(p_adjuster_phone,''),NULLIF(p_adjuster_email,''),NULLIF(p_cat_code,''),
    p_project_manager_id,p_lead_tech_id,NULLIF(p_internal_notes,''),
    v_contact_id,v_claim_id,now(),now())
  RETURNING id INTO v_job_id;

  INSERT INTO contact_jobs(contact_id,job_id,role,is_primary) VALUES(v_contact_id,v_job_id,'primary_client',true);

  IF p_address IS NOT NULL AND p_address!='' THEN
    IF NOT EXISTS(SELECT 1 FROM contact_addresses ca WHERE ca.contact_id=v_contact_id AND ca.address=p_address) THEN
      SELECT EXISTS(SELECT 1 FROM contact_addresses WHERE contact_id=v_contact_id) INTO v_has_any_address;
      INSERT INTO contact_addresses(contact_id,label,address,city,state,zip,is_billing)
      VALUES(v_contact_id,'service',p_address,NULLIF(p_city,''),NULLIF(p_state,''),NULLIF(p_zip,''),NOT v_has_any_address);
      IF NOT v_has_any_address THEN
        UPDATE contacts SET billing_address=p_address,billing_city=NULLIF(p_city,''),billing_state=NULLIF(p_state,''),billing_zip=NULLIF(p_zip,''),updated_at=now()
        WHERE id=v_contact_id AND billing_address IS NULL;
      END IF;
    END IF;
  END IF;

  SELECT to_jsonb(j) INTO v_job FROM(SELECT * FROM jobs WHERE id=v_job_id)j;
  SELECT to_jsonb(c) INTO v_contact FROM(SELECT * FROM contacts WHERE id=v_contact_id)c;
  RETURN jsonb_build_object('job',v_job,'contact',v_contact,'claim_id',v_claim_id,'claim_number',v_claim_number);
END;$$;


ALTER FUNCTION "public"."create_job_with_contact"("p_contact_id" "uuid", "p_contact_name" "text", "p_contact_phone" "text", "p_contact_email" "text", "p_contact_role" "text", "p_billing_address" "text", "p_billing_city" "text", "p_billing_state" "text", "p_billing_zip" "text", "p_insurance_carrier" "text", "p_policy_number" "text", "p_division" "text", "p_source" "text", "p_priority" integer, "p_type_of_loss" "text", "p_date_of_loss" "date", "p_target_completion" "date", "p_address" "text", "p_city" "text", "p_state" "text", "p_zip" "text", "p_insurance_company" "text", "p_claim_number" "text", "p_job_policy_number" "text", "p_adjuster_name" "text", "p_adjuster_phone" "text", "p_adjuster_email" "text", "p_cat_code" "text", "p_project_manager_id" "uuid", "p_lead_tech_id" "uuid", "p_internal_notes" "text", "p_existing_claim_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."inbound_leads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "contact_id" "uuid",
    "source_type" "text" NOT NULL,
    "callrail_id" "text" NOT NULL,
    "tracking_number" "text",
    "caller_number" "text",
    "duration_sec" integer,
    "spam_flag" boolean DEFAULT false NOT NULL,
    "source" "text",
    "medium" "text",
    "campaign" "text",
    "recording_url" "text",
    "transcription" "text",
    "form_data" "jsonb",
    "lead_status" "text" DEFAULT 'new'::"text" NOT NULL,
    "value" numeric,
    "direction" "text",
    "occurred_at" timestamp with time zone,
    "raw_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "transcription_source" "text",
    "transcribed_at" timestamp with time zone,
    "transcript_analysis" "jsonb",
    "caller_name" "text",
    "lost_reason" "text",
    "lead_score" integer,
    "merged_into_lead_id" "uuid",
    "answered" boolean GENERATED ALWAYS AS (
CASE
    WHEN (("raw_payload" ? 'answered'::"text") AND ("lower"(("raw_payload" ->> 'answered'::"text")) = 'true'::"text")) THEN true
    WHEN (("raw_payload" ? 'answered'::"text") AND ("lower"(("raw_payload" ->> 'answered'::"text")) = 'false'::"text")) THEN false
    ELSE NULL::boolean
END) STORED,
    "claim_id" "uuid",
    "value_source" "text",
    CONSTRAINT "inbound_leads_source_type_check" CHECK (("source_type" = ANY (ARRAY['call'::"text", 'form'::"text"]))),
    CONSTRAINT "inbound_leads_value_source_check" CHECK ((("value_source" IS NULL) OR ("value_source" = ANY (ARRAY['manual'::"text", 'auto'::"text"]))))
);


ALTER TABLE "public"."inbound_leads" OWNER TO "postgres";


COMMENT ON COLUMN "public"."inbound_leads"."answered" IS 'Provider-agnostic call outcome: true = answered, false = confirmed unanswered, NULL = unknown. Derived from raw_payload.answered by string compare (never a cast). Unknown must never be treated as missed. Consumed by the missed-call text-back trigger; countable-lead reporting still uses crm_call_is_answered().';



COMMENT ON COLUMN "public"."inbound_leads"."claim_id" IS 'The claim that originated from this lead. Set by crm_attach_claim_to_lead on claim insert; correctable by staff. NULL = never became work.';



COMMENT ON COLUMN "public"."inbound_leads"."value_source" IS 'manual = a human typed the value and automation must never overwrite it. auto = owned by crm_recompute_lead_value. NULL = unset.';



CREATE OR REPLACE FUNCTION "public"."create_manual_lead"("p_phone" "text", "p_name" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'Manual entry'::"text", "p_value" numeric DEFAULT NULL::numeric, "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id     uuid;
  v_phone      text := nullif(btrim(p_phone), '');
  v_name       text := nullif(btrim(p_name), '');
  v_contact_id uuid;
  v_row        inbound_leads;
BEGIN
  IF v_phone IS NULL THEN
    RAISE EXCEPTION 'a phone number is required to add a lead';
  END IF;

  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  SELECT id INTO v_contact_id FROM contacts WHERE phone = v_phone LIMIT 1;
  IF v_contact_id IS NULL THEN
    INSERT INTO contacts (phone, name) VALUES (v_phone, v_name)
    RETURNING id INTO v_contact_id;
  ELSIF v_name IS NOT NULL THEN
    UPDATE contacts SET name = v_name, updated_at = now()
     WHERE id = v_contact_id AND (name IS NULL OR btrim(name) = '');
  END IF;

  INSERT INTO inbound_leads (
    org_id, contact_id, source_type, callrail_id, caller_number,
    source, lead_status, value, spam_flag, direction, occurred_at, raw_payload
  ) VALUES (
    v_org_id, v_contact_id, 'form', 'manual:' || gen_random_uuid()::text, v_phone,
    COALESCE(nullif(btrim(p_source), ''), 'Manual entry'), 'new', p_value, false,
    'manual', now(), jsonb_build_object('manual', true, 'created_by', p_created_by)
  )
  RETURNING * INTO v_row;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_created_manual', 'inbound_lead', v_row.id, p_created_by,
          jsonb_build_object('source', v_row.source, 'contact_id', v_contact_id));

  RETURN v_row;
END;
$$;


