CREATE OR REPLACE FUNCTION "public"."create_room"("p_job_id" "uuid", "p_name" "text", "p_area_sqft" numeric DEFAULT NULL::numeric, "p_ceiling_height_ft" numeric DEFAULT NULL::numeric, "p_sort_order" integer DEFAULT 0, "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."rooms"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_claim_id UUID;
  result rooms;
BEGIN
  SELECT j.claim_id INTO v_claim_id FROM jobs j WHERE j.id = p_job_id;
  IF v_claim_id IS NULL THEN
    RAISE EXCEPTION 'create_room: job % not found or has no claim', p_job_id;
  END IF;
  INSERT INTO rooms (claim_id, name, area_sqft, ceiling_height_ft, sort_order, client_id, created_by)
  VALUES (v_claim_id, p_name, p_area_sqft, p_ceiling_height_ft, p_sort_order, p_client_id, p_created_by)
  ON CONFLICT (client_id) DO UPDATE
    SET name = EXCLUDED.name,
        area_sqft = EXCLUDED.area_sqft,
        ceiling_height_ft = EXCLUDED.ceiling_height_ft,
        sort_order = EXCLUDED.sort_order
  RETURNING * INTO result;
  RETURN result;
END;
$$;


