CREATE OR REPLACE FUNCTION "public"."create_sign_request"("p_job_id" "uuid", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_doc_type" "text" DEFAULT 'coc'::"text", "p_signer_name" "text" DEFAULT NULL::"text", "p_signer_email" "text" DEFAULT NULL::"text", "p_sent_by" "uuid" DEFAULT NULL::"uuid", "p_divisions" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_token uuid;
  v_id    uuid;
  v_result jsonb;
BEGIN
  -- Both id and token are uuid — gen_random_uuid() is the right call
  v_id    := gen_random_uuid();
  v_token := gen_random_uuid();

  INSERT INTO sign_requests (
    id, token, job_id, contact_id, doc_type,
    signer_name, signer_email, sent_by, divisions,
    status, sent_at, expires_at
  ) VALUES (
    v_id, v_token, p_job_id, p_contact_id, p_doc_type,
    p_signer_name, p_signer_email, p_sent_by, p_divisions,
    'pending', now(),
    now() + INTERVAL '30 days'
  );

  SELECT jsonb_build_object(
    'id',         v_id,
    'token',      v_token,
    'job_id',     p_job_id,
    'doc_type',   p_doc_type,
    'divisions',  p_divisions,
    'status',     'pending',
    'expires_at', (now() + INTERVAL '30 days')
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_sign_request"("p_job_id" "uuid", "p_contact_id" "uuid", "p_doc_type" "text", "p_signer_name" "text", "p_signer_email" "text", "p_sent_by" "uuid", "p_divisions" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_advance_lead_if_forward"("p_lead_id" "uuid", "p_stage_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canonical_id      uuid;
  v_merged_into       uuid;
  v_hops              integer := 0;
  v_lead              record;
  v_current_sort      integer;
  v_current_terminal  boolean;
  v_current_recover   boolean;
  v_stage_id          uuid;
  v_target_sort       integer;
BEGIN
  IF p_lead_id IS NULL THEN
    RETURN;
  END IF;

  v_canonical_id := p_lead_id;
  LOOP
    SELECT merged_into_lead_id INTO v_merged_into
      FROM inbound_leads WHERE id = v_canonical_id;
    EXIT WHEN v_merged_into IS NULL OR NOT FOUND OR v_hops >= 5;
    v_canonical_id := v_merged_into;
    v_hops := v_hops + 1;
  END LOOP;

  SELECT il.id, il.org_id, il.spam_flag, lps.stage_id AS current_stage_id
    INTO v_lead
    FROM inbound_leads il
    LEFT JOIN lead_pipeline_stage lps ON lps.lead_id = il.id
   WHERE il.id = v_canonical_id;

  IF NOT FOUND OR COALESCE(v_lead.spam_flag, false) THEN
    RETURN;
  END IF;

  v_current_sort := -1;
  v_current_terminal := false;
  v_current_recover := false;
  IF v_lead.current_stage_id IS NOT NULL THEN
    SELECT sort_order, (is_won OR is_lost), COALESCE(is_recoverable, false)
      INTO v_current_sort, v_current_terminal, v_current_recover
      FROM pipeline_stages
     WHERE id = v_lead.current_stage_id;
  END IF;

  IF COALESCE(v_current_terminal, false) AND NOT COALESCE(v_current_recover, false) THEN
    RETURN;
  END IF;

  SELECT id, sort_order INTO v_stage_id, v_target_sort
    FROM pipeline_stages
   WHERE org_id = v_lead.org_id AND name = p_stage_name
   LIMIT 1;

  IF v_stage_id IS NULL OR v_stage_id = v_lead.current_stage_id THEN
    RETURN;
  END IF;

  IF v_target_sort <= COALESCE(v_current_sort, -1) THEN
    RETURN;
  END IF;

  PERFORM move_lead_to_stage(v_canonical_id, v_stage_id, NULL, NULL);
END;
$$;


ALTER FUNCTION "public"."crm_advance_lead_if_forward"("p_lead_id" "uuid", "p_stage_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_attach_claim_to_lead"("p_claim_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_claim   claims;
  v_lead_id uuid;
BEGIN
  SELECT * INTO v_claim FROM claims WHERE id = p_claim_id;
  IF NOT FOUND OR v_claim.contact_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT il.id INTO v_lead_id
    FROM inbound_leads il
   WHERE il.contact_id = v_claim.contact_id
     AND il.claim_id IS NULL
     AND COALESCE(il.spam_flag, false) = false
     AND il.merged_into_lead_id IS NULL
     AND COALESCE(il.occurred_at, il.created_at) <= COALESCE(v_claim.created_at, now())
   ORDER BY COALESCE(il.occurred_at, il.created_at) DESC
   LIMIT 1;

  IF v_lead_id IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE inbound_leads
     SET claim_id = p_claim_id, updated_at = now()
   WHERE id = v_lead_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_claim_attached', 'inbound_lead', v_lead_id,
          jsonb_build_object('claim_id', p_claim_id, 'contact_id', v_claim.contact_id));

  RETURN v_lead_id;
END;
$$;


ALTER FUNCTION "public"."crm_attach_claim_to_lead"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_auto_advance_leads"("p_contact_id" "uuid", "p_stage_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead   record;
  v_is_won boolean;
  v_stage_id uuid;
BEGIN
  IF p_contact_id IS NULL THEN
    RETURN;
  END IF;

  FOR v_lead IN
    SELECT il.id, il.org_id, lps.stage_id AS current_stage_id
    FROM inbound_leads il
    LEFT JOIN lead_pipeline_stage lps ON lps.lead_id = il.id
    WHERE il.contact_id = p_contact_id
      AND il.spam_flag = false
      AND il.merged_into_lead_id IS NULL
  LOOP
    v_is_won := false;
    IF v_lead.current_stage_id IS NOT NULL THEN
      SELECT is_won INTO v_is_won FROM pipeline_stages WHERE id = v_lead.current_stage_id;
    END IF;
    IF COALESCE(v_is_won, false) THEN
      CONTINUE;
    END IF;

    SELECT id INTO v_stage_id
    FROM pipeline_stages
    WHERE org_id = v_lead.org_id AND name = p_stage_name
    LIMIT 1;
    IF v_stage_id IS NULL OR v_stage_id = v_lead.current_stage_id THEN
      CONTINUE;
    END IF;

    PERFORM move_lead_to_stage(v_lead.id, v_stage_id, NULL, NULL);
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."crm_auto_advance_leads"("p_contact_id" "uuid", "p_stage_name" "text") OWNER TO "postgres";


