    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "phone" "text" NOT NULL,
    "name" "text",
    "email" "text",
    "company" "text",
    "role" "text" DEFAULT 'homeowner'::"text",
    "opt_in_status" boolean DEFAULT false NOT NULL,
    "opt_in_source" "text",
    "opt_in_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "dnd" boolean DEFAULT false NOT NULL,
    "dnd_at" timestamp with time zone,
    "opt_out_at" timestamp with time zone,
    "opt_out_reason" "text",
    "billing_address" "text",
    "billing_city" "text",
    "billing_state" "text",
    "billing_zip" "text",
    "phone_secondary" "text",
    "preferred_contact_method" "text" DEFAULT 'sms'::"text",
    "insurance_carrier" "text",
    "policy_number" "text",
    "claim_number" "text",
    "referral_source" "text",
    "tags" "jsonb" DEFAULT '[]'::"jsonb",
    "desk_phone" "text",
    "desk_extension" "text",
    "territory" "text",
    "relationship_notes" "text",
    "trade_specialty" "text",
    "payment_terms" "text" DEFAULT 'net_30'::"text",
    "coi_expiration" "date",
    "w9_on_file" boolean DEFAULT false,
    "preferred_language" "text" DEFAULT 'en'::"text",
    "qbo_customer_id" "text",
    "qbo_synced_at" timestamp with time zone,
    "qbo_sync_error" "text",
    "owner_id" "uuid",
    "lifecycle_status" "text",
    CONSTRAINT "contacts_preferred_method_check" CHECK (("preferred_contact_method" = ANY (ARRAY['sms'::"text", 'call'::"text", 'email'::"text"]))),
    CONSTRAINT "contacts_role_check" CHECK (("role" = ANY (ARRAY['homeowner'::"text", 'adjuster'::"text", 'subcontractor'::"text", 'property_manager'::"text", 'agent'::"text", 'mortgage_co'::"text", 'tenant'::"text", 'other'::"text", 'vendor'::"text", 'referral_partner'::"text", 'insurance_rep'::"text", 'broker'::"text"])))
);


