COMMENT ON COLUMN "public"."contacts"."dnd" IS 'Do Not Disturb — blocks all outbound messaging. Twilio compliance.';



COMMENT ON COLUMN "public"."contacts"."dnd_at" IS 'Timestamp when DND was last toggled on/off.';



COMMENT ON COLUMN "public"."contacts"."opt_out_at" IS 'When the contact opted out. NULL = still opted in.';



COMMENT ON COLUMN "public"."contacts"."opt_out_reason" IS 'How they opted out: stop_keyword, manual, complaint.';



CREATE OR REPLACE FUNCTION "public"."crm_auto_qualify_contact"("p_lead_id" "uuid") RETURNS "public"."contacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead        inbound_leads;
  v_name        text;
  v_phone       text;
  v_digits      text;
  v_contact_id  uuid;
  v_match_count int;
  v_row         contacts;
BEGIN
  SELECT * INTO v_lead FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  IF v_lead.contact_id IS NOT NULL THEN
    SELECT * INTO v_row FROM contacts WHERE id = v_lead.contact_id;
    RETURN v_row;
  END IF;

  v_name := NULLIF(btrim(v_lead.caller_name), '');
  IF v_name IS NULL OR position(' ' IN v_name) = 0 THEN
    v_name := NULLIF(btrim(v_lead.transcript_analysis ->> 'customer_full_name'), '');
  END IF;
  IF v_name IS NULL OR position(' ' IN v_name) = 0 THEN
    RETURN NULL;
  END IF;

  v_phone := NULLIF(btrim(v_lead.caller_number), '');
  IF v_phone IS NULL THEN
    RETURN NULL;
  END IF;
  v_digits := regexp_replace(v_phone, '\D', '', 'g');
  IF length(v_digits) < 10 THEN
    RETURN NULL;
  END IF;

  IF COALESCE(v_lead.spam_flag, false) THEN
    RETURN NULL;
  END IF;
  IF COALESCE((v_lead.transcript_analysis ->> 'is_customer_inquiry')::boolean, false) IS NOT TRUE THEN
    RETURN NULL;
  END IF;
  IF COALESCE(v_lead.transcript_analysis ->> 'service_match', '') <> 'in_scope' THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_match_count
  FROM contacts
  WHERE phone IS NOT NULL
    AND length(regexp_replace(phone, '\D', '', 'g')) >= 10
    AND right(regexp_replace(phone, '\D', '', 'g'), 10) = right(v_digits, 10);

  IF v_match_count > 1 THEN
    RETURN NULL;
  ELSIF v_match_count = 1 THEN
    SELECT id INTO v_contact_id
    FROM contacts
    WHERE phone IS NOT NULL
      AND length(regexp_replace(phone, '\D', '', 'g')) >= 10
      AND right(regexp_replace(phone, '\D', '', 'g'), 10) = right(v_digits, 10);
  ELSE
    INSERT INTO contacts (phone, name)
    VALUES (v_phone, v_name)
    RETURNING id INTO v_contact_id;
  END IF;

  UPDATE inbound_leads
     SET contact_id = v_contact_id,
         updated_at = now()
   WHERE id = p_lead_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_auto_qualified_contact', 'inbound_lead', p_lead_id,
          jsonb_build_object('contact_id', v_contact_id, 'name', v_name));

  SELECT * INTO v_row FROM contacts WHERE id = v_contact_id;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."crm_auto_qualify_contact"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_backfill_lead_values"("p_days" integer DEFAULT 30) RETURNS TABLE("lead_id" "uuid", "claim_id" "uuid", "new_value" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead   record;
  v_result numeric;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM employees e
     WHERE e.auth_user_id = auth.uid() AND e.is_active AND NOT e.is_external
       AND e.role::text = 'admin'
  ) THEN
    RAISE EXCEPTION 'not authorized to backfill lead values';
  END IF;

  FOR v_lead IN
    SELECT il.id
      FROM inbound_leads il
      JOIN lead_pipeline_stage lps ON lps.lead_id = il.id
     WHERE COALESCE(il.spam_flag, false) = false
       AND il.merged_into_lead_id IS NULL
       AND COALESCE(il.value_source, 'auto') <> 'manual'
       AND COALESCE(il.occurred_at, il.created_at) >= now() - make_interval(days => GREATEST(p_days, 0))
  LOOP
    UPDATE inbound_leads il
       SET claim_id = (
             SELECT c.id FROM claims c
              WHERE c.contact_id = il.contact_id
              LIMIT 1
           )
     WHERE il.id = v_lead.id
       AND il.claim_id IS NULL
       AND il.contact_id IS NOT NULL
       AND (SELECT count(*) FROM claims c WHERE c.contact_id = il.contact_id) = 1;

    v_result := crm_recompute_lead_value(v_lead.id);
    IF v_result IS NOT NULL THEN
      RETURN QUERY
        SELECT il.id, il.claim_id, il.value
          FROM inbound_leads il WHERE il.id = v_lead.id AND il.value IS NOT NULL;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."crm_backfill_lead_values"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_backlink_leads_to_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_digits     text;
  v_suffix     text;
  v_old_digits text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.phone IS NOT DISTINCT FROM OLD.phone THEN
    RETURN NEW;
  END IF;

  -- Self-healing on a REAL phone change: release ONLY this trigger's own
  -- past links for the OLD number (system_events trail; human links never
  -- touched), audited as 'crm_lead_backlink_reverted'. Runs before the
  -- new-number validity checks so a phone corrected to garbage still heals.
  IF TG_OP = 'UPDATE' THEN
    v_old_digits := regexp_replace(COALESCE(OLD.phone, ''), '\D', '', 'g');
    IF length(v_old_digits) >= 10 THEN
      WITH reverted AS (
        UPDATE inbound_leads il
        SET contact_id = NULL, updated_at = now()
        WHERE il.contact_id = NEW.id
          AND il.caller_number IS NOT NULL
          AND length(regexp_replace(il.caller_number, '\D', '', 'g')) >= 10
          AND right(regexp_replace(il.caller_number, '\D', '', 'g'), 10) = right(v_old_digits, 10)
          AND EXISTS (
            SELECT 1 FROM system_events se
            WHERE se.event_type = 'crm_lead_backlinked'
              AND se.entity_type = 'inbound_lead'
              AND se.entity_id = il.id
              AND (se.payload->>'contact_id')::uuid = NEW.id
          )
        RETURNING il.id
      )
      INSERT INTO system_events (event_type, entity_type, entity_id, payload)
      SELECT 'crm_lead_backlink_reverted', 'inbound_lead', reverted.id,
             jsonb_build_object('contact_id', NEW.id, 'reason', 'contact_phone_changed')
      FROM reverted;
    END IF;
  END IF;

  v_digits := regexp_replace(COALESCE(NEW.phone, ''), '\D', '', 'g');
  IF length(v_digits) < 10 THEN
    RETURN NEW;
  END IF;
  v_suffix := right(v_digits, 10);

  IF EXISTS (
    SELECT 1 FROM contacts c
    WHERE c.id <> NEW.id
      AND c.phone IS NOT NULL
      AND length(regexp_replace(c.phone, '\D', '', 'g')) >= 10
      AND right(regexp_replace(c.phone, '\D', '', 'g'), 10) = v_suffix
  ) THEN
    RETURN NEW;
  END IF;

  WITH linked AS (
    UPDATE inbound_leads il
    SET contact_id = NEW.id, updated_at = now()
    WHERE il.contact_id IS NULL
      AND il.merged_into_lead_id IS NULL
      AND il.caller_number IS NOT NULL
      AND length(regexp_replace(il.caller_number, '\D', '', 'g')) >= 10
      AND right(regexp_replace(il.caller_number, '\D', '', 'g'), 10) = v_suffix
    RETURNING il.id
  )
  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  SELECT 'crm_lead_backlinked', 'inbound_lead', linked.id,
         jsonb_build_object('contact_id', NEW.id, 'via', 'trigger')
  FROM linked;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."crm_backlink_leads_to_contact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_call_is_answered"("p_raw_payload" "jsonb", "p_duration_sec" integer) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_raw_payload ? 'answered' THEN (p_raw_payload->>'answered')::boolean
    ELSE COALESCE(p_duration_sec, 0) > 0
  END;
$$;


ALTER FUNCTION "public"."crm_call_is_answered"("p_raw_payload" "jsonb", "p_duration_sec" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_channel_for_source"("p_source" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v     text := lower(trim(coalesce(p_source, '')));
  v_cat text;
BEGIN
  IF v = '' THEN RETURN 'other'; END IF;
  IF v LIKE '%facebook%' OR v LIKE '%instagram%' OR v LIKE '%meta ads%'
     OR v = 'meta' OR v = 'fb' OR v = 'ig' THEN
    RETURN 'meta_ads';
  END IF;
  IF v LIKE '%my business%' OR v LIKE '%business profile%' OR v LIKE '%gmb%'
     OR v LIKE '%seo%' OR v LIKE '%organic%' OR v LIKE '%website%' OR v LIKE '%nextdoor%' THEN
    RETURN 'organic';
  END IF;
  IF v LIKE '%google%' OR v LIKE '%adwords%' OR v LIKE '%lsa%' OR v LIKE '%local service%'
     OR v LIKE '%ppc%' OR v LIKE '%paid search%' OR v LIKE '%sem%' THEN
    RETURN 'google_ads';
  END IF;
  IF v LIKE '%insurance%' OR v LIKE '%adjuster%' OR v LIKE '%tpa%' OR v LIKE '%carrier%' THEN
    RETURN 'insurance';
  END IF;
  IF v LIKE '%referral%' OR v LIKE '%word of mouth%' OR v LIKE '%repeat%'
     OR v LIKE '%neighbor%' OR v LIKE '%friend%' THEN
    RETURN 'referral';
  END IF;
  SELECT category INTO v_cat
    FROM referral_sources
   WHERE lower(name) = v OR v LIKE '%' || lower(name) || '%'
   ORDER BY length(name) DESC
   LIMIT 1;
  IF v_cat IS NULL THEN RETURN 'other'; END IF;
  RETURN CASE v_cat
    WHEN 'insurance'   THEN 'insurance'
    WHEN 'digital'     THEN 'organic'
    WHEN 'traditional' THEN 'other'
    WHEN 'other'       THEN 'other'
    ELSE 'referral'
  END;
END;
$$;


ALTER FUNCTION "public"."crm_channel_for_source"("p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_contact_is_traced"("p_contact_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p_contact_id IS NOT NULL AND (
    EXISTS (SELECT 1 FROM lead_attribution la WHERE la.contact_id = p_contact_id)
    OR EXISTS (
      SELECT 1 FROM inbound_leads il
      WHERE il.contact_id = p_contact_id AND COALESCE(il.spam_flag, false) = false
    )
  );
$$;


ALTER FUNCTION "public"."crm_contact_is_traced"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_disqualify_lead_if_open"("p_lead_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead             record;
  v_current_terminal boolean;
  v_lost_stage_id    uuid;
BEGIN
  IF p_lead_id IS NULL THEN
    RETURN;
  END IF;

  SELECT il.id, il.org_id, il.spam_flag, il.merged_into_lead_id, lps.stage_id AS current_stage_id
    INTO v_lead
    FROM inbound_leads il
    LEFT JOIN lead_pipeline_stage lps ON lps.lead_id = il.id
   WHERE il.id = p_lead_id;

  IF NOT FOUND OR COALESCE(v_lead.spam_flag, false) OR v_lead.merged_into_lead_id IS NOT NULL THEN
    RETURN;
  END IF;

  v_current_terminal := false;
  IF v_lead.current_stage_id IS NOT NULL THEN
    SELECT (is_won OR is_lost) INTO v_current_terminal
      FROM pipeline_stages
     WHERE id = v_lead.current_stage_id;
  END IF;

  IF COALESCE(v_current_terminal, false) THEN
    RETURN;
  END IF;

  SELECT id INTO v_lost_stage_id
    FROM pipeline_stages
   WHERE org_id = v_lead.org_id AND is_lost = true
   ORDER BY sort_order
   LIMIT 1;

  IF v_lost_stage_id IS NULL OR v_lost_stage_id = v_lead.current_stage_id THEN
    RETURN;
  END IF;

  PERFORM move_lead_to_stage(p_lead_id, v_lost_stage_id, NULL, p_reason);
END;
$$;


ALTER FUNCTION "public"."crm_disqualify_lead_if_open"("p_lead_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_fixed_automation_conflict"("p_org_id" "uuid", "p_trigger_event_type" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings automation_settings;
  v_blocked  text[] := '{}';
BEGIN
  IF p_org_id IS NULL OR nullif(btrim(p_trigger_event_type), '') IS NULL THEN
    RETURN false;
  END IF;
  SELECT * INTO v_settings FROM automation_settings WHERE org_id = p_org_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_settings.speed_to_lead_enabled THEN
    v_blocked := v_blocked || ARRAY['crm_lead_created', 'crm_lead_created_manual'];
  END IF;
  IF v_settings.missed_call_textback_enabled THEN
    v_blocked := v_blocked || ARRAY['crm_lead_created', 'crm_lead_created_manual'];
  END IF;
  IF v_settings.review_request_enabled THEN
    v_blocked := v_blocked || ARRAY['job.phase_changed', 'job.status_changed'];
  END IF;
  RETURN btrim(p_trigger_event_type) = ANY(v_blocked);
END;
$$;


