CREATE OR REPLACE FUNCTION "public"."crm_lead_access"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_employee public.employees%ROWTYPE;
  v_override boolean;
  v_role_allowed boolean;
BEGIN
  SELECT e.*
    INTO v_employee
    FROM public.employees e
   WHERE e.auth_user_id = (SELECT auth.uid())
     AND e.is_active IS TRUE
     AND e.is_external IS FALSE
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Layer 1 — an admin is allowed outright, exactly as canAccess() does.
  IF v_employee.role::text = 'admin' THEN
    RETURN true;
  END IF;

  -- Layer 2 — a per-employee override wins over the role default, in BOTH
  -- directions. A row with can_view = false is a deliberate revocation and must
  -- not fall through to the role table.
  SELECT bool_or(epa.can_view IS TRUE)
    INTO v_override
    FROM public.employee_page_access epa
   WHERE epa.employee_id = v_employee.id
     AND epa.nav_key IN ('crm_leads', 'crm_call_log');

  IF v_override IS NOT NULL THEN
    RETURN v_override;
  END IF;

  -- Layer 3 — the role default, over either CRM lead nav key.
  SELECT bool_or(np.can_view IS TRUE)
    INTO v_role_allowed
    FROM public.nav_permissions np
   WHERE np.role = v_employee.role::text
     AND np.nav_key IN ('crm_leads', 'crm_call_log');

  RETURN COALESCE(v_role_allowed, false);
END;
$$;


ALTER FUNCTION "public"."crm_lead_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_lead_claim_value"("p_claim_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(SUM(COALESCE(iv.adjusted_total, iv.total, 0)), 0)
    FROM jobs j
    JOIN invoices iv ON iv.job_id = j.id
   WHERE j.claim_id = p_claim_id
     AND COALESCE(iv.adjusted_total, iv.total, 0) > 0
     AND (
          iv.sent_at            IS NOT NULL
       OR iv.qbo_emailed_at     IS NOT NULL
       OR iv.estimate_id        IS NOT NULL
       OR COALESCE(iv.amount_paid, 0) > 0
     );
$$;


ALTER FUNCTION "public"."crm_lead_claim_value"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_recompute_lead_value"("p_lead_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead inbound_leads;
  v_new  numeric;
BEGIN
  SELECT * INTO v_lead FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_lead.value_source = 'manual' THEN
    RETURN v_lead.value;
  END IF;

  IF v_lead.claim_id IS NULL THEN
    RETURN v_lead.value;
  END IF;

  v_new := crm_lead_claim_value(v_lead.claim_id);

  IF COALESCE(v_new, 0) <= 0 THEN
    RETURN v_lead.value;
  END IF;

  IF v_lead.value IS NOT DISTINCT FROM v_new THEN
    RETURN v_lead.value;
  END IF;

  UPDATE inbound_leads
     SET value        = v_new,
         value_source = 'auto',
         updated_at   = now()
   WHERE id = p_lead_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_value_synced', 'inbound_lead', p_lead_id,
          jsonb_build_object('value', v_new,
                             'previous_value', v_lead.value,
                             'claim_id', v_lead.claim_id));

  RETURN v_new;
END;
$$;


ALTER FUNCTION "public"."crm_recompute_lead_value"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_recompute_lead_values_for_claim"("p_claim_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead_id uuid;
BEGIN
  IF p_claim_id IS NULL THEN
    RETURN;
  END IF;
  FOR v_lead_id IN
    SELECT id FROM inbound_leads WHERE claim_id = p_claim_id
  LOOP
    PERFORM crm_recompute_lead_value(v_lead_id);
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."crm_recompute_lead_values_for_claim"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_sync_lead_value"("p_contact_id" "uuid", "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead_id uuid;
BEGIN
  IF p_contact_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN;
  END IF;

  SELECT il.id INTO v_lead_id
    FROM inbound_leads il
    JOIN lead_pipeline_stage lps ON lps.lead_id = il.id
    JOIN pipeline_stages ps ON ps.id = lps.stage_id
   WHERE il.contact_id = p_contact_id
     AND ps.is_won = true
     AND il.value IS NULL
     AND COALESCE(il.spam_flag, false) = false
   ORDER BY lps.updated_at DESC
   LIMIT 1;

  IF v_lead_id IS NULL THEN
    RETURN; -- nothing Won yet for this contact, or it already has a value
  END IF;

  UPDATE inbound_leads
     SET value      = p_amount,
         updated_at = now()
   WHERE id = v_lead_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_value_synced', 'inbound_lead', v_lead_id,
          jsonb_build_object('value', p_amount, 'contact_id', p_contact_id));
END;
$$;


ALTER FUNCTION "public"."crm_sync_lead_value"("p_contact_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


