CREATE OR REPLACE FUNCTION "public"."current_active_internal_appointment_employee"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT employee.id
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IS DISTINCT FROM 'crm_partner'
  ORDER BY employee.id
  LIMIT 1;
$$;


ALTER FUNCTION "public"."current_active_internal_appointment_employee"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_active_internal_appointment_employee"() IS 'UPR appointment crew atomic save/audit repair v1: private authenticated active-internal actor resolver';



CREATE OR REPLACE FUNCTION "public"."current_attributed_appointment_crew_actor"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  WITH requested_actor AS (
    SELECT CASE
      WHEN public.is_trusted_appointment_command_caller() THEN
        NULLIF(
          btrim(
            current_setting(
              'upr.appointment_crew_actor_id',
              true
            )
          ),
          ''
        )
      ELSE
        public.current_active_internal_appointment_employee()::text
    END AS actor_id_text
  )
  SELECT employee.id
  FROM requested_actor
  JOIN public.employees employee
    ON employee.id = CASE
      WHEN requested_actor.actor_id_text ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN requested_actor.actor_id_text::uuid
      ELSE NULL::uuid
    END
  WHERE employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IS DISTINCT FROM 'crm_partner'
  ORDER BY employee.id
  LIMIT 1;
$_$;


ALTER FUNCTION "public"."current_attributed_appointment_crew_actor"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_attributed_appointment_crew_actor"() IS 'UPR appointment crew atomic save/audit repair v1: private employee attribution resolver; trusted callers require SET LOCAL upr.appointment_crew_actor_id';



