CREATE OR REPLACE FUNCTION "public"."delete_appointment"("p_appointment_id" "uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_is_trusted boolean :=
    public.is_trusted_appointment_command_caller();
  v_date date;
  v_time_start time;
  v_time_end time;
  v_status text;
BEGIN
  IF p_appointment_id IS NULL THEN
    RAISE EXCEPTION
      'delete_appointment: p_appointment_id is required'
      USING ERRCODE = '22023';
  END IF;

  IF v_is_trusted THEN
    IF p_actor_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.employees employee
         WHERE employee.id = p_actor_id
           AND employee.is_active IS TRUE
           AND employee.is_external IS FALSE
           AND employee.role::text IS DISTINCT FROM 'crm_partner'
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: active internal appointment actor required'
        USING ERRCODE = '42501';
    END IF;
    v_actor_id := p_actor_id;
  ELSE
    v_actor_id :=
      public.current_active_internal_appointment_employee();
    IF v_actor_id IS NULL
       OR (
         p_actor_id IS NOT NULL
         AND p_actor_id IS DISTINCT FROM v_actor_id
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment actor does not match caller'
      USING ERRCODE = '42501';
    END IF;
  END IF;

  PERFORM pg_catalog.set_config(
    'upr.appointment_crew_actor_id',
    v_actor_id::text,
    true
  );

  SELECT
    appointment.date,
    appointment.time_start,
    appointment.time_end,
    appointment.status::text
  INTO
    v_date,
    v_time_start,
    v_time_end,
    v_status
  FROM public.appointments appointment
  WHERE appointment.id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT v_is_trusted
     AND NOT public.can_current_employee_edit_appointment_command(
       p_appointment_id
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment mutation access required'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.appointment_status_history (
    appointment_id,
    event_type,
    old_date,
    old_time_start,
    old_time_end,
    old_status,
    actor_id,
    reason
  )
  VALUES (
    p_appointment_id,
    'deleted',
    v_date,
    v_time_start,
    v_time_end,
    v_status,
    v_actor_id,
    p_reason
  );

  UPDATE public.job_tasks task
  SET appointment_id = NULL
  WHERE task.appointment_id = p_appointment_id;

  DELETE FROM public.appointment_crew crew
  WHERE crew.appointment_id = p_appointment_id;

  DELETE FROM public.appointments appointment
  WHERE appointment.id = p_appointment_id;
END;
$$;


ALTER FUNCTION "public"."delete_appointment"("p_appointment_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_appointment"("p_appointment_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") IS 'UPR appointment crew atomic save/audit repair v1: legacy-compatible actor-bound atomic appointment deletion';



CREATE OR REPLACE FUNCTION "public"."delete_contact_address"("p_address_id" "uuid", "p_contact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  was_billing boolean;
BEGIN
  SELECT is_billing INTO was_billing FROM contact_addresses WHERE id = p_address_id AND contact_id = p_contact_id;
  DELETE FROM contact_addresses WHERE id = p_address_id AND contact_id = p_contact_id;

  -- If we deleted the billing address, clear it from contacts table
  IF was_billing THEN
    UPDATE contacts SET billing_address = NULL, billing_city = NULL, billing_state = NULL, billing_zip = NULL, updated_at = now()
    WHERE id = p_contact_id;
    -- Auto-promote another address to billing if one exists
    UPDATE contact_addresses SET is_billing = true
    WHERE contact_id = p_contact_id AND id = (
      SELECT id FROM contact_addresses WHERE contact_id = p_contact_id ORDER BY created_at ASC LIMIT 1
    );
  END IF;

  RETURN jsonb_build_object('success', true);
END; $$;


