CREATE OR REPLACE FUNCTION "public"."delete_my_native_device_token"("p_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_employee_id uuid;
BEGIN
  IF NULLIF(btrim(p_token), '') IS NULL OR length(p_token) > 4096 THEN
    RAISE EXCEPTION 'token is required' USING errcode = '22023';
  END IF;

  SELECT employee.id
  INTO v_employee_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IN (
      'admin',
      'office',
      'project_manager',
      'field_tech',
      'estimator',
      'supervisor'
    )
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.device_tokens token_row
    WHERE token_row.token = btrim(p_token)
      AND token_row.employee_id <> v_employee_id
  ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: device token belongs to another employee'
      USING errcode = '42501';
  END IF;

  DELETE FROM public.device_tokens
  WHERE token = btrim(p_token)
    AND employee_id = v_employee_id;
END;
$$;


ALTER FUNCTION "public"."delete_my_native_device_token"("p_token" "text") OWNER TO "postgres";


