CREATE OR REPLACE FUNCTION "public"."derive_invoice_qbo_lifecycle_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.amount_paid, 0) > 0
     OR NEW.status IN ('paid', 'partially_paid', 'voided', 'disputed', 'viewed', 'overdue') THEN
    RETURN NEW;
  END IF;

  IF NEW.qbo_invoice_id IS NULL THEN
    NEW.status := 'draft';
  ELSIF NEW.qbo_emailed_at IS NOT NULL
        AND NEW.qbo_emailed_at IS DISTINCT FROM OLD.qbo_emailed_at THEN
    -- A successful provider send writes a fresh timestamp through the locked
    -- CAS and must win even when the local editor had marked the invoice draft.
    NEW.status := 'sent';
  ELSIF OLD.status = 'draft' THEN
    -- The shipped editor marks a revised synced invoice draft. Saving that
    -- revision makes it current in QBO but does not claim it was re-emailed.
    NEW.status := 'saved';
  ELSIF NEW.qbo_emailed_at IS NOT NULL THEN
    NEW.status := 'sent';
  ELSE
    NEW.status := 'saved';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."derive_invoice_qbo_lifecycle_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disconnect_integration"("p_provider" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  IF p_provider NOT IN ('stripe', 'twilio', 'resend') THEN
    RAISE EXCEPTION 'INVALID_PROVIDER: %', p_provider USING errcode = '22023';
  END IF;

  UPDATE integration_credentials
     SET access_token = NULL, connected_by = NULL, updated_at = now()
   WHERE provider = p_provider;

  IF p_provider = 'twilio' THEN
    UPDATE integration_config SET value = NULL, updated_at = now()
     WHERE key IN ('twilio_account_sid', 'twilio_messaging_service_sid', 'twilio_phone_number');
  END IF;
END;
$$;


ALTER FUNCTION "public"."disconnect_integration"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_due_appointment_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_row record; v_count integer := 0;
BEGIN
  FOR v_row IN
    SELECT appointment.id, crew.employee_id,
      ((appointment.date + appointment.time_start) AT TIME ZONE 'America/Denver') AS starts_at
    FROM public.appointments appointment
    JOIN public.appointment_crew crew ON crew.appointment_id = appointment.id
    JOIN public.employees employee ON employee.id = crew.employee_id
    WHERE appointment.status = 'scheduled'
      AND appointment.time_start IS NOT NULL
      AND employee.is_active IS TRUE AND employee.is_external IS FALSE
      AND ((appointment.date + appointment.time_start) AT TIME ZONE 'America/Denver') >= now() + interval '59 minutes'
      AND ((appointment.date + appointment.time_start) AT TIME ZONE 'America/Denver') < now() + interval '61 minutes'
  LOOP
    INSERT INTO public.appointment_reminder_claims (appointment_id, employee_id, appointment_starts_at)
    VALUES (v_row.id, v_row.employee_id, v_row.starts_at)
    ON CONFLICT DO NOTHING;
    IF FOUND THEN
      PERFORM public.notify_emit('appointment.reminder', jsonb_build_object(
        'appointment_id', v_row.id, 'employee_id', v_row.employee_id,
        'notification_event_id', concat(v_row.id, ':', v_row.employee_id, ':', v_row.starts_at)
      ));
      v_count := v_count + 1;
    END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."dispatch_due_appointment_reminders"() OWNER TO "postgres";


