    CONSTRAINT "email_suppressions_reason_check" CHECK (("reason" = ANY (ARRAY['unsubscribed'::"text", 'bounced'::"text", 'complained'::"text", 'manual'::"text", 'hard_bounce'::"text", 'complaint'::"text", 'global'::"text"])))
