CREATE OR REPLACE FUNCTION "public"."enroll_in_sequence"("p_sequence_id" "uuid", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_segment_id" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."crm_sequence_enrollments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id      uuid := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_filter      jsonb;
  v_first_delay int;
  v_next        timestamptz;
BEGIN
  IF p_sequence_id IS NULL THEN RAISE EXCEPTION 'a sequence id is required'; END IF;
  IF p_contact_id IS NULL AND p_segment_id IS NULL THEN
    RAISE EXCEPTION 'enroll_in_sequence needs a contact or a segment';
  END IF;

  SELECT delay_hours INTO v_first_delay
  FROM crm_sequence_steps WHERE sequence_id = p_sequence_id ORDER BY step_order LIMIT 1;
  v_next := CASE WHEN v_first_delay IS NULL THEN NULL
                 ELSE now() + make_interval(hours => v_first_delay) END;

  IF p_contact_id IS NOT NULL THEN
    INSERT INTO crm_sequence_enrollments (sequence_id, org_id, contact_id, status, current_step, next_run_at)
    VALUES (p_sequence_id, v_org_id, p_contact_id, 'active', 0, v_next)
    ON CONFLICT (sequence_id, contact_id) DO NOTHING;

    RETURN QUERY
      SELECT * FROM crm_sequence_enrollments
      WHERE sequence_id = p_sequence_id AND contact_id = p_contact_id;
  ELSE
    SELECT filter INTO v_filter FROM crm_segments WHERE id = p_segment_id;
    IF v_filter IS NULL THEN RAISE EXCEPTION 'segment % not found', p_segment_id; END IF;

    INSERT INTO crm_sequence_enrollments (sequence_id, org_id, contact_id, status, current_step, next_run_at)
    SELECT p_sequence_id, v_org_id, c.id, 'active', 0, v_next
    FROM contacts c
    WHERE (v_filter->>'referral_source' IS NULL OR c.referral_source = v_filter->>'referral_source')
      AND (v_filter->>'role' IS NULL OR c.role = v_filter->>'role')
      AND (v_filter->>'tag' IS NULL OR c.tags @> to_jsonb(ARRAY[v_filter->>'tag']))
    ON CONFLICT (sequence_id, contact_id) DO NOTHING;

    RETURN QUERY
      SELECT e.* FROM crm_sequence_enrollments e
      WHERE e.sequence_id = p_sequence_id
        AND e.contact_id IN (
          SELECT c.id FROM contacts c
          WHERE (v_filter->>'referral_source' IS NULL OR c.referral_source = v_filter->>'referral_source')
            AND (v_filter->>'role' IS NULL OR c.role = v_filter->>'role')
            AND (v_filter->>'tag' IS NULL OR c.tags @> to_jsonb(ARRAY[v_filter->>'tag']))
        );
  END IF;
END;
$$;


ALTER FUNCTION "public"."enroll_in_sequence"("p_sequence_id" "uuid", "p_contact_id" "uuid", "p_segment_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_contractor_compliance_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.role = 'subcontractor' THEN
    INSERT INTO public.contractor_compliance_profiles(contact_id,assigned_owner_id) VALUES(NEW.id,NEW.owner_id)
    ON CONFLICT(contact_id) DO NOTHING;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."ensure_contractor_compliance_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."establish_qbo_payment_allocation_fences"("p_attempt_id" "uuid", "p_realm_id" "text", "p_request" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row record;
  v_count integer := 0;
  v_invoice_ids uuid[] := ARRAY[]::uuid[];
  v_contact_id uuid := NULLIF(p_request->>'contact_id', '')::uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;
  IF p_attempt_id IS NULL OR NULLIF(btrim(p_realm_id), '') IS NULL
     OR p_request IS NULL OR jsonb_typeof(p_request) <> 'object'
     OR jsonb_typeof(p_request->'allocations') <> 'array'
     OR jsonb_array_length(p_request->'allocations') = 0
     OR jsonb_array_length(p_request->'allocations') > 100
     OR v_contact_id IS NULL THEN
    RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;

  FOR v_row IN
    WITH requested AS (
      SELECT
        NULLIF(value->>'invoice_id', '')::uuid AS invoice_id,
        NULLIF(value->>'amount_cents', '')::bigint AS amount_cents
      FROM jsonb_array_elements(p_request->'allocations')
    )
    SELECT i.id, i.locked, r.amount_cents
    FROM requested r
    JOIN public.invoices i ON i.id = r.invoice_id
    WHERE i.contact_id = v_contact_id
    ORDER BY i.id
    FOR UPDATE OF i
  LOOP
    v_count := v_count + 1;
    IF v_row.amount_cents IS NULL OR v_row.amount_cents <= 0 THEN
      RAISE EXCEPTION 'INVALID_ALLOCATION' USING ERRCODE = '22023';
    END IF;
    IF v_row.id = ANY(v_invoice_ids) THEN
      RAISE EXCEPTION 'DUPLICATE_INVOICE_ALLOCATION' USING ERRCODE = '23505';
    END IF;
    v_invoice_ids := array_append(v_invoice_ids, v_row.id);
    IF v_row.locked IS TRUE THEN
      RAISE EXCEPTION 'INVOICE_LOCKED' USING ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.qbo_payment_allocation_fences f
      WHERE f.invoice_id = v_row.id AND f.attempt_id <> p_attempt_id
    ) THEN
      RAISE EXCEPTION 'PAYMENT_ALLOCATION_BUSY' USING ERRCODE = '55P03';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.payment_receipt_attempts a
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(a.request_payload->'allocations', '[]'::jsonb)) prior(value)
      WHERE a.id <> p_attempt_id
        AND a.qbo_realm_id = p_realm_id
        AND a.status IN ('submitting', 'qbo_created', 'unknown_outcome')
        AND NULLIF(prior.value->>'invoice_id', '')::uuid = v_row.id
    ) THEN
      RAISE EXCEPTION 'PAYMENT_ALLOCATION_BUSY' USING ERRCODE = '55P03';
    END IF;
    INSERT INTO public.qbo_payment_allocation_fences (attempt_id, invoice_id, qbo_realm_id, amount_cents)
    VALUES (p_attempt_id, v_row.id, btrim(p_realm_id), v_row.amount_cents)
    ON CONFLICT (attempt_id, invoice_id) DO UPDATE
      SET amount_cents = EXCLUDED.amount_cents
      WHERE public.qbo_payment_allocation_fences.qbo_realm_id = EXCLUDED.qbo_realm_id
        AND public.qbo_payment_allocation_fences.amount_cents = EXCLUDED.amount_cents;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAYMENT_ALLOCATION_IDENTITY_MISMATCH' USING ERRCODE = '23514';
    END IF;
  END LOOP;
  IF v_count <> jsonb_array_length(p_request->'allocations') THEN
    RAISE EXCEPTION 'ALLOCATION_INVOICE_MISMATCH' USING ERRCODE = '23514';
  END IF;
END;
$$;


ALTER FUNCTION "public"."establish_qbo_payment_allocation_fences"("p_attempt_id" "uuid", "p_realm_id" "text", "p_request" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exec_read_sql"("p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_query  text := btrim(coalesce(p_query, ''));
  v_lower  text;
  v_result jsonb;
BEGIN
  IF right(v_query, 1) = ';' THEN
    v_query := btrim(left(v_query, length(v_query) - 1));
  END IF;

  v_lower := lower(v_query);

  IF v_lower !~ '^(select|with)\s' THEN
    RAISE EXCEPTION 'Only SELECT/WITH queries are allowed (got: %)', left(v_query, 40);
  END IF;

  IF position(';' in v_query) > 0 THEN
    RAISE EXCEPTION 'Multiple statements are not allowed';
  END IF;

  SET LOCAL transaction_read_only = on;
  SET LOCAL statement_timeout = '15s';

  EXECUTE format('SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (%s) AS t', v_query)
  INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."exec_read_sql"("p_query" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."exec_read_sql"("p_query" "text") IS 'Read-only SQL passthrough for the owner-locked UPR MCP (upr_sql tool). SELECT/WITH only, single statement, runs in a read-only transaction with a 15s timeout. service_role only.';



CREATE OR REPLACE FUNCTION "public"."fail_qbo_payment_receipt_attempt"("p_attempt_id" "uuid", "p_status" "text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_attempt public.payment_receipt_attempts%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF p_attempt_id IS NULL OR p_status NOT IN ('unknown_outcome', 'rejected', 'conflict') THEN RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_attempt FROM public.payment_receipt_attempts WHERE id = p_attempt_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTEMPT_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_attempt.status IN ('conflict', 'locally_finalized', 'reconciled', 'voided', 'deleted') THEN
    RETURN jsonb_build_object(
      'attempt_id', p_attempt_id,
      'status', v_attempt.status,
      'replayed', true,
      'ignored_downgrade', true
    );
  END IF;
  UPDATE public.payment_receipt_attempts SET status = p_status, error_code = NULLIF(btrim(p_error_code), ''),
    error_message = NULLIF(left(btrim(p_error_message), 1000), ''), updated_at = now() WHERE id = p_attempt_id;
  INSERT INTO public.payment_receipt_events (attempt_id, receipt_id, qbo_realm_id, qbo_payment_id, event_type, after_snapshot)
  VALUES (v_attempt.id, v_attempt.receipt_id, v_attempt.qbo_realm_id, v_attempt.qbo_payment_id, p_status,
    jsonb_build_object('status', p_status, 'error_code', NULLIF(btrim(p_error_code), '')));
  RETURN jsonb_build_object('attempt_id', p_attempt_id, 'status', p_status);
END;
$$;


ALTER FUNCTION "public"."fail_qbo_payment_receipt_attempt"("p_attempt_id" "uuid", "p_status" "text", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_fixed_automation_claim"("p_automation_key" "text", "p_entity_id" "uuid", "p_outcome" "text", "p_reason" "text" DEFAULT NULL::"text", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_updated boolean := false;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'finalize_fixed_automation_claim is service-role only'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.fixed_automation_claims AS c
  SET finalized_at = p_now,
      outcome = p_outcome,
      reason = p_reason
  WHERE c.automation_key = p_automation_key
    AND c.entity_id = p_entity_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."finalize_fixed_automation_claim"("p_automation_key" "text", "p_entity_id" "uuid", "p_outcome" "text", "p_reason" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_fixed_automation_claim"("p_automation_key" "text", "p_entity_id" "uuid", "p_outcome" "text", "p_reason" "text", "p_now" timestamp with time zone) IS 'Service-only terminal marker for a fixed-automation claim. The claim row is retained so it keeps blocking re-sends.';



CREATE OR REPLACE FUNCTION "public"."finalize_qbo_estimate_command"("p_command_id" "uuid", "p_response_status" integer, "p_response_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE seed public.qbo_estimate_commands; c public.qbo_estimate_commands; e public.estimates; r public.qbo_estimate_command_reservations;
 change jsonb; frozen jsonb; current jsonb; all_current jsonb; provider_current jsonb; line_id uuid; new_id uuid; pos integer:=0; local jsonb:='{}'::jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO seed FROM public.qbo_estimate_commands WHERE id=p_command_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 change:=seed.intent_payload->'line_change';
 -- Global order: every affected line, parent estimate, provider-source rows,
 -- command, reservation. Source-row locks turn this final comparison into a
 -- real CAS: a concurrent job/contact/claim edit either wins before the check
 -- and mismatches, or waits until this command has finished.
 PERFORM 1 FROM public.estimate_line_items WHERE estimate_id=seed.estimate_id ORDER BY id FOR UPDATE;
 SELECT * INTO e FROM public.estimates WHERE id=seed.estimate_id FOR UPDATE;
 PERFORM 1 FROM public.jobs WHERE id=e.job_id FOR UPDATE;
 PERFORM 1 FROM public.contacts WHERE id=COALESCE(e.contact_id,(SELECT j.primary_contact_id FROM public.jobs j WHERE j.id=e.job_id)) FOR UPDATE;
 PERFORM 1 FROM public.claims WHERE id=(SELECT j.claim_id FROM public.jobs j WHERE j.id=e.job_id) FOR UPDATE;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE id=p_command_id FOR UPDATE;
 SELECT * INTO r FROM public.qbo_estimate_command_reservations WHERE estimate_id=c.estimate_id FOR UPDATE;
 IF c.status='succeeded' THEN RETURN jsonb_build_object('ok',true,'idempotent',true,'result',c.local_result); END IF;
 IF c.status IS DISTINCT FROM 'provider_succeeded' THEN RETURN jsonb_build_object('ok',false,'reason','provider-not-succeeded'); END IF;
 IF NOT FOUND OR r.command_id IS DISTINCT FROM c.id THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
 IF e.converted_invoice_id IS NOT NULL OR e.status IN ('approved','denied','paid') THEN RETURN jsonb_build_object('ok',false,'reason','estimate-terminal'); END IF;
 IF e.qbo_estimate_id IS DISTINCT FROM c.expected_qbo_estimate_id AND NOT (c.action='save' AND e.qbo_estimate_id IS NOT DISTINCT FROM c.provider_result->>'qbo_estimate_id') THEN RETURN jsonb_build_object('ok',false,'reason','qbo-estimate-mismatch'); END IF;
 -- Validate every provider-driving source before any local projection.
 SELECT jsonb_build_object(
   'estimate',jsonb_build_object(
     'id',est_row.id::text,'job_id',est_row.job_id,'contact_id',est_row.contact_id,
     'status',est_row.status,'converted_invoice_id',est_row.converted_invoice_id,
     'qbo_estimate_id',est_row.qbo_estimate_id,'intended_division',est_row.intended_division,
     'estimate_number',est_row.estimate_number,'expiration_date',est_row.expiration_date,
     'property_address',est_row.property_address,'property_city',est_row.property_city,
     'property_state',est_row.property_state,'property_zip',est_row.property_zip),
   'job',CASE WHEN job_row.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
     'id',job_row.id::text,'division',job_row.division,'job_number',job_row.job_number,
     'claim_id',job_row.claim_id,'address',job_row.address,'city',job_row.city,
     'state',job_row.state,'zip',job_row.zip,'date_of_loss',job_row.date_of_loss,
     'primary_contact_id',job_row.primary_contact_id) END,
   'contact',CASE WHEN contact_row.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
     'id',contact_row.id::text,'qbo_customer_id',contact_row.qbo_customer_id,
     'name',contact_row.name,'email',contact_row.email) END,
   'claim',CASE WHEN claim_row.id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object(
     'id',claim_row.id::text,'claim_number',claim_row.claim_number,
     'date_of_loss',claim_row.date_of_loss,'loss_address',claim_row.loss_address,
     'loss_city',claim_row.loss_city,'loss_state',claim_row.loss_state,
     'loss_zip',claim_row.loss_zip) END
  ) INTO provider_current
  FROM public.estimates est_row
  LEFT JOIN public.jobs job_row ON job_row.id=est_row.job_id
  LEFT JOIN public.contacts contact_row ON contact_row.id=COALESCE(est_row.contact_id,job_row.primary_contact_id)
  LEFT JOIN public.claims claim_row ON claim_row.id=job_row.claim_id
  WHERE est_row.id=e.id;
 IF jsonb_typeof(c.intent_payload->'provider_source_preimage') IS DISTINCT FROM 'object'
    OR provider_current IS DISTINCT FROM c.intent_payload->'provider_source_preimage' THEN
  RETURN jsonb_build_object('ok',false,'reason','provider-source-mismatch');
 END IF;
 -- Validate every line preimage before any projection so failure rolls back cleanly.
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',li.id::text,'description',btrim(COALESCE(li.description,'')),'qbo_item_id',li.qbo_item_id,'qbo_item_name',li.qbo_item_name,'qbo_class_id',li.qbo_class_id,'qbo_class_name',li.qbo_class_name,'quantity',li.quantity,'unit_price',li.unit_price,'sort_order',li.sort_order) ORDER BY li.sort_order ASC NULLS LAST,li.created_at ASC,li.id ASC),'[]'::jsonb) INTO all_current FROM public.estimate_line_items li WHERE li.estimate_id=e.id;
 IF jsonb_typeof(c.intent_payload->'document_line_preimage') IS DISTINCT FROM 'array'
    OR COALESCE(c.intent_payload->>'document_line_preimage_hash','') !~ '^[0-9a-f]{64}$'
    OR all_current IS DISTINCT FROM c.intent_payload->'document_line_preimage' THEN
  RETURN jsonb_build_object('ok',false,'reason','document-line-source-mismatch');
 END IF;
 IF change IS NOT NULL AND change<>'null'::jsonb THEN
  IF change->>'kind' IN ('update','delete') THEN
   line_id:=(change->>'line_id')::uuid; frozen:=c.intent_payload->'line_preimage';
   SELECT jsonb_build_object('id',li.id::text,'description',btrim(COALESCE(li.description,'')),'qbo_item_id',li.qbo_item_id,'qbo_item_name',li.qbo_item_name,'qbo_class_id',li.qbo_class_id,'qbo_class_name',li.qbo_class_name,'quantity',li.quantity,'unit_price',li.unit_price,'sort_order',li.sort_order) INTO current FROM public.estimate_line_items li WHERE li.id=line_id AND li.estimate_id=e.id;
   IF current IS NULL OR current IS DISTINCT FROM frozen THEN RETURN jsonb_build_object('ok',false,'reason','line-source-mismatch'); END IF;
  ELSIF change->>'kind'='reorder' THEN
   IF all_current IS DISTINCT FROM c.intent_payload->'line_preimage'
      OR jsonb_typeof(change->'ordered_line_ids') IS DISTINCT FROM 'array'
      OR jsonb_array_length(change->'ordered_line_ids')<>jsonb_array_length(all_current)
      OR (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(change->'ordered_line_ids'))<>jsonb_array_length(all_current)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(all_current) item WHERE NOT ((change->'ordered_line_ids') ? (item->>'id'))) THEN RETURN jsonb_build_object('ok',false,'reason','line-source-mismatch'); END IF;
  END IF;
 END IF;
 PERFORM set_config('upr.qbo_estimate_finalizer_command_id',c.id::text,true);
 IF c.action='save' THEN
  IF change->>'kind'='create' THEN
   new_id:=gen_random_uuid();
   INSERT INTO public.estimate_line_items(id,estimate_id,description,qbo_item_id,qbo_item_name,qbo_class_id,qbo_class_name,quantity,unit_price,sort_order) VALUES(new_id,e.id,change->'patch'->>'description',change->'patch'->>'qbo_item_id',change->'patch'->>'qbo_item_name',change->'patch'->>'qbo_class_id',change->'patch'->>'qbo_class_name',(change->'patch'->>'quantity')::numeric,(change->'patch'->>'unit_price')::numeric,COALESCE((SELECT max(sort_order)+1 FROM public.estimate_line_items WHERE estimate_id=e.id),0)); local:=jsonb_build_object('line_id',new_id);
  ELSIF change->>'kind'='update' THEN
   UPDATE public.estimate_line_items SET description=change->'patch'->>'description',qbo_item_id=change->'patch'->>'qbo_item_id',qbo_item_name=change->'patch'->>'qbo_item_name',qbo_class_id=change->'patch'->>'qbo_class_id',qbo_class_name=change->'patch'->>'qbo_class_name',quantity=(change->'patch'->>'quantity')::numeric,unit_price=(change->'patch'->>'unit_price')::numeric WHERE id=line_id AND estimate_id=e.id; IF NOT FOUND THEN RAISE EXCEPTION 'line update target disappeared' USING ERRCODE='40001'; END IF;
  ELSIF change->>'kind'='delete' THEN DELETE FROM public.estimate_line_items WHERE id=line_id AND estimate_id=e.id; IF NOT FOUND THEN RAISE EXCEPTION 'line delete target disappeared' USING ERRCODE='40001'; END IF;
  ELSIF change->>'kind'='reorder' THEN
   FOR line_id IN SELECT value::uuid FROM jsonb_array_elements_text(change->'ordered_line_ids') LOOP UPDATE public.estimate_line_items SET sort_order=pos WHERE id=line_id AND estimate_id=e.id; IF NOT FOUND THEN RAISE EXCEPTION 'line reorder target disappeared' USING ERRCODE='40001'; END IF; pos:=pos+1; END LOOP;
  END IF;
  UPDATE public.estimates SET qbo_estimate_id=c.provider_result->>'qbo_estimate_id',qbo_synced_at=now(),qbo_doc_number=COALESCE(c.provider_result->>'doc_number',qbo_doc_number),qbo_sync_error=NULL,status=CASE WHEN status='draft' AND c.expected_qbo_estimate_id IS NULL THEN 'submitted' ELSE status END,submitted_at=CASE WHEN status='draft' AND c.expected_qbo_estimate_id IS NULL AND submitted_at IS NULL THEN now() ELSE submitted_at END WHERE id=e.id;
 ELSIF c.action='send' THEN
  UPDATE public.estimates SET qbo_emailed_at=now(),qbo_email_status=COALESCE(c.provider_result->>'email_status','EmailSent'),sent_to_email=c.provider_result->>'send_to',qbo_sync_error=NULL WHERE id=e.id;
 ELSE
  UPDATE public.estimates SET qbo_estimate_id=NULL,qbo_synced_at=NULL,qbo_doc_number=NULL,qbo_emailed_at=NULL,qbo_email_status=NULL,sent_to_email=NULL,qbo_sync_error=NULL WHERE id=e.id;
 END IF;
 UPDATE public.qbo_estimate_commands SET status='succeeded',local_result=local||jsonb_build_object('finalized',true),response_status=p_response_status,response_payload=p_response_payload,completed_at=now(),updated_at=now() WHERE id=c.id RETURNING * INTO c;
 DELETE FROM public.qbo_estimate_command_reservations WHERE estimate_id=e.id AND command_id=c.id;
 RETURN jsonb_build_object('ok',true,'result',c.local_result);
END;$_$;


ALTER FUNCTION "public"."finalize_qbo_estimate_command"("p_command_id" "uuid", "p_response_status" integer, "p_response_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_qbo_invoice_line_change"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_line_change" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_invoice public.invoices; v_command public.qbo_invoice_commands; v_reservation public.qbo_invoice_command_reservations;
  v_frozen jsonb; v_kind text; v_line public.invoice_line_items; v_current jsonb; v_row jsonb; v_id uuid; v_i integer:=0;
  v_current_rows jsonb; v_frozen_rows jsonb; v_current_order jsonb; v_original_order jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE='42501'; END IF;
  -- Read the immutable intent without a lock only to determine which source
  -- rows must be locked first. The authoritative command is then re-read FOR
  -- UPDATE after line(s) → invoice, matching desktop trigger lock ordering.
  SELECT intent_payload->'line_change' INTO v_frozen FROM public.qbo_invoice_commands WHERE id=p_command_id;
  IF NOT FOUND OR jsonb_typeof(v_frozen) IS DISTINCT FROM 'object' OR v_frozen->'request' IS DISTINCT FROM p_line_change THEN RETURN jsonb_build_object('ok',false,'reason','change-conflict'); END IF;
  v_kind := v_frozen->>'kind';
  IF v_kind IN ('update','delete') THEN
    v_id := (v_frozen->>'line_id')::uuid;
    SELECT * INTO v_line FROM public.invoice_line_items WHERE id=v_id AND invoice_id=p_invoice_id FOR UPDATE;
    IF NOT FOUND AND v_kind='update' THEN RETURN jsonb_build_object('ok',false,'reason','line-not-found'); END IF;
  ELSIF v_kind='reorder' THEN
    PERFORM 1 FROM public.invoice_line_items WHERE invoice_id=p_invoice_id ORDER BY id FOR UPDATE;
  END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id=p_invoice_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','invoice-not-found'); END IF;
  SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id=p_command_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations WHERE invoice_id=p_invoice_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.command_id IS DISTINCT FROM p_command_id OR v_reservation.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR v_reservation.actor_employee_id IS DISTINCT FROM p_actor_employee_id OR v_reservation.realm_id IS DISTINCT FROM p_realm_id OR v_reservation.initiator IS DISTINCT FROM p_initiator THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
  v_frozen := v_command.intent_payload->'line_change';
  IF v_command.status IS DISTINCT FROM 'provider_succeeded' OR jsonb_typeof(v_frozen) IS DISTINCT FROM 'object' OR v_frozen->'request' IS DISTINCT FROM p_line_change THEN RETURN jsonb_build_object('ok',false,'reason','change-conflict'); END IF;
  v_kind := v_frozen->>'kind';
  IF v_kind='create' THEN
    v_id := (v_frozen->>'line_id')::uuid;
    SELECT * INTO v_line FROM public.invoice_line_items WHERE id=v_id FOR UPDATE;
    IF FOUND THEN
      IF v_line.invoice_id IS DISTINCT FROM p_invoice_id
        OR v_line.description IS DISTINCT FROM v_frozen->'patch'->>'description'
        OR v_line.qbo_item_id IS DISTINCT FROM v_frozen->'patch'->>'qbo_item_id'
        OR v_line.qbo_item_name IS DISTINCT FROM v_frozen->'patch'->>'qbo_item_name'
        OR v_line.qbo_class_id IS DISTINCT FROM v_frozen->'patch'->>'qbo_class_id'
        OR v_line.qbo_class_name IS DISTINCT FROM v_frozen->'patch'->>'qbo_class_name'
        OR v_line.quantity IS DISTINCT FROM (v_frozen->'patch'->>'quantity')::numeric
        OR v_line.unit_price IS DISTINCT FROM (v_frozen->'patch'->>'unit_price')::numeric
        OR v_line.sort_order IS DISTINCT FROM (v_frozen->>'sort_order')::integer THEN RETURN jsonb_build_object('ok',false,'reason','source-mismatch'); END IF;
      RETURN jsonb_build_object('ok',true,'applied',false,'line',to_jsonb(v_line));
    END IF;
    INSERT INTO public.invoice_line_items (id,invoice_id,description,qbo_item_id,qbo_item_name,qbo_class_id,qbo_class_name,quantity,unit_price,sort_order)
    VALUES (v_id,p_invoice_id,v_frozen->'patch'->>'description',v_frozen->'patch'->>'qbo_item_id',v_frozen->'patch'->>'qbo_item_name',v_frozen->'patch'->>'qbo_class_id',v_frozen->'patch'->>'qbo_class_name',(v_frozen->'patch'->>'quantity')::numeric,(v_frozen->'patch'->>'unit_price')::numeric,(v_frozen->>'sort_order')::integer) RETURNING * INTO v_line;
  ELSIF v_kind='update' THEN
    v_id := (v_frozen->>'line_id')::uuid; SELECT * INTO v_line FROM public.invoice_line_items WHERE id=v_id AND invoice_id=p_invoice_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','line-not-found'); END IF;
    v_current := to_jsonb(v_line) - 'line_total' - 'created_at' - 'updated_at';
    IF v_current IS DISTINCT FROM v_frozen->'preimage' THEN
      IF v_current IS NOT DISTINCT FROM ((v_frozen->'preimage') || (v_frozen->'patch')) THEN RETURN jsonb_build_object('ok',true,'applied',false); END IF;
      RETURN jsonb_build_object('ok',false,'reason','source-mismatch');
    END IF;
    UPDATE public.invoice_line_items SET description=v_frozen->'patch'->>'description',qbo_item_id=v_frozen->'patch'->>'qbo_item_id',qbo_item_name=v_frozen->'patch'->>'qbo_item_name',qbo_class_id=v_frozen->'patch'->>'qbo_class_id',qbo_class_name=v_frozen->'patch'->>'qbo_class_name',quantity=(v_frozen->'patch'->>'quantity')::numeric,unit_price=(v_frozen->'patch'->>'unit_price')::numeric WHERE id=v_id RETURNING * INTO v_line;
  ELSIF v_kind='delete' THEN
    v_id := (v_frozen->>'line_id')::uuid; SELECT * INTO v_line FROM public.invoice_line_items WHERE id=v_id AND invoice_id=p_invoice_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('ok',true,'applied',false); END IF;
    IF (to_jsonb(v_line) - 'line_total' - 'created_at' - 'updated_at') IS DISTINCT FROM v_frozen->'preimage' THEN RETURN jsonb_build_object('ok',false,'reason','source-mismatch'); END IF;
    DELETE FROM public.invoice_line_items WHERE id=v_id;
  ELSIF v_kind='reorder' THEN
    SELECT jsonb_agg((to_jsonb(l) - 'line_total' - 'created_at' - 'updated_at' - 'sort_order') ORDER BY l.id),
           jsonb_agg(to_jsonb(l.id) ORDER BY l.sort_order, l.id)
      INTO v_current_rows, v_current_order FROM public.invoice_line_items l WHERE l.invoice_id=p_invoice_id;
    SELECT jsonb_agg(value - 'sort_order' ORDER BY value->>'id'),
           jsonb_agg(to_jsonb((value->>'id')::uuid) ORDER BY (value->>'sort_order')::integer, value->>'id')
      INTO v_frozen_rows, v_original_order FROM jsonb_array_elements(v_frozen->'preimage') value;
    IF v_current_rows IS DISTINCT FROM v_frozen_rows THEN RETURN jsonb_build_object('ok',false,'reason','source-mismatch'); END IF;
    IF v_current_order IS NOT DISTINCT FROM v_frozen->'ordered_line_ids' THEN RETURN jsonb_build_object('ok',true,'applied',false); END IF;
    IF v_current_order IS DISTINCT FROM v_original_order THEN RETURN jsonb_build_object('ok',false,'reason','source-mismatch'); END IF;
    FOR v_row IN SELECT value FROM jsonb_array_elements(v_frozen->'ordered_line_ids') LOOP v_id := (v_row #>> '{}')::uuid; UPDATE public.invoice_line_items SET sort_order=v_i WHERE id=v_id AND invoice_id=p_invoice_id; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','source-mismatch'); END IF; v_i:=v_i+1; END LOOP;
  ELSE RETURN jsonb_build_object('ok',false,'reason','change-conflict'); END IF;
  RETURN jsonb_build_object('ok',true,'applied',true,'line',CASE WHEN v_line.id IS NULL THEN NULL ELSE to_jsonb(v_line) END);
END;
$$;


ALTER FUNCTION "public"."finalize_qbo_invoice_line_change"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_line_change" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_qbo_invoice_line_update"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_line_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_description" "text", "p_qbo_item_id" "text", "p_qbo_item_name" "text", "p_qbo_class_id" "text", "p_qbo_class_name" "text", "p_quantity" numeric, "p_unit_price" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_invoice public.invoices;
  v_command public.qbo_invoice_commands;
  v_reservation public.qbo_invoice_command_reservations;
  v_line public.invoice_line_items;
  v_current jsonb;
  v_patch jsonb;
  v_frozen jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  IF p_command_id IS NULL OR p_invoice_id IS NULL OR p_line_id IS NULL
     OR p_initiator <> 'browser' OR p_actor_auth_user_id IS NULL OR p_realm_id IS NULL
     OR p_description IS NULL OR btrim(p_description) = '' OR length(p_description) > 4000
     OR p_quantity IS NULL OR p_unit_price IS NULL
     OR p_quantity IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric)
     OR p_unit_price IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-line-update');
  END IF;
  SELECT * INTO v_line FROM public.invoice_line_items
  WHERE id = p_line_id AND invoice_id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'line-not-found'); END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invoice-not-found'); END IF;
  IF v_invoice.locked IS TRUE THEN RETURN jsonb_build_object('ok', false, 'reason', 'invoice-locked'); END IF;
  SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id = p_command_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'command-not-found'); END IF;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations
  WHERE invoice_id = p_invoice_id FOR UPDATE;
  IF NOT FOUND
     OR v_reservation.command_id IS DISTINCT FROM p_command_id
     OR v_reservation.action IS DISTINCT FROM 'save'
     OR v_reservation.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id
     OR v_reservation.actor_employee_id IS DISTINCT FROM p_actor_employee_id
     OR v_reservation.initiator IS DISTINCT FROM p_initiator
     OR v_reservation.realm_id IS DISTINCT FROM p_realm_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reservation-mismatch');
  END IF;
  IF v_command.invoice_id IS DISTINCT FROM p_invoice_id
     OR v_command.action IS DISTINCT FROM 'save'
     OR v_command.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id
     OR v_command.actor_employee_id IS DISTINCT FROM p_actor_employee_id
     OR v_command.initiator IS DISTINCT FROM p_initiator
     OR v_command.realm_id IS DISTINCT FROM p_realm_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'command-mismatch');
  END IF;
  IF v_command.status IS DISTINCT FROM 'provider_succeeded' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'provider-not-succeeded', 'status', v_command.status);
  END IF;
  v_current := jsonb_build_object(
    'description', v_line.description, 'qbo_item_id', v_line.qbo_item_id,
    'qbo_item_name', v_line.qbo_item_name, 'qbo_class_id', v_line.qbo_class_id,
    'qbo_class_name', v_line.qbo_class_name, 'quantity', v_line.quantity,
    'unit_price', v_line.unit_price
  );
  v_patch := jsonb_build_object(
    'description', p_description, 'qbo_item_id', p_qbo_item_id,
    'qbo_item_name', p_qbo_item_name, 'qbo_class_id', p_qbo_class_id,
    'qbo_class_name', p_qbo_class_name, 'quantity', p_quantity,
    'unit_price', p_unit_price
  );
  v_frozen := v_command.intent_payload->'line_update';
  IF jsonb_typeof(v_frozen) IS DISTINCT FROM 'object'
     OR v_frozen->>'line_id' IS DISTINCT FROM p_line_id::text
     OR v_frozen->'patch' IS DISTINCT FROM v_patch THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'patch-conflict');
  END IF;
  IF v_current IS NOT DISTINCT FROM v_patch THEN
    RETURN jsonb_build_object('ok', true, 'applied', false, 'line', to_jsonb(v_line));
  END IF;
  IF v_current IS DISTINCT FROM v_frozen->'preimage' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'source-mismatch');
  END IF;
  UPDATE public.invoice_line_items
  SET description = p_description,
      qbo_item_id = p_qbo_item_id,
      qbo_item_name = p_qbo_item_name,
      qbo_class_id = p_qbo_class_id,
      qbo_class_name = p_qbo_class_name,
      quantity = p_quantity,
      unit_price = p_unit_price
  WHERE id = v_line.id
  RETURNING * INTO v_line;
  RETURN jsonb_build_object('ok', true, 'applied', true, 'line', to_jsonb(v_line));
END;
$$;


ALTER FUNCTION "public"."finalize_qbo_invoice_line_update"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_line_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_description" "text", "p_qbo_item_id" "text", "p_qbo_item_name" "text", "p_qbo_class_id" "text", "p_qbo_class_name" "text", "p_quantity" numeric, "p_unit_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_qbo_payment_receipt"("p_attempt_id" "uuid", "p_receipt" "jsonb", "p_allocations" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_attempt public.payment_receipt_attempts%ROWTYPE;
  v_receipt public.payment_receipts%ROWTYPE;
  v_item jsonb;
  v_invoice record;
  v_contact_id uuid;
  v_total bigint;
  v_applied bigint;
  v_unapplied bigint;
  v_sum bigint := 0;
  v_payment_method text;
  v_actor uuid;
  v_source text;
  v_qbo_payment_id text;
  v_qbo_realm_id text;
  v_qbo_customer_id text;
  v_receipt_id uuid;
  v_invoice_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF p_attempt_id IS NULL OR p_receipt IS NULL OR jsonb_typeof(p_receipt) <> 'object'
     OR p_allocations IS NULL OR jsonb_typeof(p_allocations) <> 'array'
     OR jsonb_array_length(p_allocations) = 0 OR jsonb_array_length(p_allocations) > 100 THEN
    RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;
  v_qbo_realm_id := NULLIF(btrim(p_receipt->>'qbo_realm_id'), '');
  v_qbo_customer_id := NULLIF(btrim(p_receipt->>'qbo_customer_id'), '');
  v_qbo_payment_id := NULLIF(btrim(p_receipt->>'qbo_payment_id'), '');
  v_total := (p_receipt->>'total_cents')::bigint;
  v_applied := (p_receipt->>'applied_cents')::bigint;
  v_unapplied := COALESCE((p_receipt->>'unapplied_cents')::bigint, 0);
  v_payment_method := NULLIF(btrim(p_receipt->>'payment_method'), '');
  v_actor := NULLIF(p_receipt->>'actor_employee_id', '')::uuid;
  v_source := COALESCE(NULLIF(btrim(p_receipt->>'source'), ''), 'qbo');
  IF v_qbo_realm_id IS NULL OR v_qbo_customer_id IS NULL OR v_qbo_payment_id IS NULL
     OR v_total IS NULL OR v_applied IS NULL OR v_total <= 0 OR v_applied <= 0 OR v_unapplied < 0 OR v_total <> v_applied + v_unapplied
     OR v_source NOT IN ('qbo', 'upr', 'manual')
     OR (v_payment_method IS NOT NULL AND v_payment_method NOT IN ('check','ach','eft','credit_card','wire','cash','insurance_direct','other'))
     OR jsonb_typeof(COALESCE(p_receipt->'normalized_snapshot', '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_RECEIPT' USING ERRCODE = '22023';
  END IF;
  IF v_actor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id = v_actor AND e.is_active IS TRUE AND e.is_external IS FALSE) THEN
    RAISE EXCEPTION 'INVALID_ACTOR' USING ERRCODE = '42501';
  END IF;
  -- Match mark/reconcile lock order: payment advisory first, attempt row second.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_qbo_realm_id || ':' || v_qbo_payment_id, 0));
  -- Distinct Payments for one customer can touch the same invoice. Serialize
  -- that customer's projection mutations before taking compatible invoice
  -- validation locks, so the payment rollup trigger never has two sessions
  -- trying to upgrade the same invoice/job locks.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('qbo-receipt-customer:' || v_qbo_realm_id || ':' || v_qbo_customer_id, 0)
  );
  SELECT * INTO v_attempt
  FROM public.payment_receipt_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTEMPT_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_attempt.receipt_id IS NOT NULL THEN
    RETURN jsonb_build_object('receipt_id', v_attempt.receipt_id, 'attempt_id', p_attempt_id, 'status', v_attempt.status, 'replayed', true);
  END IF;
  IF v_attempt.qbo_payment_id IS NULL THEN RAISE EXCEPTION 'QBO_PAYMENT_NOT_RECORDED' USING ERRCODE = '23514'; END IF;
  IF v_qbo_realm_id <> v_attempt.qbo_realm_id OR v_qbo_payment_id <> v_attempt.qbo_payment_id THEN
    RAISE EXCEPTION 'ATTEMPT_RECEIPT_MISMATCH' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.payment_receipt_events e
    WHERE e.qbo_realm_id = v_qbo_realm_id
      AND e.qbo_payment_id = v_qbo_payment_id
      AND e.event_type IN ('voided', 'deleted')
  ) THEN
    RAISE EXCEPTION 'QBO_PAYMENT_TERMINAL' USING ERRCODE = '23514';
  END IF;

  -- Lock every real allocation invoice in UUID order before any projection.
  PERFORM public.lock_qbo_payment_allocation_invoices(p_allocations);

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
    IF jsonb_typeof(v_item) <> 'object' OR NULLIF(v_item->>'invoice_id', '') IS NULL
       OR NULLIF(v_item->>'qbo_invoice_id', '') IS NULL OR (v_item->>'amount_cents')::bigint <= 0
       OR COALESCE(v_item->>'payer_type', 'homeowner') NOT IN ('insurance','homeowner','other') THEN
      RAISE EXCEPTION 'INVALID_ALLOCATION' USING ERRCODE = '22023';
    END IF;
    SELECT i.id, i.job_id, i.contact_id, i.qbo_invoice_id, c.qbo_customer_id
      INTO v_invoice FROM public.invoices i JOIN public.contacts c ON c.id = i.contact_id
      WHERE i.id = (v_item->>'invoice_id')::uuid FOR SHARE;
    IF NOT FOUND OR v_invoice.qbo_invoice_id IS DISTINCT FROM v_item->>'qbo_invoice_id'
       OR v_invoice.qbo_customer_id IS DISTINCT FROM v_qbo_customer_id THEN
      RAISE EXCEPTION 'ALLOCATION_INVOICE_MISMATCH' USING ERRCODE = '23514';
    END IF;
    IF v_contact_id IS NULL THEN v_contact_id := v_invoice.contact_id;
    ELSIF v_contact_id <> v_invoice.contact_id THEN RAISE EXCEPTION 'CROSS_CONTACT_ALLOCATION' USING ERRCODE = '23514'; END IF;
    IF (v_item->>'invoice_id')::uuid = ANY(v_invoice_ids) THEN RAISE EXCEPTION 'DUPLICATE_INVOICE_ALLOCATION' USING ERRCODE = '23505'; END IF;
    v_invoice_ids := array_append(v_invoice_ids, (v_item->>'invoice_id')::uuid);
    v_sum := v_sum + (v_item->>'amount_cents')::bigint;
  END LOOP;
  IF v_sum <> v_applied THEN RAISE EXCEPTION 'ALLOCATION_SUM_MISMATCH' USING ERRCODE = '23514'; END IF;

  INSERT INTO public.payment_receipts (
    contact_id, qbo_realm_id, qbo_customer_id, qbo_payment_id, qbo_sync_token, txn_date,
    total_cents, applied_cents, unapplied_cents, payment_method, qbo_payment_method_id,
    qbo_payment_method_name, reference_number, deposit_account_id, deposit_account_name,
    source, status, actor_employee_id, qbo_created_at, qbo_updated_at, normalized_snapshot
  ) VALUES (
    v_contact_id, v_qbo_realm_id, v_qbo_customer_id, v_qbo_payment_id, p_receipt->>'qbo_sync_token',
    (p_receipt->>'txn_date')::date, v_total, v_applied, v_unapplied, v_payment_method,
    p_receipt->>'qbo_payment_method_id', p_receipt->>'qbo_payment_method_name', p_receipt->>'reference_number',
    p_receipt->>'deposit_account_id', p_receipt->>'deposit_account_name', v_source, 'locally_finalized',
    COALESCE(v_actor, v_attempt.actor_employee_id), NULLIF(p_receipt->>'qbo_created_at', '')::timestamptz,
    NULLIF(p_receipt->>'qbo_updated_at', '')::timestamptz, COALESCE(p_receipt->'normalized_snapshot', '{}'::jsonb)
  ) ON CONFLICT (qbo_realm_id, qbo_payment_id) WHERE qbo_payment_id IS NOT NULL DO UPDATE SET
    qbo_sync_token = EXCLUDED.qbo_sync_token, txn_date = EXCLUDED.txn_date, total_cents = EXCLUDED.total_cents,
    applied_cents = EXCLUDED.applied_cents, unapplied_cents = EXCLUDED.unapplied_cents,
    payment_method = EXCLUDED.payment_method, qbo_payment_method_id = EXCLUDED.qbo_payment_method_id,
    qbo_payment_method_name = EXCLUDED.qbo_payment_method_name, reference_number = EXCLUDED.reference_number,
    deposit_account_id = EXCLUDED.deposit_account_id, deposit_account_name = EXCLUDED.deposit_account_name,
    source = EXCLUDED.source,
    status = CASE
      WHEN public.payment_receipts.status = 'reconciled' THEN 'reconciled'
      ELSE 'locally_finalized'
    END,
    qbo_updated_at = EXCLUDED.qbo_updated_at,
    normalized_snapshot = EXCLUDED.normalized_snapshot, updated_at = now()
  RETURNING id INTO v_receipt_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
    SELECT i.id, i.job_id, i.contact_id INTO v_invoice FROM public.invoices i WHERE i.id = (v_item->>'invoice_id')::uuid FOR SHARE;
    INSERT INTO public.payments (receipt_id, invoice_id, job_id, contact_id, amount, payment_date, payer_type,
      payment_method, reference_number, recorded_by, source, qbo_payment_id, qbo_realm_id, qbo_synced_at, qbo_sync_error)
    VALUES (v_receipt_id, v_invoice.id, v_invoice.job_id, v_invoice.contact_id,
      ((v_item->>'amount_cents')::numeric / 100), (p_receipt->>'txn_date')::date,
      COALESCE(v_item->>'payer_type', 'homeowner'), v_payment_method, p_receipt->>'reference_number',
      COALESCE(v_actor, v_attempt.actor_employee_id), v_source, v_qbo_payment_id, v_qbo_realm_id, now(), NULL)
    ON CONFLICT (qbo_payment_id, invoice_id) WHERE qbo_payment_id IS NOT NULL DO UPDATE SET
      receipt_id = EXCLUDED.receipt_id, amount = EXCLUDED.amount, payment_date = EXCLUDED.payment_date,
      payer_type = EXCLUDED.payer_type, payment_method = EXCLUDED.payment_method,
      qbo_realm_id = EXCLUDED.qbo_realm_id,
      reference_number = EXCLUDED.reference_number, qbo_synced_at = EXCLUDED.qbo_synced_at, qbo_sync_error = NULL;
  END LOOP;
  UPDATE public.payment_receipt_attempts SET receipt_id = v_receipt_id, status = 'locally_finalized', updated_at = now() WHERE id = p_attempt_id;
  INSERT INTO public.payment_receipt_events (receipt_id, attempt_id, qbo_realm_id, qbo_payment_id, event_type, after_snapshot)
  VALUES (v_receipt_id, p_attempt_id, v_qbo_realm_id, v_qbo_payment_id, 'locally_finalized', p_receipt);
  RETURN jsonb_build_object('receipt_id', v_receipt_id, 'attempt_id', p_attempt_id, 'status', 'locally_finalized', 'replayed', false);
END;
$$;


ALTER FUNCTION "public"."finalize_qbo_payment_receipt"("p_attempt_id" "uuid", "p_receipt" "jsonb", "p_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_or_create_conversation"("p_contact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_conv_id uuid;
  v_contact public.contacts%ROWTYPE;
  v_title   text;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'find_or_create_conversation is service-role only'
      USING ERRCODE = '42501';
  END IF;

  IF p_contact_id IS NULL THEN
    RAISE EXCEPTION 'find_or_create_conversation: p_contact_id is required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('find_or_create_conversation:' || p_contact_id::text));

  SELECT c.id INTO v_conv_id
  FROM public.conversations c
  JOIN public.conversation_participants cp
    ON cp.conversation_id = c.id
   AND cp.contact_id = p_contact_id
   AND cp.is_active = true
   AND cp.removed_at IS NULL
  WHERE c.type = 'direct'
    AND c.status <> 'archived'
    AND NOT EXISTS (
      SELECT 1
      FROM public.conversation_participants other
      WHERE other.conversation_id = c.id
        AND other.contact_id IS DISTINCT FROM p_contact_id
    )
  ORDER BY COALESCE(c.last_message_at, c.created_at) DESC, c.id DESC
  LIMIT 1;

  IF v_conv_id IS NULL THEN
    SELECT * INTO v_contact FROM public.contacts WHERE id = p_contact_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'find_or_create_conversation: contact % not found', p_contact_id;
    END IF;
    IF v_contact.phone IS NULL OR btrim(v_contact.phone) = '' THEN
      RAISE EXCEPTION 'find_or_create_conversation: contact % has no phone number', p_contact_id;
    END IF;

    v_title := CASE
      WHEN v_contact.company IS NOT NULL AND btrim(v_contact.company) <> ''
        THEN v_contact.name || ' — ' || v_contact.company
      ELSE v_contact.name
    END;

    INSERT INTO public.conversations (type, title, status)
      VALUES ('direct', v_title, 'needs_response')
      RETURNING id INTO v_conv_id;

    INSERT INTO public.conversation_participants (conversation_id, contact_id, phone, role)
      VALUES (v_conv_id, p_contact_id, v_contact.phone, 'primary');
  END IF;

  RETURN (
    SELECT public.get_tech_conversations(p_conversation_id => v_conv_id)
      -> 'conversations' -> 0
  );
END;
$$;


ALTER FUNCTION "public"."find_or_create_conversation"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_or_create_scoped_conversation"("p_contact_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_existing_conversation_id uuid;
  v_conversation jsonb;
  v_conversation_id uuid;
  v_can_start boolean;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'find_or_create_scoped_conversation is service-role only'
      USING ERRCODE = '42501';
  END IF;

  IF p_contact_id IS NULL OR p_employee_id IS NULL THEN
    RAISE EXCEPTION 'contact and employee are required'
      USING ERRCODE = '22023';
  END IF;

  IF NOT public.messaging_employee_has_conversations_capability(p_employee_id) THEN
    RAISE EXCEPTION 'Messages access is not granted'
      USING ERRCODE = '42501';
  END IF;

  SELECT conversation.id
    INTO v_existing_conversation_id
  FROM public.conversations conversation
  JOIN public.conversation_participants participant
    ON participant.conversation_id = conversation.id
   AND participant.contact_id = p_contact_id
   AND participant.is_active
   AND participant.removed_at IS NULL
  WHERE conversation.type = 'direct'
    AND conversation.status <> 'archived'
    AND NOT EXISTS (
      SELECT 1
      FROM public.conversation_participants other
      WHERE other.conversation_id = conversation.id
        AND other.contact_id IS DISTINCT FROM p_contact_id
    )
  ORDER BY
    COALESCE(conversation.last_message_at, conversation.created_at) DESC,
    conversation.id DESC
  LIMIT 1;

  IF v_existing_conversation_id IS NOT NULL THEN
    IF NOT public.messaging_employee_can_access_conversation(
      p_employee_id,
      v_existing_conversation_id
    ) THEN
      RAISE EXCEPTION 'conversation access not found'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    SELECT EXISTS (
      SELECT 1
      FROM public.employees employee
      WHERE employee.id = p_employee_id
        AND employee.is_active
        AND NOT employee.is_external
        AND employee.role::text <> 'crm_partner'
    )
      INTO v_can_start;

    IF NOT COALESCE(v_can_start, false) THEN
      RAISE EXCEPTION 'conversation access not found'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_conversation := public.find_or_create_conversation(p_contact_id);
  v_conversation_id := NULLIF(v_conversation ->> 'id', '')::uuid;

  IF v_conversation_id IS NULL
     OR NOT public.messaging_employee_can_access_conversation(
       p_employee_id,
       v_conversation_id
     ) THEN
    RAISE EXCEPTION 'conversation access not found'
      USING ERRCODE = '42501';
  END IF;

  RETURN v_conversation;
END;
$$;


ALTER FUNCTION "public"."find_or_create_scoped_conversation"("p_contact_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."find_or_create_scoped_conversation"("p_contact_id" "uuid", "p_employee_id" "uuid") IS 'Service-only atomic browser boundary: opens an existing direct thread only for a trusted member, or creates one only for privileged/default staff.';



CREATE OR REPLACE FUNCTION "public"."finish_appointment"("p_appointment_id" "uuid", "p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_completed INT;
  v_released INT;
  v_total INT;
BEGIN
  -- Count tasks
  SELECT count(*) INTO v_total FROM job_tasks WHERE appointment_id = p_appointment_id;
  SELECT count(*) INTO v_completed FROM job_tasks WHERE appointment_id = p_appointment_id AND is_completed = true;
  
  -- Unassign incomplete tasks (release back to pool)
  UPDATE job_tasks 
  SET appointment_id = NULL 
  WHERE appointment_id = p_appointment_id AND is_completed = false;
  
  GET DIAGNOSTICS v_released = ROW_COUNT;

  -- Mark appointment as completed
  UPDATE appointments 
  SET status = 'completed'
  WHERE id = p_appointment_id;

  RETURN jsonb_build_object(
    'total_tasks', v_total,
    'completed_tasks', v_completed,
    'released_tasks', v_released
  );
END;
$$;


ALTER FUNCTION "public"."finish_appointment"("p_appointment_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_claim_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  next_seq int;
BEGIN
  PERFORM pg_advisory_xact_lock(739104826);
  SELECT COALESCE(max(split_part(claim_number, '-', 3)::int), 0) + 1
    INTO next_seq
    FROM claims
    WHERE claim_number ~ '^CLM-\d{4}-\d+$';
  -- keep the legacy sequence in sync as a secondary guard
  PERFORM setval('claim_number_seq', next_seq);
  RETURN 'CLM-' || to_char(now(), 'YYMM') || '-' || lpad(next_seq::text, 3, '0');
END;
$_$;


ALTER FUNCTION "public"."generate_claim_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_estimate_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  next_num int;
BEGIN
  PERFORM pg_advisory_xact_lock(739104829);
  SELECT COALESCE(max((regexp_replace(estimate_number, '\D', '', 'g'))::int), 0) + 1
    INTO next_num
    FROM public.estimates
    WHERE estimate_number ~ '^EST-\d+$';
  PERFORM setval('estimate_number_seq', next_num);
  RETURN 'EST-' || lpad(next_num::text, 6, '0');
END;
$_$;


