CREATE OR REPLACE FUNCTION "public"."generate_job_number"("p_division" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_prefix VARCHAR(2);
  v_ym CHAR(4);
  v_seq INT;
  v_job_number TEXT;
BEGIN
  v_prefix := CASE
    WHEN p_division = 'water' THEN 'W'
    WHEN p_division = 'mold' THEN 'M'
    WHEN p_division = 'reconstruction' THEN 'R'
    WHEN p_division = 'remodeling' THEN 'RM'
    WHEN p_division = 'contents' THEN 'C'
    WHEN p_division = 'fire' THEN 'F'
    WHEN p_division = 'general' THEN 'G'
    ELSE 'X'
  END;

  v_ym := to_char(now(), 'YYMM');

  INSERT INTO job_number_sequences (division_prefix, year_month, last_seq)
  VALUES (v_prefix, v_ym, 1)
  ON CONFLICT (division_prefix, year_month)
  DO UPDATE SET last_seq = job_number_sequences.last_seq + 1
  RETURNING last_seq INTO v_seq;

  v_job_number := v_prefix || '-' || v_ym || '-' || LPAD(v_seq::TEXT, 3, '0');
  RETURN v_job_number;
END;
$$;


ALTER FUNCTION "public"."generate_job_number"("p_division" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_oop_quote_number"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_month text := to_char(now() AT TIME ZONE 'America/Denver', 'YYMM');
  v_prefix text;
  v_next integer;
BEGIN
  v_prefix := 'OOP-' || v_month || '-';
  PERFORM pg_advisory_xact_lock(hashtext('oop_quote_number:America/Denver:' || v_month));
  SELECT COALESCE(max(NULLIF(substring(quote_number from length(v_prefix)+1), '')::integer),0)+1
    INTO v_next FROM public.oop_quotes WHERE quote_number ~ ('^' || v_prefix || '[0-9]+$');
  RETURN v_prefix || lpad(v_next::text, 3, '0');
END;
$_$;


ALTER FUNCTION "public"."generate_oop_quote_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_appointment_geo"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'appointment_id', a.id,
    'job_id',         j.id,
    'status',         a.status,
    'title',          a.title,
    'address',        COALESCE(j.address, ''),
    'city',           COALESCE(j.city, ''),
    'clock_in_at',    e.clock_in,
    'clock_in_lat',   e.clock_in_lat,
    'clock_in_lng',   e.clock_in_lng
  )
  INTO v_result
  FROM appointments a
  JOIN appointment_crew c ON c.appointment_id = a.id
  LEFT JOIN jobs j ON j.id = a.job_id
  LEFT JOIN LATERAL (
    SELECT clock_in, clock_in_lat, clock_in_lng
    FROM job_time_entries te
    WHERE te.appointment_id = a.id AND te.employee_id = p_employee_id
    ORDER BY te.created_at DESC
    LIMIT 1
  ) e ON TRUE
  WHERE c.employee_id = p_employee_id
    AND a.status IN ('in_progress', 'paused')
  ORDER BY a.status = 'in_progress' DESC, a.date DESC, a.time_start DESC NULLS LAST
  LIMIT 1;

  RETURN v_result;  -- NULL if no match
END;
$$;


ALTER FUNCTION "public"."get_active_appointment_geo"("p_employee_id" "uuid") OWNER TO "postgres";


