CREATE OR REPLACE FUNCTION "public"."get_claim_activity"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'created_at') DESC), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', se.id,
      'event_type', se.event_type,
      'entity_type', se.entity_type,
      'entity_id', se.entity_id,
      'job_id', se.job_id,
      'payload', se.payload,
      'created_at', se.created_at,
      'actor_name', e.full_name
    ) AS row_data
    FROM system_events se
    LEFT JOIN employees e ON e.auth_user_id = se.actor_id
    WHERE se.entity_id = p_claim_id
       OR se.job_id IN (SELECT id FROM jobs WHERE claim_id = p_claim_id)
    ORDER BY se.created_at DESC
    LIMIT 50
  ) sub;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_claim_activity"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claim_appointments"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY row_data->>'date' DESC, row_data->>'time_start' DESC NULLS LAST), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', a.id,
      'job_id', a.job_id,
      'job_number', j.job_number,
      'division', j.division,
      'title', a.title,
      'date', a.date,
      'time_start', a.time_start,
      'time_end', a.time_end,
      'type', a.type,
      'status', a.status,
      'notes', a.notes,
      'duration_days', a.duration_days,
      'is_milestone', a.is_milestone,
      'color', a.color,
      'crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'employee_id', ac.employee_id,
          'full_name', e.full_name,
          'role', ac.role
        ))
        FROM appointment_crew ac
        JOIN employees e ON e.id = ac.employee_id
        WHERE ac.appointment_id = a.id
      ), '[]'::jsonb),
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true)
    ) AS row_data
    FROM appointments a
    JOIN jobs j ON j.id = a.job_id
    WHERE j.claim_id = p_claim_id
  ) sub;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_claim_appointments"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claim_demo_sheets"("p_claim_id" "uuid") RETURNS TABLE("id" "uuid", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "email_sent" boolean, "job_id" "uuid", "job_number" "text", "job_division" "text", "technician_name" "text", "form_date" "date", "insured_name" "text", "address" "text", "room_count" integer, "summary" "jsonb")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    f.id,
    f.status,
    f.created_at,
    f.updated_at,
    f.email_sent,
    f.job_id,
    j.job_number,
    j.division::text AS job_division,
    f.technician_name,
    f.form_date,
    (f.form_data -> 'jobInfo' ->> 'insuredName') AS insured_name,
    (f.form_data -> 'jobInfo' ->> 'address')     AS address,
    COALESCE(jsonb_array_length(f.form_data -> 'rooms'), 0)::int AS room_count,
    f.summary
  FROM forms f
  JOIN jobs j ON j.id = f.job_id
  WHERE f.form_type = 'demo_sheet'
    AND j.claim_id = p_claim_id
  ORDER BY f.updated_at DESC;
$$;


ALTER FUNCTION "public"."get_claim_demo_sheets"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claim_detail"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(

    'claim', (SELECT to_jsonb(cl) FROM (
      SELECT c.id, c.claim_number, c.insurance_claim_number,
             c.contact_id, c.adjuster_contact_id,
             c.insurance_carrier, c.policy_number, c.date_of_loss,
             c.loss_address, c.loss_city, c.loss_state, c.loss_zip,
             c.loss_type, c.status, c.deductible, c.notes,
             c.created_at, c.updated_at
      FROM claims c WHERE c.id = p_claim_id
    ) cl),

    'jobs', COALESCE((
      SELECT jsonb_agg(to_jsonb(j) ORDER BY j.created_at ASC)
      FROM (
        SELECT j.id, j.job_number, j.division, j.phase, j.status, j.priority,
               j.insured_name, j.client_phone, j.client_email,
               j.address, j.city, j.state, j.zip,
               j.insurance_company, j.claim_number, j.policy_number,
               j.adjuster_name, j.adjuster_phone, j.adjuster_email,
               j.date_of_loss, j.type_of_loss, j.received_date, j.phase_entered_at,
               COALESCE(j.invoiced_value,        0)     AS invoiced_value,
               COALESCE(j.collected_value,       0)     AS collected_value,
               COALESCE(j.ar_status,        'open')     AS ar_status,
               j.ar_notes, j.invoiced_date, j.last_followup_date,
               COALESCE(j.deductible,            0)     AS deductible,
               COALESCE(j.deductible_collected,  false) AS deductible_collected,
               j.deductible_collected_date,
               COALESCE(j.depreciation_held,     0)     AS depreciation_held,
               COALESCE(j.depreciation_released, 0)     AS depreciation_released,
               COALESCE(j.supplement_value,      0)     AS supplement_value,
               COALESCE(j.estimated_value,       0)     AS estimated_value,
               COALESCE(j.approved_value,        0)     AS approved_value,
               j.primary_contact_id, j.claim_id,
               j.is_cat_loss, j.has_asbestos, j.has_lead,
               j.created_at, j.updated_at
        FROM jobs j WHERE j.claim_id = p_claim_id
      ) j
    ), '[]'::jsonb),

    'contact', (SELECT to_jsonb(ct) FROM (
      SELECT ct.id, ct.name, ct.phone, ct.email,
             ct.billing_address, ct.billing_city, ct.billing_state, ct.billing_zip
      FROM contacts ct
      WHERE ct.id = (SELECT contact_id FROM claims WHERE id = p_claim_id)
    ) ct),

    'adjuster', (SELECT to_jsonb(adj) FROM (
      SELECT adj.id, adj.name, adj.phone, adj.email, adj.company,
             adj.desk_phone, adj.desk_extension, adj.territory
      FROM contacts adj
      WHERE adj.id = (SELECT adjuster_contact_id FROM claims WHERE id = p_claim_id)
    ) adj)

  ) INTO result;
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_claim_detail"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claim_jobs"("p_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'claim', (SELECT to_jsonb(cl) FROM (
      SELECT id, claim_number, insurance_claim_number, contact_id,
             insurance_carrier, policy_number, date_of_loss,
             loss_address, loss_city, loss_state, loss_zip,
             loss_type, status, deductible
      FROM claims WHERE id = p_claim_id
    ) cl),
    'jobs', COALESCE((
      SELECT jsonb_agg(to_jsonb(j) ORDER BY j.created_at ASC)
      FROM (
        SELECT id, job_number, division, phase, status, priority,
               address, city, insured_name, type_of_loss,
               estimated_value, approved_value, date_of_loss, created_at
        FROM jobs WHERE claim_id = p_claim_id
      ) j
    ), '[]'::jsonb)
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_claim_jobs"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claim_rooms"("p_claim_id" "uuid") RETURNS TABLE("id" "uuid", "claim_id" "uuid", "name" "text", "area_sqft" numeric, "ceiling_height_ft" numeric, "sort_order" integer, "client_id" "uuid", "created_by" "uuid", "created_at" timestamp with time zone, "deleted_at" timestamp with time zone, "photo_count" integer, "reading_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT r.id, r.claim_id, r.name, r.area_sqft, r.ceiling_height_ft,
           r.sort_order, r.client_id, r.created_by, r.created_at, r.deleted_at,
           COALESCE((SELECT COUNT(*)::INT FROM job_documents d
                     WHERE d.room_id = r.id AND d.category='photo'), 0) AS photo_count,
           0::INT AS reading_count
    FROM rooms r
    WHERE r.claim_id = p_claim_id AND r.deleted_at IS NULL
    ORDER BY r.sort_order ASC, r.created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_claim_rooms"("p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_claims_list"() RETURNS TABLE("id" "uuid", "claim_number" "text", "insurance_claim_number" "text", "insurance_carrier" "text", "policy_number" "text", "date_of_loss" "date", "loss_type" "text", "loss_city" "text", "loss_state" "text", "status" "text", "deductible" numeric, "created_at" timestamp with time zone, "last_activity_at" timestamp with time zone, "insured_name" "text", "client_phone" "text", "job_count" bigint, "total_invoiced" numeric, "total_collected" numeric, "total_balance" numeric, "jobs_summary" "jsonb")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    c.id, c.claim_number, c.insurance_claim_number, c.insurance_carrier,
    c.policy_number, c.date_of_loss, c.loss_type, c.loss_city, c.loss_state,
    c.status, c.deductible, c.created_at,
    -- last_activity_at: NULL when no real activity exists (so the UI can distinguish)
    GREATEST(
      (SELECT MAX(a.updated_at) FROM appointments a JOIN jobs jj ON jj.id = a.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) AS last_activity_at,
    ct.name  AS insured_name,
    ct.phone AS client_phone,
    COUNT(j.id) AS job_count,
    COALESCE(SUM(COALESCE(j.invoiced_value,  0)), 0) AS total_invoiced,
    COALESCE(SUM(COALESCE(j.collected_value, 0)), 0) AS total_collected,
    COALESCE(SUM(GREATEST(COALESCE(j.invoiced_value,0) - COALESCE(j.collected_value,0), 0)), 0) AS total_balance,
    COALESCE(
      jsonb_agg(
        jsonb_build_object('id', j.id, 'job_number', j.job_number, 'division', j.division, 'phase', j.phase)
        ORDER BY j.created_at ASC
      ) FILTER (WHERE j.id IS NOT NULL),
      '[]'::jsonb
    ) AS jobs_summary
  FROM claims c
  LEFT JOIN contacts ct ON ct.id = c.contact_id
  LEFT JOIN jobs j ON j.claim_id = c.id
  WHERE c.status IS DISTINCT FROM 'deleted'
  GROUP BY c.id, ct.name, ct.phone
  ORDER BY
    GREATEST(
      (SELECT MAX(a.updated_at) FROM appointments a JOIN jobs jj ON jj.id = a.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) DESC NULLS LAST,
    c.created_at DESC;
$$;


ALTER FUNCTION "public"."get_claims_list"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_commissions"("p_month" "date" DEFAULT NULL::"date") RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "job_id" "uuid", "job_number" "text", "division" "text", "sale_date" timestamp with time zone, "sale_source" "text", "base" numeric, "commission" numeric, "commission_period" "date", "is_attributed" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH inv AS (
    SELECT i.job_id, SUM(COALESCE(i.adjusted_total, i.total, 0)) AS base
    FROM public.invoices i
    GROUP BY i.job_id
  ),
  sold AS (
    SELECT j.id AS job_id,
           COALESCE(
             (SELECT sr.sent_by FROM public.sign_requests sr
               WHERE sr.job_id = j.id AND sr.status = 'signed'
                 AND sr.doc_type IN ('work_auth','recon_agreement') AND sr.sent_by IS NOT NULL
               ORDER BY sr.signed_at NULLS LAST LIMIT 1),
             (SELECT e.created_by FROM public.estimates e
               WHERE e.job_id = j.id AND e.created_by IS NOT NULL
                 AND lower(COALESCE(e.status,'')) IN ('approved','accepted','converted','signed')
               ORDER BY e.approved_at NULLS LAST LIMIT 1)
           ) AS sold_by
    FROM public.jobs j
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
  )
  SELECT
    sd.sold_by                                            AS employee_id,
    emp.full_name                                         AS employee_name,
    j.id                                                  AS job_id,
    j.job_number,
    j.division::text                                      AS division,
    j.created_at                                          AS sale_date,
    j.real_job_source                                     AS sale_source,
    COALESCE(iv.base, 0)                                  AS base,
    CASE
      WHEN emp.commission_flat    IS NOT NULL THEN emp.commission_flat
      WHEN emp.commission_percent IS NOT NULL THEN round(COALESCE(iv.base, 0) * emp.commission_percent / 100.0, 2)
      ELSE 0
    END                                                   AS commission,
    date_trunc('month', j.created_at)::date               AS commission_period,
    (sd.sold_by IS NOT NULL
       AND (emp.commission_percent IS NOT NULL OR emp.commission_flat IS NOT NULL)) AS is_attributed
  FROM public.jobs j
  JOIN sold sd              ON sd.job_id = j.id
  LEFT JOIN public.employees emp ON emp.id = sd.sold_by
  LEFT JOIN inv iv          ON iv.job_id = j.id
  WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
    AND (p_month IS NULL
         OR date_trunc('month', j.created_at) = date_trunc('month', p_month::timestamptz))
  ORDER BY j.created_at DESC;
$$;


ALTER FUNCTION "public"."get_commissions"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_activity"("p_contact_id" "uuid") RETURNS TABLE("activity_type" "text", "occurred_at" timestamp with time zone, "title" "text", "body" "text", "meta" "jsonb")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    'lead'::text,
    COALESCE(il.occurred_at, il.created_at),
    CASE WHEN il.source_type = 'call' THEN 'Call' ELSE 'Web form' END,
    il.transcription,
    jsonb_build_object(
      'source_type', il.source_type, 'duration_sec', il.duration_sec,
      'lead_status', il.lead_status, 'source', il.source, 'campaign', il.campaign,
      'recording_url', il.recording_url, 'transcript_analysis', il.transcript_analysis
    )
  FROM inbound_leads il
  WHERE il.contact_id = p_contact_id
    AND il.merged_into_lead_id IS NULL

  UNION ALL

  SELECT
    'sms'::text,
    m.created_at,
    CASE WHEN m.sender_contact_id = p_contact_id THEN 'Received SMS' ELSE 'Sent SMS' END,
    m.body,
    jsonb_build_object(
      'type', m.type, 'status', m.status,
      'sent_by_name', COALESCE(es.display_name, es.full_name)
    )
  FROM messages m
  LEFT JOIN employees es ON es.id = m.sent_by
  WHERE m.conversation_id IN (
    SELECT cp.conversation_id FROM conversation_participants cp WHERE cp.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'note'::text,
    jn.created_at,
    'Note'::text,
    jn.body,
    jsonb_build_object('job_id', jn.job_id, 'author_name', jn.author_name)
  FROM job_notes jn
  WHERE jn.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'note'::text,
    ln.created_at,
    'Note'::text,
    ln.body,
    jsonb_build_object('note_id', ln.id, 'author_name', COALESCE(eln.display_name, eln.full_name))
  FROM crm_lead_notes ln
  LEFT JOIN employees eln ON eln.id = ln.created_by
  WHERE ln.contact_id = p_contact_id
     OR ln.lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'estimate'::text,
    e.created_at,
    'Estimate ' || COALESCE(e.estimate_number, e.id::text),
    NULL::text,
    jsonb_build_object(
      'status', e.status, 'amount', e.amount, 'estimate_id', e.id,
      'created_by_name', COALESCE(eest.display_name, eest.full_name)
    )
  FROM estimates e
  LEFT JOIN employees eest ON eest.id = e.created_by
  WHERE e.contact_id = p_contact_id

  UNION ALL

  SELECT
    'email'::text,
    COALESCE(r.sent_at, r.created_at),
    'Campaign email'::text,
    ec.subject,
    jsonb_build_object('status', r.status, 'campaign', ec.name, 'campaign_id', ec.id)
  FROM email_campaign_recipients r
  JOIN email_campaigns ec ON ec.id = r.campaign_id
  WHERE r.contact_id = p_contact_id

  UNION ALL

  SELECT
    'job'::text,
    j.created_at,
    'Job ' || COALESCE(j.job_number, j.id::text),
    j.address,
    jsonb_build_object('status', j.status, 'job_id', j.id)
  FROM jobs j
  WHERE j.id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'task'::text,
    COALESCE(t.due_at, t.created_at),
    t.title,
    t.notes,
    jsonb_build_object(
      'status', t.status, 'due_at', t.due_at, 'task_id', t.id,
      'created_by_name', COALESCE(etc.display_name, etc.full_name),
      'assignee_name', COALESCE(eta.display_name, eta.full_name)
    )
  FROM crm_tasks t
  LEFT JOIN employees etc ON etc.id = t.created_by
  LEFT JOIN employees eta ON eta.id = t.assignee_id
  WHERE t.contact_id = p_contact_id
     OR t.lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'appointment'::text,
    (a.date + COALESCE(a.time_start, '00:00'::time))::timestamptz,
    COALESCE(a.title, 'Appointment'),
    a.notes,
    jsonb_build_object(
      'status', a.status, 'type', a.type, 'time_start', a.time_start,
      'time_end', a.time_end, 'job_id', a.job_id,
      'created_by_name', COALESCE(eap.display_name, eap.full_name)
    )
  FROM appointments a
  LEFT JOIN employees eap ON eap.id = a.created_by
  WHERE a.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'invoice'::text,
    COALESCE(i.invoice_date::timestamptz, i.created_at),
    'Invoice ' || COALESCE(i.invoice_number, i.id::text),
    NULL::text,
    jsonb_build_object(
      'status', i.status, 'total', i.total, 'amount_paid', i.amount_paid,
      'balance_due', i.balance_due, 'invoice_id', i.id, 'due_date', i.due_date,
      'created_by_name', COALESCE(einv.display_name, einv.full_name)
    )
  FROM invoices i
  LEFT JOIN employees einv ON einv.id = i.created_by
  WHERE i.contact_id = p_contact_id

  UNION ALL

  SELECT
    'work_authorization'::text,
    COALESCE(sr.signed_at, sr.sent_at, sr.created_at),
    COALESCE(initcap(replace(sr.doc_type, '_', ' ')), 'Work Authorization'),
    NULL::text,
    jsonb_build_object(
      'status', sr.status, 'doc_type', sr.doc_type, 'signed_at', sr.signed_at,
      'signed_file_path', sr.signed_file_path, 'job_id', sr.job_id,
      'sent_by_name', COALESCE(esr.display_name, esr.full_name)
    )
  FROM sign_requests sr
  LEFT JOIN employees esr ON esr.id = sr.sent_by
  WHERE sr.contact_id = p_contact_id

  UNION ALL

  SELECT
    'stage_change'::text,
    lsh.moved_at,
    'Moved to ' || ps.name,
    NULL::text,
    jsonb_build_object(
      'from_stage_id', lsh.from_stage_id, 'stage_id', lsh.stage_id, 'lost_reason', lsh.lost_reason,
      'moved_by_name', COALESCE(elsh.display_name, elsh.full_name)
    )
  FROM lead_stage_history lsh
  JOIN pipeline_stages ps ON ps.id = lsh.stage_id
  LEFT JOIN employees elsh ON elsh.id = lsh.moved_by
  WHERE lsh.lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'follow_up_call'::text,
    COALESCE(fu.occurred_at, fu.created_at),
    CASE WHEN fu.source_type = 'call' THEN 'Follow-up call' ELSE 'Follow-up web form' END,
    fu.transcription,
    jsonb_build_object(
      'source_type', fu.source_type, 'duration_sec', fu.duration_sec,
      'caller_number', fu.caller_number, 'recording_url', fu.recording_url,
      'transcript_analysis', fu.transcript_analysis, 'merged_lead_id', fu.id
    )
  FROM inbound_leads fu
  WHERE fu.merged_into_lead_id IN (SELECT id FROM inbound_leads WHERE contact_id = p_contact_id)

  UNION ALL

  SELECT
    'claim'::text,
    cl.created_at,
    'Claim ' || COALESCE(cl.claim_number, cl.id::text),
    NULLIF(TRIM(BOTH ' ' FROM COALESCE(cl.loss_type, '') || CASE WHEN cl.insurance_carrier IS NOT NULL THEN ' — ' || cl.insurance_carrier ELSE '' END), ''),
    jsonb_build_object(
      'status', cl.status, 'claim_id', cl.id, 'insurance_carrier', cl.insurance_carrier,
      'date_of_loss', cl.date_of_loss,
      'created_by_name', COALESCE(ecl.display_name, ecl.full_name)
    )
  FROM claims cl
  LEFT JOIN employees ecl ON ecl.id = cl.created_by
  WHERE cl.contact_id = p_contact_id

  UNION ALL

  SELECT
    'phase_change'::text,
    h.changed_at,
    'Phase: ' || COALESCE(pf.label, h.from_phase) || ' → ' || COALESCE(pt.label, h.to_phase),
    NULL::text,
    jsonb_build_object(
      'job_id', h.job_id, 'from_phase', h.from_phase, 'to_phase', h.to_phase,
      'changed_by_name', COALESCE(eph.display_name, eph.full_name)
    )
  FROM job_phase_history h
  LEFT JOIN employees eph ON eph.id = h.changed_by
  LEFT JOIN job_phases pf ON pf.key = h.from_phase
  LEFT JOIN job_phases pt ON pt.key = h.to_phase
  WHERE h.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'payment'::text,
    COALESCE(p.payment_date::timestamptz, p.created_at),
    'Payment received'::text,
    NULL::text,
    jsonb_build_object(
      'amount', p.amount, 'method', p.payment_method, 'invoice_id', p.invoice_id,
      'recorded_by_name', COALESCE(epay.display_name, epay.full_name)
    )
  FROM payments p
  LEFT JOIN employees epay ON epay.id = p.recorded_by
  WHERE p.contact_id = p_contact_id

  UNION ALL

  SELECT
    'document'::text,
    jd.created_at,
    COALESCE(jd.name, initcap(replace(jd.category, '_', ' ')), 'Document'),
    NULL::text,
    jsonb_build_object(
      'job_id', jd.job_id, 'category', jd.category,
      'uploaded_by_name', COALESCE(eupl.display_name, eupl.full_name)
    )
  FROM job_documents jd
  LEFT JOIN employees eupl ON eupl.id = jd.uploaded_by
  WHERE jd.job_id IN (
    SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
  )

  UNION ALL

  SELECT
    'contact_owner_set'::text,
    se_own.created_at,
    'Owner changed'::text,
    NULL::text,
    se_own.payload || jsonb_build_object(
      'actor_name', COALESCE(eown.display_name, eown.full_name)
    )
  FROM system_events se_own
  LEFT JOIN employees eown ON eown.id = se_own.actor_id
  WHERE se_own.event_type = 'crm_contact_owner_set'
    AND se_own.entity_type = 'contact'
    AND se_own.entity_id = p_contact_id

  UNION ALL

  SELECT
    'contact_lifecycle_set'::text,
    se_life.created_at,
    'Lifecycle status changed'::text,
    NULL::text,
    se_life.payload || jsonb_build_object(
      'actor_name', COALESCE(elife.display_name, elife.full_name)
    )
  FROM system_events se_life
  LEFT JOIN employees elife ON elife.id = se_life.actor_id
  WHERE se_life.event_type = 'crm_contact_lifecycle_set'
    AND se_life.entity_type = 'contact'
    AND se_life.entity_id = p_contact_id

  UNION ALL

  SELECT
    'work_auth_sent'::text,
    COALESCE(wasent.sent_at, wasent.created_at),
    'Work authorization sent'::text,
    NULL::text,
    jsonb_build_object(
      'status', wasent.status, 'doc_type', wasent.doc_type, 'sent_at', wasent.sent_at,
      'job_id', wasent.job_id, 'signer_name', wasent.signer_name, 'signer_email', wasent.signer_email,
      'sent_by_name', COALESCE(ewasent.display_name, ewasent.full_name)
    )
  FROM sign_requests wasent
  LEFT JOIN employees ewasent ON ewasent.id = wasent.sent_by
  WHERE wasent.contact_id = p_contact_id
    AND wasent.doc_type = 'work_auth'

  UNION ALL

  SELECT
    'work_auth_signed'::text,
    wasigned.signed_at,
    'Work authorization signed'::text,
    NULL::text,
    jsonb_build_object(
      'status', wasigned.status, 'doc_type', wasigned.doc_type, 'job_id', wasigned.job_id,
      'signed_file_path', wasigned.signed_file_path,
      'signer_name', wasigned.signer_name, 'signer_email', wasigned.signer_email
    )
  FROM sign_requests wasigned
  WHERE wasigned.contact_id = p_contact_id
    AND wasigned.doc_type = 'work_auth'
    AND wasigned.signed_at IS NOT NULL

  UNION ALL

  SELECT
    'scope_sheet'::text,
    COALESCE(ds.form_date::timestamptz, ds.created_at),
    COALESCE('Scope sheet — ' || ds.technician_name, 'Scope sheet'),
    NULL::text,
    jsonb_build_object(
      'status', ds.status, 'job_id', ds.job_id, 'technician_name', ds.technician_name,
      'form_date', ds.form_date, 'summary', ds.summary,
      'submitted_by_name', COALESCE(eds.display_name, eds.full_name)
    )
  FROM forms ds
  LEFT JOIN employees eds ON eds.id = ds.submitted_by
  WHERE ds.form_type = 'demo_sheet'
    AND ds.job_id IN (
      SELECT cj.job_id FROM contact_jobs cj WHERE cj.contact_id = p_contact_id
    )

  UNION ALL

  SELECT
    'invoice_sent'::text,
    i2.qbo_emailed_at,
    'Invoice sent' || CASE WHEN i2.invoice_number IS NOT NULL THEN ' — ' || i2.invoice_number ELSE '' END,
    NULL::text,
    jsonb_build_object(
      'invoice_id', i2.id, 'sent_to_email', i2.sent_to_email, 'qbo_email_status', i2.qbo_email_status
    )
  FROM invoices i2
  WHERE i2.contact_id = p_contact_id
    AND i2.qbo_emailed_at IS NOT NULL

  UNION ALL

  SELECT
    'estimate_sent'::text,
    e2.qbo_emailed_at,
    'Estimate sent' || CASE WHEN e2.estimate_number IS NOT NULL THEN ' — ' || e2.estimate_number ELSE '' END,
    NULL::text,
    jsonb_build_object(
      'estimate_id', e2.id, 'sent_to_email', e2.sent_to_email, 'qbo_email_status', e2.qbo_email_status
    )
  FROM estimates e2
  WHERE e2.contact_id = p_contact_id
    AND e2.qbo_emailed_at IS NOT NULL

  ORDER BY 2 DESC;
$$;


ALTER FUNCTION "public"."get_contact_activity"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_addresses"("p_contact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(to_jsonb(a) ORDER BY a.is_billing DESC, a.created_at ASC)
    FROM contact_addresses a WHERE a.contact_id = p_contact_id
  ), '[]'::jsonb);
END; $$;


ALTER FUNCTION "public"."get_contact_addresses"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_consent"("p_contact_id" "uuid") RETURNS json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'contact_id', c.id,
    'do_not_contact',
      COALESCE(c.dnd, false)
      OR c.opt_out_at IS NOT NULL
      OR EXISTS (SELECT 1 FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))),
    'sms', json_build_object(
      'dnd', COALESCE(c.dnd, false),
      'opted_out', c.opt_out_at IS NOT NULL,
      'opt_out_at', c.opt_out_at,
      'opt_out_reason', c.opt_out_reason
    ),
    'email', json_build_object(
      'address', c.email,
      'suppressed', EXISTS (SELECT 1 FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))),
      'reason', (SELECT es.reason FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))
                 ORDER BY es.suppressed_at DESC NULLS LAST LIMIT 1),
      'suppressed_at', (SELECT es.suppressed_at FROM email_suppressions es
                 WHERE c.email IS NOT NULL AND lower(btrim(es.email)) = lower(btrim(c.email))
                 ORDER BY es.suppressed_at DESC NULLS LAST LIMIT 1)
    )
  )
  FROM contacts c
  WHERE c.id = p_contact_id;
$$;


ALTER FUNCTION "public"."get_contact_consent"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contact_ltv"("p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH won AS (
    SELECT j.primary_contact_id AS cid,
           COUNT(*) AS jobs,
           COALESCE(SUM(j.invoiced_value), 0) AS revenue,
           MIN(COALESCE(cl.created_at, j.created_at)) AS first_job_at,
           MAX(COALESCE(cl.created_at, j.created_at)) AS last_job_at
    FROM jobs j
    LEFT JOIN claims cl ON cl.id = j.claim_id
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
      AND j.primary_contact_id IS NOT NULL
      AND (p_contact_id IS NULL OR j.primary_contact_id = p_contact_id)
    GROUP BY j.primary_contact_id
  )
  SELECT json_build_object(
    'contact_id',   won.cid,
    'contact_name', c.name,
    'jobs',         won.jobs,
    'revenue',      won.revenue,
    'first_job_at', won.first_job_at,
    'last_job_at',  won.last_job_at,
    'is_repeat',    (won.jobs > 1)
  )
  FROM won
  LEFT JOIN contacts c ON c.id = won.cid
  ORDER BY won.revenue DESC
  LIMIT (CASE WHEN p_contact_id IS NULL THEN 25 ELSE 1 END);
END;
$$;


ALTER FUNCTION "public"."get_contact_ltv"("p_contact_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contractor_compliance_audit_manifest"("p_audit_period_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_paid_filter" "text" DEFAULT NULL::"text", "p_active_filter" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_period public.contractor_compliance_audit_periods;
  v_result jsonb;
BEGIN
  SELECT e.role::text INTO v_role
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid() AND e.is_active AND NOT e.is_external;
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND (v_role IS NULL OR v_role NOT IN ('admin', 'office', 'project_manager')) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor audit access required' USING errcode = '42501';
  END IF;
  IF p_limit NOT BETWEEN 1 AND 100
     OR p_offset < 0
     OR COALESCE(p_status, 'all') NOT IN ('all', 'ready', 'gap')
     OR COALESCE(p_paid_filter, 'all') NOT IN ('all', 'yes', 'no', 'unknown')
     OR COALESCE(p_active_filter, 'all') NOT IN ('all', 'yes', 'no', 'unknown') THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: manifest filters' USING errcode = '22023';
  END IF;
  IF v_role = 'project_manager'
     AND (
       COALESCE(p_paid_filter, 'all') <> 'all'
       OR COALESCE(p_active_filter, 'all') <> 'all'
     ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: period fact filters require audit manager' USING errcode = '42501';
  END IF;
  SELECT * INTO v_period
  FROM public.contractor_compliance_audit_periods
  WHERE id = p_audit_period_id;
  IF v_period.id IS NULL THEN
    RAISE EXCEPTION 'NOT_FOUND: audit period missing' USING errcode = 'P0002';
  END IF;

  WITH roster_rows AS (
    SELECT
      r.profile_id,
      c.id AS contact_id,
      c.name,
      c.company,
      c.trade_specialty,
      r.inclusion_source,
      r.active_in_period,
      r.paid_in_period,
      r.external_source,
      r.source_external_id,
      r.reconciliation_state,
      CASE WHEN EXISTS (
        SELECT 1 FROM public.contractor_compliance_audit_evidence e
        WHERE e.audit_period_id = r.audit_period_id
          AND e.profile_id = r.profile_id
          AND e.requirement_group = 'workers_comp'
          AND e.interval_kind = 'gap'
      ) THEN 'gap' ELSE 'ready' END AS workers_comp_status,
      CASE WHEN EXISTS (
        SELECT 1 FROM public.contractor_compliance_audit_evidence e
        WHERE e.audit_period_id = r.audit_period_id
          AND e.profile_id = r.profile_id
          AND e.requirement_group = 'general_liability'
          AND e.interval_kind = 'gap'
      ) THEN 'gap' ELSE 'ready' END AS general_liability_status,
      (
        SELECT count(*) FROM public.contractor_compliance_audit_requests q
        WHERE q.audit_period_id = r.audit_period_id AND q.profile_id = r.profile_id
      ) AS request_count,
      (
        SELECT max(q.sent_at_snapshot) FROM public.contractor_compliance_audit_requests q
        WHERE q.audit_period_id = r.audit_period_id AND q.profile_id = r.profile_id
      ) AS last_request_at
    FROM public.contractor_compliance_audit_roster r
    JOIN public.contractor_compliance_profiles p ON p.id = r.profile_id
    JOIN public.contacts c ON c.id = p.contact_id
    WHERE r.audit_period_id = v_period.id AND r.included
  ),
  classified AS (
    SELECT *,
      CASE
        WHEN workers_comp_status = 'gap' OR general_liability_status = 'gap' THEN 'gap'
        ELSE 'ready'
      END AS overall_status
    FROM roster_rows
  ),
  filtered AS (
    SELECT * FROM classified
    WHERE (
      NULLIF(btrim(p_search), '') IS NULL
      OR name ILIKE '%' || btrim(p_search) || '%'
      OR company ILIKE '%' || btrim(p_search) || '%'
      OR trade_specialty ILIKE '%' || btrim(p_search) || '%'
    )
      AND (COALESCE(p_status, 'all') = 'all' OR overall_status = p_status)
      AND (
        COALESCE(p_paid_filter, 'all') = 'all'
        OR (p_paid_filter = 'yes' AND paid_in_period IS TRUE)
        OR (p_paid_filter = 'no' AND paid_in_period IS FALSE)
        OR (p_paid_filter = 'unknown' AND paid_in_period IS NULL)
      )
      AND (
        COALESCE(p_active_filter, 'all') = 'all'
        OR (p_active_filter = 'yes' AND active_in_period IS TRUE)
        OR (p_active_filter = 'no' AND active_in_period IS FALSE)
        OR (p_active_filter = 'unknown' AND active_in_period IS NULL)
      )
  )
  SELECT jsonb_build_object(
    'period', jsonb_build_object(
      'id', v_period.id,
      'name', v_period.name,
      'start_date', v_period.start_date,
      'end_date', v_period.end_date,
      'status', v_period.status,
      'materialized_at', v_period.materialized_at,
      'locked_at', v_period.locked_at
    ),
    'total', (SELECT count(*) FROM filtered),
    'items', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'contractor_id', f.contact_id,
        'name', f.name,
        'company', f.company,
        'trade_specialty', f.trade_specialty,
        'inclusion_source', f.inclusion_source,
        'active_in_period', CASE WHEN v_role IN ('admin', 'office') THEN f.active_in_period END,
        'paid_in_period', CASE WHEN v_role IN ('admin', 'office') THEN f.paid_in_period END,
        'external_source', CASE WHEN v_role IN ('admin', 'office') THEN f.external_source END,
        'source_external_id', CASE WHEN v_role IN ('admin', 'office') THEN f.source_external_id END,
        'reconciliation_state', CASE WHEN v_role IN ('admin', 'office') THEN f.reconciliation_state END,
        'overall_status', f.overall_status,
        'workers_comp_status', f.workers_comp_status,
        'general_liability_status', f.general_liability_status,
        'request_count', f.request_count,
        'last_request_at', f.last_request_at,
        'evidence', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'requirement_group', e.requirement_group,
            'interval_kind', e.interval_kind,
            'start_date', e.interval_start,
            'end_date', e.interval_end,
            'document_id', CASE WHEN v_role IN ('admin', 'office') THEN e.document_id END,
            'document_version', e.document_version
          ) ORDER BY e.requirement_group, e.interval_start, e.interval_kind)
          FROM public.contractor_compliance_audit_evidence e
          WHERE e.audit_period_id = v_period.id AND e.profile_id = f.profile_id
        ), '[]'::jsonb)
      ) ORDER BY CASE f.overall_status WHEN 'gap' THEN 1 ELSE 2 END, f.name)
      FROM (
        SELECT * FROM filtered
        ORDER BY CASE overall_status WHEN 'gap' THEN 1 ELSE 2 END, name
        LIMIT p_limit OFFSET p_offset
      ) f
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_contractor_compliance_audit_manifest"("p_audit_period_id" "uuid", "p_search" "text", "p_status" "text", "p_paid_filter" "text", "p_active_filter" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contractor_compliance_audit_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_result jsonb;
BEGIN
  SELECT e.role::text INTO v_role
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid() AND e.is_active AND NOT e.is_external;
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND (v_role IS NULL OR v_role NOT IN ('admin', 'office', 'project_manager')) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor audit access required' USING errcode = '42501';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', p.id,
    'name', p.name,
    'start_date', p.start_date,
    'end_date', p.end_date,
    'status', p.status,
    'inclusion_basis', p.inclusion_basis,
    'materialized_at', p.materialized_at,
    'locked_at', p.locked_at,
    'roster_count', (
      SELECT count(*) FROM public.contractor_compliance_audit_roster r
      WHERE r.audit_period_id = p.id AND r.included
    )
  ) ORDER BY p.start_date DESC, p.created_at DESC), '[]'::jsonb)
  INTO v_result
  FROM public.contractor_compliance_audit_periods p;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_contractor_compliance_audit_periods"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contractor_compliance_dashboard"("p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_audit_start" "date" DEFAULT NULL::"date", "p_audit_end" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_today date := (now() AT TIME ZONE 'America/Denver')::date;
  v_start date := COALESCE(p_audit_start, (now() AT TIME ZONE 'America/Denver')::date);
  v_end date := COALESCE(p_audit_end, COALESCE(p_audit_start, (now() AT TIME ZONE 'America/Denver')::date));
  v_result jsonb;
BEGIN
  SELECT e.role::text INTO v_role FROM public.employees e
  WHERE e.auth_user_id = auth.uid() AND e.is_active IS TRUE AND e.is_external IS FALSE;
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND (v_role IS NULL OR v_role NOT IN ('admin', 'office', 'project_manager')) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance access required' USING errcode = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 OR p_offset IS NULL OR p_offset < 0 OR v_end < v_start OR EXTRACT(YEAR FROM v_start) <> EXTRACT(YEAR FROM v_end) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: invalid contractor compliance page or audit range' USING errcode = '22023';
  END IF;
  WITH rows AS (
    SELECT p.id profile_id, c.id contact_id, c.name, c.company, c.trade_specialty, p.is_active, p.required_w9_year,
      owner.full_name owner_name,
      (SELECT max(r.sent_at) FROM public.contractor_compliance_requests r WHERE r.profile_id = p.id) last_request_at,
      CASE WHEN p.is_active IS FALSE THEN 'inactive'
           WHEN NOT EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='w9' AND d.review_state IN ('accepted','superseded') AND d.tax_year=EXTRACT(YEAR FROM v_start)::integer) THEN CASE WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='w9' AND d.review_state='pending_review' AND d.tax_year=EXTRACT(YEAR FROM v_start)::integer) THEN 'needs_review' ELSE 'missing' END
           ELSE 'ready' END AS w9_status,
      CASE WHEN p.is_active IS FALSE THEN 'inactive'
           WHEN public.contractor_compliance_has_continuous_coverage(p.id,ARRAY['workers_comp','workers_comp_waiver'],v_start,v_end) THEN CASE WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state IN ('accepted','superseded') AND d.coverage_start_date <= v_today AND d.coverage_end_date >= v_today AND d.coverage_end_date <= v_today + 60) THEN 'expiring' ELSE 'ready' END
           WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state='pending_review') THEN 'needs_review'
           WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state IN ('accepted','superseded') AND d.coverage_end_date < v_start) THEN 'expired'
           WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state IN ('accepted','superseded')) THEN 'gap' ELSE 'missing' END AS workers_comp_status,
      CASE WHEN p.is_active IS FALSE THEN 'inactive'
           WHEN public.contractor_compliance_has_continuous_coverage(p.id,ARRAY['general_liability'],v_start,v_end) THEN CASE WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='general_liability' AND d.review_state IN ('accepted','superseded') AND d.coverage_start_date <= v_today AND d.coverage_end_date >= v_today AND d.coverage_end_date <= v_today + 60) THEN 'expiring' ELSE 'ready' END
           WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='general_liability' AND d.review_state='pending_review') THEN 'needs_review'
           WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='general_liability' AND d.review_state IN ('accepted','superseded') AND d.coverage_end_date < v_start) THEN 'expired'
           WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type='general_liability' AND d.review_state IN ('accepted','superseded')) THEN 'gap' ELSE 'missing' END AS general_liability_status,
      (SELECT min(d.coverage_end_date) FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id AND d.document_type <> 'w9' AND d.review_state IN ('accepted','superseded') AND d.coverage_end_date >= v_today) earliest_expiration
    FROM public.contractor_compliance_profiles p
    JOIN public.contacts c ON c.id=p.contact_id AND c.role='subcontractor'
    LEFT JOIN public.employees owner ON owner.id=p.assigned_owner_id
  ), classified AS (
    SELECT *, CASE WHEN is_active IS FALSE THEN 'inactive'
      WHEN 'expired' IN (w9_status, workers_comp_status, general_liability_status) THEN 'expired'
      WHEN 'gap' IN (w9_status, workers_comp_status, general_liability_status) THEN 'gap'
      WHEN 'missing' IN (w9_status, workers_comp_status, general_liability_status) THEN 'missing'
      WHEN 'needs_review' IN (w9_status, workers_comp_status, general_liability_status) THEN 'needs_review'
      WHEN 'expiring' IN (w9_status, workers_comp_status, general_liability_status) THEN 'expiring'
      ELSE 'ready' END overall_status
    FROM rows
  ), filtered AS (
    SELECT * FROM classified WHERE (NULLIF(btrim(p_search),'') IS NULL OR name ILIKE '%' || btrim(p_search) || '%' OR company ILIKE '%' || btrim(p_search) || '%' OR trade_specialty ILIKE '%' || btrim(p_search) || '%')
      AND (NULLIF(btrim(p_status),'') IS NULL OR overall_status = p_status)
  )
  SELECT jsonb_build_object('audit', jsonb_build_object('start_date',v_start,'end_date',v_end,'timezone','America/Denver'),
    'audit_period', jsonb_build_object('start_date',v_start,'end_date',v_end,'timezone','America/Denver'),
    'total',(SELECT count(*) FROM filtered), 'total_count',(SELECT count(*) FROM filtered),
    'kpis',jsonb_build_object('ready',(SELECT count(*) FROM filtered WHERE overall_status='ready'),'missing',(SELECT count(*) FROM filtered WHERE overall_status='missing'),'needs_review',(SELECT count(*) FROM filtered WHERE overall_status='needs_review'),'expiring',(SELECT count(*) FROM filtered WHERE overall_status='expiring'),'expired',(SELECT count(*) FROM filtered WHERE overall_status='expired'),'gap',(SELECT count(*) FROM filtered WHERE overall_status='gap'),'inactive',(SELECT count(*) FROM filtered WHERE overall_status='inactive')),
    'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('contractor_id',contact_id,'contact_id',contact_id,'profile_id',profile_id,'name',name,'company',company,'trade_specialty',trade_specialty,'overall_status',overall_status,'requirements',jsonb_build_object('w9',jsonb_build_object('status',w9_status),'workers_comp',jsonb_build_object('status',workers_comp_status),'general_liability',jsonb_build_object('status',general_liability_status)),'w9_status',w9_status,'workers_comp_status',workers_comp_status,'general_liability_status',general_liability_status,'earliest_expiration',earliest_expiration,'assigned_owner_name',owner_name,'last_request_at',last_request_at) ORDER BY CASE overall_status WHEN 'expired' THEN 1 WHEN 'gap' THEN 2 WHEN 'missing' THEN 3 WHEN 'needs_review' THEN 4 WHEN 'expiring' THEN 5 WHEN 'inactive' THEN 6 ELSE 7 END, earliest_expiration NULLS LAST, name) FROM (SELECT * FROM filtered ORDER BY CASE overall_status WHEN 'expired' THEN 1 WHEN 'gap' THEN 2 WHEN 'missing' THEN 3 WHEN 'needs_review' THEN 4 WHEN 'expiring' THEN 5 WHEN 'inactive' THEN 6 ELSE 7 END, earliest_expiration NULLS LAST, name LIMIT p_limit OFFSET p_offset) page),'[]'::jsonb)) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_contractor_compliance_dashboard"("p_search" "text", "p_status" "text", "p_limit" integer, "p_offset" integer, "p_audit_start" "date", "p_audit_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contractor_compliance_detail"("p_contact_id" "uuid", "p_audit_start" "date" DEFAULT NULL::"date", "p_audit_end" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_profile uuid;
  v_result jsonb;
  v_active boolean;
  v_today date := (now() AT TIME ZONE 'America/Denver')::date;
  v_start date := COALESCE(p_audit_start, (now() AT TIME ZONE 'America/Denver')::date);
  v_end date := COALESCE(p_audit_end, COALESCE(p_audit_start, (now() AT TIME ZONE 'America/Denver')::date));
  v_w9_year integer;
  v_w9_status text;
  v_wc_status text;
  v_gl_status text;
  v_overall text;
  v_wc_end date;
  v_gl_end date;
BEGIN
  SELECT e.role::text INTO v_role FROM public.employees e WHERE e.auth_user_id=auth.uid() AND e.is_active IS TRUE AND e.is_external IS FALSE;
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND (v_role IS NULL OR v_role NOT IN ('admin','office','project_manager')) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: contractor compliance access required' USING errcode='42501';
  END IF;
  IF (p_audit_start IS NULL) <> (p_audit_end IS NULL)
     OR v_end < v_start
     OR EXTRACT(YEAR FROM v_start) <> EXTRACT(YEAR FROM v_end) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: audit period must be complete and remain within one Denver calendar year' USING errcode='22023';
  END IF;
  SELECT p.id,p.is_active INTO v_profile,v_active
  FROM public.contractor_compliance_profiles p
  JOIN public.contacts c ON c.id=p.contact_id AND c.role='subcontractor'
  WHERE p.contact_id=p_contact_id;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: contractor profile not found' USING errcode='P0002'; END IF;
  v_w9_year := EXTRACT(YEAR FROM v_start)::integer;
  v_wc_end := public.contractor_compliance_continuous_coverage_end(v_profile,ARRAY['workers_comp','workers_comp_waiver'],v_start);
  v_gl_end := public.contractor_compliance_continuous_coverage_end(v_profile,ARRAY['general_liability'],v_start);

  v_w9_status := CASE WHEN NOT v_active THEN 'inactive'
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type='w9' AND d.review_state IN ('accepted','superseded') AND d.tax_year=v_w9_year) THEN 'ready'
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type='w9' AND d.review_state='pending_review' AND d.tax_year=v_w9_year) THEN 'needs_review'
    ELSE 'missing' END;
  v_wc_status := CASE WHEN NOT v_active THEN 'inactive'
    WHEN public.contractor_compliance_has_continuous_coverage(v_profile,ARRAY['workers_comp','workers_comp_waiver'],v_start,v_end)
      THEN CASE WHEN p_audit_start IS NULL AND v_wc_end<=v_today+60 THEN 'expiring' ELSE 'ready' END
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state='pending_review') THEN 'needs_review'
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state IN ('accepted','superseded') AND d.coverage_end_date<v_start) THEN 'expired'
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type IN ('workers_comp','workers_comp_waiver') AND d.review_state IN ('accepted','superseded')) THEN 'gap'
    ELSE 'missing' END;
  v_gl_status := CASE WHEN NOT v_active THEN 'inactive'
    WHEN public.contractor_compliance_has_continuous_coverage(v_profile,ARRAY['general_liability'],v_start,v_end)
      THEN CASE WHEN p_audit_start IS NULL AND v_gl_end<=v_today+60 THEN 'expiring' ELSE 'ready' END
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type='general_liability' AND d.review_state='pending_review') THEN 'needs_review'
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type='general_liability' AND d.review_state IN ('accepted','superseded') AND d.coverage_end_date<v_start) THEN 'expired'
    WHEN EXISTS (SELECT 1 FROM public.contractor_compliance_documents d WHERE d.profile_id=v_profile AND d.document_type='general_liability' AND d.review_state IN ('accepted','superseded')) THEN 'gap'
    ELSE 'missing' END;
  v_overall := CASE WHEN NOT v_active THEN 'inactive'
    WHEN 'expired' IN (v_w9_status,v_wc_status,v_gl_status) THEN 'expired'
    WHEN 'gap' IN (v_w9_status,v_wc_status,v_gl_status) THEN 'gap'
    WHEN 'missing' IN (v_w9_status,v_wc_status,v_gl_status) THEN 'missing'
    WHEN 'needs_review' IN (v_w9_status,v_wc_status,v_gl_status) THEN 'needs_review'
    WHEN 'expiring' IN (v_w9_status,v_wc_status,v_gl_status) THEN 'expiring'
    ELSE 'ready' END;

  SELECT jsonb_build_object(
    'profile_id',p.id,
    'contractor',jsonb_build_object(
      'id',c.id,'name',c.name,'company',c.company,'email',c.email,'phone',c.phone,
      'trade_specialty',c.trade_specialty,'is_active',p.is_active,
      'assigned_owner_name',owner.full_name,
      'last_request_at',(
        SELECT max(r.sent_at)
        FROM public.contractor_compliance_requests r
        WHERE r.profile_id=p.id
          AND (
            v_role<>'project_manager'
            OR r.requested_document_types && ARRAY['workers_comp','workers_comp_waiver','general_liability']::text[]
          )
      ),
      'reminders_paused_at',p.requests_paused_at,
      'reminders_pause_reason',p.requests_pause_reason,
      'overall_status',v_overall
    ),
    'contact',jsonb_build_object('id',c.id,'name',c.name,'company',c.company,'email',c.email,'phone',c.phone,'trade_specialty',c.trade_specialty),
    'readiness',jsonb_build_object('current_status',v_overall,'view_mode',CASE WHEN p_audit_start IS NULL THEN 'current' ELSE 'audit' END,'audit_start',p_audit_start,'audit_end',p_audit_end),
    'requirements',jsonb_build_array(
      jsonb_build_object(
        'key','w9','label','W-9','status',v_w9_status,
        'detail',CASE WHEN v_role='project_manager' THEN NULL ELSE 'Required tax year '||v_w9_year::text END
      ),
      jsonb_build_object('key','workers_comp','label','Workers compensation or Utah waiver','status',v_wc_status,'expires_on',v_wc_end),
      jsonb_build_object('key','general_liability','label','General liability','status',v_gl_status,'expires_on',v_gl_end)
    ),
    'documents',CASE WHEN v_role='project_manager' THEN '[]'::jsonb ELSE COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id',d.id,'document_type',d.document_type,'version_number',d.version_number,
        'state',d.review_state,'review_state',d.review_state,
        'coverage_start_date',d.coverage_start_date,'coverage_end_date',d.coverage_end_date,
        'tax_year',d.tax_year,'original_filename',d.original_filename,'mime_type',d.mime_type,
        'byte_size',d.byte_size,'received_at',d.received_at,'received_source',d.received_source,
        'verified_at',d.verified_at,'rejection_reason',d.rejection_reason
      ) ORDER BY d.document_type,d.version_number DESC)
      FROM public.contractor_compliance_documents d WHERE d.profile_id=p.id
    ),'[]'::jsonb) END,
    'coverage_timeline',COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id',d.id,'document_type',d.document_type,'state',d.review_state,
        'start_on',d.coverage_start_date,'end_on',d.coverage_end_date
      ) ORDER BY d.coverage_start_date,d.coverage_end_date)
      FROM public.contractor_compliance_documents d
      WHERE d.profile_id=p.id AND d.document_type<>'w9' AND d.review_state IN ('accepted','superseded')
    ),'[]'::jsonb),
    'requests',CASE WHEN v_role='project_manager' THEN '[]'::jsonb ELSE COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id',r.id,'requested_document_types',r.requested_document_types,'expires_at',r.expires_at,
        'sent_at',r.sent_at,'paused_at',r.paused_at,'revoked_at',r.revoked_at,
        'completed_at',r.completed_at,'created_at',r.created_at,
        'state',CASE WHEN r.completed_at IS NOT NULL THEN 'completed' WHEN r.revoked_at IS NOT NULL THEN 'revoked' WHEN r.paused_at IS NOT NULL THEN 'paused' WHEN r.expires_at<=now() THEN 'expired' ELSE 'open' END,
        'deliveries',COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'stage',x.stage_key,'status',x.status,'sent_at',x.sent_at,
          'completed_at',x.completed_at,'outcome_reason',x.outcome_reason
        ) ORDER BY x.created_at) FROM public.contractor_compliance_request_deliveries x WHERE x.request_id=r.id),'[]'::jsonb)
      ) ORDER BY r.created_at DESC)
      FROM public.contractor_compliance_requests r WHERE r.profile_id=p.id
    ),'[]'::jsonb) END,
    'activity',CASE WHEN v_role='project_manager' THEN '[]'::jsonb ELSE COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id',a.id,'event_type',a.event_type,'note',a.note,
        'safe_metadata',a.safe_metadata,'created_at',a.created_at
      ) ORDER BY a.created_at DESC)
      FROM public.contractor_compliance_activity a WHERE a.profile_id=p.id
    ),'[]'::jsonb) END,
    'permissions',jsonb_build_object('can_manage',v_role IN ('admin','office'),'can_view_files',v_role IN ('admin','office'),'readiness_only',v_role='project_manager'),
    'audit',jsonb_build_object('start_date',v_start,'end_date',v_end,'timezone','America/Denver','mode',CASE WHEN p_audit_start IS NULL THEN 'current' ELSE 'audit' END)
  ) INTO v_result
  FROM public.contractor_compliance_profiles p
  JOIN public.contacts c ON c.id=p.contact_id
  LEFT JOIN public.employees owner ON owner.id=p.assigned_owner_id
  WHERE p.id=v_profile;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_contractor_compliance_detail"("p_contact_id" "uuid", "p_audit_start" "date", "p_audit_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contractor_w9_tax_year_checklist"("p_tax_year" integer, "p_search" "text" DEFAULT NULL::"text", "p_w9_status" "text" DEFAULT NULL::"text", "p_provider_target" "text" DEFAULT NULL::"text", "p_handoff_status" "text" DEFAULT NULL::"text", "p_active_only" boolean DEFAULT true, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_result jsonb;
BEGIN
  SELECT e.role::text INTO v_role
  FROM public.employees e
  WHERE e.auth_user_id = auth.uid() AND e.is_active AND NOT e.is_external;
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND (v_role IS NULL OR v_role NOT IN ('admin', 'office')) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: W-9 checklist access required' USING errcode = '42501';
  END IF;
  IF p_tax_year NOT BETWEEN 2000 AND 2200
     OR p_limit NOT BETWEEN 1 AND 100
     OR p_offset < 0
     OR COALESCE(p_w9_status, 'all')
        NOT IN ('all', 'valid', 'missing', 'needs_review', 'rejected', 'stale_previous_year')
     OR COALESCE(p_provider_target, 'all')
        NOT IN ('all', 'unassigned', 'quickbooks', 'gusto', 'quickbooks_and_gusto', 'other')
     OR COALESCE(p_handoff_status, 'all')
        NOT IN ('all', 'not_ready', 'ready', 'handed_off', 'reconciled') THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: W-9 checklist filters' USING errcode = '22023';
  END IF;

  WITH document_facts AS (
    SELECT
      p.id AS profile_id,
      p.contact_id,
      p.is_active,
      p.required_w9_year,
      EXISTS (
        SELECT 1 FROM public.contractor_compliance_documents d
        WHERE d.profile_id = p.id
          AND d.document_type = 'w9'
          AND d.tax_year = p_tax_year
          AND d.review_state IN ('accepted', 'superseded')
      ) AS has_valid,
      EXISTS (
        SELECT 1 FROM public.contractor_compliance_documents d
        WHERE d.profile_id = p.id
          AND d.document_type = 'w9'
          AND d.tax_year = p_tax_year
          AND d.review_state = 'pending_review'
      ) AS has_pending,
      (
        SELECT d.review_state
        FROM public.contractor_compliance_documents d
        WHERE d.profile_id = p.id
          AND d.document_type = 'w9'
          AND d.tax_year = p_tax_year
        ORDER BY d.version_number DESC
        LIMIT 1
      ) AS latest_current_state,
      EXISTS (
        SELECT 1 FROM public.contractor_compliance_documents d
        WHERE d.profile_id = p.id
          AND d.document_type = 'w9'
          AND d.tax_year < p_tax_year
          AND d.review_state IN ('accepted', 'superseded')
      ) AS has_previous,
      (
        SELECT max(d.verified_at)
        FROM public.contractor_compliance_documents d
        WHERE d.profile_id = p.id
          AND d.document_type = 'w9'
          AND d.tax_year = p_tax_year
          AND d.review_state IN ('accepted', 'superseded')
      ) AS last_verified_at,
      (
        SELECT max(d.tax_year)
        FROM public.contractor_compliance_documents d
        WHERE d.profile_id = p.id
          AND d.document_type = 'w9'
          AND d.review_state IN ('accepted', 'superseded')
      ) AS latest_accepted_tax_year,
      (
        SELECT max(q.sent_at)
        FROM public.contractor_compliance_requests q
        WHERE q.profile_id = p.id AND 'w9' = ANY(q.requested_document_types)
      ) AS last_request_at
    FROM public.contractor_compliance_profiles p
  ),
  classified AS (
    SELECT
      f.*,
      CASE
        WHEN f.has_valid THEN 'valid'
        WHEN f.has_pending THEN 'needs_review'
        WHEN f.latest_current_state = 'rejected' THEN 'rejected'
        WHEN f.has_previous THEN 'stale_previous_year'
        ELSE 'missing'
      END AS w9_status
    FROM document_facts f
  ),
  rows AS (
    SELECT
      f.profile_id,
      c.id AS contractor_id,
      c.name,
      c.company,
      c.email,
      c.trade_specialty,
      f.is_active,
      f.required_w9_year,
      f.w9_status,
      f.last_verified_at,
      f.latest_accepted_tax_year,
      f.last_request_at,
      COALESCE(h.provider_target, 'unassigned') AS provider_target,
      h.quickbooks_contractor_external_id,
      h.gusto_contractor_external_id,
      COALESCE(h.handoff_status, 'not_ready') AS handoff_status,
      h.handoff_date,
      h.provider_reference,
      h.updated_at AS handoff_updated_at
    FROM classified f
    JOIN public.contacts c ON c.id = f.contact_id AND c.role = 'subcontractor'
    LEFT JOIN public.contractor_w9_provider_handoffs h
      ON h.profile_id = f.profile_id AND h.tax_year = p_tax_year
    WHERE (NOT p_active_only OR f.is_active)
  ),
  filtered AS (
    SELECT * FROM rows
    WHERE (
      NULLIF(btrim(p_search), '') IS NULL
      OR name ILIKE '%' || btrim(p_search) || '%'
      OR company ILIKE '%' || btrim(p_search) || '%'
      OR email ILIKE '%' || btrim(p_search) || '%'
    )
      AND (COALESCE(p_w9_status, 'all') = 'all' OR w9_status = p_w9_status)
      AND (
        COALESCE(p_provider_target, 'all') = 'all'
        OR provider_target = p_provider_target
      )
      AND (
        COALESCE(p_handoff_status, 'all') = 'all'
        OR handoff_status = p_handoff_status
      )
  )
  SELECT jsonb_build_object(
    'tax_year', p_tax_year,
    'total', (SELECT count(*) FROM filtered),
    'counts', jsonb_build_object(
      'valid', (SELECT count(*) FROM filtered WHERE w9_status = 'valid'),
      'missing', (SELECT count(*) FROM filtered WHERE w9_status = 'missing'),
      'needs_review', (SELECT count(*) FROM filtered WHERE w9_status = 'needs_review'),
      'rejected', (SELECT count(*) FROM filtered WHERE w9_status = 'rejected'),
      'stale_previous_year', (
        SELECT count(*) FROM filtered WHERE w9_status = 'stale_previous_year'
      )
    ),
    'items', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'contractor_id', r.contractor_id,
        'name', r.name,
        'company', r.company,
        'email', r.email,
        'trade_specialty', r.trade_specialty,
        'is_active', r.is_active,
        'required_w9_year', r.required_w9_year,
        'w9_status', r.w9_status,
        'last_verified_at', r.last_verified_at,
        'latest_accepted_tax_year', r.latest_accepted_tax_year,
        'last_request_at', r.last_request_at,
        'provider_target', r.provider_target,
        'quickbooks_contractor_external_id', r.quickbooks_contractor_external_id,
        'gusto_contractor_external_id', r.gusto_contractor_external_id,
        'handoff_status', r.handoff_status,
        'handoff_date', r.handoff_date,
        'provider_reference', r.provider_reference,
        'handoff_updated_at', r.handoff_updated_at
      ) ORDER BY
        CASE r.w9_status
          WHEN 'missing' THEN 1
          WHEN 'rejected' THEN 2
          WHEN 'stale_previous_year' THEN 3
          WHEN 'needs_review' THEN 4
          ELSE 5
        END,
        r.name)
      FROM (
        SELECT * FROM filtered
        ORDER BY
          CASE w9_status
            WHEN 'missing' THEN 1
            WHEN 'rejected' THEN 2
            WHEN 'stale_previous_year' THEN 3
            WHEN 'needs_review' THEN 4
            ELSE 5
          END,
          name
        LIMIT p_limit OFFSET p_offset
      ) r
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_contractor_w9_tax_year_checklist"("p_tax_year" integer, "p_search" "text", "p_w9_status" "text", "p_provider_target" "text", "p_handoff_status" "text", "p_active_only" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_conversation_members"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_members jsonb;
BEGIN
  IF NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'get_conversation_members is admin-only'
      USING ERRCODE = '42501';
  END IF;

  IF p_conversation_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.conversations conversation
       WHERE conversation.id = p_conversation_id
     ) THEN
    RAISE EXCEPTION 'conversation not found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'employee_id', employee.id,
      'name', COALESCE(NULLIF(employee.display_name, ''), employee.full_name, employee.email),
      'email', employee.email,
      'role', employee.role::text,
      'included', public.messaging_employee_can_access_conversation(
        employee.id,
        p_conversation_id
      ),
      'source', CASE
        WHEN employee.role::text IN ('admin', 'office', 'project_manager', 'supervisor')
          THEN 'privileged'
        WHEN override_row.employee_id IS NOT NULL AND override_row.included
          THEN 'manual_add'
        WHEN override_row.employee_id IS NOT NULL AND NOT override_row.included
          THEN 'manual_remove'
        WHEN default_member.employee_id IS NOT NULL
          THEN 'default'
        ELSE 'none'
      END,
      'is_default', default_member.employee_id IS NOT NULL,
      'has_override', override_row.employee_id IS NOT NULL,
      'can_edit', employee.role::text NOT IN (
        'admin', 'office', 'project_manager', 'supervisor', 'crm_partner'
      ),
      'can_default', employee.role::text = 'field_tech'
    )
    ORDER BY
      CASE employee.role::text
        WHEN 'field_tech' THEN 0
        WHEN 'estimator' THEN 1
        ELSE 2
      END,
      COALESCE(NULLIF(employee.display_name, ''), employee.full_name, employee.email)
  ), '[]'::jsonb)
    INTO v_members
  FROM public.employees employee
  LEFT JOIN public.conversation_member_overrides override_row
    ON override_row.conversation_id = p_conversation_id
   AND override_row.employee_id = employee.id
  LEFT JOIN public.conversation_default_members default_member
    ON default_member.employee_id = employee.id
  WHERE employee.is_active
    AND NOT employee.is_external
    AND employee.role::text <> 'crm_partner';

  RETURN v_members;
END;
$$;


ALTER FUNCTION "public"."get_conversation_members"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_conversation_notification_recipients"("p_conversation_id" "uuid") RETURNS TABLE("employee_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT employee.id
  FROM public.employees employee
  WHERE current_user = 'service_role'
    AND public.messaging_employee_has_conversations_capability(employee.id)
    AND public.messaging_employee_can_access_conversation(
      employee.id,
      p_conversation_id
    );
$$;


ALTER FUNCTION "public"."get_conversation_notification_recipients"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_conversion_trend"("p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_start date;
  v_end   date;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_end   := COALESCE(p_end, public.mt_today());
  v_start := COALESCE(p_start, (date_trunc('month', v_end::timestamp) - interval '11 months')::date);

  RETURN QUERY
  -- All buckets are Denver calendar months: mt_date() collapses each event to
  -- its Denver day first, then date_trunc months over NAIVE timestamps (no
  -- server-TZ dependence anywhere).
  WITH months AS (
    SELECT generate_series(date_trunc('month', v_start::timestamp),
                           date_trunc('month', v_end::timestamp),
                           interval '1 month') AS m
  ),
  lead_c AS (
    SELECT date_trunc('month', public.mt_date(COALESCE(il.occurred_at, il.created_at))::timestamp) AS m, COUNT(*) AS c
    FROM inbound_leads il
    WHERE il.org_id = v_org AND COALESCE(il.spam_flag, false) = false
      AND (il.source_type <> 'call' OR public.crm_call_is_answered(il.raw_payload, il.duration_sec))
      AND public.mt_date(COALESCE(il.occurred_at, il.created_at)) >= v_start
      AND public.mt_date(COALESCE(il.occurred_at, il.created_at)) <= v_end
    GROUP BY 1
  ),
  est_c AS (
    SELECT date_trunc('month', public.mt_date(e.created_at)::timestamp) AS m, COUNT(*) AS c
    FROM estimates e
    WHERE e.status IS DISTINCT FROM 'draft'
      AND crm_contact_is_traced(e.contact_id)
      AND public.mt_date(e.created_at) >= v_start
      AND public.mt_date(e.created_at) <= v_end
    GROUP BY 1
  ),
  -- CANONICAL SALE RULE (see job_agg note in get_attribution_rollup).
  job_c AS (
    SELECT date_trunc('month', public.mt_date(COALESCE(cl.created_at, j.created_at))::timestamp) AS m,
           COUNT(*) AS c,
           COALESCE(SUM(j.invoiced_value), 0) AS rev
    FROM jobs j
    LEFT JOIN claims cl ON cl.id = j.claim_id
    WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
      AND crm_contact_is_traced(j.primary_contact_id)
      AND public.mt_date(COALESCE(cl.created_at, j.created_at)) >= v_start
      AND public.mt_date(COALESCE(cl.created_at, j.created_at)) <= v_end
    GROUP BY 1
  )
  SELECT json_build_object(
    'period',       to_char(months.m, 'YYYY-MM'),
    'period_start', months.m::date,
    'leads',        COALESCE(lead_c.c, 0),
    'estimates',    COALESCE(est_c.c, 0),
    'won_jobs',     COALESCE(job_c.c, 0),
    'revenue',      COALESCE(job_c.rev, 0)
  )
  FROM months
  LEFT JOIN lead_c ON lead_c.m = months.m
  LEFT JOIN est_c  ON est_c.m  = months.m
  LEFT JOIN job_c  ON job_c.m  = months.m
  ORDER BY months.m;
END;
$$;


ALTER FUNCTION "public"."get_conversion_trend"("p_start" "date", "p_end" "date", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crm_automations"("p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'id', a.id, 'name', a.name, 'description', a.description,
    'trigger_event_type', a.trigger_event_type,
    'conditions', a.conditions, 'actions', a.actions,
    'enabled', a.enabled, 'created_at', a.created_at, 'updated_at', a.updated_at,
    'stats', (
      SELECT json_build_object(
        'active',    count(*) FILTER (WHERE r.status = 'active'),
        'held',      count(*) FILTER (WHERE r.status = 'held'),
        'completed', count(*) FILTER (WHERE r.status = 'completed'),
        'skipped',   count(*) FILTER (WHERE r.status = 'skipped'),
        'failed',    count(*) FILTER (WHERE r.status = 'failed'),
        'total',     count(*)
      ) FROM crm_automation_runs r WHERE r.automation_id = a.id
    )
  )
  FROM crm_automations a
  WHERE a.org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
  ORDER BY a.created_at DESC;
$$;


ALTER FUNCTION "public"."get_crm_automations"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crm_build_progress"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phases jsonb;
  v_overall_done  int;
  v_overall_total int;
BEGIN
  SELECT COALESCE(jsonb_agg(x.phase_obj ORDER BY x.sort_order), '[]'::jsonb)
    INTO v_phases
  FROM (
    SELECT
      p.sort_order,
      jsonb_build_object(
        'phase_key',   p.phase_key,
        'title',       p.title,
        'status',      p.status,
        'shipped_at',  p.shipped_at,
        'sort_order',  p.sort_order,
        'stages',      COALESCE(s.stages, '[]'::jsonb),
        'done_count',  COALESCE(s.done_count, 0),
        'total_count', COALESCE(s.total_count, 0)
      ) AS phase_obj
    FROM crm_build_phases p
    LEFT JOIN (
      SELECT
        cs.phase_key,
        jsonb_agg(
          jsonb_build_object('id', cs.id, 'title', cs.title, 'status', cs.status, 'sort_order', cs.sort_order)
          ORDER BY cs.sort_order
        ) AS stages,
        COUNT(*) FILTER (WHERE cs.status = 'done') AS done_count,
        COUNT(*) AS total_count
      FROM crm_build_stages cs
      GROUP BY cs.phase_key
    ) s ON s.phase_key = p.phase_key
  ) x;

  SELECT COALESCE(SUM((phase->>'done_count')::int), 0), COALESCE(SUM((phase->>'total_count')::int), 0)
    INTO v_overall_done, v_overall_total
  FROM jsonb_array_elements(v_phases) AS phase;

  RETURN jsonb_build_object(
    'phases',        v_phases,
    'overall_done',  v_overall_done,
    'overall_total', v_overall_total
  );
END;
$$;


ALTER FUNCTION "public"."get_crm_build_progress"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crm_contacts"("p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH s AS (SELECT nullif(btrim(p_search), '') AS term),
  d AS (SELECT regexp_replace(COALESCE((SELECT term FROM s), ''), '[^0-9]', '', 'g') AS digits),
  matched AS (
    SELECT c.*
    FROM contacts c
    WHERE (SELECT term FROM s) IS NULL
       OR c.name    ILIKE '%' || (SELECT term FROM s) || '%'
       OR c.email   ILIKE '%' || (SELECT term FROM s) || '%'
       OR c.company ILIKE '%' || (SELECT term FROM s) || '%'
       OR ((SELECT digits FROM d) <> ''
           AND regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g') LIKE '%' || (SELECT digits FROM d) || '%')
  )
  SELECT json_build_object(
    'id', id, 'name', name, 'phone', phone, 'email', email,
    'company', company, 'role', role, 'lifecycle_status', lifecycle_status,
    'owner_id', owner_id, 'tags', COALESCE(tags, '[]'::jsonb), 'created_at', created_at,
    'total_count', total_count
  )
  FROM (
    SELECT m.*, count(*) OVER () AS total_count FROM matched m
  ) x
  ORDER BY (x.name IS NULL), lower(x.name), x.created_at DESC
  LIMIT  GREATEST(COALESCE(p_limit, 50), 0)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;


ALTER FUNCTION "public"."get_crm_contacts"("p_search" "text", "p_limit" integer, "p_offset" integer, "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crm_revenue_by_division"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("division" "text", "won_jobs" bigint, "revenue" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT j.division::text,
         COUNT(*)::bigint,
         COALESCE(SUM(j.invoiced_value), 0)::numeric
  FROM jobs j
  LEFT JOIN claims cl ON cl.id = j.claim_id
  WHERE j.is_real_job = true AND j.status IS DISTINCT FROM 'deleted'
    AND crm_contact_is_traced(j.primary_contact_id)
    AND (p_start_date IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start_date)
    AND (p_end_date   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end_date)
  GROUP BY j.division
  ORDER BY 3 DESC;
$$;


ALTER FUNCTION "public"."get_crm_revenue_by_division"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crm_sales_summary"("p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'total_won',      COUNT(*),
    'total_revenue',  COALESCE(SUM(j.invoiced_value), 0),
    'traced_won',     COUNT(*) FILTER (WHERE crm_contact_is_traced(j.primary_contact_id)),
    'traced_revenue', COALESCE(SUM(j.invoiced_value) FILTER (WHERE crm_contact_is_traced(j.primary_contact_id)), 0)
  )
  FROM jobs j
  LEFT JOIN claims cl ON cl.id = j.claim_id
  WHERE j.is_real_job = true
    AND j.status IS DISTINCT FROM 'deleted'
    AND (p_start_date IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) >= p_start_date)
    AND (p_end_date   IS NULL OR public.mt_date(COALESCE(cl.created_at, j.created_at)) <= p_end_date);
$$;


ALTER FUNCTION "public"."get_crm_sales_summary"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_crm_tasks"("p_assignee" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT json_build_object(
    'id', t.id, 'title', t.title, 'notes', t.notes, 'due_at', t.due_at,
    'remind_at', t.remind_at, 'status', t.status,
    'assignee_id', t.assignee_id, 'assignee_name', e.full_name,
    'contact_id', t.contact_id, 'contact_name', c.name, 'lead_id', t.lead_id,
    'created_at', t.created_at, 'updated_at', t.updated_at, 'completed_at', t.completed_at
  )
  FROM crm_tasks t
  LEFT JOIN employees e ON e.id = t.assignee_id
  LEFT JOIN contacts  c ON c.id = t.contact_id
  WHERE (p_org_id     IS NULL OR t.org_id      = p_org_id)
    AND (p_assignee   IS NULL OR t.assignee_id = p_assignee)
    AND (p_status     IS NULL OR t.status      = p_status)
    AND (p_contact_id IS NULL OR t.contact_id  = p_contact_id)
    AND (p_lead_id    IS NULL OR t.lead_id     = p_lead_id)
  ORDER BY (t.status <> 'open') ASC, t.due_at ASC NULLS LAST, t.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_crm_tasks"("p_assignee" "uuid", "p_status" "text", "p_contact_id" "uuid", "p_lead_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_detail"("p_contact_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_contact jsonb; v_claims jsonb; v_financials jsonb; v_files jsonb; v_activity jsonb; v_addresses jsonb;
  v_job_ids uuid[];
BEGIN
  SELECT to_jsonb(c) INTO v_contact FROM contacts c WHERE c.id = p_contact_id;
  IF v_contact IS NULL THEN RETURN NULL; END IF;

  SELECT array_agg(cj.job_id) INTO v_job_ids FROM contact_jobs cj WHERE cj.contact_id = p_contact_id;

  -- Addresses
  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.is_billing DESC, a.created_at ASC), '[]'::jsonb)
  INTO v_addresses FROM contact_addresses a WHERE a.contact_id = p_contact_id;

  -- Claims with nested jobs
  SELECT COALESCE(jsonb_agg(to_jsonb(cl_row) ORDER BY cl_row.date_of_loss DESC NULLS LAST), '[]'::jsonb)
  INTO v_claims
  FROM (
    SELECT cl.id, cl.claim_number, cl.insurance_claim_number, cl.insurance_carrier,
      cl.policy_number, cl.date_of_loss, cl.loss_address, cl.loss_city, cl.loss_state, cl.loss_zip,
      cl.loss_type, cl.status, cl.deductible, cl.notes,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id',j.id,'job_number',j.job_number,'division',j.division,'phase',j.phase,'status',j.status,'priority',j.priority,
          'address',j.address,'city',j.city,'insurance_company',j.insurance_company,'date_of_loss',j.date_of_loss,'created_at',j.created_at,
          'estimated_value',j.estimated_value,'approved_value',j.approved_value,'invoiced_value',j.invoiced_value,'collected_value',j.collected_value,
          'deductible',j.deductible,'supplement_value',j.supplement_value,
          'total_labor_cost',j.total_labor_cost,'total_material_cost',j.total_material_cost,
          'total_equipment_cost',j.total_equipment_cost,'total_sub_cost',j.total_sub_cost,'total_other_cost',j.total_other_cost
        ) ORDER BY j.created_at ASC)
        FROM jobs j WHERE j.claim_id = cl.id
      ), '[]'::jsonb) AS jobs
    FROM claims cl WHERE cl.contact_id = p_contact_id
  ) cl_row;

  -- Financials
  SELECT jsonb_build_object(
    'total_estimated',COALESCE(sum(j.estimated_value),0),'total_approved',COALESCE(sum(j.approved_value),0),
    'total_invoiced',COALESCE(sum(j.invoiced_value),0),'total_collected',COALESCE(sum(j.collected_value),0),
    'total_deductible',COALESCE(sum(j.deductible),0),'total_supplement',COALESCE(sum(j.supplement_value),0),
    'total_depreciation_held',COALESCE(sum(j.depreciation_held),0),'total_depreciation_released',COALESCE(sum(j.depreciation_released),0),
    'total_labor_cost',COALESCE(sum(j.total_labor_cost),0),'total_material_cost',COALESCE(sum(j.total_material_cost),0),
    'total_equipment_cost',COALESCE(sum(j.total_equipment_cost),0),'total_sub_cost',COALESCE(sum(j.total_sub_cost),0),
    'total_other_cost',COALESCE(sum(j.total_other_cost),0),'job_count',count(*)::int
  ) INTO v_financials FROM jobs j WHERE j.id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[]));

  -- Files
  SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.created_at DESC), '[]'::jsonb)
  INTO v_files FROM (
    SELECT doc.id,doc.job_id,doc.name,doc.file_path,doc.file_size,doc.mime_type,doc.category,doc.created_at,j.job_number
    FROM job_documents doc JOIN jobs j ON j.id=doc.job_id
    WHERE doc.job_id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[])) LIMIT 200
  ) d;

  -- Activity
  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.date DESC), '[]'::jsonb)
  INTO v_activity FROM (
    SELECT n.id,'note' as type,n.created_at as date,COALESCE(n.body,'') as content,
      COALESCE(n.author_name,e.full_name,'Unknown') as author,j.job_number
    FROM job_notes n LEFT JOIN employees e ON e.id=n.author_id LEFT JOIN jobs j ON j.id=n.job_id
    WHERE n.job_id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[]))
    UNION ALL
    SELECT h.id,'phase_change' as type,h.changed_at as date,
      ('Phase: '||COALESCE(pf.label,h.from_phase)||' → '||COALESCE(pt.label,h.to_phase)) as content,
      COALESCE(e.full_name,'System') as author,j.job_number
    FROM job_phase_history h LEFT JOIN employees e ON e.id=h.changed_by LEFT JOIN jobs j ON j.id=h.job_id
      LEFT JOIN job_phases pf ON pf.key=h.from_phase LEFT JOIN job_phases pt ON pt.key=h.to_phase
    WHERE h.job_id = ANY(COALESCE(v_job_ids, ARRAY[]::uuid[]))
    ORDER BY date DESC LIMIT 100
  ) a;

  RETURN jsonb_build_object(
    'contact', v_contact, 'addresses', v_addresses, 'claims', v_claims,
    'financials', COALESCE(v_financials,'{}'::jsonb), 'files', v_files, 'activity', v_activity
  );
END; $$;


ALTER FUNCTION "public"."get_customer_detail"("p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customers_list"("p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  q text;
BEGIN
  q := '%' || lower(COALESCE(trim(p_search), '')) || '%';

  SELECT jsonb_agg(to_jsonb(r))
  INTO result
  FROM (
    SELECT
      c.id, c.name, c.phone, c.email, c.company, c.role,
      c.billing_address, c.billing_city, c.billing_state, c.billing_zip,
      c.insurance_carrier, c.policy_number,
      c.preferred_contact_method, c.preferred_language,
      c.tags, c.notes, c.dnd, c.created_at, c.updated_at,
      -- Claims with nested jobs
      COALESCE(
        (SELECT jsonb_agg(
          jsonb_build_object(
            'id', cl.id,
            'claim_number', cl.claim_number,
            'insurance_claim_number', cl.insurance_claim_number,
            'date_of_loss', cl.date_of_loss,
            'loss_address', cl.loss_address,
            'loss_city', cl.loss_city,
            'loss_type', cl.loss_type,
            'insurance_carrier', cl.insurance_carrier,
            'status', cl.status,
            'jobs', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'id', j.id, 'job_number', j.job_number, 'division', j.division,
                'phase', j.phase, 'address', j.address, 'city', j.city,
                'insurance_company', j.insurance_company,
                'date_of_loss', j.date_of_loss, 'created_at', j.created_at
              ) ORDER BY j.created_at ASC)
              FROM jobs j WHERE j.claim_id = cl.id
            ), '[]'::jsonb)
          ) ORDER BY cl.date_of_loss DESC NULLS LAST
        )
        FROM claims cl WHERE cl.contact_id = c.id),
        '[]'::jsonb
      ) AS claims,
      -- Flat jobs list (backward compat)
      COALESCE(
        (SELECT jsonb_agg(jsonb_build_object(
          'id', j.id, 'job_number', j.job_number, 'division', j.division,
          'phase', j.phase, 'address', j.address, 'city', j.city,
          'insurance_company', j.insurance_company, 'date_of_loss', j.date_of_loss,
          'created_at', j.created_at
        ) ORDER BY j.created_at DESC)
        FROM contact_jobs cj JOIN jobs j ON j.id = cj.job_id
        WHERE cj.contact_id = c.id),
        '[]'::jsonb
      ) AS jobs,
      (SELECT count(*) FROM contact_jobs cj WHERE cj.contact_id = c.id)::int AS job_count
    FROM contacts c
    WHERE c.role IN ('homeowner', 'tenant', 'property_manager')
      AND (p_search IS NULL OR p_search = ''
        OR lower(c.name) LIKE q
        OR c.phone LIKE q
        OR lower(COALESCE(c.email, '')) LIKE q
        OR lower(COALESCE(c.billing_address, '')) LIKE q
        OR lower(COALESCE(c.billing_city, '')) LIKE q)
    ORDER BY c.created_at DESC
    LIMIT p_limit OFFSET p_offset
  ) r;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_customers_list"("p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_action_items"("p_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH sigs AS (
    SELECT j.id AS job_id,
           j.job_number AS job,
           j.insured_name AS client,
           NULLIF(CONCAT_WS(', ',
             NULLIF(j.address, ''),
             NULLIF(j.city, ''),
             NULLIF(j.state, '') || CASE WHEN j.zip IS NOT NULL AND j.zip <> '' THEN ' ' || j.zip ELSE '' END
           ), '') AS address,
           CASE sr.doc_type
             WHEN 'coc' THEN 'Certificate of Completion unsigned'
             WHEN 'work_auth' THEN 'Work authorization unsigned'
             WHEN 'direction_pay' THEN 'Direction-to-pay unsigned'
             WHEN 'recon_agreement' THEN 'Reconstruction agreement unsigned'
             ELSE 'Document unsigned'
           END AS text,
           'Awaiting signature · sent ' || to_char(COALESCE(sr.sent_at, sr.created_at), 'Mon DD') AS sub,
           COALESCE(sr.sent_at, sr.created_at) AS ts
    FROM sign_requests sr LEFT JOIN jobs j ON j.id = sr.job_id
    WHERE sr.status = 'pending'
  )
  SELECT COALESCE(jsonb_agg(x ORDER BY ts ASC NULLS LAST), '[]'::jsonb)
  FROM (
    SELECT jsonb_build_object(
             'job_id', job_id, 'job', job, 'client', client, 'address', address,
             'kind', 'esign', 'text', text, 'sub', sub
           ) AS x, ts
    FROM sigs ORDER BY ts ASC NULLS LAST LIMIT p_limit
  ) q;
$$;


ALTER FUNCTION "public"."get_dashboard_action_items"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_layout"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT dl.layout
  FROM public.dashboard_layouts dl
  JOIN public.employees e ON e.id = dl.employee_id
  WHERE e.auth_user_id = auth.uid()
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_dashboard_layout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_stats"() RETURNS json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT json_build_object(
    'active_jobs', (
      SELECT COUNT(*)::int
      FROM jobs
      WHERE phase NOT IN ('completed', 'closed', 'cancelled')
    ),
    'needs_response', (
      SELECT COUNT(*)::int
      FROM conversations
      WHERE status = 'needs_response'
    ),
    'total_contacts', (
      SELECT COUNT(*)::int
      FROM contacts
    ),
    'open_leads', (
      SELECT COUNT(*)::int
      FROM contacts
      WHERE role = 'lead'
    )
  );
$$;


