CREATE OR REPLACE FUNCTION "public"."get_demo_sheet_pdf_gaps"() RETURNS TABLE("form_id" "uuid", "job_id" "uuid", "job_number" "text", "insured_name" "text", "technician_name" "text", "submitted_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    f.id AS form_id,
    f.job_id,
    j.job_number,
    j.insured_name,
    f.technician_name,
    f.created_at AS submitted_at
  FROM forms f
  JOIN jobs j ON j.id = f.job_id
  WHERE f.form_type = 'demo_sheet'
    AND f.status = 'submitted'
    AND NOT EXISTS (
      SELECT 1 FROM job_documents jd
      WHERE jd.job_id = f.job_id
        AND jd.category = 'demo_sheet'
        AND jd.created_at >= f.created_at
        AND jd.created_at <= f.created_at + interval '48 hours'
    )
  ORDER BY f.created_at DESC;
$$;


