CREATE OR REPLACE FUNCTION "public"."get_dispatch_board"("p_start_date" "date", "p_end_date" "date", "p_auto_show" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'auth', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  v_caller_emp_id UUID;
  v_caller_role TEXT;
  v_active_phases TEXT[] := ARRAY[
    'emergency_response', 'mitigation_in_progress', 'drying', 'monitoring',
    'mold_remediation', 'content_packout', 'content_cleaning', 'content_storage',
    'demo_in_progress', 'reconstruction_in_progress', 'reconstruction_punch_list',
    'supplement_in_progress'
  ];
BEGIN
  SELECT id, role INTO v_caller_emp_id, v_caller_role
  FROM employees WHERE auth_user_id = auth.uid() LIMIT 1;

  SELECT COALESCE(jsonb_agg(job_row ORDER BY job_row->>'insured_name'), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'job_id', j.id,
      'insured_name', j.insured_name,
      'job_number', j.job_number,
      'division', j.division,
      'address', j.address,
      'phase', j.phase,
      'claim_id', j.claim_id,
      'date_of_loss', (SELECT c.date_of_loss FROM claims c WHERE c.id = j.claim_id),
      'pinned', EXISTS (SELECT 1 FROM dispatch_board_jobs d WHERE d.job_id = j.id),
      'task_summary', (SELECT get_job_task_summary(j.id)),
      'appointments', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', a.id,
            'title', a.title,
            'date', a.date,
            'time_start', a.time_start,
            'time_end', a.time_end,
            'type', a.type,
            'status', a.status,
            'notes', a.notes,
            'duration_days', a.duration_days,
            'color', a.color,
            'is_milestone', a.is_milestone,
            'is_private', a.is_private,
            'crew', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'id', ac.id,
                'employee_id', ac.employee_id,
                'role', ac.role,
                'display_name', e.display_name,
                'full_name', e.full_name,
                'color', e.color,
                'avatar_url', e.avatar_url
              ))
              FROM appointment_crew ac
              JOIN employees e ON e.id = ac.employee_id
              WHERE ac.appointment_id = a.id
            ), '[]'::jsonb),
            'tasks_total', (SELECT count(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
            'tasks_done', (SELECT count(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed),
            'task_names', COALESCE((
              SELECT jsonb_agg(jt.title ORDER BY jt.created_at)
              FROM job_tasks jt
              WHERE jt.appointment_id = a.id
            ), '[]'::jsonb)
          ) ORDER BY a.date, a.time_start NULLS LAST
        )
        FROM appointments a
        WHERE a.job_id = j.id
          AND a.date >= p_start_date
          AND a.date <= p_end_date
          AND (
            NOT a.is_private
            OR v_caller_role IN ('admin', 'project_manager')
            OR EXISTS (
              SELECT 1 FROM appointment_crew ac
              WHERE ac.appointment_id = a.id AND ac.employee_id = v_caller_emp_id
            )
          )
      ), '[]'::jsonb)
    ) as job_row
    FROM jobs j
    WHERE
      j.phase = ANY(v_active_phases)
      OR EXISTS (SELECT 1 FROM dispatch_board_jobs d WHERE d.job_id = j.id)
      OR (
        p_auto_show AND EXISTS (
          SELECT 1 FROM appointments a
          WHERE a.job_id = j.id
            AND a.date >= p_start_date
            AND a.date <= p_end_date
            AND (
              NOT a.is_private
              OR v_caller_role IN ('admin', 'project_manager')
              OR EXISTS (
                SELECT 1 FROM appointment_crew ac
                WHERE ac.appointment_id = a.id AND ac.employee_id = v_caller_emp_id
              )
            )
        )
      )
  ) sub;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_dispatch_board"("p_start_date" "date", "p_end_date" "date", "p_auto_show" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatch_events"("p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_caller_emp_id UUID;
  v_caller_role TEXT;
BEGIN
  SELECT id, role INTO v_caller_emp_id, v_caller_role
  FROM employees WHERE auth_user_id = auth.uid() LIMIT 1;

  RETURN COALESCE(
    (SELECT jsonb_agg(
       jsonb_build_object(
         'id',          a.id,
         'kind',        a.kind,
         'title',       a.title,
         'date',        a.date,
         'time_start',  a.time_start,
         'time_end',    a.time_end,
         'type',        a.type,
         'status',      a.status,
         'notes',       a.notes,
         'color',       a.color,
         'is_private',  a.is_private,
         'crew', COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
             'id',           ac.id,
             'employee_id',  ac.employee_id,
             'role',         ac.role,
             'display_name', e.display_name,
             'full_name',    e.full_name,
             'color',        e.color,
             'avatar_url',   e.avatar_url
           ))
           FROM appointment_crew ac
           JOIN employees e ON e.id = ac.employee_id
           WHERE ac.appointment_id = a.id
         ), '[]'::jsonb)
       ) ORDER BY a.date, a.time_start NULLS LAST
     )
     FROM appointments a
     WHERE a.kind = 'event'
       AND a.date >= p_start_date
       AND a.date <= p_end_date
       AND (
         NOT a.is_private
         OR v_caller_role IN ('admin', 'project_manager')
         OR EXISTS (
           SELECT 1 FROM appointment_crew ac
           WHERE ac.appointment_id = a.id AND ac.employee_id = v_caller_emp_id
         )
       )),
    '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."get_dispatch_events"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatch_panel_jobs"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE 
  result jsonb;
  v_active_phases TEXT[] := ARRAY[
    'emergency_response', 'mitigation_in_progress', 'drying', 'monitoring',
    'mold_remediation', 'content_packout', 'content_cleaning', 'content_storage',
    'demo_in_progress', 'reconstruction_in_progress', 'reconstruction_punch_list',
    'supplement_in_progress'
  ];
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', j.id,
      'insured_name', j.insured_name,
      'job_number', j.job_number,
      'division', j.division,
      'phase', j.phase,
      'address', j.address,
      'date_of_loss', (SELECT c.date_of_loss FROM claims c WHERE c.id = j.claim_id),
      'on_board', (
        -- Production jobs are always on the board
        j.phase = ANY(v_active_phases)
        OR EXISTS (SELECT 1 FROM dispatch_board_jobs d WHERE d.job_id = j.id)
      ),
      'in_production', (j.phase = ANY(v_active_phases)),
      'appointment_count', (SELECT count(*) FROM appointments a WHERE a.job_id = j.id AND a.status != 'cancelled')
    ) ORDER BY j.insured_name
  ), '[]'::jsonb) INTO result
  FROM jobs j
  WHERE j.phase NOT IN ('closed', 'cancelled', 'archived');
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_dispatch_panel_jobs"() OWNER TO "postgres";


