CREATE OR REPLACE FUNCTION "public"."get_integration_status"("p_provider" "text" DEFAULT 'quickbooks'::"text") RETURNS TABLE("provider" "text", "connected" boolean, "environment" "text", "company_name" "text", "realm_id" "text", "token_expires_at" timestamp with time zone, "connected_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    p_provider,
    EXISTS (
      SELECT 1 FROM integration_credentials c
      WHERE c.provider = p_provider AND (c.refresh_token IS NOT NULL OR c.access_token IS NOT NULL)
    ),
    c.environment, c.company_name, c.realm_id, c.token_expires_at, c.connected_at
  FROM (SELECT 1) one
  LEFT JOIN integration_credentials c ON c.provider = p_provider
  WHERE NOT is_crm_partner(auth.uid());
$$;


