CREATE OR REPLACE FUNCTION "public"."get_invoice_activity"("p_invoice_id" "uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text;
  v_total bigint;
  v_rows jsonb;
BEGIN
  SELECT e.role::text INTO v_role FROM public.employees e
  WHERE e.auth_user_id = auth.uid() AND e.is_active IS TRUE AND e.is_external IS FALSE;

  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role'
     AND (v_role IS NULL OR v_role NOT IN ('admin', 'office', 'project_manager')) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: invoice activity access required' USING errcode = '42501';
  END IF;

  IF p_invoice_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
     OR p_offset IS NULL OR p_offset < 0 THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: invalid invoice activity page' USING errcode = '22023';
  END IF;

  SELECT count(*) INTO v_total FROM public.invoice_activity a WHERE a.invoice_id = p_invoice_id;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.occurred_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT a.id, a.event_type, a.actor_kind, a.occurred_at,
           a.recipient_email, a.cc_email, a.safe_metadata,
           COALESCE(e.display_name, e.full_name) AS actor_name
    FROM public.invoice_activity a
    LEFT JOIN public.employees e ON e.id = a.actor_employee_id
    WHERE a.invoice_id = p_invoice_id
    ORDER BY a.occurred_at DESC
    LIMIT p_limit OFFSET p_offset
  ) t;

  RETURN jsonb_build_object('total', v_total, 'limit', p_limit, 'offset', p_offset, 'rows', v_rows);
END;
$$;


ALTER FUNCTION "public"."get_invoice_activity"("p_invoice_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_contacts"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(to_jsonb(r) ORDER BY r.is_primary DESC, r.role ASC)
  INTO result
  FROM (
    SELECT
      cj.id AS link_id, cj.role, cj.is_primary, cj.notes AS link_notes,
      c.id, c.name, c.phone, c.email, c.company,
      c.role AS contact_role,
      c.billing_address, c.billing_city, c.billing_state, c.billing_zip,
      c.insurance_carrier, c.desk_phone, c.desk_extension
    FROM contact_jobs cj
    JOIN contacts c ON c.id = cj.contact_id
    WHERE cj.job_id = p_job_id
  ) r;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_job_contacts"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_demo_sheets"("p_job_id" "uuid") RETURNS TABLE("id" "uuid", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "email_sent" boolean, "job_id" "uuid", "technician_name" "text", "form_date" "date", "insured_name" "text", "address" "text", "room_count" integer, "summary" "jsonb")
    LANGUAGE "sql" SECURITY DEFINER
