CREATE OR REPLACE FUNCTION "public"."get_job_equipment"("p_job_id" "uuid", "p_include_removed" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "job_id" "uuid", "room_id" "uuid", "room_name" "text", "equipment_type" "public"."equipment_type", "nickname" "text", "serial_number" "text", "status" "text", "placed_at" timestamp with time zone, "removed_at" timestamp with time zone, "placed_by" "uuid", "removed_by" "uuid", "notes" "text", "client_id" "uuid", "created_at" timestamp with time zone, "days_onsite" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    SELECT ep.id, ep.job_id, ep.room_id, r.name AS room_name,
           ep.equipment_type, ep.nickname, ep.serial_number, ep.status,
           ep.placed_at, ep.removed_at, ep.placed_by, ep.removed_by,
           ep.notes, ep.client_id, ep.created_at,
           EXTRACT(DAY FROM (COALESCE(ep.removed_at, now()) - ep.placed_at))::INT AS days_onsite
      FROM equipment_placements ep
      LEFT JOIN rooms r ON r.id = ep.room_id
     WHERE ep.job_id = p_job_id
       AND (p_include_removed OR ep.status = 'active')
     ORDER BY CASE WHEN ep.status = 'active' THEN 0 ELSE 1 END ASC, ep.placed_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_job_equipment"("p_job_id" "uuid", "p_include_removed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_financials"("p_job_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("job_id" "uuid", "invoice_count" integer, "invoiced" numeric, "collected" numeric, "balance_due" numeric, "deductible" numeric, "insurance_responsibility" numeric, "homeowner_responsibility" numeric, "depreciation_withheld" numeric, "depreciation_released" numeric, "invoiced_date" "date")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    i.job_id,
    count(*)::int                                          AS invoice_count,
    COALESCE(sum(COALESCE(i.adjusted_total, i.total)), 0)  AS invoiced,
    COALESCE(sum(COALESCE(i.amount_paid, 0)), 0)           AS collected,
    COALESCE(sum(
      COALESCE(i.balance_due,
               COALESCE(i.adjusted_total, i.total) - COALESCE(i.amount_paid, 0))
    ), 0)                                                  AS balance_due,
    COALESCE(sum(COALESCE(i.deductible_amount, 0)), 0)         AS deductible,
    COALESCE(sum(COALESCE(i.insurance_responsibility, 0)), 0)  AS insurance_responsibility,
    COALESCE(sum(COALESCE(i.homeowner_responsibility, 0)), 0)  AS homeowner_responsibility,
    COALESCE(sum(COALESCE(i.depreciation_withheld, 0)), 0)     AS depreciation_withheld,
    COALESCE(sum(COALESCE(i.depreciation_released, 0)), 0)     AS depreciation_released,
    min(i.qbo_synced_at)::date                                 AS invoiced_date
  FROM invoices i
  WHERE i.qbo_invoice_id IS NOT NULL
    AND i.job_id IS NOT NULL
    AND (p_job_ids IS NULL OR i.job_id = ANY (p_job_ids))
  GROUP BY i.job_id;
$$;


ALTER FUNCTION "public"."get_job_financials"("p_job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_hub"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'job', to_jsonb(j.*),
    'claim', CASE WHEN c.id IS NOT NULL
      THEN jsonb_build_object('id', c.id, 'claim_number', c.claim_number)
      ELSE NULL END,
    'contacts', public.get_job_contacts(j.id),
    'work_auth_signed', EXISTS (
      SELECT 1 FROM sign_requests sr
      WHERE sr.job_id = j.id
        AND sr.doc_type = 'work_auth'
        AND sr.status = 'signed'
    ),
    'appointments', COALESCE((
      SELECT jsonb_agg(row_data ORDER BY row_data->>'date' DESC, row_data->>'time_start' DESC NULLS LAST)
      FROM (
        SELECT jsonb_build_object(
          'id', a.id,
          'job_id', a.job_id,
          'job_number', j.job_number,
          'division', j.division,
          'title', a.title,
          'date', a.date,
          'time_start', a.time_start,
          'time_end', a.time_end,
          'type', a.type,
          'status', a.status,
          'notes', a.notes,
          'duration_days', a.duration_days,
          'is_milestone', a.is_milestone,
          'color', a.color,
          'crew', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'employee_id', ac.employee_id,
              'full_name', e.full_name,
              'role', ac.role
            ))
            FROM appointment_crew ac
            JOIN employees e ON e.id = ac.employee_id
            WHERE ac.appointment_id = a.id
          ), '[]'::jsonb),
          'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
          'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true)
        ) AS row_data
        FROM appointments a
        WHERE a.job_id = j.id
      ) sub
    ), '[]'::jsonb)
  )
  INTO result
  FROM jobs j
  LEFT JOIN claims c ON c.id = j.claim_id
  WHERE j.id = p_job_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_job_hub"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_labor_summary"("p_job_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date") RETURNS TABLE("job_id" "uuid", "job_number" "text", "insured_name" "text", "division" "text", "employee_id" "uuid", "employee_name" "text", "total_hours" numeric, "travel_hours" numeric, "total_cost" numeric, "approved_hours" numeric, "approved_cost" numeric, "entry_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    j.id AS job_id,
    j.job_number,
    j.insured_name,
    j.division,
    e.id AS employee_id,
    e.full_name AS employee_name,
    SUM(t.hours) AS total_hours,
    SUM(COALESCE(t.travel_minutes, 0)) / 60.0 AS travel_hours,
    SUM(t.total_cost) AS total_cost,
    SUM(CASE WHEN t.approved THEN t.hours ELSE 0 END) AS approved_hours,
    SUM(CASE WHEN t.approved THEN t.total_cost ELSE 0 END) AS approved_cost,
    COUNT(*) AS entry_count
  FROM job_time_entries t
  JOIN employees e ON e.id = t.employee_id
  JOIN jobs j ON j.id = t.job_id
  WHERE (p_job_id IS NULL OR t.job_id = p_job_id)
    AND (p_start_date IS NULL OR t.work_date >= p_start_date)
    AND (p_end_date IS NULL OR t.work_date <= p_end_date)
  GROUP BY j.id, j.job_number, j.insured_name, j.division, e.id, e.full_name
  ORDER BY j.job_number, e.full_name;
$$;


ALTER FUNCTION "public"."get_job_labor_summary"("p_job_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_readings"("p_job_id" "uuid") RETURNS TABLE("id" "uuid", "job_id" "uuid", "room_id" "uuid", "room_name" "text", "equipment_id" "uuid", "reading_date" "date", "material" "public"."material_type", "location_description" "text", "mc_pct" numeric, "rh_pct" numeric, "temp_f" numeric, "gpp" numeric, "dew_point_f" numeric, "dry_standard_pct" numeric, "drying_goal_pct" numeric, "is_affected" boolean, "taken_by" "uuid", "taken_at" timestamp with time zone, "edited_at" timestamp with time zone, "edited_by" "uuid", "notes" "text", "client_id" "uuid", "created_at" timestamp with time zone, "is_stalled" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH latest_per_pair AS (
    SELECT DISTINCT ON (mr.room_id, mr.material)
           mr.id AS latest_id, mr.room_id, mr.material,
           mr.mc_pct AS latest_mc, mr.drying_goal_pct AS latest_goal,
           mr.taken_at AS latest_taken_at
      FROM moisture_readings mr
     WHERE mr.job_id = p_job_id
     ORDER BY mr.room_id, mr.material, mr.taken_at DESC
  ),
  stall_check AS (
    SELECT lpp.latest_id,
           (lpp.latest_mc IS NOT NULL AND lpp.latest_goal IS NOT NULL
            AND lpp.latest_mc > lpp.latest_goal
            AND EXISTS (
              SELECT 1 FROM moisture_readings prior
               WHERE prior.job_id = p_job_id
                 AND prior.room_id IS NOT DISTINCT FROM lpp.room_id
                 AND prior.material = lpp.material
                 AND prior.id <> lpp.latest_id
                 AND prior.taken_at <= lpp.latest_taken_at - interval '36 hours'
                 AND prior.mc_pct IS NOT NULL
                 AND (prior.mc_pct - lpp.latest_mc) < 1.0
            )) AS is_stalled
      FROM latest_per_pair lpp
  )
  SELECT mr.id, mr.job_id, mr.room_id, r.name AS room_name,
         mr.equipment_id, mr.reading_date, mr.material, mr.location_description,
         mr.mc_pct, mr.rh_pct, mr.temp_f, mr.gpp, mr.dew_point_f,
         mr.dry_standard_pct, mr.drying_goal_pct,
         mr.is_affected, mr.taken_by, mr.taken_at, mr.edited_at, mr.edited_by,
         mr.notes, mr.client_id, mr.created_at,
         COALESCE(sc.is_stalled, false) AS is_stalled
    FROM moisture_readings mr
    LEFT JOIN rooms r ON r.id = mr.room_id
    LEFT JOIN stall_check sc ON sc.latest_id = mr.id
   WHERE mr.job_id = p_job_id
   ORDER BY mr.reading_date DESC, mr.taken_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_job_readings"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_rooms"("p_job_id" "uuid") RETURNS TABLE("id" "uuid", "claim_id" "uuid", "name" "text", "area_sqft" numeric, "ceiling_height_ft" numeric, "sort_order" integer, "client_id" "uuid", "created_by" "uuid", "created_at" timestamp with time zone, "deleted_at" timestamp with time zone, "photo_count" integer, "reading_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_claim_id UUID;
BEGIN
  SELECT j.claim_id INTO v_claim_id FROM jobs j WHERE j.id = p_job_id;
  IF v_claim_id IS NULL THEN RETURN; END IF;
  RETURN QUERY
    SELECT r.id, r.claim_id, r.name, r.area_sqft, r.ceiling_height_ft,
           r.sort_order, r.client_id, r.created_by, r.created_at, r.deleted_at,
           COALESCE((SELECT COUNT(*)::INT FROM job_documents d
                     WHERE d.room_id = r.id AND d.category='photo'), 0) AS photo_count,
           0::INT AS reading_count
    FROM rooms r
    WHERE r.claim_id = v_claim_id AND r.deleted_at IS NULL
    ORDER BY r.sort_order ASC, r.created_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_job_rooms"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_schedule"("p_job_schedule_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', js.id, 'job_id', js.job_id, 'template_id', js.template_id,
    'name', js.name, 'start_date', js.start_date, 'status', js.status,
    'notes', js.notes, 'created_at', js.created_at,
    'template', (SELECT jsonb_build_object('name', st.name, 'division', st.division) FROM schedule_templates st WHERE st.id = js.template_id),
    'appointments', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'title', a.title, 'date', a.date,
        'time_start', a.time_start, 'time_end', a.time_end,
        'type', a.type, 'status', a.status, 'duration_days', a.duration_days,
        'color', a.color, 'is_milestone', a.is_milestone,
        'template_phase_id', a.template_phase_id, 'notes', a.notes,
        'crew', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', ac.id, 'employee_id', ac.employee_id, 'role', ac.role,
            'employee', jsonb_build_object('display_name', e.display_name, 'full_name', e.full_name, 'role', e.role)
          )) FROM appointment_crew ac JOIN employees e ON e.id = ac.employee_id WHERE ac.appointment_id = a.id
        ), '[]'::jsonb),
        'tasks', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', at2.id, 'title', at2.title, 'description', at2.description,
            'is_required', at2.is_required, 'is_completed', at2.is_completed,
            'completed_by', at2.completed_by, 'completed_at', at2.completed_at,
            'display_order', at2.display_order
          ) ORDER BY at2.display_order) FROM appointment_tasks at2 WHERE at2.appointment_id = a.id
        ), '[]'::jsonb)
      ) ORDER BY a.date, a.time_start NULLS LAST)
      FROM appointments a WHERE a.job_schedule_id = js.id
    ), '[]'::jsonb),
    'dependencies', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', ad.id, 'source_appointment_id', ad.source_appointment_id,
        'target_appointment_id', ad.target_appointment_id,
        'dependency_type', ad.dependency_type, 'lag_days', ad.lag_days
      )) FROM appointment_dependencies ad WHERE ad.job_schedule_id = js.id
    ), '[]'::jsonb)
  ) INTO result
  FROM job_schedules js WHERE js.id = p_job_schedule_id;
  RETURN result;
END; $$;


ALTER FUNCTION "public"."get_job_schedule"("p_job_schedule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_schedules"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', js.id, 'template_id', js.template_id, 'name', js.name,
    'start_date', js.start_date, 'status', js.status, 'created_at', js.created_at,
    'template_name', st.name,
    'appointment_count', (SELECT count(*) FROM appointments a WHERE a.job_schedule_id = js.id),
    'completed_count', (SELECT count(*) FROM appointments a WHERE a.job_schedule_id = js.id AND a.status = 'completed'),
    'task_count', (SELECT count(*) FROM appointment_tasks at2 JOIN appointments a ON at2.appointment_id = a.id WHERE a.job_schedule_id = js.id),
    'tasks_completed', (SELECT count(*) FROM appointment_tasks at2 JOIN appointments a ON at2.appointment_id = a.id WHERE a.job_schedule_id = js.id AND at2.is_completed = true)
  ) ORDER BY js.created_at DESC), '[]'::jsonb) INTO result
  FROM job_schedules js LEFT JOIN schedule_templates st ON st.id = js.template_id
  WHERE js.job_id = p_job_id;
  RETURN result;
END; $$;


ALTER FUNCTION "public"."get_job_schedules"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_task_pool"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(phase_data ORDER BY (phase_data->>'sort_order')::INT), '[]'::JSONB)
  INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'phase_name', sub.phase_name,
      'phase_color', sub.phase_color,
      'target_start', sub.target_start,
      'target_end', sub.target_end,
      'duration_days', sub.duration_days,
      'sort_order', COALESCE(sub.sort_order, 999),
      'total', sub.total,
      'assigned', sub.assigned,
      'completed', sub.completed,
      'tasks', sub.tasks
    ) AS phase_data
    FROM (
      SELECT
        jt.phase_name,
        jt.phase_color,
        MAX(jsp.target_start) AS target_start,
        MAX(jsp.target_end) AS target_end,
        MAX(jsp.duration_days) AS duration_days,
        MIN(jsp.sort_order) AS sort_order,
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE jt.appointment_id IS NOT NULL) AS assigned,
        COUNT(*) FILTER (WHERE jt.is_completed) AS completed,
        jsonb_agg(
          jsonb_build_object(
            'id', jt.id,
            'title', jt.title,
            'is_completed', jt.is_completed,
            'is_required', jt.is_required,
            'appointment_id', jt.appointment_id,
            'target_date', jt.target_date,
            'completed_at', jt.completed_at
          ) ORDER BY jt.created_at
        ) AS tasks
      FROM job_tasks jt
      LEFT JOIN job_schedule_phases jsp ON jsp.id = jt.job_schedule_phase_id
      WHERE jt.job_id = p_job_id
      GROUP BY jt.phase_name, jt.phase_color
    ) sub
  ) wrapper;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_job_task_pool"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_task_summary"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total', count(*),
    'assigned', count(*) FILTER (WHERE appointment_id IS NOT NULL),
    'unassigned', count(*) FILTER (WHERE appointment_id IS NULL),
    'completed', count(*) FILTER (WHERE is_completed),
    'required_total', count(*) FILTER (WHERE is_required),
    'required_completed', count(*) FILTER (WHERE is_required AND is_completed),
    'by_phase', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'phase_name', sub.phase_name,
        'phase_color', sub.phase_color,
        'total', sub.total,
        'completed', sub.completed,
        'assigned', sub.assigned
      ) ORDER BY sub.phase_name), '[]'::jsonb)
      FROM (
        SELECT phase_name, phase_color,
          count(*) as total,
          count(*) FILTER (WHERE is_completed) as completed,
          count(*) FILTER (WHERE appointment_id IS NOT NULL) as assigned
        FROM job_tasks WHERE job_id = p_job_id
        GROUP BY phase_name, phase_color
      ) sub
    )
  ) INTO result
  FROM job_tasks WHERE job_id = p_job_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_job_task_summary"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_jobs_closed"("p_floor" "date" DEFAULT NULL::"date") RETURNS TABLE("job_id" "uuid", "sale_date" timestamp with time zone, "sale_source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT j.id,
         COALESCE(c.created_at, j.created_at) AS sale_date,
         j.real_job_source                    AS sale_source
  FROM public.jobs j
  LEFT JOIN public.claims c ON c.id = j.claim_id
  WHERE j.is_real_job = true
    AND j.status IS DISTINCT FROM 'deleted'
    AND (p_floor IS NULL OR public.mt_date(COALESCE(c.created_at, j.created_at)) >= p_floor)
  ORDER BY sale_date DESC;
$$;


ALTER FUNCTION "public"."get_jobs_closed"("p_floor" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_jobs_completed"("p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'count', (SELECT count(*) FROM jobs
              WHERE phase IN ('completed','closed') AND actual_completion BETWEEN p_start AND p_end),
    'last_month', (SELECT count(*) FROM jobs
              WHERE phase IN ('completed','closed')
                AND actual_completion >= date_trunc('month', CURRENT_DATE - interval '1 month')::date
                AND actual_completion <  date_trunc('month', CURRENT_DATE)::date)
  );
$$;


ALTER FUNCTION "public"."get_jobs_completed"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_jobs_list"("p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT to_json(t) FROM (
    SELECT
      j.id, j.job_number, j.insured_name, j.phase, j.division, j.source, j.status,
      j.address, j.city, j.state, j.zip, j.claim_number, j.insurance_company,
      j.date_of_loss, j.received_date, j.target_completion,
      j.project_manager, j.project_manager_id, j.lead_tech_id,
      j.estimated_value, j.approved_value, j.invoiced_value, j.collected_value,
      j.priority, j.tags, j.is_cat_loss, j.has_asbestos, j.has_lead,
      j.phase_entered_at, j.created_at, j.updated_at,
      count(*) OVER() AS total_count
    FROM public.jobs j
    WHERE j.status <> 'deleted'
      AND (
        p_search IS NULL OR btrim(p_search) = '' OR
        j.insured_name      ILIKE '%' || btrim(p_search) || '%' OR
        j.job_number        ILIKE '%' || btrim(p_search) || '%' OR
        j.address           ILIKE '%' || btrim(p_search) || '%' OR
        j.claim_number      ILIKE '%' || btrim(p_search) || '%' OR
        j.insurance_company ILIKE '%' || btrim(p_search) || '%'
      )
    ORDER BY j.created_at DESC
    LIMIT  GREATEST(LEAST(COALESCE(p_limit, 100), 500), 1)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0)
  ) t;
$$;


ALTER FUNCTION "public"."get_jobs_list"("p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_activity"("p_lead_id" "uuid") RETURNS TABLE("activity_type" "text", "occurred_at" timestamp with time zone, "title" "text", "body" "text", "meta" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.crm_lead_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    'lead'::text,
    COALESCE(il.occurred_at, il.created_at),
    (CASE WHEN il.source_type = 'call' THEN 'Call' ELSE 'Web form' END)::text,
    il.transcription,
    jsonb_build_object(
      'source_type', il.source_type, 'duration_sec', il.duration_sec,
      'lead_status', il.lead_status, 'source', il.source, 'campaign', il.campaign,
      'recording_url', il.recording_url, 'transcript_analysis', il.transcript_analysis
    )
  FROM inbound_leads il
  WHERE il.id = p_lead_id

  UNION ALL

  SELECT
    'note'::text,
    ln.created_at,
    'Note'::text,
    ln.body,
    jsonb_build_object('note_id', ln.id, 'author_name', COALESCE(en.display_name, en.full_name))
  FROM crm_lead_notes ln
  LEFT JOIN employees en ON en.id = ln.created_by
  WHERE ln.lead_id = p_lead_id
     OR ln.lead_id IN (SELECT id FROM inbound_leads WHERE merged_into_lead_id = p_lead_id)

  UNION ALL

  SELECT
    'task'::text,
    COALESCE(t.due_at, t.created_at),
    t.title::text,
    t.notes,
    jsonb_build_object(
      'status', t.status, 'due_at', t.due_at, 'task_id', t.id,
      'created_by_name', COALESCE(ec.display_name, ec.full_name),
      'assignee_name', COALESCE(ea.display_name, ea.full_name)
    )
  FROM crm_tasks t
  LEFT JOIN employees ec ON ec.id = t.created_by
  LEFT JOIN employees ea ON ea.id = t.assignee_id
  WHERE t.lead_id = p_lead_id

  UNION ALL

  SELECT
    'stage_change'::text,
    lsh.moved_at,
    ('Moved to ' || ps.name)::text,
    NULL::text,
    jsonb_build_object(
      'from_stage_id', lsh.from_stage_id, 'stage_id', lsh.stage_id, 'lost_reason', lsh.lost_reason,
      'moved_by_name', COALESCE(em.display_name, em.full_name)
    )
  FROM lead_stage_history lsh
  JOIN pipeline_stages ps ON ps.id = lsh.stage_id
  LEFT JOIN employees em ON em.id = lsh.moved_by
  WHERE lsh.lead_id = p_lead_id

  UNION ALL

  SELECT
    'follow_up_call'::text,
    COALESCE(fu.occurred_at, fu.created_at),
    (CASE WHEN fu.source_type = 'call' THEN 'Follow-up call' ELSE 'Follow-up web form' END)::text,
    fu.transcription,
    jsonb_build_object(
      'source_type', fu.source_type, 'duration_sec', fu.duration_sec,
      'caller_number', fu.caller_number, 'recording_url', fu.recording_url,
      'transcript_analysis', fu.transcript_analysis, 'merged_lead_id', fu.id
    )
  FROM inbound_leads fu
  WHERE fu.merged_into_lead_id = p_lead_id

  ORDER BY 2 DESC;
END;
$$;


ALTER FUNCTION "public"."get_lead_activity"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_notes"("p_lead_id" "uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.crm_lead_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT json_build_object(
    'id', ln.id,
    'lead_id', ln.lead_id,
    'body', ln.body,
    'created_at', ln.created_at,
    'created_by', ln.created_by,
    'author_name', COALESCE(e.display_name, e.full_name)
  )
  FROM crm_lead_notes ln
  LEFT JOIN employees e ON e.id = ln.created_by
  WHERE ln.lead_id = p_lead_id
     OR ln.lead_id IN (SELECT id FROM inbound_leads WHERE merged_into_lead_id = p_lead_id)
  ORDER BY ln.created_at DESC;
END;
$$;


