CREATE OR REPLACE FUNCTION "public"."get_managed_credentials_status"() RETURNS SETOF json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  RETURN QUERY
  SELECT json_build_object(
           'provider', p.provider,
           'connected', (c.access_token IS NOT NULL AND (
             p.provider <> 'encircle' OR c.managed_status = 'active'
           )),
           'connected_at', CASE WHEN c.access_token IS NOT NULL THEN c.connected_at END,
           'updated_at', c.updated_at,
           'managed_status', CASE WHEN p.provider = 'encircle' THEN c.managed_status END,
           'last_verified_at', CASE WHEN p.provider = 'encircle' THEN c.last_verified_at END,
           'last_verification_status',
             CASE WHEN p.provider = 'encircle' THEN c.last_verification_status END,
           'organization_name', CASE WHEN p.provider = 'encircle' THEN c.company_name END,
           'phone_number', CASE WHEN p.provider = 'twilio'
                                THEN (SELECT value FROM integration_config WHERE key = 'twilio_phone_number')
                           END,
           'has_account_sid', CASE WHEN p.provider = 'twilio'
                                   THEN (SELECT value IS NOT NULL AND btrim(value) <> ''
                                         FROM integration_config WHERE key = 'twilio_account_sid')
                              END,
           'has_messaging_service', CASE WHEN p.provider = 'twilio'
                                         THEN (SELECT value IS NOT NULL AND btrim(value) <> ''
                                               FROM integration_config WHERE key = 'twilio_messaging_service_sid')
                                    END
         )
  FROM (VALUES ('stripe'), ('twilio'), ('resend'), ('encircle')) AS p(provider)
  LEFT JOIN public.integration_credentials c ON c.provider = p.provider;
END;
$$;


ALTER FUNCTION "public"."get_managed_credentials_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_message_author_directory"("p_message_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "full_name" "text", "display_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_is_service boolean := auth.role() = 'service_role';
BEGIN
  IF NOT v_is_service
     AND NOT public.messaging_can_access_conversations() THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: Conversations access required for message authors'
      USING errcode = '42501';
  END IF;

  IF p_message_ids IS NULL
     OR array_position(p_message_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION
      'INVALID_MESSAGE_AUTHORS: message IDs must be non-null'
      USING errcode = '22023';
  END IF;

  IF cardinality(p_message_ids) > 200 THEN
    RAISE EXCEPTION
      'INVALID_MESSAGE_AUTHORS: at most 200 message IDs are allowed'
      USING errcode = '22023';
  END IF;

  IF cardinality(p_message_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH requested_message AS (
    SELECT DISTINCT requested.message_id
    FROM unnest(p_message_ids) requested(message_id)
  ),
  author AS (
    SELECT DISTINCT
      employee.id,
      employee.full_name,
      employee.display_name
    FROM requested_message requested
    JOIN public.messages message
      ON message.id = requested.message_id
     AND message.sent_by IS NOT NULL
     AND (
       v_is_service
       OR public.messaging_can_access_conversation(message.conversation_id)
     )
    JOIN public.employees employee
      ON employee.id = message.sent_by
  )
  SELECT
    author.id,
    author.full_name,
    author.display_name
  FROM author
  ORDER BY
    COALESCE(author.display_name, author.full_name),
    author.full_name;
END;
$$;


ALTER FUNCTION "public"."get_message_author_directory"("p_message_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_message_log"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_direction" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "body" "text", "direction" "text", "status" "text", "created_at" timestamp with time zone, "contact_name" "text", "contact_phone" "text", "conversation_id" "uuid", "media_url" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    m.id, m.body,
    CASE WHEN m.sender_contact_id IS NOT NULL THEN 'inbound' ELSE 'outbound' END AS direction,
    m.status, m.created_at,
    COALESCE(c.name, cp.phone) AS contact_name,
    cp.phone AS contact_phone,
    m.conversation_id,
    m.media_urls AS media_url
  FROM messages m
  JOIN conversations conv ON m.conversation_id = conv.id
  LEFT JOIN conversation_participants cp ON cp.conversation_id = conv.id AND cp.is_active = true
  LEFT JOIN contacts c ON cp.contact_id = c.id
  WHERE (p_direction IS NULL 
    OR (p_direction = 'inbound' AND m.sender_contact_id IS NOT NULL)
    OR (p_direction = 'outbound' AND m.sender_contact_id IS NULL))
    AND (p_status IS NULL OR m.status = p_status)
  ORDER BY m.created_at DESC
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."get_message_log"("p_limit" integer, "p_offset" integer, "p_direction" "text", "p_status" "text") OWNER TO "postgres";


