CREATE OR REPLACE FUNCTION "public"."get_my_appointments_today"("p_employee_id" "uuid", "p_include_cancelled" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  today date := public.mt_today();
BEGIN
  SELECT jsonb_agg(row_data ORDER BY (row_data->>'time_start'))
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac2.id, 'employee_id', ac2.employee_id, 'role', ac2.role,
          'employees', jsonb_build_object(
            'id', e2.id, 'display_name', e2.display_name, 'full_name', e2.full_name,
            'color', e2.color, 'avatar_url', e2.avatar_url
          )
        ))
        FROM appointment_crew ac2 JOIN employees e2 ON e2.id = ac2.employee_id
        WHERE ac2.appointment_id = a.id
      ), '[]'::jsonb)
    ) as row_data
    FROM appointments a
    JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date = today
      AND (p_include_cancelled OR a.status <> 'cancelled')
  ) sub;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_my_appointments_today"("p_employee_id" "uuid", "p_include_cancelled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_conversation_access_snapshot"("p_conversation_ids" "uuid"[]) RETURNS TABLE("conversation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_id uuid;
BEGIN
  IF p_conversation_ids IS NULL
     OR cardinality(p_conversation_ids) > 200
     OR EXISTS (
       SELECT 1
       FROM unnest(p_conversation_ids) requested(conversation_id)
       WHERE requested.conversation_id IS NULL
     ) THEN
    RAISE EXCEPTION 'conversation ids must contain at most 200 non-null values'
      USING ERRCODE = '22023';
  END IF;

  SELECT employee.id
    INTO v_actor_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active
    AND NOT employee.is_external
  LIMIT 1;

  IF v_actor_id IS NULL
     OR NOT public.messaging_employee_has_conversations_capability(v_actor_id) THEN
    RAISE EXCEPTION 'Messages access is not granted'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT DISTINCT conversation.id
  FROM unnest(p_conversation_ids) requested(conversation_id)
  JOIN public.conversations conversation
    ON conversation.id = requested.conversation_id
  WHERE public.messaging_employee_can_access_conversation(
    v_actor_id,
    conversation.id
  )
  ORDER BY conversation.id;
END;
$$;


ALTER FUNCTION "public"."get_my_conversation_access_snapshot"("p_conversation_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_conversation_access_snapshot"("p_conversation_ids" "uuid"[]) IS 'Actor-derived bounded access snapshot. Returns only existing conversations the authenticated active internal employee can currently access.';



CREATE OR REPLACE FUNCTION "public"."get_my_employee_profile"() RETURNS TABLE("id" "uuid", "full_name" "text", "display_name" "text", "email" "text", "role" "text", "is_active" boolean, "is_external" boolean, "default_division" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_binding_count integer;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: authenticated employee required'
      USING errcode = '42501';
  END IF;

  SELECT count(*)
    INTO v_binding_count
  FROM public.employees employee
  WHERE employee.auth_user_id = v_actor_id
    AND employee.is_active;

  IF v_binding_count > 1 THEN
    RAISE EXCEPTION 'IDENTITY_CONFLICT: multiple active employee bindings'
      USING errcode = '21000';
  END IF;

  IF v_binding_count = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    employee.id,
    employee.full_name,
    employee.display_name,
    employee.email,
    employee.role::text,
    employee.is_active,
    employee.is_external,
    employee.default_division
  FROM public.employees employee
  WHERE employee.auth_user_id = v_actor_id
    AND employee.is_active;
END;
$$;


ALTER FUNCTION "public"."get_my_employee_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_notification_prefs"("p_employee_id" "uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT COALESCE(
       (SELECT auth.jwt() ->> 'role' = 'service_role'),
       false
     )
     AND NOT public.is_current_native_push_preferences_employee(p_employee_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: own notification preferences only'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT resolved_pref
  FROM public.get_effective_notification_prefs(p_employee_id) AS resolved_pref
  WHERE COALESCE((resolved_pref->>'type_enabled')::boolean, false);
END;
$$;


ALTER FUNCTION "public"."get_my_notification_prefs"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_notification_quiet_time"("p_employee_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_current_native_push_preferences_employee(p_employee_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: own notification quiet time only' USING errcode = '42501';
  END IF;
  RETURN COALESCE((SELECT enabled FROM public.notification_quiet_time_preferences WHERE employee_id = p_employee_id), false);
END;
