CREATE OR REPLACE FUNCTION "public"."get_my_onboarding_version_seen"("p_surface" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_employee_id uuid;
  v_version integer;
BEGIN
  IF p_surface IS NULL OR p_surface NOT IN ('tech') THEN
    RAISE EXCEPTION 'unknown onboarding surface'
      USING errcode = '22023';
  END IF;

  SELECT employee.id
  INTO v_employee_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IN (
      'admin',
      'office',
      'project_manager',
      'field_tech',
      'estimator',
      'supervisor'
    )
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  SELECT state.version_seen
  INTO v_version
  FROM public.employee_onboarding_state state
  WHERE state.employee_id = v_employee_id
    AND state.surface = p_surface;

  RETURN COALESCE(v_version, 0);
END;
$$;


ALTER FUNCTION "public"."get_my_onboarding_version_seen"("p_surface" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_push_subscriptions"("p_employee_id" "uuid") RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'id',            ps.id,
    'label',         ps.user_agent,
    'created_at',    ps.created_at,
    'endpoint_hash', substr(encode(extensions.digest(ps.endpoint, 'sha256'), 'hex'), 1, 16)
  )
  FROM public.push_subscriptions ps
  WHERE ps.employee_id = p_employee_id
  ORDER BY ps.created_at DESC;
$$;


ALTER FUNCTION "public"."get_my_push_subscriptions"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_defaults"() RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH roles(role) AS (
    VALUES ('admin'), ('office'), ('project_manager'), ('supervisor'),
           ('field_tech'), ('crm_partner')
  ),
  channels(channel) AS (VALUES ('bell'), ('push'), ('email')),
  matrix AS (
    SELECT r.role, t.type_key, t.label, t.category, t.sort_order,
           t.enabled AS type_enabled, c.channel,
           CASE c.channel WHEN 'bell'  THEN t.bell_default
                          WHEN 'push'  THEN t.push_default
                          ELSE              t.email_default END AS type_channel_default
      FROM public.notification_types t
      CROSS JOIN roles r
      CROSS JOIN channels c
  )
  SELECT json_build_object(
    'role',                 m.role,
    'type_key',             m.type_key,
    'label',                m.label,
    'category',             m.category,
    'sort_order',           m.sort_order,
    'channel',              m.channel,
    'type_enabled',         m.type_enabled,
    'type_channel_default', m.type_channel_default,
    'enabled',             COALESCE(rd.enabled, m.type_channel_default),
    'user_customizable',   COALESCE(rd.user_customizable, true),
    'has_default',         (rd.id IS NOT NULL)
  )
  FROM matrix m
  LEFT JOIN public.notification_role_defaults rd
    ON rd.role = m.role AND rd.type_key = m.type_key AND rd.channel = m.channel
  ORDER BY m.sort_order, m.type_key, m.role, m.channel;
$$;


ALTER FUNCTION "public"."get_notification_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notifications"("p_limit" integer DEFAULT 30, "p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."notifications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  IF v_is_service_role THEN
    RETURN QUERY
    SELECT notification.*
    FROM public.notifications notification
    WHERE notification.recipient_id IS NULL
       OR notification.recipient_id = p_employee_id
    ORDER BY notification.created_at DESC
    LIMIT greatest(1, least(p_limit, 100));
    RETURN;
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active = true
    AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NOT NULL AND p_employee_id <> v_actor THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;

  RETURN QUERY
  SELECT
    notification.id,
    notification.type,
    notification.title,
    notification.body,
    notification.link,
    notification.entity_type,
    notification.entity_id,
    notification.job_id,
    notification.payload,
    CASE
      WHEN notification.recipient_id IS NULL
        THEN COALESCE(notification.read_at, receipt.read_at)
      ELSE notification.read_at
    END AS read_at,
    notification.created_at,
    notification.recipient_id,
    notification.type_key
  FROM public.notifications notification
  LEFT JOIN public.notification_reads receipt
    ON receipt.notification_id = notification.id
   AND receipt.employee_id = v_actor
   AND notification.recipient_id IS NULL
  WHERE notification.recipient_id IS NULL
     OR notification.recipient_id = p_employee_id
  ORDER BY notification.created_at DESC
  LIMIT greatest(1, least(p_limit, 100));
END;
$$;


ALTER FUNCTION "public"."get_notifications"("p_limit" integer, "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_oop_pricing_admin_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.oop_pricing_active_employee(true);
  RETURN jsonb_build_object('published',(SELECT jsonb_build_object('id',r.id,'revisionNumber',r.revision_number,'status',r.status,'lockVersion',r.lock_version,'config',r.config,'createdAt',r.created_at,'publishedAt',r.published_at,'contentHash',md5(r.config::text)) FROM public.oop_pricing_revisions r WHERE status='published'),'draft',(SELECT jsonb_build_object('id',r.id,'revisionNumber',r.revision_number,'status',r.status,'lockVersion',r.lock_version,'config',r.config,'createdAt',r.created_at,'publishedAt',r.published_at,'contentHash',md5(r.config::text)) FROM public.oop_pricing_revisions r WHERE status='draft'));
END;
$$;


ALTER FUNCTION "public"."get_oop_pricing_admin_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_oop_pricing_config"("p_revision_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_id uuid; v_result jsonb;
BEGIN
  PERFORM public.oop_pricing_active_employee(false);
  SELECT r.id INTO v_id FROM public.oop_pricing_revisions r WHERE r.id = p_revision_id AND r.status IN ('published','superseded')
  UNION ALL SELECT r.id FROM public.oop_pricing_revisions r WHERE p_revision_id IS NULL AND r.status = 'published' LIMIT 1;
  SELECT jsonb_build_object('id',id,'revisionNumber',revision_number,'status',status,'lockVersion',lock_version,'config',config,'createdAt',created_at,'publishedAt',published_at,'contentHash',md5(config::text)) INTO v_result FROM public.oop_pricing_revisions WHERE id=v_id;
  IF v_result IS NULL THEN RAISE EXCEPTION 'pricing_revision_not_found'; END IF; RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_oop_pricing_config"("p_revision_id" "uuid") OWNER TO "postgres";


