CREATE OR REPLACE FUNCTION "public"."get_oop_quotes"("p_limit" integer DEFAULT 50, "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "quote_number" "text", "job_id" "uuid", "job_type" "text", "insured_name" "text", "address" "text", "quote_total" numeric, "net_margin_pct" numeric, "created_at" timestamp with time zone, "created_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.oop_pricing_active_employee(false);
  PERFORM public.oop_pricing_assert_job_exists(p_job_id);
  RETURN QUERY SELECT q.id,q.quote_number,q.job_id,q.job_type,q.insured_name,q.address,q.quote_total,q.net_margin_pct,q.created_at,q.created_by
    FROM public.oop_quotes q WHERE (p_job_id IS NULL OR q.job_id=p_job_id)
    ORDER BY q.created_at DESC LIMIT least(greatest(COALESCE(p_limit,50),1),200);
END;
$$;


ALTER FUNCTION "public"."get_oop_quotes"("p_limit" integer, "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_open_estimates_summary"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH e AS (
    SELECT public.dash_division_bucket(COALESCE(es.intended_division, j.division::text)) AS bucket,
           COALESCE(es.amount, 0) AS amt
    FROM estimates es
    LEFT JOIN jobs j ON j.id = es.job_id
    WHERE COALESCE(es.status, 'open') NOT IN ('approved','denied','rejected','cancelled','void','converted','paid')
  )
  SELECT jsonb_build_object(
    'total_count', COALESCE((SELECT count(*) FROM e), 0),
    'total_value', COALESCE((SELECT SUM(amt) FROM e), 0),
    'segments', COALESCE((SELECT jsonb_agg(jsonb_build_object('key', bucket, 'count', c, 'value', v))
                          FROM (SELECT bucket, count(*) c, SUM(amt) v FROM e GROUP BY bucket) s), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "public"."get_open_estimates_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_orphan_contacts"() RETURNS TABLE("id" "uuid", "name" "text", "phone" "text", "role" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT c.id, c.name, c.phone, c.role, c.created_at
  FROM contacts c
  LEFT JOIN contact_jobs cj ON c.id = cj.contact_id
  WHERE cj.id IS NULL
  ORDER BY c.created_at DESC LIMIT 100;
$$;


ALTER FUNCTION "public"."get_orphan_contacts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_overdue_tasks"("p_assignee" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS SETOF json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT json_build_object(
    'id', t.id, 'title', t.title, 'notes', t.notes, 'due_at', t.due_at,
    'remind_at', t.remind_at, 'status', t.status,
    'assignee_id', t.assignee_id, 'assignee_name', e.full_name,
    'contact_id', t.contact_id, 'contact_name', c.name, 'lead_id', t.lead_id,
    'created_at', t.created_at, 'updated_at', t.updated_at, 'completed_at', t.completed_at
  )
  FROM crm_tasks t
  LEFT JOIN employees e ON e.id = t.assignee_id
  LEFT JOIN contacts  c ON c.id = t.contact_id
  WHERE t.status = 'open'
    AND t.due_at IS NOT NULL
    AND (t.due_at AT TIME ZONE 'America/Denver')::date < (p_now AT TIME ZONE 'America/Denver')::date
    AND (p_org_id   IS NULL OR t.org_id      = p_org_id)
    AND (p_assignee IS NULL OR t.assignee_id = p_assignee)
  ORDER BY t.due_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_overdue_tasks"("p_assignee" "uuid", "p_org_id" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payments_ledger"("p_limit" integer DEFAULT 500) RETURNS TABLE("payment_id" "uuid", "amount" numeric, "payment_date" "date", "payment_method" "text", "payer_type" "text", "payer_name" "text", "reference_number" "text", "is_deductible" boolean, "created_at" timestamp with time zone, "source" "text", "qbo_payment_id" "text", "qbo_synced_at" timestamp with time zone, "qbo_sync_error" "text", "invoice_id" "uuid", "invoice_number" "text", "qbo_doc_number" "text", "job_id" "uuid", "job_number" "text", "division" "text", "claim_id" "uuid", "claim_number" "text", "contact_id" "uuid", "client_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.billing_edit_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    p.id, p.amount, p.payment_date, p.payment_method,
    p.payer_type, p.payer_name, p.reference_number,
    p.is_deductible, p.created_at, p.source,
    p.qbo_payment_id, p.qbo_synced_at, p.qbo_sync_error,
    p.invoice_id, i.invoice_number, i.qbo_doc_number,
    p.job_id, j.job_number, j.division::text,
    j.claim_id, cl.claim_number,
    p.contact_id, COALESCE(ct.name, jc.name) AS client_name
  FROM payments p
  LEFT JOIN invoices i  ON i.id  = p.invoice_id
  LEFT JOIN jobs     j  ON j.id  = p.job_id
  LEFT JOIN claims   cl ON cl.id = j.claim_id
  LEFT JOIN contacts ct ON ct.id = p.contact_id
  LEFT JOIN contacts jc ON jc.id = j.primary_contact_id
  ORDER BY p.payment_date DESC NULLS LAST, p.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 2000));
END;
$$;


ALTER FUNCTION "public"."get_payments_ledger"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payments_received"("p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.billing_edit_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  RETURN (
  WITH pay AS (
    SELECT public.dash_division_bucket(j.division::text) AS bucket,
           COALESCE(p.amount, 0) - COALESCE(p.refunded_amount, 0) AS amt,
           p.payment_date AS d
    FROM payments p
    LEFT JOIN invoices i ON i.id = p.invoice_id
    LEFT JOIN jobs j ON j.id = COALESCE(p.job_id, i.job_id)
    WHERE p.payment_date IS NOT NULL
  ),
  cur  AS (SELECT bucket, SUM(amt) AS v FROM pay WHERE d BETWEEN p_start AND p_end AND bucket IS NOT NULL GROUP BY bucket),
  tot  AS (SELECT SUM(amt) AS v FROM pay WHERE d BETWEEN p_start AND p_end),
  prev AS (SELECT SUM(amt) AS v FROM pay WHERE d BETWEEN (p_start - ((p_end - p_start) + 1)) AND (p_start - 1))
  SELECT jsonb_build_object(
    'total',      COALESCE((SELECT v FROM tot), 0),
    'prev_total', COALESCE((SELECT v FROM prev), 0),
    'segments',   COALESCE((SELECT jsonb_agg(jsonb_build_object('key', bucket, 'value', v)) FROM cur), '[]'::jsonb)
  )
  );
END;
$$;


ALTER FUNCTION "public"."get_payments_received"("p_start" "date", "p_end" "date") OWNER TO "postgres";


