CREATE OR REPLACE FUNCTION "public"."get_payroll_summary"("p_start_date" "date" DEFAULT ("date_trunc"('week'::"text", ("public"."mt_today"())::timestamp with time zone))::"date", "p_end_date" "date" DEFAULT (("date_trunc"('week'::"text", ("public"."mt_today"())::timestamp with time zone) + '6 days'::interval))::"date") RETURNS TABLE("employee_id" "uuid", "employee_name" "text", "hourly_rate" numeric, "overtime_rate" numeric, "total_hours" numeric, "regular_hours" numeric, "overtime_hours" numeric, "regular_cost" numeric, "overtime_cost" numeric, "total_cost" numeric, "approved_hours" numeric, "pending_hours" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH weekly_hours AS (
    SELECT
      t.employee_id,
      date_trunc('week', t.work_date::timestamp) AS week_start,
      SUM(t.hours) AS week_hours
    FROM job_time_entries t
    WHERE t.work_date BETWEEN p_start_date AND p_end_date
    GROUP BY t.employee_id, date_trunc('week', t.work_date::timestamp)
  ),
  ot_by_employee AS (
    SELECT
      employee_id,
      SUM(GREATEST(week_hours - 40, 0)) AS total_ot_hours,
      SUM(LEAST(week_hours, 40)) AS total_reg_hours
    FROM weekly_hours
    GROUP BY employee_id
  )
  SELECT
    e.id AS employee_id,
    e.full_name AS employee_name,
    e.hourly_rate,
    COALESCE(e.overtime_rate, e.hourly_rate * 1.5) AS overtime_rate,
    SUM(t.hours) AS total_hours,
    COALESCE(ot.total_reg_hours, SUM(t.hours)) AS regular_hours,
    COALESCE(ot.total_ot_hours, 0) AS overtime_hours,
    ROUND(COALESCE(ot.total_reg_hours, SUM(t.hours)) * e.hourly_rate, 2) AS regular_cost,
    ROUND(COALESCE(ot.total_ot_hours, 0) * COALESCE(e.overtime_rate, e.hourly_rate * 1.5), 2) AS overtime_cost,
    ROUND(
      COALESCE(ot.total_reg_hours, SUM(t.hours)) * e.hourly_rate +
      COALESCE(ot.total_ot_hours, 0) * COALESCE(e.overtime_rate, e.hourly_rate * 1.5),
    2) AS total_cost,
    SUM(CASE WHEN t.approved THEN t.hours ELSE 0 END) AS approved_hours,
    SUM(CASE WHEN NOT COALESCE(t.approved, false) THEN t.hours ELSE 0 END) AS pending_hours
  FROM employees e
  JOIN job_time_entries t ON t.employee_id = e.id
  LEFT JOIN ot_by_employee ot ON ot.employee_id = e.id
  WHERE t.work_date BETWEEN p_start_date AND p_end_date
    AND e.is_active = true
  GROUP BY e.id, e.full_name, e.hourly_rate, e.overtime_rate, ot.total_reg_hours, ot.total_ot_hours
  ORDER BY e.full_name;
$$;


ALTER FUNCTION "public"."get_payroll_summary"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pipeline_movement"("p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_since timestamptz;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_since := (SELECT MIN(moved_at) FROM lead_stage_history WHERE org_id = v_org);

  RETURN QUERY
  WITH moves AS (
    SELECT lsh.stage_id, lsh.from_stage_id
    FROM lead_stage_history lsh
    JOIN inbound_leads il ON il.id = lsh.lead_id
    WHERE lsh.org_id = v_org
      AND COALESCE(il.spam_flag, false) = false
      AND (p_start IS NULL OR public.mt_date(lsh.moved_at) >= p_start)
      AND (p_end   IS NULL OR public.mt_date(lsh.moved_at) <= p_end)
  ),
  in_c  AS (SELECT stage_id AS sid, COUNT(*) AS c FROM moves GROUP BY stage_id),
  out_c AS (SELECT from_stage_id AS sid, COUNT(*) AS c FROM moves WHERE from_stage_id IS NOT NULL GROUP BY from_stage_id)
  SELECT json_build_object(
    'stage_id',   ps.id,
    'stage_name', ps.name,
    'sort_order', ps.sort_order,
    'is_won',     ps.is_won,
    'is_lost',    ps.is_lost,
    'moved_in',   COALESCE(in_c.c, 0),
    'moved_out',  COALESCE(out_c.c, 0),
    'net',        COALESCE(in_c.c, 0) - COALESCE(out_c.c, 0),
    'data_since', v_since
  )
  FROM pipeline_stages ps
  LEFT JOIN in_c  ON in_c.sid  = ps.id
  LEFT JOIN out_c ON out_c.sid = ps.id
  WHERE ps.org_id = v_org
  ORDER BY ps.sort_order;
END;
$$;


ALTER FUNCTION "public"."get_pipeline_movement"("p_start" "date", "p_end" "date", "p_org_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pipeline_stages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "color" "text" DEFAULT '#6366f1'::"text" NOT NULL,
    "is_won" boolean DEFAULT false NOT NULL,
    "is_lost" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "win_probability" numeric,
    "is_recoverable" boolean DEFAULT false NOT NULL,
    CONSTRAINT "pipeline_stages_win_probability_check" CHECK ((("win_probability" IS NULL) OR (("win_probability" >= (0)::numeric) AND ("win_probability" <= (1)::numeric))))
);


ALTER TABLE "public"."pipeline_stages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."pipeline_stages"."is_recoverable" IS 'A terminal (is_won/is_lost) stage a lead may automatically LEAVE when new forward evidence arrives (AI-detected qualification/appointment, auto-advance triggers). Missed Calls = true; Won/Lost = false (human judgments stay sticky).';



CREATE OR REPLACE FUNCTION "public"."get_pipeline_stages"("p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."pipeline_stages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.crm_lead_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT *
    FROM pipeline_stages
   WHERE org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
   ORDER BY sort_order;
END;
$$;


ALTER FUNCTION "public"."get_pipeline_stages"("p_org_id" "uuid") OWNER TO "postgres";


