CREATE OR REPLACE FUNCTION "public"."get_purgeable_feedback_media"("p_days" integer DEFAULT 90) RETURNS TABLE("id" "uuid", "attachments" "jsonb", "resolved_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  -- Clamp INSIDE the RPC: the purge endpoint that will call this runs
  -- unauthenticated (cron convention), so a caller-supplied p_days must never
  -- be able to shorten retention below 30 days.
  v_days int := GREATEST(COALESCE(p_days, 90), 30);
BEGIN
  RETURN QUERY
    SELECT f.id, f.attachments, f.resolved_at
    FROM tech_feedback f
    WHERE f.status IN ('resolved', 'dismissed')
      AND f.resolved_at IS NOT NULL
      AND f.resolved_at < now() - make_interval(days => v_days)
      AND f.attachments_purged_at IS NULL
      AND f.attachments <> '[]'::jsonb
    ORDER BY f.resolved_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_purgeable_feedback_media"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_qbo_connection_status"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  c record;
begin
  select refresh_token, granted_scopes, company_name, environment
    into c
  from integration_credentials
  where provider = 'quickbooks'
  limit 1;

  return json_build_object(
    'connected',         (c.refresh_token is not null),
    'has_payment_scope', coalesce(c.granted_scopes ilike '%com.intuit.quickbooks.payment%', false),
    'company_name',      c.company_name,
    'environment',       coalesce(c.environment, 'production')
  );
end;
$$;


ALTER FUNCTION "public"."get_qbo_connection_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_qbo_estimate_command"("p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE c public.qbo_estimate_commands;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE id=p_command_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 RETURN to_jsonb(c)||jsonb_build_object('ok',true);
END;$$;


ALTER FUNCTION "public"."get_qbo_estimate_command"("p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_qbo_invoice_command"("p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_command public.qbo_invoice_commands;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_command
  FROM public.qbo_invoice_commands
  WHERE id = p_command_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'command-not-found');
  END IF;
  RETURN to_jsonb(v_command) || jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."get_qbo_invoice_command"("p_command_id" "uuid") OWNER TO "postgres";


