CREATE OR REPLACE FUNCTION "public"."get_real_claims_created"("p_floor" timestamp with time zone) RETURNS TABLE("created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.created_at
  FROM public.claims c
  WHERE c.created_at >= p_floor
    AND COALESCE(c.status,'') <> 'deleted'
    AND EXISTS (
      SELECT 1 FROM public.jobs j
      WHERE j.claim_id = c.id AND j.is_real_job = true AND COALESCE(j.status,'') <> 'deleted'
    )
  ORDER BY c.created_at DESC;
$$;


