$$;


ALTER FUNCTION "public"."get_referral_sources"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_revenue_by_division"("p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.billing_edit_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  RETURN (
  WITH inv AS (
    SELECT public.dash_division_bucket(j.division::text) AS bucket,
           COALESCE(i.adjusted_total, i.total, 0) AS amt,
           i.invoice_date AS d
    FROM invoices i JOIN jobs j ON j.id = i.job_id
    WHERE i.qbo_invoice_id IS NOT NULL
  ),
  cur AS (SELECT bucket, SUM(amt) AS v FROM inv WHERE d BETWEEN p_start AND p_end GROUP BY bucket),
  prev AS (SELECT SUM(amt) AS v FROM inv WHERE d BETWEEN (p_start - ((p_end - p_start) + 1)) AND (p_start - 1))
  SELECT jsonb_build_object(
    'total', COALESCE((SELECT SUM(v) FROM cur), 0),
    'prev_total', COALESCE((SELECT v FROM prev), 0),
    'segments', COALESCE((SELECT jsonb_agg(jsonb_build_object('key', bucket, 'value', v)) FROM cur), '[]'::jsonb)
  )
  );
END;
$$;


ALTER FUNCTION "public"."get_revenue_by_division"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_template"("p_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', t.id, 'name', t.name, 'description', t.description,
    'division', t.division, 'is_active', t.is_active,
    'created_by', t.created_by, 'created_at', t.created_at,
    'phases', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id, 'name', p.name, 'description', p.description,
        'appointment_type', p.appointment_type, 'day_offset', p.day_offset,
        'duration_days', p.duration_days, 'default_start_time', p.default_start_time,
        'default_end_time', p.default_end_time, 'is_milestone', p.is_milestone,
        'color', p.color, 'default_crew_count', p.default_crew_count,
        'display_order', p.display_order, 'notes', p.notes,
        'tasks', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', tk.id, 'title', tk.title, 'description', tk.description,
            'is_required', tk.is_required, 'display_order', tk.display_order
          ) ORDER BY tk.display_order)
          FROM template_tasks tk WHERE tk.template_phase_id = p.id
        ), '[]'::jsonb)
      ) ORDER BY p.display_order)
      FROM template_phases p WHERE p.template_id = t.id
    ), '[]'::jsonb),
    'dependencies', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', d.id, 'source_phase_id', d.source_phase_id,
        'target_phase_id', d.target_phase_id,
        'dependency_type', d.dependency_type, 'lag_days', d.lag_days
      ))
      FROM template_dependencies d WHERE d.template_id = t.id
    ), '[]'::jsonb)
  ) INTO result
  FROM schedule_templates t WHERE t.id = p_template_id;
  RETURN result;
END; $$;


ALTER FUNCTION "public"."get_schedule_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_templates"("p_division" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', t.id, 'name', t.name, 'description', t.description,
    'division', t.division, 'is_active', t.is_active, 'created_at', t.created_at,
    'phase_count', (SELECT count(*) FROM template_phases p WHERE p.template_id = t.id AND NOT p.is_milestone),
    'milestone_count', (SELECT count(*) FROM template_phases p WHERE p.template_id = t.id AND p.is_milestone),
    'task_count', (SELECT count(*) FROM template_tasks tk JOIN template_phases p ON tk.template_phase_id = p.id WHERE p.template_id = t.id)
  ) ORDER BY t.name), '[]'::jsonb) INTO result
  FROM schedule_templates t
  WHERE t.is_active = true AND (p_division IS NULL OR t.division = p_division);
  RETURN result;
END; $$;


ALTER FUNCTION "public"."get_schedule_templates"("p_division" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_scheduled_queue"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "body" "text", "send_at" timestamp with time zone, "status" "text", "contact_name" "text", "contact_phone" "text", "template_name" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    sm.id, sm.body, sm.send_at, sm.status,
    COALESCE(c.name, cp.phone) AS contact_name,
    cp.phone AS contact_phone,
    mt.title AS template_name
  FROM scheduled_messages sm
  LEFT JOIN conversations conv ON sm.conversation_id = conv.id
  LEFT JOIN conversation_participants cp ON cp.conversation_id = conv.id AND cp.is_active = true
  LEFT JOIN contacts c ON cp.contact_id = c.id
  LEFT JOIN message_templates mt ON sm.template_id = mt.id
  ORDER BY sm.send_at ASC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_scheduled_queue"("p_limit" integer) OWNER TO "postgres";


