CREATE OR REPLACE FUNCTION "public"."get_sequences"("p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT json_build_object(
    'id', s.id,
    'name', s.name,
    'description', s.description,
    'status', s.status,
    'exit_on_reply', s.exit_on_reply,
    'exit_on_conversion', s.exit_on_conversion,
    'created_at', s.created_at,
    'updated_at', s.updated_at,
    'steps', COALESCE((
      SELECT json_agg(json_build_object(
        'id', st.id, 'step_order', st.step_order, 'channel', st.channel,
        'delay_hours', st.delay_hours, 'subject', st.subject, 'body', st.body,
        'template_id', st.template_id
      ) ORDER BY st.step_order)
      FROM crm_sequence_steps st WHERE st.sequence_id = s.id
    ), '[]'::json),
    'stats', (
      SELECT json_build_object(
        'active',    count(*) FILTER (WHERE e.status = 'active'),
        'paused',    count(*) FILTER (WHERE e.status = 'paused'),
        'completed', count(*) FILTER (WHERE e.status = 'completed'),
        'exited',    count(*) FILTER (WHERE e.status = 'exited'),
        'total',     count(*)
      )
      FROM crm_sequence_enrollments e WHERE e.sequence_id = s.id
    ),
    'enrollments', COALESCE((
      SELECT json_agg(en) FROM (
        SELECT e.id, e.contact_id, c.name AS contact_name, c.phone AS contact_phone,
               e.status, e.current_step, e.next_run_at, e.enrolled_at,
               e.completed_at, e.exit_reason
        FROM crm_sequence_enrollments e
        LEFT JOIN contacts c ON c.id = e.contact_id
        WHERE e.sequence_id = s.id
        ORDER BY e.enrolled_at DESC
        LIMIT 200
      ) en
    ), '[]'::json)
  )
  FROM crm_sequences s
  WHERE s.org_id = COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1))
  ORDER BY s.created_at DESC;
$$;


ALTER FUNCTION "public"."get_sequences"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_service_sms_consent_status"("p_contact_id" "uuid", "p_destination_phone" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_contact public.contacts%ROWTYPE;
  v_service_consent public.service_sms_consents%ROWTYPE;
  v_work_auth_consent public.work_authorization_sms_consents%ROWTYPE;
  v_phone_digits text;
  v_phone_key text;
  v_locked_phone_digits text;
  v_locked_phone_key text;
  v_destination_digits text;
  v_destination_key text;
BEGIN
  IF current_user <> 'service_role' THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'CONSENT_STATUS_NOT_AUTHORIZED'
    );
  END IF;

  IF p_contact_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'CONTACT_NOT_FOUND');
  END IF;

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id;

  IF v_contact.id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'CONTACT_NOT_FOUND');
  END IF;

  v_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_phone_digits) = 10 THEN
    v_phone_key := v_phone_digits;
  ELSIF length(v_phone_digits) = 11 AND left(v_phone_digits, 1) = '1' THEN
    v_phone_key := right(v_phone_digits, 10);
  ELSE
    RETURN jsonb_build_object('allowed', false, 'code', 'CONTACT_HAS_NO_PHONE');
  END IF;

  v_destination_digits := regexp_replace(
    COALESCE(p_destination_phone, v_contact.phone, ''),
    '[^0-9]',
    '',
    'g'
  );
  IF length(v_destination_digits) = 10 THEN
    v_destination_key := v_destination_digits;
  ELSIF length(v_destination_digits) = 11 AND left(v_destination_digits, 1) = '1' THEN
    v_destination_key := right(v_destination_digits, 10);
  END IF;

  IF v_destination_key IS NULL OR v_destination_key <> v_phone_key THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'CONTACT_PHONE_MISMATCH',
      'contact_id', v_contact.id
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('messaging-phone:' || v_phone_key, 0));

  SELECT *
  INTO v_contact
  FROM public.contacts
  WHERE id = p_contact_id
  FOR SHARE;

  v_locked_phone_digits := regexp_replace(COALESCE(v_contact.phone, ''), '[^0-9]', '', 'g');
  IF length(v_locked_phone_digits) = 10 THEN
    v_locked_phone_key := v_locked_phone_digits;
  ELSIF length(v_locked_phone_digits) = 11 AND left(v_locked_phone_digits, 1) = '1' THEN
    v_locked_phone_key := right(v_locked_phone_digits, 10);
  END IF;

  IF v_contact.id IS NULL
     OR v_locked_phone_key IS NULL
     OR v_locked_phone_key <> v_phone_key THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'CONTACT_PHONE_CHANGED',
      'contact_id', p_contact_id
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.dnd IS TRUE
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'DND_ACTIVE',
      'contact_id', v_contact.id
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND c.opt_out_at IS NOT NULL
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'NO_CONSENT',
      'contact_id', v_contact.id,
      'source', 'explicit_opt_out'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.message_provider_events e
    WHERE e.direction = 'inbound'
      AND e.message_type IN ('sms', 'mms')
      AND e.processing_state IN ('received', 'claimed', 'retryable', 'failed')
      AND right(regexp_replace(COALESCE(e.sender_address, ''), '[^0-9]', '', 'g'), 10)
        = v_phone_key
      AND regexp_replace(lower(trim(COALESCE(e.content, ''))), '[^a-z0-9]', '', 'g')
        = ANY (ARRAY['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'])
      AND NOT EXISTS (
        SELECT 1
        FROM public.message_provider_events later_event
        WHERE later_event.direction = 'inbound'
          AND later_event.message_type IN ('sms', 'mms')
          AND later_event.processing_state = 'processed'
          AND right(
            regexp_replace(COALESCE(later_event.sender_address, ''), '[^0-9]', '', 'g'),
            10
          ) = v_phone_key
          AND later_event.occurred_at > e.occurred_at
          AND regexp_replace(
            lower(trim(COALESCE(later_event.content, ''))),
            '[^a-z0-9]',
            '',
            'g'
          ) = ANY (ARRAY['start', 'unstop', 'subscribe', 'yes'])
      )
  ) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'NO_CONSENT',
      'contact_id', v_contact.id,
      'source', 'pending_stop'
    );
  END IF;

  IF v_contact.opt_in_status IS TRUE THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'code', 'GLOBAL_OPT_IN',
      'contact_id', v_contact.id,
      'consent_source', v_contact.opt_in_source
    );
  END IF;

  SELECT *
  INTO v_service_consent
  FROM public.service_sms_consents s
  WHERE s.contact_id = v_contact.id
    AND s.consent_scope = 'service_related_customer_project_messages'
    AND s.attestation_version = 'prior_sms_consent_v1';

  IF v_service_consent.contact_id IS NOT NULL
     AND right(
       regexp_replace(COALESCE(v_service_consent.phone, ''), '[^0-9]', '', 'g'),
       10
     ) = v_phone_key THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'code', 'SERVICE_CONSENT',
      'contact_id', v_contact.id,
      'consent_scope', v_service_consent.consent_scope,
      'attested_at', v_service_consent.attested_at
    );
  END IF;

  SELECT *
  INTO v_work_auth_consent
  FROM public.work_authorization_sms_consents w
  WHERE w.contact_id = v_contact.id
    AND w.consent_scope = 'service_related_customer_project_messages'
    AND w.disclosure_version = 'upr_work_auth_sms_v1'
    AND right(
      regexp_replace(COALESCE(w.phone, ''), '[^0-9]', '', 'g'),
      10
    ) = v_phone_key
  ORDER BY w.signed_at DESC
  LIMIT 1;

  IF v_work_auth_consent.sign_request_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'allowed', true,
      'code', 'SERVICE_CONSENT',
      'contact_id', v_contact.id,
      'consent_scope', v_work_auth_consent.consent_scope,
      'attested_at', v_work_auth_consent.signed_at
    );
  END IF;

  -- ── THE 2026-07-28 CHANGE ───────────────────────────────────────────────
  -- Previously: allowed=false / 'NO_CONSENT'. Reaching here means we hold a
  -- phone number for this contact and NONE of the refusals above fired — no
  -- DND, no opt-out, no unfiled STOP, no phone mismatch or mid-flight phone
  -- change. Under the owner's 2026-07-28 direction that is now a yes.
  --
  -- The distinct code matters: callers accept 'IMPLIED_CONSENT' by name, so a
  -- send path can be returned to opt-in-only by removing one string from its
  -- accepted list, with no database change. `source` records WHY this was
  -- allowed so sms_consent_log and any later audit can tell an implied
  -- permission apart from a recorded one.
  RETURN jsonb_build_object(
    'allowed', true,
    'code', 'IMPLIED_CONSENT',
    'contact_id', v_contact.id,
    'source', 'no_recorded_objection',
    'consent_scope', 'service_related_customer_project_messages'
  );
END;
$$;


ALTER FUNCTION "public"."get_service_sms_consent_status"("p_contact_id" "uuid", "p_destination_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sign_document_templates"("p_token" "text") RETURNS SETOF "public"."document_templates"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT dt.*
  FROM public.document_templates dt
  WHERE dt.doc_type = (
    SELECT sr.doc_type
    FROM public.sign_requests sr
    WHERE sr.token = p_token::uuid
    LIMIT 1
  )
  ORDER BY dt.sort_order ASC NULLS LAST;
$$;


ALTER FUNCTION "public"."get_sign_document_templates"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sign_request_by_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id',               sr.id,
    'token',            sr.token,
    'doc_type',         sr.doc_type,
    'divisions',        sr.divisions,
    'status',           sr.status,
    'expires_at',       sr.expires_at,
    'signed_at',        sr.signed_at,
    -- Withheld once the link can no longer be signed. See the header: the ROW
    -- must still come back so the caller can tell "expired" from "already
    -- signed" from "not found"; only its contents are gated.
    'signer_name',      CASE WHEN a.actionable THEN sr.signer_name      ELSE NULL END,
    'signer_email',     CASE WHEN a.actionable THEN sr.signer_email     ELSE NULL END,
    'signed_file_path', CASE WHEN a.actionable THEN sr.signed_file_path ELSE NULL END,
    'job', CASE WHEN a.actionable THEN jsonb_build_object(
      'id',                j.id,
      'job_number',        j.job_number,
      'insured_name',      j.insured_name,
      'address',           j.address,
      'city',              j.city,
      'state',             j.state,
      'zip',               j.zip,
      'date_of_loss',      j.date_of_loss,
      'division',          j.division,
      'insurance_company', j.insurance_company,
      'claim_number',      j.claim_number,
      'policy_number',     j.policy_number,
      'adjuster_name',     j.adjuster_name
    ) ELSE NULL END
  )
  INTO v_result
  FROM sign_requests sr
  JOIN jobs j ON j.id = sr.job_id
  -- now() is the transaction timestamp, so every CASE in one call agrees.
  CROSS JOIN LATERAL (
    SELECT (sr.status = 'pending' AND sr.expires_at > now()) AS actionable
  ) a
  WHERE sr.token = p_token::uuid;  -- explicit cast: text → uuid

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_sign_request_by_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sign_request_custom_text"("p_token" "text") RETURNS TABLE("custom_heading" "text", "custom_body" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT sr.custom_heading, sr.custom_body
  FROM public.sign_requests sr
  WHERE sr.token = p_token::uuid
    AND sr.doc_type = 'other'
    AND sr.status = 'pending'
    AND sr.expires_at > now();
$$;


ALTER FUNCTION "public"."get_sign_request_custom_text"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_speed_to_lead"("p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org   uuid;
  v_since timestamptz;
BEGIN
  v_org   := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_since := (SELECT MIN(moved_at) FROM lead_stage_history WHERE org_id = v_org);

  RETURN QUERY
  WITH first_move AS (
    SELECT lsh.lead_id, MIN(lsh.moved_at) AS first_moved_at
    FROM lead_stage_history lsh
    WHERE lsh.org_id = v_org
      AND lsh.moved_by IS NOT NULL
    GROUP BY lsh.lead_id
  ),
  gaps AS (
    SELECT EXTRACT(EPOCH FROM (fm.first_moved_at - COALESCE(il.occurred_at, il.created_at))) / 60.0 AS mins
    FROM first_move fm
    JOIN inbound_leads il ON il.id = fm.lead_id
    WHERE COALESCE(il.spam_flag, false) = false
      AND (p_start IS NULL OR public.mt_date(fm.first_moved_at) >= p_start)
      AND (p_end   IS NULL OR public.mt_date(fm.first_moved_at) <= p_end)
  ),
  binned AS (
    SELECT CASE
      WHEN GREATEST(mins, 0) <= 5 THEN 1
      WHEN mins <= 30            THEN 2
      WHEN mins <= 60            THEN 3
      WHEN mins <= 240           THEN 4
      WHEN mins <= 1440          THEN 5
      ELSE 6
    END AS b
    FROM gaps
  ),
  counts AS (SELECT b, COUNT(*) AS c FROM binned GROUP BY b),
  defs(sort_order, label, within_sla) AS (
    VALUES (1, '≤5 min', true), (2, '5–30 min', false), (3, '30–60 min', false),
           (4, '1–4 hr', false), (5, '4–24 hr', false), (6, '>24 hr', false)
  )
  SELECT json_build_object(
    'bucket',     defs.label,
    'sort_order', defs.sort_order,
    'within_sla', defs.within_sla,
    'count',      COALESCE(counts.c, 0),
    'data_since', v_since
  )
  FROM defs
  LEFT JOIN counts ON counts.b = defs.sort_order
  ORDER BY defs.sort_order;
END;
$$;


ALTER FUNCTION "public"."get_speed_to_lead"("p_start" "date", "p_end" "date", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_stalled_materials"("p_job_id" "uuid") RETURNS TABLE("room_id" "uuid", "room_name" "text", "material" "public"."material_type", "latest_mc" numeric, "latest_reading_at" timestamp with time zone, "mc_36h_ago" numeric, "drying_goal_pct" numeric, "days_stalled" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH latest_per_pair AS (
    SELECT DISTINCT ON (mr.room_id, mr.material)
           mr.id, mr.room_id, mr.material,
           mr.mc_pct AS latest_mc, mr.drying_goal_pct AS latest_goal,
           mr.taken_at AS latest_taken_at
      FROM moisture_readings mr
     WHERE mr.job_id = p_job_id
     ORDER BY mr.room_id, mr.material, mr.taken_at DESC
  ),
  prior_per_pair AS (
    SELECT lpp.id AS latest_id,
           (SELECT prior.mc_pct FROM moisture_readings prior
             WHERE prior.job_id = p_job_id
               AND prior.room_id IS NOT DISTINCT FROM lpp.room_id
               AND prior.material = lpp.material
               AND prior.id <> lpp.id
               AND prior.taken_at <= lpp.latest_taken_at - interval '36 hours'
               AND prior.mc_pct IS NOT NULL
             ORDER BY prior.taken_at DESC LIMIT 1) AS prior_mc,
           (SELECT prior.taken_at FROM moisture_readings prior
             WHERE prior.job_id = p_job_id
               AND prior.room_id IS NOT DISTINCT FROM lpp.room_id
               AND prior.material = lpp.material
               AND prior.id <> lpp.id
               AND prior.taken_at <= lpp.latest_taken_at - interval '36 hours'
               AND prior.mc_pct IS NOT NULL
             ORDER BY prior.taken_at DESC LIMIT 1) AS prior_taken_at
      FROM latest_per_pair lpp
  )
  SELECT lpp.room_id, r.name AS room_name, lpp.material,
         lpp.latest_mc, lpp.latest_taken_at AS latest_reading_at,
         ppp.prior_mc AS mc_36h_ago, lpp.latest_goal AS drying_goal_pct,
         EXTRACT(DAY FROM (lpp.latest_taken_at - ppp.prior_taken_at))::INT AS days_stalled
    FROM latest_per_pair lpp
    LEFT JOIN rooms r ON r.id = lpp.room_id
    LEFT JOIN prior_per_pair ppp ON ppp.latest_id = lpp.id
   WHERE lpp.latest_mc IS NOT NULL
     AND lpp.latest_goal IS NOT NULL
     AND lpp.latest_mc > lpp.latest_goal
     AND ppp.prior_mc IS NOT NULL
     AND (ppp.prior_mc - lpp.latest_mc) < 1.0
   ORDER BY lpp.latest_taken_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_stalled_materials"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_stalled_materials_for_employee"("p_employee_id" "uuid") RETURNS TABLE("job_id" "uuid", "job_number" "text", "appointment_id" "uuid", "appointment_date" "date", "room_id" "uuid", "room_name" "text", "material" "public"."material_type", "latest_mc" numeric, "latest_reading_at" timestamp with time zone, "mc_36h_ago" numeric, "drying_goal_pct" numeric, "days_stalled" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH emp_jobs AS (
    SELECT DISTINCT a.job_id,
                    (array_agg(a.id ORDER BY a.date DESC))[1] AS latest_appt_id,
                    max(a.date) AS latest_appt_date
      FROM appointments a
      JOIN appointment_crew ac ON ac.appointment_id = a.id
     WHERE ac.employee_id = p_employee_id
       AND a.job_id IS NOT NULL
       AND a.date >= (public.mt_today() - interval '30 days')
     GROUP BY a.job_id
  )
  SELECT
    ej.job_id,
    j.job_number,
    ej.latest_appt_id AS appointment_id,
    ej.latest_appt_date AS appointment_date,
    sm.room_id,
    sm.room_name,
    sm.material,
    sm.latest_mc,
    sm.latest_reading_at,
    sm.mc_36h_ago,
    sm.drying_goal_pct,
    sm.days_stalled
  FROM emp_jobs ej
  JOIN jobs j ON j.id = ej.job_id
  CROSS JOIN LATERAL get_stalled_materials(ej.job_id) AS sm
  ORDER BY sm.latest_reading_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_stalled_materials_for_employee"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_table_stats"("p_table" "text") RETURNS TABLE("row_count" bigint, "latest_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY EXECUTE format(
    'SELECT COUNT(*)::BIGINT, MAX(created_at) FROM %I', p_table
  );
END;
$$;


