CREATE OR REPLACE FUNCTION "public"."get_tasks_for_appointment"("p_appointment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', jt.id,
      'title', jt.title,
      'description', jt.description,
      'phase_name', jt.phase_name,
      'phase_color', jt.phase_color,
      'is_required', jt.is_required,
      'is_completed', jt.is_completed,
      'completed_by', jt.completed_by,
      'completed_at', jt.completed_at,
      'completed_by_name', e.display_name,
      'display_order', jt.display_order
    ) ORDER BY jt.phase_name, jt.display_order
  ), '[]'::jsonb) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.appointment_id = p_appointment_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_tasks_for_appointment"("p_appointment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tech_claims"("p_employee_id" "uuid") RETURNS TABLE("id" "uuid", "claim_number" "text", "insurance_claim_number" "text", "insurance_carrier" "text", "policy_number" "text", "date_of_loss" "date", "loss_type" "text", "loss_city" "text", "loss_state" "text", "loss_address" "text", "status" "text", "deductible" numeric, "created_at" timestamp with time zone, "last_activity_at" timestamp with time zone, "insured_name" "text", "client_phone" "text", "job_count" bigint, "primary_division" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    c.id, c.claim_number, c.insurance_claim_number, c.insurance_carrier,
    c.policy_number, c.date_of_loss, c.loss_type, c.loss_city, c.loss_state,
    c.loss_address, c.status, c.deductible, c.created_at,
    GREATEST(
      (SELECT MAX(a2.updated_at) FROM appointments a2 JOIN jobs jj ON jj.id = a2.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) AS last_activity_at,
    ct.name  AS insured_name,
    ct.phone AS client_phone,
    COUNT(DISTINCT j.id) AS job_count,
    (SELECT j2.division FROM jobs j2 WHERE j2.claim_id = c.id ORDER BY j2.created_at ASC LIMIT 1) AS primary_division
  FROM claims c
  JOIN jobs j ON j.claim_id = c.id
  JOIN appointments a ON a.job_id = j.id
  JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
  LEFT JOIN contacts ct ON ct.id = c.contact_id
  WHERE c.status IS DISTINCT FROM 'deleted'
  GROUP BY c.id, ct.name, ct.phone
  ORDER BY
    GREATEST(
      (SELECT MAX(a2.updated_at) FROM appointments a2 JOIN jobs jj ON jj.id = a2.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(d.created_at) FROM job_documents d JOIN jobs jj ON jj.id = d.job_id WHERE jj.claim_id = c.id),
      (SELECT MAX(se.created_at) FROM system_events se JOIN jobs jj ON jj.id = se.job_id WHERE jj.claim_id = c.id AND se.event_type NOT LIKE '%.created'),
      (SELECT MAX(te.updated_at) FROM job_time_entries te JOIN jobs jj ON jj.id = te.job_id WHERE jj.claim_id = c.id)
    ) DESC NULLS LAST,
    c.created_at DESC;
$$;


ALTER FUNCTION "public"."get_tech_claims"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tech_conversations"("p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_conversation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_limit  int  := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
  v_search text := NULLIF(btrim(COALESCE(p_search, '')), '');
  v_like   text;
  v_convs  jsonb;
  v_unread int;
  v_counts jsonb;
BEGIN
  IF v_search IS NOT NULL THEN
    v_like := '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  WITH base AS (
    SELECT c.*, COALESCE(c.last_message_at, c.created_at) AS sort_key
    FROM public.conversations c
    WHERE public.messaging_can_access_conversation(c.id)
  ),
  matched AS (
    SELECT b.* FROM base b
    WHERE
      (p_conversation_id IS NOT NULL AND b.id = p_conversation_id)
      OR (
        p_conversation_id IS NULL
        AND (
          p_status IS NULL OR p_status = 'all'
          OR (p_status = 'unread' AND b.unread_count > 0)
          OR (p_status NOT IN ('all', 'unread') AND b.status = p_status)
        )
        AND (
          v_like IS NULL
          OR b.title ILIKE v_like
          OR b.last_message_preview ILIKE v_like
          OR EXISTS (
            SELECT 1
            FROM public.conversation_participants cp
            LEFT JOIN public.contacts ct ON ct.id = cp.contact_id
            WHERE cp.conversation_id = b.id
              AND cp.is_active
              AND cp.removed_at IS NULL
              AND (cp.phone ILIKE v_like OR ct.name ILIKE v_like OR ct.phone ILIKE v_like)
          )
        )
        AND (
          p_before IS NULL
          OR b.sort_key < p_before
          OR (b.sort_key = p_before AND b.id < p_before_id)
        )
      )
  ),
  paged AS (
    SELECT * FROM matched
    ORDER BY sort_key DESC, id DESC
    LIMIT v_limit
  ),
  page_rows AS (
    SELECT
      p.sort_key,
      p.id,
      (to_jsonb(p) - 'email_reply_token') || jsonb_build_object(
        'conversation_participants',
        COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'contact_id', cp.contact_id,
              'phone',      cp.phone,
              'role',       cp.role,
              'contacts',   CASE WHEN ct.id IS NULL THEN NULL ELSE jsonb_build_object(
                'id', ct.id, 'name', ct.name, 'phone', ct.phone, 'email', ct.email,
                'company', ct.company, 'role', ct.role, 'dnd', ct.dnd, 'dnd_at', ct.dnd_at
              ) END
            )
            ORDER BY cp.added_at
          )
          FROM public.conversation_participants cp
          LEFT JOIN public.contacts ct ON ct.id = cp.contact_id
          WHERE cp.conversation_id = p.id
            AND cp.is_active
            AND cp.removed_at IS NULL
        ), '[]'::jsonb)
      ) AS row_json
    FROM paged p
  )
  SELECT COALESCE(jsonb_agg(row_json ORDER BY sort_key DESC, id DESC), '[]'::jsonb)
    INTO v_convs
  FROM page_rows;

  SELECT COALESCE(SUM(conversation.unread_count), 0)::int
    INTO v_unread
  FROM public.conversations conversation
  WHERE public.messaging_can_access_conversation(conversation.id);

  WITH scope AS (
    SELECT c.* FROM public.conversations c
    WHERE public.messaging_can_access_conversation(c.id)
      AND (
        v_like IS NULL
        OR c.title ILIKE v_like
        OR c.last_message_preview ILIKE v_like
        OR EXISTS (
          SELECT 1
          FROM public.conversation_participants cp
          LEFT JOIN public.contacts ct ON ct.id = cp.contact_id
          WHERE cp.conversation_id = c.id
            AND cp.is_active
            AND cp.removed_at IS NULL
            AND (cp.phone ILIKE v_like OR ct.name ILIKE v_like OR ct.phone ILIKE v_like)
        )
      )
  )
  SELECT jsonb_build_object(
    'all',               count(*),
    'unread',            count(*) FILTER (WHERE unread_count > 0),
    'needs_response',    count(*) FILTER (WHERE status = 'needs_response'),
    'waiting_on_client', count(*) FILTER (WHERE status = 'waiting_on_client'),
    'resolved',          count(*) FILTER (WHERE status = 'resolved')
  ) INTO v_counts
  FROM scope;

  RETURN jsonb_build_object(
    'conversations', COALESCE(v_convs, '[]'::jsonb),
    'unread_total',  COALESCE(v_unread, 0),
    'status_counts', v_counts
  );
END;
$$;


ALTER FUNCTION "public"."get_tech_conversations"("p_limit" integer, "p_before" timestamp with time zone, "p_before_id" "uuid", "p_search" "text", "p_status" "text", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tech_dashboard"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_now         timestamptz := now();
  v_today       date := (v_now AT TIME ZONE 'America/Denver')::date;
  v_week_start  date := (date_trunc('week', ((v_now AT TIME ZONE 'America/Denver')::date)::timestamp))::date;
  v_today_appts jsonb;
  v_upcoming    jsonb;
  v_open        job_time_entries%ROWTYPE;
  v_open_json   jsonb;
  v_photos      integer;
  v_hours_today jsonb;
  v_hours_week  jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'time_start')), '[]'::jsonb)
  INTO v_today_appts
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac2.id, 'employee_id', ac2.employee_id, 'role', ac2.role,
          'employees', jsonb_build_object('id', e2.id, 'display_name', e2.display_name, 'full_name', e2.full_name, 'color', e2.color, 'avatar_url', e2.avatar_url)
        ))
        FROM appointment_crew ac2 JOIN employees e2 ON e2.id = ac2.employee_id
        WHERE ac2.appointment_id = a.id
      ), '[]'::jsonb)
    ) AS row_data
    FROM appointments a
    JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date = v_today AND a.status <> 'cancelled'
  ) sub;

  SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'date'), (row_data->>'time_start')), '[]'::jsonb)
  INTO v_upcoming
  FROM (
    SELECT jsonb_build_object(
      'id', a.id, 'job_id', a.job_id, 'title', a.title, 'date', a.date,
      'time_start', a.time_start, 'time_end', a.time_end, 'type', a.type,
      'status', a.status, 'notes', a.notes,
      'color', a.color, 'kind', a.kind, 'duration_days', a.duration_days, 'is_milestone', a.is_milestone,
      'task_total', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id),
      'task_completed', (SELECT COUNT(*) FROM job_tasks jt WHERE jt.appointment_id = a.id AND jt.is_completed = true),
      'jobs', CASE WHEN j.id IS NOT NULL THEN jsonb_build_object(
        'id', j.id, 'job_number', j.job_number, 'insured_name', j.insured_name, 'address', j.address,
        'city', j.city, 'division', j.division, 'phase', j.phase, 'client_phone', j.client_phone
      ) ELSE NULL END,
      'appointment_crew', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', ac2.id, 'employee_id', ac2.employee_id, 'role', ac2.role,
          'employees', jsonb_build_object('id', e2.id, 'display_name', e2.display_name, 'full_name', e2.full_name, 'color', e2.color, 'avatar_url', e2.avatar_url)
        ))
        FROM appointment_crew ac2 JOIN employees e2 ON e2.id = ac2.employee_id
        WHERE ac2.appointment_id = a.id
      ), '[]'::jsonb)
    ) AS row_data
    FROM appointments a
    JOIN appointment_crew ac ON ac.appointment_id = a.id AND ac.employee_id = p_employee_id
    LEFT JOIN jobs j ON j.id = a.job_id
    WHERE a.date > v_today AND a.date <= v_today + 7 AND a.status <> 'cancelled'
  ) sub;

  SELECT * INTO v_open FROM job_time_entries
  WHERE employee_id = p_employee_id AND clock_out IS NULL
  ORDER BY created_at DESC LIMIT 1;
  v_open_json := CASE WHEN v_open.id IS NOT NULL THEN to_jsonb(v_open) ELSE NULL END;

  SELECT COUNT(*) INTO v_photos FROM job_documents d
  WHERE d.uploaded_by = p_employee_id AND d.category = 'photo'
    AND (d.created_at AT TIME ZONE 'America/Denver')::date = v_today;

  v_hours_today := tech_hours_bucket(p_employee_id, v_today, v_today, v_now, v_open);
  v_hours_week  := tech_hours_bucket(p_employee_id, v_week_start, v_today, v_now, v_open);

  RETURN jsonb_build_object(
    'server_now', v_now, 'today', v_today, 'week_start', v_week_start,
    'appointments', COALESCE(v_today_appts, '[]'::jsonb),
    'upcoming', COALESCE(v_upcoming, '[]'::jsonb),
    'open_entry', v_open_json,
    'hours_today', v_hours_today, 'hours_week', v_hours_week,
    'photos_today', COALESCE(v_photos, 0)
  );
END;
$$;


ALTER FUNCTION "public"."get_tech_dashboard"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tech_feedback"() RETURNS TABLE("id" "uuid", "employee_id" "uuid", "employee_name" "text", "type" "text", "title" "text", "description" "text", "screenshots" "jsonb", "status" "text", "admin_notes" "text", "created_at" timestamp with time zone, "attachments" "jsonb", "source" "text", "resolved_at" timestamp with time zone, "attachments_purged_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- New columns are appended: the live AdminFeedback.jsx caller reads JSON
  -- objects by key and simply ignores the extra keys.
  RETURN QUERY
    SELECT
      f.id, f.employee_id,
      e.full_name AS employee_name,
      f.type, f.title, f.description,
      f.screenshots, f.status, f.admin_notes,
      f.created_at,
      f.attachments, f.source, f.resolved_at, f.attachments_purged_at
    FROM tech_feedback f
    JOIN employees e ON e.id = f.employee_id
    ORDER BY f.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_tech_feedback"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tech_status_board"() RETURNS TABLE("employee_id" "uuid", "full_name" "text", "default_division" "text", "status" "text", "status_since" timestamp with time zone, "entry_id" "uuid", "appointment_id" "uuid", "appointment_title" "text", "job_id" "uuid", "job_number" "text", "client_name" "text", "address" "text", "division" "text", "next_appt_time" timestamp with time zone, "next_appt_title" "text", "travel_start" timestamp with time zone, "clock_in" timestamp with time zone, "paused_at" timestamp with time zone, "total_paused_minutes" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH open_entry AS (
    SELECT DISTINCT ON (jte.employee_id)
      jte.employee_id, jte.id AS entry_id, jte.appointment_id, jte.job_id,
      jte.travel_start, jte.clock_in, jte.paused_at, jte.total_paused_minutes
    FROM job_time_entries jte
    WHERE jte.clock_out IS NULL
      AND (jte.travel_start IS NOT NULL OR jte.clock_in IS NOT NULL)
    ORDER BY jte.employee_id, jte.created_at DESC
  ),
  today_appt AS (
    SELECT DISTINCT ON (ac.employee_id)
      ac.employee_id,
      a.id          AS appointment_id,
      a.title       AS appointment_title,
      a.job_id,
      ((a.date + a.time_start) AT TIME ZONE 'America/Denver') AS appt_ts
    FROM appointment_crew ac
    JOIN appointments a ON a.id = ac.appointment_id
    WHERE a.date = (NOW() AT TIME ZONE 'America/Denver')::date
    ORDER BY ac.employee_id,
      (((a.date + a.time_start) AT TIME ZONE 'America/Denver') >= NOW()) DESC,
      ((a.date + a.time_start) AT TIME ZONE 'America/Denver') ASC
  )
  SELECT
    e.id                                        AS employee_id,
    e.full_name,
    e.default_division,
    CASE
      WHEN oe.paused_at IS NOT NULL                THEN 'paused'
      WHEN oe.clock_in IS NOT NULL                 THEN 'on_site'
      WHEN oe.travel_start IS NOT NULL             THEN 'omw'
      WHEN ta.appointment_id IS NOT NULL           THEN 'scheduled'
      ELSE 'idle'
    END                                         AS status,
    CASE
      WHEN oe.paused_at IS NOT NULL    THEN oe.paused_at
      WHEN oe.clock_in IS NOT NULL     THEN oe.clock_in
      WHEN oe.travel_start IS NOT NULL THEN oe.travel_start
      ELSE NULL
    END                                         AS status_since,
    oe.entry_id,
    COALESCE(oe.appointment_id, ta.appointment_id)  AS appointment_id,
    COALESCE(a_open.title, ta.appointment_title)    AS appointment_title,
    COALESCE(oe.job_id, ta.job_id)                  AS job_id,
    j.job_number,
    j.insured_name                              AS client_name,
    NULLIF(CONCAT_WS(', ',
      NULLIF(j.address, ''),
      NULLIF(j.city, ''),
      NULLIF(j.state, '') || CASE WHEN j.zip IS NOT NULL AND j.zip <> '' THEN ' ' || j.zip ELSE '' END
    ), '')                                      AS address,
    j.division,
    CASE WHEN oe.entry_id IS NULL AND ta.appt_ts >= NOW() THEN ta.appt_ts ELSE NULL END AS next_appt_time,
    CASE WHEN oe.entry_id IS NULL AND ta.appt_ts >= NOW() THEN ta.appointment_title ELSE NULL END AS next_appt_title,
    oe.travel_start,
    oe.clock_in,
    oe.paused_at,
    oe.total_paused_minutes
  FROM employees e
  LEFT JOIN open_entry oe       ON oe.employee_id = e.id
  LEFT JOIN today_appt ta       ON ta.employee_id = e.id
  LEFT JOIN appointments a_open ON a_open.id = oe.appointment_id
  LEFT JOIN jobs j              ON j.id = COALESCE(oe.job_id, ta.job_id)
  WHERE e.is_active = TRUE
    AND (e.role IN ('field_tech', 'supervisor')
         OR e.show_on_status_board
         OR oe.entry_id IS NOT NULL
         OR ta.appointment_id IS NOT NULL)
  ORDER BY
    CASE
      WHEN oe.paused_at IS NOT NULL    THEN 1
      WHEN oe.clock_in IS NOT NULL     THEN 2
      WHEN oe.travel_start IS NOT NULL THEN 3
      WHEN ta.appointment_id IS NOT NULL THEN 4
      ELSE 5
    END,
    e.full_name;
$$;


ALTER FUNCTION "public"."get_tech_status_board"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_timesheet_entries"("p_start_date" "date" DEFAULT ("date_trunc"('week'::"text", ("public"."mt_today"())::timestamp with time zone))::"date", "p_end_date" "date" DEFAULT (("date_trunc"('week'::"text", ("public"."mt_today"())::timestamp with time zone) + '6 days'::interval))::"date", "p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "job_id" "uuid", "employee_id" "uuid", "employee_name" "text", "job_number" "text", "insured_name" "text", "division" "text", "work_date" "date", "hours" numeric, "hourly_rate" numeric, "total_cost" numeric, "work_type" "text", "description" "text", "approved" boolean, "approved_by" "uuid", "clock_in" timestamp with time zone, "clock_out" timestamp with time zone, "appointment_id" "uuid", "notes" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    t.id,
    t.job_id,
    t.employee_id,
    e.full_name AS employee_name,
    j.job_number,
    j.insured_name,
    j.division,
    t.work_date,
    t.hours,
    t.hourly_rate,
    t.total_cost,
    t.work_type,
    t.description,
    t.approved,
    t.approved_by,
    t.clock_in,
    t.clock_out,
    t.appointment_id,
    t.notes,
    t.created_at
  FROM job_time_entries t
  JOIN employees e ON e.id = t.employee_id
  JOIN jobs j ON j.id = t.job_id
  WHERE t.work_date BETWEEN p_start_date AND p_end_date
    AND (p_employee_id IS NULL OR t.employee_id = p_employee_id)
  ORDER BY t.work_date DESC, e.full_name, t.clock_in;
$$;


ALTER FUNCTION "public"."get_timesheet_entries"("p_start_date" "date", "p_end_date" "date", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_timesheet_entries_admin"("p_start_date" "date" DEFAULT ("date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone))::"date", "p_end_date" "date" DEFAULT (("date_trunc"('week'::"text", (CURRENT_DATE)::timestamp with time zone) + '6 days'::interval))::"date", "p_employee_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_division" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "job_id" "uuid", "employee_id" "uuid", "employee_name" "text", "job_number" "text", "insured_name" "text", "division" "text", "work_date" "date", "hours" numeric, "hourly_rate" numeric, "total_cost" numeric, "work_type" "text", "description" "text", "approved" boolean, "approved_by" "uuid", "travel_start" timestamp with time zone, "clock_in" timestamp with time zone, "on_site_end" timestamp with time zone, "clock_out" timestamp with time zone, "travel_minutes" numeric, "total_paused_minutes" numeric, "auto_continued" boolean, "appointment_id" "uuid", "notes" "text", "created_at" timestamp with time zone, "duration_minutes" numeric, "is_open" boolean, "is_overlong" boolean, "has_pending_change" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  select * from (
    select t.id, t.job_id, t.employee_id, e.full_name as employee_name, j.job_number, j.insured_name, j.division::text as division,
      t.work_date, t.hours, t.hourly_rate, t.total_cost, t.work_type, t.description, t.approved, t.approved_by,
      t.travel_start, t.clock_in, t.on_site_end, t.clock_out, t.travel_minutes, t.total_paused_minutes, t.auto_continued,
      t.appointment_id, t.notes, t.created_at,
      round(coalesce(t.travel_minutes, 0) + coalesce(t.hours, 0) * 60, 1) as duration_minutes,
      (t.clock_out is null and t.travel_start is not null) as is_open,
      ((coalesce(t.hours, 0) + coalesce(t.travel_minutes, 0) / 60.0) > 12) as is_overlong,
      exists (select 1 from time_entry_change_requests cr where cr.entry_id = t.id and cr.status = 'pending') as has_pending_change
    from job_time_entries t join employees e on e.id = t.employee_id join jobs j on j.id = t.job_id
    where t.work_date between p_start_date and p_end_date
      and (p_employee_id is null or t.employee_id = p_employee_id) and (p_job_id is null or t.job_id = p_job_id)
      and (p_division is null or j.division::text = p_division)
  ) q
  where (p_status is null or (p_status='open' and q.is_open) or (p_status='approved' and q.approved)
    or (p_status='unapproved' and not coalesce(q.approved,false)) or (p_status='overlong' and q.is_overlong))
  order by q.work_date desc, q.employee_name, q.clock_in;
$$;


ALTER FUNCTION "public"."get_timesheet_entries_admin"("p_start_date" "date", "p_end_date" "date", "p_employee_id" "uuid", "p_job_id" "uuid", "p_status" "text", "p_division" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_tracking_numbers"() RETURNS TABLE("tracking_number" "text", "label" "text", "call_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT il.tracking_number, tn.label, count(*) AS call_count
  FROM inbound_leads il
  LEFT JOIN crm_tracking_numbers tn ON tn.tracking_number = il.tracking_number
  WHERE il.tracking_number IS NOT NULL
  GROUP BY il.tracking_number, tn.label
  ORDER BY count(*) DESC;
$$;


ALTER FUNCTION "public"."get_tracking_numbers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unassigned_tasks"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(phase_group ORDER BY phase_group->>'phase_name'), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'phase_name', jt.phase_name,
      'phase_color', jt.phase_color,
      'tasks', jsonb_agg(
        jsonb_build_object(
          'id', jt.id,
          'title', jt.title,
          'description', jt.description,
          'is_required', jt.is_required,
          'display_order', jt.display_order
        ) ORDER BY jt.display_order
      )
    ) as phase_group
    FROM job_tasks jt
    WHERE jt.job_id = p_job_id
      AND jt.appointment_id IS NULL
      AND jt.is_completed = false
    GROUP BY jt.phase_name, jt.phase_color
  ) sub;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_unassigned_tasks"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unread_notification_count"("p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  IF v_is_service_role THEN
    RETURN (
      SELECT count(*)::integer
      FROM public.notifications notification
      WHERE notification.read_at IS NULL
        AND (
          notification.recipient_id IS NULL
          OR notification.recipient_id = p_employee_id
        )
    );
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active = true
    AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NOT NULL AND p_employee_id <> v_actor THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;

  RETURN (
    SELECT count(*)::integer
    FROM public.notifications notification
    LEFT JOIN public.notification_reads receipt
      ON receipt.notification_id = notification.id
     AND receipt.employee_id = v_actor
     AND notification.recipient_id IS NULL
    WHERE (
            notification.recipient_id IS NULL
            OR notification.recipient_id = p_employee_id
          )
      AND CASE
            WHEN notification.recipient_id IS NULL
              THEN COALESCE(notification.read_at, receipt.read_at)
            ELSE notification.read_at
          END IS NULL
  );
END;
$$;


ALTER FUNCTION "public"."get_unread_notification_count"("p_employee_id" "uuid") OWNER TO "postgres";


