CREATE OR REPLACE FUNCTION "public"."global_search"("p_term" "text", "p_limit" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH q AS (SELECT '%' || trim(p_term) || '%' AS like_term)
  SELECT jsonb_build_object(
    'customers', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT c.id,
               c.name AS title,
               NULLIF(concat_ws(' · ', NULLIF(c.company::text,''), NULLIF(c.phone::text,''), NULLIF(c.role::text,'')), '') AS subtitle
        FROM contacts c, q
        WHERE c.name ILIKE q.like_term OR c.phone ILIKE q.like_term
           OR c.email ILIKE q.like_term OR c.company ILIKE q.like_term
        ORDER BY c.name
        LIMIT p_limit
      ) x
    ), '[]'::jsonb),
    'claims', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT cl.id,
               COALESCE(NULLIF(cl.claim_number::text,''), 'Claim') AS title,
               NULLIF(concat_ws(' · ', NULLIF(ct.name::text,''), NULLIF(cl.loss_city::text,''), NULLIF(cl.insurance_carrier::text,'')), '') AS subtitle
        FROM claims cl
        LEFT JOIN contacts ct ON ct.id = cl.contact_id, q
        WHERE cl.claim_number ILIKE q.like_term OR cl.insurance_claim_number ILIKE q.like_term
           OR cl.loss_address ILIKE q.like_term OR cl.loss_city ILIKE q.like_term
           OR ct.name ILIKE q.like_term
        ORDER BY cl.created_at DESC
        LIMIT p_limit
      ) x
    ), '[]'::jsonb),
    'jobs', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT j.id,
               COALESCE(NULLIF(j.job_number::text,''), 'Job') AS title,
               NULLIF(concat_ws(' · ', NULLIF(j.insured_name::text,''), NULLIF(j.division::text,''), NULLIF(j.address::text,'')), '') AS subtitle
        FROM jobs j, q
        WHERE j.job_number ILIKE q.like_term OR j.insured_name ILIKE q.like_term
           OR j.address ILIKE q.like_term OR j.claim_number ILIKE q.like_term
        ORDER BY j.created_at DESC
        LIMIT p_limit
      ) x
    ), '[]'::jsonb),
    'invoices', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT iv.id,
               COALESCE(NULLIF(iv.qbo_doc_number::text,''), NULLIF(iv.invoice_number::text,''), 'Invoice') AS title,
               NULLIF(concat_ws(' · ', NULLIF(ct.name::text,''), NULLIF(iv.billed_to::text,''),
                      '$' || to_char(COALESCE(iv.adjusted_total, iv.total, 0), 'FM999,999,990.00')), '') AS subtitle
        FROM invoices iv
        LEFT JOIN contacts ct ON ct.id = iv.contact_id, q
        WHERE iv.invoice_number ILIKE q.like_term OR iv.qbo_doc_number ILIKE q.like_term
           OR iv.qbo_invoice_id ILIKE q.like_term
           OR iv.claim_number ILIKE q.like_term OR iv.billed_to ILIKE q.like_term
           OR ct.name ILIKE q.like_term
        ORDER BY iv.created_at DESC
        LIMIT p_limit
      ) x
    ), '[]'::jsonb),
    'payments', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT p.id, p.invoice_id, p.job_id,
               concat_ws(' ', COALESCE(NULLIF(p.payer_name::text,''), 'Payment'),
                         '· $' || to_char(COALESCE(p.amount,0), 'FM999,999,990.00')) AS title,
               NULLIF(concat_ws(' · ', NULLIF(p.payment_method::text,''), NULLIF(p.reference_number::text,''),
                      to_char(p.payment_date, 'Mon DD, YYYY')), '') AS subtitle
        FROM payments p, q
        WHERE p.payer_name ILIKE q.like_term OR p.reference_number ILIKE q.like_term
           OR p.amount::text ILIKE q.like_term
        ORDER BY p.payment_date DESC NULLS LAST
        LIMIT p_limit
      ) x
    ), '[]'::jsonb),
    'estimates', '[]'::jsonb
  );
$_$;


ALTER FUNCTION "public"."global_search"("p_term" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_appointment_command_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
BEGIN
  IF public.is_trusted_appointment_command_caller() THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  v_actor_id :=
    public.current_active_internal_appointment_employee();
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal appointment employee required'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.created_by IS NOT NULL
       AND NEW.created_by IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment creator does not match caller'
        USING ERRCODE = '42501';
    END IF;
    NEW.created_by := v_actor_id;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.kind IS DISTINCT FROM OLD.kind
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment identity is immutable'
        USING ERRCODE = '42501';
    END IF;

    IF NEW.is_private IS DISTINCT FROM OLD.is_private
       AND NOT public.can_current_employee_manage_appointment_privacy() THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment privacy manager required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_appointment_command_write"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_appointment_command_write"() IS 'UPR appointment crew atomic save/audit repair v1: trigger-only browser actor, identity, and privacy guard';



CREATE OR REPLACE FUNCTION "public"."guard_estimate_line_during_qbo_command"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE old_estimate_id uuid; new_estimate_id uuid; finalizer_id text;
BEGIN
 old_estimate_id:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.estimate_id END;
 new_estimate_id:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE NEW.estimate_id END;
 finalizer_id:=current_setting('upr.qbo_estimate_finalizer_command_id',true);
 IF auth.role() IS NOT DISTINCT FROM 'service_role'
    AND finalizer_id IS NOT NULL
    AND (old_estimate_id IS NULL OR new_estimate_id IS NULL OR old_estimate_id=new_estimate_id)
    AND EXISTS(SELECT 1 FROM public.qbo_estimate_commands c JOIN public.qbo_estimate_command_reservations r ON r.command_id=c.id AND r.estimate_id=c.estimate_id WHERE c.id::text=finalizer_id AND c.estimate_id=COALESCE(new_estimate_id,old_estimate_id) AND c.status='provider_succeeded') THEN
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END IF;
 -- A line reassignment touches both documents. Lock both parent rows in UUID
 -- order so it cannot move a line out of (or into) an active command fence.
 PERFORM 1 FROM public.estimates
  WHERE id IN (old_estimate_id,new_estimate_id)
  ORDER BY id
  FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.qbo_estimate_command_reservations WHERE estimate_id IN (old_estimate_id,new_estimate_id))
 OR EXISTS(SELECT 1 FROM public.qbo_estimate_commands WHERE estimate_id IN (old_estimate_id,new_estimate_id) AND status IN ('prepared','provider_started','ambiguous','provider_succeeded','needs_reconciliation')) THEN
  RAISE EXCEPTION 'ESTIMATE_QBO_COMMAND_ACTIVE' USING ERRCODE='55000';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;$$;


ALTER FUNCTION "public"."guard_estimate_line_during_qbo_command"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_estimate_transition_during_qbo_command"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE finalizer_id text;
BEGIN
 finalizer_id:=current_setting('upr.qbo_estimate_finalizer_command_id',true);
 IF auth.role() IS NOT DISTINCT FROM 'service_role'
    AND finalizer_id IS NOT NULL
    AND EXISTS(SELECT 1 FROM public.qbo_estimate_commands c JOIN public.qbo_estimate_command_reservations r ON r.command_id=c.id AND r.estimate_id=c.estimate_id WHERE c.id::text=finalizer_id AND c.estimate_id=NEW.id AND c.status='provider_succeeded') THEN
  RETURN NEW;
 END IF;
 IF EXISTS(SELECT 1 FROM public.qbo_estimate_command_reservations WHERE estimate_id=NEW.id)
 OR EXISTS(SELECT 1 FROM public.qbo_estimate_commands WHERE estimate_id=NEW.id AND status IN ('prepared','provider_started','ambiguous','provider_succeeded','needs_reconciliation')) THEN
  RAISE EXCEPTION 'ESTIMATE_QBO_COMMAND_ACTIVE' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END;$$;


ALTER FUNCTION "public"."guard_estimate_transition_during_qbo_command"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_invoice_line_write_during_qbo_command"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_invoice_id uuid;
  v_invoice_ids uuid[];
  v_locked boolean;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_invoice_ids := ARRAY[NEW.invoice_id];
  ELSIF TG_OP = 'DELETE' THEN
    v_invoice_ids := ARRAY[OLD.invoice_id];
  ELSE
    v_invoice_ids := ARRAY[OLD.invoice_id, NEW.invoice_id];
  END IF;

  FOR v_invoice_id IN
    SELECT DISTINCT candidate
    FROM unnest(v_invoice_ids) AS candidate
    WHERE candidate IS NOT NULL
    ORDER BY candidate
  LOOP
    SELECT i.locked INTO v_locked
    FROM public.invoices i
    WHERE i.id = v_invoice_id
    FOR UPDATE;
    IF NOT FOUND OR v_locked IS TRUE THEN
      RAISE EXCEPTION 'INVOICE_QBO_WRITE_FENCED: invoice is missing or locked'
        USING ERRCODE = '55000';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.qbo_invoice_command_reservations r
      WHERE r.invoice_id = v_invoice_id
    ) OR EXISTS (
      SELECT 1 FROM public.qbo_invoice_commands c
      WHERE c.invoice_id = v_invoice_id
        AND c.status IN (
          'prepared', 'provider_started', 'ambiguous',
          'provider_succeeded', 'needs_reconciliation'
        )
    ) THEN
      RAISE EXCEPTION 'INVOICE_QBO_COMMAND_ACTIVE: resolve the QuickBooks command before editing invoice lines'
        USING ERRCODE = '55000';
    END IF;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."guard_invoice_line_write_during_qbo_command"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_invoice_lock_during_qbo_command"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.locked IS TRUE AND OLD.locked IS FALSE THEN
    IF EXISTS (SELECT 1 FROM public.qbo_invoice_command_reservations r WHERE r.invoice_id = NEW.id) THEN
      RAISE EXCEPTION 'INVOICE_QBO_COMMAND_ACTIVE: resolve the QuickBooks command before locking this invoice'
        USING ERRCODE = '55000';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.qbo_invoice_commands c
      WHERE c.invoice_id = NEW.id
        AND c.status IN ('prepared', 'provider_started', 'ambiguous', 'provider_succeeded', 'needs_reconciliation')
    ) THEN
      RAISE EXCEPTION 'INVOICE_QBO_COMMAND_ACTIVE: resolve the QuickBooks command before locking this invoice'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_invoice_lock_during_qbo_command"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_invoice_lock_during_qbo_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.locked IS TRUE AND OLD.locked IS FALSE AND (
    EXISTS (
      SELECT 1
      FROM public.qbo_payment_allocation_fences f
      JOIN public.payment_receipt_attempts a ON a.id = f.attempt_id
      WHERE f.invoice_id = NEW.id
        AND a.status IN ('submitting', 'qbo_created', 'unknown_outcome')
    )
    OR EXISTS (
      SELECT 1
      FROM public.payment_receipt_attempts a
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(a.request_payload->'allocations', '[]'::jsonb)) allocation(value)
      WHERE a.status IN ('submitting', 'qbo_created', 'unknown_outcome')
        AND NULLIF(allocation.value->>'invoice_id', '')::uuid = NEW.id
    )
  ) THEN
    RAISE EXCEPTION 'INVOICE_PAYMENT_ALLOCATION_IN_FLIGHT' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_invoice_lock_during_qbo_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_payment_receipt_invoice_unlocked"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_locked boolean;
BEGIN
  IF NEW.receipt_id IS NOT NULL THEN
    SELECT i.locked INTO v_locked
    FROM public.invoices i
    WHERE i.id = NEW.invoice_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ALLOCATION_INVOICE_MISMATCH' USING ERRCODE = '23514';
    END IF;
    IF v_locked IS TRUE THEN
      RAISE EXCEPTION 'INVOICE_LOCKED_DURING_PAYMENT_FINALIZATION' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


