BEGIN
  IF (TG_OP = 'INSERT' AND NEW.receipt_id IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND NEW.receipt_id IS DISTINCT FROM OLD.receipt_id) THEN
    IF auth.role() <> 'service_role' THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
    END IF;
