CREATE OR REPLACE FUNCTION "public"."guard_qbo_realm_binding"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_binding public.qbo_company_binding%ROWTYPE;
  v_realm_id text := NULLIF(pg_catalog.btrim(pg_catalog.to_jsonb(NEW)->>TG_ARGV[0]), '');
  v_old_realm_id text := CASE
    WHEN TG_OP = 'INSERT' THEN NULL
    ELSE NULLIF(pg_catalog.btrim(pg_catalog.to_jsonb(OLD)->>TG_ARGV[0]), '')
  END;
  v_new_identity text := CASE
    WHEN COALESCE(TG_ARGV[2], '') = '' THEN NULL
    ELSE NULLIF(pg_catalog.btrim(pg_catalog.to_jsonb(NEW)->>TG_ARGV[2]), '')
  END;
  v_old_identity text := CASE
    WHEN TG_OP = 'INSERT' OR COALESCE(TG_ARGV[2], '') = '' THEN NULL
    ELSE NULLIF(pg_catalog.btrim(pg_catalog.to_jsonb(OLD)->>TG_ARGV[2]), '')
  END;
  v_new_secondary_identity text := CASE
    WHEN COALESCE(TG_ARGV[3], '') = '' THEN NULL
    ELSE NULLIF(pg_catalog.btrim(pg_catalog.to_jsonb(NEW)->>TG_ARGV[3]), '')
  END;
  v_old_secondary_identity text := CASE
    WHEN TG_OP = 'INSERT' OR COALESCE(TG_ARGV[3], '') = '' THEN NULL
    ELSE NULLIF(pg_catalog.btrim(pg_catalog.to_jsonb(OLD)->>TG_ARGV[3]), '')
  END;
BEGIN
  -- Do not turn ordinary browser-created manual payments or legacy projection
  -- rows into QBO writes. This compatibility exit is deliberately before the
  -- service-role/binding checks; any QBO identity, required ledger surface, or
  -- attempt to erase an existing realm continues through the fail-closed path.
  IF v_realm_id IS NULL
     AND v_old_realm_id IS NULL
     AND v_new_identity IS NULL
     AND v_old_identity IS NULL
     AND v_new_secondary_identity IS NULL
     AND v_old_secondary_identity IS NULL
     AND TG_ARGV[1] = 'nullable' THEN
    RETURN NEW;
  END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'QBO_REALM_WRITE_REQUIRES_SERVICE_ROLE' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_binding FROM public.qbo_company_binding WHERE singleton;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'QBO_BINDING_REQUIRED' USING ERRCODE = '55000';
  END IF;
  IF v_realm_id IS NULL THEN
    RAISE EXCEPTION 'QBO_REALM_BINDING_REQUIRED' USING ERRCODE = '55000';
  END IF;
  IF v_realm_id IS DISTINCT FROM v_binding.realm_id THEN
    RAISE EXCEPTION 'QBO_COMPANY_BINDING_MISMATCH' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_qbo_realm_binding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_quickbooks_company_binding"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_binding public.qbo_company_binding%ROWTYPE;
  v_environment text;
  v_realm_id text;
  v_writer_generation text;
  v_protected_write boolean;
BEGIN
  IF NEW.provider IS DISTINCT FROM 'quickbooks' THEN
    RETURN NEW;
  END IF;
  v_environment := pg_catalog.lower(pg_catalog.btrim(COALESCE(NEW.environment, 'production')));
  v_realm_id := NULLIF(pg_catalog.btrim(NEW.realm_id), '');
  SELECT * INTO v_binding FROM public.qbo_company_binding WHERE singleton;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'QBO_BINDING_REQUIRED' USING ERRCODE = '55000';
  END IF;
  IF v_realm_id IS NULL
     OR v_environment IS DISTINCT FROM v_binding.environment
     OR v_realm_id IS DISTINCT FROM v_binding.realm_id THEN
    RAISE EXCEPTION 'QBO_COMPANY_BINDING_MISMATCH' USING ERRCODE = '55000';
  END IF;
  v_writer_generation := NULLIF(
    current_setting('upr.qbo_connection_writer_generation', true),
    ''
  );
  IF TG_OP = 'INSERT' THEN
    v_protected_write := true;
  ELSE
    v_protected_write := OLD.access_token IS DISTINCT FROM NEW.access_token
      OR OLD.refresh_token IS DISTINCT FROM NEW.refresh_token
      OR OLD.token_expires_at IS DISTINCT FROM NEW.token_expires_at
      OR OLD.granted_scopes IS DISTINCT FROM NEW.granted_scopes
      OR OLD.realm_id IS DISTINCT FROM NEW.realm_id
      OR OLD.environment IS DISTINCT FROM NEW.environment
      OR OLD.qbo_binding_generation IS DISTINCT FROM NEW.qbo_binding_generation;
  END IF;
  IF v_protected_write
     AND (
       auth.role() IS DISTINCT FROM 'service_role'
       OR v_writer_generation IS DISTINCT FROM v_binding.generation::text
     ) THEN
    RAISE EXCEPTION 'QBO_CONNECTION_WRITE_REQUIRES_CAS' USING ERRCODE = '55000';
  END IF;
  NEW.environment := v_binding.environment;
  NEW.realm_id := v_binding.realm_id;
  NEW.qbo_binding_generation := v_binding.generation;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_quickbooks_company_binding"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."crm_import_batches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "filename" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "total_rows" integer DEFAULT 0 NOT NULL,
    "created_count" integer DEFAULT 0 NOT NULL,
    "updated_count" integer DEFAULT 0 NOT NULL,
    "skipped_count" integer DEFAULT 0 NOT NULL,
    "error_count" integer DEFAULT 0 NOT NULL,
    "errors" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "crm_import_batches_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'complete'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."crm_import_batches" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_contacts"("p_rows" "jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_filename" "text" DEFAULT NULL::"text") RETURNS "public"."crm_import_batches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id       uuid;
  v_batch        crm_import_batches;
  v_row          jsonb;
  v_idx          int  := 0;
  v_total        int  := 0;
  v_created      int  := 0;
  v_updated      int  := 0;
  v_skipped      int  := 0;
  v_errored      int  := 0;
  v_errors       jsonb := '[]'::jsonb;
  v_phone_digits text;
  v_phone_key    text;
  v_email_raw    text;
  v_email_key    text;
  v_existing     uuid;
  v_owner        uuid;
  v_tags         jsonb;
BEGIN
  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'import_contacts: p_rows must be a JSON array';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_idx   := v_idx + 1;
    v_total := v_total + 1;
    BEGIN
      v_phone_digits := regexp_replace(COALESCE(v_row->>'phone', ''), '[^0-9]', '', 'g');
      v_phone_key    := CASE WHEN length(v_phone_digits) >= 10 THEN right(v_phone_digits, 10) ELSE NULL END;
      v_email_raw    := NULLIF(btrim(COALESCE(v_row->>'email', '')), '');
      v_email_key    := lower(v_email_raw);

      IF v_phone_key IS NULL AND v_email_key IS NULL THEN
        v_skipped := v_skipped + 1;
        v_errors  := v_errors || jsonb_build_object('row', v_idx, 'reason', 'no phone or email');
        CONTINUE;
      END IF;

      v_owner := NULL;
      IF NULLIF(btrim(COALESCE(v_row->>'owner_id', '')), '') IS NOT NULL THEN
        BEGIN v_owner := (v_row->>'owner_id')::uuid; EXCEPTION WHEN others THEN v_owner := NULL; END;
      END IF;
      v_tags := CASE WHEN jsonb_typeof(v_row->'tags') = 'array' THEN v_row->'tags' ELSE NULL END;

      SELECT id INTO v_existing FROM contacts
      WHERE (v_phone_key IS NOT NULL
              AND length(regexp_replace(COALESCE(phone, ''), '[^0-9]', '', 'g')) >= 10
              AND right(regexp_replace(COALESCE(phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key)
         OR (v_email_key IS NOT NULL AND lower(btrim(COALESCE(email, ''))) = v_email_key)
      ORDER BY created_at
      LIMIT 1;

      IF v_existing IS NOT NULL THEN
        UPDATE contacts SET
          name             = COALESCE(name, NULLIF(btrim(COALESCE(v_row->>'name', '')), '')),
          email            = COALESCE(NULLIF(btrim(COALESCE(email, '')), ''), v_email_raw),
          phone            = COALESCE(NULLIF(btrim(COALESCE(phone, '')), ''), NULLIF(btrim(COALESCE(v_row->>'phone', '')), '')),
          company          = COALESCE(company, NULLIF(btrim(COALESCE(v_row->>'company', '')), '')),
          role             = COALESCE(role, NULLIF(btrim(COALESCE(v_row->>'role', '')), '')),
          referral_source  = COALESCE(referral_source, NULLIF(btrim(COALESCE(v_row->>'referral_source', '')), '')),
          notes            = COALESCE(notes, NULLIF(btrim(COALESCE(v_row->>'notes', '')), '')),
          billing_address  = COALESCE(billing_address, NULLIF(btrim(COALESCE(v_row->>'billing_address', '')), '')),
          billing_city     = COALESCE(billing_city, NULLIF(btrim(COALESCE(v_row->>'billing_city', '')), '')),
          billing_state    = COALESCE(billing_state, NULLIF(btrim(COALESCE(v_row->>'billing_state', '')), '')),
          billing_zip      = COALESCE(billing_zip, NULLIF(btrim(COALESCE(v_row->>'billing_zip', '')), '')),
          phone_secondary  = COALESCE(phone_secondary, NULLIF(btrim(COALESCE(v_row->>'phone_secondary', '')), '')),
          lifecycle_status = COALESCE(lifecycle_status, NULLIF(btrim(COALESCE(v_row->>'lifecycle_status', '')), '')),
          owner_id         = COALESCE(owner_id, v_owner),
          tags             = COALESCE(tags, v_tags),
          updated_at       = now()
        WHERE id = v_existing;
        v_updated := v_updated + 1;
      ELSE
        INSERT INTO contacts (
          name, email, phone, company, role, referral_source, notes,
          billing_address, billing_city, billing_state, billing_zip, phone_secondary,
          lifecycle_status, owner_id, tags)
        VALUES (
          NULLIF(btrim(COALESCE(v_row->>'name', '')), ''),
          v_email_raw,
          NULLIF(btrim(COALESCE(v_row->>'phone', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'company', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'role', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'referral_source', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'notes', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'billing_address', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'billing_city', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'billing_state', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'billing_zip', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'phone_secondary', '')), ''),
          NULLIF(btrim(COALESCE(v_row->>'lifecycle_status', '')), ''),
          v_owner,
          v_tags);
        v_created := v_created + 1;
      END IF;
    EXCEPTION WHEN others THEN
      v_errored := v_errored + 1;
      v_errors  := v_errors || jsonb_build_object('row', v_idx, 'reason', SQLERRM);
    END;
  END LOOP;

  INSERT INTO crm_import_batches (
    org_id, filename, status, total_rows, created_count, updated_count,
    skipped_count, error_count, errors, created_by, completed_at)
  VALUES (
    v_org_id, p_filename, 'complete', v_total, v_created, v_updated,
    v_skipped, v_errored, v_errors, p_created_by, now())
  RETURNING * INTO v_batch;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_contacts_imported', 'crm_import_batch', v_batch.id, p_created_by,
    jsonb_build_object(
      'total', v_total, 'created', v_created, 'updated', v_updated,
      'skipped', v_skipped, 'errors', v_errored, 'filename', p_filename));

  RETURN v_batch;
END;
$$;


