CREATE OR REPLACE FUNCTION "public"."increment_conversation_unread"("p_conversation_id" "uuid", "p_by" integer DEFAULT 1) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new integer;
BEGIN
  UPDATE public.conversations
     SET unread_count = GREATEST(0, unread_count + COALESCE(p_by, 1))
   WHERE id = p_conversation_id
  RETURNING unread_count INTO v_new;
  RETURN v_new;
END;
$$;


