CREATE OR REPLACE FUNCTION "public"."insert_reading"("p_job_id" "uuid", "p_room_id" "uuid", "p_material" "public"."material_type", "p_location" "text", "p_mc" numeric, "p_rh" numeric, "p_temp_f" numeric, "p_gpp" numeric, "p_dew_point" numeric, "p_is_affected" boolean, "p_equipment_id" "uuid", "p_taken_by" "uuid", "p_notes" "text", "p_client_id" "uuid", "p_taken_at" timestamp with time zone DEFAULT "now"()) RETURNS "public"."moisture_readings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_existing_standard NUMERIC;
  v_existing_goal     NUMERIC;
  v_dry_standard      NUMERIC;
  v_drying_goal       NUMERIC;
  result              moisture_readings;
BEGIN
  SELECT mr.dry_standard_pct, mr.drying_goal_pct
    INTO v_existing_standard, v_existing_goal
    FROM moisture_readings mr
   WHERE mr.job_id = p_job_id AND mr.material = p_material
     AND mr.dry_standard_pct IS NOT NULL
   ORDER BY mr.taken_at ASC LIMIT 1;

  IF p_is_affected = false AND v_existing_standard IS NULL AND p_mc IS NOT NULL THEN
    v_dry_standard := p_mc;
    v_drying_goal  := p_mc + 2;
  ELSIF v_existing_standard IS NOT NULL THEN
    v_dry_standard := v_existing_standard;
    v_drying_goal  := COALESCE(v_existing_goal, v_existing_standard + 2);
  ELSE
    v_dry_standard := NULL;
    v_drying_goal  := NULL;
  END IF;

  INSERT INTO moisture_readings (
    job_id, room_id, equipment_id, material, location_description,
    mc_pct, rh_pct, temp_f, gpp, dew_point_f,
    dry_standard_pct, drying_goal_pct,
    is_affected, taken_by, taken_at, notes, client_id
  )
  VALUES (
    p_job_id, p_room_id, p_equipment_id, p_material, p_location,
    p_mc, p_rh, p_temp_f, p_gpp, p_dew_point,
    v_dry_standard, v_drying_goal,
    p_is_affected, p_taken_by, p_taken_at, p_notes, p_client_id
  )
  ON CONFLICT (client_id) DO UPDATE
    SET room_id=EXCLUDED.room_id, equipment_id=EXCLUDED.equipment_id,
        material=EXCLUDED.material, location_description=EXCLUDED.location_description,
        mc_pct=EXCLUDED.mc_pct, rh_pct=EXCLUDED.rh_pct, temp_f=EXCLUDED.temp_f,
        gpp=EXCLUDED.gpp, dew_point_f=EXCLUDED.dew_point_f,
        dry_standard_pct=EXCLUDED.dry_standard_pct, drying_goal_pct=EXCLUDED.drying_goal_pct,
        is_affected=EXCLUDED.is_affected, notes=EXCLUDED.notes
  RETURNING * INTO result;

  IF p_is_affected = false AND v_existing_standard IS NULL AND v_dry_standard IS NOT NULL THEN
    UPDATE moisture_readings
       SET dry_standard_pct = v_dry_standard, drying_goal_pct = v_drying_goal
     WHERE job_id = p_job_id AND material = p_material
       AND dry_standard_pct IS NULL AND id <> result.id;
  END IF;

  RETURN result;
END;
$$;


