CREATE OR REPLACE FUNCTION "public"."leave_conversation"("p_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.employees%ROWTYPE;
  v_already_left boolean;
BEGIN
  SELECT employee.*
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active
    AND NOT employee.is_external
  LIMIT 1;

  IF NOT FOUND
     OR v_actor.role::text IN (
       'admin', 'office', 'project_manager', 'supervisor', 'crm_partner'
     ) THEN
    RAISE EXCEPTION 'this role cannot leave a conversation'
      USING ERRCODE = '42501';
  END IF;

  IF p_conversation_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.conversations conversation
       WHERE conversation.id = p_conversation_id
     ) THEN
    RAISE EXCEPTION 'conversation not found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.conversation_member_overrides override_row
    WHERE override_row.conversation_id = p_conversation_id
      AND override_row.employee_id = v_actor.id
      AND NOT override_row.included
  )
    INTO v_already_left;

  IF NOT v_already_left
     AND NOT public.messaging_can_access_conversation(p_conversation_id) THEN
    RAISE EXCEPTION 'conversation access not found'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.conversation_member_overrides (
    conversation_id,
    employee_id,
    included,
    updated_by,
    updated_at
  )
  VALUES (
    p_conversation_id,
    v_actor.id,
    false,
    v_actor.id,
    now()
  )
  ON CONFLICT (conversation_id, employee_id)
  DO UPDATE SET
    included = false,
    updated_by = EXCLUDED.updated_by,
    updated_at = EXCLUDED.updated_at;
END;
$$;


ALTER FUNCTION "public"."leave_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."leave_conversation"("p_conversation_id" "uuid") IS 'Records a durable self-removal for an eligible current member; an already-successful removal is safe to retry.';



CREATE OR REPLACE FUNCTION "public"."link_contact_to_job"("p_contact_id" "uuid", "p_job_id" "uuid", "p_role" "text" DEFAULT 'other'::"text", "p_is_primary" boolean DEFAULT false, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_link_id uuid;
BEGIN
  INSERT INTO contact_jobs (contact_id, job_id, role, is_primary, notes)
  VALUES (p_contact_id, p_job_id, p_role, p_is_primary, p_notes)
  ON CONFLICT (contact_id, job_id, role) DO UPDATE SET
    is_primary = EXCLUDED.is_primary,
    notes = COALESCE(EXCLUDED.notes, contact_jobs.notes)
  RETURNING id INTO v_link_id;

  IF p_is_primary THEN
    UPDATE contact_jobs SET is_primary = false
    WHERE job_id = p_job_id AND id != v_link_id AND is_primary = true;
    UPDATE jobs SET primary_contact_id = p_contact_id WHERE id = p_job_id;
  END IF;

  RETURN jsonb_build_object('link_id', v_link_id, 'success', true);
END;
$$;


