CREATE OR REPLACE FUNCTION "public"."mark_all_notifications_read"("p_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  IF v_is_service_role THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE read_at IS NULL
       AND (
         recipient_id IS NULL
         OR recipient_id = p_employee_id
       );
    RETURN;
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active = true
    AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  IF p_employee_id IS NOT NULL AND p_employee_id <> v_actor THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;

  INSERT INTO public.notification_reads (
    notification_id,
    employee_id,
    read_at
  )
  SELECT notification.id, v_actor, now()
  FROM public.notifications notification
  WHERE notification.recipient_id IS NULL
    AND notification.read_at IS NULL
  ON CONFLICT (notification_id, employee_id) DO NOTHING;

  IF p_employee_id IS NOT NULL THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE recipient_id = p_employee_id
       AND read_at IS NULL;
  END IF;
END;
$$;


ALTER FUNCTION "public"."mark_all_notifications_read"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_feedback_attachments_purged"("p_id" "uuid") RETURNS "public"."tech_feedback"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result tech_feedback;
BEGIN
  UPDATE tech_feedback
  SET attachments_purged_at = COALESCE(attachments_purged_at, now())  -- first stamp wins
  WHERE id = p_id
  RETURNING * INTO result;
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."mark_feedback_attachments_purged"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_invoice_line_revision_draft"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  target uuid;
BEGIN
  target := CASE WHEN TG_OP = 'DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END;
  IF target IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  UPDATE public.invoices
     SET status = 'draft',
         updated_at = now()
   WHERE id = target
     AND qbo_invoice_id IS NOT NULL
     AND COALESCE(invoice_type, '') <> 'collection'
     AND COALESCE(amount_paid, 0) = 0
     AND status NOT IN (
       'draft', 'paid', 'partially_paid', 'voided', 'disputed', 'viewed', 'overdue'
     );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."mark_invoice_line_revision_draft"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_job_real"("p_job_id" "uuid", "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_job_id IS NULL THEN RETURN; END IF;
  UPDATE public.jobs
     SET is_real_job        = true,
         real_job_source    = COALESCE(real_job_source, p_source),
         real_job_marked_at = COALESCE(real_job_marked_at, now())
   WHERE id = p_job_id
     AND is_real_job = false;
END; $$;


ALTER FUNCTION "public"."mark_job_real"("p_job_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_notification_read"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_recipient uuid;
  v_existing_read_at timestamptz;
  v_is_service_role boolean :=
    COALESCE((SELECT auth.jwt() ->> 'role' = 'service_role'), false);
BEGIN
  -- Trusted server callers retain the old exact behavior. Browser callers never
  -- reach this branch because a signed service-role JWT cannot be minted by them.
  IF v_is_service_role THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE id = p_id
       AND read_at IS NULL;
    RETURN;
  END IF;

  SELECT employee.id
    INTO v_actor
  FROM public.employees employee
    WHERE employee.auth_user_id = (SELECT auth.uid())
      AND employee.is_active = true
      AND employee.is_external = false;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  SELECT notification.recipient_id, notification.read_at
    INTO v_recipient, v_existing_read_at
  FROM public.notifications notification
  WHERE notification.id = p_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_recipient IS NULL THEN
    IF v_existing_read_at IS NULL THEN
      INSERT INTO public.notification_reads (
        notification_id,
        employee_id,
        read_at
      )
      VALUES (p_id, v_actor, now())
      ON CONFLICT (notification_id, employee_id) DO NOTHING;
    END IF;
  ELSIF v_recipient = v_actor THEN
    UPDATE public.notifications
       SET read_at = now()
     WHERE id = p_id
       AND read_at IS NULL;
  ELSE
    RAISE EXCEPTION
      'NOT_AUTHORIZED: notification recipient mismatch'
      USING errcode = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mark_notification_read"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_qbo_payment_receipt_created"("p_attempt_id" "uuid", "p_qbo_payment_id" "text", "p_provider_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_attempt public.payment_receipt_attempts%ROWTYPE;
  v_claimed_attempt_id uuid;
  v_tombstone_event_id uuid;
  v_tombstone_status text;
  v_payment_id text;
  v_realm_id text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF p_attempt_id IS NULL OR NULLIF(btrim(p_qbo_payment_id), '') IS NULL
     OR p_provider_snapshot IS NULL OR jsonb_typeof(p_provider_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;
  SELECT qbo_realm_id INTO v_realm_id
  FROM public.payment_receipt_attempts
  WHERE id = p_attempt_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTEMPT_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  v_payment_id := btrim(p_qbo_payment_id);
  -- Every receipt RPC that needs both locks takes the realm/payment advisory
  -- lock before an attempt row lock. Webhook-first reconciliation uses the same
  -- order, so a fast provider event cannot deadlock the outbound request.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_realm_id || ':' || v_payment_id, 0)
  );
  SELECT * INTO v_attempt
  FROM public.payment_receipt_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTEMPT_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_attempt.qbo_payment_id = v_payment_id
     AND v_attempt.status IN ('qbo_created', 'locally_finalized', 'reconciled') THEN
    RETURN jsonb_build_object('attempt_id', p_attempt_id, 'qbo_payment_id', v_attempt.qbo_payment_id, 'status', v_attempt.status, 'replayed', true);
  END IF;
  IF v_attempt.qbo_payment_id = v_payment_id AND v_attempt.status = 'conflict' THEN
    RETURN jsonb_build_object(
      'attempt_id', p_attempt_id,
      'qbo_payment_id', v_attempt.qbo_payment_id,
      'status', v_attempt.status,
      'conflict', true,
      'replayed', true
    );
  END IF;
  IF v_attempt.qbo_payment_id = v_payment_id AND v_attempt.status IN ('voided', 'deleted') THEN
    RETURN jsonb_build_object(
      'attempt_id', p_attempt_id,
      'qbo_payment_id', v_attempt.qbo_payment_id,
      'status', v_attempt.status,
      'ignored_terminal', true,
      'replayed', true
    );
  END IF;
  IF v_attempt.qbo_payment_id IS NOT NULL AND v_attempt.qbo_payment_id <> v_payment_id THEN
    RAISE EXCEPTION 'QBO_PAYMENT_ID_CONFLICT' USING ERRCODE = '23505';
  END IF;

  SELECT id INTO v_claimed_attempt_id
  FROM public.payment_receipt_attempts
  WHERE qbo_realm_id = v_attempt.qbo_realm_id
    AND qbo_payment_id = v_payment_id
    AND id <> p_attempt_id
  LIMIT 1;
  IF FOUND THEN
    UPDATE public.payment_receipt_attempts
    SET status = 'conflict',
        provider_snapshot = p_provider_snapshot,
        error_code = 'QBO_PAYMENT_ID_CONFLICT',
        error_message = 'QuickBooks Payment identity is already claimed by another receipt attempt',
        updated_at = now()
    WHERE id = p_attempt_id;
    INSERT INTO public.payment_receipt_events (
      attempt_id, qbo_realm_id, qbo_payment_id, event_type, after_snapshot
    ) VALUES (
      p_attempt_id, v_attempt.qbo_realm_id, v_payment_id, 'conflict',
      jsonb_build_object(
        'status', 'conflict',
        'error_code', 'QBO_PAYMENT_ID_CONFLICT',
        'claimed_attempt_id', v_claimed_attempt_id
      )
    );
    RETURN jsonb_build_object(
      'attempt_id', p_attempt_id,
      'qbo_payment_id', v_payment_id,
      'status', 'conflict',
      'conflict', true,
      'claimed_attempt_id', v_claimed_attempt_id
    );
  END IF;

  SELECT e.id, e.event_type
    INTO v_tombstone_event_id, v_tombstone_status
  FROM public.payment_receipt_events e
  WHERE e.qbo_realm_id = v_attempt.qbo_realm_id
    AND e.qbo_payment_id = v_payment_id
    AND e.event_type IN ('conflict', 'voided', 'deleted')
  ORDER BY CASE e.event_type
      WHEN 'deleted' THEN 3
      WHEN 'voided' THEN 2
      ELSE 1
    END DESC,
    e.created_at DESC,
    e.id DESC
  LIMIT 1;
  IF FOUND THEN
    UPDATE public.payment_receipt_attempts
    SET qbo_payment_id = v_payment_id,
        provider_snapshot = p_provider_snapshot,
        status = v_tombstone_status,
        updated_at = now()
    WHERE id = p_attempt_id;
    INSERT INTO public.payment_receipt_events (
      attempt_id, qbo_realm_id, qbo_payment_id, event_type, after_snapshot
    ) VALUES (
      p_attempt_id, v_attempt.qbo_realm_id, v_payment_id, v_tombstone_status,
      jsonb_build_object(
        'status', v_tombstone_status,
        'absorbed_tombstone', true,
        'tombstone_event_id', v_tombstone_event_id
      )
    );
    RETURN jsonb_build_object(
      'attempt_id', p_attempt_id,
      'qbo_payment_id', v_payment_id,
      'status', v_tombstone_status,
      'ignored_terminal', true,
      'replayed', true
    );
  END IF;

  UPDATE public.payment_receipt_attempts SET qbo_payment_id = v_payment_id,
    provider_snapshot = p_provider_snapshot, status = 'qbo_created', updated_at = now() WHERE id = p_attempt_id;
  INSERT INTO public.payment_receipt_events (attempt_id, qbo_realm_id, qbo_payment_id, event_type, after_snapshot)
  VALUES (p_attempt_id, v_attempt.qbo_realm_id, v_payment_id, 'qbo_created', p_provider_snapshot);
  RETURN jsonb_build_object('attempt_id', p_attempt_id, 'qbo_payment_id', v_payment_id, 'status', 'qbo_created');
END;
$$;


ALTER FUNCTION "public"."mark_qbo_payment_receipt_created"("p_attempt_id" "uuid", "p_qbo_payment_id" "text", "p_provider_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialize_message_send_attempt"("p_attempt_id" "uuid") RETURNS TABLE("outcome" "text", "message_id" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_attempt public.message_send_attempts%ROWTYPE;
  v_message public.messages%ROWTYPE;
  v_message_id uuid;
  v_status text;
  v_inserted boolean := false;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'materialize_message_send_attempt is service-role only'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_attempt
  FROM public.message_send_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_attempt.parent_attempt_id IS NULL AND v_attempt.recipient_contact_id IS NULL
        AND v_attempt.client_request_id IS NULL
     OR v_attempt.provider_message_id IS NULL
     OR v_attempt.conversation_id IS NULL
     OR v_attempt.state NOT IN ('accepted', 'ambiguous', 'confirmed') THEN
    RAISE EXCEPTION 'Message attempt is not materializable'
      USING ERRCODE = '22023';
  END IF;

  IF v_attempt.actual_channel IS NOT NULL
     AND v_attempt.actual_channel <> v_attempt.requested_channel THEN
    RAISE EXCEPTION 'Cross-channel fallback cannot be materialized'
      USING ERRCODE = '22023';
  END IF;

  IF v_attempt.message_id IS NOT NULL THEN
    RETURN QUERY SELECT 'message_already_materialized'::text, v_attempt.message_id;
    RETURN;
  END IF;

  SELECT *
  INTO v_message
  FROM public.messages m
  WHERE (m.provider = v_attempt.provider
      AND m.provider_message_id = v_attempt.provider_message_id)
     OR (v_attempt.client_request_id IS NOT NULL
      AND m.client_request_id = v_attempt.client_request_id)
  ORDER BY
    (m.provider = v_attempt.provider
      AND m.provider_message_id = v_attempt.provider_message_id) DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    IF v_message.provider IS DISTINCT FROM v_attempt.provider
       OR v_message.provider_message_id IS DISTINCT FROM v_attempt.provider_message_id
       OR v_message.conversation_id IS DISTINCT FROM v_attempt.conversation_id
       OR v_message.recipient_address IS DISTINCT FROM v_attempt.recipient_address
       OR v_message.body IS DISTINCT FROM v_attempt.canonical_body THEN
      RAISE EXCEPTION 'Existing message conflicts with provider attempt identity'
        USING ERRCODE = '23505';
    END IF;
    v_message_id := v_message.id;
  ELSE
    v_status := CASE
      WHEN v_attempt.state = 'confirmed' THEN 'sent'
      ELSE COALESCE(NULLIF(v_attempt.provider_status, ''), 'queued')
    END;

    INSERT INTO public.messages (
      conversation_id,
      type,
      channel,
      body,
      status,
      twilio_sid,
      sent_by,
      media_urls,
      provider,
      provider_message_id,
      provider_conversation_id,
      client_request_id,
      sender_address,
      recipient_address,
      direction
    )
    VALUES (
      v_attempt.conversation_id,
      'sms_outbound',
      COALESCE(v_attempt.actual_channel, v_attempt.requested_channel),
      v_attempt.canonical_body,
      v_status,
      CASE WHEN v_attempt.provider = 'twilio'
        THEN v_attempt.provider_message_id ELSE NULL END,
      v_attempt.actor_employee_id,
      CASE WHEN jsonb_array_length(v_attempt.media_urls) > 0
        THEN v_attempt.media_urls ELSE NULL END,
      v_attempt.provider,
      v_attempt.provider_message_id,
      v_attempt.provider_conversation_id,
      v_attempt.client_request_id,
      v_attempt.sender_address,
      v_attempt.recipient_address,
      'outbound'
    )
    RETURNING id INTO v_message_id;
    v_inserted := true;
  END IF;

  UPDATE public.message_send_attempts
  SET message_id = v_message_id, updated_at = now()
  WHERE id = v_attempt.id;

  RETURN QUERY
  SELECT
    CASE WHEN v_inserted
      THEN 'message_materialized'::text
      ELSE 'message_already_materialized'::text
    END,
    v_message_id;
END;
$$;


ALTER FUNCTION "public"."materialize_message_send_attempt"("p_attempt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."materialize_message_send_attempt"("p_attempt_id" "uuid") IS 'Service-role-only, provider-free recovery of one accepted attempt into exactly one canonical outbound message row.';



CREATE OR REPLACE FUNCTION "public"."merge_claims"("p_keep_id" "uuid", "p_merge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_keep claims;
  v_merge claims;
  v_jobs_moved INT;
BEGIN
  IF p_keep_id = p_merge_id THEN
    RAISE EXCEPTION 'Cannot merge a claim with itself';
  END IF;

  SELECT * INTO v_keep FROM claims WHERE id = p_keep_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Keep claim not found'; END IF;

  SELECT * INTO v_merge FROM claims WHERE id = p_merge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Merge claim not found'; END IF;

  UPDATE claims SET
    insurance_carrier = COALESCE(insurance_carrier, v_merge.insurance_carrier),
    insurance_claim_number = COALESCE(insurance_claim_number, v_merge.insurance_claim_number),
    policy_number = COALESCE(policy_number, v_merge.policy_number),
    date_of_loss = COALESCE(date_of_loss, v_merge.date_of_loss),
    loss_address = COALESCE(loss_address, v_merge.loss_address),
    loss_city = COALESCE(loss_city, v_merge.loss_city),
    loss_state = COALESCE(loss_state, v_merge.loss_state),
    loss_zip = COALESCE(loss_zip, v_merge.loss_zip),
    loss_type = COALESCE(loss_type, v_merge.loss_type),
    contact_id = COALESCE(contact_id, v_merge.contact_id),
    adjuster_contact_id = COALESCE(adjuster_contact_id, v_merge.adjuster_contact_id),
    notes = CASE
      WHEN notes IS NULL THEN v_merge.notes
      WHEN v_merge.notes IS NOT NULL THEN notes || E'\n---\n' || v_merge.notes
      ELSE notes
    END,
    updated_at = now()
  WHERE id = p_keep_id;

  UPDATE jobs SET claim_id = p_keep_id WHERE claim_id = p_merge_id;
  GET DIAGNOSTICS v_jobs_moved = ROW_COUNT;

  INSERT INTO system_events (event_type, entity_type, entity_id, job_id, payload)
  VALUES ('claim.merged', 'claim', p_keep_id, NULL, jsonb_build_object(
    'kept_id', p_keep_id,
    'merged_id', p_merge_id,
    'merged_claim_number', v_merge.claim_number,
    'jobs_moved', v_jobs_moved
  ));

  DELETE FROM claims WHERE id = p_merge_id;

  RETURN jsonb_build_object(
    'ok', true,
    'kept_id', p_keep_id,
    'kept_claim_number', v_keep.claim_number,
    'merged_id', p_merge_id,
    'merged_claim_number', v_merge.claim_number,
    'jobs_moved', v_jobs_moved
  );
END;
$$;


ALTER FUNCTION "public"."merge_claims"("p_keep_id" "uuid", "p_merge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_contacts"("p_keep_id" "uuid", "p_merge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_keep contacts; v_merge contacts;
  v_claims_moved INT := 0; v_jobs_moved INT := 0; v_conversations_moved INT := 0;
BEGIN
  IF p_keep_id = p_merge_id THEN RAISE EXCEPTION 'Cannot merge a contact with itself'; END IF;
  SELECT * INTO v_keep FROM contacts WHERE id = p_keep_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Keep contact not found'; END IF;
  SELECT * INTO v_merge FROM contacts WHERE id = p_merge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Merge contact not found'; END IF;

  UPDATE contacts SET
    name = COALESCE(name, v_merge.name),
    email = COALESCE(email, v_merge.email),
    phone_secondary = COALESCE(phone_secondary, v_merge.phone_secondary),
    billing_address = COALESCE(billing_address, v_merge.billing_address),
    billing_city = COALESCE(billing_city, v_merge.billing_city),
    billing_state = COALESCE(billing_state, v_merge.billing_state),
    billing_zip = COALESCE(billing_zip, v_merge.billing_zip),
    insurance_carrier = COALESCE(insurance_carrier, v_merge.insurance_carrier),
    policy_number = COALESCE(policy_number, v_merge.policy_number),
    claim_number = COALESCE(claim_number, v_merge.claim_number),
    referral_source = COALESCE(referral_source, v_merge.referral_source),
    preferred_language = COALESCE(preferred_language, v_merge.preferred_language),
    desk_phone = COALESCE(desk_phone, v_merge.desk_phone),
    desk_extension = COALESCE(desk_extension, v_merge.desk_extension),
    territory = COALESCE(territory, v_merge.territory),
    trade_specialty = COALESCE(trade_specialty, v_merge.trade_specialty),
    notes = CASE WHEN notes IS NULL THEN v_merge.notes WHEN v_merge.notes IS NOT NULL THEN notes || E'\n---\n' || v_merge.notes ELSE notes END,
    relationship_notes = CASE WHEN relationship_notes IS NULL THEN v_merge.relationship_notes WHEN v_merge.relationship_notes IS NOT NULL THEN relationship_notes || E'\n---\n' || v_merge.relationship_notes ELSE relationship_notes END,
    dnd = COALESCE(dnd, false) OR COALESCE(v_merge.dnd, false),
    dnd_at = COALESCE(dnd_at, v_merge.dnd_at),
    opt_in_status = CASE WHEN opt_in_status = false OR v_merge.opt_in_status = false THEN false ELSE COALESCE(opt_in_status, v_merge.opt_in_status) END,
    opt_out_at = COALESCE(opt_out_at, v_merge.opt_out_at),
    opt_out_reason = COALESCE(opt_out_reason, v_merge.opt_out_reason),
    updated_at = now()
  WHERE id = p_keep_id;

  UPDATE claims SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  GET DIAGNOSTICS v_claims_moved = ROW_COUNT;
  UPDATE claims SET adjuster_contact_id = p_keep_id WHERE adjuster_contact_id = p_merge_id;
  UPDATE jobs SET primary_contact_id = p_keep_id WHERE primary_contact_id = p_merge_id;
  GET DIAGNOSTICS v_jobs_moved = ROW_COUNT;
  DELETE FROM contact_jobs WHERE contact_id = p_merge_id AND (job_id, role) IN (SELECT job_id, role FROM contact_jobs WHERE contact_id = p_keep_id);
  UPDATE contact_jobs SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE contact_addresses SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM contact_tags WHERE contact_id = p_merge_id AND tag IN (SELECT tag FROM contact_tags WHERE contact_id = p_keep_id);
  UPDATE contact_tags SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM conversation_participants WHERE contact_id = p_merge_id AND conversation_id IN (SELECT conversation_id FROM conversation_participants WHERE contact_id = p_keep_id);
  UPDATE conversation_participants SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  GET DIAGNOSTICS v_conversations_moved = ROW_COUNT;
  UPDATE messages SET sender_contact_id = p_keep_id WHERE sender_contact_id = p_merge_id;
  UPDATE invoices SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE payments SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE sign_requests SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE campaign_recipients SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE sms_consent_log SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE sub_confirmations SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE lead_attribution SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM email_campaign_recipients WHERE contact_id = p_merge_id AND campaign_id IN (SELECT campaign_id FROM email_campaign_recipients WHERE contact_id = p_keep_id);
  UPDATE email_campaign_recipients SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  DELETE FROM email_campaign_exclusions WHERE contact_id = p_merge_id AND campaign_id IN (SELECT campaign_id FROM email_campaign_exclusions WHERE contact_id = p_keep_id);
  UPDATE email_campaign_exclusions SET contact_id = p_keep_id WHERE contact_id = p_merge_id;
  UPDATE inbound_leads SET contact_id = p_keep_id WHERE contact_id = p_merge_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('contact.merged', 'contact', p_keep_id, jsonb_build_object('kept_id', p_keep_id, 'merged_id', p_merge_id, 'merged_name', v_merge.name, 'merged_phone', v_merge.phone, 'claims_moved', v_claims_moved, 'jobs_moved', v_jobs_moved, 'conversations_moved', v_conversations_moved));
  DELETE FROM contacts WHERE id = p_merge_id;
  RETURN jsonb_build_object('ok', true, 'kept_id', p_keep_id, 'merged_id', p_merge_id, 'claims_moved', v_claims_moved, 'jobs_moved', v_jobs_moved, 'conversations_moved', v_conversations_moved);
END;
$$;


ALTER FUNCTION "public"."merge_contacts"("p_keep_id" "uuid", "p_merge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_jobs"("p_keep_id" "uuid", "p_merge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_keep public.jobs%ROWTYPE;
  v_merge public.jobs%ROWTYPE;
  v_keep_has_payments boolean;
  v_merge_has_payments boolean;
  v_docs_moved integer := 0;
  v_time_entries_moved integer := 0;
  v_appointments_moved integer := 0;
BEGIN
  SELECT employee.id
  INTO v_actor_id
  FROM public.employees employee
  WHERE employee.auth_user_id = (SELECT auth.uid())
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text = 'admin'
  ORDER BY employee.id
  LIMIT 1;

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal admin required to merge jobs'
      USING ERRCODE = '42501';
  END IF;

  IF p_keep_id IS NULL
     OR p_merge_id IS NULL
     OR p_keep_id = p_merge_id THEN
    RAISE EXCEPTION 'Cannot merge a job with itself'
      USING ERRCODE = '22023';
  END IF;

  -- Lock in UUID order so opposite merge requests cannot deadlock.
  PERFORM 1
  FROM public.jobs job
  WHERE job.id IN (p_keep_id, p_merge_id)
  ORDER BY job.id
  FOR UPDATE;

  SELECT *
  INTO v_keep
  FROM public.jobs job
  WHERE job.id = p_keep_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Keep job not found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_merge
  FROM public.jobs job
  WHERE job.id = p_merge_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Merge job not found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.payments payment
    WHERE payment.job_id = p_keep_id
  )
  INTO v_keep_has_payments;
  SELECT EXISTS (
    SELECT 1
    FROM public.payments payment
    WHERE payment.job_id = p_merge_id
  )
  INTO v_merge_has_payments;

  IF v_keep_has_payments AND v_merge_has_payments THEN
    RAISE EXCEPTION
      'Both jobs have payment records. Manual reconciliation required — choose the job with the correct payment history as the keeper.';
  END IF;

  UPDATE public.jobs job
  SET insured_name = COALESCE(job.insured_name, v_merge.insured_name),
      address = COALESCE(job.address, v_merge.address),
      city = COALESCE(job.city, v_merge.city),
      state = COALESCE(job.state, v_merge.state),
      zip = COALESCE(job.zip, v_merge.zip),
      client_email = COALESCE(job.client_email, v_merge.client_email),
      client_phone = COALESCE(job.client_phone, v_merge.client_phone),
      insurance_company = COALESCE(
        job.insurance_company,
        v_merge.insurance_company
      ),
      claim_number = COALESCE(job.claim_number, v_merge.claim_number),
      adjuster_name = COALESCE(job.adjuster_name, v_merge.adjuster_name),
      adjuster_phone = COALESCE(job.adjuster_phone, v_merge.adjuster_phone),
      adjuster_email = COALESCE(job.adjuster_email, v_merge.adjuster_email),
      policy_number = COALESCE(job.policy_number, v_merge.policy_number),
      cat_code = COALESCE(job.cat_code, v_merge.cat_code),
      date_of_loss = COALESCE(job.date_of_loss, v_merge.date_of_loss),
      type_of_loss = COALESCE(job.type_of_loss, v_merge.type_of_loss),
      broker_agent = COALESCE(job.broker_agent, v_merge.broker_agent),
      project_manager = COALESCE(
        job.project_manager,
        v_merge.project_manager
      ),
      encircle_summary = COALESCE(
        job.encircle_summary,
        v_merge.encircle_summary
      ),
      encircle_claim_id = COALESCE(
        job.encircle_claim_id,
        v_merge.encircle_claim_id
      ),
      carrier_identifier = COALESCE(
        job.carrier_identifier,
        v_merge.carrier_identifier
      ),
      assignment_identifier = COALESCE(
        job.assignment_identifier,
        v_merge.assignment_identifier
      ),
      claim_id = COALESCE(job.claim_id, v_merge.claim_id),
      primary_contact_id = COALESCE(
        job.primary_contact_id,
        v_merge.primary_contact_id
      ),
      lead_source = COALESCE(job.lead_source, v_merge.lead_source),
      lead_source_detail = COALESCE(
        job.lead_source_detail,
        v_merge.lead_source_detail
      ),
      estimator = COALESCE(job.estimator, v_merge.estimator),
      lead_tech = COALESCE(job.lead_tech, v_merge.lead_tech),
      supervisor = COALESCE(job.supervisor, v_merge.supervisor),
      internal_notes = CASE
        WHEN job.internal_notes IS NULL THEN v_merge.internal_notes
        WHEN v_merge.internal_notes IS NOT NULL THEN
          job.internal_notes || E'\n---\nMerged from '
          || COALESCE(v_merge.job_number, v_merge.id::text)
          || E':\n' || v_merge.internal_notes
        ELSE job.internal_notes
      END,
      estimated_value = COALESCE(job.estimated_value, 0)
        + COALESCE(v_merge.estimated_value, 0),
      approved_value = COALESCE(job.approved_value, 0)
        + COALESCE(v_merge.approved_value, 0),
      invoiced_value = COALESCE(job.invoiced_value, 0)
        + COALESCE(v_merge.invoiced_value, 0),
      collected_value = COALESCE(job.collected_value, 0)
        + COALESCE(v_merge.collected_value, 0),
      supplement_value = COALESCE(job.supplement_value, 0)
        + COALESCE(v_merge.supplement_value, 0),
      total_labor_cost = COALESCE(job.total_labor_cost, 0)
        + COALESCE(v_merge.total_labor_cost, 0),
      total_material_cost = COALESCE(job.total_material_cost, 0)
        + COALESCE(v_merge.total_material_cost, 0),
      total_equipment_cost = COALESCE(job.total_equipment_cost, 0)
        + COALESCE(v_merge.total_equipment_cost, 0),
      total_sub_cost = COALESCE(job.total_sub_cost, 0)
        + COALESCE(v_merge.total_sub_cost, 0),
      total_other_cost = COALESCE(job.total_other_cost, 0)
        + COALESCE(v_merge.total_other_cost, 0),
      updated_at = now()
  WHERE job.id = p_keep_id;

  UPDATE public.payments SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.invoices SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.estimates SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.job_costs SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.job_supplements SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.vendor_invoices SET job_id = p_keep_id
  WHERE job_id = p_merge_id;

  UPDATE public.job_documents SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  GET DIAGNOSTICS v_docs_moved = ROW_COUNT;
  UPDATE public.job_notes SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.job_checklists SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.forms SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.sign_requests SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.document_requests SET job_id = p_keep_id
  WHERE job_id = p_merge_id;

  UPDATE public.appointments SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  GET DIAGNOSTICS v_appointments_moved = ROW_COUNT;

  DELETE FROM public.job_assignments assignment
  WHERE assignment.job_id = p_merge_id
    AND (assignment.employee_id, assignment.scheduled_date) IN (
      SELECT kept.employee_id, kept.scheduled_date
      FROM public.job_assignments kept
      WHERE kept.job_id = p_keep_id
    );
  UPDATE public.job_assignments SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.job_schedules SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.schedule_blocks SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.job_time_entries SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  GET DIAGNOSTICS v_time_entries_moved = ROW_COUNT;
  UPDATE public.job_equipment SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.job_tasks SET job_id = p_keep_id
  WHERE job_id = p_merge_id;

  UPDATE public.conversations SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.notification_queue SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.selection_dispatches SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.selection_responses SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.sub_confirmations SET job_id = p_keep_id
  WHERE job_id = p_merge_id;

  UPDATE public.job_phase_history SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  UPDATE public.system_events SET job_id = p_keep_id
  WHERE job_id = p_merge_id;
  DELETE FROM public.dispatch_board_jobs
  WHERE job_id = p_merge_id;
  DELETE FROM public.contact_jobs link
  WHERE link.job_id = p_merge_id
    AND (link.contact_id, link.role) IN (
      SELECT kept.contact_id, kept.role
      FROM public.contact_jobs kept
      WHERE kept.job_id = p_keep_id
    );
  UPDATE public.contact_jobs SET job_id = p_keep_id
  WHERE job_id = p_merge_id;

  INSERT INTO public.system_events (
    event_type,
    entity_type,
    entity_id,
    actor_id,
    job_id,
    payload
  )
  VALUES (
    'job.merged',
    'job',
    p_keep_id,
    v_actor_id,
    p_keep_id,
    jsonb_build_object(
      'kept_id', p_keep_id,
      'kept_job_number', v_keep.job_number,
      'merged_id', p_merge_id,
      'merged_job_number', v_merge.job_number,
      'appointments_moved', v_appointments_moved,
      'docs_moved', v_docs_moved,
      'time_entries_moved', v_time_entries_moved,
      'changed_at', now()
    )
  );

  DELETE FROM public.jobs
  WHERE id = p_merge_id;

  RETURN jsonb_build_object(
    'ok', true,
    'kept_id', p_keep_id,
    'kept_job_number', v_keep.job_number,
    'merged_id', p_merge_id,
    'merged_job_number', v_merge.job_number,
    'appointments_moved', v_appointments_moved,
    'docs_moved', v_docs_moved,
    'time_entries_moved', v_time_entries_moved
  );
END;
$$;


ALTER FUNCTION "public"."merge_jobs"("p_keep_id" "uuid", "p_merge_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_jobs"("p_keep_id" "uuid", "p_merge_id" "uuid") IS 'UPR appointment crew atomic save/audit repair v1: admin-only atomic merge with audited appointment reparent';



CREATE OR REPLACE FUNCTION "public"."messaging_can_access_conversation"("p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_employee_id uuid;
BEGIN
  IF p_conversation_id IS NULL THEN
    RETURN false;
  END IF;

  -- Trusted Workers keep their existing all-conversations contract. Browser
  -- callers must pass both the page capability and participant membership gates.
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  SELECT employee.id
    INTO v_employee_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active
    AND NOT employee.is_external
  LIMIT 1;

  RETURN public.messaging_employee_has_conversations_capability(v_employee_id)
    AND public.messaging_employee_can_access_conversation(
      v_employee_id,
      p_conversation_id
    );
END;
$$;


ALTER FUNCTION "public"."messaging_can_access_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."messaging_can_access_conversation"("p_conversation_id" "uuid") IS 'Participant-aware browser read predicate. Service-role Workers retain trusted all-conversation access.';



CREATE OR REPLACE FUNCTION "public"."messaging_can_access_conversations"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH actor AS (
    SELECT id, role
    FROM public.employees
    WHERE auth_user_id = auth.uid()
      AND is_active = true
      AND COALESCE(is_external, false) = false
    LIMIT 1
  ),
  employee_override AS (
    SELECT epa.can_view
    FROM public.employee_page_access epa
    JOIN actor ON actor.id = epa.employee_id
    WHERE epa.nav_key = 'conversations'
    LIMIT 1
  )
  SELECT EXISTS (
    SELECT 1
    FROM actor
    WHERE NOT COALESCE((
      SELECT force_disabled
      FROM public.feature_flags
      WHERE key = 'page:conversations'
      LIMIT 1
    ), false)
      AND CASE
        WHEN EXISTS (SELECT 1 FROM employee_override)
          THEN (SELECT can_view FROM employee_override)
        WHEN actor.role = 'admin' THEN true
        ELSE COALESCE((
          SELECT np.can_view
          FROM public.nav_permissions np
          WHERE np.role = actor.role::text
            AND np.nav_key = 'conversations'
          LIMIT 1
        ), false)
      END
  );
$$;


ALTER FUNCTION "public"."messaging_can_access_conversations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."messaging_can_access_conversations"() IS 'Trusted boolean caller contract for company-wide conversation visibility: active non-external employee plus force-disable/override/admin/role permission precedence.';



CREATE OR REPLACE FUNCTION "public"."messaging_employee_can_access_conversation"("p_employee_id" "uuid", "p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH employee_row AS (
    SELECT employee.id, employee.role::text AS role
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.is_active
      AND NOT employee.is_external
    LIMIT 1
  ),
  manual_choice AS (
    SELECT override_row.included
    FROM public.conversation_member_overrides override_row
    JOIN employee_row ON true
    WHERE override_row.conversation_id = p_conversation_id
      AND override_row.employee_id = employee_row.id
    LIMIT 1
  )
  SELECT COALESCE((
    SELECT CASE
      WHEN employee_row.role = 'crm_partner'
        THEN false
      WHEN EXISTS (SELECT 1 FROM manual_choice)
        THEN (SELECT included FROM manual_choice)
      ELSE true
    END
    FROM employee_row
  ), false);
$$;


ALTER FUNCTION "public"."messaging_employee_can_access_conversation"("p_employee_id" "uuid", "p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."messaging_employee_can_access_conversation"("p_employee_id" "uuid", "p_conversation_id" "uuid") IS 'Service-only per-conversation membership decision ONLY. It does NOT check the Conversations page capability — every caller must separately call messaging_employee_has_conversations_capability(employee_id). Default-open for active internal employees; an explicit conversation_member_overrides row adds or removes one person; crm_partner, external and inactive employees are always denied. Browser-writable appointment/job records are not authorization evidence. Corrected 2026-08-04 from deny-by-default, which had locked every field technician out of every conversation.';



CREATE OR REPLACE FUNCTION "public"."messaging_employee_has_conversations_capability"("p_employee_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH actor AS (
    SELECT employee.id, employee.role::text AS role
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.is_active
      AND NOT employee.is_external
    LIMIT 1
  ),
  employee_override AS (
    SELECT page_access.can_view
    FROM public.employee_page_access page_access
    JOIN actor ON actor.id = page_access.employee_id
    WHERE page_access.nav_key = 'conversations'
    LIMIT 1
  )
  SELECT EXISTS (
    SELECT 1
    FROM actor
    WHERE NOT COALESCE((
      SELECT flag.force_disabled
      FROM public.feature_flags flag
      WHERE flag.key = 'page:conversations'
      LIMIT 1
    ), false)
      AND CASE
        WHEN EXISTS (SELECT 1 FROM employee_override)
          THEN (SELECT can_view FROM employee_override)
        WHEN actor.role = 'admin'
          THEN true
        ELSE COALESCE((
          SELECT permission.can_view
          FROM public.nav_permissions permission
          WHERE permission.role::text = actor.role
            AND permission.nav_key = 'conversations'
          LIMIT 1
        ), false)
      END
  );
$$;


ALTER FUNCTION "public"."messaging_employee_has_conversations_capability"("p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."messaging_employee_has_conversations_capability"("p_employee_id" "uuid") IS 'Service-only target-employee Messages capability predicate. Definer wrappers derive their actor from auth.uid().';



CREATE TABLE IF NOT EXISTS "public"."lead_pipeline_stage" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lead_id" "uuid" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "stage_id" "uuid" NOT NULL,
    "moved_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."lead_pipeline_stage" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_lead_to_stage"("p_lead_id" "uuid", "p_stage_id" "uuid", "p_moved_by" "uuid" DEFAULT NULL::"uuid", "p_lost_reason" "text" DEFAULT NULL::"text") RETURNS "public"."lead_pipeline_stage"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id   uuid;
  v_from     uuid;
  v_actor    uuid;
  v_row      lead_pipeline_stage;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.crm_lead_access() THEN
    RAISE EXCEPTION 'insufficient privilege' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(
    p_moved_by,
    (SELECT e.id FROM employees e WHERE e.auth_user_id = (SELECT auth.uid()) LIMIT 1)
  );

  SELECT org_id INTO v_org_id FROM inbound_leads WHERE id = p_lead_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pipeline_stages WHERE id = p_stage_id) THEN
    RAISE EXCEPTION 'unknown pipeline_stages id: %', p_stage_id;
  END IF;

  SELECT stage_id INTO v_from FROM lead_pipeline_stage WHERE lead_id = p_lead_id;

  INSERT INTO lead_pipeline_stage (lead_id, org_id, stage_id, moved_by)
  VALUES (p_lead_id, v_org_id, p_stage_id, v_actor)
  ON CONFLICT (lead_id) DO UPDATE SET
    stage_id   = EXCLUDED.stage_id,
    moved_by   = EXCLUDED.moved_by,
    updated_at = now()
  RETURNING * INTO v_row;

  IF p_lost_reason IS NOT NULL THEN
    UPDATE inbound_leads SET lost_reason = p_lost_reason, updated_at = now()
    WHERE id = p_lead_id;
  END IF;

  INSERT INTO lead_stage_history (lead_id, org_id, stage_id, from_stage_id, lost_reason, moved_by)
  VALUES (p_lead_id, v_org_id, p_stage_id, v_from, p_lost_reason, v_actor);

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_stage_changed', 'inbound_lead', p_lead_id, v_actor,
          jsonb_build_object('stage_id', p_stage_id, 'from_stage_id', v_from, 'lost_reason', p_lost_reason));

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."move_lead_to_stage"("p_lead_id" "uuid", "p_stage_id" "uuid", "p_moved_by" "uuid", "p_lost_reason" "text") OWNER TO "postgres";


