ALTER FUNCTION "public"."mt_date"("p_ts" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mutate_notification_presentation"("p_actor_id" "uuid", "p_type_key" "text", "p_surface" "text", "p_action" "text", "p_config" "jsonb", "p_expected_revision" bigint, "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_existing public.notification_presentation_overrides%ROWTYPE;
  v_replay public.notification_presentation_audit%ROWTYPE;
  v_current_revision bigint := 0;
  v_next_revision bigint;
  v_before jsonb;
  v_after jsonb;
BEGIN
  IF COALESCE(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  IF p_request_id IS NULL
     OR p_actor_id IS NULL
     OR p_type_key IS NULL
     OR p_surface NOT IN ('bell', 'pwa_push', 'native_push')
     OR p_action NOT IN ('save', 'reset') THEN
    RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = p_actor_id
      AND e.role::text = 'admin'
      AND e.is_active IS TRUE
      AND e.is_external IS FALSE
  ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.notification_types nt WHERE nt.type_key = p_type_key
  ) THEN
    RAISE EXCEPTION 'UNKNOWN_NOTIFICATION_TYPE' USING ERRCODE = '23503';
  END IF;

  -- Serialize before replay/revision reads, including the first write where no
  -- override row exists yet. This prevents two expected_revision=0 requests
  -- from both claiming revision 1 and silently overwriting one another.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_type_key || ':' || p_surface, 0)
  );

  SELECT *
  INTO v_replay
  FROM public.notification_presentation_audit
  WHERE request_id = p_request_id;

  IF FOUND THEN
    IF v_replay.actor_employee_id <> p_actor_id
       OR v_replay.type_key <> p_type_key
       OR v_replay.surface <> p_surface
       OR v_replay.action <> p_action THEN
      RAISE EXCEPTION 'REQUEST_ID_CONFLICT' USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'revision', v_replay.revision,
      'config', v_replay.after_config,
      'replayed', true
    );
  END IF;

  SELECT *
  INTO v_existing
  FROM public.notification_presentation_overrides
  WHERE type_key = p_type_key AND surface = p_surface
  FOR UPDATE;

  IF FOUND THEN
    v_current_revision := v_existing.revision;
    v_before := jsonb_build_object(
      'enabled', v_existing.enabled,
      'title_template', v_existing.title_template,
      'body_template', v_existing.body_template,
      'route_id', v_existing.route_id,
      'contract_version', v_existing.contract_version
    );
  END IF;

  IF COALESCE(p_expected_revision, 0) <> v_current_revision THEN
    RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE = '40001';
  END IF;

  v_next_revision := v_current_revision + 1;

  IF p_action = 'save' THEN
    IF p_config IS NULL
       OR jsonb_typeof(p_config) <> 'object'
       OR (p_config - ARRAY[
         'title_template',
         'body_template',
         'route_id',
         'contract_version'
       ]::text[]) <> '{}'::jsonb
       OR NULLIF(trim(p_config->>'title_template'), '') IS NULL
       OR length(p_config->>'title_template') > 120
       OR NULLIF(trim(p_config->>'body_template'), '') IS NULL
       OR length(p_config->>'body_template') > 500
       OR NULLIF(trim(p_config->>'route_id'), '') IS NULL
       OR length(p_config->>'route_id') > 80
       OR jsonb_typeof(p_config->'contract_version') <> 'number'
       OR p_config->'contract_version' <> '1'::jsonb THEN
      RAISE EXCEPTION 'INVALID_CONFIG' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.notification_presentation_overrides (
      type_key,
      surface,
      enabled,
      title_template,
      body_template,
      route_id,
      contract_version,
      revision,
      updated_by
    )
    VALUES (
      p_type_key,
      p_surface,
      true,
      p_config->>'title_template',
      p_config->>'body_template',
      p_config->>'route_id',
      (p_config->>'contract_version')::integer,
      v_next_revision,
      p_actor_id
    )
    ON CONFLICT (type_key, surface) DO UPDATE SET
      enabled = EXCLUDED.enabled,
      title_template = EXCLUDED.title_template,
      body_template = EXCLUDED.body_template,
      route_id = EXCLUDED.route_id,
      contract_version = EXCLUDED.contract_version,
      revision = EXCLUDED.revision,
      updated_by = EXCLUDED.updated_by,
      updated_at = now();

    v_after := jsonb_build_object(
      'enabled', true,
      'title_template', p_config->>'title_template',
      'body_template', p_config->>'body_template',
      'route_id', p_config->>'route_id',
      'contract_version', (p_config->>'contract_version')::integer
    );
  ELSE
    INSERT INTO public.notification_presentation_overrides (
      type_key,
      surface,
      enabled,
      title_template,
      body_template,
      route_id,
      contract_version,
      revision,
      updated_by
    )
    VALUES (
      p_type_key,
      p_surface,
      false,
      NULL,
      NULL,
      NULL,
      NULL,
      v_next_revision,
      p_actor_id
    )
    ON CONFLICT (type_key, surface) DO UPDATE SET
      enabled = false,
      title_template = NULL,
      body_template = NULL,
      route_id = NULL,
      contract_version = NULL,
      revision = EXCLUDED.revision,
      updated_by = EXCLUDED.updated_by,
      updated_at = now();

    v_after := jsonb_build_object('enabled', false);
  END IF;

  INSERT INTO public.notification_presentation_audit (
    type_key,
    surface,
    revision,
    action,
    before_config,
    after_config,
    actor_employee_id,
    request_id
  )
  VALUES (
    p_type_key,
    p_surface,
    v_next_revision,
    p_action,
    v_before,
    v_after,
    p_actor_id,
    p_request_id
  );

  RETURN jsonb_build_object(
    'revision', v_next_revision,
    'config', v_after,
    'replayed', false
  );
END;
$$;


ALTER FUNCTION "public"."mutate_notification_presentation"("p_actor_id" "uuid", "p_type_key" "text", "p_surface" "text", "p_action" "text", "p_config" "jsonb", "p_expected_revision" bigint, "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_emit"("p_type_key" "text", "p_body" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enabled boolean;
  v_url text;
  v_secret text;
BEGIN
  IF p_type_key IS NULL THEN RETURN; END IF;
  SELECT enabled
  INTO v_enabled
  FROM public.notification_types
  WHERE type_key = p_type_key;
  IF v_enabled IS NOT TRUE THEN RETURN; END IF;

  SELECT value
  INTO v_url
  FROM public.integration_config
  WHERE key = 'notify_worker_url';
  SELECT value
  INTO v_secret
  FROM public.integration_config
  WHERE key = 'notify_webhook_secret';

  -- Exact UPR worker-URL allowlist: a rewritten integration_config row must
  -- never turn this SECURITY DEFINER pg_net caller into an SSRF vector (or
  -- leak the webhook secret to a third-party host). A blank secret is refused
  -- here because authorizeNotifyRequest 401s it anyway.
  IF v_url IS NULL OR v_url NOT IN (
    'https://dev.utahpros.app/api/notify',
    'https://utahpros.app/api/notify'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_url,
    body := COALESCE(p_body, '{}'::jsonb) || jsonb_build_object(
      'notification_event_id',
      gen_random_uuid(),
      'type_key',
      p_type_key
    ),
    headers := jsonb_build_object(
      'Content-Type',
      'application/json',
      'x-webhook-secret',
      v_secret
    )
  );
END;
$$;


ALTER FUNCTION "public"."notify_emit"("p_type_key" "text", "p_body" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_google_calendar_sync"("p_source_id" "uuid", "p_op" "text", "p_cancel" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_worker_url TEXT;
  v_secret     TEXT;
  v_body       JSONB;
BEGIN
  IF p_source_id IS NULL THEN RETURN; END IF;
  -- Inert until at least one employee has connected Google Calendar (the writer).
  IF NOT EXISTS (
    SELECT 1 FROM user_google_accounts
    WHERE refresh_token IS NOT NULL AND scopes ILIKE '%calendar%'
  ) THEN RETURN; END IF;

  SELECT value INTO v_worker_url FROM integration_config WHERE key = 'gcal_worker_url';
  SELECT value INTO v_secret     FROM integration_config WHERE key = 'gcal_webhook_secret';

  -- Exact UPR worker-URL allowlist: a rewritten integration_config row must
  -- never turn this SECURITY DEFINER pg_net caller into an SSRF vector (or
  -- leak the webhook secret to a third-party host). A blank secret is refused
  -- here because the worker 401s it anyway.
  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/google-calendar-sync',
    'https://utahpros.app/api/google-calendar-sync'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  v_body := jsonb_build_object('source_type', 'appointment', 'source_id', p_source_id, 'op', p_op);
  IF p_cancel IS NOT NULL THEN
    v_body := v_body || jsonb_build_object('cancel_client', p_cancel);
  END IF;

  PERFORM net.http_post(
    url     := v_worker_url,
    body    := v_body,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-webhook-secret', v_secret)
  );
END;
$$;


ALTER FUNCTION "public"."notify_google_calendar_sync"("p_source_id" "uuid", "p_op" "text", "p_cancel" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_qbo_customer_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Phase B: no-op. QBO customers are created on-demand at invoice/estimate
  -- time (ensureQboCustomer), not when a contact is inserted. Restore the body
  -- above to re-enable auto-sync.
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_qbo_customer_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."omni_verify_foundation"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv     uuid;
  v_msg      uuid;
  v_ids      uuid[] := '{}';
  v_val      text;
  v_type_ok    jsonb := '{}'::jsonb;
  v_channel_ok jsonb := '{}'::jsonb;
  v_type_rej boolean := false;
  v_chan_rej boolean := false;
  v_key      text;
  v_claim1   boolean;
  v_claim2   boolean;
  v_types    text[] := ARRAY['sms_inbound','sms_outbound','internal_note','email_inbound','email_outbound'];
  v_channels text[] := ARRAY['sms','mms','rcs','email'];
BEGIN
  INSERT INTO public.conversations (type, status, title)
  VALUES ('direct', 'needs_response', '__omni_selftest__')
  RETURNING id INTO v_conv;

  FOREACH v_val IN ARRAY v_types LOOP
    BEGIN
      INSERT INTO public.messages (conversation_id, type, channel, body)
      VALUES (v_conv, v_val, 'sms', 'selftest') RETURNING id INTO v_msg;
      v_ids := array_append(v_ids, v_msg);
      v_type_ok := v_type_ok || jsonb_build_object(v_val, true);
    EXCEPTION WHEN check_violation THEN
      v_type_ok := v_type_ok || jsonb_build_object(v_val, false);
    END;
  END LOOP;

  FOREACH v_val IN ARRAY v_channels LOOP
    BEGIN
      INSERT INTO public.messages (conversation_id, type, channel, body)
      VALUES (v_conv, 'sms_outbound', v_val, 'selftest') RETURNING id INTO v_msg;
      v_ids := array_append(v_ids, v_msg);
      v_channel_ok := v_channel_ok || jsonb_build_object(v_val, true);
    EXCEPTION WHEN check_violation THEN
      v_channel_ok := v_channel_ok || jsonb_build_object(v_val, false);
    END;
  END LOOP;

  BEGIN
    INSERT INTO public.messages (conversation_id, type, channel, body)
    VALUES (v_conv, '__bogus__', 'sms', 'selftest');
  EXCEPTION WHEN check_violation THEN v_type_rej := true;
  END;

  BEGIN
    INSERT INTO public.messages (conversation_id, type, channel, body)
    VALUES (v_conv, 'sms_outbound', '__bogus__', 'selftest');
  EXCEPTION WHEN check_violation THEN v_chan_rej := true;
  END;

  v_key    := 'selftest:' || gen_random_uuid()::text;
  v_claim1 := public.claim_inbound_email(v_key);
  v_claim2 := public.claim_inbound_email(v_key);

  DELETE FROM public.system_events WHERE entity_type = 'message' AND entity_id = ANY(v_ids);
  DELETE FROM public.messages       WHERE conversation_id = v_conv;
  DELETE FROM public.conversations  WHERE id = v_conv;
  DELETE FROM public.email_inbound_events WHERE message_key = v_key;

  RETURN jsonb_build_object(
    'type_accepts',          v_type_ok,
    'channel_accepts',       v_channel_ok,
    'type_rejects_bogus',    v_type_rej,
    'channel_rejects_bogus', v_chan_rej,
    'claim_first',           v_claim1,
    'claim_second',          v_claim2
  );
END;
$$;


ALTER FUNCTION "public"."omni_verify_foundation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_clear_v2_snapshot_on_legacy_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF current_setting('oop_pricing.v2_write',true) IS DISTINCT FROM 'on' THEN
    UPDATE public.oop_quote_pricing_snapshots
      SET cleared_at=now(), updated_at=now()
      WHERE quote_id=NEW.id AND cleared_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."oop_clear_v2_snapshot_on_legacy_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_prevent_converted_quote_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF OLD.converted_estimate_id IS NOT NULL THEN
    RAISE EXCEPTION 'oop_quote_already_converted' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE'
    AND NEW.converted_estimate_id IS DISTINCT FROM OLD.converted_estimate_id
    AND current_setting('oop_pricing.estimate_conversion', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'oop_quote_conversion_rpc_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE'
    AND current_setting('oop_pricing.estimate_conversion', true) = 'on'
    AND (to_jsonb(NEW) - 'converted_estimate_id')
      IS DISTINCT FROM (to_jsonb(OLD) - 'converted_estimate_id') THEN
    RAISE EXCEPTION 'oop_quote_conversion_link_only' USING ERRCODE = '23514';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."oop_prevent_converted_quote_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_pricing_active_employee"("p_admin" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_employee_id uuid;
BEGIN
  IF p_admin THEN
    SELECT e.id INTO v_employee_id FROM public.employees e
    WHERE e.auth_user_id=auth.uid()
      AND e.is_active IS TRUE
      AND e.is_external IS FALSE
      AND e.role::text='admin';
    IF v_employee_id IS NULL THEN
      RAISE EXCEPTION 'not_authorized: active internal admin employee required' USING ERRCODE='42501';
    END IF;
  ELSE
    SELECT e.id INTO v_employee_id FROM public.employees e
    WHERE e.auth_user_id=auth.uid();
    IF v_employee_id IS NULL OR NOT public.oop_pricing_calculator_access() THEN
      RAISE EXCEPTION 'not_authorized: OOP pricing access required' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN v_employee_id;
END;
$$;


ALTER FUNCTION "public"."oop_pricing_active_employee"("p_admin" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_pricing_assert_job_exists"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF p_job_id IS NOT NULL
    AND NOT EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=p_job_id) THEN
    RAISE EXCEPTION 'oop_job_not_found';
  END IF;
END;
$$;


ALTER FUNCTION "public"."oop_pricing_assert_job_exists"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_pricing_assert_storage_bounds"("p_shadow" "jsonb", "p_quote_total" numeric, "p_net_margin_pct" numeric, "p_internal_total" numeric, "p_lines" "jsonb", "p_minimum_adjustment" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_key text; v_value numeric; v_line jsonb;
BEGIN
  IF p_shadow IS NULL OR jsonb_typeof(p_shadow)<>'object' THEN RAISE EXCEPTION 'oop_shadow_values_required'; END IF;
  FOREACH v_key IN ARRAY ARRAY['techHours','billRate'] LOOP
    v_value:=COALESCE((p_shadow->>v_key)::numeric,0);
    IF v_value<0 OR v_value>999999.99 OR v_value<>round(v_value,2) THEN RAISE EXCEPTION 'oop_shadow_numeric_8_2_out_of_range:%',v_key; END IF;
  END LOOP;
  FOREACH v_key IN ARRAY ARRAY['materialsActualCost','antimicrobialSqft','containmentLinearFt','prvInvoiceCost'] LOOP
    v_value:=COALESCE((p_shadow->>v_key)::numeric,0);
    IF v_value<0 OR v_value>99999999.99 OR v_value<>round(v_value,2) THEN RAISE EXCEPTION 'oop_shadow_numeric_10_2_out_of_range:%',v_key; END IF;
  END LOOP;
  FOREACH v_key IN ARRAY ARRAY['airMoverCount','airMoverDays','lgrCount','lgrDays','xlgrCount','xlgrDays','airScrubberCount','airScrubberDays','negAirCount','negAirDays','disposalTrips'] LOOP
    v_value:=COALESCE((p_shadow->>v_key)::numeric,0);
    IF v_value<0 OR v_value>2147483647 OR v_value<>trunc(v_value) THEN RAISE EXCEPTION 'oop_shadow_integer_out_of_range:%',v_key; END IF;
  END LOOP;
  IF p_quote_total IS NULL OR abs(p_quote_total)>99999999.99 OR p_quote_total<>round(p_quote_total,2) THEN RAISE EXCEPTION 'oop_quote_total_out_of_range'; END IF;
  IF p_net_margin_pct IS NOT NULL AND (abs(p_net_margin_pct)>9999.99 OR p_net_margin_pct<>round(p_net_margin_pct,2)) THEN RAISE EXCEPTION 'oop_net_margin_pct_out_of_range'; END IF;
  IF p_internal_total IS NULL OR p_internal_total<0 OR p_internal_total>99999999.99 OR p_internal_total<>round(p_internal_total,2) THEN RAISE EXCEPTION 'oop_internal_total_out_of_range'; END IF;
  IF p_minimum_adjustment IS NULL OR p_minimum_adjustment<0 OR p_minimum_adjustment>9999999999.99 OR p_minimum_adjustment<>round(p_minimum_adjustment,2) THEN RAISE EXCEPTION 'oop_minimum_adjustment_out_of_range'; END IF;
  IF p_lines IS NOT NULL THEN
    IF jsonb_typeof(p_lines)<>'array' THEN RAISE EXCEPTION 'oop_evaluated_lines_invalid'; END IF;
    FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
      FOREACH v_key IN ARRAY ARRAY['amount','internalCost'] LOOP
        v_value:=COALESCE((v_line->>v_key)::numeric,0);
        IF abs(v_value)>99999999.99 OR v_value<>round(v_value,2) THEN RAISE EXCEPTION 'oop_pricing_line_out_of_range:%:%',COALESCE(v_line->>'key','unknown'),v_key; END IF;
      END LOOP;
    END LOOP;
  END IF;
END;
$$;


ALTER FUNCTION "public"."oop_pricing_assert_storage_bounds"("p_shadow" "jsonb", "p_quote_total" numeric, "p_net_margin_pct" numeric, "p_internal_total" numeric, "p_lines" "jsonb", "p_minimum_adjustment" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_pricing_calculator_access"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT EXISTS(
    SELECT 1
    FROM public.employees e
    JOIN public.feature_flags f ON f.key='tool:oop_pricing'
    WHERE e.auth_user_id=auth.uid()
      AND e.is_active IS TRUE
      AND e.is_external IS FALSE
      AND e.role::text IN ('admin','office','supervisor','estimator','project_manager')
      AND f.force_disabled IS NOT TRUE
      AND (f.enabled IS TRUE OR f.dev_only_user_id=e.id)
  );
$$;


ALTER FUNCTION "public"."oop_pricing_calculator_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_pricing_validate_config"("p_config" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_item jsonb; v_key text; v_keys text[]:=ARRAY[]::text[]; v_number numeric; v_field text;
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_config) k WHERE k NOT IN ('schemaVersion','name','projectMinimums','items'))
    OR jsonb_typeof(p_config->'schemaVersion')<>'number' OR p_config->>'schemaVersion'<>'1'
    OR jsonb_typeof(p_config->'name')<>'string' OR btrim(p_config->>'name')='' OR length(p_config->>'name')>120
    OR jsonb_typeof(p_config->'projectMinimums')<>'object'
    OR (SELECT count(*) FROM jsonb_object_keys(p_config->'projectMinimums'))<>2
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_config->'projectMinimums') k WHERE k NOT IN ('water','mold'))
    OR jsonb_typeof(p_config->'projectMinimums'->'water')<>'number' OR jsonb_typeof(p_config->'projectMinimums'->'mold')<>'number'
    OR jsonb_typeof(p_config->'items')<>'array' OR jsonb_array_length(p_config->'items')>250
    THEN RAISE EXCEPTION 'invalid_pricing_config'; END IF;
  FOREACH v_field IN ARRAY ARRAY['water','mold'] LOOP
    v_number:=(p_config->'projectMinimums'->>v_field)::numeric;
    IF v_number<0 OR v_number>1000000 OR v_number<>round(v_number,4) THEN RAISE EXCEPTION 'invalid_project_minimums'; END IF;
  END LOOP;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_config->'items') LOOP
    IF jsonb_typeof(v_item)<>'object'
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(v_item) k WHERE k NOT IN ('key','label','helpText','section','sortOrder','jobTypes','formula','unit','standardRate','internalRate','internalCostBasis','minimumQuantity','minimumCharge','defaultQuantity','defaultDays','percentageBase','customerVisible','active','priceOverrideAllowed'))
      OR NOT(v_item ?& ARRAY['key','label','helpText','section','sortOrder','jobTypes','formula','unit','standardRate','internalRate','internalCostBasis','minimumQuantity','minimumCharge','defaultQuantity','defaultDays','percentageBase','customerVisible','active','priceOverrideAllowed'])
      OR jsonb_typeof(v_item->'key')<>'string' OR jsonb_typeof(v_item->'label')<>'string' OR jsonb_typeof(v_item->'helpText')<>'string' OR jsonb_typeof(v_item->'section')<>'string' OR jsonb_typeof(v_item->'unit')<>'string'
      OR jsonb_typeof(v_item->'sortOrder')<>'number' OR jsonb_typeof(v_item->'standardRate')<>'number' OR jsonb_typeof(v_item->'internalRate')<>'number' OR jsonb_typeof(v_item->'minimumQuantity')<>'number' OR jsonb_typeof(v_item->'minimumCharge')<>'number' OR jsonb_typeof(v_item->'defaultQuantity')<>'number' OR jsonb_typeof(v_item->'defaultDays')<>'number'
      OR jsonb_typeof(v_item->'customerVisible')<>'boolean' OR jsonb_typeof(v_item->'active')<>'boolean' OR jsonb_typeof(v_item->'priceOverrideAllowed')<>'boolean'
      THEN RAISE EXCEPTION 'invalid_pricing_item_shape'; END IF;
    v_key:=v_item->>'key';
    IF v_key !~ '^[a-z][a-z0-9_]{0,63}$' OR v_key=ANY(v_keys)
      OR jsonb_typeof(v_item->'jobTypes')<>'array' OR jsonb_array_length(v_item->'jobTypes')=0
      OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_item->'jobTypes') x WHERE x NOT IN ('water','mold'))
      OR (SELECT count(*) FROM jsonb_array_elements_text(v_item->'jobTypes'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements_text(v_item->'jobTypes'))
      OR COALESCE(v_item->>'formula','') NOT IN ('quantity','duration','fixed','cost_plus','percentage','pass_through')
      OR COALESCE(v_item->>'internalCostBasis','') NOT IN ('units','input','percentage_base','final_total','none')
      THEN RAISE EXCEPTION 'invalid_pricing_item'; END IF;
    FOREACH v_field IN ARRAY ARRAY['sortOrder','standardRate','internalRate','minimumQuantity','minimumCharge','defaultQuantity','defaultDays'] LOOP
      v_number:=(v_item->>v_field)::numeric;
      IF v_number<0 OR v_number>(CASE WHEN v_field='sortOrder' THEN 100000 ELSE 1000000 END) OR v_number<>round(v_number,4) OR (v_field='sortOrder' AND v_number<>trunc(v_number)) THEN RAISE EXCEPTION 'invalid_pricing_item_numeric'; END IF;
    END LOOP;
    IF v_item->>'formula'<>'percentage' AND jsonb_typeof(v_item->'percentageBase')<>'null' THEN RAISE EXCEPTION 'non_percent_percentage_base'; END IF;
    IF v_item->>'formula'='percentage' AND COALESCE(v_item->>'percentageBase','')<>'prior_subtotal' AND COALESCE(v_item->>'percentageBase','')<>'final_total' AND COALESCE(v_item->>'percentageBase','') !~ '^item:[a-z][a-z0-9_]{0,63}$' THEN RAISE EXCEPTION 'invalid_percentage_base'; END IF;
    IF v_item->>'formula'='percentage' AND v_item->>'percentageBase'='final_total' AND (v_item->>'customerVisible')::boolean AND (v_item->>'standardRate')::numeric<>0 THEN RAISE EXCEPTION 'final_total_percentage_customer_rate_must_be_zero'; END IF;
    IF v_item->>'internalCostBasis' IN ('percentage_base','final_total') AND v_item->>'formula'<>'percentage' THEN RAISE EXCEPTION 'percentage_internal_basis_requires_percentage_formula'; END IF;
    v_keys:=array_append(v_keys,v_key);
  END LOOP;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_config->'items') LOOP
    IF v_item->>'formula'='percentage' AND v_item->>'percentageBase' LIKE 'item:%' AND (
      substring(v_item->>'percentageBase' from 6)=v_item->>'key' OR NOT substring(v_item->>'percentageBase' from 6)=ANY(v_keys)
      OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_config->'items') target
        WHERE target->>'key'=substring(v_item->>'percentageBase' from 6)
          AND ((target->>'sortOrder')::integer, target->>'key') < ((v_item->>'sortOrder')::integer, v_item->>'key'))
    ) THEN RAISE EXCEPTION 'invalid_percentage_base_target'; END IF;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."oop_pricing_validate_config"("p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oop_require_active_internal_quote_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid; v_labor numeric; v_equipment numeric; v_quote_raw numeric;
  v_direct numeric; v_internal_total numeric; v_margin numeric;
BEGIN
  v_actor:=public.oop_pricing_active_employee(false);
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  PERFORM public.oop_pricing_assert_job_exists(NEW.job_id);
  IF NEW.job_type IS NULL OR NEW.job_type NOT IN ('water','mold') THEN RAISE EXCEPTION 'invalid_job_type'; END IF;
  IF TG_OP='INSERT' THEN NEW.created_by:=v_actor; ELSE NEW.created_by:=OLD.created_by; END IF;

  -- Bounded compatibility exception: already-deployed legacy callers have no
  -- request-id parameter, so this path cannot be idempotent without breaking
  -- its frozen 26-argument signature. It is active-internal-only and every
  -- client-supplied total/margin is replaced by the exact frozen v1 math.
  IF current_setting('oop_pricing.v2_write',true) IS DISTINCT FROM 'on'
    AND current_setting('oop_pricing.legacy_canonical_write',true) IS DISTINCT FROM 'on' THEN
    v_labor:=COALESCE(NEW.tech_hours,0)*COALESCE(NEW.bill_rate,92);
    v_equipment:=COALESCE(NEW.air_mover_count,0)*COALESCE(NEW.air_mover_days,0)*25
      +COALESCE(NEW.lgr_count,0)*COALESCE(NEW.lgr_days,0)*80
      +COALESCE(NEW.xlgr_count,0)*COALESCE(NEW.xlgr_days,0)*125
      +COALESCE(NEW.air_scrubber_count,0)*COALESCE(NEW.air_scrubber_days,0)*75
      +CASE WHEN NEW.job_type='mold' THEN COALESCE(NEW.neg_air_count,0)*COALESCE(NEW.neg_air_days,0)*110 ELSE 0 END;
    v_quote_raw:=v_labor+v_equipment+COALESCE(NEW.materials_actual_cost,0)*1.25
      +COALESCE(NEW.antimicrobial_sqft,0)*0.35+COALESCE(NEW.disposal_trips,0)*125
      +CASE WHEN NEW.job_type='mold' THEN COALESCE(NEW.containment_linear_ft,0)*2+v_labor*0.05 ELSE 0 END;
    v_direct:=COALESCE(NEW.tech_hours,0)*51+COALESCE(NEW.materials_actual_cost,0)
      +COALESCE(NEW.antimicrobial_sqft,0)*0.15+COALESCE(NEW.disposal_trips,0)*50
      +CASE WHEN NEW.job_type='mold' THEN COALESCE(NEW.containment_linear_ft,0)*1.2+v_labor*0.02+COALESCE(NEW.prv_invoice_cost,0) ELSE 0 END;
    v_internal_total:=round(v_direct+v_quote_raw*0.33,2);
    NEW.quote_total:=round(v_quote_raw,2);
    v_margin:=CASE WHEN v_quote_raw>0 THEN round((v_quote_raw-v_direct-v_quote_raw*0.33)*100/v_quote_raw,2) END;
    NEW.net_margin_pct:=v_margin;
    PERFORM public.oop_pricing_assert_storage_bounds(
      jsonb_build_object('techHours',COALESCE(NEW.tech_hours,0),'billRate',COALESCE(NEW.bill_rate,92),
        'airMoverCount',COALESCE(NEW.air_mover_count,0),'airMoverDays',COALESCE(NEW.air_mover_days,0),
        'lgrCount',COALESCE(NEW.lgr_count,0),'lgrDays',COALESCE(NEW.lgr_days,0),
        'xlgrCount',COALESCE(NEW.xlgr_count,0),'xlgrDays',COALESCE(NEW.xlgr_days,0),
        'airScrubberCount',COALESCE(NEW.air_scrubber_count,0),'airScrubberDays',COALESCE(NEW.air_scrubber_days,0),
        'negAirCount',COALESCE(NEW.neg_air_count,0),'negAirDays',COALESCE(NEW.neg_air_days,0),
        'materialsActualCost',COALESCE(NEW.materials_actual_cost,0),'antimicrobialSqft',COALESCE(NEW.antimicrobial_sqft,0),
        'disposalTrips',COALESCE(NEW.disposal_trips,0),'containmentLinearFt',COALESCE(NEW.containment_linear_ft,0),
        'prvInvoiceCost',COALESCE(NEW.prv_invoice_cost,0)),NEW.quote_total,NEW.net_margin_pct,v_internal_total,NULL,0);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."oop_require_active_internal_quote_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."p9_assert_admin"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM employees
    WHERE auth_user_id = auth.uid()
      AND role = 'admin'
      AND is_active
  ) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;
END;
$$;


