CREATE OR REPLACE FUNCTION "public"."prepare_qbo_estimate_command"("p_command_id" "uuid", "p_estimate_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_request_hash" "text", "p_expected_qbo_estimate_id" "text", "p_target_qbo_estimate_id" "text", "p_intent_hash" "text", "p_intent_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE e public.estimates; c public.qbo_estimate_commands; r public.qbo_estimate_command_reservations; has_c boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO e FROM public.estimates WHERE id=p_estimate_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','estimate-not-found'); END IF;
 IF e.converted_invoice_id IS NOT NULL OR e.status IN ('approved','denied','paid') THEN RETURN jsonb_build_object('ok',false,'reason','estimate-terminal'); END IF;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE id=p_command_id FOR UPDATE; has_c:=FOUND;
 SELECT * INTO r FROM public.qbo_estimate_command_reservations WHERE estimate_id=p_estimate_id FOR UPDATE;
 IF NOT FOUND OR r.command_id IS DISTINCT FROM p_command_id OR r.action IS DISTINCT FROM p_action OR r.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR r.actor_employee_id IS DISTINCT FROM p_actor_employee_id OR r.realm_id IS DISTINCT FROM p_realm_id OR r.request_hash IS DISTINCT FROM p_request_hash THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
 IF COALESCE(p_intent_payload->'customer_prerequisite','{}'::jsonb) IS DISTINCT FROM r.prerequisite_payload THEN RETURN jsonb_build_object('ok',false,'reason','prerequisite-mismatch'); END IF;
 IF jsonb_typeof(p_intent_payload->'provider_source_preimage') IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-provider-source-preimage'); END IF;
 IF jsonb_typeof(p_intent_payload->'document_line_preimage') IS DISTINCT FROM 'array' OR COALESCE(p_intent_payload->>'document_line_preimage_hash','') !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-document-preimage'); END IF;
 IF has_c THEN
  IF c.estimate_id IS DISTINCT FROM p_estimate_id OR c.action IS DISTINCT FROM p_action OR c.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR c.actor_employee_id IS DISTINCT FROM p_actor_employee_id OR c.realm_id IS DISTINCT FROM p_realm_id OR c.request_hash IS DISTINCT FROM p_request_hash OR c.expected_qbo_estimate_id IS DISTINCT FROM p_expected_qbo_estimate_id OR c.target_qbo_estimate_id IS DISTINCT FROM p_target_qbo_estimate_id OR c.intent_hash IS DISTINCT FROM p_intent_hash OR c.intent_payload IS DISTINCT FROM p_intent_payload THEN RETURN jsonb_build_object('ok',false,'reason','idempotency-key-mismatch'); END IF;
  RETURN jsonb_build_object('ok',true,'replay',true,'status',c.status);
 END IF;
 INSERT INTO public.qbo_estimate_commands(id,estimate_id,action,actor_auth_user_id,actor_employee_id,initiator,realm_id,request_hash,expected_qbo_estimate_id,target_qbo_estimate_id,intent_hash,intent_payload)
 VALUES(p_command_id,p_estimate_id,p_action,p_actor_auth_user_id,p_actor_employee_id,'browser',p_realm_id,p_request_hash,p_expected_qbo_estimate_id,p_target_qbo_estimate_id,p_intent_hash,p_intent_payload);
 RETURN jsonb_build_object('ok',true,'prepared',true,'status','prepared');
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('ok',false,'reason','active-command-conflict'); END;$_$;


ALTER FUNCTION "public"."prepare_qbo_estimate_command"("p_command_id" "uuid", "p_estimate_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_request_hash" "text", "p_expected_qbo_estimate_id" "text", "p_target_qbo_estimate_id" "text", "p_intent_hash" "text", "p_intent_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_qbo_invoice_command"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_expected_qbo_invoice_id" "text", "p_target_qbo_invoice_id" "text", "p_intent_hash" "text", "p_intent_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_command public.qbo_invoice_commands; v_invoice public.invoices;
  v_reservation public.qbo_invoice_command_reservations; v_active public.qbo_invoice_commands;
  v_command_found boolean := false;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501'; END IF;
  IF p_action NOT IN ('save', 'send', 'delete') OR p_initiator NOT IN ('browser', 'webhook')
    OR (p_initiator = 'browser' AND p_actor_auth_user_id IS NULL)
    OR (p_initiator = 'webhook' AND (p_actor_auth_user_id IS NOT NULL OR p_actor_employee_id IS NOT NULL))
    OR p_intent_hash !~ '^[0-9a-f]{64}$' OR jsonb_typeof(p_intent_payload) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-command');
  END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invoice-not-found'); END IF;
  IF v_invoice.locked IS TRUE THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invoice-locked');
  END IF;
  -- Existing state transitions lock command→reservation. Follow the same
  -- order on replay so prepare cannot deadlock a concurrent terminal cleanup.
  SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id = p_command_id FOR UPDATE;
  v_command_found := FOUND;
  IF NOT v_command_found THEN
    -- Rolling-deploy compatibility: the currently deployed Worker reaches
    -- prepare without the new pre-intent reserve call. It may establish the
    -- fence here only when no other active command exists. The new Worker calls
    -- reserve_qbo_invoice_command before intent/customer work, so this branch
    -- disappears from normal traffic as soon as both origins are updated.
    SELECT * INTO v_active
    FROM public.qbo_invoice_commands
    WHERE invoice_id = p_invoice_id
      AND status IN ('prepared','provider_started','ambiguous','provider_succeeded','needs_reconciliation')
    FOR UPDATE;
    IF FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'active-command-conflict',
        'command_id', v_active.id, 'status', v_active.status);
    END IF;
  END IF;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations
   WHERE invoice_id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.qbo_invoice_command_reservations (
      invoice_id, command_id, action, actor_auth_user_id, actor_employee_id, initiator, realm_id
    ) VALUES (
      p_invoice_id, p_command_id, p_action, p_actor_auth_user_id,
      p_actor_employee_id, p_initiator, p_realm_id
    );
  ELSIF v_reservation.command_id IS DISTINCT FROM p_command_id
     OR v_reservation.action IS DISTINCT FROM p_action
     OR v_reservation.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id
     OR v_reservation.actor_employee_id IS DISTINCT FROM p_actor_employee_id
     OR v_reservation.initiator IS DISTINCT FROM p_initiator
     OR v_reservation.realm_id IS DISTINCT FROM p_realm_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reservation-mismatch');
  END IF;
  IF v_command_found THEN
    IF v_command.invoice_id IS DISTINCT FROM p_invoice_id OR v_command.action IS DISTINCT FROM p_action
      OR v_command.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR v_command.actor_employee_id IS DISTINCT FROM p_actor_employee_id
      OR v_command.initiator IS DISTINCT FROM p_initiator OR v_command.realm_id IS DISTINCT FROM p_realm_id
      OR v_command.expected_qbo_invoice_id IS DISTINCT FROM p_expected_qbo_invoice_id OR v_command.target_qbo_invoice_id IS DISTINCT FROM p_target_qbo_invoice_id
      OR v_command.intent_hash IS DISTINCT FROM p_intent_hash OR v_command.intent_payload IS DISTINCT FROM p_intent_payload THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'idempotency-key-mismatch');
    END IF;
    RETURN jsonb_build_object('ok', true, 'replay', true, 'command_id', v_command.id, 'status', v_command.status,
      'provider_stage', v_command.provider_stage, 'response_status', v_command.response_status, 'response_payload', v_command.response_payload);
  END IF;
  INSERT INTO public.qbo_invoice_commands (id,invoice_id,action,actor_auth_user_id,actor_employee_id,initiator,realm_id,expected_qbo_invoice_id,target_qbo_invoice_id,intent_hash,intent_payload)
  VALUES (p_command_id,p_invoice_id,p_action,p_actor_auth_user_id,p_actor_employee_id,p_initiator,p_realm_id,p_expected_qbo_invoice_id,p_target_qbo_invoice_id,p_intent_hash,p_intent_payload);
  RETURN jsonb_build_object('ok', true, 'prepared', true, 'command_id', p_command_id, 'status', 'prepared');
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('ok', false, 'reason', 'active-command-conflict');
END;
$_$;


ALTER FUNCTION "public"."prepare_qbo_invoice_command"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_expected_qbo_invoice_id" "text", "p_target_qbo_invoice_id" "text", "p_intent_hash" "text", "p_intent_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_email_audience"("p_filter" "jsonb" DEFAULT '{}'::"jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("contact_id" "uuid", "name" "text", "email" "text", "phone" "text", "role" "text", "referral_source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id, c.name, c.email, c.phone, c.role, c.referral_source
  FROM contacts c
  WHERE c.email IS NOT NULL AND c.email <> ''
    AND NOT c.dnd
    AND NOT EXISTS (SELECT 1 FROM email_suppressions es WHERE lower(es.email) = lower(c.email))
    AND (p_filter->>'referral_source' IS NULL OR c.referral_source = p_filter->>'referral_source')
    AND (p_filter->>'role' IS NULL OR c.role = p_filter->>'role')
    AND (p_filter->>'tag' IS NULL OR c.tags @> to_jsonb(ARRAY[p_filter->>'tag']))
    AND (p_filter->>'city' IS NULL OR c.billing_city ILIKE '%' || (p_filter->>'city') || '%')
    AND (p_filter->>'company' IS NULL OR c.company ILIKE '%' || (p_filter->>'company') || '%')
    AND (
      p_filter->>'search' IS NULL
      OR c.name ILIKE '%' || (p_filter->>'search') || '%'
      OR c.email ILIKE '%' || (p_filter->>'search') || '%'
      OR c.phone ILIKE '%' || (p_filter->>'search') || '%'
    )
  ORDER BY c.name
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."preview_email_audience"("p_filter" "jsonb", "p_org_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule"("p_template_id" "uuid", "p_start_date" "date", "p_skip_weekends" boolean DEFAULT true, "p_duration_overrides" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_phase record;
  v_dep record;
  v_phases jsonb := '[]'::jsonb;
  v_date_map jsonb := '{}'::jsonb;
  v_start date;
  v_end date;
  v_max_dep_end date;
  v_lag integer;
  v_dur integer;
  v_template_name text;
  v_override_dur integer;
BEGIN
  SELECT name INTO v_template_name FROM schedule_templates WHERE id = p_template_id;
  IF v_template_name IS NULL THEN RAISE EXCEPTION 'Template not found'; END IF;

  FOR v_phase IN
    SELECT tp.id, tp.name, tp.display_order, tp.duration_days, tp.is_milestone, tp.color,
      (SELECT count(*) FROM template_tasks tt WHERE tt.template_phase_id = tp.id) as task_count
    FROM template_phases tp
    WHERE tp.template_id = p_template_id
    ORDER BY tp.display_order
  LOOP
    -- Check for duration override (object format: {"phase_id": days})
    v_override_dur := NULL;
    IF p_duration_overrides ? v_phase.id::TEXT THEN
      v_override_dur := (p_duration_overrides->>v_phase.id::TEXT)::INTEGER;
    END IF;

    v_dur := COALESCE(v_override_dur, v_phase.duration_days, 1);

    v_max_dep_end := NULL;
    FOR v_dep IN
      SELECT td.source_phase_id, td.lag_days
      FROM template_dependencies td
      WHERE td.target_phase_id = v_phase.id AND td.template_id = p_template_id
    LOOP
      v_lag := COALESCE(v_dep.lag_days, 0);
      IF v_date_map ? v_dep.source_phase_id::text THEN
        v_end := (v_date_map -> v_dep.source_phase_id::text ->> 'end_date')::date + v_lag;
        IF v_max_dep_end IS NULL OR v_end > v_max_dep_end THEN v_max_dep_end := v_end; END IF;
      END IF;
    END LOOP;

    IF v_max_dep_end IS NOT NULL THEN v_start := v_max_dep_end + 1;
    ELSE v_start := p_start_date; END IF;

    IF p_skip_weekends THEN
      WHILE EXTRACT(DOW FROM v_start) IN (0, 6) LOOP v_start := v_start + 1; END LOOP;
    END IF;

    IF v_phase.is_milestone THEN v_end := v_start;
    ELSE
      v_end := v_start;
      FOR i IN 2..v_dur LOOP
        v_end := v_end + 1;
        IF p_skip_weekends THEN
          WHILE EXTRACT(DOW FROM v_end) IN (0, 6) LOOP v_end := v_end + 1; END LOOP;
        END IF;
      END LOOP;
    END IF;

    v_date_map := v_date_map || jsonb_build_object(
      v_phase.id::text, jsonb_build_object('start_date', v_start, 'end_date', v_end)
    );

    v_phases := v_phases || jsonb_build_object(
      'phase_id', v_phase.id, 'name', v_phase.name, 'display_order', v_phase.display_order,
      'duration_days', v_dur, 'is_milestone', v_phase.is_milestone, 'color', v_phase.color,
      'task_count', v_phase.task_count, 'start_date', v_start, 'end_date', v_end
    );
  END LOOP;

  RETURN jsonb_build_object(
    'template_name', v_template_name, 'template_id', p_template_id,
    'project_start', p_start_date,
    'project_end', (SELECT max((p->>'end_date')::date) FROM jsonb_array_elements(v_phases) p),
    'total_phases', jsonb_array_length(v_phases),
    'total_tasks', (SELECT count(*) FROM template_tasks WHERE template_phase_id IN (
      SELECT id FROM template_phases WHERE template_id = p_template_id AND NOT is_milestone)),
    'skip_weekends', p_skip_weekends, 'phases', v_phases
  );
END;
$$;


ALTER FUNCTION "public"."preview_schedule"("p_template_id" "uuid", "p_start_date" "date", "p_skip_weekends" boolean, "p_duration_overrides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."project_callrail_inbound_event"("p_event_id" "uuid", "p_consent_only" boolean DEFAULT false) RETURNS TABLE("outcome" "text", "message_id" "uuid", "conversation_id" "uuid", "contact_id" "uuid", "inserted" boolean, "requires_staff_reply" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_event public.message_provider_events%ROWTYPE;
  v_contact public.contacts%ROWTYPE;
  v_phone_digits text;
  v_phone_key text;
  v_keyword text;
  v_should_persist boolean;
  v_start_stale boolean := false;
  v_conversation_id uuid;
  v_conversation_contact_id uuid;
  v_assigned_to uuid;
  v_message_id uuid;
  v_inserted boolean := false;
  v_outcome text;
  v_now timestamptz := now();
  v_media_urls jsonb := '[]'::jsonb;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'project_callrail_inbound_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.message_provider_events
  WHERE id = p_event_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CallRail provider event % was not found', p_event_id
      USING ERRCODE = 'P0002';
  END IF;

  IF v_event.processing_state = 'processed' THEN
    RETURN QUERY
    SELECT
      COALESCE(v_event.outcome, 'inbound_already_processed'),
      v_event.message_id,
      v_event.conversation_id,
      v_event.contact_id,
      false,
      v_event.outcome = 'inbound_help';
    RETURN;
  END IF;

  IF v_event.provider <> 'callrail'
     OR v_event.direction <> 'inbound'
     OR v_event.provider_message_id IS NULL
     OR v_event.provider_conversation_id IS NULL
     OR v_event.sender_address IS NULL
     OR v_event.recipient_address IS NULL
     OR v_event.occurred_at IS NULL
     OR v_event.message_type NOT IN ('sms', 'mms') THEN
    RAISE EXCEPTION 'Stored event is not a complete CallRail inbound text event'
      USING ERRCODE = '22023';
  END IF;

  v_phone_digits := regexp_replace(v_event.sender_address, '[^0-9]', '', 'g');
  v_phone_key := right(v_phone_digits, 10);
  IF length(v_phone_key) <> 10 THEN
    RAISE EXCEPTION 'CallRail inbound sender is not a supported NANP address'
      USING ERRCODE = '22023';
  END IF;

  -- Classify consent keywords before creating an unknown contact. STOP must
  -- never pass through implied opt-in, while HELP/INFO records no global
  -- consent transition. Only an ordinary inbound message implies consent.
  v_keyword := CASE
    WHEN regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      = ANY (ARRAY['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'])
      THEN 'stop'
    WHEN regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      = ANY (ARRAY['start', 'unstop', 'subscribe', 'yes'])
      THEN 'start'
    WHEN regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      = ANY (ARRAY['help', 'info'])
      THEN 'help'
    ELSE NULL
  END;

  -- Serialize all contact/conversation/consent work for one customer number.
  PERFORM pg_advisory_xact_lock(hashtextextended('messaging-phone:' || v_phone_key, 0));

  SELECT c.*
  INTO v_contact
  FROM public.contacts c
  WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
  ORDER BY c.created_at ASC, c.id ASC
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.contacts (
      phone,
      name,
      opt_in_status,
      opt_in_source,
      opt_in_at,
      opt_out_at,
      opt_out_reason,
      dnd,
      dnd_at,
      created_at,
      updated_at
    )
    VALUES (
      v_event.sender_address,
      NULL,
      v_keyword IN ('start') OR v_keyword IS NULL,
      CASE
        WHEN v_keyword = 'start' THEN 'start_keyword'
        WHEN v_keyword IS NULL THEN 'inbound_sms'
        ELSE NULL
      END,
      CASE WHEN v_keyword IN ('start') OR v_keyword IS NULL
        THEN v_event.occurred_at
        ELSE NULL
      END,
      CASE WHEN v_keyword = 'stop' THEN v_event.occurred_at ELSE NULL END,
      CASE WHEN v_keyword = 'stop' THEN 'stop_keyword' ELSE NULL END,
      COALESCE(v_keyword = 'stop', false),
      CASE WHEN v_keyword = 'stop' THEN v_event.occurred_at ELSE NULL END,
      v_now,
      v_now
    )
    RETURNING * INTO v_contact;

    IF v_keyword IS NULL THEN
      INSERT INTO public.sms_consent_log (
        contact_id,
        phone,
        event_type,
        source,
        details,
        provider_event_id
      )
      VALUES (
        v_contact.id,
        v_event.sender_address,
        'opt_in',
        'inbound_sms',
        'Implied consent: contact initiated conversation via SMS.',
        v_event.id
      )
      ON CONFLICT (provider_event_id, contact_id, event_type)
        WHERE provider_event_id IS NOT NULL
        DO NOTHING;
    END IF;
  END IF;

  IF v_keyword = 'stop' THEN
    -- STOP is deliberately fail-closed even when an older event arrives late.
    UPDATE public.contacts c
    SET
      opt_in_status = false,
      opt_out_at = v_event.occurred_at,
      opt_out_reason = 'stop_keyword',
      dnd = true,
      dnd_at = v_event.occurred_at,
      updated_at = v_now
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key;
  ELSIF v_keyword = 'start' THEN
    -- A delayed START/YES must never undo a STOP that happened at or after it.
    SELECT EXISTS (
      SELECT 1
      FROM public.contacts c
      WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
        AND c.opt_out_at IS NOT NULL
        AND c.opt_out_at >= v_event.occurred_at
    ) OR EXISTS (
      SELECT 1
      FROM public.sms_consent_log scl
      JOIN public.message_provider_events stop_event
        ON stop_event.id = scl.provider_event_id
      JOIN public.contacts c
        ON c.id = scl.contact_id
      WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
        AND scl.event_type = 'stop_keyword'
        AND stop_event.occurred_at >= v_event.occurred_at
    )
    INTO v_start_stale;

    IF NOT v_start_stale THEN
      UPDATE public.contacts c
      SET
        opt_in_status = true,
        opt_in_source = 'start_keyword',
        opt_in_at = v_event.occurred_at,
        opt_out_at = NULL,
        opt_out_reason = NULL,
        dnd = false,
        dnd_at = v_event.occurred_at,
        updated_at = v_now
      WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key;
    END IF;
  END IF;

  IF v_keyword IS NOT NULL THEN
    INSERT INTO public.sms_consent_log (
      contact_id,
      phone,
      event_type,
      source,
      details,
      provider_event_id
    )
    SELECT
      c.id,
      COALESCE(c.phone, v_event.sender_address),
      CASE v_keyword
        WHEN 'stop' THEN 'stop_keyword'
        WHEN 'start' THEN 'start_keyword'
        ELSE 'help_request'
      END,
      'keyword',
      CASE
        WHEN v_keyword = 'stop'
          THEN 'Contact texted "' || trim(COALESCE(v_event.content, '')) ||
            '". Opted out and DND enabled.'
        WHEN v_keyword = 'start' AND v_start_stale
          THEN 'Contact texted "' || trim(COALESCE(v_event.content, '')) ||
            '". Re-subscribe suppressed because a newer STOP exists.'
        WHEN v_keyword = 'start'
          THEN 'Contact texted "' || trim(COALESCE(v_event.content, '')) ||
            '". Re-subscribed and DND disabled.'
        ELSE 'Contact texted "' || trim(COALESCE(v_event.content, '')) || '".'
      END,
      v_event.id
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND (v_keyword <> 'help' OR c.id = v_contact.id)
    ON CONFLICT (provider_event_id, contact_id, event_type)
      WHERE provider_event_id IS NOT NULL
      DO NOTHING;
  END IF;

  IF p_consent_only THEN
    v_outcome := CASE
      WHEN v_keyword = 'stop' THEN 'inbound_stop'
      WHEN v_keyword = 'start' AND v_start_stale THEN 'inbound_start_stale'
      WHEN v_keyword = 'start' THEN 'inbound_start'
      WHEN v_keyword = 'help' THEN 'inbound_help'
      ELSE 'inbound_consent_not_applicable'
    END;
    RETURN QUERY
    SELECT v_outcome, NULL::uuid, NULL::uuid, v_contact.id, false, false;
    RETURN;
  END IF;

  IF v_event.message_type = 'mms' AND (
    jsonb_array_length(v_event.owned_media) = 0
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_event.owned_media) AS media(item)
      WHERE COALESCE(media.item->>'storageRef', '') !~ '^upr-storage://'
    )
  ) THEN
    RAISE EXCEPTION 'CallRail MMS must be copied to UPR-owned storage before projection'
      USING ERRCODE = '22023';
  END IF;

  v_should_persist := v_keyword IS NULL
    OR regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      IN ('yes', 'info')
    OR v_keyword = 'help';

  IF v_should_persist THEN
    SELECT c.id, contact_match.id
    INTO v_conversation_id, v_conversation_contact_id
    FROM public.conversations c
    JOIN public.conversation_participants cp
      ON cp.conversation_id = c.id
    JOIN public.contacts contact_match
      ON contact_match.id = cp.contact_id
    WHERE c.type = 'direct'
      AND cp.is_active = true
      AND right(
        regexp_replace(COALESCE(contact_match.phone, ''), '[^0-9]', '', 'g'),
        10
      ) = v_phone_key
    ORDER BY
      c.created_at ASC,
      c.id ASC,
      contact_match.created_at ASC,
      contact_match.id ASC
    LIMIT 1;

    IF NOT FOUND THEN
      INSERT INTO public.conversations (
        type,
        title,
        status,
        status_changed_at,
        created_at,
        updated_at
      )
      VALUES (
        'direct',
        COALESCE(v_contact.name, v_event.sender_address),
        'needs_response',
        v_now,
        v_now,
        v_now
      )
      RETURNING id INTO v_conversation_id;

      INSERT INTO public.conversation_participants (
        conversation_id,
        contact_id,
        phone,
        role,
        is_active
      )
      VALUES (
        v_conversation_id,
        v_contact.id,
        v_event.sender_address,
        'primary',
        true
      )
      ON CONFLICT (conversation_id, contact_id) DO NOTHING;
    ELSE
      -- Keep sender/contact identity consistent with the participant that made
      -- this deterministic existing conversation eligible.
      SELECT c.*
      INTO v_contact
      FROM public.contacts c
      WHERE c.id = v_conversation_contact_id;
    END IF;

    IF v_event.message_type = 'mms' THEN
      SELECT COALESCE(jsonb_agg(media.item->>'storageRef'), '[]'::jsonb)
      INTO v_media_urls
      FROM jsonb_array_elements(v_event.owned_media) AS media(item);
    END IF;

    INSERT INTO public.messages (
      conversation_id,
      type,
      channel,
      body,
      status,
      provider,
      provider_message_id,
      provider_conversation_id,
      sender_address,
      recipient_address,
      sender_phone,
      sender_contact_id,
      media_urls,
      direction,
      created_at
    )
    VALUES (
      v_conversation_id,
      'sms_inbound',
      v_event.message_type,
      NULLIF(trim(COALESCE(v_event.content, '')), ''),
      'received',
      'callrail',
      v_event.provider_message_id,
      v_event.provider_conversation_id,
      v_event.sender_address,
      v_event.recipient_address,
      v_event.sender_address,
      v_contact.id,
      CASE WHEN v_event.message_type = 'mms' THEN v_media_urls ELSE NULL END,
      'inbound',
      v_event.occurred_at
    )
    ON CONFLICT (provider, provider_message_id)
      WHERE provider IS NOT NULL AND provider_message_id IS NOT NULL
      DO NOTHING
    RETURNING id INTO v_message_id;

    v_inserted := v_message_id IS NOT NULL;
    IF NOT v_inserted THEN
      SELECT m.id, m.conversation_id
      INTO v_message_id, v_conversation_id
      FROM public.messages m
      WHERE m.provider = 'callrail'
        AND m.provider_message_id = v_event.provider_message_id
      LIMIT 1;
    ELSE
      UPDATE public.conversations c
      SET
        unread_count = c.unread_count + 1,
        status = 'needs_response',
        status_changed_at = v_now,
        last_message_at = CASE
          WHEN c.last_message_at IS NULL OR v_event.occurred_at >= c.last_message_at
            THEN v_event.occurred_at
          ELSE c.last_message_at
        END,
        last_message_preview = CASE
          WHEN c.last_message_at IS NULL OR v_event.occurred_at >= c.last_message_at
            THEN left(COALESCE(NULLIF(trim(v_event.content), ''), '[Media]'), 100)
          ELSE c.last_message_preview
        END,
        updated_at = v_now
      WHERE c.id = v_conversation_id;
    END IF;
  END IF;

  v_outcome := CASE
    WHEN v_keyword = 'stop' THEN 'inbound_stop'
    WHEN v_keyword = 'start' AND v_start_stale THEN 'inbound_start_stale'
    WHEN v_keyword = 'start' THEN 'inbound_start'
    WHEN v_keyword = 'help' THEN 'inbound_help'
    ELSE 'inbound_persisted'
  END;

  IF v_inserted AND NOT p_consent_only AND v_message_id IS NOT NULL THEN
    SELECT c.assigned_to
    INTO v_assigned_to
    FROM public.conversations c
    WHERE c.id = v_conversation_id;

    INSERT INTO public.message_notification_outbox (
      provider_event_id,
      message_id,
      conversation_id,
      contact_id,
      type_key,
      payload
    )
    VALUES (
      v_event.id,
      v_message_id,
      v_conversation_id,
      v_contact.id,
      'message.inbound',
      jsonb_strip_nulls(jsonb_build_object(
        'title', 'New text from ' || COALESCE(
          NULLIF(trim(v_contact.name), ''),
          v_event.sender_address
        ),
        'body', COALESCE(
          NULLIF(left(trim(COALESCE(v_event.content, '')), 140), ''),
          '[Media]'
        ),
        'link', '/conversations',
        'entity_type', 'conversation',
        'entity_id', v_conversation_id,
        'recipient_ids', CASE WHEN v_assigned_to IS NOT NULL
          THEN jsonb_build_array(v_assigned_to) ELSE NULL END,
        'data', jsonb_build_object(
          'conversation_id', v_conversation_id,
          'route', '/conversations'
        )
      ))
    )
    ON CONFLICT (provider_event_id) DO NOTHING;
  END IF;

  UPDATE public.message_provider_events
  SET
    processing_state = 'processed',
    processed_at = v_now,
    message_id = v_message_id,
    contact_id = v_contact.id,
    conversation_id = v_conversation_id,
    outcome = v_outcome,
    error_code = NULL,
    error_message = NULL,
    updated_at = v_now
  WHERE id = v_event.id;

  RETURN QUERY
  SELECT
    v_outcome,
    v_message_id,
    v_conversation_id,
    v_contact.id,
    v_inserted,
    v_keyword = 'help';
END;
$$;


ALTER FUNCTION "public"."project_callrail_inbound_event"("p_event_id" "uuid", "p_consent_only" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."project_callrail_inbound_event"("p_event_id" "uuid", "p_consent_only" boolean) IS 'Service-role-only atomic projection of one durable CallRail inbound SMS or captured MMS event into consent, contact, conversation and message state.';



CREATE OR REPLACE FUNCTION "public"."project_callrail_outbound_event"("p_event_id" "uuid", "p_attempt_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("outcome" "text", "message_id" "uuid", "send_attempt_id" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_event public.message_provider_events%ROWTYPE;
  v_attempt public.message_send_attempts%ROWTYPE;
  v_existing_message public.messages%ROWTYPE;
  v_existing_media jsonb;
  v_materialized record;
  v_message_id uuid;
  v_now timestamptz := now();
  v_attempt_digits text;
  v_event_digits text;
  v_recipient_matches boolean;
  v_media_prefix constant text := 'upr-storage://message-attachments/outbound/';
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'project_callrail_outbound_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.message_provider_events
  WHERE id = p_event_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_event.provider <> 'callrail'
     OR v_event.direction <> 'outbound'
     OR v_event.event_type <> 'message.sent'
     OR v_event.provider_message_id IS NULL
     OR v_event.message_type NOT IN ('sms', 'mms') THEN
    RAISE EXCEPTION 'CallRail outbound event identity is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_event.processing_state = 'processed' THEN
    RETURN QUERY SELECT
      'outbound_already_projected'::text,
      v_event.message_id,
      v_event.send_attempt_id;
    RETURN;
  END IF;

  IF p_attempt_id IS NULL THEN
    SELECT m.*
    INTO v_existing_message
    FROM public.messages m
    WHERE m.provider = 'callrail'
      AND m.provider_message_id = v_event.provider_message_id
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RETURN QUERY SELECT 'outbound_unmatched'::text, NULL::uuid, NULL::uuid;
      RETURN;
    END IF;

    IF v_existing_message.channel IS DISTINCT FROM v_event.message_type THEN
      RETURN QUERY SELECT
        'outbound_unmatched'::text,
        v_existing_message.id,
        NULL::uuid;
      RETURN;
    END IF;

    v_existing_media := COALESCE(v_existing_message.media_urls, '[]'::jsonb);
    IF jsonb_typeof(v_existing_media) = 'string' THEN
      BEGIN
        v_existing_media := (v_existing_media #>> '{}')::jsonb;
      EXCEPTION
        WHEN invalid_text_representation THEN
          v_existing_media := '[]'::jsonb;
      END;
    END IF;

    IF v_event.message_type = 'mms'
       AND (
         jsonb_typeof(v_existing_media) <> 'array'
         OR jsonb_array_length(v_existing_media) = 0
         OR EXISTS (
           SELECT 1
           FROM jsonb_array_elements(v_existing_media) AS media(item)
           WHERE jsonb_typeof(media.item) <> 'string'
              OR (media.item #>> '{}') NOT LIKE v_media_prefix || '%'
              OR (media.item #>> '{}') = v_media_prefix
              OR substring((media.item #>> '{}') FROM length(v_media_prefix) + 1) LIKE '%..%'
              OR position(E'\\' IN (media.item #>> '{}')) > 0
         )
      ) THEN
      RETURN QUERY SELECT
        'outbound_unmatched'::text,
        v_existing_message.id,
        NULL::uuid;
      RETURN;
    END IF;

    v_message_id := v_existing_message.id;
  ELSE
    SELECT *
    INTO v_attempt
    FROM public.message_send_attempts
    WHERE id = p_attempt_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CallRail outbound event conflicts with its send attempt'
        USING ERRCODE = '22023';
    END IF;

    IF v_attempt.requested_channel IS DISTINCT FROM v_event.message_type THEN
      RETURN QUERY SELECT
        'outbound_unmatched'::text,
        v_attempt.message_id,
        v_attempt.id;
      RETURN;
    END IF;

    IF v_event.message_type = 'mms'
       AND (
         jsonb_typeof(COALESCE(v_attempt.media_urls, '[]'::jsonb)) <> 'array'
         OR jsonb_array_length(COALESCE(v_attempt.media_urls, '[]'::jsonb)) = 0
         OR EXISTS (
           SELECT 1
           FROM jsonb_array_elements(COALESCE(v_attempt.media_urls, '[]'::jsonb))
             AS media(item)
           WHERE jsonb_typeof(media.item) <> 'string'
              OR (media.item #>> '{}') NOT LIKE v_media_prefix || '%'
              OR (media.item #>> '{}') = v_media_prefix
              OR substring((media.item #>> '{}') FROM length(v_media_prefix) + 1) LIKE '%..%'
              OR position(E'\\' IN (media.item #>> '{}')) > 0
         )
      ) THEN
      RETURN QUERY SELECT
        'outbound_unmatched'::text,
        v_attempt.message_id,
        v_attempt.id;
      RETURN;
    END IF;

    v_attempt_digits := regexp_replace(
      COALESCE(v_attempt.recipient_address, ''),
      '[^0-9]',
      '',
      'g'
    );
    v_event_digits := regexp_replace(
      COALESCE(v_event.recipient_address, ''),
      '[^0-9]',
      '',
      'g'
    );
    v_recipient_matches :=
      v_attempt.recipient_address IS NOT DISTINCT FROM v_event.recipient_address
      OR (
        (
          v_attempt_digits ~ '^[2-9][0-9]{9}$'
          OR v_attempt_digits ~ '^1[2-9][0-9]{9}$'
        )
        AND (
          v_event_digits ~ '^[2-9][0-9]{9}$'
          OR v_event_digits ~ '^1[2-9][0-9]{9}$'
        )
        AND right(v_attempt_digits, 10) = right(v_event_digits, 10)
      );

    IF v_attempt.provider <> 'callrail'
       OR v_attempt.state NOT IN ('accepted', 'ambiguous', 'confirmed')
       OR NOT v_recipient_matches
       OR v_attempt.submitted_body IS DISTINCT FROM v_event.content
       OR (
         v_attempt.provider_message_id IS NOT NULL
         AND v_attempt.provider_message_id <> v_event.provider_message_id
       )
       OR (
         v_attempt.provider_conversation_id IS NOT NULL
         AND v_event.provider_conversation_id IS NOT NULL
         AND v_attempt.provider_conversation_id <> v_event.provider_conversation_id
       ) THEN
      RAISE EXCEPTION 'CallRail outbound event conflicts with its send attempt'
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.message_send_attempts
    SET
      state = 'confirmed',
      provider_message_id = v_event.provider_message_id,
      provider_conversation_id = v_event.provider_conversation_id,
      provider_status = 'sent',
      actual_channel = requested_channel,
      completed_at = v_event.occurred_at,
      reconcile_after = NULL,
      error_code = NULL,
      error_message = NULL,
      updated_at = v_now
    WHERE id = v_attempt.id;

    SELECT *
    INTO v_materialized
    FROM public.materialize_message_send_attempt(v_attempt.id);
    v_message_id := v_materialized.message_id;
  END IF;

  UPDATE public.messages
  SET
    status = 'sent',
    provider_message_id = v_event.provider_message_id,
    provider_conversation_id = v_event.provider_conversation_id
  WHERE id = v_message_id
    AND provider = 'callrail';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Canonical CallRail message was not found'
      USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.message_provider_events
  SET
    processing_state = 'processed',
    processed_at = v_now,
    message_id = v_message_id,
    send_attempt_id = p_attempt_id,
    outcome = 'outbound_confirmed',
    error_code = NULL,
    error_message = NULL,
    updated_at = v_now
  WHERE id = v_event.id;

  RETURN QUERY
  SELECT 'outbound_confirmed'::text, v_message_id, p_attempt_id;
END;
$_$;


ALTER FUNCTION "public"."project_callrail_outbound_event"("p_event_id" "uuid", "p_attempt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."project_callrail_outbound_event"("p_event_id" "uuid", "p_attempt_id" "uuid") IS 'Service-role-only projection of one CallRail message.sent event; channel identity and private outbound MMS ownership must match before confirmation, including the frozen canonical JSON-string media shape.';



CREATE OR REPLACE FUNCTION "public"."project_callrail_reconcile_outcome"("p_attempt_id" "uuid", "p_message_id" "uuid", "p_provider_message_id" "text", "p_provider_conversation_id" "text", "p_company_resource_id" "text", "p_sender_address" "text", "p_recipient_address" "text", "p_provider_status" "text", "p_occurred_at" timestamp with time zone, "p_raw_body_hash" "text", "p_dedupe_key" "text", "p_confirmed" boolean) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_attempt public.message_send_attempts%ROWTYPE;
  v_provider_status text;
  v_message_id uuid;
  v_now timestamptz := now();
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'project_callrail_reconcile_outcome is service-role only'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_attempt
  FROM public.message_send_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_attempt.provider <> 'callrail'
     OR v_attempt.message_id IS DISTINCT FROM p_message_id THEN
    RAISE EXCEPTION 'CallRail reconciliation attempt identity is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF v_attempt.state NOT IN ('accepted', 'ambiguous') THEN
    RETURN false;
  END IF;

  v_provider_status := lower(trim(COALESCE(p_provider_status, '')));
  IF v_provider_status NOT IN ('sent', 'failed', 'error')
     OR p_confirmed IS DISTINCT FROM (v_provider_status = 'sent') THEN
    RAISE EXCEPTION 'CallRail reconciliation status and confirmation are inconsistent'
      USING ERRCODE = '22023';
  END IF;

  v_message_id := p_message_id;
  IF p_confirmed AND v_message_id IS NULL THEN
    UPDATE public.message_send_attempts
    SET
      provider_message_id = p_provider_message_id,
      provider_conversation_id = p_provider_conversation_id,
      provider_status = v_provider_status,
      actual_channel = requested_channel,
      updated_at = v_now
    WHERE id = p_attempt_id;

    SELECT materialized.message_id
    INTO v_message_id
    FROM public.materialize_message_send_attempt(p_attempt_id) materialized;
  END IF;

  INSERT INTO public.message_provider_events (
    provider,
    event_type,
    provider_event_id,
    provider_message_id,
    provider_conversation_id,
    direction,
    message_type,
    provider_status,
    sender_address,
    recipient_address,
    content,
    company_resource_id,
    media_count,
    raw_body_hash,
    dedupe_key,
    occurred_at,
    processing_state,
    processed_at,
    message_id,
    send_attempt_id,
    outcome
  )
  VALUES (
    'callrail',
    'text_reconciled',
    'reconcile:' || p_provider_message_id,
    p_provider_message_id,
    p_provider_conversation_id,
    'outbound',
    v_attempt.requested_channel,
    v_provider_status,
    p_sender_address,
    p_recipient_address,
    NULL,
    p_company_resource_id,
    0,
    p_raw_body_hash,
    p_dedupe_key,
    p_occurred_at,
    'processed',
    v_now,
    v_message_id,
    p_attempt_id,
    CASE WHEN p_confirmed THEN 'outbound_confirmed' ELSE 'outbound_failed' END
  )
  ON CONFLICT (dedupe_key) DO NOTHING;

  UPDATE public.message_send_attempts
  SET
    state = CASE WHEN p_confirmed THEN 'confirmed' ELSE 'failed' END,
    message_id = v_message_id,
    provider_message_id = p_provider_message_id,
    provider_conversation_id = p_provider_conversation_id,
    actual_channel = requested_channel,
    completed_at = p_occurred_at,
    reconcile_after = NULL,
    error_code = CASE WHEN p_confirmed THEN NULL ELSE 'CALLRAIL_PROVIDER_FAILED' END,
    error_message = CASE
      WHEN p_confirmed THEN NULL
      ELSE 'CallRail reports provider status ' || v_provider_status
    END,
    updated_at = v_now
  WHERE id = p_attempt_id;

  IF v_message_id IS NOT NULL THEN
    UPDATE public.messages
    SET
      status = CASE WHEN p_confirmed THEN 'sent' ELSE 'failed' END,
      provider_message_id = p_provider_message_id,
      provider_conversation_id = p_provider_conversation_id,
      error_code = CASE WHEN p_confirmed THEN NULL ELSE 'CALLRAIL_PROVIDER_FAILED' END,
      error_message = CASE
        WHEN p_confirmed THEN NULL
        ELSE 'CallRail reports provider status ' || v_provider_status
      END
    WHERE id = v_message_id
      AND provider = 'callrail';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Canonical CallRail message was not found for reconciliation'
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."project_callrail_reconcile_outcome"("p_attempt_id" "uuid", "p_message_id" "uuid", "p_provider_message_id" "text", "p_provider_conversation_id" "text", "p_company_resource_id" "text", "p_sender_address" "text", "p_recipient_address" "text", "p_provider_status" "text", "p_occurred_at" timestamp with time zone, "p_raw_body_hash" "text", "p_dedupe_key" "text", "p_confirmed" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."project_callrail_reconcile_outcome"("p_attempt_id" "uuid", "p_message_id" "uuid", "p_provider_message_id" "text", "p_provider_conversation_id" "text", "p_company_resource_id" "text", "p_sender_address" "text", "p_recipient_address" "text", "p_provider_status" "text", "p_occurred_at" timestamp with time zone, "p_raw_body_hash" "text", "p_dedupe_key" "text", "p_confirmed" boolean) IS 'Service-role-only atomic projection of one exact CallRail history reconciliation into provider event, attempt, and canonical message state.';



CREATE OR REPLACE FUNCTION "public"."project_twilio_inbound_event"("p_event_id" "uuid", "p_consent_only" boolean DEFAULT false) RETURNS TABLE("outcome" "text", "message_id" "uuid", "conversation_id" "uuid", "contact_id" "uuid", "inserted" boolean, "requires_staff_reply" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_event public.message_provider_events%ROWTYPE;
  v_contact public.contacts%ROWTYPE;
  v_phone_digits text;
  v_phone_key text;
  v_keyword text;
  v_should_persist boolean;
  v_start_stale boolean := false;
  v_conversation_id uuid;
  v_conversation_contact_id uuid;
  v_assigned_to uuid;
  v_message_id uuid;
  v_inserted boolean := false;
  v_outcome text;
  v_now timestamptz := now();
  v_media_urls jsonb := '[]'::jsonb;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'project_twilio_inbound_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_event
  FROM public.message_provider_events
  WHERE id = p_event_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Twilio provider event % was not found', p_event_id
      USING ERRCODE = 'P0002';
  END IF;

  IF v_event.processing_state = 'processed' THEN
    RETURN QUERY
    SELECT
      COALESCE(v_event.outcome, 'inbound_already_processed'),
      v_event.message_id,
      v_event.conversation_id,
      v_event.contact_id,
      false,
      v_event.outcome = 'inbound_help';
    RETURN;
  END IF;

  IF v_event.provider <> 'twilio'
     OR v_event.direction <> 'inbound'
     OR v_event.provider_message_id IS NULL
     OR v_event.sender_address IS NULL
     OR v_event.recipient_address IS NULL
     OR v_event.occurred_at IS NULL
     OR v_event.message_type NOT IN ('sms', 'mms') THEN
    RAISE EXCEPTION 'Stored event is not a complete Twilio inbound text event'
      USING ERRCODE = '22023';
  END IF;

  v_phone_digits := regexp_replace(v_event.sender_address, '[^0-9]', '', 'g');
  v_phone_key := right(v_phone_digits, 10);
  IF length(v_phone_key) <> 10 THEN
    RAISE EXCEPTION 'Twilio inbound sender is not a supported NANP address'
      USING ERRCODE = '22023';
  END IF;

  v_keyword := CASE
    WHEN regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      = ANY (ARRAY['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'])
      THEN 'stop'
    WHEN regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      = ANY (ARRAY['start', 'unstop', 'subscribe', 'yes'])
      THEN 'start'
    WHEN regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      = ANY (ARRAY['help', 'info'])
      THEN 'help'
    ELSE NULL
  END;

  -- This is the same advisory-lock namespace used by CallRail inbound and the
  -- service-consent RPCs, so late events from either provider cannot race one
  -- customer into competing contacts/conversations or reordered consent state.
  PERFORM pg_advisory_xact_lock(hashtextextended('messaging-phone:' || v_phone_key, 0));

  SELECT c.*
  INTO v_contact
  FROM public.contacts c
  WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
  ORDER BY c.created_at ASC, c.id ASC
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.contacts (
      phone,
      name,
      opt_in_status,
      opt_in_source,
      opt_in_at,
      opt_out_at,
      opt_out_reason,
      dnd,
      dnd_at,
      created_at,
      updated_at
    )
    VALUES (
      v_event.sender_address,
      NULL,
      v_keyword IN ('start') OR v_keyword IS NULL,
      CASE
        WHEN v_keyword = 'start' THEN 'start_keyword'
        WHEN v_keyword IS NULL THEN 'inbound_sms'
        ELSE NULL
      END,
      CASE WHEN v_keyword IN ('start') OR v_keyword IS NULL
        THEN v_event.occurred_at
        ELSE NULL
      END,
      CASE WHEN v_keyword = 'stop' THEN v_event.occurred_at ELSE NULL END,
      CASE WHEN v_keyword = 'stop' THEN 'stop_keyword' ELSE NULL END,
      COALESCE(v_keyword = 'stop', false),
      CASE WHEN v_keyword = 'stop' THEN v_event.occurred_at ELSE NULL END,
      v_now,
      v_now
    )
    RETURNING * INTO v_contact;

    IF v_keyword IS NULL THEN
      INSERT INTO public.sms_consent_log (
        contact_id,
        phone,
        event_type,
        source,
        details,
        provider_event_id
      )
      VALUES (
        v_contact.id,
        v_event.sender_address,
        'opt_in',
        'inbound_sms',
        'Implied consent: contact initiated conversation via SMS.',
        v_event.id
      )
      ON CONFLICT (provider_event_id, contact_id, event_type)
        WHERE provider_event_id IS NOT NULL
        DO NOTHING;
    END IF;
  END IF;

  IF v_keyword = 'stop' THEN
    UPDATE public.contacts c
    SET
      opt_in_status = false,
      opt_out_at = v_event.occurred_at,
      opt_out_reason = 'stop_keyword',
      dnd = true,
      dnd_at = v_event.occurred_at,
      updated_at = v_now
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key;
  ELSIF v_keyword = 'start' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.contacts c
      WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
        AND c.opt_out_at IS NOT NULL
        AND c.opt_out_at >= v_event.occurred_at
    ) OR EXISTS (
      SELECT 1
      FROM public.sms_consent_log scl
      JOIN public.message_provider_events stop_event
        ON stop_event.id = scl.provider_event_id
      JOIN public.contacts c
        ON c.id = scl.contact_id
      WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
        AND scl.event_type = 'stop_keyword'
        AND stop_event.occurred_at >= v_event.occurred_at
    )
    INTO v_start_stale;

    IF NOT v_start_stale THEN
      UPDATE public.contacts c
      SET
        opt_in_status = true,
        opt_in_source = 'start_keyword',
        opt_in_at = v_event.occurred_at,
        opt_out_at = NULL,
        opt_out_reason = NULL,
        dnd = false,
        dnd_at = v_event.occurred_at,
        updated_at = v_now
      WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key;
    END IF;
  END IF;

  IF v_keyword IS NOT NULL THEN
    INSERT INTO public.sms_consent_log (
      contact_id,
      phone,
      event_type,
      source,
      details,
      provider_event_id
    )
    SELECT
      c.id,
      COALESCE(c.phone, v_event.sender_address),
      CASE v_keyword
        WHEN 'stop' THEN 'stop_keyword'
        WHEN 'start' THEN 'start_keyword'
        ELSE 'help_request'
      END,
      'keyword',
      CASE
        WHEN v_keyword = 'stop'
          THEN 'Contact texted "' || trim(COALESCE(v_event.content, '')) ||
            '". Opted out and DND enabled.'
        WHEN v_keyword = 'start' AND v_start_stale
          THEN 'Contact texted "' || trim(COALESCE(v_event.content, '')) ||
            '". Re-subscribe suppressed because a newer STOP exists.'
        WHEN v_keyword = 'start'
          THEN 'Contact texted "' || trim(COALESCE(v_event.content, '')) ||
            '". Re-subscribed and DND disabled.'
        ELSE 'Contact texted "' || trim(COALESCE(v_event.content, '')) || '".'
      END,
      v_event.id
    FROM public.contacts c
    WHERE right(regexp_replace(COALESCE(c.phone, ''), '[^0-9]', '', 'g'), 10) = v_phone_key
      AND (v_keyword <> 'help' OR c.id = v_contact.id)
    ON CONFLICT (provider_event_id, contact_id, event_type)
      WHERE provider_event_id IS NOT NULL
      DO NOTHING;
  END IF;

  IF p_consent_only THEN
    v_outcome := CASE
      WHEN v_keyword = 'stop' THEN 'inbound_stop'
      WHEN v_keyword = 'start' AND v_start_stale THEN 'inbound_start_stale'
      WHEN v_keyword = 'start' THEN 'inbound_start'
      WHEN v_keyword = 'help' THEN 'inbound_help'
      ELSE 'inbound_consent_not_applicable'
    END;
    RETURN QUERY
    SELECT v_outcome, NULL::uuid, NULL::uuid, v_contact.id, false, false;
    RETURN;
  END IF;

  IF v_event.message_type = 'mms' AND (
    jsonb_array_length(v_event.owned_media) = 0
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_event.owned_media) AS media(item)
      WHERE COALESCE(media.item->>'storageRef', '')
        !~ '^upr-storage://message-attachments/twilio/'
    )
  ) THEN
    RAISE EXCEPTION 'Twilio MMS must be copied to UPR-owned storage before projection'
      USING ERRCODE = '22023';
  END IF;

  -- Preserve the hardened shared keyword semantics: STOP and unambiguous START
  -- are consent-only; YES/INFO remain real content; HELP stays visible to staff.
  v_should_persist := v_keyword IS NULL
    OR regexp_replace(lower(trim(COALESCE(v_event.content, ''))), '[^a-z0-9]', '', 'g')
      IN ('yes', 'info')
    OR v_keyword = 'help';

  IF v_should_persist THEN
    SELECT c.id, contact_match.id
    INTO v_conversation_id, v_conversation_contact_id
    FROM public.conversations c
    JOIN public.conversation_participants cp
      ON cp.conversation_id = c.id
    JOIN public.contacts contact_match
      ON contact_match.id = cp.contact_id
    WHERE c.type = 'direct'
      AND cp.is_active = true
      AND right(
        regexp_replace(COALESCE(contact_match.phone, ''), '[^0-9]', '', 'g'),
        10
      ) = v_phone_key
    ORDER BY
      c.created_at ASC,
      c.id ASC,
      contact_match.created_at ASC,
      contact_match.id ASC
    LIMIT 1;

    IF NOT FOUND THEN
      INSERT INTO public.conversations (
        type,
        title,
        status,
        status_changed_at,
        twilio_number,
        created_at,
        updated_at
      )
      VALUES (
        'direct',
        COALESCE(v_contact.name, v_event.sender_address),
        'needs_response',
        v_now,
        v_event.recipient_address,
        v_now,
        v_now
      )
      RETURNING id INTO v_conversation_id;

      INSERT INTO public.conversation_participants (
        conversation_id,
        contact_id,
        phone,
        role,
        is_active
      )
      VALUES (
        v_conversation_id,
        v_contact.id,
        v_event.sender_address,
        'primary',
        true
      )
      ON CONFLICT (conversation_id, contact_id) DO NOTHING;
    ELSE
      SELECT c.*
      INTO v_contact
      FROM public.contacts c
      WHERE c.id = v_conversation_contact_id;
    END IF;

    IF v_event.message_type = 'mms' THEN
      SELECT COALESCE(jsonb_agg(media.item->>'storageRef'), '[]'::jsonb)
      INTO v_media_urls
      FROM jsonb_array_elements(v_event.owned_media) AS media(item);
    END IF;

    INSERT INTO public.messages (
      conversation_id,
      type,
      channel,
      body,
      status,
      twilio_sid,
      provider,
      provider_message_id,
      provider_conversation_id,
      sender_address,
      recipient_address,
      sender_phone,
      sender_contact_id,
      media_urls,
      direction,
      created_at
    )
    VALUES (
      v_conversation_id,
      'sms_inbound',
      v_event.message_type,
      NULLIF(trim(COALESCE(v_event.content, '')), ''),
      'received',
      v_event.provider_message_id,
      'twilio',
      v_event.provider_message_id,
      NULL,
      v_event.sender_address,
      v_event.recipient_address,
      v_event.sender_address,
      v_contact.id,
      CASE WHEN v_event.message_type = 'mms' THEN v_media_urls ELSE NULL END,
      'inbound',
      v_event.occurred_at
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_message_id;

    v_inserted := v_message_id IS NOT NULL;
    IF NOT v_inserted THEN
      SELECT m.id, m.conversation_id
      INTO v_message_id, v_conversation_id
      FROM public.messages m
      WHERE (
          m.provider = 'twilio'
          AND m.provider_message_id = v_event.provider_message_id
        )
        OR m.twilio_sid = v_event.provider_message_id
      ORDER BY (m.provider = 'twilio') DESC, m.created_at ASC, m.id ASC
      LIMIT 1;
      IF v_message_id IS NULL THEN
        RAISE EXCEPTION
          'Twilio MessageSid conflict did not resolve to a canonical message'
          USING ERRCODE = '23505';
      END IF;
    ELSE
      UPDATE public.conversations c
      SET
        unread_count = c.unread_count + 1,
        status = 'needs_response',
        status_changed_at = v_now,
        last_message_at = CASE
          WHEN c.last_message_at IS NULL OR v_event.occurred_at >= c.last_message_at
            THEN v_event.occurred_at
          ELSE c.last_message_at
        END,
        last_message_preview = CASE
          WHEN c.last_message_at IS NULL OR v_event.occurred_at >= c.last_message_at
            THEN left(COALESCE(NULLIF(trim(v_event.content), ''), '[Media]'), 100)
          ELSE c.last_message_preview
        END,
        updated_at = v_now
      WHERE c.id = v_conversation_id;
    END IF;
  END IF;

  v_outcome := CASE
    WHEN v_keyword = 'stop' THEN 'inbound_stop'
    WHEN v_keyword = 'start' AND v_start_stale THEN 'inbound_start_stale'
    WHEN v_keyword = 'start' THEN 'inbound_start'
    WHEN v_keyword = 'help' THEN 'inbound_help'
    ELSE 'inbound_persisted'
  END;

  IF v_inserted AND v_message_id IS NOT NULL THEN
    SELECT c.assigned_to
    INTO v_assigned_to
    FROM public.conversations c
    WHERE c.id = v_conversation_id;

    INSERT INTO public.message_notification_outbox (
      provider_event_id,
      message_id,
      conversation_id,
      contact_id,
      type_key,
      payload
    )
    VALUES (
      v_event.id,
      v_message_id,
      v_conversation_id,
      v_contact.id,
      'message.inbound',
      jsonb_strip_nulls(jsonb_build_object(
        'title', 'New text from ' || COALESCE(
          NULLIF(trim(v_contact.name), ''),
          v_event.sender_address
        ),
        'body', COALESCE(
          NULLIF(left(trim(COALESCE(v_event.content, '')), 140), ''),
          '[Media]'
        ),
        'link', '/conversations',
        'entity_type', 'conversation',
        'entity_id', v_conversation_id,
        'recipient_ids', CASE WHEN v_assigned_to IS NOT NULL
          THEN jsonb_build_array(v_assigned_to) ELSE NULL END,
        'data', jsonb_build_object(
          'conversation_id', v_conversation_id,
          'route', '/conversations'
        )
      ))
    )
    ON CONFLICT (provider_event_id) DO NOTHING;
  END IF;

  UPDATE public.message_provider_events
  SET
    processing_state = 'processed',
    processed_at = v_now,
    message_id = v_message_id,
    contact_id = v_contact.id,
    conversation_id = v_conversation_id,
    outcome = v_outcome,
    error_code = NULL,
    error_message = NULL,
    next_attempt_at = NULL,
    claimed_at = NULL,
    updated_at = v_now
  WHERE id = v_event.id;

  RETURN QUERY
  SELECT
    v_outcome,
    v_message_id,
    v_conversation_id,
    v_contact.id,
    v_inserted,
    v_keyword = 'help';
END;
$$;


ALTER FUNCTION "public"."project_twilio_inbound_event"("p_event_id" "uuid", "p_consent_only" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."project_twilio_inbound_event"("p_event_id" "uuid", "p_consent_only" boolean) IS 'Service-role-only atomic Twilio inbound projection: per-phone consent/conversation serialization, MessageSid idempotency, unread update, and one durable notification-outbox occurrence.';



CREATE OR REPLACE FUNCTION "public"."promote_lead_to_contact"("p_lead_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead       inbound_leads;
  v_phone      text;
  v_name       text := nullif(btrim(p_name), '');
  v_email      text := nullif(btrim(p_email), '');
  v_contact_id uuid;
BEGIN
  SELECT * INTO v_lead FROM inbound_leads WHERE id = p_lead_id;
  IF v_lead.id IS NULL THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  v_phone := nullif(btrim(v_lead.caller_number), '');
  IF v_phone IS NULL THEN
    RAISE EXCEPTION 'this lead has no phone number to create a contact from';
  END IF;

  SELECT id INTO v_contact_id FROM contacts WHERE phone = v_phone LIMIT 1;
  IF v_contact_id IS NULL THEN
    INSERT INTO contacts (phone, name, email) VALUES (v_phone, v_name, v_email)
    RETURNING id INTO v_contact_id;
  ELSE
    UPDATE contacts
       SET name  = COALESCE(NULLIF(btrim(name), ''), v_name),
           email = COALESCE(NULLIF(btrim(email), ''), v_email),
           updated_at = now()
     WHERE id = v_contact_id;
  END IF;

  UPDATE inbound_leads
     SET contact_id = v_contact_id, updated_at = now()
   WHERE caller_number = v_phone AND contact_id IS NULL;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_promoted', 'inbound_lead', p_lead_id, p_created_by,
          jsonb_build_object('contact_id', v_contact_id));

  SELECT * INTO v_lead FROM inbound_leads WHERE id = p_lead_id;
  RETURN v_lead;
END;
$$;


ALTER FUNCTION "public"."promote_lead_to_contact"("p_lead_id" "uuid", "p_name" "text", "p_email" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_inbound_lead_recording_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.recording_url IS NOT NULL
     AND btrim(NEW.recording_url) <> ''
     AND NEW.recording_url <> 'upr-recording://available'
  THEN
    INSERT INTO public.inbound_lead_recording_sources (lead_id, recording_url, updated_at)
    VALUES (NEW.id, NEW.recording_url, now())
    ON CONFLICT (lead_id) DO UPDATE
      SET recording_url = EXCLUDED.recording_url,
          updated_at = EXCLUDED.updated_at;
    UPDATE public.inbound_leads
    SET recording_url = 'upr-recording://available'
    WHERE id = NEW.id
      AND recording_url IS DISTINCT FROM 'upr-recording://available';
  ELSIF NEW.recording_url IS NULL
        OR btrim(NEW.recording_url) = ''
  THEN
    DELETE FROM public.inbound_lead_recording_sources WHERE lead_id = NEW.id;
    IF NEW.recording_url IS NOT NULL THEN
      UPDATE public.inbound_leads
      SET recording_url = NULL
      WHERE id = NEW.id
        AND recording_url IS NOT NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_inbound_lead_recording_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_stale_native_device_token"("p_device_token_id" "uuid", "p_token" "text", "p_apns_environment" "text", "p_observed_updated_at" timestamp with time zone, "p_invalidated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_deleted boolean;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required'
      USING errcode = '42501';
  END IF;

  DELETE FROM public.device_tokens token_row
  WHERE token_row.id = p_device_token_id
    AND token_row.token = p_token
    AND token_row.platform = 'ios'
    AND token_row.apns_environment = p_apns_environment
    AND token_row.updated_at = p_observed_updated_at
    AND (
      p_invalidated_at IS NULL
      OR token_row.updated_at <= p_invalidated_at
    )
  RETURNING true INTO v_deleted;

  RETURN COALESCE(v_deleted, false);
END;
$$;


ALTER FUNCTION "public"."prune_stale_native_device_token"("p_device_token_id" "uuid", "p_token" "text", "p_apns_environment" "text", "p_observed_updated_at" timestamp with time zone, "p_invalidated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_demo_schema"("p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE demo_sheet_schemas SET is_active = false WHERE is_active = true;
  UPDATE demo_sheet_schemas
     SET is_active = true,
         published_at = COALESCE(published_at, now())
   WHERE id = p_id;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."publish_demo_schema"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_oop_pricing_draft"("p_expected_lock_version" integer, "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid; v_draft public.oop_pricing_revisions; v_result jsonb; v_number integer;
BEGIN
  v_actor:=public.oop_pricing_active_employee(true);
  IF p_expected_lock_version IS NULL OR p_request_id IS NULL THEN RAISE EXCEPTION 'expected_lock_version_and_request_id_required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('oop_pricing_publish'));
  PERFORM pg_advisory_xact_lock(hashtext('oop_pricing_request:' || p_request_id::text));
  SELECT result INTO v_result FROM public.oop_pricing_audit WHERE request_id=p_request_id AND actor_employee_id=v_actor AND action='publish_draft' AND request_hash=md5(jsonb_build_object('expectedLockVersion',p_expected_lock_version)::text); IF FOUND THEN RETURN v_result; END IF; IF EXISTS(SELECT 1 FROM public.oop_pricing_audit WHERE request_id=p_request_id) THEN RAISE EXCEPTION 'request_id_reused_with_different_payload'; END IF;
  SELECT * INTO v_draft FROM public.oop_pricing_revisions WHERE status='draft' FOR UPDATE;
  IF v_draft.id IS NULL THEN RAISE EXCEPTION 'pricing_draft_missing'; END IF;
  IF v_draft.lock_version <> p_expected_lock_version THEN RAISE EXCEPTION 'pricing_draft_conflict'; END IF;
  UPDATE public.oop_pricing_revisions SET status='superseded' WHERE status='published';
  UPDATE public.oop_pricing_revisions SET status='published', published_at=now(), published_by=v_actor WHERE id=v_draft.id RETURNING * INTO v_draft;
  SELECT max(revision_number)+1 INTO v_number FROM public.oop_pricing_revisions;
  INSERT INTO public.oop_pricing_revisions(revision_number,status,config,created_by) VALUES(v_number,'draft',v_draft.config,v_actor);
  v_result:=jsonb_build_object('publishedRevisionId',v_draft.id,'revisionNumber',v_draft.revision_number,'updatedAt',v_draft.published_at,'publishedAt',v_draft.published_at,'contentHash',md5(v_draft.config::text));
  INSERT INTO public.oop_pricing_audit(request_id,action,revision_id,actor_employee_id,request_hash,result) VALUES(p_request_id,'publish_draft',v_draft.id,v_actor,md5(jsonb_build_object('expectedLockVersion',p_expected_lock_version)::text),v_result); RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."publish_oop_pricing_draft"("p_expected_lock_version" integer, "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qbo_payments_sync_poll"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret     text;
BEGIN
  SELECT value INTO v_worker_url FROM public.integration_config WHERE key = 'qbo_payments_sync_worker_url';
  SELECT value INTO v_secret     FROM public.integration_config WHERE key = 'qbo_webhook_secret';

  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/qbo-payments-sync',
    'https://utahpros.app/api/qbo-payments-sync'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Content-Type',    'application/json',
      'x-webhook-secret', v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );
END;
$$;


ALTER FUNCTION "public"."qbo_payments_sync_poll"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_email_campaign"("p_campaign_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign email_campaigns;
  v_count    int;
BEGIN
  SELECT * INTO v_campaign FROM email_campaigns WHERE id = p_campaign_id;
  IF v_campaign IS NULL THEN
    RAISE EXCEPTION 'Campaign not found';
  END IF;
  IF v_campaign.status NOT IN ('draft', 'sending') THEN
    RAISE EXCEPTION 'Campaign already % — cannot (re)queue', v_campaign.status;
  END IF;

  INSERT INTO email_campaign_recipients (campaign_id, contact_id, email)
  SELECT p_campaign_id, a.contact_id, a.email
  FROM preview_email_audience(v_campaign.audience_filter, v_campaign.org_id) a
  WHERE NOT EXISTS (
    SELECT 1 FROM email_campaign_exclusions ex
    WHERE ex.campaign_id = p_campaign_id AND ex.contact_id = a.contact_id
  )
  ON CONFLICT (campaign_id, contact_id) DO NOTHING;

  SELECT count(*) INTO v_count FROM email_campaign_recipients WHERE campaign_id = p_campaign_id;

  UPDATE email_campaigns SET status = 'sending', audience_count = v_count, updated_at = now() WHERE id = p_campaign_id;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_email_campaign_queued', 'email_campaign', p_campaign_id, jsonb_build_object('recipient_count', v_count));

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."queue_email_campaign"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rearm_callrail_provider_event"("p_event_id" "uuid", "p_expect_error_code" "text", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."message_provider_events"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'rearm_callrail_provider_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  IF p_expect_error_code IS NULL OR btrim(p_expect_error_code) = '' THEN
    RAISE EXCEPTION 'rearm_callrail_provider_event requires the expected error_code'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  UPDATE public.message_provider_events AS event
  SET
    processing_state    = 'received',
    processing_attempts = 0,
    next_attempt_at     = NULL,
    claimed_at          = NULL,
    updated_at          = p_now
  WHERE event.id = p_event_id
    AND event.provider = 'callrail'
    AND event.message_type IN ('sms', 'mms')
    AND event.processing_state = 'failed'
    AND event.error_code = p_expect_error_code
  RETURNING event.*;
END;
$$;


ALTER FUNCTION "public"."rearm_callrail_provider_event"("p_event_id" "uuid", "p_expect_error_code" "text", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rearm_callrail_provider_event"("p_event_id" "uuid", "p_expect_error_code" "text", "p_now" timestamp with time zone) IS 'Service-role only. Moves ONE terminally-failed CallRail sms/mms event back to received so the recovery worker retries it. Requires the exact event id AND its current error_code, so it cannot be used to bulk-reset failures. Preserves error_code/error_message as the audit trail. Returns only the row it changed.';



CREATE OR REPLACE FUNCTION "public"."recompute_estimate_from_lines"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target uuid;
  sub    numeric;
BEGIN
  target := CASE WHEN TG_OP = 'DELETE' THEN OLD.estimate_id ELSE NEW.estimate_id END;
  IF target IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT COALESCE(SUM(line_total), 0) INTO sub FROM estimate_line_items WHERE estimate_id = target;
  UPDATE estimates
     SET subtotal   = sub,
         amount     = sub,
         updated_at = now()
   WHERE id = target;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."recompute_estimate_from_lines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_invoice_from_lines"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target uuid;
  sub    numeric;
BEGIN
  target := CASE WHEN TG_OP = 'DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END;
  IF target IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  SELECT COALESCE(SUM(line_total), 0) INTO sub FROM invoice_line_items WHERE invoice_id = target;
  UPDATE invoices
     SET subtotal   = sub,
         total      = sub + COALESCE(tax, 0),
         updated_at = now()
   WHERE id = target;
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."recompute_invoice_from_lines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_qbo_payment_receipt"("p_receipt" "jsonb", "p_allocations" "jsonb", "p_event_type" "text" DEFAULT 'reconciled'::"text", "p_event_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_receipt_id uuid;
  v_existing_event uuid;
  v_item jsonb;
  v_invoice record;
  v_qbo_realm_id text := NULLIF(btrim(p_receipt->>'qbo_realm_id'), '');
  v_qbo_customer_id text := NULLIF(btrim(p_receipt->>'qbo_customer_id'), '');
  v_qbo_payment_id text := NULLIF(btrim(p_receipt->>'qbo_payment_id'), '');
  v_contact_id uuid;
  v_invoice_ids uuid[] := ARRAY[]::uuid[];
  v_total bigint := (p_receipt->>'total_cents')::bigint;
  v_applied bigint := (p_receipt->>'applied_cents')::bigint;
  v_unapplied bigint := COALESCE((p_receipt->>'unapplied_cents')::bigint, 0);
  v_payment_method text := NULLIF(btrim(p_receipt->>'payment_method'), '');
  v_actor uuid := NULLIF(p_receipt->>'actor_employee_id', '')::uuid;
  v_source text := COALESCE(NULLIF(btrim(p_receipt->>'source'), ''), 'qbo');
  v_sum bigint := 0;
  v_preserve_upr boolean := false;
  v_attempt_id uuid := NULLIF(p_receipt->>'attempt_id', '')::uuid;
  v_existing_receipt public.payment_receipts%ROWTYPE;
  v_incoming_updated_at timestamptz := NULLIF(p_receipt->>'qbo_updated_at', '')::timestamptz;
  v_incoming_sync_token text := NULLIF(btrim(p_receipt->>'qbo_sync_token'), '');
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF p_receipt IS NULL OR jsonb_typeof(p_receipt) <> 'object' OR p_allocations IS NULL
     OR jsonb_typeof(p_allocations) <> 'array' OR jsonb_array_length(p_allocations) = 0
     OR jsonb_array_length(p_allocations) > 100
     OR v_qbo_realm_id IS NULL OR v_qbo_customer_id IS NULL OR v_qbo_payment_id IS NULL
     OR p_event_type <> 'reconciled' THEN RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023'; END IF;
  IF v_total IS NULL OR v_applied IS NULL OR v_total <= 0 OR v_applied <= 0 OR v_unapplied < 0 OR v_total <> v_applied + v_unapplied
     OR v_source NOT IN ('qbo', 'upr', 'manual')
     OR (v_payment_method IS NOT NULL AND v_payment_method NOT IN ('check','ach','eft','credit_card','wire','cash','insurance_direct','other'))
     OR jsonb_typeof(COALESCE(p_receipt->'normalized_snapshot', '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_RECEIPT' USING ERRCODE = '22023';
  END IF;
  IF v_actor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.id = v_actor AND e.is_active IS TRUE AND e.is_external IS FALSE) THEN
    RAISE EXCEPTION 'INVALID_ACTOR' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_qbo_realm_id || ':' || v_qbo_payment_id, 0));
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('qbo-receipt-customer:' || v_qbo_realm_id || ':' || v_qbo_customer_id, 0)
  );
  -- Check the event key only after the per-payment lock. Two Workers can receive
  -- the same webhook envelope concurrently; the second must return a replay
  -- instead of colliding on the unique event-key index.
  IF p_event_key IS NOT NULL THEN
    SELECT id INTO v_existing_event FROM public.payment_receipt_events WHERE event_key = p_event_key;
    IF FOUND THEN RETURN jsonb_build_object('event_id', v_existing_event, 'replayed', true); END IF;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.payment_receipt_events e
    WHERE e.qbo_realm_id = v_qbo_realm_id
      AND e.qbo_payment_id = v_qbo_payment_id
      AND e.event_type IN ('voided', 'deleted')
  ) THEN
    RETURN jsonb_build_object('status', 'terminal', 'ignored_terminal', true, 'replayed', true);
  END IF;
  SELECT * INTO v_existing_receipt
  FROM public.payment_receipts r
  WHERE r.qbo_realm_id = v_qbo_realm_id AND r.qbo_payment_id = v_qbo_payment_id
  FOR UPDATE;
  v_preserve_upr := FOUND AND v_existing_receipt.source = 'upr';
  -- Intuit says webhook notifications may arrive out of order. CDC can also
  -- overlap the webhook. Never let an older provider snapshot replace the
  -- newest accepted allocations; retain the stale event as audit evidence.
  IF FOUND AND (
    (v_existing_receipt.qbo_updated_at IS NOT NULL AND (
      v_incoming_updated_at IS NULL
      OR v_incoming_updated_at < v_existing_receipt.qbo_updated_at
    ))
    OR (
      v_existing_receipt.qbo_sync_token ~ '^[0-9]+$'
      AND (
        v_incoming_updated_at IS NULL
        OR v_existing_receipt.qbo_updated_at IS NULL
        OR v_incoming_updated_at = v_existing_receipt.qbo_updated_at
      )
      AND (
        v_incoming_sync_token IS NULL
        OR v_incoming_sync_token !~ '^[0-9]+$'
        OR v_incoming_sync_token::numeric < v_existing_receipt.qbo_sync_token::numeric
      )
    )
  ) THEN
    INSERT INTO public.payment_receipt_events (
      receipt_id, qbo_realm_id, qbo_payment_id, event_type, event_key, after_snapshot
    ) VALUES (
      v_existing_receipt.id, v_qbo_realm_id, v_qbo_payment_id, p_event_type, p_event_key,
      p_receipt || jsonb_build_object('upr_reconciliation_result', 'ignored_stale')
    );
    RETURN jsonb_build_object(
      'receipt_id', v_existing_receipt.id,
      'status', v_existing_receipt.status,
      'ignored_stale', true,
      'replayed', true
    );
  END IF;
  -- Lock every real allocation invoice in UUID order before any projection.
  PERFORM public.lock_qbo_payment_allocation_invoices(p_allocations);

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
    IF jsonb_typeof(v_item) <> 'object' OR NULLIF(v_item->>'invoice_id', '') IS NULL
       OR NULLIF(v_item->>'qbo_invoice_id', '') IS NULL OR (v_item->>'amount_cents')::bigint <= 0
       OR COALESCE(v_item->>'payer_type', 'homeowner') NOT IN ('insurance','homeowner','other') THEN
      RAISE EXCEPTION 'INVALID_ALLOCATION' USING ERRCODE = '22023';
    END IF;
    SELECT i.id, i.job_id, i.contact_id, i.qbo_invoice_id, c.qbo_customer_id INTO v_invoice
    FROM public.invoices i JOIN public.contacts c ON c.id = i.contact_id
    WHERE i.id = (v_item->>'invoice_id')::uuid FOR SHARE;
    IF NOT FOUND OR v_invoice.qbo_invoice_id IS DISTINCT FROM v_item->>'qbo_invoice_id'
       OR v_invoice.qbo_customer_id IS DISTINCT FROM v_qbo_customer_id
       OR (v_item->>'invoice_id')::uuid = ANY(v_invoice_ids) THEN
      RAISE EXCEPTION 'ALLOCATION_INVOICE_MISMATCH' USING ERRCODE = '23514';
    END IF;
    IF v_contact_id IS NULL THEN v_contact_id := v_invoice.contact_id;
    ELSIF v_contact_id <> v_invoice.contact_id THEN RAISE EXCEPTION 'CROSS_CONTACT_ALLOCATION' USING ERRCODE = '23514'; END IF;
    v_invoice_ids := array_append(v_invoice_ids, (v_item->>'invoice_id')::uuid);
    v_sum := v_sum + (v_item->>'amount_cents')::bigint;
  END LOOP;
  IF v_sum <> v_applied THEN RAISE EXCEPTION 'ALLOCATION_SUM_MISMATCH' USING ERRCODE = '23514'; END IF;
  INSERT INTO public.payment_receipts (
    contact_id, qbo_realm_id, qbo_customer_id, qbo_payment_id, qbo_sync_token, txn_date,
    total_cents, applied_cents, unapplied_cents, payment_method, qbo_payment_method_id,
    qbo_payment_method_name, reference_number, deposit_account_id, deposit_account_name,
    source, status, actor_employee_id, qbo_created_at, qbo_updated_at, normalized_snapshot
  ) VALUES (
    v_contact_id, v_qbo_realm_id, v_qbo_customer_id, v_qbo_payment_id, p_receipt->>'qbo_sync_token',
    (p_receipt->>'txn_date')::date, v_total, v_applied, v_unapplied, v_payment_method,
    p_receipt->>'qbo_payment_method_id', p_receipt->>'qbo_payment_method_name', p_receipt->>'reference_number',
    p_receipt->>'deposit_account_id', p_receipt->>'deposit_account_name', v_source, 'reconciled', v_actor,
    NULLIF(p_receipt->>'qbo_created_at', '')::timestamptz, NULLIF(p_receipt->>'qbo_updated_at', '')::timestamptz,
    COALESCE(p_receipt->'normalized_snapshot', '{}'::jsonb)
  ) ON CONFLICT (qbo_realm_id, qbo_payment_id) WHERE qbo_payment_id IS NOT NULL DO UPDATE SET
    contact_id = EXCLUDED.contact_id, qbo_customer_id = EXCLUDED.qbo_customer_id,
    qbo_sync_token = EXCLUDED.qbo_sync_token, txn_date = EXCLUDED.txn_date, total_cents = EXCLUDED.total_cents,
    applied_cents = EXCLUDED.applied_cents, unapplied_cents = EXCLUDED.unapplied_cents,
    payment_method = EXCLUDED.payment_method, qbo_payment_method_id = EXCLUDED.qbo_payment_method_id,
    qbo_payment_method_name = EXCLUDED.qbo_payment_method_name, reference_number = EXCLUDED.reference_number,
    deposit_account_id = EXCLUDED.deposit_account_id, deposit_account_name = EXCLUDED.deposit_account_name,
    source = CASE
      WHEN public.payment_receipts.source = 'upr' THEN public.payment_receipts.source
      ELSE EXCLUDED.source
    END,
    status = 'reconciled', qbo_updated_at = EXCLUDED.qbo_updated_at,
    normalized_snapshot = EXCLUDED.normalized_snapshot, updated_at = now()
  RETURNING id INTO v_receipt_id;
  SELECT (r.source = 'upr') INTO v_preserve_upr
  FROM public.payment_receipts r WHERE r.id = v_receipt_id;
  DELETE FROM public.payments p WHERE p.receipt_id = v_receipt_id AND NOT (p.invoice_id = ANY(v_invoice_ids));
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
    SELECT i.id, i.job_id, i.contact_id INTO v_invoice FROM public.invoices i WHERE i.id = (v_item->>'invoice_id')::uuid FOR SHARE;
    INSERT INTO public.payments (receipt_id, invoice_id, job_id, contact_id, amount, payment_date, payer_type,
      payment_method, reference_number, recorded_by, source, qbo_payment_id, qbo_realm_id, qbo_synced_at, qbo_sync_error)
    VALUES (v_receipt_id, v_invoice.id, v_invoice.job_id, v_invoice.contact_id,
      ((v_item->>'amount_cents')::numeric / 100), (p_receipt->>'txn_date')::date,
      COALESCE(v_item->>'payer_type', 'homeowner'), v_payment_method, p_receipt->>'reference_number', v_actor,
      v_source, v_qbo_payment_id, v_qbo_realm_id, now(), NULL)
    ON CONFLICT (qbo_payment_id, invoice_id) WHERE qbo_payment_id IS NOT NULL DO UPDATE SET
      receipt_id = EXCLUDED.receipt_id, amount = EXCLUDED.amount, payment_date = EXCLUDED.payment_date,
      payer_type = CASE WHEN v_preserve_upr THEN public.payments.payer_type ELSE EXCLUDED.payer_type END,
      payment_method = EXCLUDED.payment_method,
      qbo_realm_id = EXCLUDED.qbo_realm_id,
      reference_number = EXCLUDED.reference_number, qbo_synced_at = EXCLUDED.qbo_synced_at, qbo_sync_error = NULL;
  END LOOP;
  IF v_attempt_id IS NOT NULL THEN
    UPDATE public.payment_receipt_attempts a
    SET receipt_id = v_receipt_id,
        qbo_payment_id = v_qbo_payment_id,
        provider_snapshot = COALESCE(p_receipt->'normalized_snapshot', '{}'::jsonb),
        status = 'reconciled',
        updated_at = now()
    WHERE a.id = v_attempt_id
      AND a.qbo_realm_id = v_qbo_realm_id
      AND (a.qbo_payment_id IS NULL OR a.qbo_payment_id = v_qbo_payment_id);
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ATTEMPT_RECEIPT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  END IF;
  INSERT INTO public.payment_receipt_events (receipt_id, qbo_realm_id, qbo_payment_id, event_type, event_key, after_snapshot)
  VALUES (v_receipt_id, v_qbo_realm_id, v_qbo_payment_id, p_event_type, p_event_key, p_receipt);
  RETURN jsonb_build_object('receipt_id', v_receipt_id, 'status', 'reconciled', 'replayed', false);
END;
$_$;


ALTER FUNCTION "public"."reconcile_qbo_payment_receipt"("p_receipt" "jsonb", "p_allocations" "jsonb", "p_event_type" "text", "p_event_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_email_campaign_send"("p_recipient_id" "uuid", "p_status" "text", "p_resend_id" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign_id uuid;
  v_pending     int;
  v_sent        int;
  v_suppressed  int;
  v_failed      int;
BEGIN
  IF p_status NOT IN ('sent', 'suppressed', 'failed') THEN
    RAISE EXCEPTION 'invalid recipient status: %', p_status;
  END IF;
  UPDATE email_campaign_recipients
     SET status = p_status,
         resend_id = p_resend_id,
         error_message = p_error_message,
         sent_at = CASE WHEN p_status = 'sent' THEN now() ELSE sent_at END
   WHERE id = p_recipient_id
   RETURNING campaign_id INTO v_campaign_id;
  IF v_campaign_id IS NULL THEN
    RAISE EXCEPTION 'Recipient row not found';
  END IF;
  UPDATE email_campaigns SET
    total_sent       = (SELECT count(*) FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'sent'),
    total_suppressed = (SELECT count(*) FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'suppressed'),
    total_failed      = (SELECT count(*) FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'failed'),
    updated_at = now()
  WHERE id = v_campaign_id;
  SELECT count(*) INTO v_pending FROM email_campaign_recipients WHERE campaign_id = v_campaign_id AND status = 'pending';
  IF v_pending = 0 THEN
    UPDATE email_campaigns SET status = 'sent', sent_at = now(), updated_at = now()
     WHERE id = v_campaign_id AND status = 'sending'
     RETURNING total_sent, total_suppressed, total_failed INTO v_sent, v_suppressed, v_failed;
    IF FOUND THEN
      INSERT INTO system_events (event_type, entity_type, entity_id, payload)
      VALUES ('crm_email_campaign_sent', 'email_campaign', v_campaign_id,
        jsonb_build_object(
          'sent', v_sent, 'suppressed', v_suppressed, 'failed', v_failed,
          'total', COALESCE(v_sent, 0) + COALESCE(v_suppressed, 0) + COALESCE(v_failed, 0)));
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."record_email_campaign_send"("p_recipient_id" "uuid", "p_status" "text", "p_resend_id" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_email_open"("p_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  UPDATE sign_requests
  SET
    email_opened_at  = COALESCE(email_opened_at, now()),
    email_open_count = COALESCE(email_open_count, 0) + 1,
    updated_at       = now()
  WHERE token = p_token
    AND status = 'pending';
END;
$$;


ALTER FUNCTION "public"."record_email_open"("p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_email_suppression"("p_email" "text", "p_reason" "text", "p_source" "text" DEFAULT NULL::"text") RETURNS "public"."email_suppressions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_row public.email_suppressions;
BEGIN
  IF p_email IS NULL OR btrim(p_email) = '' THEN
    RETURN NULL;
  END IF;
  IF p_reason IS NULL OR p_reason NOT IN
       ('unsubscribed', 'bounced', 'complained', 'manual', 'hard_bounce', 'complaint', 'global') THEN
    RAISE EXCEPTION 'invalid suppression reason: %', p_reason;
  END IF;
  v_org := (SELECT id FROM public.crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1);
  INSERT INTO public.email_suppressions (org_id, email, reason, source)
  VALUES (v_org, btrim(p_email), p_reason, p_source)
  ON CONFLICT (lower(email)) DO UPDATE
    SET reason        = CASE WHEN public.email_suppressions.reason = 'unsubscribed'
                             THEN EXCLUDED.reason ELSE public.email_suppressions.reason END,
        source        = COALESCE(EXCLUDED.source, public.email_suppressions.source),
        suppressed_at = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."record_email_suppression"("p_email" "text", "p_reason" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_invoice_activity"("p_invoice_id" "uuid", "p_actor_employee_id" "uuid", "p_event_type" "text", "p_recipient_email" "text" DEFAULT NULL::"text", "p_cc_email" "text" DEFAULT NULL::"text", "p_safe_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_kind text := 'system';
  v_id uuid;
BEGIN
  IF p_invoice_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.invoices i WHERE i.id = p_invoice_id) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: unknown invoice' USING errcode = '22023';
  END IF;

  IF p_actor_employee_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.employees e
      WHERE e.id = p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE
    ) THEN
      RAISE EXCEPTION 'NOT_AUTHORIZED: actor is not an active internal employee' USING errcode = '42501';
    END IF;
    v_actor_kind := 'employee';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_each(COALESCE(p_safe_metadata, '{}'::jsonb)) AS entry(key, value)
    WHERE jsonb_typeof(entry.value) IN ('object', 'array')
  ) THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: activity metadata must be flat scalar values' USING errcode = '22023';
  END IF;

  INSERT INTO public.invoice_activity (
    invoice_id, actor_employee_id, actor_kind, event_type, recipient_email, cc_email, safe_metadata
  ) VALUES (
    p_invoice_id, p_actor_employee_id, v_actor_kind, p_event_type,
    NULLIF(btrim(COALESCE(p_recipient_email, '')), ''),
    NULLIF(btrim(COALESCE(p_cc_email, '')), ''),
    COALESCE(p_safe_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_invoice_activity"("p_invoice_id" "uuid", "p_actor_employee_id" "uuid", "p_event_type" "text", "p_recipient_email" "text", "p_cc_email" "text", "p_safe_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_job_real_flag_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  BEGIN
    v_actor := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL;
  END;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.job_real_flag_history
      (job_id, old_is_real, new_is_real, old_source, new_source,
       old_marked_at, new_marked_at, changed_by)
    VALUES
      (NEW.id, NULL, NEW.is_real_job, NULL, NEW.real_job_source,
       NULL, NEW.real_job_marked_at, v_actor);
  ELSE
    INSERT INTO public.job_real_flag_history
      (job_id, old_is_real, new_is_real, old_source, new_source,
       old_marked_at, new_marked_at, changed_by)
    VALUES
      (OLD.id, OLD.is_real_job, NEW.is_real_job,
       OLD.real_job_source, NEW.real_job_source,
       OLD.real_job_marked_at, NEW.real_job_marked_at, v_actor);
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."record_job_real_flag_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_qbo_connection_cas"("p_expected_environment" "text", "p_expected_realm_id" "text", "p_expected_generation" bigint, "p_access_token" "text", "p_refresh_token" "text", "p_token_expires_at" timestamp with time zone, "p_granted_scopes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_environment text := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_expected_environment, '')));
  v_realm_id text := NULLIF(pg_catalog.btrim(p_expected_realm_id), '');
  v_binding public.qbo_company_binding%ROWTYPE;
  v_connection public.integration_credentials%ROWTYPE;
  v_generation bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  IF v_environment NOT IN ('production', 'sandbox')
     OR v_realm_id IS NULL
     OR p_expected_generation IS NULL
     OR p_expected_generation < 1
     OR NULLIF(pg_catalog.btrim(p_access_token), '') IS NULL
     OR p_token_expires_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-refresh');
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('upr:qbo-company-binding', 0)
  );
  SELECT * INTO v_binding
    FROM public.qbo_company_binding
   WHERE singleton
   FOR UPDATE;
  IF NOT FOUND
     OR v_binding.environment IS DISTINCT FROM v_environment
     OR v_binding.realm_id IS DISTINCT FROM v_realm_id
     OR v_binding.generation IS DISTINCT FROM p_expected_generation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'connection-changed');
  END IF;

  SELECT * INTO v_connection
    FROM public.integration_credentials
   WHERE provider = 'quickbooks'
   FOR UPDATE;
  IF NOT FOUND
     OR v_connection.environment IS DISTINCT FROM v_environment
     OR v_connection.realm_id IS DISTINCT FROM v_realm_id
     OR v_connection.qbo_binding_generation IS DISTINCT FROM p_expected_generation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'connection-changed');
  END IF;

  v_generation := p_expected_generation + 1;
  UPDATE public.qbo_company_binding
     SET generation = v_generation,
         updated_at = now()
   WHERE singleton;
  PERFORM pg_catalog.set_config(
    'upr.qbo_connection_writer_generation',
    v_generation::text,
    true
  );
  UPDATE public.integration_credentials
     SET access_token = p_access_token,
         refresh_token = COALESCE(NULLIF(pg_catalog.btrim(p_refresh_token), ''), v_connection.refresh_token),
         token_expires_at = p_token_expires_at,
         granted_scopes = COALESCE(p_granted_scopes, v_connection.granted_scopes),
         updated_at = now(),
         qbo_binding_generation = v_generation
   WHERE provider = 'quickbooks';
  PERFORM pg_catalog.set_config('upr.qbo_connection_writer_generation', '', true);

  RETURN jsonb_build_object(
    'ok', true,
    'environment', v_environment,
    'realm_id', v_realm_id,
    'generation', v_generation
  );
END;
$$;


ALTER FUNCTION "public"."refresh_qbo_connection_cas"("p_expected_environment" "text", "p_expected_realm_id" "text", "p_expected_generation" bigint, "p_access_token" "text", "p_refresh_token" "text", "p_token_expires_at" timestamp with time zone, "p_granted_scopes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_fixed_automation_claim"("p_automation_key" "text", "p_entity_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_released boolean := false;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'release_fixed_automation_claim is service-role only'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.fixed_automation_claims AS c
  WHERE c.automation_key = p_automation_key
    AND c.entity_id = p_entity_id
    AND c.finalized_at IS NULL;

  GET DIAGNOSTICS v_released = ROW_COUNT;
  RETURN v_released;
END;
$$;


ALTER FUNCTION "public"."release_fixed_automation_claim"("p_automation_key" "text", "p_entity_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_fixed_automation_claim"("p_automation_key" "text", "p_entity_id" "uuid", "p_reason" "text") IS 'Service-only release of a fixed-automation claim that sent nothing (quiet hours, kill-switch, no consent, transient failure). Never releases a finalized claim.';



CREATE OR REPLACE FUNCTION "public"."release_native_push_delivery_claim"("p_delivery_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_released_count integer;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required'
      USING errcode = '42501';
  END IF;

  DELETE FROM public.native_push_delivery_claims
  WHERE delivery_key = p_delivery_key;

  GET DIAGNOSTICS v_released_count = ROW_COUNT;
  RETURN v_released_count > 0;
END;
$$;


ALTER FUNCTION "public"."release_native_push_delivery_claim"("p_delivery_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_qbo_estimate_command_reservation"("p_command_id" "uuid", "p_estimate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE c public.qbo_estimate_commands; r public.qbo_estimate_command_reservations;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE id=p_command_id FOR UPDATE;
 IF FOUND AND (c.estimate_id IS DISTINCT FROM p_estimate_id OR c.status NOT IN ('succeeded','rejected')) THEN RETURN jsonb_build_object('ok',false,'reason','command-not-terminal'); END IF;
 SELECT * INTO r FROM public.qbo_estimate_command_reservations WHERE estimate_id=p_estimate_id FOR UPDATE;
 IF FOUND AND r.command_id IS DISTINCT FROM p_command_id THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
 DELETE FROM public.qbo_estimate_command_reservations WHERE estimate_id=p_estimate_id AND command_id=p_command_id;
 RETURN jsonb_build_object('ok',true,'released',FOUND);
END;$$;


ALTER FUNCTION "public"."release_qbo_estimate_command_reservation"("p_command_id" "uuid", "p_estimate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_qbo_invoice_command_reservation"("p_command_id" "uuid", "p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_reservation public.qbo_invoice_command_reservations;
  v_command public.qbo_invoice_commands;
  v_command_found boolean := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  -- Lock the parent so a concurrent false→true manual lock observes either the
  -- reservation or its definitive local release, never an in-between state.
  PERFORM 1 FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invoice-not-found'); END IF;
  -- Keep the same command→reservation lock order as terminal state changes so
  -- a terminal retry and its original finalizer cannot deadlock each other.
  SELECT * INTO v_command
  FROM public.qbo_invoice_commands
  WHERE id = p_command_id
  FOR UPDATE;
  v_command_found := FOUND;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations
  WHERE invoice_id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', true, 'released', false); END IF;
  IF v_reservation.command_id IS DISTINCT FROM p_command_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reservation-mismatch');
  END IF;
  -- A reservation with no ledger row is the pre-command/local-validation case.
  -- Once preparation has created a command, only its terminal state may release
  -- the manual-lock fence; service-role possession alone is not sufficient.
  IF v_command_found THEN
    IF v_command.invoice_id IS DISTINCT FROM p_invoice_id THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'command-mismatch');
    END IF;
    IF v_command.status NOT IN ('succeeded', 'rejected') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'command-not-terminal',
        'status', v_command.status);
    END IF;
  END IF;
  DELETE FROM public.qbo_invoice_command_reservations WHERE invoice_id = p_invoice_id;
  RETURN jsonb_build_object('ok', true, 'released', true);
END;
$$;


ALTER FUNCTION "public"."release_qbo_invoice_command_reservation"("p_command_id" "uuid", "p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_qbo_payment_allocation_fences"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.status IN ('rejected', 'conflict', 'locally_finalized', 'reconciled', 'voided', 'deleted')
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    DELETE FROM public.qbo_payment_allocation_fences WHERE attempt_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."release_qbo_payment_allocation_fences"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_equipment"("p_equipment_id" "uuid", "p_removed_by" "uuid") RETURNS "public"."equipment_placements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE result equipment_placements;
BEGIN
  UPDATE equipment_placements
     SET status='removed', removed_at=now(), removed_by=p_removed_by
   WHERE id = p_equipment_id AND status='active'
  RETURNING * INTO result;
  IF result.id IS NULL THEN
    SELECT * INTO result FROM equipment_placements WHERE id = p_equipment_id;
  END IF;
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."remove_equipment"("p_equipment_id" "uuid", "p_removed_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_qbo_payment_receipt"("p_qbo_realm_id" "text", "p_qbo_payment_id" "text", "p_status" "text", "p_event_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_receipt public.payment_receipts%ROWTYPE;
  v_removed integer;
  v_attempt_id uuid;
  v_effective_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF NULLIF(btrim(p_qbo_realm_id), '') IS NULL OR NULLIF(btrim(p_qbo_payment_id), '') IS NULL
     OR p_status NOT IN ('conflict', 'voided', 'deleted') THEN RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(btrim(p_qbo_realm_id) || ':' || btrim(p_qbo_payment_id), 0)
  );
  IF p_event_key IS NOT NULL AND EXISTS (SELECT 1 FROM public.payment_receipt_events WHERE event_key = p_event_key) THEN
    RETURN jsonb_build_object('replayed', true);
  END IF;
  SELECT * INTO v_receipt FROM public.payment_receipts
  WHERE qbo_realm_id = btrim(p_qbo_realm_id) AND qbo_payment_id = btrim(p_qbo_payment_id)
  FOR UPDATE;
  IF NOT FOUND THEN
    v_effective_status := p_status;
    UPDATE public.payment_receipt_attempts
    SET status = CASE
          WHEN status = 'deleted' THEN 'deleted'
          WHEN status = 'voided' AND p_status = 'conflict' THEN 'voided'
          ELSE p_status
        END,
        updated_at = now()
    WHERE qbo_realm_id = btrim(p_qbo_realm_id)
      AND qbo_payment_id = btrim(p_qbo_payment_id)
    RETURNING id, status INTO v_attempt_id, v_effective_status;
    IF NOT FOUND THEN v_effective_status := p_status; END IF;
    INSERT INTO public.payment_receipt_events (
      attempt_id, qbo_realm_id, qbo_payment_id, event_type, event_key, after_snapshot
    ) VALUES (
      v_attempt_id, btrim(p_qbo_realm_id), btrim(p_qbo_payment_id), p_status, p_event_key,
      jsonb_build_object('status', v_effective_status, 'tombstone', true)
    );
    RETURN jsonb_build_object('removed', 0, 'missing', true, 'tombstone', true, 'status', v_effective_status);
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'qbo-receipt-customer:' || v_receipt.qbo_realm_id || ':' || v_receipt.qbo_customer_id,
      0
    )
  );
  DELETE FROM public.payments WHERE receipt_id = v_receipt.id;
  GET DIAGNOSTICS v_removed = ROW_COUNT;
  v_effective_status := CASE
    WHEN v_receipt.status = 'deleted' THEN 'deleted'
    WHEN v_receipt.status = 'voided' AND p_status = 'conflict' THEN 'voided'
    ELSE p_status
  END;
  UPDATE public.payment_receipts SET status = v_effective_status, updated_at = now() WHERE id = v_receipt.id;
  UPDATE public.payment_receipt_attempts
  SET receipt_id = COALESCE(receipt_id, v_receipt.id),
      status = v_effective_status,
      updated_at = now()
  WHERE receipt_id = v_receipt.id
     OR (
       qbo_realm_id = v_receipt.qbo_realm_id
       AND qbo_payment_id = v_receipt.qbo_payment_id
     );
  INSERT INTO public.payment_receipt_events (receipt_id, qbo_realm_id, qbo_payment_id, event_type, event_key, after_snapshot)
  VALUES (v_receipt.id, v_receipt.qbo_realm_id, v_receipt.qbo_payment_id, p_status, p_event_key, jsonb_build_object('status', v_effective_status));
  RETURN jsonb_build_object('receipt_id', v_receipt.id, 'removed', v_removed, 'status', v_effective_status, 'replayed', false);
END;
$$;


