CREATE OR REPLACE FUNCTION "public"."replace_qbo_connection"("p_environment" "text", "p_realm_id" "text", "p_access_token" "text", "p_refresh_token" "text", "p_token_expires_at" timestamp with time zone, "p_granted_scopes" "text" DEFAULT NULL::"text", "p_connected_by" "uuid" DEFAULT NULL::"uuid", "p_connected_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_environment text;
  v_realm_id text := NULLIF(pg_catalog.btrim(p_realm_id), '');
  v_binding public.qbo_company_binding%ROWTYPE;
  v_has_artifacts boolean;
  v_generation bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  v_environment := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_environment, '')));
  IF v_environment NOT IN ('production', 'sandbox')
     OR v_realm_id IS NULL
     OR NULLIF(pg_catalog.btrim(p_access_token), '') IS NULL
     OR NULLIF(pg_catalog.btrim(p_refresh_token), '') IS NULL
     OR p_token_expires_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-connection');
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('upr:qbo-company-binding', 0)
  );
  SELECT * INTO v_binding
    FROM public.qbo_company_binding
   WHERE singleton
   FOR UPDATE;
  IF FOUND THEN
    IF v_binding.environment IS DISTINCT FROM v_environment
       OR v_binding.realm_id IS DISTINCT FROM v_realm_id THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'realm-mismatch',
        'environment', v_binding.environment,
        'realm_id', v_binding.realm_id,
        'generation', v_binding.generation
      );
    END IF;
    v_generation := v_binding.generation + 1;
    UPDATE public.qbo_company_binding
       SET generation = v_generation,
           updated_at = now()
     WHERE singleton;
  ELSE
    SELECT
      EXISTS (
        SELECT 1 FROM public.integration_credentials
         WHERE provider = 'quickbooks'
           AND (
             NULLIF(pg_catalog.btrim(realm_id), '') IS NOT NULL
             OR NULLIF(pg_catalog.btrim(access_token), '') IS NOT NULL
             OR NULLIF(pg_catalog.btrim(refresh_token), '') IS NOT NULL
           )
      )
      OR EXISTS (SELECT 1 FROM public.payments WHERE NULLIF(pg_catalog.btrim(qbo_realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.payment_receipts WHERE NULLIF(pg_catalog.btrim(qbo_realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.payment_receipt_attempts WHERE NULLIF(pg_catalog.btrim(qbo_realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.qbo_payment_allocation_fences WHERE NULLIF(pg_catalog.btrim(qbo_realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.qbo_invoice_commands WHERE NULLIF(pg_catalog.btrim(realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.qbo_invoice_command_reservations WHERE NULLIF(pg_catalog.btrim(realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.qbo_estimate_commands WHERE NULLIF(pg_catalog.btrim(realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.qbo_estimate_command_reservations WHERE NULLIF(pg_catalog.btrim(realm_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.contacts WHERE NULLIF(pg_catalog.btrim(qbo_customer_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.invoices WHERE NULLIF(pg_catalog.btrim(qbo_invoice_id), '') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM public.estimates WHERE NULLIF(pg_catalog.btrim(qbo_estimate_id), '') IS NOT NULL)
      OR EXISTS (
        SELECT 1 FROM public.payments
         WHERE NULLIF(pg_catalog.btrim(qbo_payment_id), '') IS NOT NULL
            OR NULLIF(pg_catalog.btrim(stripe_fee_qbo_purchase_id), '') IS NOT NULL
      )
      OR EXISTS (SELECT 1 FROM public.qbo_attachments WHERE NULLIF(pg_catalog.btrim(qbo_attachable_id), '') IS NOT NULL)
      OR EXISTS (
        SELECT 1 FROM public.invoice_line_items
         WHERE NULLIF(pg_catalog.btrim(qbo_item_id), '') IS NOT NULL
            OR NULLIF(pg_catalog.btrim(qbo_class_id), '') IS NOT NULL
      )
      OR EXISTS (
        SELECT 1 FROM public.estimate_line_items
         WHERE NULLIF(pg_catalog.btrim(qbo_item_id), '') IS NOT NULL
            OR NULLIF(pg_catalog.btrim(qbo_class_id), '') IS NOT NULL
      )
      OR EXISTS (
        SELECT 1 FROM public.integration_config
         WHERE key IN (
           'qbo_stripe_clearing_account_id',
           'qbo_fee_expense_account_id',
           'qbo_bank_account_id'
         )
           AND NULLIF(pg_catalog.btrim(value), '') IS NOT NULL
      )
      INTO v_has_artifacts;

    IF v_has_artifacts THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'unscoped-links');
    END IF;
    v_generation := 1;
    INSERT INTO public.qbo_company_binding(singleton, environment, realm_id, generation)
    VALUES(true, v_environment, v_realm_id, v_generation);
  END IF;

  PERFORM pg_catalog.set_config(
    'upr.qbo_connection_writer_generation',
    v_generation::text,
    true
  );
  INSERT INTO public.integration_credentials(
    provider, access_token, refresh_token, realm_id, environment,
    token_expires_at, granted_scopes, connected_by, connected_at,
    updated_at, qbo_binding_generation
  ) VALUES(
    'quickbooks', p_access_token, p_refresh_token, v_realm_id, v_environment,
    p_token_expires_at, p_granted_scopes, p_connected_by,
    COALESCE(p_connected_at, now()), now(), v_generation
  )
  ON CONFLICT (provider) DO UPDATE SET
    access_token = EXCLUDED.access_token,
    refresh_token = EXCLUDED.refresh_token,
    realm_id = EXCLUDED.realm_id,
    environment = EXCLUDED.environment,
    token_expires_at = EXCLUDED.token_expires_at,
    granted_scopes = COALESCE(EXCLUDED.granted_scopes, public.integration_credentials.granted_scopes),
    connected_by = EXCLUDED.connected_by,
    connected_at = EXCLUDED.connected_at,
    updated_at = EXCLUDED.updated_at,
    qbo_binding_generation = EXCLUDED.qbo_binding_generation;
  PERFORM pg_catalog.set_config('upr.qbo_connection_writer_generation', '', true);

  RETURN jsonb_build_object(
    'ok', true,
    'environment', v_environment,
    'realm_id', v_realm_id,
    'generation', v_generation
  );
END;
$$;


ALTER FUNCTION "public"."replace_qbo_connection"("p_environment" "text", "p_realm_id" "text", "p_access_token" "text", "p_refresh_token" "text", "p_token_expires_at" timestamp with time zone, "p_granted_scopes" "text", "p_connected_by" "uuid", "p_connected_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_account_deletion"("p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."account_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_emp public.employees%ROWTYPE;
  v_row public.account_deletion_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_emp
  FROM public.employees
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_emp.id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: no employee for caller' USING errcode = '42501';
  END IF;

  SELECT * INTO v_row
  FROM public.account_deletion_requests
  WHERE employee_id = v_emp.id AND status = 'pending'
  ORDER BY requested_at DESC
  LIMIT 1;

  IF v_row.id IS NOT NULL THEN
    RETURN v_row;
  END IF;

  BEGIN
    INSERT INTO public.account_deletion_requests (employee_id, notes)
    VALUES (v_emp.id, NULLIF(btrim(p_notes), ''))
    RETURNING * INTO v_row;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_row
    FROM public.account_deletion_requests
    WHERE employee_id = v_emp.id AND status = 'pending'
    ORDER BY requested_at DESC
    LIMIT 1;
    RETURN v_row;
  END;

  INSERT INTO public.notifications (type, title, body, entity_type, entity_id, recipient_id)
  SELECT
    'account_deletion_requested',
    'Account deletion requested',
    COALESCE(v_emp.full_name, 'An employee')
      || ' requested that their account be deleted. Deactivate their access and handle data retention per policy.',
    'employee',
    v_emp.id,
    a.id
  FROM public.employees a
  WHERE a.role = 'admin' AND a.is_active;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."request_account_deletion"("p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_qbo_estimate_command"("p_command_id" "uuid", "p_estimate_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_request_hash" "text", "p_prerequisite" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE e public.estimates; c public.qbo_estimate_commands; r public.qbo_estimate_command_reservations;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 IF p_command_id IS NULL OR p_estimate_id IS NULL OR p_action NOT IN ('save','send','delete') OR p_initiator IS DISTINCT FROM 'browser' OR p_actor_auth_user_id IS NULL OR p_actor_employee_id IS NULL OR NULLIF(p_realm_id,'') IS NULL OR COALESCE(p_request_hash,'') !~ '^[0-9a-f]{64}$' OR jsonb_typeof(p_prerequisite) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-command'); END IF;
 IF p_action='save' THEN
  IF p_prerequisite->>'kind' IS DISTINCT FROM 'customer_sync'
     OR COALESCE(p_prerequisite-'kind'-'contact_id'-'primary_request_id','{}'::jsonb)<>'{}'::jsonb
     OR COALESCE(p_prerequisite->>'contact_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR COALESCE(p_prerequisite->>'primary_request_id','') !~ '^[A-Za-z0-9._-]{1,50}$' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-prerequisite'); END IF;
 ELSIF p_prerequisite<>'{}'::jsonb THEN RETURN jsonb_build_object('ok',false,'reason','invalid-prerequisite'); END IF;
 SELECT * INTO e FROM public.estimates WHERE id=p_estimate_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','estimate-not-found'); END IF;
 IF e.converted_invoice_id IS NOT NULL OR e.status IN ('approved','denied','paid') THEN RETURN jsonb_build_object('ok',false,'reason','estimate-terminal'); END IF;
 IF p_action='save' AND COALESCE(e.contact_id,(SELECT j.primary_contact_id FROM public.jobs j WHERE j.id=e.job_id))::text IS DISTINCT FROM p_prerequisite->>'contact_id' THEN RETURN jsonb_build_object('ok',false,'reason','prerequisite-source-mismatch'); END IF;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE estimate_id=p_estimate_id AND status IN ('prepared','provider_started','ambiguous','provider_succeeded','needs_reconciliation') FOR UPDATE;
 IF FOUND AND (c.id IS DISTINCT FROM p_command_id OR c.action IS DISTINCT FROM p_action OR c.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR c.actor_employee_id IS DISTINCT FROM p_actor_employee_id OR c.realm_id IS DISTINCT FROM p_realm_id OR c.request_hash IS DISTINCT FROM p_request_hash) THEN RETURN jsonb_build_object('ok',false,'reason','active-command-conflict'); END IF;
 SELECT * INTO r FROM public.qbo_estimate_command_reservations WHERE estimate_id=p_estimate_id FOR UPDATE;
 IF FOUND THEN
  IF r.command_id=p_command_id AND r.action=p_action AND r.actor_auth_user_id=p_actor_auth_user_id AND r.actor_employee_id=p_actor_employee_id AND r.realm_id=p_realm_id AND r.request_hash=p_request_hash AND r.prerequisite_payload=p_prerequisite THEN RETURN jsonb_build_object('ok',true,'replay',true); END IF;
  RETURN jsonb_build_object('ok',false,'reason','active-command-conflict');
 END IF;
 INSERT INTO public.qbo_estimate_command_reservations(estimate_id,command_id,action,actor_auth_user_id,actor_employee_id,initiator,realm_id,request_hash,prerequisite_payload) VALUES(p_estimate_id,p_command_id,p_action,p_actor_auth_user_id,p_actor_employee_id,'browser',p_realm_id,p_request_hash,p_prerequisite);
 RETURN jsonb_build_object('ok',true,'reserved',true);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('ok',false,'reason','active-command-conflict'); END;$_$;


ALTER FUNCTION "public"."reserve_qbo_estimate_command"("p_command_id" "uuid", "p_estimate_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_request_hash" "text", "p_prerequisite" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_qbo_invoice_command"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_invoice public.invoices;
  v_reservation public.qbo_invoice_command_reservations;
  v_active public.qbo_invoice_commands;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  IF p_command_id IS NULL OR p_invoice_id IS NULL
     OR p_action NOT IN ('save', 'send', 'delete')
     OR p_initiator NOT IN ('browser', 'webhook')
     OR p_realm_id IS NULL
     OR (p_initiator = 'browser' AND p_actor_auth_user_id IS NULL)
     OR (p_initiator = 'webhook' AND (p_actor_auth_user_id IS NOT NULL OR p_actor_employee_id IS NOT NULL)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-command');
  END IF;
  SELECT * INTO v_invoice FROM public.invoices
  WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invoice-not-found');
  END IF;
  IF v_invoice.locked IS TRUE THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invoice-locked');
  END IF;
  -- Rolling deploys can encounter a pre-reservation command. Never install a
  -- different reservation in front of it: only the exact same command and
  -- frozen identity may acquire the missing fence and resume.
  SELECT * INTO v_active
  FROM public.qbo_invoice_commands
  WHERE invoice_id = p_invoice_id
    AND status IN ('prepared', 'provider_started', 'ambiguous', 'provider_succeeded', 'needs_reconciliation')
  FOR UPDATE;
  IF FOUND AND (
    v_active.id IS DISTINCT FROM p_command_id
    OR v_active.action IS DISTINCT FROM p_action
    OR v_active.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id
    OR v_active.actor_employee_id IS DISTINCT FROM p_actor_employee_id
    OR v_active.initiator IS DISTINCT FROM p_initiator
    OR v_active.realm_id IS DISTINCT FROM p_realm_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'active-command-conflict',
      'command_id', v_active.id, 'status', v_active.status);
  END IF;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations
  WHERE invoice_id = p_invoice_id FOR UPDATE;
  IF FOUND THEN
    IF v_reservation.command_id = p_command_id
       AND v_reservation.action = p_action
       AND v_reservation.actor_auth_user_id IS NOT DISTINCT FROM p_actor_auth_user_id
       AND v_reservation.actor_employee_id IS NOT DISTINCT FROM p_actor_employee_id
       AND v_reservation.initiator IS NOT DISTINCT FROM p_initiator
       AND v_reservation.realm_id IS NOT DISTINCT FROM p_realm_id THEN
      RETURN jsonb_build_object('ok', true, 'replay', true,
        'command_id', v_reservation.command_id, 'action', v_reservation.action);
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'active-command-conflict',
      'command_id', v_reservation.command_id);
  END IF;
  INSERT INTO public.qbo_invoice_command_reservations (
    invoice_id, command_id, action, actor_auth_user_id, actor_employee_id, initiator, realm_id
  ) VALUES (
    p_invoice_id, p_command_id, p_action, p_actor_auth_user_id, p_actor_employee_id, p_initiator, p_realm_id
  );
  RETURN jsonb_build_object('ok', true, 'reserved', true,
    'command_id', p_command_id, 'action', p_action);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('ok', false, 'reason', 'active-command-conflict');
END;
$$;


ALTER FUNCTION "public"."reserve_qbo_invoice_command"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_action" "text", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_qbo_payment_receipt"("p_client_request_id" "text", "p_intuit_request_id" "text", "p_realm_id" "text", "p_request_fingerprint" "text", "p_request" "jsonb", "p_actor_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_attempt public.payment_receipt_attempts%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF NULLIF(btrim(p_client_request_id), '') IS NULL
     OR NULLIF(btrim(p_intuit_request_id), '') IS NULL
     OR NULLIF(btrim(p_realm_id), '') IS NULL
     OR NULLIF(btrim(p_request_fingerprint), '') IS NULL
     OR p_request IS NULL OR jsonb_typeof(p_request) <> 'object' THEN
    RAISE EXCEPTION 'INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;
  IF p_actor_employee_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = p_actor_employee_id AND e.is_active IS TRUE AND e.is_external IS FALSE
  ) THEN RAISE EXCEPTION 'INVALID_ACTOR' USING ERRCODE = '42501'; END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_realm_id || ':' || p_client_request_id, 0));
  SELECT * INTO v_attempt FROM public.payment_receipt_attempts
  WHERE qbo_realm_id = p_realm_id AND client_request_id = p_client_request_id
  FOR UPDATE;
  IF FOUND THEN
    IF v_attempt.request_fingerprint <> p_request_fingerprint THEN
      RAISE EXCEPTION 'CLIENT_REQUEST_ID_CONFLICT' USING ERRCODE = '23505';
    END IF;
    -- Migration-first compatibility: an old deployed worker already calls this
    -- frozen RPC before its provider write. A nonterminal pre-fence attempt is
    -- bound to its original request on replay, never a new allocation shape.
    IF v_attempt.status IN ('submitting', 'qbo_created', 'unknown_outcome') THEN
      PERFORM public.establish_qbo_payment_allocation_fences(v_attempt.id, v_attempt.qbo_realm_id, v_attempt.request_payload);
    END IF;
    RETURN jsonb_build_object('attempt_id', v_attempt.id, 'receipt_id', v_attempt.receipt_id,
      'status', v_attempt.status, 'replayed', true, 'qbo_payment_id', v_attempt.qbo_payment_id);
  END IF;

  INSERT INTO public.payment_receipt_attempts (
    client_request_id, intuit_request_id, qbo_realm_id, request_fingerprint,
    request_payload, actor_employee_id, status
  ) VALUES (
    btrim(p_client_request_id), btrim(p_intuit_request_id), btrim(p_realm_id),
    btrim(p_request_fingerprint), p_request, p_actor_employee_id, 'submitting'
  ) RETURNING * INTO v_attempt;
  PERFORM public.establish_qbo_payment_allocation_fences(v_attempt.id, v_attempt.qbo_realm_id, v_attempt.request_payload);
  INSERT INTO public.payment_receipt_events (attempt_id, qbo_realm_id, event_type, after_snapshot)
  VALUES (v_attempt.id, v_attempt.qbo_realm_id, 'reserved', jsonb_build_object('status', v_attempt.status));
  RETURN jsonb_build_object('attempt_id', v_attempt.id, 'status', v_attempt.status, 'replayed', false);
END;
$$;


ALTER FUNCTION "public"."reserve_qbo_payment_receipt"("p_client_request_id" "text", "p_intuit_request_id" "text", "p_realm_id" "text", "p_request_fingerprint" "text", "p_request" "jsonb", "p_actor_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_provider_event"("p_event_id" "uuid", "p_resolved_by" "uuid" DEFAULT NULL::"uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."message_provider_events"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'resolve_provider_event is service-role only'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  UPDATE public.message_provider_events AS event
  SET
    resolved_at = p_now,
    resolved_by = p_resolved_by,
    updated_at  = p_now
  WHERE event.id = p_event_id
    AND event.processing_state = 'failed'
    AND event.resolved_at IS NULL
  RETURNING event.*;
END;
$$;


ALTER FUNCTION "public"."resolve_provider_event"("p_event_id" "uuid", "p_resolved_by" "uuid", "p_now" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_provider_event"("p_event_id" "uuid", "p_resolved_by" "uuid", "p_now" timestamp with time zone) IS 'Service-role only. Marks ONE terminally-failed event acknowledged so ops-health stops alerting on it. Only touches processing_state=failed rows that are not already resolved, so it is idempotent and cannot silence an in-flight event. Returns only the row it changed.';



CREATE TABLE IF NOT EXISTS "public"."time_entry_change_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entry_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "proposed" "jsonb" NOT NULL,
    "tech_note" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reviewed_by" "uuid",
    "review_note" "text",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "time_entry_change_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."time_entry_change_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_time_entry_change_request"("p_request_id" "uuid", "p_approve" boolean, "p_actor_id" "uuid", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "public"."time_entry_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_req time_entry_change_requests%ROWTYPE; v_e job_time_entries%ROWTYPE; v_p jsonb;
begin
  if not is_time_admin(p_actor_id) then raise exception 'NOT_AUTHORIZED' using errcode='P0001'; end if;
  select * into v_req from time_entry_change_requests where id=p_request_id;
  if v_req.id is null then raise exception 'REQUEST_NOT_FOUND' using errcode='P0001'; end if;
  if v_req.status <> 'pending' then raise exception 'REQUEST_ALREADY_REVIEWED' using errcode='P0001'; end if;
  if p_approve then
    select * into v_e from job_time_entries where id=v_req.entry_id;
    if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
    v_p := v_req.proposed;
    perform admin_upsert_time_entry(p_actor_id=>p_actor_id, p_id=>v_e.id, p_employee_id=>v_e.employee_id, p_job_id=>v_e.job_id,
      p_work_date=>coalesce((v_p->>'work_date')::date, v_e.work_date), p_hours=>coalesce((v_p->>'hours')::numeric, v_e.hours),
      p_clock_in=>coalesce((v_p->>'clock_in')::timestamptz, v_e.clock_in), p_clock_out=>coalesce((v_p->>'clock_out')::timestamptz, v_e.clock_out),
      p_travel_start=>v_e.travel_start, p_on_site_end=>v_e.on_site_end, p_travel_minutes=>coalesce((v_p->>'travel_minutes')::numeric, v_e.travel_minutes),
      p_total_paused_minutes=>v_e.total_paused_minutes, p_work_type=>v_e.work_type, p_description=>coalesce(v_p->>'description', v_e.description),
      p_notes=>coalesce(v_p->>'notes', v_e.notes), p_override_approved=>true);
  end if;
  update time_entry_change_requests set status=case when p_approve then 'approved' else 'rejected' end, reviewed_by=p_actor_id, review_note=p_review_note, reviewed_at=now() where id=p_request_id returning * into v_req;
  perform notify_emit('timesheet.change_reviewed', jsonb_build_object(
    'employee_id', v_req.requested_by,
    'title', case when p_approve then 'Timesheet change approved' else 'Timesheet change rejected' end,
    'body', coalesce(nullif(p_review_note,''), case when p_approve then 'Your requested correction was approved.' else 'Your requested correction was declined.' end),
    'link', '/time-tracking',
    'entity_type', 'time_entry_change_request',
    'entity_id', v_req.id,
    'payload', jsonb_build_object('entry_id', v_req.entry_id, 'approved', p_approve)
  ));
  insert into system_events (event_type, entity_type, entity_id, actor_id, job_id, payload) values ('time_entry.change_reviewed','time_entry_change_request', v_req.id, p_actor_id, null, jsonb_build_object('approved', p_approve, 'entry_id', v_req.entry_id));
  return v_req;
end; $$;


ALTER FUNCTION "public"."review_time_entry_change_request"("p_request_id" "uuid", "p_approve" boolean, "p_actor_id" "uuid", "p_review_note" "text") OWNER TO "postgres";


