CREATE OR REPLACE FUNCTION "public"."save_demo_sheet"("p_id" "uuid", "p_data" "jsonb", "p_job_date" "date", "p_tech_id" "uuid", "p_job_number" "text", "p_address" "text", "p_insured_name" "text", "p_encircle_claim_id" "text", "p_status" "text" DEFAULT 'draft'::"text", "p_encircle_note_id" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_summary" "jsonb" DEFAULT NULL::"jsonb", "p_email_sent" boolean DEFAULT NULL::boolean, "p_schema_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id UUID;
  v_tech_name TEXT;
  v_schema_id UUID;
BEGIN
  IF p_tech_id IS NOT NULL THEN
    SELECT COALESCE(display_name, full_name) INTO v_tech_name
    FROM employees WHERE id = p_tech_id;
  END IF;

  IF p_id IS NULL THEN
    v_schema_id := p_schema_id;
    IF v_schema_id IS NULL THEN
      SELECT id INTO v_schema_id FROM demo_sheet_schemas WHERE is_active = true LIMIT 1;
    END IF;

    INSERT INTO forms (
      form_type, form_data, summary, form_date, technician_name,
      submitted_by, status, encircle_claim_id, encircle_note_id,
      encircle_synced_at, email_sent, email_sent_at, job_id, schema_id
    )
    VALUES (
      'demo_sheet', p_data, COALESCE(p_summary, '{}'::jsonb), p_job_date, v_tech_name,
      p_tech_id, p_status, p_encircle_claim_id, p_encircle_note_id,
      CASE WHEN p_encircle_note_id IS NOT NULL THEN now() ELSE NULL END,
      COALESCE(p_email_sent, false),
      CASE WHEN p_email_sent THEN now() ELSE NULL END,
      p_job_id, v_schema_id
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE forms SET
      form_data = p_data,
      summary   = COALESCE(p_summary, summary),
      form_date = p_job_date,
      technician_name = COALESCE(v_tech_name, technician_name),
      submitted_by = COALESCE(p_tech_id, submitted_by),
      status = p_status,
      encircle_claim_id = p_encircle_claim_id,
      encircle_note_id = COALESCE(p_encircle_note_id, encircle_note_id),
      encircle_synced_at = CASE
        WHEN p_encircle_note_id IS NOT NULL AND encircle_synced_at IS NULL THEN now()
        ELSE encircle_synced_at
      END,
      email_sent = CASE
        WHEN p_email_sent IS NOT NULL THEN p_email_sent
        ELSE email_sent
      END,
      email_sent_at = CASE
        WHEN p_email_sent = true AND email_sent_at IS NULL THEN now()
        ELSE email_sent_at
      END,
      job_id = COALESCE(p_job_id, job_id),
      updated_at = now()
    WHERE id = p_id AND form_type = 'demo_sheet'
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."save_demo_sheet"("p_id" "uuid", "p_data" "jsonb", "p_job_date" "date", "p_tech_id" "uuid", "p_job_number" "text", "p_address" "text", "p_insured_name" "text", "p_encircle_claim_id" "text", "p_status" "text", "p_encircle_note_id" "text", "p_job_id" "uuid", "p_summary" "jsonb", "p_email_sent" boolean, "p_schema_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_estimate_lines"("p_id" "uuid", "p_lines" "jsonb" DEFAULT '[]'::"jsonb", "p_kind" "text" DEFAULT 'estimate'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'save_estimate_lines: p_id is required';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('estimate', 'invoice') THEN
    RAISE EXCEPTION 'save_estimate_lines: p_kind must be ''estimate'' or ''invoice'' (got %)', p_kind;
  END IF;

  IF p_kind = 'estimate' THEN
    DELETE FROM public.estimate_line_items WHERE estimate_id = p_id;

    INSERT INTO public.estimate_line_items
      (estimate_id, description, xactimate_code, quantity, unit, unit_price,
       qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name, sort_order)
    SELECT
      p_id,
      COALESCE(elem->>'description', ''),
      elem->>'xactimate_code',
      COALESCE(NULLIF(elem->>'quantity', '')::numeric, 1),
      elem->>'unit',
      COALESCE(NULLIF(elem->>'unit_price', '')::numeric, 0),
      elem->>'qbo_item_id',
      elem->>'qbo_item_name',
      elem->>'qbo_class_id',
      elem->>'qbo_class_name',
      COALESCE(NULLIF(elem->>'sort_order', '')::int, (n - 1)::int)
    FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb)) WITH ORDINALITY AS arr(elem, n);

    SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order, e.created_at), '[]'::jsonb)
      INTO v_result
      FROM public.estimate_line_items e
     WHERE e.estimate_id = p_id;
  ELSE
    DELETE FROM public.invoice_line_items WHERE invoice_id = p_id;

    INSERT INTO public.invoice_line_items
      (invoice_id, description, xactimate_code, quantity, unit, unit_price,
       qbo_item_id, qbo_item_name, qbo_class_id, qbo_class_name, sort_order)
    SELECT
      p_id,
      COALESCE(elem->>'description', ''),
      elem->>'xactimate_code',
      COALESCE(NULLIF(elem->>'quantity', '')::numeric, 1),
      elem->>'unit',
      COALESCE(NULLIF(elem->>'unit_price', '')::numeric, 0),
      elem->>'qbo_item_id',
      elem->>'qbo_item_name',
      elem->>'qbo_class_id',
      elem->>'qbo_class_name',
      COALESCE(NULLIF(elem->>'sort_order', '')::int, (n - 1)::int)
    FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb)) WITH ORDINALITY AS arr(elem, n);

    SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order, e.created_at), '[]'::jsonb)
      INTO v_result
      FROM public.invoice_line_items e
     WHERE e.invoice_id = p_id;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."save_estimate_lines"("p_id" "uuid", "p_lines" "jsonb", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_homebuilding_build_project"("p_id" "uuid", "p_label" "text", "p_region" "text", "p_spec" "jsonb", "p_plan" "jsonb") RETURNS "public"."homebuilding_build_projects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r public.homebuilding_build_projects;
