    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "phase_key" "text" NOT NULL,
    "title" "text" NOT NULL,
    "status" "text" DEFAULT 'todo'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "crm_build_stages_status_check" CHECK (("status" = ANY (ARRAY['todo'::"text", 'in_progress'::"text", 'done'::"text"])))
);


ALTER TABLE "public"."crm_build_stages" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_crm_stage_status"("p_stage_id" "uuid", "p_status" "text") RETURNS "public"."crm_build_stages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row crm_build_stages;
BEGIN
  IF p_status NOT IN ('todo', 'in_progress', 'done') THEN
    RAISE EXCEPTION 'invalid crm stage status: %', p_status;
  END IF;

  UPDATE crm_build_stages
     SET status = p_status
   WHERE id = p_stage_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown crm stage id: %', p_stage_id;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_crm_stage_status"("p_stage_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_default_conversation_member"("p_employee_id" "uuid", "p_included" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_id uuid;
BEGIN
  IF NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'set_default_conversation_member is admin-only'
      USING ERRCODE = '42501';
  END IF;

  SELECT employee.id
    INTO v_actor_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active
    AND NOT employee.is_external
    AND employee.role::text = 'admin'
  LIMIT 1;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.is_active
      AND NOT employee.is_external
      AND employee.role::text = 'field_tech'
  ) THEN
    RAISE EXCEPTION 'default chat members must be active internal field technicians'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_included, false) THEN
    INSERT INTO public.conversation_default_members (employee_id, added_by, added_at)
    VALUES (p_employee_id, v_actor_id, now())
    ON CONFLICT (employee_id)
    DO UPDATE SET
      added_by = EXCLUDED.added_by,
      added_at = EXCLUDED.added_at;
  ELSE
    DELETE FROM public.conversation_default_members default_member
    WHERE default_member.employee_id = p_employee_id;
  END IF;
END;
$$;


