CREATE TABLE IF NOT EXISTS "public"."notification_employee_overrides" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "type_key" "text" NOT NULL,
    "channel" "text" NOT NULL,
    "enabled" boolean NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "notification_employee_overrides_channel_check" CHECK (("channel" = ANY (ARRAY['bell'::"text", 'push'::"text", 'email'::"text"])))
);


ALTER TABLE "public"."notification_employee_overrides" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_employee_notification_override"("p_employee_id" "uuid", "p_type_key" "text", "p_channel" "text", "p_enabled" boolean, "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."notification_employee_overrides"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.notification_employee_overrides;
  v_actor uuid;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  SELECT e.id INTO v_actor FROM public.employees e WHERE e.auth_user_id = auth.uid();

  INSERT INTO public.notification_employee_overrides
    (employee_id, type_key, channel, enabled, updated_at, updated_by)
  VALUES
    (p_employee_id, p_type_key, p_channel, p_enabled, now(), COALESCE(v_actor, p_actor_id))
  ON CONFLICT (employee_id, type_key, channel) DO UPDATE
    SET enabled    = EXCLUDED.enabled,
        updated_at = now(),
        updated_by = COALESCE(v_actor, p_actor_id)
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_employee_notification_override"("p_employee_id" "uuid", "p_type_key" "text", "p_channel" "text", "p_enabled" boolean, "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_integration_secret"("p_provider" "text", "p_secret" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.p9_assert_admin();

  IF p_provider NOT IN ('stripe', 'twilio', 'resend') THEN
    RAISE EXCEPTION 'INVALID_PROVIDER: %', p_provider USING errcode = '22023';
  END IF;
  IF p_secret IS NULL OR btrim(p_secret) = '' THEN
    RAISE EXCEPTION 'EMPTY_SECRET' USING errcode = '22023';
  END IF;

  INSERT INTO integration_credentials (provider, access_token, environment,
                                       connected_by, connected_at, updated_at)
  VALUES (p_provider, p_secret, 'production',
          (SELECT id FROM employees WHERE auth_user_id = auth.uid() LIMIT 1),
          now(), now())
  ON CONFLICT (provider) DO UPDATE
    SET access_token = EXCLUDED.access_token,
        connected_by = EXCLUDED.connected_by,
        connected_at = COALESCE(integration_credentials.connected_at, EXCLUDED.connected_at),
        updated_at   = now();
END;
$$;


ALTER FUNCTION "public"."set_integration_secret"("p_provider" "text", "p_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_invoice_send_presentation"("p_invoice_id" "uuid", "p_customer_message" "text" DEFAULT NULL::"text", "p_cc_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_role text;
  v_employee_id uuid;
  v_message text := NULLIF(btrim(COALESCE(p_customer_message, '')), '');
  v_cc text := NULLIF(btrim(COALESCE(p_cc_email, '')), '');
  v_locked boolean;
BEGIN
  SELECT e.id, e.role::text INTO v_employee_id, v_role FROM public.employees e
  WHERE e.auth_user_id = auth.uid() AND e.is_active IS TRUE AND e.is_external IS FALSE;

  IF v_role IS NULL OR v_role NOT IN ('admin', 'office', 'project_manager') THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: invoice billing edit required' USING errcode = '42501';
  END IF;

  IF v_message IS NOT NULL AND length(v_message) > 1000 THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: customer message is too long' USING errcode = '22023';
  END IF;
  IF v_cc IS NOT NULL AND v_cc !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: cc address is not a valid email' USING errcode = '22023';
  END IF;

  SELECT i.locked INTO v_locked FROM public.invoices i WHERE i.id = p_invoice_id;
  IF v_locked IS NULL THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT: unknown invoice' USING errcode = '22023';
  END IF;
  IF v_locked IS TRUE THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: invoice is locked' USING errcode = '42501';
  END IF;

  PERFORM set_config('upr.invoice_presentation_write', 'on', true);
  UPDATE public.invoices
  SET customer_message = v_message, send_cc_email = v_cc
  WHERE id = p_invoice_id;
  PERFORM set_config('upr.invoice_presentation_write', 'off', true);

  PERFORM public.record_invoice_activity(
    p_invoice_id, v_employee_id, 'send_presentation_changed', NULL, v_cc,
    jsonb_build_object('has_customer_message', v_message IS NOT NULL)
  );

  RETURN jsonb_build_object('ok', true, 'customer_message', v_message, 'send_cc_email', v_cc);
END;
$_$;


ALTER FUNCTION "public"."set_invoice_send_presentation"("p_invoice_id" "uuid", "p_customer_message" "text", "p_cc_email" "text") OWNER TO "postgres";


