CREATE OR REPLACE FUNCTION "public"."set_job_real_job"("p_job_id" "uuid", "p_is_real" boolean, "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  DECLARE r public.jobs;
BEGIN
  IF p_is_real THEN
    UPDATE public.jobs
       SET is_real_job        = true,
           real_job_source    = 'manual',
           real_job_marked_at = now(),
           updated_by         = COALESCE(p_actor, updated_by)
     WHERE id = p_job_id
     RETURNING * INTO r;
  ELSE
    UPDATE public.jobs
       SET is_real_job = false,
           updated_by  = COALESCE(p_actor, updated_by)
     WHERE id = p_job_id
     RETURNING * INTO r;
  END IF;
  RETURN r;
END; $$;


