CREATE OR REPLACE FUNCTION "public"."set_lead_caller_name"("p_lead_id" "uuid", "p_name" "text", "p_allow_upgrade" boolean DEFAULT false) RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row       inbound_leads;
  v_touched   inbound_leads;
  v_name      text := NULLIF(btrim(p_name), '');
  v_current   text;
  v_upgrade   boolean;
  v_canonical uuid;
  v_merged    uuid;
  v_hops      integer := 0;
  v_targets   uuid[];
  v_target    uuid;
BEGIN
  IF v_name IS NULL THEN
    SELECT * INTO v_row FROM inbound_leads WHERE id = p_lead_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
    END IF;
    RETURN v_row;
  END IF;

  PERFORM 1 FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  -- Resolve the canonical root: the AI names the row whose recording it read,
  -- but only the canonical owns a pipeline card. Bounded walk, identical to
  -- crm_advance_lead_if_forward's.
  v_canonical := p_lead_id;
  LOOP
    SELECT merged_into_lead_id INTO v_merged FROM inbound_leads WHERE id = v_canonical;
    EXIT WHEN v_merged IS NULL OR v_hops >= 5;
    v_canonical := v_merged;
    v_hops := v_hops + 1;
  END LOOP;

  v_targets := ARRAY[p_lead_id];
  IF v_canonical <> p_lead_id THEN
    v_targets := v_targets || v_canonical;
  END IF;

  FOREACH v_target IN ARRAY v_targets LOOP
    SELECT caller_name INTO v_current FROM inbound_leads WHERE id = v_target;

    v_upgrade := p_allow_upgrade
      AND v_current IS NOT NULL AND btrim(v_current) <> ''
      AND left(lower(v_name), length(btrim(v_current)) + 1) = lower(btrim(v_current)) || ' '
      AND lower(v_name) <> lower(btrim(v_current));

    IF v_upgrade THEN
      UPDATE inbound_leads
         SET caller_name = v_name,
             updated_at  = now()
       WHERE id = v_target
       RETURNING * INTO v_touched;
    ELSE
      UPDATE inbound_leads
         SET caller_name = COALESCE(NULLIF(btrim(caller_name), ''), v_name),
             updated_at  = now()
       WHERE id = v_target
       RETURNING * INTO v_touched;
    END IF;

    IF v_touched.contact_id IS NOT NULL THEN
      IF v_upgrade THEN
        UPDATE contacts
           SET name = v_name
         WHERE id = v_touched.contact_id
           AND COALESCE(NULLIF(btrim(name), ''), '') <> ''
           AND left(lower(v_name), length(btrim(name)) + 1) = lower(btrim(name)) || ' ';
      ELSE
        UPDATE contacts
           SET name = v_name
         WHERE id = v_touched.contact_id
           AND COALESCE(NULLIF(btrim(name), ''), '') = '';
      END IF;
    END IF;

    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_lead_caller_named', 'inbound_lead', v_touched.id, NULL,
            jsonb_build_object('name', v_name, 'contact_id', v_touched.contact_id,
                               'upgraded', v_upgrade,
                               'via_merge', v_target <> p_lead_id));

    IF v_target = p_lead_id THEN
      v_row := v_touched;
    END IF;
  END LOOP;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_lead_caller_name"("p_lead_id" "uuid", "p_name" "text", "p_allow_upgrade" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_contact_details"("p_lead_id" "uuid", "p_email" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text") RETURNS "public"."contacts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_contact_id uuid;
  v_row        contacts;
  v_email      text := NULLIF(btrim(p_email), '');
  v_address    text := NULLIF(btrim(p_address), '');
BEGIN
  IF v_email IS NULL AND v_address IS NULL THEN
    SELECT contact_id INTO v_contact_id FROM inbound_leads WHERE id = p_lead_id;
    IF v_contact_id IS NOT NULL THEN
      SELECT * INTO v_row FROM contacts WHERE id = v_contact_id;
    END IF;
    RETURN v_row;
  END IF;

  SELECT contact_id INTO v_contact_id FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  IF v_contact_id IS NULL THEN
    RETURN NULL; -- no linked contact yet — nowhere to write this, never create one
  END IF;

  UPDATE contacts
     SET email          = COALESCE(NULLIF(btrim(email), ''), v_email),
         billing_address = COALESCE(NULLIF(btrim(billing_address), ''), v_address),
         updated_at      = now()
   WHERE id = v_contact_id
   RETURNING * INTO v_row;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_contact_details_backfilled', 'contact', v_contact_id, NULL,
          jsonb_build_object('lead_id', p_lead_id, 'email_provided', v_email IS NOT NULL, 'address_provided', v_address IS NOT NULL));

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_lead_contact_details"("p_lead_id" "uuid", "p_email" "text", "p_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_details"("p_lead_id" "uuid", "p_notes" "text", "p_value" numeric, "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  UPDATE inbound_leads
     SET notes      = NULLIF(btrim(p_notes), ''),
         value      = p_value,
         updated_at = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_details_updated', 'inbound_lead', v_row.id, p_updated_by,
          jsonb_build_object('value', v_row.value, 'has_notes', (v_row.notes IS NOT NULL)));

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_lead_details"("p_lead_id" "uuid", "p_notes" "text", "p_value" numeric, "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_spam_flag"("p_lead_id" "uuid", "p_spam" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row  inbound_leads;
  v_prev boolean;
BEGIN
  SELECT spam_flag INTO v_prev FROM inbound_leads WHERE id = p_lead_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  UPDATE inbound_leads
     SET spam_flag  = p_spam,
         updated_at = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF COALESCE(v_prev, false) IS DISTINCT FROM p_spam THEN
    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_lead_spam_flag_set', 'inbound_lead', v_row.id, NULL,
            jsonb_build_object('spam_flag', p_spam, 'reason', p_reason));
  END IF;

  IF p_spam THEN
    DELETE FROM lead_pipeline_stage WHERE lead_id = p_lead_id;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_lead_spam_flag"("p_lead_id" "uuid", "p_spam" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_transcription"("p_lead_id" "uuid", "p_transcription" "text", "p_source" "text" DEFAULT 'deepgram'::"text", "p_analysis" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  UPDATE inbound_leads
     SET transcription        = p_transcription,
         transcription_source = p_source,
         transcript_analysis  = COALESCE(p_analysis, transcript_analysis),
         transcribed_at       = now(),
         updated_at           = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_call_transcribed', 'inbound_lead', v_row.id, NULL,
          jsonb_build_object(
            'source', p_source,
            'chars', length(COALESCE(p_transcription, '')),
            'has_analysis', (p_analysis IS NOT NULL)
          ));

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_lead_transcription"("p_lead_id" "uuid", "p_transcription" "text", "p_source" "text", "p_analysis" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_value"("p_lead_id" "uuid", "p_value" numeric DEFAULT NULL::numeric, "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM employees e
     WHERE e.auth_user_id = auth.uid()
       AND e.is_active
       AND NOT e.is_external
  ) THEN
    RAISE EXCEPTION 'not authorized to set a lead value';
  END IF;

  IF p_value IS NOT NULL AND p_value < 0 THEN
    RAISE EXCEPTION 'lead value cannot be negative';
  END IF;

  UPDATE inbound_leads
     SET value        = p_value,
         value_source = CASE WHEN p_value IS NULL THEN 'auto' ELSE 'manual' END,
         updated_at   = now()
   WHERE id = p_lead_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'lead % not found', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_value_set', 'inbound_lead', p_lead_id,
          jsonb_build_object('value', p_value, 'updated_by', p_updated_by));

  IF p_value IS NULL THEN
    PERFORM crm_recompute_lead_value(p_lead_id);
    SELECT * INTO v_row FROM inbound_leads WHERE id = p_lead_id;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_lead_value"("p_lead_id" "uuid", "p_value" numeric, "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_conversation_unread_state"("p_conversation_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_unread" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_id uuid;
  v_conversation_ids uuid[];
  v_updated integer := 0;
BEGIN
  SELECT employee.id
    INTO v_actor_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active
    AND NOT employee.is_external
  LIMIT 1;

  IF v_actor_id IS NULL
     OR NOT public.messaging_employee_has_conversations_capability(v_actor_id) THEN
    RAISE EXCEPTION 'Messages access is not granted'
      USING ERRCODE = '42501';
  END IF;

  IF p_unread IS NULL THEN
    RAISE EXCEPTION 'unread state is required'
      USING ERRCODE = '22023';
  END IF;

  -- NULL means "mark every currently accessible conversation read". It is
  -- intentionally unavailable for marking everything unread.
  IF p_conversation_ids IS NULL THEN
    IF p_unread THEN
      RAISE EXCEPTION 'conversation ids are required when marking unread'
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.conversations conversation
       SET unread_count = 0
     WHERE COALESCE(conversation.unread_count, 0) <> 0
       AND public.messaging_employee_can_access_conversation(
         v_actor_id,
         conversation.id
       );

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated;
  END IF;

  IF cardinality(p_conversation_ids) > 200
     OR EXISTS (
       SELECT 1
       FROM unnest(p_conversation_ids) requested(conversation_id)
       WHERE requested.conversation_id IS NULL
     ) THEN
    RAISE EXCEPTION 'conversation ids must contain at most 200 non-null values'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
    array_agg(DISTINCT requested.conversation_id),
    ARRAY[]::uuid[]
  )
    INTO v_conversation_ids
  FROM unnest(p_conversation_ids) requested(conversation_id);

  IF cardinality(v_conversation_ids) = 0 THEN
    RETURN 0;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_conversation_ids) requested(conversation_id)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.conversations conversation
      WHERE conversation.id = requested.conversation_id
    )
       OR NOT public.messaging_employee_can_access_conversation(
         v_actor_id,
         requested.conversation_id
       )
  ) THEN
    RAISE EXCEPTION 'conversation access not found'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.conversations conversation
     SET unread_count = CASE WHEN p_unread THEN 1 ELSE 0 END
   WHERE conversation.id = ANY(v_conversation_ids);

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."set_my_conversation_unread_state"("p_conversation_ids" "uuid"[], "p_unread" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_my_conversation_unread_state"("p_conversation_ids" "uuid"[], "p_unread" boolean) IS 'Actor-derived read/unread mutation. Updates only unread_count for conversations the authenticated employee can currently access; NULL ids mark all accessible threads read.';



CREATE TABLE IF NOT EXISTS "public"."notification_prefs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "type_key" "text" NOT NULL,
    "channel" "text" NOT NULL,
    "enabled" boolean NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "notification_prefs_channel_check" CHECK (("channel" = ANY (ARRAY['bell'::"text", 'push'::"text", 'email'::"text"])))
);

ALTER TABLE ONLY "public"."notification_prefs" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."notification_prefs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_notification_pref"("p_employee_id" "uuid", "p_type_key" "text", "p_channel" "text", "p_enabled" boolean) RETURNS "public"."notification_prefs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_customizable boolean;
  v_row public.notification_prefs;
BEGIN
  IF NOT COALESCE(
       (SELECT auth.jwt() ->> 'role' = 'service_role'),
       false
     )
     AND NOT public.is_current_native_push_preferences_employee(p_employee_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: own notification preferences only'
      USING errcode = '42501';
  END IF;

  IF p_channel NOT IN ('bell', 'push', 'email') THEN
    RAISE EXCEPTION 'invalid channel: %', p_channel;
  END IF;

  SELECT employee.role::text
  INTO v_role
  FROM public.employees employee
  WHERE employee.id = p_employee_id;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'unknown employee: %', p_employee_id;
  END IF;

  SELECT role_default.user_customizable
  INTO v_customizable
  FROM public.notification_role_defaults role_default
  WHERE role_default.role = v_role
    AND role_default.type_key = p_type_key
    AND role_default.channel = p_channel;

  IF v_customizable IS FALSE THEN
    RAISE EXCEPTION
      'notification preference locked by an administrator (% / %)',
      p_type_key,
      p_channel;
  END IF;

  INSERT INTO public.notification_prefs (
    employee_id,
    type_key,
    channel,
    enabled
  )
  VALUES (
    p_employee_id,
    p_type_key,
    p_channel,
    p_enabled
  )
  ON CONFLICT (employee_id, type_key, channel)
  DO UPDATE SET
    enabled = EXCLUDED.enabled,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."set_my_notification_pref"("p_employee_id" "uuid", "p_type_key" "text", "p_channel" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_notification_quiet_time"("p_employee_id" "uuid", "p_enabled" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_current_native_push_preferences_employee(p_employee_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: own notification quiet time only' USING errcode = '42501';
  END IF;
  INSERT INTO public.notification_quiet_time_preferences (employee_id, enabled)
  VALUES (p_employee_id, p_enabled)
  ON CONFLICT (employee_id) DO UPDATE SET enabled = EXCLUDED.enabled, updated_at = now();
  RETURN p_enabled;
END;
$$;


ALTER FUNCTION "public"."set_my_notification_quiet_time"("p_employee_id" "uuid", "p_enabled" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."notification_role_defaults" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "role" "text" NOT NULL,
    "type_key" "text" NOT NULL,
    "channel" "text" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "user_customizable" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    CONSTRAINT "notification_role_defaults_channel_check" CHECK (("channel" = ANY (ARRAY['bell'::"text", 'push'::"text", 'email'::"text"])))
);


ALTER TABLE "public"."notification_role_defaults" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_notification_default"("p_role" "text", "p_type_key" "text", "p_channel" "text", "p_enabled" boolean, "p_user_customizable" boolean DEFAULT NULL::boolean) RETURNS "public"."notification_role_defaults"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.notification_role_defaults;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  INSERT INTO public.notification_role_defaults
    (role, type_key, channel, enabled, user_customizable, updated_at)
  VALUES
    (p_role, p_type_key, p_channel, p_enabled, COALESCE(p_user_customizable, true), now())
  ON CONFLICT (role, type_key, channel) DO UPDATE
    SET enabled           = EXCLUDED.enabled,
        user_customizable = COALESCE(p_user_customizable,
                                     public.notification_role_defaults.user_customizable),
        updated_at        = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


