CREATE OR REPLACE FUNCTION "public"."set_qbo_estimate_command_state"("p_command_id" "uuid", "p_status" "text", "p_provider_result" "jsonb" DEFAULT NULL::"jsonb", "p_response_status" integer DEFAULT NULL::integer, "p_response_payload" "jsonb" DEFAULT NULL::"jsonb", "p_error" "text" DEFAULT NULL::"text", "p_intuit_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE c public.qbo_estimate_commands; allowed boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE id=p_command_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 allowed:=(c.status='prepared' AND p_status='rejected') OR (c.status='provider_started' AND p_status IN ('ambiguous','provider_succeeded','rejected')) OR (c.status='provider_succeeded' AND p_status='needs_reconciliation');
 IF NOT allowed THEN RETURN jsonb_build_object('ok',false,'reason','invalid-transition','status',c.status); END IF;
 UPDATE public.qbo_estimate_commands SET status=p_status,provider_result=COALESCE(p_provider_result,provider_result),response_status=COALESCE(p_response_status,response_status),response_payload=COALESCE(p_response_payload,response_payload),error=p_error,intuit_request_id=COALESCE(p_intuit_request_id,intuit_request_id),provider_succeeded_at=CASE WHEN p_status='provider_succeeded' THEN now() ELSE provider_succeeded_at END,completed_at=CASE WHEN p_status='rejected' THEN now() ELSE completed_at END,updated_at=now() WHERE id=p_command_id RETURNING * INTO c;
 IF p_status='rejected' THEN DELETE FROM public.qbo_estimate_command_reservations WHERE estimate_id=c.estimate_id AND command_id=c.id; END IF;
 RETURN jsonb_build_object('ok',true,'status',c.status);
END;$$;


ALTER FUNCTION "public"."set_qbo_estimate_command_state"("p_command_id" "uuid", "p_status" "text", "p_provider_result" "jsonb", "p_response_status" integer, "p_response_payload" "jsonb", "p_error" "text", "p_intuit_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_qbo_invoice_command_state"("p_command_id" "uuid", "p_status" "text", "p_provider_result" "jsonb" DEFAULT NULL::"jsonb", "p_response_status" integer DEFAULT NULL::integer, "p_response_payload" "jsonb" DEFAULT NULL::"jsonb", "p_error" "text" DEFAULT NULL::"text", "p_intuit_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE v_command public.qbo_invoice_commands; v_allowed boolean:=false;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id=p_command_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 v_allowed := (v_command.status='prepared' AND p_status IN ('succeeded','rejected')) OR (v_command.status='provider_started' AND p_status IN ('ambiguous','provider_succeeded','rejected')) OR (v_command.status='ambiguous' AND p_status IN ('provider_succeeded','needs_reconciliation','rejected')) OR (v_command.status='provider_succeeded' AND p_status IN ('succeeded','needs_reconciliation')) OR (v_command.status='needs_reconciliation' AND p_status IN ('provider_started','provider_succeeded','succeeded','rejected'));
 IF NOT v_allowed THEN RETURN jsonb_build_object('ok',false,'reason','invalid-transition','status',v_command.status); END IF;
 IF v_command.status='prepared' AND p_status='succeeded' AND (p_response_status IS NULL OR p_response_payload IS NULL) THEN RETURN jsonb_build_object('ok',false,'reason','terminal-response-required','status',v_command.status); END IF;
 UPDATE public.qbo_invoice_commands SET status=p_status,provider_result=COALESCE(p_provider_result,provider_result),response_status=COALESCE(p_response_status,response_status),response_payload=COALESCE(p_response_payload,response_payload),error=p_error,intuit_request_id=COALESCE(p_intuit_request_id,intuit_request_id),provider_succeeded_at=CASE WHEN p_status='provider_succeeded' THEN now() ELSE provider_succeeded_at END,completed_at=CASE WHEN p_status IN ('succeeded','rejected') THEN now() ELSE completed_at END,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
 IF p_status IN ('succeeded','rejected') THEN
   DELETE FROM public.qbo_invoice_command_reservations WHERE invoice_id=v_command.invoice_id AND command_id=p_command_id;
 END IF;
 RETURN jsonb_build_object('ok',true,'command_id',v_command.id,'status',v_command.status,'provider_stage',v_command.provider_stage,'response_status',v_command.response_status,'response_payload',v_command.response_payload);
END;
$$;


ALTER FUNCTION "public"."set_qbo_invoice_command_state"("p_command_id" "uuid", "p_status" "text", "p_provider_result" "jsonb", "p_response_status" integer, "p_response_payload" "jsonb", "p_error" "text", "p_intuit_request_id" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."crm_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "notes" "text",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "due_at" timestamp with time zone,
    "remind_at" timestamp with time zone,
    "assignee_id" "uuid",
    "contact_id" "uuid",
    "lead_id" "uuid",
    "completed_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "crm_tasks_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'done'::"text"])))
);


ALTER TABLE "public"."crm_tasks" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_task_status"("p_task_id" "uuid", "p_status" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."crm_tasks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text := lower(btrim(p_status));
  v_row    crm_tasks;
BEGIN
  IF v_status NOT IN ('open', 'done') THEN
    RAISE EXCEPTION 'invalid task status: % (expected open or done)', p_status;
  END IF;
  UPDATE crm_tasks SET
    status = v_status,
    completed_at = CASE WHEN v_status = 'done' THEN now() ELSE NULL END,
    updated_at = now()
  WHERE id = p_task_id
  RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'unknown crm_tasks id: %', p_task_id; END IF;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_task_status_changed', 'crm_task', v_row.id, p_actor_id, jsonb_build_object('status', v_status));
  RETURN v_row;
END;
$$;


