CREATE OR REPLACE FUNCTION "public"."stage_qbo_invoice_line_change"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_line_change" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_invoice public.invoices; v_command public.qbo_invoice_commands;
  v_reservation public.qbo_invoice_command_reservations; v_kind text;
  v_existing jsonb; v_frozen jsonb; v_preimage jsonb; v_ids uuid[];
  v_line public.invoice_line_items; v_requested uuid; v_new_id uuid;
  v_count bigint; v_sort integer; v_command_found boolean := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE='42501'; END IF;
  IF p_command_id IS NULL OR p_invoice_id IS NULL OR p_initiator <> 'browser' OR p_actor_auth_user_id IS NULL OR p_realm_id IS NULL OR jsonb_typeof(p_line_change) <> 'object' THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid-line-change');
  END IF;
  v_kind := p_line_change->>'kind';
  IF v_kind NOT IN ('create','update','delete','reorder') OR (v_kind='reorder' AND jsonb_typeof(p_line_change->'ordered_line_ids') IS DISTINCT FROM 'array') THEN RETURN jsonb_build_object('ok',false,'reason','invalid-line-change'); END IF;
  -- Match the deployed line-trigger order (line(s) then parent) for every
  -- operation that has existing rows. This prevents a desktop line write from
  -- holding a line while waiting on the parent that this command already owns.
  IF v_kind IN ('update','delete') THEN
    BEGIN v_requested := (p_line_change->>'line_id')::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN jsonb_build_object('ok',false,'reason','invalid-line-change'); END;
    SELECT * INTO v_line FROM public.invoice_line_items WHERE id=v_requested AND invoice_id=p_invoice_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','line-not-found'); END IF;
  ELSIF v_kind='reorder' THEN
    PERFORM 1 FROM public.invoice_line_items WHERE invoice_id=p_invoice_id ORDER BY id FOR UPDATE;
  END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id=p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','invoice-not-found'); END IF;
  IF v_invoice.locked IS TRUE THEN RETURN jsonb_build_object('ok',false,'reason','invoice-locked'); END IF;
  SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id=p_command_id FOR UPDATE; v_command_found := FOUND;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations WHERE invoice_id=p_invoice_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.command_id IS DISTINCT FROM p_command_id OR v_reservation.action IS DISTINCT FROM 'save'
    OR v_reservation.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR v_reservation.actor_employee_id IS DISTINCT FROM p_actor_employee_id
    OR v_reservation.initiator IS DISTINCT FROM p_initiator OR v_reservation.realm_id IS DISTINCT FROM p_realm_id THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
  IF v_command_found AND (v_command.invoice_id IS DISTINCT FROM p_invoice_id OR v_command.action IS DISTINCT FROM 'save' OR v_command.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id OR v_command.actor_employee_id IS DISTINCT FROM p_actor_employee_id OR v_command.initiator IS DISTINCT FROM p_initiator OR v_command.realm_id IS DISTINCT FROM p_realm_id) THEN RETURN jsonb_build_object('ok',false,'reason','command-mismatch'); END IF;
  IF v_command_found THEN
    v_existing := v_command.intent_payload->'line_change';
    IF jsonb_typeof(v_existing) IS DISTINCT FROM 'object' OR v_existing->'request' IS DISTINCT FROM p_line_change THEN RETURN jsonb_build_object('ok',false,'reason','change-conflict'); END IF;
    -- Before provider success the original preimage must remain exact. After
    -- success either the old preimage or the applied candidate is legal so a
    -- crash replay can finish exactly once.
    v_frozen := v_existing;
    IF v_command.status NOT IN ('prepared','provider_started','ambiguous','provider_succeeded','needs_reconciliation','succeeded','rejected') THEN RETURN jsonb_build_object('ok',false,'reason','invalid-state'); END IF;
    RETURN jsonb_build_object('ok',true,'line_change',v_frozen);
  END IF;
  IF v_kind IN ('create','update') AND (jsonb_typeof(p_line_change->'patch') IS DISTINCT FROM 'object' OR coalesce(btrim(p_line_change->'patch'->>'description'),'')='' OR length(p_line_change->'patch'->>'description')>4000 OR (p_line_change->'patch'->>'quantity') IS NULL OR (p_line_change->'patch'->>'unit_price') IS NULL) THEN RETURN jsonb_build_object('ok',false,'reason','invalid-line-change'); END IF;
  IF v_kind='create' THEN
    SELECT count(*) INTO v_count FROM public.invoice_line_items WHERE invoice_id=p_invoice_id;
    IF p_line_change ? 'sort_order' THEN
      IF jsonb_typeof(p_line_change->'sort_order') IS DISTINCT FROM 'number'
         OR (p_line_change->>'sort_order') !~ '^[0-9]+$' THEN
        RETURN jsonb_build_object('ok',false,'reason','invalid-sort-order');
      END IF;
      BEGIN
        IF (p_line_change->>'sort_order')::numeric > 2147483647 THEN
          RETURN jsonb_build_object('ok',false,'reason','invalid-sort-order');
        END IF;
      EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN
        RETURN jsonb_build_object('ok',false,'reason','invalid-sort-order');
      END;
    END IF;
    IF v_count > 2147483647 THEN RETURN jsonb_build_object('ok',false,'reason','invalid-sort-order'); END IF;
    v_new_id := gen_random_uuid(); v_sort := COALESCE((p_line_change->>'sort_order')::integer,v_count::integer);
    v_frozen := jsonb_build_object('request',p_line_change,'kind','create','line_id',v_new_id,'patch',p_line_change->'patch','sort_order',v_sort);
  ELSIF v_kind IN ('update','delete') THEN
    v_preimage := to_jsonb(v_line) - 'line_total' - 'created_at' - 'updated_at';
    v_frozen := jsonb_build_object('request',p_line_change,'kind',v_kind,'line_id',v_requested,'preimage',v_preimage) || CASE WHEN v_kind='update' THEN jsonb_build_object('patch',p_line_change->'patch') ELSE '{}'::jsonb END;
  ELSE
    SELECT array_agg((value #>> '{}')::uuid ORDER BY ordinality) INTO v_ids FROM jsonb_array_elements(p_line_change->'ordered_line_ids') WITH ORDINALITY;
    IF v_ids IS NULL OR cardinality(v_ids) <> (SELECT count(*) FROM public.invoice_line_items WHERE invoice_id=p_invoice_id) OR (SELECT count(DISTINCT x) FROM unnest(v_ids) x) <> cardinality(v_ids) OR EXISTS (SELECT 1 FROM public.invoice_line_items WHERE invoice_id=p_invoice_id AND NOT (id = ANY(v_ids))) THEN RETURN jsonb_build_object('ok',false,'reason','invalid-reorder'); END IF;
    SELECT jsonb_agg(to_jsonb(l) - 'line_total' - 'created_at' - 'updated_at' ORDER BY l.id) INTO v_preimage FROM public.invoice_line_items l WHERE l.invoice_id=p_invoice_id;
    v_frozen := jsonb_build_object('request',p_line_change,'kind','reorder','ordered_line_ids',to_jsonb(v_ids),'preimage',v_preimage);
  END IF;
  RETURN jsonb_build_object('ok',true,'line_change',v_frozen);
END;
$_$;


ALTER FUNCTION "public"."stage_qbo_invoice_line_change"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_line_change" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stage_qbo_invoice_line_update"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_line_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_description" "text", "p_qbo_item_id" "text", "p_qbo_item_name" "text", "p_qbo_class_id" "text", "p_qbo_class_name" "text", "p_quantity" numeric, "p_unit_price" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_invoice public.invoices;
  v_command public.qbo_invoice_commands;
  v_reservation public.qbo_invoice_command_reservations;
  v_line public.invoice_line_items;
  v_command_found boolean := false;
  v_current jsonb;
  v_patch jsonb;
  v_frozen jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE = '42501';
  END IF;
  IF p_command_id IS NULL OR p_invoice_id IS NULL OR p_line_id IS NULL
     OR p_initiator <> 'browser' OR p_actor_auth_user_id IS NULL OR p_realm_id IS NULL
     OR p_description IS NULL OR btrim(p_description) = '' OR length(p_description) > 4000
     OR p_quantity IS NULL OR p_unit_price IS NULL
     OR p_quantity IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric)
     OR p_unit_price IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid-line-update');
  END IF;

  SELECT * INTO v_line FROM public.invoice_line_items
  WHERE id = p_line_id AND invoice_id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'line-not-found'); END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'invoice-not-found'); END IF;
  IF v_invoice.locked IS TRUE THEN RETURN jsonb_build_object('ok', false, 'reason', 'invoice-locked'); END IF;

  SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id = p_command_id FOR UPDATE;
  v_command_found := FOUND;
  SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations
  WHERE invoice_id = p_invoice_id FOR UPDATE;
  IF NOT FOUND
     OR v_reservation.command_id IS DISTINCT FROM p_command_id
     OR v_reservation.action IS DISTINCT FROM 'save'
     OR v_reservation.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id
     OR v_reservation.actor_employee_id IS DISTINCT FROM p_actor_employee_id
     OR v_reservation.initiator IS DISTINCT FROM p_initiator
     OR v_reservation.realm_id IS DISTINCT FROM p_realm_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reservation-mismatch');
  END IF;
  IF v_command_found AND (
    v_command.invoice_id IS DISTINCT FROM p_invoice_id
    OR v_command.action IS DISTINCT FROM 'save'
    OR v_command.actor_auth_user_id IS DISTINCT FROM p_actor_auth_user_id
    OR v_command.actor_employee_id IS DISTINCT FROM p_actor_employee_id
    OR v_command.initiator IS DISTINCT FROM p_initiator
    OR v_command.realm_id IS DISTINCT FROM p_realm_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'command-mismatch');
  END IF;

  v_current := jsonb_build_object(
    'description', v_line.description, 'qbo_item_id', v_line.qbo_item_id,
    'qbo_item_name', v_line.qbo_item_name, 'qbo_class_id', v_line.qbo_class_id,
    'qbo_class_name', v_line.qbo_class_name, 'quantity', v_line.quantity,
    'unit_price', v_line.unit_price
  );
  v_patch := jsonb_build_object(
    'description', p_description, 'qbo_item_id', p_qbo_item_id,
    'qbo_item_name', p_qbo_item_name, 'qbo_class_id', p_qbo_class_id,
    'qbo_class_name', p_qbo_class_name, 'quantity', p_quantity,
    'unit_price', p_unit_price
  );
  v_frozen := jsonb_build_object('line_id', p_line_id, 'preimage', v_current, 'patch', v_patch);
  IF v_command_found THEN
    IF jsonb_typeof(v_command.intent_payload->'line_update') IS DISTINCT FROM 'object'
       OR v_command.intent_payload->'line_update'->>'line_id' IS DISTINCT FROM p_line_id::text
       OR v_command.intent_payload->'line_update'->'patch' IS DISTINCT FROM v_patch THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'patch-conflict');
    END IF;
    v_frozen := v_command.intent_payload->'line_update';
    IF v_command.status IN ('prepared', 'provider_started', 'ambiguous', 'rejected')
       AND v_current IS DISTINCT FROM v_frozen->'preimage' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'source-mismatch');
    ELSIF v_command.status = 'succeeded'
       AND v_current IS DISTINCT FROM v_frozen->'patch' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'source-mismatch');
    ELSIF v_command.status IN ('provider_succeeded', 'needs_reconciliation')
       AND v_current IS DISTINCT FROM v_frozen->'preimage'
       AND v_current IS DISTINCT FROM v_frozen->'patch' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'source-mismatch');
    ELSIF v_command.status NOT IN (
      'prepared', 'provider_started', 'ambiguous', 'provider_succeeded',
      'needs_reconciliation', 'succeeded', 'rejected'
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'invalid-state');
    END IF;
  END IF;
  RETURN jsonb_build_object('ok', true, 'line_update', v_frozen);
END;
$$;


ALTER FUNCTION "public"."stage_qbo_invoice_line_update"("p_command_id" "uuid", "p_invoice_id" "uuid", "p_line_id" "uuid", "p_actor_auth_user_id" "uuid", "p_actor_employee_id" "uuid", "p_initiator" "text", "p_realm_id" "text", "p_description" "text", "p_qbo_item_id" "text", "p_qbo_item_name" "text", "p_qbo_class_id" "text", "p_qbo_class_name" "text", "p_quantity" numeric, "p_unit_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_qbo_estimate_command_attempt"("p_command_id" "uuid", "p_provider_stage" "text", "p_provider_action" "text", "p_provider_target_id" "text", "p_provider_request_id" "text", "p_provider_payload" "jsonb", "p_provider_payload_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE c public.qbo_estimate_commands; r public.qbo_estimate_command_reservations;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.qbo_estimate_commands WHERE id=p_command_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 SELECT * INTO r FROM public.qbo_estimate_command_reservations WHERE estimate_id=c.estimate_id FOR UPDATE;
 IF NOT FOUND OR r.command_id IS DISTINCT FROM p_command_id THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
 IF c.status IS DISTINCT FROM 'prepared' THEN RETURN jsonb_build_object('ok',false,'reason','attempt-not-fresh','status',c.status); END IF;
 IF NULLIF(p_provider_stage,'') IS NULL OR p_provider_action NOT IN ('create','update','send','delete') OR COALESCE(p_provider_request_id,'') !~ '^[A-Za-z0-9._-]{1,50}$' OR jsonb_typeof(p_provider_payload) IS DISTINCT FROM 'object' OR p_provider_payload_hash !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-attempt'); END IF;
 UPDATE public.qbo_estimate_commands SET status='provider_started',provider_stage=p_provider_stage,provider_action=p_provider_action,provider_target_id=p_provider_target_id,provider_request_id=p_provider_request_id,provider_payload=p_provider_payload,provider_payload_hash=p_provider_payload_hash,provider_started_at=now(),updated_at=now() WHERE id=p_command_id;
 RETURN jsonb_build_object('ok',true,'started',true);
END;$_$;


ALTER FUNCTION "public"."start_qbo_estimate_command_attempt"("p_command_id" "uuid", "p_provider_stage" "text", "p_provider_action" "text", "p_provider_target_id" "text", "p_provider_request_id" "text", "p_provider_payload" "jsonb", "p_provider_payload_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_qbo_invoice_command_attempt"("p_command_id" "uuid", "p_provider_stage" "text", "p_provider_action" "text", "p_provider_target_id" "text", "p_provider_request_id" "text", "p_provider_payload" "jsonb", "p_provider_payload_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_command public.qbo_invoice_commands; v_reservation public.qbo_invoice_command_reservations;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized: service role required' USING ERRCODE='42501'; END IF;
 IF p_provider_stage IS NULL OR p_provider_action IS NULL OR p_provider_request_id IS NULL OR (p_provider_target_id IS NULL AND p_provider_action <> 'create') OR jsonb_typeof(p_provider_payload) <> 'object' OR p_provider_payload_hash !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-attempt'); END IF;
 SELECT * INTO v_command FROM public.qbo_invoice_commands WHERE id=p_command_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','command-not-found'); END IF;
 SELECT * INTO v_reservation FROM public.qbo_invoice_command_reservations WHERE invoice_id=v_command.invoice_id FOR UPDATE;
  IF NOT FOUND OR v_reservation.command_id IS DISTINCT FROM p_command_id OR v_reservation.action IS DISTINCT FROM v_command.action OR v_reservation.actor_auth_user_id IS DISTINCT FROM v_command.actor_auth_user_id OR v_reservation.actor_employee_id IS DISTINCT FROM v_command.actor_employee_id OR v_reservation.initiator IS DISTINCT FROM v_command.initiator OR v_reservation.realm_id IS DISTINCT FROM v_command.realm_id THEN RETURN jsonb_build_object('ok',false,'reason','reservation-mismatch'); END IF;
 IF v_command.status IN ('provider_started','ambiguous') THEN
  IF v_command.provider_stage IS DISTINCT FROM p_provider_stage OR v_command.provider_action IS DISTINCT FROM p_provider_action OR v_command.provider_target_id IS DISTINCT FROM p_provider_target_id OR v_command.provider_request_id IS DISTINCT FROM p_provider_request_id OR v_command.provider_payload IS DISTINCT FROM p_provider_payload OR v_command.provider_payload_hash IS DISTINCT FROM p_provider_payload_hash THEN RETURN jsonb_build_object('ok',false,'reason','attempt-mismatch'); END IF;
  RETURN jsonb_build_object('ok',true,'replay',true,'status',v_command.status,'provider_stage',v_command.provider_stage,'provider_action',v_command.provider_action,'provider_target_id',v_command.provider_target_id,'provider_request_id',v_command.provider_request_id,'provider_payload',v_command.provider_payload,'provider_payload_hash',v_command.provider_payload_hash);
 END IF;
 IF v_command.status <> 'prepared' THEN RETURN jsonb_build_object('ok',false,'reason','invalid-state','status',v_command.status); END IF;
 UPDATE public.qbo_invoice_commands SET status='provider_started',provider_stage=p_provider_stage,provider_action=p_provider_action,provider_target_id=p_provider_target_id,provider_request_id=p_provider_request_id,provider_payload=p_provider_payload,provider_payload_hash=p_provider_payload_hash,provider_started_at=now(),error=NULL,updated_at=now() WHERE id=p_command_id;
 RETURN jsonb_build_object('ok',true,'started',true,'status','provider_started','provider_stage',p_provider_stage,'provider_action',p_provider_action,'provider_target_id',p_provider_target_id,'provider_request_id',p_provider_request_id,'provider_payload',p_provider_payload,'provider_payload_hash',p_provider_payload_hash);
END;
$_$;


ALTER FUNCTION "public"."start_qbo_invoice_command_attempt"("p_command_id" "uuid", "p_provider_stage" "text", "p_provider_action" "text", "p_provider_target_id" "text", "p_provider_request_id" "text", "p_provider_payload" "jsonb", "p_provider_payload_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."strip_recording_sources"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE jsonb_typeof(p_value)
    WHEN 'object' THEN COALESCE((
      SELECT jsonb_object_agg(e.key, public.strip_recording_sources(e.value))
      FROM jsonb_each(p_value) e
      WHERE e.key NOT IN ('recording', 'recording_url')
    ), '{}'::jsonb)
    WHEN 'array' THEN COALESCE((
      SELECT jsonb_agg(public.strip_recording_sources(a.value))
      FROM jsonb_array_elements(p_value) a
    ), '[]'::jsonb)
    ELSE p_value
  END;
$$;


ALTER FUNCTION "public"."strip_recording_sources"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_time_entry_change_request"("p_entry_id" "uuid", "p_proposed" "jsonb", "p_tech_note" "text", "p_actor_id" "uuid") RETURNS "public"."time_entry_change_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_e job_time_entries%ROWTYPE; v_req time_entry_change_requests%ROWTYPE; v_emp text;
begin
  select * into v_e from job_time_entries where id=p_entry_id;
  if v_e.id is null then raise exception 'ENTRY_NOT_FOUND' using errcode='P0001'; end if;
  if v_e.employee_id <> p_actor_id then raise exception 'NOT_OWNER' using errcode='P0001'; end if;
  insert into time_entry_change_requests (entry_id, requested_by, proposed, tech_note) values (p_entry_id, p_actor_id, coalesce(p_proposed,'{}'::jsonb), p_tech_note) returning * into v_req;
  select full_name into v_emp from employees where id=p_actor_id;
  perform notify_emit('timesheet.change_requested', jsonb_build_object(
    'title', 'Timesheet change requested',
    'body', coalesce(v_emp,'A tech')||' requested a correction to a time entry.',
    'link', '/time-tracking',
    'entity_type', 'time_entry_change_request',
    'entity_id', v_req.id,
    'job_id', v_e.job_id,
    'payload', jsonb_build_object('entry_id', p_entry_id, 'proposed', coalesce(p_proposed,'{}'::jsonb))
  ));
  return v_req;
end; $$;


ALTER FUNCTION "public"."submit_time_entry_change_request"("p_entry_id" "uuid", "p_proposed" "jsonb", "p_tech_note" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."appointment_crew" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "appointment_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "role" "public"."crew_role" DEFAULT 'tech'::"public"."crew_role" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."appointment_crew" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_appointment_crew"("p_appointment_id" "uuid", "p_crew" "jsonb" DEFAULT '[]'::"jsonb") RETURNS SETOF "public"."appointment_crew"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor_id uuid;
  v_actor_kind text;
  v_job_id uuid;
  v_old_crew jsonb;
  v_new_crew jsonb;
BEGIN
  IF p_appointment_id IS NULL THEN
    RAISE EXCEPTION
      'sync_appointment_crew: p_appointment_id is required'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(COALESCE(p_crew, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION
      'sync_appointment_crew: p_crew must be an array'
      USING ERRCODE = '22023';
  END IF;

  IF NOT public.is_trusted_appointment_command_caller()
     AND NOT public.can_current_employee_manage_appointment_crew(
       p_appointment_id
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal appointment employee required'
      USING ERRCODE = '42501';
  END IF;

  SELECT appointment.job_id
  INTO v_job_id
  FROM public.appointments appointment
  WHERE appointment.id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'sync_appointment_crew: appointment not found'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      COALESCE(p_crew, '[]'::jsonb)
    ) element
    WHERE jsonb_typeof(element) IS DISTINCT FROM 'object'
       OR COALESCE(element ->> 'employee_id', '')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR COALESCE(
            NULLIF(btrim(element ->> 'role'), ''),
            'tech'
          ) NOT IN ('lead', 'tech', 'helper')
  ) THEN
    RAISE EXCEPTION
      'sync_appointment_crew: invalid crew member'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      COALESCE(p_crew, '[]'::jsonb)
    ) element
    GROUP BY (element ->> 'employee_id')::uuid
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION
      'sync_appointment_crew: duplicate crew member'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(
      COALESCE(p_crew, '[]'::jsonb)
    ) element
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.employees employee
      WHERE employee.id = (element ->> 'employee_id')::uuid
        AND employee.is_active IS TRUE
        AND employee.is_external IS FALSE
        AND employee.role::text IS DISTINCT FROM 'crm_partner'
    )
  ) THEN
    RAISE EXCEPTION
      'sync_appointment_crew: active internal crew required'
      USING ERRCODE = '42501';
  END IF;

  v_actor_id :=
    public.current_attributed_appointment_crew_actor();
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: attributed active internal appointment actor required'
      USING ERRCODE = '42501';
  END IF;

  IF public.is_trusted_appointment_command_caller() THEN
    v_actor_kind := CASE
      WHEN auth.jwt() ->> 'role' = 'service_role' THEN 'service_role'
      ELSE 'database_owner'
    END;
  ELSE
    v_actor_kind := 'employee';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'employee_id', crew.employee_id,
        'role', crew.role::text
      )
      ORDER BY crew.employee_id
    ),
    '[]'::jsonb
  )
  INTO v_old_crew
  FROM public.appointment_crew crew
  WHERE crew.appointment_id = p_appointment_id;

  WITH desired AS (
    SELECT
      (element ->> 'employee_id')::uuid AS employee_id,
      COALESCE(
        NULLIF(btrim(element ->> 'role'), ''),
        'tech'
      )::public.crew_role AS role
    FROM jsonb_array_elements(
      COALESCE(p_crew, '[]'::jsonb)
    ) element
  )
  DELETE FROM public.appointment_crew existing
  WHERE existing.appointment_id = p_appointment_id
    AND NOT EXISTS (
      SELECT 1
      FROM desired
      WHERE desired.employee_id = existing.employee_id
    );

  WITH desired AS (
    SELECT
      (element ->> 'employee_id')::uuid AS employee_id,
      COALESCE(
        NULLIF(btrim(element ->> 'role'), ''),
        'tech'
      )::public.crew_role AS role
    FROM jsonb_array_elements(
      COALESCE(p_crew, '[]'::jsonb)
    ) element
  )
  UPDATE public.appointment_crew existing
  SET role = desired.role
  FROM desired
  WHERE existing.appointment_id = p_appointment_id
    AND existing.employee_id = desired.employee_id
    AND existing.role IS DISTINCT FROM desired.role;

  WITH desired AS (
    SELECT
      (element ->> 'employee_id')::uuid AS employee_id,
      COALESCE(
        NULLIF(btrim(element ->> 'role'), ''),
        'tech'
      )::public.crew_role AS role
    FROM jsonb_array_elements(
      COALESCE(p_crew, '[]'::jsonb)
    ) element
  )
  INSERT INTO public.appointment_crew (
    appointment_id,
    employee_id,
    role
  )
  SELECT
    p_appointment_id,
    desired.employee_id,
    desired.role
  FROM desired
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.appointment_crew existing
    WHERE existing.appointment_id = p_appointment_id
      AND existing.employee_id = desired.employee_id
  )
  ON CONFLICT (appointment_id, employee_id) DO NOTHING;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'employee_id', crew.employee_id,
        'role', crew.role::text
      )
      ORDER BY crew.employee_id
    ),
    '[]'::jsonb
  )
  INTO v_new_crew
  FROM public.appointment_crew crew
  WHERE crew.appointment_id = p_appointment_id;

  IF v_new_crew IS DISTINCT FROM v_old_crew THEN
    INSERT INTO public.system_events (
      event_type,
      entity_type,
      entity_id,
      actor_id,
      job_id,
      payload
    )
    VALUES (
      'appointment.crew_changed',
      'appointment',
      p_appointment_id,
      v_actor_id,
      v_job_id,
      jsonb_build_object(
        'operation', 'set_diff',
        'actor_kind', v_actor_kind,
        'old_crew', v_old_crew,
        'new_crew', v_new_crew,
        'changed_at', statement_timestamp()
      )
    );
  END IF;

  RETURN QUERY
  SELECT crew.*
  FROM public.appointment_crew crew
  WHERE crew.appointment_id = p_appointment_id
  ORDER BY crew.created_at, crew.id;
END;
$_$;


ALTER FUNCTION "public"."sync_appointment_crew"("p_appointment_id" "uuid", "p_crew" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_appointment_crew"("p_appointment_id" "uuid", "p_crew" "jsonb") IS 'UPR appointment crew atomic save/audit repair v1: enum-safe locked audited set diff';



CREATE OR REPLACE FUNCTION "public"."sync_appointment_crew"("p_appointment_id" "uuid", "p_crew" "jsonb", "p_actor_id" "uuid") RETURNS SETOF "public"."appointment_crew"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT public.is_trusted_appointment_command_caller()
     OR p_actor_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.employees employee
       WHERE employee.id = p_actor_id
         AND employee.is_active IS TRUE
         AND employee.is_external IS FALSE
         AND employee.role::text IS DISTINCT FROM 'crm_partner'
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: attributed service appointment actor required'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'upr.appointment_crew_actor_id',
    p_actor_id::text,
    true
  );

  RETURN QUERY
  SELECT crew.*
  FROM public.sync_appointment_crew(
    p_appointment_id,
    p_crew
  ) crew;
END;
$$;


ALTER FUNCTION "public"."sync_appointment_crew"("p_appointment_id" "uuid", "p_crew" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_appointment_crew"("p_appointment_id" "uuid", "p_crew" "jsonb", "p_actor_id" "uuid") IS 'UPR appointment crew atomic save/audit repair v1: service-only explicit employee-attributed set diff';



CREATE OR REPLACE FUNCTION "public"."sync_job_invoiced_from_invoices"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count int;
  v_sum   numeric;
  v_date  timestamptz;
BEGIN
  IF p_job_id IS NULL THEN RETURN; END IF;

  SELECT count(*),
         COALESCE(sum(COALESCE(adjusted_total, total)), 0),
         min(qbo_synced_at)
    INTO v_count, v_sum, v_date
    FROM invoices
   WHERE job_id = p_job_id
     AND qbo_invoice_id IS NOT NULL;

  -- Only write when the job actually has pushed invoices; never zero legacy values.
  IF v_count > 0 THEN
    UPDATE jobs
       SET invoiced_value = v_sum,
           invoiced_date  = COALESCE(invoiced_date, v_date::date),
           updated_at     = now()
     WHERE id = p_job_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."sync_job_invoiced_from_invoices"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_job_to_claim"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Only sync if claim_id exists
  IF NEW.claim_id IS NULL THEN RETURN NEW; END IF;

  -- Sync insurance_company → claim.insurance_carrier (if claim's is null or job changed)
  IF NEW.insurance_company IS DISTINCT FROM OLD.insurance_company AND NEW.insurance_company IS NOT NULL THEN
    UPDATE claims SET insurance_carrier = NEW.insurance_company, updated_at = now()
    WHERE id = NEW.claim_id AND (insurance_carrier IS NULL OR insurance_carrier = OLD.insurance_company);
  END IF;

  -- Sync date_of_loss → claim.date_of_loss
  IF NEW.date_of_loss IS DISTINCT FROM OLD.date_of_loss AND NEW.date_of_loss IS NOT NULL THEN
    UPDATE claims SET date_of_loss = NEW.date_of_loss, updated_at = now()
    WHERE id = NEW.claim_id AND (date_of_loss IS NULL OR date_of_loss = OLD.date_of_loss);
  END IF;

  -- Sync address → claim loss_address
  IF NEW.address IS DISTINCT FROM OLD.address AND NEW.address IS NOT NULL THEN
    UPDATE claims SET loss_address = NEW.address, loss_city = NEW.city, loss_state = NEW.state, loss_zip = NEW.zip, updated_at = now()
    WHERE id = NEW.claim_id AND (loss_address IS NULL OR loss_address = OLD.address);
  END IF;

  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."sync_job_to_claim"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tech_hours_bucket"("p_employee_id" "uuid", "p_start" "date", "p_end" "date", "p_now" timestamp with time zone, "p_open" "public"."job_time_entries") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_onsite_stored numeric;
  v_travel_stored numeric;
  v_live_onsite   numeric := 0;
  v_live_travel   numeric := 0;
  v_onsite        numeric;
  v_travel        numeric;
BEGIN
  SELECT COALESCE(SUM(hours), 0), COALESCE(SUM(travel_minutes), 0) / 60.0
  INTO v_onsite_stored, v_travel_stored
  FROM job_time_entries
  WHERE employee_id = p_employee_id AND work_date BETWEEN p_start AND p_end;

  IF p_open.id IS NOT NULL AND p_open.work_date BETWEEN p_start AND p_end THEN
    IF p_open.clock_in IS NOT NULL THEN
      v_live_onsite := GREATEST(0,
        EXTRACT(EPOCH FROM (p_now - p_open.clock_in)) / 3600.0
        - COALESCE(p_open.total_paused_minutes, 0) / 60.0
        - CASE WHEN p_open.paused_at IS NOT NULL
               THEN EXTRACT(EPOCH FROM (p_now - p_open.paused_at)) / 3600.0 ELSE 0 END);
    ELSIF p_open.travel_start IS NOT NULL THEN
      v_live_travel := GREATEST(0, EXTRACT(EPOCH FROM (p_now - p_open.travel_start)) / 3600.0);
    END IF;
  END IF;

  v_onsite := ROUND((v_onsite_stored + v_live_onsite)::numeric, 2);
  v_travel := ROUND((v_travel_stored + v_live_travel)::numeric, 2);

  RETURN jsonb_build_object(
    'on_site', v_onsite,
    'travel', v_travel,
    'total', ROUND((v_onsite + v_travel)::numeric, 2)
  );
END;
$$;


ALTER FUNCTION "public"."tech_hours_bucket"("p_employee_id" "uuid", "p_start" "date", "p_end" "date", "p_now" timestamp with time zone, "p_open" "public"."job_time_entries") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_appointment_task"("p_task_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_current boolean;
  result jsonb;
BEGIN
  SELECT is_completed INTO v_current FROM job_tasks WHERE id = p_task_id;

  IF v_current THEN
    UPDATE job_tasks SET is_completed = false, completed_by = NULL, completed_at = NULL
    WHERE id = p_task_id;
  ELSE
    UPDATE job_tasks SET is_completed = true, completed_by = p_employee_id, completed_at = now()
    WHERE id = p_task_id;
  END IF;

  SELECT jsonb_build_object(
    'id', jt.id, 'is_completed', jt.is_completed,
    'completed_by', jt.completed_by, 'completed_at', jt.completed_at,
    'completed_by_name', e.display_name
  ) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.id = p_task_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."toggle_appointment_task"("p_task_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_job_task"("p_task_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_current boolean;
  result jsonb;
BEGIN
  SELECT is_completed INTO v_current FROM job_tasks WHERE id = p_task_id;

  IF v_current THEN
    -- Un-complete: also unassign from appointment so it returns to pool
    UPDATE job_tasks SET is_completed = false, completed_by = NULL, completed_at = NULL, appointment_id = NULL
    WHERE id = p_task_id;
  ELSE
    UPDATE job_tasks SET is_completed = true, completed_by = p_employee_id, completed_at = now()
    WHERE id = p_task_id;
  END IF;

  SELECT jsonb_build_object(
    'id', jt.id, 'is_completed', jt.is_completed,
    'completed_by', jt.completed_by, 'completed_at', jt.completed_at,
    'completed_by_name', e.display_name
  ) INTO result
  FROM job_tasks jt
  LEFT JOIN employees e ON e.id = jt.completed_by
  WHERE jt.id = p_task_id;

  RETURN result;
END;
$$;


