CREATE OR REPLACE FUNCTION "public"."trg_appt_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.notify_emit('appointment.canceled', jsonb_build_object('appointment_id', NEW.id));
    RETURN NEW;
  END IF;
  IF (NEW.title, NEW.date, NEW.time_start, NEW.time_end, NEW.status, NEW.job_id)
     IS NOT DISTINCT FROM
     (OLD.title, OLD.date, OLD.time_start, OLD.time_end, OLD.status, OLD.job_id)
  THEN RETURN NEW; END IF;
  PERFORM public.notify_emit('appointment.updated', jsonb_build_object('appointment_id', NEW.id));
  RETURN NEW;
END; $$;


