CREATE OR REPLACE FUNCTION "public"."trigger_claim_events"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM log_system_event(
      'claim.created', 'claim', NEW.id, NULL, NULL,
      jsonb_build_object('claim_number', NEW.claim_number, 'status', NEW.status, 'insurance_carrier', NEW.insurance_carrier)
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Status change (covers soft delete)
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      PERFORM log_system_event('claim.status_changed', 'claim', NEW.id, NULL, NEW.updated_by,
        jsonb_build_object('from', OLD.status, 'to', NEW.status, 'claim_number', NEW.claim_number));
    END IF;
    -- Insurance carrier change
    IF OLD.insurance_carrier IS DISTINCT FROM NEW.insurance_carrier THEN
      PERFORM log_system_event('claim.carrier_changed', 'claim', NEW.id, NULL, NEW.updated_by,
        jsonb_build_object('from', OLD.insurance_carrier, 'to', NEW.insurance_carrier));
    END IF;
    -- Contact changed
    IF OLD.contact_id IS DISTINCT FROM NEW.contact_id THEN
      PERFORM log_system_event('claim.contact_changed', 'claim', NEW.id, NULL, NEW.updated_by,
        jsonb_build_object('from', OLD.contact_id, 'to', NEW.contact_id));
    END IF;
    -- Deductible changed
    IF OLD.deductible IS DISTINCT FROM NEW.deductible THEN
      PERFORM log_system_event('claim.deductible_changed', 'claim', NEW.id, NULL, NEW.updated_by,
        jsonb_build_object('from', OLD.deductible, 'to', NEW.deductible));
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trigger_claim_events"() OWNER TO "postgres";


