CREATE OR REPLACE FUNCTION "public"."trigger_job_events"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM log_system_event(
      'job.created', 'job', NEW.id, NEW.id, NEW.project_manager_id,
      jsonb_build_object('job_number', NEW.job_number, 'insured_name', NEW.insured_name, 'division', NEW.division, 'phase', NEW.phase)
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Status change (covers soft delete)
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      PERFORM log_system_event('job.status_changed', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.status, 'to', NEW.status, 'job_number', NEW.job_number));
    END IF;
    -- Phase change
    IF OLD.phase IS DISTINCT FROM NEW.phase THEN
      PERFORM log_system_event('job.phase_changed', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.phase, 'to', NEW.phase, 'job_number', NEW.job_number));
    END IF;
    -- Priority change
    IF OLD.priority IS DISTINCT FROM NEW.priority THEN
      PERFORM log_system_event('job.priority_changed', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.priority, 'to', NEW.priority));
    END IF;
    -- PM assigned
    IF OLD.project_manager_id IS DISTINCT FROM NEW.project_manager_id THEN
      PERFORM log_system_event('job.pm_assigned', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.project_manager_id, 'to', NEW.project_manager_id));
    END IF;
    -- Tech assigned
    IF OLD.lead_tech_id IS DISTINCT FROM NEW.lead_tech_id THEN
      PERFORM log_system_event('job.tech_assigned', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.lead_tech_id, 'to', NEW.lead_tech_id));
    END IF;
    -- Approved value
    IF OLD.approved_value IS DISTINCT FROM NEW.approved_value THEN
      PERFORM log_system_event('job.approved_value_changed', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.approved_value, 'to', NEW.approved_value));
    END IF;
    -- Collected value
    IF OLD.collected_value IS DISTINCT FROM NEW.collected_value THEN
      PERFORM log_system_event('job.payment_received', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.collected_value, 'to', NEW.collected_value, 'amount', COALESCE(NEW.collected_value, 0) - COALESCE(OLD.collected_value, 0)));
    END IF;
    -- Division change
    IF OLD.division IS DISTINCT FROM NEW.division THEN
      PERFORM log_system_event('job.division_changed', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.division, 'to', NEW.division));
    END IF;
    -- Invoiced value
    IF OLD.invoiced_value IS DISTINCT FROM NEW.invoiced_value THEN
      PERFORM log_system_event('job.invoiced_value_changed', 'job', NEW.id, NEW.id, NEW.updated_by,
        jsonb_build_object('from', OLD.invoiced_value, 'to', NEW.invoiced_value));
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trigger_job_events"() OWNER TO "postgres";


