      jsonb_build_object('type', NEW.type, 'channel', NEW.channel, 'body_preview', LEFT(NEW.body, 100), 'conversation_id', NEW.conversation_id)
    );
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


