CREATE OR REPLACE FUNCTION "public"."update_appointment"("p_appointment_id" "uuid", "p_date" "date" DEFAULT NULL::"date", "p_time_start" time without time zone DEFAULT NULL::time without time zone, "p_time_end" time without time zone DEFAULT NULL::time without time zone, "p_title" "text" DEFAULT NULL::"text", "p_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_is_trusted boolean :=
    public.is_trusted_appointment_command_caller();
  v_result jsonb;
  v_old_date date;
  v_old_time_start time;
  v_old_time_end time;
  v_old_status text;
BEGIN
  IF p_appointment_id IS NULL THEN
    RAISE EXCEPTION
      'update_appointment: p_appointment_id is required'
      USING ERRCODE = '22023';
  END IF;

  IF v_is_trusted THEN
    IF p_actor_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.employees employee
         WHERE employee.id = p_actor_id
           AND employee.is_active IS TRUE
           AND employee.is_external IS FALSE
           AND employee.role::text IS DISTINCT FROM 'crm_partner'
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: active internal appointment actor required'
        USING ERRCODE = '42501';
    END IF;
    v_actor_id := p_actor_id;
  ELSE
    v_actor_id :=
      public.current_active_internal_appointment_employee();
    IF v_actor_id IS NULL
       OR (
         p_actor_id IS NOT NULL
         AND p_actor_id IS DISTINCT FROM v_actor_id
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment actor does not match caller'
      USING ERRCODE = '42501';
    END IF;
  END IF;

  PERFORM pg_catalog.set_config(
    'upr.appointment_crew_actor_id',
    v_actor_id::text,
    true
  );

  SELECT
    appointment.date,
    appointment.time_start,
    appointment.time_end,
    appointment.status::text
  INTO
    v_old_date,
    v_old_time_start,
    v_old_time_end,
    v_old_status
  FROM public.appointments appointment
  WHERE appointment.id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'update_appointment: appointment not found'
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT v_is_trusted
     AND NOT public.can_current_employee_edit_appointment_command(
       p_appointment_id
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment mutation access required'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.appointments appointment
  SET
    date = COALESCE(p_date, appointment.date),
    time_start = COALESCE(
      p_time_start,
      appointment.time_start
    ),
    time_end = COALESCE(p_time_end, appointment.time_end),
    title = COALESCE(p_title, appointment.title),
    type = COALESCE(
      p_type::public.appointment_type,
      appointment.type
    ),
    status = COALESCE(
      p_status::public.appointment_status,
      appointment.status
    ),
    notes = COALESCE(p_notes, appointment.notes)
  WHERE appointment.id = p_appointment_id
  RETURNING jsonb_build_object(
    'id', appointment.id,
    'date', appointment.date,
    'time_start', appointment.time_start,
    'time_end', appointment.time_end,
    'title', appointment.title,
    'status', appointment.status
  )
  INTO v_result;

  IF (v_result ->> 'date')::date IS DISTINCT FROM v_old_date
     OR (v_result ->> 'time_start')::time
        IS DISTINCT FROM v_old_time_start
     OR (v_result ->> 'time_end')::time
        IS DISTINCT FROM v_old_time_end THEN
    INSERT INTO public.appointment_status_history (
      appointment_id,
      event_type,
      old_date,
      old_time_start,
      old_time_end,
      old_status,
      new_date,
      new_time_start,
      new_time_end,
      new_status,
      actor_id
    )
    VALUES (
      p_appointment_id,
      'rescheduled',
      v_old_date,
      v_old_time_start,
      v_old_time_end,
      v_old_status,
      (v_result ->> 'date')::date,
      (v_result ->> 'time_start')::time,
      (v_result ->> 'time_end')::time,
      v_result ->> 'status',
      v_actor_id
    );
  ELSIF (v_result ->> 'status') IS DISTINCT FROM v_old_status THEN
    INSERT INTO public.appointment_status_history (
      appointment_id,
      event_type,
      old_status,
      new_status,
      actor_id
    )
    VALUES (
      p_appointment_id,
      CASE
        WHEN v_result ->> 'status' = 'cancelled'
          THEN 'cancelled'
        ELSE 'status_changed'
      END,
      v_old_status,
      v_result ->> 'status',
      v_actor_id
    );
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."update_appointment"("p_appointment_id" "uuid", "p_date" "date", "p_time_start" time without time zone, "p_time_end" time without time zone, "p_title" "text", "p_type" "text", "p_status" "text", "p_notes" "text", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_appointment"("p_appointment_id" "uuid", "p_date" "date", "p_time_start" time without time zone, "p_time_end" time without time zone, "p_title" "text", "p_type" "text", "p_status" "text", "p_notes" "text", "p_actor_id" "uuid") IS 'UPR appointment crew atomic save/audit repair v1: legacy-compatible actor-bound appointment update';



CREATE OR REPLACE FUNCTION "public"."update_appointment_with_crew"("p_appointment_id" "uuid", "p_date" "date" DEFAULT NULL::"date", "p_time_start" time without time zone DEFAULT NULL::time without time zone, "p_time_end" time without time zone DEFAULT NULL::time without time zone, "p_title" "text" DEFAULT NULL::"text", "p_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_crew" "jsonb" DEFAULT NULL::"jsonb", "p_is_private" boolean DEFAULT NULL::boolean, "p_notify_client" boolean DEFAULT NULL::boolean, "p_task_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_set_time_start" boolean DEFAULT false, "p_set_time_end" boolean DEFAULT false, "p_set_notes" boolean DEFAULT false, "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_actor_role text;
  v_is_trusted boolean :=
    public.is_trusted_appointment_command_caller();
  v_existing public.appointments%ROWTYPE;
  v_result jsonb;
  v_has_core_change boolean;
  v_has_noncrew_intent boolean;
  v_can_access boolean := false;
  v_set_time_start boolean;
  v_set_time_end boolean;
  v_set_notes boolean;
  v_target_time_start time without time zone;
  v_target_time_end time without time zone;
  v_target_notes text;
BEGIN
  IF p_appointment_id IS NULL THEN
    RAISE EXCEPTION
      'update_appointment_with_crew: p_appointment_id is required'
      USING ERRCODE = '22023';
  END IF;

  IF v_is_trusted THEN
    IF p_actor_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.employees employee
         WHERE employee.id = p_actor_id
           AND employee.is_active IS TRUE
           AND employee.is_external IS FALSE
           AND employee.role::text IS DISTINCT FROM 'crm_partner'
       ) THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: active internal appointment actor required'
        USING ERRCODE = '42501';
    END IF;
    PERFORM pg_catalog.set_config(
      'upr.appointment_crew_actor_id',
      p_actor_id::text,
      true
    );
  ELSE
    v_actor_id :=
      public.current_active_internal_appointment_employee();
    IF p_actor_id IS NOT NULL
       AND p_actor_id IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION
        'NOT_AUTHORIZED: appointment actor does not match caller'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_actor_id :=
    public.current_attributed_appointment_crew_actor();
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: attributed active internal appointment actor required'
      USING ERRCODE = '42501';
  END IF;
  SELECT employee.role::text
  INTO v_actor_role
  FROM public.employees employee
  WHERE employee.id = v_actor_id;
  PERFORM pg_catalog.set_config(
    'upr.appointment_crew_actor_id',
    v_actor_id::text,
    true
  );

  SELECT appointment.*
  INTO v_existing
  FROM public.appointments appointment
  WHERE appointment.id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'update_appointment_with_crew: appointment not found'
      USING ERRCODE = 'P0001';
  END IF;

  v_set_time_start :=
    COALESCE(p_set_time_start, false) OR p_time_start IS NOT NULL;
  v_set_time_end :=
    COALESCE(p_set_time_end, false) OR p_time_end IS NOT NULL;
  v_set_notes :=
    COALESCE(p_set_notes, false) OR p_notes IS NOT NULL;
  v_target_time_start := CASE
    WHEN v_set_time_start THEN p_time_start
    ELSE v_existing.time_start
  END;
  v_target_time_end := CASE
    WHEN v_set_time_end THEN p_time_end
    ELSE v_existing.time_end
  END;
  v_target_notes := CASE
    WHEN v_set_notes THEN
      NULLIF(btrim(COALESCE(p_notes, '')), '')
    ELSE v_existing.notes
  END;

  IF v_target_time_start IS NOT NULL
     AND v_target_time_end IS NOT NULL
     AND v_target_time_end <= v_target_time_start THEN
    RAISE EXCEPTION
      'update_appointment_with_crew: end time must follow start time'
      USING ERRCODE = '22023';
  END IF;

  v_has_core_change :=
    (p_date IS NOT NULL AND p_date IS DISTINCT FROM v_existing.date)
    OR v_target_time_start IS DISTINCT FROM v_existing.time_start
    OR v_target_time_end IS DISTINCT FROM v_existing.time_end
    OR (
      p_title IS NOT NULL
      AND p_title IS DISTINCT FROM v_existing.title
    )
    OR (
      p_type IS NOT NULL
      AND p_type IS DISTINCT FROM v_existing.type::text
    )
    OR (
      p_status IS NOT NULL
      AND p_status IS DISTINCT FROM v_existing.status::text
    )
    OR v_target_notes IS DISTINCT FROM v_existing.notes;

  v_has_noncrew_intent :=
    p_date IS NOT NULL
    OR v_set_time_start
    OR v_set_time_end
    OR p_title IS NOT NULL
    OR p_type IS NOT NULL
    OR p_status IS NOT NULL
    OR v_set_notes
    OR p_is_private IS NOT NULL
    OR p_notify_client IS NOT NULL
    OR p_task_ids IS NOT NULL;

  IF NOT v_is_trusted THEN
    v_can_access :=
      public.can_current_employee_access_appointment_command(
        p_appointment_id
      );
  END IF;

  IF NOT v_is_trusted
     AND v_has_noncrew_intent
     AND NOT public.can_current_employee_edit_appointment_command(
       p_appointment_id
     ) THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment mutation access required'
      USING ERRCODE = '42501';
  END IF;

  IF NOT v_is_trusted
     AND NOT v_has_noncrew_intent
     AND p_crew IS NULL
     AND NOT v_can_access THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment access required'
      USING ERRCODE = '42501';
  END IF;

  IF p_is_private IS NOT NULL
     AND p_is_private IS DISTINCT FROM v_existing.is_private
     AND NOT v_is_trusted
     AND v_actor_role NOT IN ('admin', 'project_manager') THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: appointment privacy manager required'
      USING ERRCODE = '42501';
  END IF;

  IF p_task_ids IS NOT NULL THEN
    PERFORM 1
    FROM public.job_tasks task
    WHERE task.id = ANY(p_task_ids)
    ORDER BY task.id
    FOR UPDATE;

    IF cardinality(p_task_ids) IS DISTINCT FROM (
      SELECT count(*)::integer
      FROM public.job_tasks task
      WHERE task.id = ANY(p_task_ids)
        AND task.job_id = v_existing.job_id
        AND (
          task.appointment_id IS NULL
          OR task.appointment_id = p_appointment_id
        )
    ) THEN
      RAISE EXCEPTION
        'update_appointment_with_crew: task IDs must be unique, unassigned/current, and belong to the appointment job'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  -- Preserve the existing notify-before-reschedule ordering so downstream
  -- client-notification triggers see the checkbox chosen in this save.
  IF p_notify_client IS NOT NULL
     AND p_notify_client IS DISTINCT FROM v_existing.notify_client THEN
    UPDATE public.appointments
    SET notify_client = p_notify_client
    WHERE id = p_appointment_id;
  END IF;

  IF v_has_core_change THEN
    UPDATE public.appointments appointment
    SET
      date = COALESCE(p_date, appointment.date),
      time_start = v_target_time_start,
      time_end = v_target_time_end,
      title = COALESCE(p_title, appointment.title),
      type = COALESCE(
        p_type::public.appointment_type,
        appointment.type
      ),
      status = COALESCE(
        p_status::public.appointment_status,
        appointment.status
      ),
      notes = v_target_notes
    WHERE appointment.id = p_appointment_id
    RETURNING jsonb_build_object(
      'id', appointment.id,
      'date', appointment.date,
      'time_start', appointment.time_start,
      'time_end', appointment.time_end,
      'title', appointment.title,
      'status', appointment.status
    )
    INTO v_result;

    IF (v_result ->> 'date')::date
         IS DISTINCT FROM v_existing.date
       OR (v_result ->> 'time_start')::time
         IS DISTINCT FROM v_existing.time_start
       OR (v_result ->> 'time_end')::time
         IS DISTINCT FROM v_existing.time_end THEN
      INSERT INTO public.appointment_status_history (
        appointment_id,
        event_type,
        old_date,
        old_time_start,
        old_time_end,
        old_status,
        new_date,
        new_time_start,
        new_time_end,
        new_status,
        actor_id
      )
      VALUES (
        p_appointment_id,
        'rescheduled',
        v_existing.date,
        v_existing.time_start,
        v_existing.time_end,
        v_existing.status::text,
        (v_result ->> 'date')::date,
        (v_result ->> 'time_start')::time,
        (v_result ->> 'time_end')::time,
        v_result ->> 'status',
        v_actor_id
      );
    ELSIF (v_result ->> 'status')
      IS DISTINCT FROM v_existing.status::text THEN
      INSERT INTO public.appointment_status_history (
        appointment_id,
        event_type,
        old_status,
        new_status,
        actor_id
      )
      VALUES (
        p_appointment_id,
        CASE
          WHEN v_result ->> 'status' = 'cancelled'
            THEN 'cancelled'
          ELSE 'status_changed'
        END,
        v_existing.status::text,
        v_result ->> 'status',
        v_actor_id
      );
    END IF;
  ELSE
    v_result := jsonb_build_object(
      'id', v_existing.id,
      'date', v_existing.date,
      'time_start', v_existing.time_start,
      'time_end', v_existing.time_end,
      'title', v_existing.title,
      'status', v_existing.status
    );
  END IF;

  IF p_is_private IS NOT NULL
     AND p_is_private IS DISTINCT FROM v_existing.is_private THEN
    UPDATE public.appointments
    SET is_private = p_is_private
    WHERE id = p_appointment_id;
  END IF;

  IF p_crew IS NOT NULL THEN
    PERFORM *
    FROM public.sync_appointment_crew(
      p_appointment_id,
      p_crew
    );
  END IF;

  IF p_task_ids IS NOT NULL THEN
    PERFORM public.assign_tasks_to_appointment(
      p_appointment_id,
      p_task_ids
    );
  END IF;

  IF NOT v_is_trusted AND NOT v_can_access THEN
    RETURN jsonb_build_object(
      'id',
      p_appointment_id,
      'crew_changed',
      p_crew IS NOT NULL
    );
  END IF;

  RETURN v_result || jsonb_build_object(
    'is_private', COALESCE(p_is_private, v_existing.is_private),
    'notify_client', COALESCE(
      p_notify_client,
      v_existing.notify_client
    )
  );
END;
$$;


ALTER FUNCTION "public"."update_appointment_with_crew"("p_appointment_id" "uuid", "p_date" "date", "p_time_start" time without time zone, "p_time_end" time without time zone, "p_title" "text", "p_type" "text", "p_status" "text", "p_notes" "text", "p_crew" "jsonb", "p_is_private" boolean, "p_notify_client" boolean, "p_task_ids" "uuid"[], "p_set_time_start" boolean, "p_set_time_end" boolean, "p_set_notes" boolean, "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_appointment_with_crew"("p_appointment_id" "uuid", "p_date" "date", "p_time_start" time without time zone, "p_time_end" time without time zone, "p_title" "text", "p_type" "text", "p_status" "text", "p_notes" "text", "p_crew" "jsonb", "p_is_private" boolean, "p_notify_client" boolean, "p_task_ids" "uuid"[], "p_set_time_start" boolean, "p_set_time_end" boolean, "p_set_notes" boolean, "p_actor_id" "uuid") IS 'UPR appointment crew atomic save/audit repair v1: atomic appointment, history, crew, privacy, preference, and task assignment update';



