CREATE OR REPLACE FUNCTION "public"."update_lead_status"("p_lead_id" "uuid", "p_status" "text", "p_notes" "text" DEFAULT NULL::"text", "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row inbound_leads;
BEGIN
  UPDATE inbound_leads
     SET lead_status = p_status,
         notes       = COALESCE(p_notes, notes),
         updated_at  = now()
   WHERE id = p_lead_id
   RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown inbound_leads id: %', p_lead_id;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_status_updated', 'inbound_lead', v_row.id, p_updated_by, jsonb_build_object('status', p_status));

  RETURN v_row;
END;
$$;


