    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "token" "text" NOT NULL,
    "platform" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "apns_environment" "text",
    "apns_topic" "text",
    CONSTRAINT "device_tokens_apns_environment_check" CHECK ((("apns_environment" IS NULL) OR ("apns_environment" = ANY (ARRAY['sandbox'::"text", 'production'::"text"])))),
    CONSTRAINT "device_tokens_apns_topic_check" CHECK ((("apns_topic" IS NULL) OR ("apns_topic" ~ '^[A-Za-z0-9][A-Za-z0-9.-]{0,254}$'::"text"))),
    CONSTRAINT "device_tokens_platform_check" CHECK (("platform" = ANY (ARRAY['ios'::"text", 'android'::"text", 'web'::"text"])))
);

