ALTER TABLE "public"."device_tokens" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_device_token"("p_employee_id" "uuid", "p_token" "text", "p_platform" "text") RETURNS "public"."device_tokens"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.device_tokens;
BEGIN
  INSERT INTO public.device_tokens (employee_id, token, platform)
  VALUES (p_employee_id, p_token, p_platform)
  ON CONFLICT (token) DO UPDATE
    SET employee_id = EXCLUDED.employee_id,
        platform    = EXCLUDED.platform,
        updated_at  = now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


