CREATE OR REPLACE FUNCTION "public"."upsert_document_template"("p_doc_type" "text", "p_division" "text" DEFAULT NULL::"text", "p_heading" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text", "p_sort_order" integer DEFAULT 0) RETURNS "public"."document_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result document_templates;
BEGIN
  UPDATE document_templates
  SET
    heading    = COALESCE(p_heading,    heading),
    body       = COALESCE(p_body,       body),
    sort_order = COALESCE(p_sort_order, sort_order),
    updated_at = now()
  WHERE
    doc_type = p_doc_type
    AND (
      (division IS NULL AND p_division IS NULL) OR
      (division = p_division)
    )
  RETURNING * INTO result;

  IF NOT FOUND THEN
    INSERT INTO document_templates (doc_type, division, heading, body, sort_order)
    VALUES (p_doc_type, p_division,
            COALESCE(p_heading, ''), COALESCE(p_body, ''), COALESCE(p_sort_order, 0))
    RETURNING * INTO result;
  END IF;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."upsert_document_template"("p_doc_type" "text", "p_division" "text", "p_heading" "text", "p_body" "text", "p_sort_order" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_email_campaign"("p_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_subject" "text" DEFAULT NULL::"text", "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_body_html" "text" DEFAULT ''::"text", "p_audience_filter" "jsonb" DEFAULT '{}'::"jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."email_campaigns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_count  int;
  v_row    email_campaigns;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Campaign name is required';
  END IF;
  IF p_subject IS NULL OR btrim(p_subject) = '' THEN
    RAISE EXCEPTION 'Subject line is required';
  END IF;
  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  SELECT count(*) INTO v_count FROM preview_email_audience(p_audience_filter, v_org_id);
  IF p_id IS NULL THEN
    INSERT INTO email_campaigns (org_id, name, subject, template_id, body_html, audience_filter, audience_count, created_by)
    VALUES (v_org_id, btrim(p_name), btrim(p_subject), p_template_id, COALESCE(p_body_html, ''), COALESCE(p_audience_filter, '{}'::jsonb), v_count, p_created_by)
    RETURNING * INTO v_row;
    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_email_campaign_created', 'email_campaign', v_row.id, p_created_by,
      jsonb_build_object('campaign_id', v_row.id, 'name', v_row.name, 'audience_count', v_row.audience_count));
  ELSE
    UPDATE email_campaigns
       SET name = btrim(p_name),
           subject = btrim(p_subject),
           template_id = p_template_id,
           body_html = COALESCE(p_body_html, ''),
           audience_filter = COALESCE(p_audience_filter, '{}'::jsonb),
           audience_count = v_count,
           updated_at = now()
     WHERE id = p_id AND status = 'draft'
     RETURNING * INTO v_row;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Campaign not found or is no longer a draft';
    END IF;
    INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
    VALUES ('crm_email_campaign_updated', 'email_campaign', v_row.id, p_created_by,
      jsonb_build_object('campaign_id', v_row.id, 'name', v_row.name, 'audience_count', v_row.audience_count));
  END IF;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_email_campaign"("p_id" "uuid", "p_name" "text", "p_subject" "text", "p_template_id" "uuid", "p_body_html" "text", "p_audience_filter" "jsonb", "p_org_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


