CREATE TABLE IF NOT EXISTS "public"."lead_attribution" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "contact_id" "uuid",
    "channel" "text" NOT NULL,
    "source" "text",
    "campaign" "text",
    "referral_source_id" "uuid",
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "lead_attribution_channel_check" CHECK (("channel" = ANY (ARRAY['google_ads'::"text", 'meta_ads'::"text", 'organic'::"text", 'referral'::"text", 'insurance'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."lead_attribution" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_lead_attribution"("p_channel" "text", "p_source" "text" DEFAULT NULL::"text", "p_campaign" "text" DEFAULT NULL::"text", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_referral_source_id" "uuid" DEFAULT NULL::"uuid", "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."lead_attribution"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_row lead_attribution;
BEGIN
  IF p_channel NOT IN ('google_ads','meta_ads','organic','referral','insurance','other') THEN
    RAISE EXCEPTION 'invalid attribution channel: %', p_channel;
  END IF;
  IF p_lead_id IS NULL AND p_contact_id IS NULL THEN
    RAISE EXCEPTION 'lead_attribution needs a lead_id or a contact_id';
  END IF;
  v_org := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  INSERT INTO lead_attribution (
    org_id, lead_id, contact_id, channel, source, campaign,
    referral_source_id, occurred_at, created_by
  ) VALUES (
    v_org, p_lead_id, p_contact_id, p_channel, p_source, p_campaign,
    p_referral_source_id, COALESCE(p_occurred_at, now()), p_created_by
  )
  RETURNING * INTO v_row;
  INSERT INTO system_events (event_type, entity_type, entity_id, actor_id, payload)
  VALUES ('crm_lead_attributed', 'lead_attribution', v_row.id, p_created_by,
          jsonb_build_object('channel', p_channel, 'campaign', p_campaign));
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_lead_attribution"("p_channel" "text", "p_source" "text", "p_campaign" "text", "p_lead_id" "uuid", "p_contact_id" "uuid", "p_referral_source_id" "uuid", "p_occurred_at" timestamp with time zone, "p_created_by" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_lead_from_callrail"("p_callrail_id" "text", "p_source_type" "text", "p_tracking_number" "text" DEFAULT NULL::"text", "p_caller_number" "text" DEFAULT NULL::"text", "p_duration_sec" integer DEFAULT NULL::integer, "p_spam_flag" boolean DEFAULT false, "p_source" "text" DEFAULT NULL::"text", "p_medium" "text" DEFAULT NULL::"text", "p_campaign" "text" DEFAULT NULL::"text", "p_recording_url" "text" DEFAULT NULL::"text", "p_transcription" "text" DEFAULT NULL::"text", "p_form_data" "jsonb" DEFAULT NULL::"jsonb", "p_lead_status" "text" DEFAULT 'new'::"text", "p_value" numeric DEFAULT NULL::numeric, "p_direction" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_raw_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id          uuid;
  v_contact_id      uuid;
  v_match_count     int;
  v_existed         boolean;
  v_row             inbound_leads;
  v_caller_digits   text;
  v_open_lead_id    uuid;
  v_missed_stage_id uuid;
BEGIN
  IF p_source_type NOT IN ('call', 'form') THEN
    RAISE EXCEPTION 'invalid inbound_leads source_type: %', p_source_type;
  END IF;

  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  IF p_caller_number IS NOT NULL THEN
    v_caller_digits := regexp_replace(p_caller_number, '\D', '', 'g');
    IF length(v_caller_digits) >= 10 THEN
      SELECT count(*) INTO v_match_count
      FROM contacts
      WHERE phone IS NOT NULL
        AND length(regexp_replace(phone, '\D', '', 'g')) >= 10
        AND right(regexp_replace(phone, '\D', '', 'g'), 10) = right(v_caller_digits, 10);

      IF v_match_count = 1 THEN
        SELECT id INTO v_contact_id
        FROM contacts
        WHERE phone IS NOT NULL
          AND length(regexp_replace(phone, '\D', '', 'g')) >= 10
          AND right(regexp_replace(phone, '\D', '', 'g'), 10) = right(v_caller_digits, 10);
      END IF;
    END IF;
  END IF;

  SELECT EXISTS (SELECT 1 FROM inbound_leads WHERE callrail_id = p_callrail_id) INTO v_existed;

  INSERT INTO inbound_leads (
    org_id, contact_id, source_type, callrail_id, tracking_number, caller_number,
    duration_sec, spam_flag, source, medium, campaign, recording_url, transcription,
    form_data, lead_status, value, direction, occurred_at, raw_payload
  ) VALUES (
    v_org_id, v_contact_id, p_source_type, p_callrail_id, p_tracking_number, p_caller_number,
    p_duration_sec, p_spam_flag, p_source, p_medium, p_campaign, p_recording_url, p_transcription,
    p_form_data, p_lead_status, p_value, p_direction, p_occurred_at, p_raw_payload
  )
  ON CONFLICT (callrail_id) DO UPDATE SET
    contact_id      = COALESCE(inbound_leads.contact_id, EXCLUDED.contact_id),
    tracking_number = COALESCE(EXCLUDED.tracking_number, inbound_leads.tracking_number),
    caller_number   = COALESCE(EXCLUDED.caller_number, inbound_leads.caller_number),
    duration_sec    = COALESCE(EXCLUDED.duration_sec, inbound_leads.duration_sec),
    spam_flag       = EXCLUDED.spam_flag,
    source          = COALESCE(EXCLUDED.source, inbound_leads.source),
    medium          = COALESCE(EXCLUDED.medium, inbound_leads.medium),
    campaign        = COALESCE(EXCLUDED.campaign, inbound_leads.campaign),
    recording_url   = COALESCE(EXCLUDED.recording_url, inbound_leads.recording_url),
    transcription   = COALESCE(EXCLUDED.transcription, inbound_leads.transcription),
    form_data       = COALESCE(EXCLUDED.form_data, inbound_leads.form_data),
    value           = COALESCE(EXCLUDED.value, inbound_leads.value),
    raw_payload     = EXCLUDED.raw_payload,
    updated_at      = now()
  RETURNING * INTO v_row;

  IF NOT v_existed AND p_caller_number IS NOT NULL AND v_caller_digits IS NOT NULL AND length(v_caller_digits) >= 10 THEN
    -- Repeat-caller merge, four explicit tiers (see header). When several
    -- candidates match, the most-alive one wins: open > recoverable-terminal
    -- (Missed Calls) > recently-won > recently-lost; oldest within a tier.
    SELECT il2.id INTO v_open_lead_id
    FROM inbound_leads il2
    LEFT JOIN lead_pipeline_stage lps2 ON lps2.lead_id = il2.id
    LEFT JOIN pipeline_stages ps2 ON ps2.id = lps2.stage_id
    WHERE il2.id <> v_row.id
      AND il2.org_id = v_org_id
      AND il2.merged_into_lead_id IS NULL
      AND COALESCE(il2.spam_flag, false) = false
      AND il2.caller_number IS NOT NULL
      AND length(regexp_replace(il2.caller_number, '\D', '', 'g')) >= 10
      AND right(regexp_replace(il2.caller_number, '\D', '', 'g'), 10) = right(v_caller_digits, 10)
      AND (
        (COALESCE(ps2.is_won, false) = false AND COALESCE(ps2.is_lost, false) = false)
        OR COALESCE(ps2.is_recoverable, false) = true
        OR (COALESCE(ps2.is_won, false) = true AND lps2.updated_at > p_occurred_at - interval '30 days')
        OR (COALESCE(ps2.is_lost, false) = true AND COALESCE(ps2.is_recoverable, false) = false
            AND il2.occurred_at > p_occurred_at - interval '3 hours')
      )
    ORDER BY CASE
               WHEN COALESCE(ps2.is_won, false) = false AND COALESCE(ps2.is_lost, false) = false THEN 0
               WHEN COALESCE(ps2.is_recoverable, false) = true THEN 1
               WHEN COALESCE(ps2.is_won, false) = true THEN 2
               ELSE 3
             END,
             il2.created_at ASC
    LIMIT 1;

    IF v_open_lead_id IS NOT NULL THEN
      UPDATE inbound_leads SET merged_into_lead_id = v_open_lead_id, updated_at = now()
      WHERE id = v_row.id;
      v_row.merged_into_lead_id := v_open_lead_id;
      v_row.updated_at := now();

      INSERT INTO system_events (event_type, entity_type, entity_id, payload)
      VALUES ('crm_lead_merged', 'inbound_lead', v_row.id,
              jsonb_build_object('merged_into_lead_id', v_open_lead_id, 'caller_number', p_caller_number));
    END IF;
  END IF;

  IF v_row.source_type = 'call'
     AND v_row.merged_into_lead_id IS NULL
     AND COALESCE(v_row.spam_flag, false) = false
     AND lower(COALESCE(v_row.raw_payload->>'answered', '')) IN ('false', 'f', '0')
     AND NOT EXISTS (SELECT 1 FROM lead_pipeline_stage lps3 WHERE lps3.lead_id = v_row.id)
  THEN
    SELECT id INTO v_missed_stage_id
    FROM pipeline_stages
    WHERE org_id = v_org_id AND name = 'Missed Calls'
    LIMIT 1;
    IF v_missed_stage_id IS NOT NULL THEN
      PERFORM move_lead_to_stage(v_row.id, v_missed_stage_id, NULL, NULL);
    END IF;
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES (
    CASE WHEN v_existed THEN 'crm_lead_updated' ELSE 'crm_lead_created' END,
    'inbound_lead',
    v_row.id,
    jsonb_build_object('source_type', v_row.source_type, 'callrail_id', v_row.callrail_id, 'contact_id', v_row.contact_id)
  );

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_lead_from_callrail"("p_callrail_id" "text", "p_source_type" "text", "p_tracking_number" "text", "p_caller_number" "text", "p_duration_sec" integer, "p_spam_flag" boolean, "p_source" "text", "p_medium" "text", "p_campaign" "text", "p_recording_url" "text", "p_transcription" "text", "p_form_data" "jsonb", "p_lead_status" "text", "p_value" numeric, "p_direction" "text", "p_occurred_at" timestamp with time zone, "p_raw_payload" "jsonb", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_lead_from_form"("p_form_id" "uuid", "p_submission_token" "text", "p_data" "jsonb", "p_utm" "jsonb" DEFAULT '{}'::"jsonb", "p_consent" boolean DEFAULT false, "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."inbound_leads"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_form        form_definitions;
  v_version     form_definition_versions;
  v_schema      jsonb;
  v_org         uuid;
  v_callrail_id text := 'form:' || COALESCE(p_submission_token, '');
  v_field       jsonb;
  v_phone_key   text;
  v_email_key   text;
  v_name_key    text;
  v_consent_lbl text := 'SMS consent';
  v_raw_phone   text;
  v_phone       text;
  v_digits      text;
  v_name        text;
  v_email       text;
  v_contact_id  uuid;
  v_source      text;
  v_medium      text;
  v_campaign    text;
  v_channel     text;
  v_row         inbound_leads;
BEGIN
  IF p_submission_token IS NULL OR btrim(p_submission_token) = '' THEN
    RAISE EXCEPTION 'submission_token is required';
  END IF;

  SELECT * INTO v_form FROM form_definitions WHERE id = p_form_id;
  IF v_form.id IS NULL THEN RAISE EXCEPTION 'form % not found', p_form_id; END IF;
  IF v_form.published_version_id IS NULL THEN RAISE EXCEPTION 'form % is not published', p_form_id; END IF;

  SELECT * INTO v_version FROM form_definition_versions WHERE id = v_form.published_version_id;
  v_schema := COALESCE(v_version.schema, '{}'::jsonb);
  v_org := COALESCE(p_org_id, v_form.org_id);

  SELECT * INTO v_row FROM inbound_leads WHERE callrail_id = v_callrail_id;
  IF v_row.id IS NOT NULL THEN
    RETURN v_row;
  END IF;

  FOR v_field IN SELECT * FROM jsonb_array_elements(COALESCE(v_schema->'fields', '[]'::jsonb)) LOOP
    IF v_field->>'type' = 'phone' AND v_phone_key IS NULL THEN v_phone_key := v_field->>'key'; END IF;
    IF v_field->>'type' = 'email' AND v_email_key IS NULL THEN v_email_key := v_field->>'key'; END IF;
    IF v_field->>'type' = 'consent' THEN v_consent_lbl := COALESCE(nullif(btrim(v_field->>'label'), ''), v_consent_lbl); END IF;
    IF v_field->>'type' = 'text' AND v_name_key IS NULL
       AND ((v_field->>'key') = 'name' OR lower(COALESCE(v_field->>'label', '')) LIKE '%name%')
    THEN v_name_key := v_field->>'key'; END IF;
  END LOOP;

  v_raw_phone := CASE WHEN v_phone_key IS NOT NULL THEN p_data->>v_phone_key ELSE NULL END;
  v_email     := CASE WHEN v_email_key IS NOT NULL THEN p_data->>v_email_key ELSE NULL END;
  v_name      := CASE WHEN v_name_key  IS NOT NULL THEN p_data->>v_name_key  ELSE NULL END;

  v_digits := regexp_replace(COALESCE(v_raw_phone, ''), '\D', '', 'g');
  IF length(v_digits) = 10 THEN v_digits := '1' || v_digits; END IF;
  IF length(v_digits) >= 10 THEN v_phone := '+' || v_digits; ELSE v_phone := NULL; END IF;

  IF v_phone IS NOT NULL THEN
    SELECT id INTO v_contact_id FROM contacts WHERE phone = v_phone LIMIT 1;
    IF v_contact_id IS NULL THEN
      INSERT INTO contacts (phone, name, email, opt_in_status)
      VALUES (v_phone, nullif(btrim(v_name), ''), nullif(btrim(v_email), ''), false)
      RETURNING id INTO v_contact_id;
    ELSE
      UPDATE contacts SET
        name  = COALESCE(name, nullif(btrim(v_name), '')),
        email = COALESCE(email, nullif(btrim(v_email), '')),
        updated_at = now()
      WHERE id = v_contact_id;
    END IF;
  END IF;

  v_source   := COALESCE(p_utm->>'utm_source', p_utm->>'source');
  v_medium   := COALESCE(p_utm->>'utm_medium', p_utm->>'medium');
  v_campaign := COALESCE(p_utm->>'utm_campaign', p_utm->>'campaign');
  v_channel  := crm_channel_for_source(v_source);

  INSERT INTO inbound_leads (
    org_id, contact_id, source_type, callrail_id, caller_number,
    spam_flag, source, medium, campaign, form_data, lead_status,
    direction, occurred_at, raw_payload
  ) VALUES (
    v_org, v_contact_id, 'form', v_callrail_id, v_phone,
    false, COALESCE(nullif(btrim(v_source), ''), v_form.name), v_medium, v_campaign, p_data, 'new',
    'inbound', now(),
    jsonb_build_object('form_id', v_form.id, 'public_id', v_form.public_id,
                       'utm', COALESCE(p_utm, '{}'::jsonb), 'user_agent', p_user_agent, 'ip', p_ip)
  )
  ON CONFLICT (callrail_id) DO NOTHING
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row FROM inbound_leads WHERE callrail_id = v_callrail_id;
    RETURN v_row;
  END IF;

  INSERT INTO form_submissions (
    form_id, version_id, org_id, submission_token, data, utm,
    lead_id, contact_id, ip_address, user_agent, is_spam
  ) VALUES (
    v_form.id, v_form.published_version_id, v_org, p_submission_token, p_data, COALESCE(p_utm, '{}'::jsonb),
    v_row.id, v_contact_id, p_ip, p_user_agent, false
  )
  ON CONFLICT (submission_token) DO NOTHING;

  PERFORM upsert_lead_attribution(v_channel, v_source, v_campaign, v_row.id, v_contact_id, NULL, now(), NULL, v_org);

  IF p_consent AND v_contact_id IS NOT NULL AND v_phone IS NOT NULL THEN
    UPDATE contacts SET
      opt_in_status = true, opt_in_source = 'web_form', opt_in_at = now(),
      opt_out_at = NULL, opt_out_reason = NULL, updated_at = now()
    WHERE id = v_contact_id;

    INSERT INTO sms_consent_log (contact_id, phone, event_type, source, details, ip_address)
    VALUES (v_contact_id, v_phone, 'opt_in', 'web_form',
            'Web-form consent (form ' || v_form.public_id || ' v' || COALESCE(v_version.version, 1) || '): ' || v_consent_lbl,
            p_ip);
  END IF;

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_lead_created', 'inbound_lead', v_row.id,
          jsonb_build_object('source_type', 'form', 'form_id', v_form.id, 'contact_id', v_contact_id));

  INSERT INTO system_events (event_type, entity_type, entity_id, payload)
  VALUES ('crm_form_submitted', 'form_definition', v_form.id,
          jsonb_build_object('submission_token', p_submission_token, 'lead_id', v_row.id,
                             'contact_id', v_contact_id, 'public_id', v_form.public_id));

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_lead_from_form"("p_form_id" "uuid", "p_submission_token" "text", "p_data" "jsonb", "p_utm" "jsonb", "p_consent" boolean, "p_ip" "text", "p_user_agent" "text", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_my_native_device_token"("p_token" "text", "p_apns_environment" "text", "p_apns_topic" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_employee_id uuid;
  v_row public.device_tokens%ROWTYPE;
BEGIN
  IF NULLIF(btrim(p_token), '') IS NULL
     OR length(p_token) > 4096
     OR p_apns_environment IS NULL
     OR p_apns_environment NOT IN ('sandbox', 'production') THEN
    RAISE EXCEPTION
      'token and an exact APNs environment are required'
      USING errcode = '22023';
  END IF;

  IF p_apns_topic IS NOT NULL
     AND p_apns_topic !~ '^[A-Za-z0-9][A-Za-z0-9.-]{0,254}$' THEN
    RAISE EXCEPTION
      'apns topic must be an app bundle identifier'
      USING errcode = '22023';
  END IF;

  SELECT employee.id
  INTO v_employee_id
  FROM public.employees employee
  WHERE employee.auth_user_id = auth.uid()
    AND employee.is_active IS TRUE
    AND employee.is_external IS FALSE
    AND employee.role::text IN (
      'admin',
      'office',
      'project_manager',
      'field_tech',
      'estimator',
      'supervisor'
    )
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: active internal employee required'
      USING errcode = '42501';
  END IF;

  INSERT INTO public.device_tokens (
    employee_id,
    token,
    platform,
    apns_environment,
    apns_topic
  )
  VALUES (
    v_employee_id,
    btrim(p_token),
    'ios',
    p_apns_environment,
    p_apns_topic
  )
  ON CONFLICT (token)
  DO UPDATE SET
    platform = 'ios',
    apns_environment = EXCLUDED.apns_environment,
    -- A device token is minted per app install, so its bundle id never
    -- changes. An older deployed client that omits the parameter re-upserts
    -- with NULL and must not erase a topic a newer build already recorded.
    apns_topic = COALESCE(EXCLUDED.apns_topic, device_tokens.apns_topic),
    updated_at = now()
  WHERE device_tokens.employee_id = EXCLUDED.employee_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION
      'NOT_AUTHORIZED: device token belongs to another employee'
      USING errcode = '42501';
  END IF;

  -- Bound one employee/environment to the five newest installations. The
  -- delivery worker uses the same cap, so one account cannot hold a Worker open
  -- across an unbounded sequence of APNs calls.
  DELETE FROM public.device_tokens stale_token
  WHERE stale_token.id IN (
    SELECT ranked.id
    FROM (
      SELECT
        token_row.id,
        row_number() OVER (
          ORDER BY token_row.updated_at DESC, token_row.id DESC
        ) AS position
      FROM public.device_tokens token_row
      WHERE token_row.employee_id = v_employee_id
        AND token_row.platform = 'ios'
        AND token_row.apns_environment = p_apns_environment
    ) ranked
    WHERE ranked.position > 5
  );

  RETURN jsonb_build_object(
    'id', v_row.id,
    'platform', v_row.platform,
    'apns_environment', v_row.apns_environment,
    'apns_topic', v_row.apns_topic,
    'updated_at', v_row.updated_at
  );
END;
$_$;


ALTER FUNCTION "public"."upsert_my_native_device_token"("p_token" "text", "p_apns_environment" "text", "p_apns_topic" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_oop_quote"("p_id" "uuid", "p_job_id" "uuid", "p_job_type" "text", "p_insured_name" "text", "p_address" "text", "p_tech_hours" numeric, "p_bill_rate" numeric, "p_air_mover_count" integer, "p_air_mover_days" integer, "p_lgr_count" integer, "p_lgr_days" integer, "p_xlgr_count" integer, "p_xlgr_days" integer, "p_air_scrubber_count" integer, "p_air_scrubber_days" integer, "p_neg_air_count" integer, "p_neg_air_days" integer, "p_materials_actual_cost" numeric, "p_antimicrobial_sqft" numeric, "p_disposal_trips" integer, "p_containment_linear_ft" numeric, "p_prv_invoice_cost" numeric, "p_quote_total" numeric, "p_net_margin_pct" numeric, "p_notes" "text", "p_created_by" "uuid") RETURNS "public"."oop_quotes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid; v_row public.oop_quotes; v_labor numeric; v_equipment numeric;
  v_quote_raw numeric; v_quote numeric; v_direct numeric; v_internal_total numeric; v_margin numeric; v_shadow jsonb;
BEGIN
  v_actor:=public.oop_pricing_active_employee(false);
  PERFORM public.oop_pricing_assert_job_exists(p_job_id);
  IF p_job_type IS NULL OR p_job_type NOT IN ('water','mold') THEN RAISE EXCEPTION 'invalid_job_type'; END IF;
  v_labor:=COALESCE(p_tech_hours,0)*COALESCE(p_bill_rate,92);
  v_equipment:=COALESCE(p_air_mover_count,0)*COALESCE(p_air_mover_days,0)*25
    +COALESCE(p_lgr_count,0)*COALESCE(p_lgr_days,0)*80
    +COALESCE(p_xlgr_count,0)*COALESCE(p_xlgr_days,0)*125
    +COALESCE(p_air_scrubber_count,0)*COALESCE(p_air_scrubber_days,0)*75
    +CASE WHEN p_job_type='mold' THEN COALESCE(p_neg_air_count,0)*COALESCE(p_neg_air_days,0)*110 ELSE 0 END;
  v_quote_raw:=v_labor+v_equipment+COALESCE(p_materials_actual_cost,0)*1.25
    +COALESCE(p_antimicrobial_sqft,0)*0.35+COALESCE(p_disposal_trips,0)*125
    +CASE WHEN p_job_type='mold' THEN COALESCE(p_containment_linear_ft,0)*2+v_labor*0.05 ELSE 0 END;
  v_direct:=COALESCE(p_tech_hours,0)*51+COALESCE(p_materials_actual_cost,0)
    +COALESCE(p_antimicrobial_sqft,0)*0.15+COALESCE(p_disposal_trips,0)*50
    +CASE WHEN p_job_type='mold' THEN COALESCE(p_containment_linear_ft,0)*1.2+v_labor*0.02+COALESCE(p_prv_invoice_cost,0) ELSE 0 END;
  v_quote:=round(v_quote_raw,2);
  v_internal_total:=round(v_direct+v_quote_raw*0.33,2);
  v_margin:=CASE WHEN v_quote_raw>0 THEN round((v_quote_raw-v_direct-v_quote_raw*0.33)*100/v_quote_raw,2) END;
  -- Full-precision parameters remain authoritative for the frozen legacy math;
  -- only the pre-existing compatibility columns are rounded to their typmods.
  v_shadow:=jsonb_build_object(
    'techHours',round(COALESCE(p_tech_hours,0),2),'billRate',round(COALESCE(p_bill_rate,92),2),
    'airMoverCount',COALESCE(p_air_mover_count,0),'airMoverDays',COALESCE(p_air_mover_days,0),
    'lgrCount',COALESCE(p_lgr_count,0),'lgrDays',COALESCE(p_lgr_days,0),
    'xlgrCount',COALESCE(p_xlgr_count,0),'xlgrDays',COALESCE(p_xlgr_days,0),
    'airScrubberCount',COALESCE(p_air_scrubber_count,0),'airScrubberDays',COALESCE(p_air_scrubber_days,0),
    'negAirCount',COALESCE(p_neg_air_count,0),'negAirDays',COALESCE(p_neg_air_days,0),
    'materialsActualCost',round(COALESCE(p_materials_actual_cost,0),2),'antimicrobialSqft',round(COALESCE(p_antimicrobial_sqft,0),2),
    'disposalTrips',COALESCE(p_disposal_trips,0),'containmentLinearFt',round(COALESCE(p_containment_linear_ft,0),2),
    'prvInvoiceCost',round(COALESCE(p_prv_invoice_cost,0),2));
  PERFORM public.oop_pricing_assert_storage_bounds(v_shadow,v_quote,v_margin,v_internal_total,NULL,0);
  -- Mark only this transaction-local DML as already canonical so the generic
  -- trigger does not recalculate money from the rounded shadow columns.
  PERFORM set_config('oop_pricing.legacy_canonical_write','on',true);
  IF p_id IS NULL THEN
    INSERT INTO public.oop_quotes(quote_number,job_id,job_type,insured_name,address,tech_hours,bill_rate,
      air_mover_count,air_mover_days,lgr_count,lgr_days,xlgr_count,xlgr_days,air_scrubber_count,air_scrubber_days,
      neg_air_count,neg_air_days,materials_actual_cost,antimicrobial_sqft,disposal_trips,containment_linear_ft,
      prv_invoice_cost,quote_total,net_margin_pct,notes,created_by)
    VALUES(public.generate_oop_quote_number(),p_job_id,p_job_type,p_insured_name,p_address,
      (v_shadow->>'techHours')::numeric,(v_shadow->>'billRate')::numeric,COALESCE(p_air_mover_count,0),COALESCE(p_air_mover_days,0),
      COALESCE(p_lgr_count,0),COALESCE(p_lgr_days,0),COALESCE(p_xlgr_count,0),COALESCE(p_xlgr_days,0),
      COALESCE(p_air_scrubber_count,0),COALESCE(p_air_scrubber_days,0),COALESCE(p_neg_air_count,0),COALESCE(p_neg_air_days,0),
      (v_shadow->>'materialsActualCost')::numeric,(v_shadow->>'antimicrobialSqft')::numeric,COALESCE(p_disposal_trips,0),
      (v_shadow->>'containmentLinearFt')::numeric,(v_shadow->>'prvInvoiceCost')::numeric,v_quote,v_margin,p_notes,v_actor)
    RETURNING * INTO v_row;
  ELSE
    UPDATE public.oop_quotes SET job_id=p_job_id,job_type=p_job_type,insured_name=p_insured_name,address=p_address,
      tech_hours=(v_shadow->>'techHours')::numeric,bill_rate=(v_shadow->>'billRate')::numeric,air_mover_count=COALESCE(p_air_mover_count,0),
      air_mover_days=COALESCE(p_air_mover_days,0),lgr_count=COALESCE(p_lgr_count,0),lgr_days=COALESCE(p_lgr_days,0),
      xlgr_count=COALESCE(p_xlgr_count,0),xlgr_days=COALESCE(p_xlgr_days,0),air_scrubber_count=COALESCE(p_air_scrubber_count,0),
      air_scrubber_days=COALESCE(p_air_scrubber_days,0),neg_air_count=COALESCE(p_neg_air_count,0),neg_air_days=COALESCE(p_neg_air_days,0),
      materials_actual_cost=(v_shadow->>'materialsActualCost')::numeric,antimicrobial_sqft=(v_shadow->>'antimicrobialSqft')::numeric,
      disposal_trips=COALESCE(p_disposal_trips,0),containment_linear_ft=(v_shadow->>'containmentLinearFt')::numeric,
      prv_invoice_cost=(v_shadow->>'prvInvoiceCost')::numeric,quote_total=v_quote,net_margin_pct=v_margin,notes=p_notes,updated_at=now()
    WHERE id=p_id RETURNING * INTO v_row;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'oop_quote_not_found'; END IF;
  END IF;
  PERFORM set_config('oop_pricing.legacy_canonical_write','off',true);
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_oop_quote"("p_id" "uuid", "p_job_id" "uuid", "p_job_type" "text", "p_insured_name" "text", "p_address" "text", "p_tech_hours" numeric, "p_bill_rate" numeric, "p_air_mover_count" integer, "p_air_mover_days" integer, "p_lgr_count" integer, "p_lgr_days" integer, "p_xlgr_count" integer, "p_xlgr_days" integer, "p_air_scrubber_count" integer, "p_air_scrubber_days" integer, "p_neg_air_count" integer, "p_neg_air_days" integer, "p_materials_actual_cost" numeric, "p_antimicrobial_sqft" numeric, "p_disposal_trips" integer, "p_containment_linear_ft" numeric, "p_prv_invoice_cost" numeric, "p_quote_total" numeric, "p_net_margin_pct" numeric, "p_notes" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_oop_quote_v2"("p_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_job_type" "text" DEFAULT NULL::"text", "p_insured_name" "text" DEFAULT NULL::"text", "p_address" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_pricing_revision_id" "uuid" DEFAULT NULL::"uuid", "p_inputs" "jsonb" DEFAULT '{}'::"jsonb", "p_expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."oop_quotes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid; v_revision public.oop_pricing_revisions; v_existing public.oop_quotes; v_existing_snapshot public.oop_quote_pricing_snapshots; v_item jsonb; v_input jsonb; v_key text;
  v_raw_qty numeric; v_qty numeric; v_days numeric; v_rate numeric; v_base numeric; v_customer_raw numeric; v_customer numeric; v_internal_raw numeric; v_internal numeric;
  v_subtotal numeric:=0; v_internal_total numeric:=0; v_minimum numeric; v_adjustment numeric:=0;
  v_lines jsonb:='[]'::jsonb; v_deferred jsonb:='[]'::jsonb; v_deferred_item jsonb;
  v_row public.oop_quotes; v_request_hash text; v_saved_actor uuid; v_saved_hash text; v_margin numeric; v_shadow jsonb;
BEGIN
  v_actor:=public.oop_pricing_active_employee(false);
  PERFORM public.oop_pricing_assert_job_exists(p_job_id);
  IF p_request_id IS NULL THEN RAISE EXCEPTION 'request_id_required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('oop_quote_save_request:' || p_request_id::text));
  IF p_job_type IS NULL OR p_job_type NOT IN ('water','mold') THEN RAISE EXCEPTION 'invalid_job_type'; END IF;
  IF p_inputs IS NULL OR jsonb_typeof(p_inputs)<>'object' THEN RAISE EXCEPTION 'invalid_pricing_inputs'; END IF;
  v_request_hash:=md5(jsonb_build_object('id',p_id,'jobId',p_job_id,'jobType',p_job_type,'insuredName',p_insured_name,'address',p_address,'notes',p_notes,'pricingRevisionId',p_pricing_revision_id,'inputs',p_inputs,'expectedUpdatedAt',p_expected_updated_at)::text);
  SELECT actor_employee_id,request_hash INTO v_saved_actor,v_saved_hash FROM public.oop_quote_save_requests WHERE request_id=p_request_id;
  IF FOUND THEN
    IF v_saved_actor IS DISTINCT FROM v_actor OR v_saved_hash<>v_request_hash THEN RAISE EXCEPTION 'request_id_reused_with_different_payload'; END IF;
    SELECT * INTO v_row FROM jsonb_populate_record(NULL::public.oop_quotes, (SELECT response FROM public.oop_quote_save_requests WHERE request_id=p_request_id));
    RETURN v_row;
  END IF;
  SELECT q.* INTO v_existing FROM public.oop_quotes q WHERE q.id=p_id FOR UPDATE;
  IF p_id IS NOT NULL AND v_existing.id IS NULL THEN RAISE EXCEPTION 'oop_quote_not_found'; END IF;
  IF v_existing.id IS NOT NULL AND (p_expected_updated_at IS NULL OR v_existing.updated_at<>p_expected_updated_at) THEN RAISE EXCEPTION 'quote_conflict'; END IF;
  IF v_existing.id IS NOT NULL THEN
    SELECT s.* INTO v_existing_snapshot FROM public.oop_quote_pricing_snapshots s WHERE s.quote_id=v_existing.id;
  END IF;
  IF v_existing_snapshot.quote_id IS NOT NULL AND p_pricing_revision_id IS NOT NULL AND v_existing_snapshot.pricing_revision_id<>p_pricing_revision_id THEN RAISE EXCEPTION 'pricing_revision_immutable'; END IF;
  IF p_pricing_revision_id IS NOT NULL THEN
    SELECT r.* INTO v_revision FROM public.oop_pricing_revisions r WHERE r.id=p_pricing_revision_id AND r.status IN ('published','superseded') FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'pricing_revision_not_found_or_not_published'; END IF;
  ELSIF v_existing_snapshot.quote_id IS NOT NULL THEN
    SELECT r.* INTO v_revision FROM public.oop_pricing_revisions r WHERE r.id=v_existing_snapshot.pricing_revision_id AND r.status IN ('published','superseded') FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'pricing_pinned_revision_missing'; END IF;
  ELSIF p_id IS NOT NULL THEN
    SELECT r.* INTO v_revision FROM public.oop_pricing_revisions r WHERE r.revision_number=1 AND r.status IN ('published','superseded') FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'pricing_legacy_revision_missing'; END IF;
  ELSE
    SELECT r.* INTO v_revision FROM public.oop_pricing_revisions r WHERE r.status='published' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'pricing_published_revision_missing'; END IF;
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(p_inputs) LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_revision.config->'items') i WHERE i->>'key'=v_key) THEN RAISE EXCEPTION 'unknown_pricing_input'; END IF;
  END LOOP;
  -- One deterministic pass preserves calcPricingQuote's prior-subtotal and
  -- named-item semantics. Inputs are validated before inactive/job-type skips.
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_revision.config->'items') ORDER BY (value->>'sortOrder')::integer,value->>'key' LOOP
    v_key:=v_item->>'key'; v_input:=COALESCE(p_inputs->v_key,'{}'::jsonb);
    IF jsonb_typeof(v_input)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(v_input) x WHERE x.key NOT IN ('quantity','days','rateOverride') OR jsonb_typeof(x.value)<>'number') THEN RAISE EXCEPTION 'invalid_pricing_input'; END IF;
    v_raw_qty:=COALESCE((v_input->>'quantity')::numeric,0); v_days:=COALESCE((v_input->>'days')::numeric,0);
    IF v_raw_qty<0 OR v_raw_qty>1000000 OR v_days<0 OR v_days>1000000 OR (v_input?'rateOverride' AND ((v_input->>'rateOverride')::numeric<0 OR (v_input->>'rateOverride')::numeric>1000000)) THEN RAISE EXCEPTION 'invalid_pricing_input_bounds'; END IF;
    IF v_raw_qty<>round(v_raw_qty,4) OR v_days<>round(v_days,4) OR (v_input?'rateOverride' AND (v_input->>'rateOverride')::numeric<>round((v_input->>'rateOverride')::numeric,4)) THEN RAISE EXCEPTION 'invalid_pricing_input_precision'; END IF;
    IF NOT(v_item->'jobTypes'?p_job_type) OR (v_item->>'active')::boolean IS FALSE THEN CONTINUE; END IF;
    v_qty:=CASE WHEN v_raw_qty>0 THEN greatest(v_raw_qty,(v_item->>'minimumQuantity')::numeric) ELSE 0 END;
    v_rate:=COALESCE((v_input->>'rateOverride')::numeric,(v_item->>'standardRate')::numeric);
    IF v_input?'rateOverride' AND (v_item->>'priceOverrideAllowed')::boolean IS FALSE THEN RAISE EXCEPTION 'invalid_pricing_rate'; END IF;
    v_base:=CASE
      WHEN v_item->>'percentageBase'='prior_subtotal' THEN v_subtotal
      WHEN v_item->>'percentageBase'='final_total' THEN NULL
      WHEN v_item->>'percentageBase' LIKE 'item:%' THEN COALESCE((SELECT (x->>'amount')::numeric FROM jsonb_array_elements(v_lines) x WHERE x->>'key'=substring(v_item->>'percentageBase' from 6) AND COALESCE((x->>'customerVisible')::boolean,false)),0)
      ELSE 0 END;
    v_customer_raw:=CASE v_item->>'formula'
      WHEN 'fixed' THEN CASE WHEN v_qty>0 THEN v_rate ELSE 0 END
      WHEN 'duration' THEN v_qty*v_days*v_rate
      WHEN 'percentage' THEN COALESCE(v_base,0)*v_rate
      ELSE v_qty*v_rate END;
    v_internal_raw:=CASE v_item->>'internalCostBasis'
      WHEN 'units' THEN CASE WHEN v_item->>'formula'='duration' THEN v_qty*v_days ELSE v_qty END*(v_item->>'internalRate')::numeric
      WHEN 'input' THEN v_raw_qty*(v_item->>'internalRate')::numeric
      WHEN 'percentage_base' THEN COALESCE(v_base,0)*(v_item->>'internalRate')::numeric
      ELSE 0 END;
    v_customer:=round(v_customer_raw,2);
    IF v_customer_raw>0 THEN v_customer:=round(greatest(v_customer,(v_item->>'minimumCharge')::numeric),2); END IF;
    IF v_item->>'internalCostBasis'='final_total' THEN
      v_internal:=0;
      v_deferred:=v_deferred||jsonb_build_array(jsonb_build_object('key',v_key,'internalRate',(v_item->>'internalRate')::numeric));
    ELSE
      v_internal:=round(v_internal_raw,2);
    END IF;
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('key',v_key,'sortOrder',(v_item->>'sortOrder')::integer,'quantity',v_qty,'days',v_days,'rate',v_rate,'amount',v_customer,'internalCost',v_internal,'customerVisible',(v_item->>'customerVisible')::boolean));
    IF (v_item->>'customerVisible')::boolean THEN v_subtotal:=round(v_subtotal+v_customer,2); END IF;
    v_internal_total:=round(v_internal_total+v_internal,2);
  END LOOP;
  v_minimum:=COALESCE((v_revision.config->'projectMinimums'->>p_job_type)::numeric,0);
  IF v_subtotal>0 AND v_subtotal<v_minimum THEN
    v_adjustment:=round(v_minimum-v_subtotal,2); v_subtotal:=round(v_subtotal+v_adjustment,2);
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('key','project_minimum_adjustment','amount',v_adjustment,'internalCost',0,'customerVisible',true));
  END IF;
  -- Only final_total internal costs are deferred, and they use the visible quote
  -- after the project minimum adjustment exactly like calcPricingQuote.
  FOR v_deferred_item IN SELECT value FROM jsonb_array_elements(v_deferred) LOOP
    v_internal:=round(v_subtotal*(v_deferred_item->>'internalRate')::numeric,2);
    v_internal_total:=round(v_internal_total+v_internal,2);
    SELECT jsonb_agg(CASE WHEN x.value->>'key'=v_deferred_item->>'key' THEN jsonb_set(x.value,'{internalCost}',to_jsonb(v_internal)) ELSE x.value END ORDER BY x.ordinality)
      INTO v_lines FROM jsonb_array_elements(v_lines) WITH ORDINALITY x(value,ordinality);
  END LOOP;
  v_margin:=CASE WHEN v_subtotal>0 THEN round((v_subtotal-v_internal_total)*100/v_subtotal,2) END;
  -- Exact four-decimal inputs remain in pricing_inputs and drive calculation.
  -- Only legacy compatibility columns are rounded to their storage shapes.
  v_shadow:=jsonb_build_object(
    'techHours',round(COALESCE((p_inputs->'labor'->>'quantity')::numeric,0),2),
    'billRate',round(COALESCE((SELECT (x->>'rate')::numeric FROM jsonb_array_elements(v_lines) x WHERE x->>'key'='labor'),92),2),
    'airMoverCount',round(COALESCE((p_inputs->'air_mover'->>'quantity')::numeric,0)),'airMoverDays',round(COALESCE((p_inputs->'air_mover'->>'days')::numeric,0)),
    'lgrCount',round(COALESCE((p_inputs->'lgr'->>'quantity')::numeric,0)),'lgrDays',round(COALESCE((p_inputs->'lgr'->>'days')::numeric,0)),
    'xlgrCount',round(COALESCE((p_inputs->'xlgr'->>'quantity')::numeric,0)),'xlgrDays',round(COALESCE((p_inputs->'xlgr'->>'days')::numeric,0)),
    'airScrubberCount',round(COALESCE((p_inputs->'air_scrubber'->>'quantity')::numeric,0)),'airScrubberDays',round(COALESCE((p_inputs->'air_scrubber'->>'days')::numeric,0)),
    'negAirCount',round(COALESCE((p_inputs->'negative_air'->>'quantity')::numeric,0)),'negAirDays',round(COALESCE((p_inputs->'negative_air'->>'days')::numeric,0)),
    'materialsActualCost',round(COALESCE((p_inputs->'materials'->>'quantity')::numeric,0),2),'antimicrobialSqft',round(COALESCE((p_inputs->'antimicrobial'->>'quantity')::numeric,0),2),
    'disposalTrips',round(COALESCE((p_inputs->'disposal'->>'quantity')::numeric,0)),'containmentLinearFt',round(COALESCE((p_inputs->'containment'->>'quantity')::numeric,0),2),
    'prvInvoiceCost',round(COALESCE((p_inputs->'prv'->>'quantity')::numeric,0),2)
  );
  PERFORM public.oop_pricing_assert_storage_bounds(v_shadow,v_subtotal,v_margin,v_internal_total,v_lines,v_adjustment);
  PERFORM set_config('oop_pricing.v2_write','on',true);
  IF p_id IS NULL THEN
    INSERT INTO public.oop_quotes(
      quote_number,job_id,job_type,insured_name,address,tech_hours,bill_rate,
      air_mover_count,air_mover_days,lgr_count,lgr_days,xlgr_count,xlgr_days,
      air_scrubber_count,air_scrubber_days,neg_air_count,neg_air_days,
      materials_actual_cost,antimicrobial_sqft,disposal_trips,
      containment_linear_ft,prv_invoice_cost,quote_total,net_margin_pct,notes,created_by
    ) VALUES(
      public.generate_oop_quote_number(),p_job_id,p_job_type,p_insured_name,p_address,
      (v_shadow->>'techHours')::numeric,(v_shadow->>'billRate')::numeric,
      (v_shadow->>'airMoverCount')::integer,(v_shadow->>'airMoverDays')::integer,
      (v_shadow->>'lgrCount')::integer,(v_shadow->>'lgrDays')::integer,
      (v_shadow->>'xlgrCount')::integer,(v_shadow->>'xlgrDays')::integer,
      (v_shadow->>'airScrubberCount')::integer,(v_shadow->>'airScrubberDays')::integer,
      (v_shadow->>'negAirCount')::integer,(v_shadow->>'negAirDays')::integer,
      (v_shadow->>'materialsActualCost')::numeric,(v_shadow->>'antimicrobialSqft')::numeric,
      (v_shadow->>'disposalTrips')::integer,(v_shadow->>'containmentLinearFt')::numeric,
      (v_shadow->>'prvInvoiceCost')::numeric,v_subtotal,v_margin,p_notes,v_actor
    ) RETURNING * INTO v_row;
  ELSE
    UPDATE public.oop_quotes SET
      job_id=p_job_id,job_type=p_job_type,insured_name=p_insured_name,address=p_address,
      tech_hours=(v_shadow->>'techHours')::numeric,bill_rate=(v_shadow->>'billRate')::numeric,
      air_mover_count=(v_shadow->>'airMoverCount')::integer,air_mover_days=(v_shadow->>'airMoverDays')::integer,
      lgr_count=(v_shadow->>'lgrCount')::integer,lgr_days=(v_shadow->>'lgrDays')::integer,
      xlgr_count=(v_shadow->>'xlgrCount')::integer,xlgr_days=(v_shadow->>'xlgrDays')::integer,
      air_scrubber_count=(v_shadow->>'airScrubberCount')::integer,air_scrubber_days=(v_shadow->>'airScrubberDays')::integer,
      neg_air_count=(v_shadow->>'negAirCount')::integer,neg_air_days=(v_shadow->>'negAirDays')::integer,
      materials_actual_cost=(v_shadow->>'materialsActualCost')::numeric,
      antimicrobial_sqft=(v_shadow->>'antimicrobialSqft')::numeric,
      disposal_trips=(v_shadow->>'disposalTrips')::integer,
      containment_linear_ft=(v_shadow->>'containmentLinearFt')::numeric,
      prv_invoice_cost=(v_shadow->>'prvInvoiceCost')::numeric,
      quote_total=v_subtotal,net_margin_pct=v_margin,notes=p_notes,updated_at=now()
    WHERE id=p_id RETURNING * INTO v_row;
  END IF;
  PERFORM set_config('oop_pricing.v2_write','off',true);
  INSERT INTO public.oop_quote_pricing_snapshots(
    quote_id,pricing_revision_id,pricing_inputs,pricing_config_snapshot,
    pricing_evaluated_lines,pricing_engine_version,pricing_minimum_adjustment
  ) VALUES(v_row.id,v_revision.id,p_inputs,v_revision.config,v_lines,1,v_adjustment)
  ON CONFLICT (quote_id) DO UPDATE SET
    pricing_revision_id=EXCLUDED.pricing_revision_id,
    pricing_inputs=EXCLUDED.pricing_inputs,
    pricing_config_snapshot=EXCLUDED.pricing_config_snapshot,
    pricing_evaluated_lines=EXCLUDED.pricing_evaluated_lines,
    pricing_engine_version=EXCLUDED.pricing_engine_version,
    pricing_minimum_adjustment=EXCLUDED.pricing_minimum_adjustment,
    cleared_at=NULL,
    updated_at=now();
  INSERT INTO public.oop_quote_save_requests(request_id,quote_id,actor_employee_id,request_hash,response)
    VALUES(p_request_id,v_row.id,v_actor,v_request_hash,to_jsonb(v_row));
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_oop_quote_v2"("p_id" "uuid", "p_job_id" "uuid", "p_job_type" "text", "p_insured_name" "text", "p_address" "text", "p_notes" "text", "p_pricing_revision_id" "uuid", "p_inputs" "jsonb", "p_expected_updated_at" timestamp with time zone, "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_permission"("p_role" "text", "p_nav_key" "text", "p_can_view" boolean, "p_can_edit" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  result nav_permissions;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.is_active_internal_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED: admin only' USING errcode = '42501';
  END IF;

  INSERT INTO nav_permissions (role, nav_key, can_view, can_edit)
  VALUES (p_role, p_nav_key, p_can_view, p_can_edit)
  ON CONFLICT (role, nav_key)
  DO UPDATE SET can_view = p_can_view, can_edit = p_can_edit
  RETURNING * INTO result;

  RETURN row_to_json(result)::jsonb;
END;
$$;


ALTER FUNCTION "public"."upsert_permission"("p_role" "text", "p_nav_key" "text", "p_can_view" boolean, "p_can_edit" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_pipeline_stage"("p_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_color" "text" DEFAULT '#6366f1'::"text", "p_sort_order" integer DEFAULT NULL::integer, "p_is_won" boolean DEFAULT false, "p_is_lost" boolean DEFAULT false, "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."pipeline_stages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_row    pipeline_stages;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'pipeline stage name is required';
  END IF;
  IF p_is_won AND p_is_lost THEN
    RAISE EXCEPTION 'a pipeline stage cannot be both is_won and is_lost';
  END IF;

  v_org_id := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));

  IF p_id IS NULL THEN
    INSERT INTO pipeline_stages (org_id, name, color, sort_order, is_won, is_lost)
    VALUES (
      v_org_id, btrim(p_name), COALESCE(p_color, '#6366f1'),
      COALESCE(p_sort_order, (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM pipeline_stages WHERE org_id = v_org_id)),
      p_is_won, p_is_lost
    )
    RETURNING * INTO v_row;
  ELSE
    UPDATE pipeline_stages
       SET name       = btrim(p_name),
           color      = COALESCE(p_color, color),
           sort_order = COALESCE(p_sort_order, sort_order),
           is_won     = p_is_won,
           is_lost    = p_is_lost,
           updated_at = now()
     WHERE id = p_id
     RETURNING * INTO v_row;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'unknown pipeline_stages id: %', p_id;
    END IF;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_pipeline_stage"("p_id" "uuid", "p_name" "text", "p_color" "text", "p_sort_order" integer, "p_is_won" boolean, "p_is_lost" boolean, "p_org_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."property_meld_melds" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "meld_number" "text" NOT NULL,
    "meld_internal_id" "text",
    "org_id" "text",
    "vendor_account_id" "text" NOT NULL,
    "business" "text" DEFAULT 'restoration'::"text" NOT NULL,
    "pm_brand" "text",
    "is_emergency" boolean DEFAULT false NOT NULL,
    "meld_type" "text",
    "status" "text",
    "due_date_text" "text",
    "appointment_window" "text",
    "address_street" "text",
    "address_unit" "text",
    "address_city_state_zip" "text",
    "address_full" "text",
    "description" "text",
    "description_clipped" boolean DEFAULT false NOT NULL,
    "last_message_from" "text",
    "last_message_text" "text",
    "thread_reply_address" "text",
    "portal_url" "text",
    "state" "text" DEFAULT 'open'::"text" NOT NULL,
    "imported_job_id" "uuid",
    "received_at" timestamp with time zone,
    "last_event" "text",
    "last_event_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "property_meld_melds_state_check" CHECK (("state" = ANY (ARRAY['open'::"text", 'canceled'::"text", 'imported'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."property_meld_melds" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_property_meld_meld"("p_meld_number" "text", "p_event" "text", "p_vendor_account_id" "text", "p_business" "text" DEFAULT 'restoration'::"text", "p_org_id" "text" DEFAULT NULL::"text", "p_meld_internal_id" "text" DEFAULT NULL::"text", "p_pm_brand" "text" DEFAULT NULL::"text", "p_is_emergency" boolean DEFAULT false, "p_meld_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_due_date_text" "text" DEFAULT NULL::"text", "p_appointment_window" "text" DEFAULT NULL::"text", "p_address_street" "text" DEFAULT NULL::"text", "p_address_unit" "text" DEFAULT NULL::"text", "p_address_city_state_zip" "text" DEFAULT NULL::"text", "p_address_full" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_description_clipped" boolean DEFAULT false, "p_message_from" "text" DEFAULT NULL::"text", "p_message_text" "text" DEFAULT NULL::"text", "p_thread_reply_address" "text" DEFAULT NULL::"text", "p_portal_url" "text" DEFAULT NULL::"text", "p_received_at" timestamp with time zone DEFAULT "now"()) RETURNS "public"."property_meld_melds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result property_meld_melds;
BEGIN
  INSERT INTO property_meld_melds (
    meld_number, meld_internal_id, org_id, vendor_account_id, business, pm_brand,
    is_emergency, meld_type, status, due_date_text, appointment_window,
    address_street, address_unit, address_city_state_zip, address_full,
    description, description_clipped,
    last_message_from, last_message_text, thread_reply_address, portal_url,
    state, received_at, last_event, last_event_at
  )
  VALUES (
    p_meld_number, p_meld_internal_id, p_org_id, p_vendor_account_id,
    COALESCE(p_business, 'restoration'), p_pm_brand,
    COALESCE(p_is_emergency, FALSE), p_meld_type, p_status, p_due_date_text, p_appointment_window,
    p_address_street, p_address_unit, p_address_city_state_zip, p_address_full,
    CASE WHEN p_event = 'message' THEN NULL ELSE p_description END,
    COALESCE(p_description_clipped, FALSE),
    CASE WHEN p_event = 'message' THEN p_message_from END,
    CASE WHEN p_event = 'message' THEN p_message_text END,
    p_thread_reply_address, p_portal_url,
    CASE WHEN p_event = 'canceled' THEN 'canceled' ELSE 'open' END,
    COALESCE(p_received_at, now()), p_event, COALESCE(p_received_at, now())
  )
  ON CONFLICT (meld_number) DO UPDATE SET
    meld_internal_id       = COALESCE(EXCLUDED.meld_internal_id, property_meld_melds.meld_internal_id),
    org_id                 = COALESCE(EXCLUDED.org_id, property_meld_melds.org_id),
    vendor_account_id      = COALESCE(EXCLUDED.vendor_account_id, property_meld_melds.vendor_account_id),
    pm_brand               = COALESCE(EXCLUDED.pm_brand, property_meld_melds.pm_brand),
    is_emergency           = property_meld_melds.is_emergency OR EXCLUDED.is_emergency,
    meld_type              = COALESCE(EXCLUDED.meld_type, property_meld_melds.meld_type),
    status                 = CASE WHEN p_event = 'canceled' THEN 'Canceled'
                                  ELSE COALESCE(EXCLUDED.status, property_meld_melds.status) END,
    due_date_text          = COALESCE(EXCLUDED.due_date_text, property_meld_melds.due_date_text),
    appointment_window     = COALESCE(EXCLUDED.appointment_window, property_meld_melds.appointment_window),
    address_street         = COALESCE(EXCLUDED.address_street, property_meld_melds.address_street),
    address_unit           = COALESCE(EXCLUDED.address_unit, property_meld_melds.address_unit),
    address_city_state_zip = COALESCE(EXCLUDED.address_city_state_zip, property_meld_melds.address_city_state_zip),
    address_full           = COALESCE(EXCLUDED.address_full, property_meld_melds.address_full),
    description            = CASE WHEN p_event = 'message' THEN property_meld_melds.description
                                  ELSE COALESCE(EXCLUDED.description, property_meld_melds.description) END,
    description_clipped    = CASE WHEN p_event = 'message' THEN property_meld_melds.description_clipped
                                  ELSE EXCLUDED.description_clipped END,
    last_message_from      = COALESCE(EXCLUDED.last_message_from, property_meld_melds.last_message_from),
    last_message_text      = COALESCE(EXCLUDED.last_message_text, property_meld_melds.last_message_text),
    thread_reply_address   = COALESCE(EXCLUDED.thread_reply_address, property_meld_melds.thread_reply_address),
    portal_url             = COALESCE(EXCLUDED.portal_url, property_meld_melds.portal_url),
    state                  = CASE
                               WHEN property_meld_melds.state = 'imported' THEN 'imported'
                               WHEN p_event = 'canceled' THEN 'canceled'
                               ELSE property_meld_melds.state
                             END,
    received_at            = LEAST(property_meld_melds.received_at, COALESCE(EXCLUDED.received_at, now())),
    last_event             = p_event,
    last_event_at          = COALESCE(EXCLUDED.received_at, now()),
    updated_at             = now()
  RETURNING * INTO result;

  RETURN result;
END;
$$;


