CREATE OR REPLACE FUNCTION "public"."upsert_segment"("p_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_filter" "jsonb" DEFAULT '{}'::"jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."crm_segments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_name   text := nullif(btrim(p_name), '');
  v_row    crm_segments;
BEGIN
  IF p_id IS NULL THEN
    IF v_name IS NULL THEN RAISE EXCEPTION 'a segment name is required'; END IF;
    INSERT INTO crm_segments (org_id, name, description, filter, created_by)
    VALUES (v_org_id, v_name, nullif(btrim(p_description), ''), COALESCE(p_filter, '{}'::jsonb), p_created_by)
    RETURNING * INTO v_row;
  ELSE
    UPDATE crm_segments SET
      name        = COALESCE(v_name, name),
      description  = nullif(btrim(p_description), ''),
      filter      = COALESCE(p_filter, filter),
      updated_at  = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'segment % not found', p_id; END IF;
  END IF;
  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_segment"("p_id" "uuid", "p_name" "text", "p_description" "text", "p_filter" "jsonb", "p_org_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."crm_sequences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "exit_on_reply" boolean DEFAULT true NOT NULL,
    "exit_on_conversion" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "crm_sequences_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'paused'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."crm_sequences" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_sequence"("p_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_steps" "jsonb" DEFAULT '[]'::"jsonb", "p_org_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."crm_sequences"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := COALESCE(p_org_id, (SELECT id FROM crm_orgs WHERE is_test = false ORDER BY created_at LIMIT 1));
  v_name   text := nullif(btrim(p_name), '');
  v_row    crm_sequences;
BEGIN
  IF p_id IS NULL THEN
    IF v_name IS NULL THEN RAISE EXCEPTION 'a sequence name is required'; END IF;
    INSERT INTO crm_sequences (org_id, name, description, status, created_by)
    VALUES (v_org_id, v_name, nullif(btrim(p_description), ''),
            COALESCE(nullif(btrim(p_status), ''), 'draft'), p_created_by)
    RETURNING * INTO v_row;
  ELSE
    UPDATE crm_sequences SET
      name        = COALESCE(v_name, name),
      description  = nullif(btrim(p_description), ''),
      status      = COALESCE(nullif(btrim(p_status), ''), status),
      updated_at  = now()
    WHERE id = p_id
    RETURNING * INTO v_row;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'sequence % not found', p_id; END IF;
  END IF;

  IF p_steps IS NOT NULL THEN
    DELETE FROM crm_sequence_steps WHERE sequence_id = v_row.id;
    INSERT INTO crm_sequence_steps (sequence_id, org_id, step_order, channel, delay_hours, subject, body, template_id)
    SELECT
      v_row.id, v_org_id,
      (row_number() OVER (ORDER BY COALESCE((e.elem->>'step_order')::int, (e.ord - 1)::int), e.ord) - 1)::int,
      e.elem->>'channel',
      GREATEST(COALESCE((e.elem->>'delay_hours')::int, 0), 0),
      nullif(e.elem->>'subject', ''),
      nullif(e.elem->>'body', ''),
      nullif(e.elem->>'template_id', '')::uuid
    FROM jsonb_array_elements(p_steps) WITH ORDINALITY AS e(elem, ord);
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_sequence"("p_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_steps" "jsonb", "p_org_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_time_entry"("p_id" "uuid" DEFAULT NULL::"uuid", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_employee_id" "uuid" DEFAULT NULL::"uuid", "p_work_date" "date" DEFAULT NULL::"date", "p_hours" numeric DEFAULT NULL::numeric, "p_work_type" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_id IS NOT NULL THEN
    UPDATE job_time_entries SET
      job_id      = COALESCE(p_job_id, job_id),
      employee_id = COALESCE(p_employee_id, employee_id),
      work_date   = COALESCE(p_work_date, work_date),
      hours       = COALESCE(p_hours, hours),
      work_type   = COALESCE(p_work_type, work_type),
      description = COALESCE(p_description, description),
      notes       = COALESCE(p_notes, notes)
    WHERE id = p_id
    RETURNING id INTO v_id;
  ELSE
    INSERT INTO job_time_entries (job_id, employee_id, work_date, hours, work_type, description, notes)
    VALUES (p_job_id, p_employee_id, p_work_date, p_hours, p_work_type, p_description, p_notes)
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."upsert_time_entry"("p_id" "uuid", "p_job_id" "uuid", "p_employee_id" "uuid", "p_work_date" "date", "p_hours" numeric, "p_work_type" "text", "p_description" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wake_callrail_event_recovery_worker"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret text;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT value
  INTO v_worker_url
  FROM public.integration_config
  WHERE key = 'callrail_event_recovery_worker_url';

  SELECT value
  INTO v_secret
  FROM public.integration_config
  WHERE key = 'cron_worker_secret';

  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/process-callrail-events',
    'https://utahpros.app/api/process-callrail-events'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.message_provider_events e
    WHERE e.provider = 'callrail'
      AND e.message_type IN ('sms', 'mms')
      AND (
        e.processing_state = 'received'
        OR (
          e.processing_state = 'retryable'
          AND e.next_attempt_at <= v_now
        )
        OR (
          e.processing_state = 'claimed'
          AND e.claimed_at < v_now - interval '5 minutes'
        )
      )
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );

  RETURN;
END;
$$;


ALTER FUNCTION "public"."wake_callrail_event_recovery_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wake_message_notification_outbox_worker"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret text;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT value
  INTO v_worker_url
  FROM public.integration_config
  WHERE key = 'message_notification_outbox_worker_url';

  SELECT value
  INTO v_secret
  FROM public.integration_config
  WHERE key = 'cron_worker_secret';

  IF v_worker_url IS NULL OR v_worker_url NOT IN (
    'https://dev.utahpros.app/api/process-message-notification-outbox',
    'https://utahpros.app/api/process-message-notification-outbox'
  ) OR NULLIF(btrim(v_secret), '') IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.message_notification_outbox o
    WHERE (
      o.delivery_state IN ('pending', 'retryable')
      AND o.next_attempt_at <= v_now
    ) OR (
      o.delivery_state = 'processing'
      AND o.claimed_at < v_now - interval '5 minutes'
    )
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-webhook-secret', v_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  );

  RETURN;
END;
$$;


ALTER FUNCTION "public"."wake_message_notification_outbox_worker"() OWNER TO "postgres";


