CREATE TABLE IF NOT EXISTS "public"."contractor_compliance_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "document_type" "text" NOT NULL,
    "version_number" integer NOT NULL,
    "review_state" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "coverage_start_date" "date",
    "coverage_end_date" "date",
    "tax_year" integer,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "received_source" "text" DEFAULT 'internal_upload'::"text" NOT NULL,
    "source_external_id" "text",
    "storage_bucket" "text" DEFAULT 'contractor-compliance-private'::"text" NOT NULL,
    "storage_object_path" "text" NOT NULL,
    "original_filename" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "sha256_hex" character(64) NOT NULL,
    "extracted_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "verified_by" "uuid",
    "verified_at" timestamp with time zone,
    "rejection_reason" "text",
    "superseded_at" timestamp with time zone,
    "superseded_by_document_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "contractor_compliance_documents_date_check" CHECK (((("document_type" = 'w9'::"text") AND ("tax_year" >= 2000) AND ("tax_year" <= 2200) AND ("coverage_start_date" IS NULL) AND ("coverage_end_date" IS NULL)) OR (("document_type" <> 'w9'::"text") AND ("tax_year" IS NULL) AND
CASE
    WHEN ("review_state" = 'accepted'::"text") THEN (("coverage_start_date" IS NOT NULL) AND ("coverage_end_date" IS NOT NULL) AND ("coverage_end_date" >= "coverage_start_date"))
    ELSE ((("coverage_start_date" IS NULL) AND ("coverage_end_date" IS NULL)) OR (("coverage_start_date" IS NOT NULL) AND ("coverage_end_date" IS NOT NULL) AND ("coverage_end_date" >= "coverage_start_date")))
END))),
    CONSTRAINT "contractor_compliance_documents_file_check" CHECK ((("mime_type" = ANY (ARRAY['application/pdf'::"text", 'image/jpeg'::"text", 'image/png'::"text"])) AND ("byte_size" > 0) AND ("byte_size" <= 6291456))),
    CONSTRAINT "contractor_compliance_documents_hash_check" CHECK (("sha256_hex" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contractor_compliance_documents_review_check" CHECK (((("review_state" = 'pending_review'::"text") AND ("verified_at" IS NULL) AND ("verified_by" IS NULL) AND ("rejection_reason" IS NULL)) OR (("review_state" = 'accepted'::"text") AND ("verified_at" IS NOT NULL) AND ("verified_by" IS NOT NULL) AND ("rejection_reason" IS NULL)) OR (("review_state" = 'rejected'::"text") AND ("verified_at" IS NOT NULL) AND ("verified_by" IS NOT NULL) AND ("rejection_reason" IS NOT NULL)) OR (("review_state" = 'superseded'::"text") AND ("verified_at" IS NOT NULL) AND ("verified_by" IS NOT NULL) AND ("rejection_reason" IS NULL)))),
    CONSTRAINT "contractor_compliance_documents_state_check" CHECK (("review_state" = ANY (ARRAY['pending_review'::"text", 'accepted'::"text", 'rejected'::"text", 'superseded'::"text"]))),
    CONSTRAINT "contractor_compliance_documents_storage_check" CHECK ((("storage_bucket" = 'contractor-compliance-private'::"text") AND ("storage_object_path" !~ '(^/|\\.\\.)'::"text"))),
    CONSTRAINT "contractor_compliance_documents_type_check" CHECK (("document_type" = ANY (ARRAY['w9'::"text", 'workers_comp'::"text", 'workers_comp_waiver'::"text", 'general_liability'::"text"]))),
    CONSTRAINT "contractor_compliance_documents_version_check" CHECK (("version_number" > 0))
);

