);


ALTER TABLE "public"."messages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."messages"."num_segments" IS 'Twilio SMS segment count for this message (from the status callback / message resource). Nullable; null on legacy + inbound rows.';



COMMENT ON COLUMN "public"."messages"."price" IS 'Twilio-reported price for this message (negative string in Twilio; stored as numeric). Nullable; null until Twilio reports it.';



COMMENT ON COLUMN "public"."messages"."provider" IS 'Outbound/inbound transport that owns this message. Provider facts do not control consent or conversation identity.';



COMMENT ON COLUMN "public"."messages"."provider_message_id" IS 'Provider message/resource identity when the provider exposes one. Twilio dual-writes twilio_sid during transition.';



COMMENT ON COLUMN "public"."messages"."provider_conversation_id" IS 'Provider conversation identity; never the UPR conversation primary key.';



COMMENT ON COLUMN "public"."messages"."client_request_id" IS 'Stable browser-generated UUID for one direct staff send action, reused on retry.';



COMMENT ON COLUMN "public"."messages"."sender_address" IS 'Actual provider sender address used for this message.';



COMMENT ON COLUMN "public"."messages"."recipient_address" IS 'Actual provider recipient address used for this message.';



